window.CFA_DEEP_ETH=[{"module_id":"CFA26-10-01","module_title":"Ethics and Trust in the Investment Profession","subject":"Ethical and Professional Standards","level":"CFA Level I 2026","status":"Source-mapped detailed academic draft; not independently certified","language":"Vietnamese explanations with English terminology and English exam questions","source_policy":"Original paraphrases, conceptual cases and questions; CFAI 2026 Volume 10 primary, Kaplan Book 4 and SAPP Ethics secondary. Legacy v59 ethics lessons reviewed and preserved. No publisher question reproductions.","disclaimer_vi":"Bản học chi tiết dạng draft, không thay thế nguyên văn Code and Standards. Phân biệt yêu cầu bắt buộc với hướng dẫn và best practices; nội dung LM2 là tổng quan 23 sub-standards, không thay cho LM3 Guidance. Chưa thẩm định học thuật độc lập từng câu.","los":[{"id":"CFA26-10-01-LOS01","letter":"a","title_en":"Ethics and Ethical Conduct","outcome_en":"explain ethics","overview_vi":"Bài 1.a: Ethics and Ethical Conduct. Học nguyên tắc, phân biệt nghĩa vụ và bẫy, rồi vận dụng vào tình huống tiếng Anh nguyên gốc. Các khung trong phần Công thức là khung định tính, không phải công thức toán. LM2 giới thiệu các sub-standard; hướng dẫn áp dụng chi tiết thuộc LM3. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 17 (LOS); pp. 19–21 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 89","pages":"Physical PDF pp. 154"},{"id":"SAPP CFA Level I 2026 — Ethics slides","pages":"Physical PDF pp. 5"}],"sections":[{"heading":"Ethics and moral principles","body":"Ethics (đạo đức) nghiên cứu việc lựa chọn hành vi tốt, dựa trên nguyên tắc đạo đức và quy tắc ứng xử định hướng hành vi. Ethical conduct phù hợp các nguyên tắc và kỳ vọng đạo đức của cộng đồng. Đây không chỉ là sở thích cá nhân hay tuân thủ pháp luật; cần cân nhắc tác động tới những người khác.","trap":"Đừng đồng nhất ethics với legal compliance hoặc với việc tối đa hóa lợi ích bản thân."},{"heading":"Stakeholders and indirect effects","body":"Stakeholders là cá nhân hoặc nhóm chịu ảnh hưởng trực tiếp hoặc gián tiếp từ quyết định: khách hàng hiện tại và tiềm năng, nhân viên, đồng nghiệp, công ty, nhà quản lý, thị trường và cộng đồng. Phân tích đầy đủ cần nhìn cả người không tham gia ký hợp đồng nhưng chịu hậu quả.","trap":"Không giới hạn stakeholders ở cổ đông hoặc người trực tiếp nhận tiền."},{"heading":"Short-term gain versus long-term harm","body":"Một hành vi có thể làm tăng doanh thu hoặc thu nhập ngắn hạn nhưng giảm niềm tin, làm tổn hại khách hàng, uy tín doanh nghiệp và tính toàn vẹn của thị trường trong dài hạn. Hậu quả có thể lan sang người không có quan hệ trực tiếp với người ra quyết định.","trap":"Lợi nhuận và kết quả đầu tư tốt không tự chứng minh hành vi có đạo đức."},{"heading":"Ethical conduct versus personal values","body":"Giá trị cá nhân hình thành từ gia đình, văn hóa, xã hội và kinh nghiệm; các chuẩn mực nghề nghiệp đặt ra kỳ vọng chung để giảm tùy tiện. Khi niềm tin cá nhân không trùng nghĩa vụ nghề nghiệp, cần xác định nguyên tắc và nghĩa vụ liên quan thay vì áp đặt sở thích riêng lên khách hàng.","trap":"Một người có ý tốt vẫn có thể quyết định phi đạo đức nếu không xem xét các nghĩa vụ khách quan."},{"heading":"Fiduciary and suitability standards","body":"Trong ví dụ của Curriculum, fiduciary duty yêu cầu mức chăm sóc cao khi hành động cho lợi ích người khác, trong khi suitability xét mức phù hợp của khoản đầu tư với mục tiêu, rủi ro và hoàn cảnh khách hàng. Yêu cầu pháp lý có thể khác giữa nước và giữa loại dịch vụ; một sản phẩm phù hợp chưa chắc là lựa chọn phục vụ tốt nhất lợi ích khách hàng.","trap":"Không xem hai chuẩn là hoàn toàn đồng nhất; không giả định mọi nước có cùng luật."},{"heading":"Stakeholder impact and self-interest","body":"Suy luận đạo đức cân nhắc lợi ích bản thân cùng ảnh hưởng tới người khác. Lợi ích của một bên có thể gây chi phí cho bên khác; cần xét cả tác động trực tiếp, gián tiếp và dài hạn. Niềm tin cá nhân không tự chứng minh hành vi đúng đắn.","body_en":"Ethical reasoning considers effects on others as well as one’s own interests. A benefit to one stakeholder can impose costs on another; consider both direct and indirect effects over time. Personal conviction alone does not establish that conduct is ethical.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 19–21 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 154; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 5","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Stakeholder impact map","expr":"Action → direct effects → indirect effects → affected stakeholders → short/long-term consequences","meaning":"Xem tác động của một quyết định lên khách hàng, bản thân, công ty, profession, thị trường và xã hội; lợi ích một nhóm có thể đi kèm thiệt hại nhóm khác.","conditions":"Khung phân tích định tính, không cộng lợi ích thành một điểm số để vượt qua nghĩa vụ bắt buộc."},{"name":"Ethics vs outcome","expr":"Intent + conduct + duties + foreseeable consequences","meaning":"Đánh giá cả quá trình và hậu quả; kết quả lợi nhuận dương không tự xác nhận hành vi đúng.","conditions":"Không suy ra một khoản lỗ tự động là vi phạm."}],"examples":[{"question_en":"A manager discovers a legal but obscure charge that materially reduces investors' net returns. No contractual clause requires a separate explanation. What is the best initial ethical response?","steps_vi":["Xác định stakeholders: nhà đầu tư bị giảm net return, firm thu phí, người quản lý có duty và có thể có incentive. Tính hợp pháp không kết luận ethics.","Xem xét tác động, nghĩa vụ disclosure và cách giải thích phí rõ ràng cho client; nếu chưa đủ thông tin, hỏi compliance và kiểm tra điều khoản áp dụng."],"answer":"Evaluate the charge from the client's perspective and provide appropriate transparent disclosure.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A research department receives a revenue bonus after issuing a promotional report that knowingly omits a significant risk. Several downstream investors buy the security. Which ethical issue is most important?","steps_vi":["Bản report có tác động trực tiếp tới doanh thu firm và gián tiếp tới nhà đầu tư dựa vào report. Bonus không chứng minh chất lượng hoặc tính đạo đức.","Đánh giá hành vi che giấu rủi ro và hậu quả đối với mọi stakeholder, không chỉ người ký hợp đồng."],"answer":"The harm to investors and market trust must be considered despite the firm's revenue gain.","check":"Original conceptual vignette; conclusion limited to stated facts."}],"questions":[{"stem_en":"An adviser asks whether a permitted fee arrangement is fair to clients. The adviser is primarily considering:","options":["the enforceability of a contract only.","the profitability of the employer only.","ethical principles beyond legal compliance."],"correct":2,"why_vi":"Ethics (đạo đức) nghiên cứu việc lựa chọn hành vi tốt, dựa trên nguyên tắc đạo đức và quy tắc ứng xử định hướng hành vi. Ethical conduct phù hợp các nguyên tắc và kỳ vọng đạo đức của cộng đồng. Đây không chỉ là sở thích cá nhân hay tuân thủ pháp luật; cần cân nhắc tác động tới những người khác.","trap_vi":"Đừng đồng nhất ethics với legal compliance hoặc với việc tối đa hóa lợi ích bản thân."},{"stem_en":"A misleading report is widely redistributed by unrelated brokers. Which group should the analyst include in an ethical assessment?","options":["Only the analyst's paying subscribers.","Investors who may rely on the redistributed report.","Only employees who approved publication."],"correct":1,"why_vi":"Stakeholders là cá nhân hoặc nhóm chịu ảnh hưởng trực tiếp hoặc gián tiếp từ quyết định: khách hàng hiện tại và tiềm năng, nhân viên, đồng nghiệp, công ty, nhà quản lý, thị trường và cộng đồng. Phân tích đầy đủ cần nhìn cả người không tham gia ký hợp đồng nhưng chịu hậu quả.","trap_vi":"Không giới hạn stakeholders ở cổ đông hoặc người trực tiếp nhận tiền."},{"stem_en":"A firm profits from a misleading sales pitch and no complaints have yet been received. Which conclusion is most defensible?","options":["The sales pitch is ethical because clients have not complained.","The absence of complaints does not establish ethical conduct.","The pitch is ethical if revenue is reinvested in client services."],"correct":1,"why_vi":"Một hành vi có thể làm tăng doanh thu hoặc thu nhập ngắn hạn nhưng giảm niềm tin, làm tổn hại khách hàng, uy tín doanh nghiệp và tính toàn vẹn của thị trường trong dài hạn. Hậu quả có thể lan sang người không có quan hệ trực tiếp với người ra quyết định.","trap_vi":"Lợi nhuận và kết quả đầu tư tốt không tự chứng minh hành vi có đạo đức."},{"stem_en":"An analyst dislikes a legal industry for personal reasons and hides relevant evidence from clients. The most appropriate ethical concern is:","options":["the analyst's right to hold personal beliefs.","whether all clients share the analyst's personal preferences.","failure to evaluate professional duties independently of personal preferences."],"correct":2,"why_vi":"Giá trị cá nhân hình thành từ gia đình, văn hóa, xã hội và kinh nghiệm; các chuẩn mực nghề nghiệp đặt ra kỳ vọng chung để giảm tùy tiện. Khi niềm tin cá nhân không trùng nghĩa vụ nghề nghiệp, cần xác định nguyên tắc và nghĩa vụ liên quan thay vì áp đặt sở thích riêng lên khách hàng.","trap_vi":"Một người có ý tốt vẫn có thể quyết định phi đạo đức nếu không xem xét các nghĩa vụ khách quan."},{"stem_en":"Two products are suitable for a client. One is substantially more expensive with no offsetting client benefit. A fiduciary assessment should primarily consider:","options":["the client's best interests when choosing between the products.","whether both products meet a minimum suitability threshold, without further analysis.","which product generates the larger adviser commission."],"correct":0,"why_vi":"Trong ví dụ của Curriculum, fiduciary duty yêu cầu mức chăm sóc cao khi hành động cho lợi ích người khác, trong khi suitability xét mức phù hợp của khoản đầu tư với mục tiêu, rủi ro và hoàn cảnh khách hàng. Yêu cầu pháp lý có thể khác giữa nước và giữa loại dịch vụ; một sản phẩm phù hợp chưa chắc là lựa chọn phục vụ tốt nhất lợi ích khách hàng.","trap_vi":"Không xem hai chuẩn là hoàn toàn đồng nhất; không giả định mọi nước có cùng luật."},{"stem_en":"A manager discovers a legal but obscure charge that materially reduces investors' net returns. No contractual clause requires a separate explanation. What is the best initial ethical response?","options":["Consider whether it harms clients and communicate material cost transparently.","Continue charging without review because the contract is legal.","Assume the charge is ethical whenever the employer receives revenue."],"correct":0,"why_vi":"Xác định stakeholders: nhà đầu tư bị giảm net return, firm thu phí, người quản lý có duty và có thể có incentive. Tính hợp pháp không kết luận ethics. Xem xét tác động, nghĩa vụ disclosure và cách giải thích phí rõ ràng cho client; nếu chưa đủ thông tin, hỏi compliance và kiểm tra điều khoản áp dụng.","trap_vi":"Legal permissibility is not equivalent to ethical acceptability."},{"stem_en":"A research department receives a revenue bonus after issuing a promotional report that knowingly omits a significant risk. Several downstream investors buy the security. Which ethical issue is most important?","options":["The conduct may be unethical because it disregards downstream stakeholders and professional duties.","The conduct is ethical if only paying clients received the original report.","The bonus makes the conduct ethical unless investors immediately complain."],"correct":0,"why_vi":"Bản report có tác động trực tiếp tới doanh thu firm và gián tiếp tới nhà đầu tư dựa vào report. Bonus không chứng minh chất lượng hoặc tính đạo đức. Đánh giá hành vi che giấu rủi ro và hậu quả đối với mọi stakeholder, không chỉ người ký hợp đồng.","trap_vi":"Consider indirect stakeholders, not merely direct clients."},{"stem_en":"A platform earns higher fees by simplifying a disclosure in a way that obscures a material disadvantage to investors. Which assessment is most appropriate?","options":["The higher fees establish that the decision is ethical.","The effects on investors and other stakeholders should be evaluated alongside the platform’s interests.","Only the platform’s internal approval matters."],"correct":1,"why_en":"Ethical reasoning considers stakeholder consequences; approval or private benefit alone does not settle the issue.","why_vi":"Cần xét hậu quả đối với nhà đầu tư và các bên liên quan; lợi ích riêng hay phê duyệt nội bộ không đủ.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 19–21 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 154; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 5","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Stakeholder impact and self-interest"}],"cards":[{"front_en":"Ethics and moral principles","back_vi":"Ethics (đạo đức) nghiên cứu việc lựa chọn hành vi tốt, dựa trên nguyên tắc đạo đức và quy tắc ứng xử định hướng hành vi. Ethical conduct phù hợp các nguyên tắc và kỳ vọng đạo đức của cộng đồng. Đây không chỉ là sở thích cá nhân hay tuân thủ pháp luật; cần cân nhắc tác động tới những người khác. | Exam trap: Đừng đồng nhất ethics với legal compliance hoặc với việc tối đa hóa lợi ích bản thân."},{"front_en":"Stakeholders and indirect effects","back_vi":"Stakeholders là cá nhân hoặc nhóm chịu ảnh hưởng trực tiếp hoặc gián tiếp từ quyết định: khách hàng hiện tại và tiềm năng, nhân viên, đồng nghiệp, công ty, nhà quản lý, thị trường và cộng đồng. Phân tích đầy đủ cần nhìn cả người không tham gia ký hợp đồng nhưng chịu hậu quả. | Exam trap: Không giới hạn stakeholders ở cổ đông hoặc người trực tiếp nhận tiền."},{"front_en":"Short-term gain versus long-term harm","back_vi":"Một hành vi có thể làm tăng doanh thu hoặc thu nhập ngắn hạn nhưng giảm niềm tin, làm tổn hại khách hàng, uy tín doanh nghiệp và tính toàn vẹn của thị trường trong dài hạn. Hậu quả có thể lan sang người không có quan hệ trực tiếp với người ra quyết định. | Exam trap: Lợi nhuận và kết quả đầu tư tốt không tự chứng minh hành vi có đạo đức."},{"front_en":"Ethical conduct versus personal values","back_vi":"Giá trị cá nhân hình thành từ gia đình, văn hóa, xã hội và kinh nghiệm; các chuẩn mực nghề nghiệp đặt ra kỳ vọng chung để giảm tùy tiện. Khi niềm tin cá nhân không trùng nghĩa vụ nghề nghiệp, cần xác định nguyên tắc và nghĩa vụ liên quan thay vì áp đặt sở thích riêng lên khách hàng. | Exam trap: Một người có ý tốt vẫn có thể quyết định phi đạo đức nếu không xem xét các nghĩa vụ khách quan."},{"front_en":"Fiduciary and suitability standards","back_vi":"Trong ví dụ của Curriculum, fiduciary duty yêu cầu mức chăm sóc cao khi hành động cho lợi ích người khác, trong khi suitability xét mức phù hợp của khoản đầu tư với mục tiêu, rủi ro và hoàn cảnh khách hàng. Yêu cầu pháp lý có thể khác giữa nước và giữa loại dịch vụ; một sản phẩm phù hợp chưa chắc là lựa chọn phục vụ tốt nhất lợi ích khách hàng. | Exam trap: Không xem hai chuẩn là hoàn toàn đồng nhất; không giả định mọi nước có cùng luật."},{"front_en":"Stakeholder impact map — framework?","back_vi":"Action → direct effects → indirect effects → affected stakeholders → short/long-term consequences · Xem tác động của một quyết định lên khách hàng, bản thân, công ty, profession, thị trường và xã hội; lợi ích một nhóm có thể đi kèm thiệt hại nhóm khác. · Khung phân tích định tính, không cộng lợi ích thành một điểm số để vượt qua nghĩa vụ bắt buộc."},{"front_en":"Ethics vs outcome — framework?","back_vi":"Intent + conduct + duties + foreseeable consequences · Đánh giá cả quá trình và hậu quả; kết quả lợi nhuận dương không tự xác nhận hành vi đúng. · Không suy ra một khoản lỗ tự động là vi phạm."},{"front_en":"A manager discovers a legal but obscure charge that materially reduces investors' net returns. No contractual clause requires a separate explanation. What is the best initial ethical response?","back_vi":"Evaluate the charge from the client's perspective and provide appropriate transparent disclosure. — Xác định stakeholders: nhà đầu tư bị giảm net return, firm thu phí, người quản lý có duty và có thể có incentive. Tính hợp pháp không kết luận ethics. Xem xét tác động, nghĩa vụ disclosure và cách giải thích phí rõ ràng cho client; nếu chưa đủ thông tin, hỏi compliance và kiểm tra điều khoản áp dụng."},{"front_en":"A research department receives a revenue bonus after issuing a promotional report that knowingly omits a significant risk. Several downstream investors buy the security. Which ethical issue is most important?","back_vi":"The harm to investors and market trust must be considered despite the firm's revenue gain. — Bản report có tác động trực tiếp tới doanh thu firm và gián tiếp tới nhà đầu tư dựa vào report. Bonus không chứng minh chất lượng hoặc tính đạo đức. Đánh giá hành vi che giấu rủi ro và hậu quả đối với mọi stakeholder, không chỉ người ký hợp đồng."},{"front_en":"Stakeholder impact and self-interest","back_en":"Ethical reasoning considers effects on others as well as one’s own interests. A benefit to one stakeholder can impose costs on another; consider both direct and indirect effects over time. Personal conviction alone does not establish that conduct is ethical.","back_vi":"Suy luận đạo đức cân nhắc lợi ích bản thân cùng ảnh hưởng tới người khác. Lợi ích của một bên có thể gây chi phí cho bên khác; cần xét cả tác động trực tiếp, gián tiếp và dài hạn. Niềm tin cá nhân không tự chứng minh hành vi đúng đắn.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 19–21 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 154; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 5","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-01-LOS02","letter":"b","title_en":"Role of a Code of Ethics","outcome_en":"describe how a code of ethics helps define a profession","overview_vi":"Bài 1.b: Role of a Code of Ethics. Học nguyên tắc, phân biệt nghĩa vụ và bẫy, rồi vận dụng vào tình huống tiếng Anh nguyên gốc. Các khung trong phần Công thức là khung định tính, không phải công thức toán. LM2 giới thiệu các sub-standard; hướng dẫn áp dụng chi tiết thuộc LM3. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 17 (LOS); pp. 19–22, 27 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 89","pages":"Physical PDF pp. 154–155"},{"id":"SAPP CFA Level I 2026 — Ethics slides","pages":"Physical PDF pp. 5, 8"}],"sections":[{"heading":"Code of ethics — public commitment","body":"Code of ethics truyền đạt các giá trị và hành vi kỳ vọng của thành viên, đồng thời cung cấp nguyên tắc hướng dẫn khi gặp tình huống chưa có quy tắc chi tiết. Việc công khai cam kết giúp khách hàng và xã hội hiểu cách các kỹ năng chuyên môn sẽ được sử dụng.","trap":"Có code không có nghĩa là mọi người luôn tuân thủ."},{"heading":"Standards of conduct — minimum benchmarks","body":"Standards of conduct cụ thể hóa các hành vi bắt buộc hoặc bị cấm, đóng vai trò chuẩn tối thiểu để đánh giá việc tuân thủ. Một code có thể được bổ sung bằng standards; không phải mọi tổ chức đều nhất thiết có cả hai dưới hai tài liệu riêng.","trap":"Minimum acceptable conduct không đồng nghĩa best practice."},{"heading":"Best practices and accountability","body":"Best practices là phương thức được khuyến nghị để đạt kết quả tốt hoặc phòng ngừa vi phạm. Các chuẩn bắt buộc đặt ra mức tối thiểu; quy trình kỷ luật giúp thực thi nhưng không thay thế phán đoán của mỗi thành viên.","trap":"Không coi mọi recommended procedure tự động là nghĩa vụ bắt buộc trong mọi hoàn cảnh."},{"heading":"Code and professional identity","body":"Thành viên chia sẻ kiến thức chuyên ngành và cam kết phục vụ người khác; code phân biệt định hướng của profession với một nhóm chỉ nhằm thúc đẩy quyền lợi kinh doanh cho hội viên. Cam kết chung giúp xây dựng lòng tin và kỳ vọng nhất quán.","trap":"Code không chỉ là công cụ marketing cho danh hiệu."},{"heading":"From principles to decisions","body":"Code giúp đánh giá các lựa chọn kể cả khi chưa có quy định chi tiết cho một công nghệ hoặc sản phẩm mới. Áp dụng nguyên tắc phải dựa vào facts, nghĩa vụ và rủi ro, không chỉ tìm đúng từ khóa trong chính sách.","trap":"Không dùng sự im lặng của code làm bằng chứng hành vi được phép."},{"heading":"Principles versus enforceable behavioral benchmarks","body":"Code có thể nêu cam kết chung mà không liệt kê mọi hành vi cấm. Standards cụ thể hóa thành yêu cầu tối thiểu. Việc công bố hoặc cam kết không bảo đảm mọi hành vi đều đúng. Giám sát, đào tạo và trách nhiệm giải trình giúp thực thi.","body_en":"A code can articulate shared commitments without listing every prohibited act. Standards can translate those commitments into specific minimum expectations. Neither publication alone nor a promise of adherence guarantees actual conduct. Monitoring, training and accountability help turn the commitment into practice.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 19–22, 27 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 154–155; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 5, 8","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Code / Standard / Best practice","expr":"Code: shared principles; Standard: minimum conduct; Best practice: recommended procedure","meaning":"Code truyền đạt giá trị; standards cụ thể hóa ngưỡng tối thiểu; best practices hỗ trợ phòng vi phạm.","conditions":"Một best practice có thể trở thành bắt buộc nếu luật hoặc chính sách áp dụng yêu cầu; không khẳng định chung cho mọi trường hợp."}],"examples":[{"question_en":"A newly formed association publishes a code that states members will serve clients honestly but has no detailed rule on promotional gifts. What is the best interpretation?","steps_vi":["Code có thể tồn tại riêng như tuyên bố giá trị và định hướng. Không nhất thiết mọi code đều phải có standards riêng.","Có thể xây thêm standards và recommended procedures để xác định mức hành vi tối thiểu và cách phòng vi phạm."],"answer":"The code provides broad guidance; detailed conduct standards can supplement it.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A policy recommends documenting annual conflicts reviews, while a separate rule prohibits knowingly misleading statements. Which is the better classification?","steps_vi":["Policy recommends một quy trình giúp phòng vi phạm; rule prohibits một hành vi cụ thể là minimum conduct.","Không biến cả hai thành cùng một loại nghĩa vụ nếu nguồn không nói vậy. Kiểm tra xem chính sách có bắt buộc theo employer hoặc luật hay không."],"answer":"The recommendation is a best practice, while the prohibition defines a minimum conduct standard.","check":"Original conceptual vignette; conclusion limited to stated facts."}],"questions":[{"stem_en":"A professional body publishes a code explaining the values expected of its members. The principal benefit is to:","options":["communicate common ethical commitments to members and the public.","guarantee that members never face conflicting obligations.","replace all laws applicable to the profession."],"correct":0,"why_vi":"Code of ethics truyền đạt các giá trị và hành vi kỳ vọng của thành viên, đồng thời cung cấp nguyên tắc hướng dẫn khi gặp tình huống chưa có quy tắc chi tiết. Việc công khai cam kết giúp khách hàng và xã hội hiểu cách các kỹ năng chuyên môn sẽ được sử dụng.","trap_vi":"Có code không có nghĩa là mọi người luôn tuân thủ."},{"stem_en":"An association adds a rule that specifies when confidential client data may be released. The new rule is best described as:","options":["a statement of aspirational values only.","a substitute for all legal confidentiality obligations.","a standard of conduct implementing broad ethical principles."],"correct":2,"why_vi":"Standards of conduct cụ thể hóa các hành vi bắt buộc hoặc bị cấm, đóng vai trò chuẩn tối thiểu để đánh giá việc tuân thủ. Một code có thể được bổ sung bằng standards; không phải mọi tổ chức đều nhất thiết có cả hai dưới hai tài liệu riêng.","trap_vi":"Minimum acceptable conduct không đồng nghĩa best practice."},{"stem_en":"A professional body's guidance recommends periodic peer review but does not mandate a specific frequency. The recommendation is best described as:","options":["a mandatory minimum review interval.","a statutory licensing requirement.","a best practice for supporting compliance."],"correct":2,"why_vi":"Best practices là phương thức được khuyến nghị để đạt kết quả tốt hoặc phòng ngừa vi phạm. Các chuẩn bắt buộc đặt ra mức tối thiểu; quy trình kỷ luật giúp thực thi nhưng không thay thế phán đoán của mỗi thành viên.","trap_vi":"Không coi mọi recommended procedure tự động là nghĩa vụ bắt buộc trong mọi hoàn cảnh."},{"stem_en":"A trade group adopts a marketing slogan but has no shared conduct expectations. Which addition would most directly support its evolution into a profession?","options":["An increase in membership fees without new standards.","A publicly communicated ethical code supported by professional accountability.","A wider advertising campaign for member firms."],"correct":1,"why_vi":"Thành viên chia sẻ kiến thức chuyên ngành và cam kết phục vụ người khác; code phân biệt định hướng của profession với một nhóm chỉ nhằm thúc đẩy quyền lợi kinh doanh cho hội viên. Cam kết chung giúp xây dựng lòng tin và kỳ vọng nhất quán.","trap_vi":"Code không chỉ là công cụ marketing cho danh hiệu."},{"stem_en":"A new automated advice tool is not specifically mentioned in the firm's code. Which response is most appropriate?","options":["Apply the code's principles to the new tool and assess client consequences.","Treat any unlisted conduct as acceptable.","Wait for a new law before considering ethical implications."],"correct":0,"why_vi":"Code giúp đánh giá các lựa chọn kể cả khi chưa có quy định chi tiết cho một công nghệ hoặc sản phẩm mới. Áp dụng nguyên tắc phải dựa vào facts, nghĩa vụ và rủi ro, không chỉ tìm đúng từ khóa trong chính sách.","trap_vi":"Không dùng sự im lặng của code làm bằng chứng hành vi được phép."},{"stem_en":"A newly formed association publishes a code that states members will serve clients honestly but has no detailed rule on promotional gifts. What is the best interpretation?","options":["The code expresses ethical principles that may be clarified by specific standards.","The code has no ethical role until every possible action is explicitly listed.","The code ensures that all members will behave ethically."],"correct":0,"why_vi":"Code có thể tồn tại riêng như tuyên bố giá trị và định hướng. Không nhất thiết mọi code đều phải có standards riêng. Có thể xây thêm standards và recommended procedures để xác định mức hành vi tối thiểu và cách phòng vi phạm.","trap_vi":"Code and detailed standards are distinct but complementary."},{"stem_en":"A policy recommends documenting annual conflicts reviews, while a separate rule prohibits knowingly misleading statements. Which is the better classification?","options":["Two identical aspirational statements with no enforceable distinction.","A best practice and a minimum standard, respectively.","Two statutory prohibitions irrespective of their wording."],"correct":1,"why_vi":"Policy recommends một quy trình giúp phòng vi phạm; rule prohibits một hành vi cụ thể là minimum conduct. Không biến cả hai thành cùng một loại nghĩa vụ nếu nguồn không nói vậy. Kiểm tra xem chính sách có bắt buộc theo employer hoặc luật hay không.","trap_vi":"Recommended procedure is not automatically identical to a mandatory standard."},{"stem_en":"A professional body publishes broad values but no detailed conduct rules. Which conclusion is most accurate?","options":["It cannot have a code of ethics.","It guarantees the behavior of its members.","It can have a principles-based code, even without separate detailed standards."],"correct":2,"why_en":"A code need not contain detailed standards; a public commitment does not guarantee adherence.","why_vi":"Code có thể dựa trên nguyên tắc, không bắt buộc có quy tắc chi tiết; cam kết không bảo đảm tuân thủ.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 19–22, 27 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 154–155; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 5, 8","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Principles versus enforceable behavioral benchmarks"}],"cards":[{"front_en":"Code of ethics — public commitment","back_vi":"Code of ethics truyền đạt các giá trị và hành vi kỳ vọng của thành viên, đồng thời cung cấp nguyên tắc hướng dẫn khi gặp tình huống chưa có quy tắc chi tiết. Việc công khai cam kết giúp khách hàng và xã hội hiểu cách các kỹ năng chuyên môn sẽ được sử dụng. | Exam trap: Có code không có nghĩa là mọi người luôn tuân thủ."},{"front_en":"Standards of conduct — minimum benchmarks","back_vi":"Standards of conduct cụ thể hóa các hành vi bắt buộc hoặc bị cấm, đóng vai trò chuẩn tối thiểu để đánh giá việc tuân thủ. Một code có thể được bổ sung bằng standards; không phải mọi tổ chức đều nhất thiết có cả hai dưới hai tài liệu riêng. | Exam trap: Minimum acceptable conduct không đồng nghĩa best practice."},{"front_en":"Best practices and accountability","back_vi":"Best practices là phương thức được khuyến nghị để đạt kết quả tốt hoặc phòng ngừa vi phạm. Các chuẩn bắt buộc đặt ra mức tối thiểu; quy trình kỷ luật giúp thực thi nhưng không thay thế phán đoán của mỗi thành viên. | Exam trap: Không coi mọi recommended procedure tự động là nghĩa vụ bắt buộc trong mọi hoàn cảnh."},{"front_en":"Code and professional identity","back_vi":"Thành viên chia sẻ kiến thức chuyên ngành và cam kết phục vụ người khác; code phân biệt định hướng của profession với một nhóm chỉ nhằm thúc đẩy quyền lợi kinh doanh cho hội viên. Cam kết chung giúp xây dựng lòng tin và kỳ vọng nhất quán. | Exam trap: Code không chỉ là công cụ marketing cho danh hiệu."},{"front_en":"From principles to decisions","back_vi":"Code giúp đánh giá các lựa chọn kể cả khi chưa có quy định chi tiết cho một công nghệ hoặc sản phẩm mới. Áp dụng nguyên tắc phải dựa vào facts, nghĩa vụ và rủi ro, không chỉ tìm đúng từ khóa trong chính sách. | Exam trap: Không dùng sự im lặng của code làm bằng chứng hành vi được phép."},{"front_en":"Code / Standard / Best practice — framework?","back_vi":"Code: shared principles; Standard: minimum conduct; Best practice: recommended procedure · Code truyền đạt giá trị; standards cụ thể hóa ngưỡng tối thiểu; best practices hỗ trợ phòng vi phạm. · Một best practice có thể trở thành bắt buộc nếu luật hoặc chính sách áp dụng yêu cầu; không khẳng định chung cho mọi trường hợp."},{"front_en":"A newly formed association publishes a code that states members will serve clients honestly but has no detailed rule on promotional gifts. What is the best interpretation?","back_vi":"The code provides broad guidance; detailed conduct standards can supplement it. — Code có thể tồn tại riêng như tuyên bố giá trị và định hướng. Không nhất thiết mọi code đều phải có standards riêng. Có thể xây thêm standards và recommended procedures để xác định mức hành vi tối thiểu và cách phòng vi phạm."},{"front_en":"A policy recommends documenting annual conflicts reviews, while a separate rule prohibits knowingly misleading statements. Which is the better classification?","back_vi":"The recommendation is a best practice, while the prohibition defines a minimum conduct standard. — Policy recommends một quy trình giúp phòng vi phạm; rule prohibits một hành vi cụ thể là minimum conduct. Không biến cả hai thành cùng một loại nghĩa vụ nếu nguồn không nói vậy. Kiểm tra xem chính sách có bắt buộc theo employer hoặc luật hay không."},{"front_en":"Principles versus enforceable behavioral benchmarks","back_en":"A code can articulate shared commitments without listing every prohibited act. Standards can translate those commitments into specific minimum expectations. Neither publication alone nor a promise of adherence guarantees actual conduct. Monitoring, training and accountability help turn the commitment into practice.","back_vi":"Code có thể nêu cam kết chung mà không liệt kê mọi hành vi cấm. Standards cụ thể hóa thành yêu cầu tối thiểu. Việc công bố hoặc cam kết không bảo đảm mọi hành vi đều đúng. Giám sát, đào tạo và trách nhiệm giải trình giúp thực thi.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 19–22, 27 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 154–155; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 5, 8","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-01-LOS03","letter":"c","title_en":"Professions and Establishing Trust","outcome_en":"describe professions and the ways they establish trust","overview_vi":"Bài 1.c: Professions and Establishing Trust. Học nguyên tắc, phân biệt nghĩa vụ và bẫy, rồi vận dụng vào tình huống tiếng Anh nguyên gốc. Các khung trong phần Công thức là khung định tính, không phải công thức toán. LM2 giới thiệu các sub-standard; hướng dẫn áp dụng chi tiết thuộc LM3. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 17 (LOS); pp. 21–24 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 89","pages":"Physical PDF pp. 155"},{"id":"SAPP CFA Level I 2026 — Ethics slides","pages":"Physical PDF pp. 6–7"}],"sections":[{"heading":"Profession — specialized knowledge and public purpose","body":"Profession là nhóm nghề có yêu cầu đào tạo, kiến thức chuyên sâu và hệ thống thực hành/ứng xử tạo sự tín nhiệm, tôn trọng và công nhận của cộng đồng. Thành viên sử dụng chuyên môn để phục vụ khách hàng và xã hội chứ không chỉ để gia tăng thu nhập.","trap":"Occupational group không tự động là profession chỉ vì có chuyên môn."},{"heading":"Normalizing practitioner behavior","body":"Code và standards tạo cách ứng xử nhất quán giữa người hành nghề; quy định nghề nghiệp do các practitioner đóng góp có thể bổ sung quy định của nhà nước ở mức chi tiết hơn. Sự nhất quán làm giảm bất định về chất lượng và hành vi dịch vụ.","trap":"Chuẩn nghề nghiệp bổ sung chứ không vô hiệu hóa luật."},{"heading":"Service to society","body":"Profession có vai trò vượt ngoài phạm vi giao dịch thương mại: nâng cao chuẩn giáo dục, tăng niềm tin, mở rộng khả năng tiếp cận dịch vụ và hỗ trợ hoạt động kinh tế. Uy tín có thể đem lại lợi ích thương mại và tự chủ nghề nghiệp, nhưng lợi ích đó là hệ quả chứ không phải mục đích duy nhất.","trap":"Phục vụ xã hội không có nghĩa cấm thu phí hoặc có lợi nhuận."},{"heading":"Client focus and fiduciary duty","body":"Client focus yêu cầu vận dụng chuyên môn, care, skill và diligence cho lợi ích người được phục vụ. Fiduciary duty biểu thị nghĩa vụ chăm sóc cao khi hành động thay mặt người khác. Niềm tin gia tăng khi khách hàng có cơ sở kỳ vọng người chuyên môn không lợi dụng sự phụ thuộc của mình.","trap":"Không đặt quyền lợi cá nhân lên trước client interest."},{"heading":"High entry standards and body of expert knowledge","body":"Tiêu chuẩn đầu vào, kiểm tra năng lực, chương trình đào tạo và kho tri thức được phát triển bởi người hành nghề có kinh nghiệm giúp người sử dụng dịch vụ đánh giá năng lực. Credential là tín hiệu chất lượng kỳ vọng chứ không bảo đảm mọi quyết định đúng.","trap":"Một kỳ thi không thể thay thế việc duy trì năng lực."},{"heading":"Continuing education","body":"Kiến thức, công nghệ, luật và thực tiễn thay đổi trong suốt sự nghiệp. Continuing professional development giúp cập nhật kỹ năng và phán đoán đạo đức; một số professional bodies có yêu cầu học tập cụ thể, nhưng không được suy diễn rằng mọi body hay CFA Standard I(E) đều yêu cầu cùng số giờ.","trap":"Phân biệt continuing competence với một số giờ bắt buộc phổ quát."},{"heading":"Monitoring and discipline","body":"Professional conduct được giám sát thông qua complaints, investigation và disciplinary process. Self-regulation có thể nâng cao trách nhiệm giải trình, trong khi sanction nghề nghiệp không đồng nhất với chế tài pháp lý của nhà nước.","trap":"Không đánh đồng professional body với cơ quan hình sự."},{"heading":"Collegiality and member engagement","body":"Collegiality yêu cầu tôn trọng quyền, phẩm giá và sự tự chủ của người khác kể cả đối thủ cạnh tranh. Engagement bao gồm đóng góp xây dựng chuẩn, mentoring, chia sẻ chuyên môn và tình nguyện phục vụ profession; không đòi hỏi chia sẻ thông tin bí mật hay phối hợp giá.","trap":"Tôn trọng đồng nghiệp không có nghĩa bảo vệ hành vi sai trái."},{"heading":"Recognized oversight and evolving professions","body":"Oversight body hỗ trợ chuẩn, đào tạo, cập nhật kiến thức và trách nhiệm kỷ luật. Professions tiếp tục thay đổi trước công nghệ, public accountability, minh bạch và quan điểm của người ngoài nghề; một profession có thể chưa đạt hoàn hảo mọi thuộc tính tại một thời điểm.","trap":"Không dùng tiêu chí tuyệt đối rằng chỉ nghề hoàn hảo mới được công nhận."},{"heading":"Trust requires credible entry, continuing competence and oversight","body":"Nghề chuyên môn tạo niềm tin qua tri thức chuyên sâu, phục vụ người khác, tiêu chuẩn gia nhập, đạo đức, duy trì năng lực và cơ chế kỷ luật đáng tin. Hiệp hội thương mại có thể đại diện lợi ích kinh doanh mà không có cùng chức năng giám sát nghề. Tư cách thành viên không tự chứng minh năng lực.","body_en":"A profession builds trust through specialized expertise, service to others, admission criteria, ethical expectations, ongoing competence and credible disciplinary mechanisms. A trade group can represent commercial interests without serving the same professional oversight function. Membership in an organization alone is not proof of professional skill.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 21–24 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 155; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 6–7","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Ten trust-building characteristics","expr":"Common conduct; society; clients; entry; expert knowledge; education; monitoring; collegiality; oversight; engagement","meaning":"Mười đặc điểm của profession trong CFAI: chuẩn hóa hành vi, phục vụ xã hội, client focus, tiêu chuẩn đầu vào cao, kho tri thức, continuing education, monitoring, collegiality, recognized oversight body, member engagement.","conditions":"Các đặc điểm hỗ trợ lẫn nhau; profession đang phát triển có thể chưa thực hiện hoàn hảo mọi đặc điểm."}],"examples":[{"question_en":"An industry association offers training and has a membership directory. It does not set ethical requirements or monitor conduct. Which change would most directly strengthen its professional status?","steps_vi":["Đào tạo và danh bạ chỉ đáp ứng một phần characteristic; thiếu shared standards và accountability.","Thêm code, standards, cơ chế monitor/discipline và service orientation để xây dựng trust."],"answer":"Establish ethical conduct standards and accountable oversight.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A senior analyst volunteers to help update a professional curriculum and mentors analysts at other firms. She protects client information and respects competitors. Which characteristics are illustrated?","steps_vi":["Công việc tình nguyện là member engagement; mentoring giúp duy trì competence và body of knowledge; tôn trọng đồng nghiệp là collegiality.","Không xung đột với confidentiality vì không chia sẻ thông tin bí mật."],"answer":"Member engagement, continuing education and collegiality.","check":"Original conceptual vignette; conclusion limited to stated facts."}],"questions":[{"stem_en":"A group has advanced technical skills but no shared service or ethical commitments. Which feature is most clearly missing?","options":["A market for the group's technical services.","The possibility of earning income from specialized work.","A professional framework linking expertise to trusted conduct."],"correct":2,"why_vi":"Profession là nhóm nghề có yêu cầu đào tạo, kiến thức chuyên sâu và hệ thống thực hành/ứng xử tạo sự tín nhiệm, tôn trọng và công nhận của cộng đồng. Thành viên sử dụng chuyên môn để phục vụ khách hàng và xã hội chứ không chỉ để gia tăng thu nhập.","trap_vi":"Occupational group không tự động là profession chỉ vì có chuyên môn."},{"stem_en":"Which action most directly normalizes practitioner behavior across competing firms?","options":["Adopting common professional conduct standards.","Setting identical profit margins for firms.","Requiring identical investment recommendations for clients."],"correct":0,"why_vi":"Code và standards tạo cách ứng xử nhất quán giữa người hành nghề; quy định nghề nghiệp do các practitioner đóng góp có thể bổ sung quy định của nhà nước ở mức chi tiết hơn. Sự nhất quán làm giảm bất định về chất lượng và hành vi dịch vụ.","trap_vi":"Chuẩn nghề nghiệp bổ sung chứ không vô hiệu hóa luật."},{"stem_en":"A profession supports education for underserved clients even when immediate member revenue is unchanged. This activity most directly illustrates:","options":["control of competitive pricing.","a guarantee of future investment performance.","service to society."],"correct":2,"why_vi":"Profession có vai trò vượt ngoài phạm vi giao dịch thương mại: nâng cao chuẩn giáo dục, tăng niềm tin, mở rộng khả năng tiếp cận dịch vụ và hỗ trợ hoạt động kinh tế. Uy tín có thể đem lại lợi ích thương mại và tự chủ nghề nghiệp, nhưng lợi ích đó là hệ quả chứ không phải mục đích duy nhất.","trap_vi":"Phục vụ xã hội không có nghĩa cấm thu phí hoặc có lợi nhuận."},{"stem_en":"An adviser gives up a larger personal commission to recommend a better solution for the client. The action most directly supports:","options":["the standardization of investment returns.","the elimination of all business conflicts.","client-focused professional conduct."],"correct":2,"why_vi":"Client focus yêu cầu vận dụng chuyên môn, care, skill và diligence cho lợi ích người được phục vụ. Fiduciary duty biểu thị nghĩa vụ chăm sóc cao khi hành động thay mặt người khác. Niềm tin gia tăng khi khách hàng có cơ sở kỳ vọng người chuyên môn không lợi dụng sự phụ thuộc của mình.","trap_vi":"Không đặt quyền lợi cá nhân lên trước client interest."},{"stem_en":"A professional examination tests ethical reasoning and technical knowledge before entry. Its main role is to:","options":["signal and support a defined level of initial competence.","eliminate the need for later professional development.","ensure all members make the same investment decisions."],"correct":0,"why_vi":"Tiêu chuẩn đầu vào, kiểm tra năng lực, chương trình đào tạo và kho tri thức được phát triển bởi người hành nghề có kinh nghiệm giúp người sử dụng dịch vụ đánh giá năng lực. Credential là tín hiệu chất lượng kỳ vọng chứ không bảo đảm mọi quyết định đúng.","trap_vi":"Một kỳ thi không thể thay thế việc duy trì năng lực."},{"stem_en":"An experienced analyst moves into a new product area with unfamiliar risks. Which professional characteristic is most relevant to closing the knowledge gap?","options":["The original entry examination alone.","Continuing education and development.","Membership in a trade association alone."],"correct":1,"why_vi":"Kiến thức, công nghệ, luật và thực tiễn thay đổi trong suốt sự nghiệp. Continuing professional development giúp cập nhật kỹ năng và phán đoán đạo đức; một số professional bodies có yêu cầu học tập cụ thể, nhưng không được suy diễn rằng mọi body hay CFA Standard I(E) đều yêu cầu cùng số giờ.","trap_vi":"Phân biệt continuing competence với một số giờ bắt buộc phổ quát."},{"stem_en":"A professional body investigates complaints and may suspend members after due process. This is primarily evidence of:","options":["monitoring and enforcement of professional conduct.","a guarantee of legal damages to complainants.","the elimination of government regulation."],"correct":0,"why_vi":"Professional conduct được giám sát thông qua complaints, investigation và disciplinary process. Self-regulation có thể nâng cao trách nhiệm giải trình, trong khi sanction nghề nghiệp không đồng nhất với chế tài pháp lý của nhà nước.","trap_vi":"Không đánh đồng professional body với cơ quan hình sự."},{"stem_en":"Two competing analysts volunteer to mentor new entrants without sharing client data. This best illustrates:","options":["a requirement to coordinate trading strategies.","a waiver of confidentiality duties.","collegiality and member engagement."],"correct":2,"why_vi":"Collegiality yêu cầu tôn trọng quyền, phẩm giá và sự tự chủ của người khác kể cả đối thủ cạnh tranh. Engagement bao gồm đóng góp xây dựng chuẩn, mentoring, chia sẻ chuyên môn và tình nguyện phục vụ profession; không đòi hỏi chia sẻ thông tin bí mật hay phối hợp giá.","trap_vi":"Tôn trọng đồng nghiệp không có nghĩa bảo vệ hành vi sai trái."},{"stem_en":"A profession revises its conduct guidance after consulting clients about a new technology. This most directly demonstrates:","options":["abandonment of its ethical purpose.","adaptation to changing practices and stakeholder expectations.","a requirement to accept every public suggestion."],"correct":1,"why_vi":"Oversight body hỗ trợ chuẩn, đào tạo, cập nhật kiến thức và trách nhiệm kỷ luật. Professions tiếp tục thay đổi trước công nghệ, public accountability, minh bạch và quan điểm của người ngoài nghề; một profession có thể chưa đạt hoàn hảo mọi thuộc tính tại một thời điểm.","trap_vi":"Không dùng tiêu chí tuyệt đối rằng chỉ nghề hoàn hảo mới được công nhận."},{"stem_en":"An industry association offers training and has a membership directory. It does not set ethical requirements or monitor conduct. Which change would most directly strengthen its professional status?","options":["Increase advertising while leaving conduct entirely unregulated.","Restrict all members to a single investment strategy.","Establish conduct standards and a credible monitoring mechanism."],"correct":2,"why_vi":"Đào tạo và danh bạ chỉ đáp ứng một phần characteristic; thiếu shared standards và accountability. Thêm code, standards, cơ chế monitor/discipline và service orientation để xây dựng trust.","trap_vi":"Technical expertise alone does not establish professional trust."},{"stem_en":"A senior analyst volunteers to help update a professional curriculum and mentors analysts at other firms. She protects client information and respects competitors. Which characteristics are illustrated?","options":["A mandatory duty to share all proprietary research.","The elimination of market competition between members.","Collegiality and member engagement supporting professional development."],"correct":2,"why_vi":"Công việc tình nguyện là member engagement; mentoring giúp duy trì competence và body of knowledge; tôn trọng đồng nghiệp là collegiality. Không xung đột với confidentiality vì không chia sẻ thông tin bí mật.","trap_vi":"Professional engagement does not require sharing confidential information."},{"stem_en":"Which initiative most directly improves confidence that a professional body’s members continue to meet its standards after admission?","options":["A functioning monitoring and disciplinary process combined with continued competence development.","An advertising campaign emphasizing the number of members.","A one-time entry examination with no subsequent oversight."],"correct":0,"why_en":"Entry tests are useful but continuing competence and accountability strengthen ongoing trust.","why_vi":"Thi đầu vào hữu ích nhưng duy trì năng lực và trách nhiệm giải trình củng cố niềm tin lâu dài.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 21–24 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 155; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 6–7","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Trust requires credible entry, continuing competence and oversight"}],"cards":[{"front_en":"Profession — specialized knowledge and public purpose","back_vi":"Profession là nhóm nghề có yêu cầu đào tạo, kiến thức chuyên sâu và hệ thống thực hành/ứng xử tạo sự tín nhiệm, tôn trọng và công nhận của cộng đồng. Thành viên sử dụng chuyên môn để phục vụ khách hàng và xã hội chứ không chỉ để gia tăng thu nhập. | Exam trap: Occupational group không tự động là profession chỉ vì có chuyên môn."},{"front_en":"Normalizing practitioner behavior","back_vi":"Code và standards tạo cách ứng xử nhất quán giữa người hành nghề; quy định nghề nghiệp do các practitioner đóng góp có thể bổ sung quy định của nhà nước ở mức chi tiết hơn. Sự nhất quán làm giảm bất định về chất lượng và hành vi dịch vụ. | Exam trap: Chuẩn nghề nghiệp bổ sung chứ không vô hiệu hóa luật."},{"front_en":"Service to society","back_vi":"Profession có vai trò vượt ngoài phạm vi giao dịch thương mại: nâng cao chuẩn giáo dục, tăng niềm tin, mở rộng khả năng tiếp cận dịch vụ và hỗ trợ hoạt động kinh tế. Uy tín có thể đem lại lợi ích thương mại và tự chủ nghề nghiệp, nhưng lợi ích đó là hệ quả chứ không phải mục đích duy nhất. | Exam trap: Phục vụ xã hội không có nghĩa cấm thu phí hoặc có lợi nhuận."},{"front_en":"Client focus and fiduciary duty","back_vi":"Client focus yêu cầu vận dụng chuyên môn, care, skill và diligence cho lợi ích người được phục vụ. Fiduciary duty biểu thị nghĩa vụ chăm sóc cao khi hành động thay mặt người khác. Niềm tin gia tăng khi khách hàng có cơ sở kỳ vọng người chuyên môn không lợi dụng sự phụ thuộc của mình. | Exam trap: Không đặt quyền lợi cá nhân lên trước client interest."},{"front_en":"High entry standards and body of expert knowledge","back_vi":"Tiêu chuẩn đầu vào, kiểm tra năng lực, chương trình đào tạo và kho tri thức được phát triển bởi người hành nghề có kinh nghiệm giúp người sử dụng dịch vụ đánh giá năng lực. Credential là tín hiệu chất lượng kỳ vọng chứ không bảo đảm mọi quyết định đúng. | Exam trap: Một kỳ thi không thể thay thế việc duy trì năng lực."},{"front_en":"Continuing education","back_vi":"Kiến thức, công nghệ, luật và thực tiễn thay đổi trong suốt sự nghiệp. Continuing professional development giúp cập nhật kỹ năng và phán đoán đạo đức; một số professional bodies có yêu cầu học tập cụ thể, nhưng không được suy diễn rằng mọi body hay CFA Standard I(E) đều yêu cầu cùng số giờ. | Exam trap: Phân biệt continuing competence với một số giờ bắt buộc phổ quát."},{"front_en":"Monitoring and discipline","back_vi":"Professional conduct được giám sát thông qua complaints, investigation và disciplinary process. Self-regulation có thể nâng cao trách nhiệm giải trình, trong khi sanction nghề nghiệp không đồng nhất với chế tài pháp lý của nhà nước. | Exam trap: Không đánh đồng professional body với cơ quan hình sự."},{"front_en":"Collegiality and member engagement","back_vi":"Collegiality yêu cầu tôn trọng quyền, phẩm giá và sự tự chủ của người khác kể cả đối thủ cạnh tranh. Engagement bao gồm đóng góp xây dựng chuẩn, mentoring, chia sẻ chuyên môn và tình nguyện phục vụ profession; không đòi hỏi chia sẻ thông tin bí mật hay phối hợp giá. | Exam trap: Tôn trọng đồng nghiệp không có nghĩa bảo vệ hành vi sai trái."},{"front_en":"Recognized oversight and evolving professions","back_vi":"Oversight body hỗ trợ chuẩn, đào tạo, cập nhật kiến thức và trách nhiệm kỷ luật. Professions tiếp tục thay đổi trước công nghệ, public accountability, minh bạch và quan điểm của người ngoài nghề; một profession có thể chưa đạt hoàn hảo mọi thuộc tính tại một thời điểm. | Exam trap: Không dùng tiêu chí tuyệt đối rằng chỉ nghề hoàn hảo mới được công nhận."},{"front_en":"Ten trust-building characteristics — framework?","back_vi":"Common conduct; society; clients; entry; expert knowledge; education; monitoring; collegiality; oversight; engagement · Mười đặc điểm của profession trong CFAI: chuẩn hóa hành vi, phục vụ xã hội, client focus, tiêu chuẩn đầu vào cao, kho tri thức, continuing education, monitoring, collegiality, recognized oversight body, member engagement. · Các đặc điểm hỗ trợ lẫn nhau; profession đang phát triển có thể chưa thực hiện hoàn hảo mọi đặc điểm."},{"front_en":"An industry association offers training and has a membership directory. It does not set ethical requirements or monitor conduct. Which change would most directly strengthen its professional status?","back_vi":"Establish ethical conduct standards and accountable oversight. — Đào tạo và danh bạ chỉ đáp ứng một phần characteristic; thiếu shared standards và accountability. Thêm code, standards, cơ chế monitor/discipline và service orientation để xây dựng trust."},{"front_en":"A senior analyst volunteers to help update a professional curriculum and mentors analysts at other firms. She protects client information and respects competitors. Which characteristics are illustrated?","back_vi":"Member engagement, continuing education and collegiality. — Công việc tình nguyện là member engagement; mentoring giúp duy trì competence và body of knowledge; tôn trọng đồng nghiệp là collegiality. Không xung đột với confidentiality vì không chia sẻ thông tin bí mật."},{"front_en":"Trust requires credible entry, continuing competence and oversight","back_en":"A profession builds trust through specialized expertise, service to others, admission criteria, ethical expectations, ongoing competence and credible disciplinary mechanisms. A trade group can represent commercial interests without serving the same professional oversight function. Membership in an organization alone is not proof of professional skill.","back_vi":"Nghề chuyên môn tạo niềm tin qua tri thức chuyên sâu, phục vụ người khác, tiêu chuẩn gia nhập, đạo đức, duy trì năng lực và cơ chế kỷ luật đáng tin. Hiệp hội thương mại có thể đại diện lợi ích kinh doanh mà không có cùng chức năng giám sát nghề. Tư cách thành viên không tự chứng minh năng lực.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 21–24 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 155; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 6–7","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-01-LOS04","letter":"d","title_en":"High Ethical Standards in Investment Management","outcome_en":"describe the need for high ethical standards in investment management","overview_vi":"Bài 1.d: High Ethical Standards in Investment Management. Học nguyên tắc, phân biệt nghĩa vụ và bẫy, rồi vận dụng vào tình huống tiếng Anh nguyên gốc. Các khung trong phần Công thức là khung định tính, không phải công thức toán. LM2 giới thiệu các sub-standard; hướng dẫn áp dụng chi tiết thuộc LM3. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 17 (LOS); pp. 17–20, 25–26, 32–33 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 89","pages":"Physical PDF pp. 155–156"},{"id":"SAPP CFA Level I 2026 — Ethics slides","pages":"Physical PDF pp. 9"},{"id":"CFAI 2026 Volume 10 — selected supporting Guidance (LM3; not full coverage)","pages":"Physical PDF pp. 67–76 (I(A)), 109–125 (II)"}],"sections":[{"heading":"Trust and entrusted assets","body":"Investment management dựa vào niềm tin vì khách hàng giao tài sản và quyết định tài chính quan trọng cho người có kiến thức vượt trội. Khách hàng thường khó đánh giá chất lượng lời khuyên, rủi ro, phí hoặc xung đột; high ethical standards giảm nguy cơ khai thác thông tin bất cân xứng.","trap":"Không lý giải nhu cầu đạo đức chỉ bằng quy định nghiêm ngặt."},{"heading":"Information asymmetry and conflicts","body":"Bên cung cấp dịch vụ biết nhiều hơn về sản phẩm, phí và cách tạo doanh thu. Họ có thể lợi dụng bất cân xứng để bán sản phẩm bất lợi; disclosure rõ ràng, phán đoán độc lập và xử lý xung đột giúp khách hàng quyết định có thông tin.","trap":"Việc khách hàng có kiến thức hạn chế không làm giảm trách nhiệm của adviser."},{"heading":"Market integrity and capital allocation","body":"Niềm tin khuyến khích người tiết kiệm tham gia thị trường; phân tích và giao dịch trung thực hỗ trợ định giá và phân bổ vốn cho hoạt động có giá trị. Khi thiếu niềm tin, người tham gia có thể rút vốn, tăng chi phí giao dịch hoặc đòi bù rủi ro, gây tổn thất cho nền kinh tế.","trap":"Ethics có hậu quả ở cấp thị trường, không chỉ từng khách hàng."},{"heading":"Benefits to firms and the profession","body":"Tính trung thực, chăm sóc và minh bạch giúp duy trì quan hệ khách hàng, giảm nguy cơ khiếu nại, chế tài và mất danh tiếng. Các hành vi lừa dối tại một doanh nghiệp có thể ảnh hưởng niềm tin đối với các doanh nghiệp khác trong ngành.","trap":"Lợi ích ngắn hạn từ vi phạm không phải bằng chứng lợi ích bền vững."},{"heading":"Market integrity and client interests","body":"Curriculum nhấn mạnh trong trường hợp lợi ích của khách hàng xung đột với market integrity, bảo vệ tính toàn vẹn của thị trường là nghĩa vụ chi phối. Không được thực hiện hành vi làm hại thị trường để tăng lợi nhuận khách hàng, kể cả khi khách hàng mong muốn.","trap":"Client first không phải giấy phép vi phạm market integrity."},{"heading":"Economic transmission of lost trust","body":"Khách hàng khó đánh giá trước chất lượng tư vấn. Hành vi sai có thể gây mất khách hàng, giảm doanh thu mới, tăng chi phí giám sát/khắc phục và giảm niềm tin thị trường. Do đó mất niềm tin có thể ảnh hưởng cả doanh thu và chi phí; không khẳng định mức tác động cố định.","body_en":"Clients cannot easily assess the quality of investment advice in advance. Misconduct can lead to client departures, weaker new business, increased monitoring and remediation costs, and reduced confidence in markets. Lower trust may thus affect both revenues and expenses; these are possible effects, not guaranteed magnitudes.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 17–20, 25–26, 32–33 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 155–156; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 9","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Trust and capital markets","expr":"Ethical conduct → confidence → participation → effective capital allocation","meaning":"Minh họa cơ chế high ethical standards hỗ trợ khách hàng và xã hội qua niềm tin và phân bổ vốn.","conditions":"Quan hệ định tính, không phải công thức dự báo lợi suất hay đảm bảo thị trường luôn hiệu quả."},{"name":"Duty priority under conflicting interests","expr":"Market integrity; client interests; employer interests; personal interests","meaning":"Trong xung đột market integrity và client interest, market integrity chi phối; client interest đặt trước employer và personal interests. Áp dụng luật và standards liên quan trước khi lựa chọn hành động.","conditions":"Không dùng thứ tự ghi nhớ này thay cho phân tích các điều kiện cụ thể của standards."}],"examples":[{"question_en":"A retired client relies on an adviser to evaluate an illiquid product. The adviser knows the client's technical knowledge is limited and the fees are complex. Which rationale best explains the need for ethical standards?","steps_vi":["Client entrusts wealth and depends on superior knowledge, tạo information asymmetry.","Adviser cần care, transparency và independence; không lợi dụng sự phụ thuộc để ưu tiên commissions."],"answer":"Clients depend on ethical use of specialized expertise to protect entrusted assets.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"Multiple dealers make misleading claims about complex products. Investors lose confidence in the market and reduce participation. What is the most likely broader ethical implication?","steps_vi":["Nhiều hành vi có vẻ riêng lẻ có thể cộng dồn làm suy yếu market integrity và public trust.","Giảm participation có thể cản trở capital allocation và lợi ích kinh tế của xã hội."],"answer":"Misconduct can damage market functioning and the broader economy.","check":"Original conceptual vignette; conclusion limited to stated facts."}],"questions":[{"stem_en":"A retiree cannot independently assess the risk model used by an adviser. The strongest reason for high ethical standards is:","options":["the adviser's ability to predict returns with certainty.","the client's inability to sign any investment contract.","the client's reliance on the adviser's expertise and stewardship."],"correct":2,"why_vi":"Investment management dựa vào niềm tin vì khách hàng giao tài sản và quyết định tài chính quan trọng cho người có kiến thức vượt trội. Khách hàng thường khó đánh giá chất lượng lời khuyên, rủi ro, phí hoặc xung đột; high ethical standards giảm nguy cơ khai thác thông tin bất cân xứng.","trap_vi":"Không lý giải nhu cầu đạo đức chỉ bằng quy định nghiêm ngặt."},{"stem_en":"A manager understands a hidden liquidity cost that clients are unlikely to detect. Ethical stewardship most strongly supports:","options":["communicating the material cost in understandable terms.","relying solely on clients to discover the cost.","disclosing the cost only if the investment loses money."],"correct":0,"why_vi":"Bên cung cấp dịch vụ biết nhiều hơn về sản phẩm, phí và cách tạo doanh thu. Họ có thể lợi dụng bất cân xứng để bán sản phẩm bất lợi; disclosure rõ ràng, phán đoán độc lập và xử lý xung đột giúp khách hàng quyết định có thông tin.","trap_vi":"Việc khách hàng có kiến thức hạn chế không làm giảm trách nhiệm của adviser."},{"stem_en":"If investors withdraw funds because financial reporting is widely distrusted, the most likely broader consequence is:","options":["automatic improvement in market liquidity.","less effective capital allocation.","elimination of information asymmetry."],"correct":1,"why_vi":"Niềm tin khuyến khích người tiết kiệm tham gia thị trường; phân tích và giao dịch trung thực hỗ trợ định giá và phân bổ vốn cho hoạt động có giá trị. Khi thiếu niềm tin, người tham gia có thể rút vốn, tăng chi phí giao dịch hoặc đòi bù rủi ro, gây tổn thất cho nền kinh tế.","trap_vi":"Ethics có hậu quả ở cấp thị trường, không chỉ từng khách hàng."},{"stem_en":"An unethical practice at one large firm causes investors to distrust other firms. The spillover illustrates:","options":["the absence of a relationship between ethics and reputation.","the profession-wide cost of ethical failures.","that only the original firm's shareholders can be affected."],"correct":1,"why_vi":"Tính trung thực, chăm sóc và minh bạch giúp duy trì quan hệ khách hàng, giảm nguy cơ khiếu nại, chế tài và mất danh tiếng. Các hành vi lừa dối tại một doanh nghiệp có thể ảnh hưởng niềm tin đối với các doanh nghiệp khác trong ngành.","trap_vi":"Lợi ích ngắn hạn từ vi phạm không phải bằng chứng lợi ích bền vững."},{"stem_en":"A client requests a trade intended to create a misleading market price that would benefit the client's portfolio. The adviser should primarily:","options":["obey the client because client interests always override market integrity.","execute the trade if the client signs a waiver.","protect market integrity and refuse the improper request."],"correct":2,"why_vi":"Curriculum nhấn mạnh trong trường hợp lợi ích của khách hàng xung đột với market integrity, bảo vệ tính toàn vẹn của thị trường là nghĩa vụ chi phối. Không được thực hiện hành vi làm hại thị trường để tăng lợi nhuận khách hàng, kể cả khi khách hàng mong muốn.","trap_vi":"Client first không phải giấy phép vi phạm market integrity."},{"stem_en":"A retired client relies on an adviser to evaluate an illiquid product. The adviser knows the client's technical knowledge is limited and the fees are complex. Which rationale best explains the need for ethical standards?","options":["Clients are guaranteed a positive return under ethical standards.","The client's reliance on the adviser's expertise and stewardship creates a special responsibility.","The adviser has no responsibility because the client signed the agreement."],"correct":1,"why_vi":"Client entrusts wealth and depends on superior knowledge, tạo information asymmetry. Adviser cần care, transparency và independence; không lợi dụng sự phụ thuộc để ưu tiên commissions.","trap_vi":"The central justification is trust and stewardship, not guaranteed returns."},{"stem_en":"Multiple dealers make misleading claims about complex products. Investors lose confidence in the market and reduce participation. What is the most likely broader ethical implication?","options":["Only the immediate dealers' revenues are affected.","Widespread ethical failures can impair capital allocation and investor confidence.","Lower trust necessarily improves market efficiency."],"correct":1,"why_vi":"Nhiều hành vi có vẻ riêng lẻ có thể cộng dồn làm suy yếu market integrity và public trust. Giảm participation có thể cản trở capital allocation và lợi ích kinh tế của xã hội.","trap_vi":"Ethics extends beyond the firm and direct clients."},{"stem_en":"After repeated misleading disclosures, a manager experiences client withdrawals and must hire additional compliance staff. The most direct economic consequences are:","options":["higher revenue and lower expense.","lower revenue and higher expense.","lower revenue with necessarily unchanged expense."],"correct":1,"why_en":"Withdrawals can reduce fee revenue and remediation can raise costs.","why_vi":"Khách rút vốn có thể giảm phí; khắc phục làm tăng chi phí.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 17–20, 25–26, 32–33 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 155–156; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 9","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Economic transmission of lost trust"}],"cards":[{"front_en":"Trust and entrusted assets","back_vi":"Investment management dựa vào niềm tin vì khách hàng giao tài sản và quyết định tài chính quan trọng cho người có kiến thức vượt trội. Khách hàng thường khó đánh giá chất lượng lời khuyên, rủi ro, phí hoặc xung đột; high ethical standards giảm nguy cơ khai thác thông tin bất cân xứng. | Exam trap: Không lý giải nhu cầu đạo đức chỉ bằng quy định nghiêm ngặt."},{"front_en":"Information asymmetry and conflicts","back_vi":"Bên cung cấp dịch vụ biết nhiều hơn về sản phẩm, phí và cách tạo doanh thu. Họ có thể lợi dụng bất cân xứng để bán sản phẩm bất lợi; disclosure rõ ràng, phán đoán độc lập và xử lý xung đột giúp khách hàng quyết định có thông tin. | Exam trap: Việc khách hàng có kiến thức hạn chế không làm giảm trách nhiệm của adviser."},{"front_en":"Market integrity and capital allocation","back_vi":"Niềm tin khuyến khích người tiết kiệm tham gia thị trường; phân tích và giao dịch trung thực hỗ trợ định giá và phân bổ vốn cho hoạt động có giá trị. Khi thiếu niềm tin, người tham gia có thể rút vốn, tăng chi phí giao dịch hoặc đòi bù rủi ro, gây tổn thất cho nền kinh tế. | Exam trap: Ethics có hậu quả ở cấp thị trường, không chỉ từng khách hàng."},{"front_en":"Benefits to firms and the profession","back_vi":"Tính trung thực, chăm sóc và minh bạch giúp duy trì quan hệ khách hàng, giảm nguy cơ khiếu nại, chế tài và mất danh tiếng. Các hành vi lừa dối tại một doanh nghiệp có thể ảnh hưởng niềm tin đối với các doanh nghiệp khác trong ngành. | Exam trap: Lợi ích ngắn hạn từ vi phạm không phải bằng chứng lợi ích bền vững."},{"front_en":"Market integrity and client interests","back_vi":"Curriculum nhấn mạnh trong trường hợp lợi ích của khách hàng xung đột với market integrity, bảo vệ tính toàn vẹn của thị trường là nghĩa vụ chi phối. Không được thực hiện hành vi làm hại thị trường để tăng lợi nhuận khách hàng, kể cả khi khách hàng mong muốn. | Exam trap: Client first không phải giấy phép vi phạm market integrity."},{"front_en":"Trust and capital markets — framework?","back_vi":"Ethical conduct → confidence → participation → effective capital allocation · Minh họa cơ chế high ethical standards hỗ trợ khách hàng và xã hội qua niềm tin và phân bổ vốn. · Quan hệ định tính, không phải công thức dự báo lợi suất hay đảm bảo thị trường luôn hiệu quả."},{"front_en":"Duty priority under conflicting interests — framework?","back_vi":"Market integrity; client interests; employer interests; personal interests · Trong xung đột market integrity và client interest, market integrity chi phối; client interest đặt trước employer và personal interests. Áp dụng luật và standards liên quan trước khi lựa chọn hành động. · Không dùng thứ tự ghi nhớ này thay cho phân tích các điều kiện cụ thể của standards."},{"front_en":"A retired client relies on an adviser to evaluate an illiquid product. The adviser knows the client's technical knowledge is limited and the fees are complex. Which rationale best explains the need for ethical standards?","back_vi":"Clients depend on ethical use of specialized expertise to protect entrusted assets. — Client entrusts wealth and depends on superior knowledge, tạo information asymmetry. Adviser cần care, transparency và independence; không lợi dụng sự phụ thuộc để ưu tiên commissions."},{"front_en":"Multiple dealers make misleading claims about complex products. Investors lose confidence in the market and reduce participation. What is the most likely broader ethical implication?","back_vi":"Misconduct can damage market functioning and the broader economy. — Nhiều hành vi có vẻ riêng lẻ có thể cộng dồn làm suy yếu market integrity và public trust. Giảm participation có thể cản trở capital allocation và lợi ích kinh tế của xã hội."},{"front_en":"Economic transmission of lost trust","back_en":"Clients cannot easily assess the quality of investment advice in advance. Misconduct can lead to client departures, weaker new business, increased monitoring and remediation costs, and reduced confidence in markets. Lower trust may thus affect both revenues and expenses; these are possible effects, not guaranteed magnitudes.","back_vi":"Khách hàng khó đánh giá trước chất lượng tư vấn. Hành vi sai có thể gây mất khách hàng, giảm doanh thu mới, tăng chi phí giám sát/khắc phục và giảm niềm tin thị trường. Do đó mất niềm tin có thể ảnh hưởng cả doanh thu và chi phí; không khẳng định mức tác động cố định.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 17–20, 25–26, 32–33 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 155–156; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 9","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-01-LOS05","letter":"e","title_en":"Professionalism in Investment Management","outcome_en":"explain professionalism in investment management","overview_vi":"Bài 1.e: Professionalism in Investment Management. Học nguyên tắc, phân biệt nghĩa vụ và bẫy, rồi vận dụng vào tình huống tiếng Anh nguyên gốc. Các khung trong phần Công thức là khung định tính, không phải công thức toán. LM2 giới thiệu các sub-standard; hướng dẫn áp dụng chi tiết thuộc LM3. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 17 (LOS); pp. 24–26 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 89","pages":"Physical PDF pp. 156"},{"id":"SAPP CFA Level I 2026 — Ethics slides","pages":"Physical PDF pp. 10"}],"sections":[{"heading":"Investment management as an evolving profession","body":"Investment management còn tương đối trẻ so với y khoa và luật; không phải tất cả người làm trong ngành có credential hoặc là thành viên professional body. Việc mở cửa thị trường, phối hợp quy định và công nghệ làm ngành ngày càng toàn cầu; chuẩn đạo đức cần thích nghi với môi trường thay đổi.","trap":"Không suy ra tất cả practitioners đều bị CFA Institute kỷ luật trực tiếp."},{"heading":"Expertise, care, transparency and integrity","body":"Investment professional có trách nhiệm sử dụng kiến thức về tài chính, công nghệ và quy định với care và judgment; làm rõ fees, risks, conflicts và nghĩa vụ liên quan. Chuyên môn phải kết hợp đạo đức, vì một phân tích kỹ thuật đúng vẫn có thể được dùng sai mục đích.","trap":"Không thay thế ethics bằng technical competence."},{"heading":"Interdependence of firms, regulators and professional bodies","body":"Doanh nghiệp thiết lập quy trình và giám sát, regulator ban hành và thực thi luật, professional body xây dựng chuẩn và hướng dẫn giải quyết khác biệt. Cá nhân vẫn chịu trách nhiệm về hành vi của mình và phải áp dụng yêu cầu nghiêm ngặt hơn khi phù hợp.","trap":"Firm approval không tự động bảo đảm tuân thủ Code and Standards."},{"heading":"CFA Institute — mission and practice analysis","body":"CFA Institute hướng tới chuẩn cao về ethics, education và professional excellence vì lợi ích xã hội. GBIK (Global Body of Investment Knowledge) và CBOK (Candidate Body of Knowledge) được cập nhật thông qua practice analysis với người đang hành nghề, nhằm giữ nội dung nghề nghiệp phù hợp toàn cầu.","trap":"Practice analysis không phải một bài thi đạo đức riêng."},{"heading":"Local societies and professional development","body":"Local CFA societies kết nối thành viên, cung cấp cơ hội học tập, mentoring và tham gia cộng đồng. Thành viên/candidate cần tuân thủ Code and Standards và annual attestation theo yêu cầu chương trình; duy trì năng lực và cố gắng nâng cao năng lực của người khác.","trap":"Không nhầm membership, local society membership và CFA charter là một."},{"heading":"Suitability and fiduciary responsibility are related but distinct","body":"Suitability xét mức phù hợp với hoàn cảnh và giới hạn khách hàng. Fiduciary obligation tập trung hành động vì lợi ích người thụ hưởng với mức cẩn trọng phù hợp. Sản phẩm phù hợp vẫn có thể được đề xuất vì động cơ tư lợi không phù hợp. Cần xét cả tính phù hợp và lòng trung thành; nghĩa vụ pháp lý cụ thể phụ thuộc quan hệ và khu vực.","body_en":"Suitability concerns whether advice or investments fit the relevant client circumstances and constraints. A fiduciary obligation focuses on acting for the beneficiary’s interests with appropriate care. A suitable product can still be recommended for an improper self-serving reason. Evaluate both fit and loyalty; the precise legal fiduciary obligation depends on the relationship and jurisdiction.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 24–26 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 156; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 10","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Professional competence loop","expr":"Assess role → identify skill gaps → learn and apply → review and maintain","meaning":"Năng lực cần phù hợp với vai trò và complexity; cập nhật liên tục, trao đổi chuyên môn, review quyết định.","conditions":"Không đặt ra số giờ CPD cố định ngoài yêu cầu của nguồn hoặc quy định thực sự áp dụng."},{"name":"Institutional roles","expr":"Regulator: applicable law; employer: policies and supervision; professional body: standards and discipline","meaning":"Phân biệt nguồn nghĩa vụ, chủ thể xây dựng rules và chủ thể giám sát; cá nhân vẫn chịu trách nhiệm với conduct của mình.","conditions":"Employer permission không loại bỏ yêu cầu nghiêm ngặt hơn."}],"examples":[{"question_en":"A successful equity analyst is promoted to manage an unfamiliar derivatives portfolio. The employer approves the promotion but provides no training. What response best demonstrates professionalism?","steps_vi":["Credential và employer approval không đảm bảo competence cho nhiệm vụ mới.","Đánh giá skill gaps và bổ sung kiến thức, supervision/support phù hợp trước khi thực hiện nhiệm vụ vượt năng lực."],"answer":"Maintain and develop competence appropriate to the new responsibilities.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A professional body consults practitioners from multiple markets to revise its curriculum following new investment technologies. Which purpose is most directly served?","steps_vi":["Nguồn CFAI mô tả practice analysis cập nhật GBIK/CBOK thông qua tương tác practitioners.","Mục tiêu là kiến thức, skills và ethics phù hợp thực tiễn đang thay đổi, không phải đảm bảo mọi người có cùng view."],"answer":"Maintain a globally relevant body of professional knowledge.","check":"Original conceptual vignette; conclusion limited to stated facts."}],"questions":[{"stem_en":"Which statement best describes investment management as a profession?","options":["All investment employees are automatically CFA Institute members.","Its professional institutions continue to develop and not every practitioner belongs to one.","Its professional requirements are identical in every jurisdiction."],"correct":1,"why_vi":"Investment management còn tương đối trẻ so với y khoa và luật; không phải tất cả người làm trong ngành có credential hoặc là thành viên professional body. Việc mở cửa thị trường, phối hợp quy định và công nghệ làm ngành ngày càng toàn cầu; chuẩn đạo đức cần thích nghi với môi trường thay đổi.","trap_vi":"Không suy ra tất cả practitioners đều bị CFA Institute kỷ luật trực tiếp."},{"stem_en":"An analyst builds an accurate model but knowingly omits a material risk from the recommendation. Professionalism requires:","options":["both technical competence and ethical communication.","only a technically accurate valuation.","only the absence of an explicit legal prohibition."],"correct":0,"why_vi":"Investment professional có trách nhiệm sử dụng kiến thức về tài chính, công nghệ và quy định với care và judgment; làm rõ fees, risks, conflicts và nghĩa vụ liên quan. Chuyên môn phải kết hợp đạo đức, vì một phân tích kỹ thuật đúng vẫn có thể được dùng sai mục đích.","trap_vi":"Không thay thế ethics bằng technical competence."},{"stem_en":"A supervisor approves conduct that conflicts with a stricter applicable professional standard. The member should:","options":["follow the stricter applicable requirement.","assume the employer's approval resolves the conflict.","follow the least restrictive rule to maintain consistency."],"correct":0,"why_vi":"Doanh nghiệp thiết lập quy trình và giám sát, regulator ban hành và thực thi luật, professional body xây dựng chuẩn và hướng dẫn giải quyết khác biệt. Cá nhân vẫn chịu trách nhiệm về hành vi của mình và phải áp dụng yêu cầu nghiêm ngặt hơn khi phù hợp.","trap_vi":"Firm approval không tự động bảo đảm tuân thủ Code and Standards."},{"stem_en":"CFA Institute consults practitioners when updating the candidate body of knowledge. The purpose is primarily to:","options":["remove the need for ethical standards.","guarantee a candidate's employment after passing the exams.","keep professional competencies relevant to current practice."],"correct":2,"why_vi":"CFA Institute hướng tới chuẩn cao về ethics, education và professional excellence vì lợi ích xã hội. GBIK (Global Body of Investment Knowledge) và CBOK (Candidate Body of Knowledge) được cập nhật thông qua practice analysis với người đang hành nghề, nhằm giữ nội dung nghề nghiệp phù hợp toàn cầu.","trap_vi":"Practice analysis không phải một bài thi đạo đức riêng."},{"stem_en":"A charterholder mentors junior colleagues and attends technical education events. These activities most directly support:","options":["a guarantee of superior future returns.","automatic exemption from conduct rules.","ongoing professional competence and engagement."],"correct":2,"why_vi":"Local CFA societies kết nối thành viên, cung cấp cơ hội học tập, mentoring và tham gia cộng đồng. Thành viên/candidate cần tuân thủ Code and Standards và annual attestation theo yêu cầu chương trình; duy trì năng lực và cố gắng nâng cao năng lực của người khác.","trap_vi":"Không nhầm membership, local society membership và CFA charter là một."},{"stem_en":"A successful equity analyst is promoted to manage an unfamiliar derivatives portfolio. The employer approves the promotion but provides no training. What response best demonstrates professionalism?","options":["Rely exclusively on the analyst's prior equity performance.","Assess the competence gap and obtain suitable training or support.","Assume employer approval removes professional responsibility."],"correct":1,"why_vi":"Credential và employer approval không đảm bảo competence cho nhiệm vụ mới. Đánh giá skill gaps và bổ sung kiến thức, supervision/support phù hợp trước khi thực hiện nhiệm vụ vượt năng lực.","trap_vi":"Competence is role-specific and must be maintained."},{"stem_en":"A professional body consults practitioners from multiple markets to revise its curriculum following new investment technologies. Which purpose is most directly served?","options":["Keep the profession's knowledge and competencies current and relevant.","Ensure every practitioner uses identical models.","Eliminate the need for individual professional judgment."],"correct":0,"why_vi":"Nguồn CFAI mô tả practice analysis cập nhật GBIK/CBOK thông qua tương tác practitioners. Mục tiêu là kiến thức, skills và ethics phù hợp thực tiễn đang thay đổi, không phải đảm bảo mọi người có cùng view.","trap_vi":"Practice analysis adapts the body of knowledge to practice."},{"stem_en":"Two products are equally suitable and identical in relevant features except that one is more costly to the client and pays the adviser more. Recommending the costly product solely for the adviser’s benefit illustrates that:","options":["a suitable recommendation always satisfies loyalty.","suitability alone does not establish that the client’s interests were prioritized.","fiduciary care requires selecting the product with the highest adviser compensation."],"correct":1,"why_en":"Suitability and client-first conduct are separate tests.","why_vi":"Tính phù hợp và đặt lợi ích khách hàng lên trước là hai phép kiểm tra khác nhau.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 24–26 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 156; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 10","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Suitability and fiduciary responsibility are related but distinct"}],"cards":[{"front_en":"Investment management as an evolving profession","back_vi":"Investment management còn tương đối trẻ so với y khoa và luật; không phải tất cả người làm trong ngành có credential hoặc là thành viên professional body. Việc mở cửa thị trường, phối hợp quy định và công nghệ làm ngành ngày càng toàn cầu; chuẩn đạo đức cần thích nghi với môi trường thay đổi. | Exam trap: Không suy ra tất cả practitioners đều bị CFA Institute kỷ luật trực tiếp."},{"front_en":"Expertise, care, transparency and integrity","back_vi":"Investment professional có trách nhiệm sử dụng kiến thức về tài chính, công nghệ và quy định với care và judgment; làm rõ fees, risks, conflicts và nghĩa vụ liên quan. Chuyên môn phải kết hợp đạo đức, vì một phân tích kỹ thuật đúng vẫn có thể được dùng sai mục đích. | Exam trap: Không thay thế ethics bằng technical competence."},{"front_en":"Interdependence of firms, regulators and professional bodies","back_vi":"Doanh nghiệp thiết lập quy trình và giám sát, regulator ban hành và thực thi luật, professional body xây dựng chuẩn và hướng dẫn giải quyết khác biệt. Cá nhân vẫn chịu trách nhiệm về hành vi của mình và phải áp dụng yêu cầu nghiêm ngặt hơn khi phù hợp. | Exam trap: Firm approval không tự động bảo đảm tuân thủ Code and Standards."},{"front_en":"CFA Institute — mission and practice analysis","back_vi":"CFA Institute hướng tới chuẩn cao về ethics, education và professional excellence vì lợi ích xã hội. GBIK (Global Body of Investment Knowledge) và CBOK (Candidate Body of Knowledge) được cập nhật thông qua practice analysis với người đang hành nghề, nhằm giữ nội dung nghề nghiệp phù hợp toàn cầu. | Exam trap: Practice analysis không phải một bài thi đạo đức riêng."},{"front_en":"Local societies and professional development","back_vi":"Local CFA societies kết nối thành viên, cung cấp cơ hội học tập, mentoring và tham gia cộng đồng. Thành viên/candidate cần tuân thủ Code and Standards và annual attestation theo yêu cầu chương trình; duy trì năng lực và cố gắng nâng cao năng lực của người khác. | Exam trap: Không nhầm membership, local society membership và CFA charter là một."},{"front_en":"Professional competence loop — framework?","back_vi":"Assess role → identify skill gaps → learn and apply → review and maintain · Năng lực cần phù hợp với vai trò và complexity; cập nhật liên tục, trao đổi chuyên môn, review quyết định. · Không đặt ra số giờ CPD cố định ngoài yêu cầu của nguồn hoặc quy định thực sự áp dụng."},{"front_en":"Institutional roles — framework?","back_vi":"Regulator: applicable law; employer: policies and supervision; professional body: standards and discipline · Phân biệt nguồn nghĩa vụ, chủ thể xây dựng rules và chủ thể giám sát; cá nhân vẫn chịu trách nhiệm với conduct của mình. · Employer permission không loại bỏ yêu cầu nghiêm ngặt hơn."},{"front_en":"A successful equity analyst is promoted to manage an unfamiliar derivatives portfolio. The employer approves the promotion but provides no training. What response best demonstrates professionalism?","back_vi":"Maintain and develop competence appropriate to the new responsibilities. — Credential và employer approval không đảm bảo competence cho nhiệm vụ mới. Đánh giá skill gaps và bổ sung kiến thức, supervision/support phù hợp trước khi thực hiện nhiệm vụ vượt năng lực."},{"front_en":"A professional body consults practitioners from multiple markets to revise its curriculum following new investment technologies. Which purpose is most directly served?","back_vi":"Maintain a globally relevant body of professional knowledge. — Nguồn CFAI mô tả practice analysis cập nhật GBIK/CBOK thông qua tương tác practitioners. Mục tiêu là kiến thức, skills và ethics phù hợp thực tiễn đang thay đổi, không phải đảm bảo mọi người có cùng view."},{"front_en":"Suitability and fiduciary responsibility are related but distinct","back_en":"Suitability concerns whether advice or investments fit the relevant client circumstances and constraints. A fiduciary obligation focuses on acting for the beneficiary’s interests with appropriate care. A suitable product can still be recommended for an improper self-serving reason. Evaluate both fit and loyalty; the precise legal fiduciary obligation depends on the relationship and jurisdiction.","back_vi":"Suitability xét mức phù hợp với hoàn cảnh và giới hạn khách hàng. Fiduciary obligation tập trung hành động vì lợi ích người thụ hưởng với mức cẩn trọng phù hợp. Sản phẩm phù hợp vẫn có thể được đề xuất vì động cơ tư lợi không phù hợp. Cần xét cả tính phù hợp và lòng trung thành; nghĩa vụ pháp lý cụ thể phụ thuộc quan hệ và khu vực.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 24–26 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 156; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 10","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-01-LOS06","letter":"f","title_en":"Challenges to Ethical Conduct","outcome_en":"identify challenges to ethical behavior","overview_vi":"Bài 1.f: Challenges to Ethical Conduct. Học nguyên tắc, phân biệt nghĩa vụ và bẫy, rồi vận dụng vào tình huống tiếng Anh nguyên gốc. Các khung trong phần Công thức là khung định tính, không phải công thức toán. LM2 giới thiệu các sub-standard; hướng dẫn áp dụng chi tiết thuộc LM3. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 17 (LOS); pp. 27–29 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 89","pages":"Physical PDF pp. 156–157"},{"id":"SAPP CFA Level I 2026 — Ethics slides","pages":"Physical PDF pp. 11"}],"sections":[{"heading":"Overconfidence in one's morality","body":"Overconfidence khiến cá nhân đánh giá quá cao khả năng luôn hành xử đúng, dựa nhiều vào tính cách hoặc ý định tốt và xem nhẹ yếu tố tình huống. Tình huống mới hoặc áp lực có thể làm một người vốn trung thực hành động trái chuẩn.","trap":"Ý định tốt không đủ để loại bỏ nguy cơ vi phạm."},{"heading":"Situational influences","body":"Situational influences là yếu tố bên ngoài như môi trường, văn hóa, hành vi đồng nghiệp, quyền lực cấp trên và kỳ vọng xã hội ảnh hưởng suy nghĩ. Chúng có thể khuyến khích hành vi tốt hoặc xấu; mức ảnh hưởng thường bị đánh giá thấp.","trap":"Không coi nhân cách là yếu tố duy nhất quyết định hành vi."},{"heading":"Money, prestige and loyalty","body":"Bonus, promotion, prestige, mong muốn làm hài lòng sếp và loyalty với đồng nghiệp có thể hướng quyết định về lợi ích trước mắt. Loyalty với employer không cho phép bỏ qua trách nhiệm với client hoặc thị trường; cần nhận diện áp lực trước khi đánh giá phương án.","trap":"Không xem mọi bonus là tự động phi đạo đức; vấn đề là ảnh hưởng lên judgment."},{"heading":"Short-term focus","body":"Yếu tố trước mắt dễ nhận diện hơn rủi ro dài hạn, khiến cá nhân giảm trọng số tác động tới khách hàng, uy tín, thị trường và chính sự nghiệp của mình. Cần mở rộng thời hạn đánh giá và xem cả hậu quả gián tiếp.","trap":"Một quyết định có lợi trong quý này có thể gây tổn hại dài hạn."},{"heading":"Bystander effect and conformity","body":"Khi có nhiều người chứng kiến vấn đề, cá nhân có thể chờ người khác can thiệp. Conformity khiến một việc sai dần trở thành bình thường trong nhóm. Nhận diện vai trò bản thân, xin hướng dẫn và hành động theo nghĩa vụ giúp chống hiệu ứng này.","trap":"Không dùng lý do 'ai cũng làm' để biện minh."},{"heading":"Compliance-only culture","body":"Compliance program giúp nhận diện luật và thủ tục nhưng cách tiếp cận check-the-box có thể làm người lao động chỉ hỏi điều gì được phép thay vì điều gì nên làm. Culture of integrity cần phản ánh trong hành vi lãnh đạo, đào tạo, khuyến khích và ra quyết định.","trap":"Hoàn thành checklist không chứng minh quyết định có đạo đức."},{"heading":"Situational pressures versus internal rationalization","body":"Thưởng, danh tiếng và trung thành đồng nghiệp/chủ lao động là áp lực hoàn cảnh; tự tin thái quá vào phán đoán đạo đức và tự biện minh là thách thức bên trong. Văn hóa chỉ thưởng kết quả ngắn hạn làm tăng cả hai. Xét hậu quả dài hạn, tìm hướng dẫn độc lập, không coi sự trung thực cá nhân là miễn nhiễm áp lực.","body_en":"Incentives, prestige and loyalty to colleagues or an employer are environmental pressures; overconfidence in one’s ethical judgment and rationalization are internal challenges. A culture that rewards only near-term results can amplify both. Consider long-run consequences, seek independent guidance and avoid assuming that personal honesty makes one immune to pressure.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 27–29 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 156–157; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 11","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Three key ethical challenges","expr":"Overconfidence in own morality; underestimation of situational influences; short-term focus","meaning":"Nhận diện đánh giá quá cao đạo đức cá nhân, đánh giá thấp áp lực tình huống và ưu tiên kết quả tức thời.","conditions":"Có thể xuất hiện đồng thời trong một vignette; xem câu hỏi đang hỏi yếu tố nào."},{"name":"Pressure review","expr":"Identify incentives → recognize affected judgment → seek independent guidance → assess longer-term effects","meaning":"Cách vận dụng framework vào tiền thưởng, prestige, loyalty và conformity; nhận diện cả áp lực thuận lợi và bất lợi.","conditions":"Không phải mọi incentive đều sai; phải xem hành vi, conflict và safeguards."}],"examples":[{"question_en":"A sales team adopts an aggressive practice after observing its most respected managers use it. An employee says, 'I am a good person, so I need not review the ethics of the practice.' What challenges are present?","steps_vi":["Hành vi cấp trên và team norms là situational influences; tự đánh giá đạo đức cao là overconfidence.","Cần tìm guidance độc lập, cân nhắc stakeholder harm và tránh lấy conformity làm justification."],"answer":"Overconfidence in personal morality and underestimation of situational influences.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A portfolio manager's bonus depends on this quarter's returns. A new position increases short-run expected performance but creates a hidden longer-term client risk. Which analysis would most improve ethical judgment?","steps_vi":["Nhận diện bonus incentive và time horizon quá ngắn; không mặc định bonus tự động là vi phạm.","Đánh giá tác động dài hạn, risk disclosure, phù hợp mandate và xin independent guidance nếu cần."],"answer":"Consider long-term consequences and the effect of compensation pressure.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A firm rewards employees solely for completing compliance checklists. Employees avoid examining whether technically permitted communications are misleading. What is the main weakness?","steps_vi":["Compliance là nền tảng hữu ích nhưng không đủ; culture có thể thúc đẩy check-the-box.","Đào tạo framework, leadership example và incentives hỗ trợ judgment sẽ giải quyết phần bị bỏ qua."],"answer":"The firm emphasizes legal or procedural permission rather than ethical reasoning.","check":"Original conceptual vignette; conclusion limited to stated facts."}],"questions":[{"stem_en":"A manager declines ethics review because she believes she is more honest than most colleagues. Her reasoning most likely reflects:","options":["effective identification of conflicts.","overconfidence in her own morality.","a complete ethical decision-making process."],"correct":1,"why_vi":"Overconfidence khiến cá nhân đánh giá quá cao khả năng luôn hành xử đúng, dựa nhiều vào tính cách hoặc ý định tốt và xem nhẹ yếu tố tình huống. Tình huống mới hoặc áp lực có thể làm một người vốn trung thực hành động trái chuẩn.","trap_vi":"Ý định tốt không đủ để loại bỏ nguy cơ vi phạm."},{"stem_en":"A normally careful employee starts accepting questionable practices after joining a team where everyone does so. The most relevant challenge is:","options":["lack of technical knowledge about every product.","underestimating situational influences.","a change in statutory reporting requirements."],"correct":1,"why_vi":"Situational influences là yếu tố bên ngoài như môi trường, văn hóa, hành vi đồng nghiệp, quyền lực cấp trên và kỳ vọng xã hội ảnh hưởng suy nghĩ. Chúng có thể khuyến khích hành vi tốt hoặc xấu; mức ảnh hưởng thường bị đánh giá thấp.","trap_vi":"Không coi nhân cách là yếu tố duy nhất quyết định hành vi."},{"stem_en":"An analyst suppresses a negative finding to preserve a promotion promised by a supervisor. The strongest situational influence is:","options":["career incentives and loyalty pressure.","the need for continuing education alone.","a decline in the market value of the analyst's own portfolio."],"correct":0,"why_vi":"Bonus, promotion, prestige, mong muốn làm hài lòng sếp và loyalty với đồng nghiệp có thể hướng quyết định về lợi ích trước mắt. Loyalty với employer không cho phép bỏ qua trách nhiệm với client hoặc thị trường; cần nhận diện áp lực trước khi đánh giá phương án.","trap_vi":"Không xem mọi bonus là tự động phi đạo đức; vấn đề là ảnh hưởng lên judgment."},{"stem_en":"A sales team evaluates a product only by this month's commission and ignores likely future client losses. The team is most clearly exhibiting:","options":["an excessively short-term decision focus.","independent consideration of all stakeholder duties.","effective professional self-regulation."],"correct":0,"why_vi":"Yếu tố trước mắt dễ nhận diện hơn rủi ro dài hạn, khiến cá nhân giảm trọng số tác động tới khách hàng, uy tín, thị trường và chính sự nghiệp của mình. Cần mở rộng thời hạn đánh giá và xem cả hậu quả gián tiếp.","trap_vi":"Một quyết định có lợi trong quý này có thể gây tổn hại dài hạn."},{"stem_en":"Several employees notice a misleading brochure, but each assumes someone else will raise the issue. The situation best illustrates:","options":["effective delegation with confirmed accountability.","the bystander effect.","a conflict eliminated by public disclosure."],"correct":1,"why_vi":"Khi có nhiều người chứng kiến vấn đề, cá nhân có thể chờ người khác can thiệp. Conformity khiến một việc sai dần trở thành bình thường trong nhóm. Nhận diện vai trò bản thân, xin hướng dẫn và hành động theo nghĩa vụ giúp chống hiệu ứng này.","trap_vi":"Không dùng lý do 'ai cũng làm' để biện minh."},{"stem_en":"A team marks every compliance box but never evaluates whether its communication is misleading. The most appropriate criticism is:","options":["rule-based compliance alone may miss ethical implications.","compliance procedures should be abandoned.","the team is necessarily ethical if no box was missed."],"correct":0,"why_vi":"Compliance program giúp nhận diện luật và thủ tục nhưng cách tiếp cận check-the-box có thể làm người lao động chỉ hỏi điều gì được phép thay vì điều gì nên làm. Culture of integrity cần phản ánh trong hành vi lãnh đạo, đào tạo, khuyến khích và ra quyết định.","trap_vi":"Hoàn thành checklist không chứng minh quyết định có đạo đức."},{"stem_en":"A sales team adopts an aggressive practice after observing its most respected managers use it. An employee says, 'I am a good person, so I need not review the ethics of the practice.' What challenges are present?","options":["Both overconfidence in one's morality and underestimation of situational influences.","Only a lack of mathematical expertise.","Only the absence of a written law."],"correct":0,"why_vi":"Hành vi cấp trên và team norms là situational influences; tự đánh giá đạo đức cao là overconfidence. Cần tìm guidance độc lập, cân nhắc stakeholder harm và tránh lấy conformity làm justification.","trap_vi":"Several behavioral challenges can coexist."},{"stem_en":"A portfolio manager's bonus depends on this quarter's returns. A new position increases short-run expected performance but creates a hidden longer-term client risk. Which analysis would most improve ethical judgment?","options":["Judge the decision solely by whether the quarter's return exceeds its target.","Evaluate longer-term client consequences and the influence of the bonus.","Disregard all compensation arrangements as inherently unethical."],"correct":1,"why_vi":"Nhận diện bonus incentive và time horizon quá ngắn; không mặc định bonus tự động là vi phạm. Đánh giá tác động dài hạn, risk disclosure, phù hợp mandate và xin independent guidance nếu cần.","trap_vi":"Short-term focus can crowd out longer-term duties."},{"stem_en":"A firm rewards employees solely for completing compliance checklists. Employees avoid examining whether technically permitted communications are misleading. What is the main weakness?","options":["The firm should eliminate its compliance program.","The firm has established that all employee conduct is ethical.","Compliance-only culture may overlook duties and stakeholder consequences."],"correct":2,"why_vi":"Compliance là nền tảng hữu ích nhưng không đủ; culture có thể thúc đẩy check-the-box. Đào tạo framework, leadership example và incentives hỗ trợ judgment sẽ giải quyết phần bị bỏ qua.","trap_vi":"Rule adherence is necessary where applicable but not sufficient for ethics."},{"stem_en":"An analyst believes that, unlike coworkers, she is too ethical to be influenced by a large bonus. Which combination is present?","options":["Only an external pressure.","Only an internal challenge.","An external incentive and internal overconfidence."],"correct":2,"why_en":"Bonus is an external influence; belief in superior immunity is an internal bias.","why_vi":"Thưởng là áp lực bên ngoài; tin mình miễn nhiễm là thiên kiến bên trong.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 27–29 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 156–157; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 11","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Situational pressures versus internal rationalization"},{"stem_en":"A firm wishes to reduce ethical lapses caused by short-term sales incentives. Which response is most directly aligned with the curriculum’s reasoning?","options":["Consider longer-term stakeholder outcomes when assessing decisions.","Assume all employees have identical moral judgment.","Replace all judgment with a checklist covering only statutory minimums."],"correct":0,"why_en":"Longer-term consequences help counter short-term situational pressure.","why_vi":"Xét hậu quả dài hạn giúp giảm áp lực ngắn hạn.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 27–29 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 156–157; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 11","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Situational pressures versus internal rationalization"}],"cards":[{"front_en":"Overconfidence in one's morality","back_vi":"Overconfidence khiến cá nhân đánh giá quá cao khả năng luôn hành xử đúng, dựa nhiều vào tính cách hoặc ý định tốt và xem nhẹ yếu tố tình huống. Tình huống mới hoặc áp lực có thể làm một người vốn trung thực hành động trái chuẩn. | Exam trap: Ý định tốt không đủ để loại bỏ nguy cơ vi phạm."},{"front_en":"Situational influences","back_vi":"Situational influences là yếu tố bên ngoài như môi trường, văn hóa, hành vi đồng nghiệp, quyền lực cấp trên và kỳ vọng xã hội ảnh hưởng suy nghĩ. Chúng có thể khuyến khích hành vi tốt hoặc xấu; mức ảnh hưởng thường bị đánh giá thấp. | Exam trap: Không coi nhân cách là yếu tố duy nhất quyết định hành vi."},{"front_en":"Money, prestige and loyalty","back_vi":"Bonus, promotion, prestige, mong muốn làm hài lòng sếp và loyalty với đồng nghiệp có thể hướng quyết định về lợi ích trước mắt. Loyalty với employer không cho phép bỏ qua trách nhiệm với client hoặc thị trường; cần nhận diện áp lực trước khi đánh giá phương án. | Exam trap: Không xem mọi bonus là tự động phi đạo đức; vấn đề là ảnh hưởng lên judgment."},{"front_en":"Short-term focus","back_vi":"Yếu tố trước mắt dễ nhận diện hơn rủi ro dài hạn, khiến cá nhân giảm trọng số tác động tới khách hàng, uy tín, thị trường và chính sự nghiệp của mình. Cần mở rộng thời hạn đánh giá và xem cả hậu quả gián tiếp. | Exam trap: Một quyết định có lợi trong quý này có thể gây tổn hại dài hạn."},{"front_en":"Bystander effect and conformity","back_vi":"Khi có nhiều người chứng kiến vấn đề, cá nhân có thể chờ người khác can thiệp. Conformity khiến một việc sai dần trở thành bình thường trong nhóm. Nhận diện vai trò bản thân, xin hướng dẫn và hành động theo nghĩa vụ giúp chống hiệu ứng này. | Exam trap: Không dùng lý do 'ai cũng làm' để biện minh."},{"front_en":"Compliance-only culture","back_vi":"Compliance program giúp nhận diện luật và thủ tục nhưng cách tiếp cận check-the-box có thể làm người lao động chỉ hỏi điều gì được phép thay vì điều gì nên làm. Culture of integrity cần phản ánh trong hành vi lãnh đạo, đào tạo, khuyến khích và ra quyết định. | Exam trap: Hoàn thành checklist không chứng minh quyết định có đạo đức."},{"front_en":"Three key ethical challenges — framework?","back_vi":"Overconfidence in own morality; underestimation of situational influences; short-term focus · Nhận diện đánh giá quá cao đạo đức cá nhân, đánh giá thấp áp lực tình huống và ưu tiên kết quả tức thời. · Có thể xuất hiện đồng thời trong một vignette; xem câu hỏi đang hỏi yếu tố nào."},{"front_en":"Pressure review — framework?","back_vi":"Identify incentives → recognize affected judgment → seek independent guidance → assess longer-term effects · Cách vận dụng framework vào tiền thưởng, prestige, loyalty và conformity; nhận diện cả áp lực thuận lợi và bất lợi. · Không phải mọi incentive đều sai; phải xem hành vi, conflict và safeguards."},{"front_en":"A sales team adopts an aggressive practice after observing its most respected managers use it. An employee says, 'I am a good person, so I need not review the ethics of the practice.' What challenges are present?","back_vi":"Overconfidence in personal morality and underestimation of situational influences. — Hành vi cấp trên và team norms là situational influences; tự đánh giá đạo đức cao là overconfidence. Cần tìm guidance độc lập, cân nhắc stakeholder harm và tránh lấy conformity làm justification."},{"front_en":"A portfolio manager's bonus depends on this quarter's returns. A new position increases short-run expected performance but creates a hidden longer-term client risk. Which analysis would most improve ethical judgment?","back_vi":"Consider long-term consequences and the effect of compensation pressure. — Nhận diện bonus incentive và time horizon quá ngắn; không mặc định bonus tự động là vi phạm. Đánh giá tác động dài hạn, risk disclosure, phù hợp mandate và xin independent guidance nếu cần."},{"front_en":"A firm rewards employees solely for completing compliance checklists. Employees avoid examining whether technically permitted communications are misleading. What is the main weakness?","back_vi":"The firm emphasizes legal or procedural permission rather than ethical reasoning. — Compliance là nền tảng hữu ích nhưng không đủ; culture có thể thúc đẩy check-the-box. Đào tạo framework, leadership example và incentives hỗ trợ judgment sẽ giải quyết phần bị bỏ qua."},{"front_en":"Situational pressures versus internal rationalization","back_en":"Incentives, prestige and loyalty to colleagues or an employer are environmental pressures; overconfidence in one’s ethical judgment and rationalization are internal challenges. A culture that rewards only near-term results can amplify both. Consider long-run consequences, seek independent guidance and avoid assuming that personal honesty makes one immune to pressure.","back_vi":"Thưởng, danh tiếng và trung thành đồng nghiệp/chủ lao động là áp lực hoàn cảnh; tự tin thái quá vào phán đoán đạo đức và tự biện minh là thách thức bên trong. Văn hóa chỉ thưởng kết quả ngắn hạn làm tăng cả hai. Xét hậu quả dài hạn, tìm hướng dẫn độc lập, không coi sự trung thực cá nhân là miễn nhiễm áp lực.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 27–29 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 156–157; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 11","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-01-LOS07","letter":"g","title_en":"Ethical versus Legal Standards","outcome_en":"compare and contrast ethical and legal standards","overview_vi":"Bài 1.g: Ethical versus Legal Standards. Học nguyên tắc, phân biệt nghĩa vụ và bẫy, rồi vận dụng vào tình huống tiếng Anh nguyên gốc. Các khung trong phần Công thức là khung định tính, không phải công thức toán. LM2 giới thiệu các sub-standard; hướng dẫn áp dụng chi tiết thuộc LM3. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 17 (LOS); pp. 30–32 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 89","pages":"Physical PDF pp. 157"},{"id":"SAPP CFA Level I 2026 — Ethics slides","pages":"Physical PDF pp. 12"},{"id":"CFAI 2026 Volume 10 — selected supporting Guidance (LM3; not full coverage)","pages":"Physical PDF pp. 67–76 (I(A)), 109–125 (II)"}],"sections":[{"heading":"Overlap between legal and ethical standards","body":"Pháp luật thường cụ thể hóa những hành vi đạo đức được chia sẻ trong xã hội, ví dụ yêu cầu cung cấp thông tin rủi ro trung thực. Nhưng legal và ethical không đồng nhất: một hành vi có thể đáp ứng cả hai, chỉ một trong hai hoặc không đáp ứng cả hai.","trap":"Không suy ra legal luôn ethical hoặc ethical luôn legal."},{"heading":"Legal minimum and higher ethical expectations","body":"Legal standards thường dựa vào quy tắc có thẩm quyền ban hành; ethical conduct còn xét quyền lợi và hậu quả đối với người khác. Pháp luật có thể phản ứng chậm trước sản phẩm mới hoặc hành vi mới; professional standards có thể nghiêm ngặt hơn luật địa phương.","trap":"Khi có standard nghiêm hơn phải tuân thủ standard áp dụng nghiêm hơn, không phải luật yếu hơn."},{"heading":"Ethical disagreement and law","body":"Stakeholders có thể có quan điểm đạo đức khác nhau; một số hoạt động được một nhóm xem là đạo đức có thể bị cấm ở nơi khác. Sự khác biệt không cấp quyền cho CFA member vi phạm luật đang áp dụng; cần xác định các nghĩa vụ và yêu cầu nghiêm ngặt hơn.","trap":"Ví dụ xã hội về civil disobedience trong Curriculum không phải ngoại lệ cho Standard I(A)."},{"heading":"Compliance and enforcement","body":"Tuân thủ luật giảm rủi ro kiện tụng, điều tra, chế tài và mất danh tiếng; nhưng khi không có chế tài rõ ràng, nguyên tắc đạo đức vẫn hướng dẫn phán đoán. Quy định nghề nghiệp có thể kỷ luật một hành vi dù không có phán quyết hình sự.","trap":"Không đòi có bản án mới được đánh giá ethics."},{"heading":"Legal permission does not establish ethical acceptability","body":"Luật và kỳ vọng đạo đức giao nhau nhưng không đồng nhất. Hành vi hợp pháp vẫn có thể vi phạm chuẩn mực nghề. Ngược lại, phản đối đạo đức đối với luật không tự cho phép thành viên vi phạm luật áp dụng. Khi áp dụng Code and Standards, xét nghĩa vụ liên quan, kể cả yêu cầu nghiêm ngặt hơn theo I(A), không đồng nhất hợp pháp với đạo đức.","body_en":"Law and ethical expectations overlap, but are not identical. A legally permitted action may still breach professional standards. Conversely, moral objections to a law do not by themselves authorize a member to violate applicable law. In applying the Code and Standards, analyze applicable obligations, including the stricter relevant requirement under I(A), rather than equating legality with ethics.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 30–32 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 157; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 12","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Legal–ethical comparison","expr":"Both legal and ethical; legal but unethical; illegal but considered ethical; neither","meaning":"Hai hệ chuẩn có vùng giao và vùng khác biệt. Pháp luật thường phản ánh một phần kỳ vọng đạo đức; ethics xem xét thêm hậu quả và nghĩa vụ.","conditions":"Mô tả phân loại xã hội không phải quyền vi phạm luật áp dụng cho CFA members/candidates."},{"name":"Applicable requirements","expr":"Identify applicable law and professional standards → follow the stricter requirement","meaning":"Nếu nhiều yêu cầu áp dụng khác nhau, ưu tiên yêu cầu nghiêm hơn; xác định đúng jurisdiction và phạm vi trước.","conditions":"Chi tiết các tình huống xuyên biên giới sẽ triển khai tại LM3 I(A)."}],"examples":[{"question_en":"A jurisdiction has not yet created a rule for a new product. A professional standard already requires disclosure of the product's significant risks. What should a member do?","steps_vi":["Luật chưa quy định chi tiết không xóa yêu cầu professional standard đang áp dụng.","Cần disclose significant risks theo yêu cầu và xem xét các luật khác áp dụng."],"answer":"Follow the applicable professional standard even in the absence of a product-specific statute.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"An employee asserts that a company policy permitting a practice conclusively establishes that the practice is ethical. Which response is best?","steps_vi":["Policy nội bộ không tự động phản ánh toàn bộ applicable law, professional standards và ethical obligations.","Xác định yêu cầu liên quan và hậu quả cho stakeholders; áp dụng yêu cầu nghiêm hơn."],"answer":"Employer permission is not conclusive evidence of ethical conduct.","check":"Original conceptual vignette; conclusion limited to stated facts."}],"questions":[{"stem_en":"A local statute allows a disclosure format that conceals a material cost from most readers. Which conclusion is most appropriate?","options":["The disclosure is necessarily ethical because it satisfies the statute.","Legal permission does not by itself establish ethical conduct.","The disclosure is necessarily illegal because it may be unethical."],"correct":1,"why_vi":"Pháp luật thường cụ thể hóa những hành vi đạo đức được chia sẻ trong xã hội, ví dụ yêu cầu cung cấp thông tin rủi ro trung thực. Nhưng legal và ethical không đồng nhất: một hành vi có thể đáp ứng cả hai, chỉ một trong hai hoặc không đáp ứng cả hai.","trap_vi":"Không suy ra legal luôn ethical hoặc ethical luôn legal."},{"stem_en":"An emerging product is not covered by a specific local regulation, but selling it without discussing major risks would harm clients. The adviser should:","options":["assume there is no duty until a product-specific law is enacted.","assess and meet applicable ethical duties despite the regulatory gap.","treat the lack of regulation as proof of suitability."],"correct":1,"why_vi":"Legal standards thường dựa vào quy tắc có thẩm quyền ban hành; ethical conduct còn xét quyền lợi và hậu quả đối với người khác. Pháp luật có thể phản ứng chậm trước sản phẩm mới hoặc hành vi mới; professional standards có thể nghiêm ngặt hơn luật địa phương.","trap_vi":"Khi có standard nghiêm hơn phải tuân thủ standard áp dụng nghiêm hơn, không phải luật yếu hơn."},{"stem_en":"A member considers an applicable licensing law unwise. Under the Code and Standards, the member should:","options":["comply with applicable requirements while seeking lawful change if desired.","ignore the law based on personal ethical disagreement.","comply only if every colleague considers the law ethical."],"correct":0,"why_vi":"Stakeholders có thể có quan điểm đạo đức khác nhau; một số hoạt động được một nhóm xem là đạo đức có thể bị cấm ở nơi khác. Sự khác biệt không cấp quyền cho CFA member vi phạm luật đang áp dụng; cần xác định các nghĩa vụ và yêu cầu nghiêm ngặt hơn.","trap_vi":"Ví dụ xã hội về civil disobedience trong Curriculum không phải ngoại lệ cho Standard I(A)."},{"stem_en":"A regulator takes no action on a misleading professional communication, but the professional body investigates. This is consistent with:","options":["distinct legal and professional conduct frameworks.","a requirement that professional investigations await criminal convictions.","a prohibition on standards that exceed legal minimums."],"correct":0,"why_vi":"Tuân thủ luật giảm rủi ro kiện tụng, điều tra, chế tài và mất danh tiếng; nhưng khi không có chế tài rõ ràng, nguyên tắc đạo đức vẫn hướng dẫn phán đoán. Quy định nghề nghiệp có thể kỷ luật một hành vi dù không có phán quyết hình sự.","trap_vi":"Không đòi có bản án mới được đánh giá ethics."},{"stem_en":"A jurisdiction has not yet created a rule for a new product. A professional standard already requires disclosure of the product's significant risks. What should a member do?","options":["Omit the risks until a local regulator issues a product rule.","Treat silence in local law as a prohibition on disclosure.","Disclose significant risks as required by the professional standard."],"correct":2,"why_vi":"Luật chưa quy định chi tiết không xóa yêu cầu professional standard đang áp dụng. Cần disclose significant risks theo yêu cầu và xem xét các luật khác áp dụng.","trap_vi":"An ethical or professional standard may exceed legal minimums."},{"stem_en":"An employee asserts that a company policy permitting a practice conclusively establishes that the practice is ethical. Which response is best?","options":["Evaluate applicable duties and ethical consequences independently of employer permission.","Accept the practice as ethical whenever a supervisor approves.","Reject every company policy as ethically irrelevant."],"correct":0,"why_vi":"Policy nội bộ không tự động phản ánh toàn bộ applicable law, professional standards và ethical obligations. Xác định yêu cầu liên quan và hậu quả cho stakeholders; áp dụng yêu cầu nghiêm hơn.","trap_vi":"Employer approval does not replace individual judgment."},{"stem_en":"A jurisdiction permits a practice that is prohibited by an applicable CFA professional standard. A member’s argument that legality alone establishes compliance is:","options":["incorrect, because applicable professional obligations must also be considered.","correct whenever the employer approves.","correct whenever no client complains."],"correct":0,"why_en":"Legal permission does not remove a stricter applicable professional obligation.","why_vi":"Luật cho phép không loại bỏ nghĩa vụ nghề nghiêm ngặt hơn.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 30–32 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 157; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 12","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Legal permission does not establish ethical acceptability"}],"cards":[{"front_en":"Overlap between legal and ethical standards","back_vi":"Pháp luật thường cụ thể hóa những hành vi đạo đức được chia sẻ trong xã hội, ví dụ yêu cầu cung cấp thông tin rủi ro trung thực. Nhưng legal và ethical không đồng nhất: một hành vi có thể đáp ứng cả hai, chỉ một trong hai hoặc không đáp ứng cả hai. | Exam trap: Không suy ra legal luôn ethical hoặc ethical luôn legal."},{"front_en":"Legal minimum and higher ethical expectations","back_vi":"Legal standards thường dựa vào quy tắc có thẩm quyền ban hành; ethical conduct còn xét quyền lợi và hậu quả đối với người khác. Pháp luật có thể phản ứng chậm trước sản phẩm mới hoặc hành vi mới; professional standards có thể nghiêm ngặt hơn luật địa phương. | Exam trap: Khi có standard nghiêm hơn phải tuân thủ standard áp dụng nghiêm hơn, không phải luật yếu hơn."},{"front_en":"Ethical disagreement and law","back_vi":"Stakeholders có thể có quan điểm đạo đức khác nhau; một số hoạt động được một nhóm xem là đạo đức có thể bị cấm ở nơi khác. Sự khác biệt không cấp quyền cho CFA member vi phạm luật đang áp dụng; cần xác định các nghĩa vụ và yêu cầu nghiêm ngặt hơn. | Exam trap: Ví dụ xã hội về civil disobedience trong Curriculum không phải ngoại lệ cho Standard I(A)."},{"front_en":"Compliance and enforcement","back_vi":"Tuân thủ luật giảm rủi ro kiện tụng, điều tra, chế tài và mất danh tiếng; nhưng khi không có chế tài rõ ràng, nguyên tắc đạo đức vẫn hướng dẫn phán đoán. Quy định nghề nghiệp có thể kỷ luật một hành vi dù không có phán quyết hình sự. | Exam trap: Không đòi có bản án mới được đánh giá ethics."},{"front_en":"Legal–ethical comparison — framework?","back_vi":"Both legal and ethical; legal but unethical; illegal but considered ethical; neither · Hai hệ chuẩn có vùng giao và vùng khác biệt. Pháp luật thường phản ánh một phần kỳ vọng đạo đức; ethics xem xét thêm hậu quả và nghĩa vụ. · Mô tả phân loại xã hội không phải quyền vi phạm luật áp dụng cho CFA members/candidates."},{"front_en":"Applicable requirements — framework?","back_vi":"Identify applicable law and professional standards → follow the stricter requirement · Nếu nhiều yêu cầu áp dụng khác nhau, ưu tiên yêu cầu nghiêm hơn; xác định đúng jurisdiction và phạm vi trước. · Chi tiết các tình huống xuyên biên giới sẽ triển khai tại LM3 I(A)."},{"front_en":"A jurisdiction has not yet created a rule for a new product. A professional standard already requires disclosure of the product's significant risks. What should a member do?","back_vi":"Follow the applicable professional standard even in the absence of a product-specific statute. — Luật chưa quy định chi tiết không xóa yêu cầu professional standard đang áp dụng. Cần disclose significant risks theo yêu cầu và xem xét các luật khác áp dụng."},{"front_en":"An employee asserts that a company policy permitting a practice conclusively establishes that the practice is ethical. Which response is best?","back_vi":"Employer permission is not conclusive evidence of ethical conduct. — Policy nội bộ không tự động phản ánh toàn bộ applicable law, professional standards và ethical obligations. Xác định yêu cầu liên quan và hậu quả cho stakeholders; áp dụng yêu cầu nghiêm hơn."},{"front_en":"Legal permission does not establish ethical acceptability","back_en":"Law and ethical expectations overlap, but are not identical. A legally permitted action may still breach professional standards. Conversely, moral objections to a law do not by themselves authorize a member to violate applicable law. In applying the Code and Standards, analyze applicable obligations, including the stricter relevant requirement under I(A), rather than equating legality with ethics.","back_vi":"Luật và kỳ vọng đạo đức giao nhau nhưng không đồng nhất. Hành vi hợp pháp vẫn có thể vi phạm chuẩn mực nghề. Ngược lại, phản đối đạo đức đối với luật không tự cho phép thành viên vi phạm luật áp dụng. Khi áp dụng Code and Standards, xét nghĩa vụ liên quan, kể cả yêu cầu nghiêm ngặt hơn theo I(A), không đồng nhất hợp pháp với đạo đức.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 30–32 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 157; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 12","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-01-LOS08","letter":"h","title_en":"Ethical Decision-Making Framework","outcome_en":"describe a framework for ethical decision making","overview_vi":"Bài 1.h: Ethical Decision-Making Framework. Học nguyên tắc, phân biệt nghĩa vụ và bẫy, rồi vận dụng vào tình huống tiếng Anh nguyên gốc. Các khung trong phần Công thức là khung định tính, không phải công thức toán. LM2 giới thiệu các sub-standard; hướng dẫn áp dụng chi tiết thuộc LM3. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 17 (LOS); pp. 32–42 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 89","pages":"Physical PDF pp. 157–160"},{"id":"SAPP CFA Level I 2026 — Ethics slides","pages":"Physical PDF pp. 13–14"}],"sections":[{"heading":"Framework purpose and multiple perspectives","body":"Ethical decision-making framework bổ sung phân tích kinh tế bằng việc xem xét facts, stakeholders, duties, conflicts và hậu quả ngắn/dài hạn. Quy trình giúp nhận diện vấn đề bị bỏ qua, chọn phương án giảm hại và giải thích rationale cho người liên quan.","trap":"Framework không phải thuật toán luôn sinh ra một đáp án hoàn hảo."},{"heading":"Identify — facts, duties, principles and conflicts","body":"Bước Identify xác định facts đã biết và thông tin còn thiếu, phân biệt fact với opinion, liệt kê stakeholders và nghĩa vụ, nguyên tắc/luật liên quan, xung đột lợi ích hoặc xung đột giữa các nghĩa vụ. Chưa quyết định trước khi hiểu đúng hoàn cảnh.","trap":"Không đánh đồng lời đồn với facts hoặc nhảy thẳng sang quyết định."},{"heading":"Consider — influences, guidance, alternatives","body":"Bước Consider xem xét áp lực tình huống và bias cá nhân; tìm thêm hướng dẫn từ policies, Code and Standards, compliance, mentor hoặc legal counsel phù hợp, đặc biệt người không chịu cùng áp lực; phát triển và đánh giá các lựa chọn. Vẫn phải bảo vệ thông tin bí mật khi xin tư vấn.","trap":"Xin lời khuyên không chuyển toàn bộ trách nhiệm sang người tư vấn."},{"heading":"Decide and act","body":"Chọn phương án phù hợp nghĩa vụ và giảm thiểu hậu quả bất lợi dựa trên phân tích; sau đó thực hiện chứ không chỉ nhận ra vấn đề. Nếu thông tin thiếu, có thể trì hoãn hành động rủi ro và quay lại các bước trước để thu thập dữ liệu cần thiết.","trap":"Không coi 'chưa biết đủ' là lý do thực hiện ngay phương án có lợi cá nhân."},{"heading":"Reflect — evaluate and learn","body":"Sau hành động, đánh giá kết quả so với dự kiến, nguyên nhân khác biệt và liệu đã xác định đủ facts, stakeholders, conflicts, influences, guidance và alternatives. Có thể phải phản tư nhiều lần khi tác động dài hạn xuất hiện, từ đó cải thiện quyết định và quy trình sau này.","trap":"Reflection không chỉ xảy ra khi quyết định có kết quả xấu."},{"heading":"Iterative rather than rigid process","body":"Framework có bốn giai đoạn nhưng mang tính iterative: khi dữ liệu mới xuất hiện, người quyết định có thể quay lại Identify/Consider; đôi khi không có phương án hoàn toàn thỏa mãn mọi người, cần chọn cách tốt nhất theo nghĩa vụ và bối cảnh.","trap":"Không bắt buộc hoàn thành mỗi bước đúng một lần."},{"heading":"Decision framework: iterate when material facts are missing","body":"Xác định dữ kiện, bên chịu ảnh hưởng, nghĩa vụ và xung đột; cân nhắc áp lực, hướng dẫn và phương án; quyết định/hành động; rồi phản tư. Thiếu dữ kiện quan trọng thì quay lại xác định hoặc tìm hướng dẫn phù hợp. Reflection cải thiện quyết định sau, không xóa vi phạm đã xảy ra.","body_en":"Identify facts, affected parties, duties and conflicts; consider pressures, advice and alternatives; decide and act; then reflect on the outcome. If important facts are missing, return to identification or seek qualified guidance. Reflection improves future decisions; it cannot undo an existing violation merely by recognizing it.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 32–42 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 157–160; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 13–14","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Ethical decision-making framework","expr":"Identify → Consider → Decide and act → Reflect","meaning":"Identify: facts, stakeholders/duties, ethical principles, conflicts. Consider: situational influences, guidance, alternatives. Decide/act: lựa chọn và thực hiện. Reflect: đánh giá kết quả.","conditions":"Quy trình iterative, quay lại bước trước khi thông tin mới xuất hiện."},{"name":"Identify checklist","expr":"Known facts / missing facts / facts vs opinion / stakeholders / duties / applicable requirements / conflicts","meaning":"Bảng kiểm trước khi ra quyết định; tách assumption, pressure và information.","conditions":"Không bỏ qua stakeholder gián tiếp hay nghĩa vụ thị trường."},{"name":"Consider checklist","expr":"Situational influences / biases / independent guidance / feasible alternatives / consequences","meaning":"Tìm nguồn tư vấn phù hợp, tránh người chịu cùng áp lực; đánh giá lựa chọn, consequences và tính phù hợp với các yêu cầu áp dụng.","conditions":"Khi hỏi ngoài công ty phải bảo vệ confidential information."},{"name":"Reflect checklist","expr":"Expected outcome vs actual outcome → causes → omitted information or influences → lessons","meaning":"Kiểm tra kết quả theo thời gian và rút kinh nghiệm để cải thiện quy trình.","conditions":"Không dùng hindsight để giả định mọi thông tin sau này đã biết từ trước."}],"examples":[{"question_en":"An analyst is asked to send confidential draft research to an external friend for advice. The analyst has not established permission to share the material. How should the analyst apply the framework?","steps_vi":["Identify: facts, confidentiality, external contact, duties, possible pressure muốn hoàn thành nhanh; còn thiếu permission.","Consider: kiểm tra firm policy, consult authorized compliance/colleagues, tìm alternative không tiết lộ confidential information; decide sau khi đủ cơ sở, reflect sau đó."],"answer":"Do not send the draft before resolving confidentiality; seek authorized guidance and alternatives.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A client seeks a low-risk income investment. An adviser has incomplete product information and receives extra compensation for one option. Which step should occur before deciding?","steps_vi":["Identify: risk/return needs, compensation conflict, unknown risk/cost facts; Consider: kiểm tra alternatives, guidance, bias do incentive.","Chưa đủ dữ liệu để quyết định, nên thu thập research và so sánh options. Disclosure một mình không thay thế suitability hoặc basis."],"answer":"Gather the missing product information and evaluate alternatives before making a recommendation.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A manager implemented an ethical decision after consulting compliance. Months later, unexpected client harm emerges. What is the appropriate next step?","steps_vi":["Reflect: so sánh kết quả thực tế với dự kiến; xem lại facts, stakeholders, influences, guidance và alternative actions.","Điều tra nguyên nhân, xác định corrective steps nếu cần và cập nhật quy trình để tránh lặp lại; không tự động suy rằng quyết định ban đầu phi đạo đức chỉ vì hậu quả ngoài dự kiến."],"answer":"Reflect on the outcome, investigate the cause and improve the decision process.","check":"Original conceptual vignette; conclusion limited to stated facts."}],"questions":[{"stem_en":"Why should an analyst use an ethical decision-making framework even for seemingly routine decisions?","options":["To guarantee that every stakeholder receives the same benefit.","To identify duties and consequences that a narrow perspective may overlook.","To replace the need for professional judgment."],"correct":1,"why_vi":"Ethical decision-making framework bổ sung phân tích kinh tế bằng việc xem xét facts, stakeholders, duties, conflicts và hậu quả ngắn/dài hạn. Quy trình giúp nhận diện vấn đề bị bỏ qua, chọn phương án giảm hại và giải thích rationale cho người liên quan.","trap_vi":"Framework không phải thuật toán luôn sinh ra một đáp án hoàn hảo."},{"stem_en":"Before selecting a product, an adviser lists the client's objectives, fee incentives, applicable duties and missing liquidity data. This is primarily the:","options":["Decide and act phase.","Identify phase.","Reflect phase."],"correct":1,"why_vi":"Bước Identify xác định facts đã biết và thông tin còn thiếu, phân biệt fact với opinion, liệt kê stakeholders và nghĩa vụ, nguyên tắc/luật liên quan, xung đột lợi ích hoặc xung đột giữa các nghĩa vụ. Chưa quyết định trước khi hiểu đúng hoàn cảnh.","trap_vi":"Không đánh đồng lời đồn với facts hoặc nhảy thẳng sang quyết định."},{"stem_en":"An analyst consults an independent compliance officer and compares several lawful responses to a conflict. This most directly represents:","options":["Identify only.","Consider.","Reflect after the action."],"correct":1,"why_vi":"Bước Consider xem xét áp lực tình huống và bias cá nhân; tìm thêm hướng dẫn từ policies, Code and Standards, compliance, mentor hoặc legal counsel phù hợp, đặc biệt người không chịu cùng áp lực; phát triển và đánh giá các lựa chọn. Vẫn phải bảo vệ thông tin bí mật khi xin tư vấn.","trap_vi":"Xin lời khuyên không chuyển toàn bộ trách nhiệm sang người tư vấn."},{"stem_en":"After reviewing the facts and guidance, a manager withdraws an unjustified recommendation. This action is primarily part of:","options":["Reflect.","Identify only.","Decide and act."],"correct":2,"why_vi":"Chọn phương án phù hợp nghĩa vụ và giảm thiểu hậu quả bất lợi dựa trên phân tích; sau đó thực hiện chứ không chỉ nhận ra vấn đề. Nếu thông tin thiếu, có thể trì hoãn hành động rủi ro và quay lại các bước trước để thu thập dữ liệu cần thiết.","trap_vi":"Không coi 'chưa biết đủ' là lý do thực hiện ngay phương án có lợi cá nhân."},{"stem_en":"Months after a decision, an adviser assesses unintended client consequences and changes future procedures. This is the:","options":["initial identification of the original facts only.","Reflect phase.","selection of the original action only."],"correct":1,"why_vi":"Sau hành động, đánh giá kết quả so với dự kiến, nguyên nhân khác biệt và liệu đã xác định đủ facts, stakeholders, conflicts, influences, guidance và alternatives. Có thể phải phản tư nhiều lần khi tác động dài hạn xuất hiện, từ đó cải thiện quyết định và quy trình sau này.","trap_vi":"Reflection không chỉ xảy ra khi quyết định có kết quả xấu."},{"stem_en":"During consideration, an analyst discovers a previously unknown conflict. The most appropriate use of the framework is to:","options":["return to identification and reassess the alternatives.","ignore the conflict because identification was completed.","skip directly to reflection without deciding or acting."],"correct":0,"why_vi":"Framework có bốn giai đoạn nhưng mang tính iterative: khi dữ liệu mới xuất hiện, người quyết định có thể quay lại Identify/Consider; đôi khi không có phương án hoàn toàn thỏa mãn mọi người, cần chọn cách tốt nhất theo nghĩa vụ và bối cảnh.","trap_vi":"Không bắt buộc hoàn thành mỗi bước đúng một lần."},{"stem_en":"An analyst is asked to send confidential draft research to an external friend for advice. The analyst has not established permission to share the material. How should the analyst apply the framework?","options":["Send the draft with an informal request for secrecy.","Assume the benefit of additional research outweighs all confidentiality obligations.","Pause the disclosure and obtain appropriate guidance without revealing confidential information."],"correct":2,"why_vi":"Identify: facts, confidentiality, external contact, duties, possible pressure muốn hoàn thành nhanh; còn thiếu permission. Consider: kiểm tra firm policy, consult authorized compliance/colleagues, tìm alternative không tiết lộ confidential information; decide sau khi đủ cơ sở, reflect sau đó.","trap_vi":"Seeking guidance is not permission to disclose protected information."},{"stem_en":"A client seeks a low-risk income investment. An adviser has incomplete product information and receives extra compensation for one option. Which step should occur before deciding?","options":["Obtain relevant information and evaluate alternatives in light of the client's needs and conflicts.","Recommend the highest-commission product after mentioning the commission.","Choose immediately to avoid delaying the sales process."],"correct":0,"why_vi":"Identify: risk/return needs, compensation conflict, unknown risk/cost facts; Consider: kiểm tra alternatives, guidance, bias do incentive. Chưa đủ dữ liệu để quyết định, nên thu thập research và so sánh options. Disclosure một mình không thay thế suitability hoặc basis.","trap_vi":"The framework is iterative and conflict disclosure alone does not establish suitability."},{"stem_en":"A manager implemented an ethical decision after consulting compliance. Months later, unexpected client harm emerges. What is the appropriate next step?","options":["Ignore the new information because the decision was approved earlier.","Reassess outcomes and revise future procedures as appropriate.","Assume every unexpected outcome proves intentional misconduct."],"correct":1,"why_vi":"Reflect: so sánh kết quả thực tế với dự kiến; xem lại facts, stakeholders, influences, guidance và alternative actions. Điều tra nguyên nhân, xác định corrective steps nếu cần và cập nhật quy trình để tránh lặp lại; không tự động suy rằng quyết định ban đầu phi đạo đức chỉ vì hậu quả ngoài dự kiến.","trap_vi":"Reflection is ongoing and does not equate bad outcomes with intentional wrongdoing."},{"stem_en":"During the consideration stage, a researcher realizes that the status of a source’s information is unclear. What is the most appropriate use of the framework?","options":["Proceed because the identify stage is already complete.","Return to fact gathering and seek guidance before acting.","Skip directly to reflection after publishing."],"correct":1,"why_en":"The framework is iterative; missing material facts can require returning to earlier stages.","why_vi":"Framework có tính lặp; cần quay lại thu thập dữ kiện quan trọng.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 32–42 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 157–160; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 13–14","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Decision framework: iterate when material facts are missing"},{"stem_en":"After implementing a decision, the manager compares actual stakeholder effects with anticipated effects. Which stage is illustrated?","options":["Reflect.","Identify.","Consider alternatives."],"correct":0,"why_en":"Reflection evaluates results and informs later decisions.","why_vi":"Reflection đánh giá kết quả và hỗ trợ quyết định tương lai.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 32–42 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 157–160; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 13–14","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Decision framework: iterate when material facts are missing"}],"cards":[{"front_en":"Framework purpose and multiple perspectives","back_vi":"Ethical decision-making framework bổ sung phân tích kinh tế bằng việc xem xét facts, stakeholders, duties, conflicts và hậu quả ngắn/dài hạn. Quy trình giúp nhận diện vấn đề bị bỏ qua, chọn phương án giảm hại và giải thích rationale cho người liên quan. | Exam trap: Framework không phải thuật toán luôn sinh ra một đáp án hoàn hảo."},{"front_en":"Identify — facts, duties, principles and conflicts","back_vi":"Bước Identify xác định facts đã biết và thông tin còn thiếu, phân biệt fact với opinion, liệt kê stakeholders và nghĩa vụ, nguyên tắc/luật liên quan, xung đột lợi ích hoặc xung đột giữa các nghĩa vụ. Chưa quyết định trước khi hiểu đúng hoàn cảnh. | Exam trap: Không đánh đồng lời đồn với facts hoặc nhảy thẳng sang quyết định."},{"front_en":"Consider — influences, guidance, alternatives","back_vi":"Bước Consider xem xét áp lực tình huống và bias cá nhân; tìm thêm hướng dẫn từ policies, Code and Standards, compliance, mentor hoặc legal counsel phù hợp, đặc biệt người không chịu cùng áp lực; phát triển và đánh giá các lựa chọn. Vẫn phải bảo vệ thông tin bí mật khi xin tư vấn. | Exam trap: Xin lời khuyên không chuyển toàn bộ trách nhiệm sang người tư vấn."},{"front_en":"Decide and act","back_vi":"Chọn phương án phù hợp nghĩa vụ và giảm thiểu hậu quả bất lợi dựa trên phân tích; sau đó thực hiện chứ không chỉ nhận ra vấn đề. Nếu thông tin thiếu, có thể trì hoãn hành động rủi ro và quay lại các bước trước để thu thập dữ liệu cần thiết. | Exam trap: Không coi 'chưa biết đủ' là lý do thực hiện ngay phương án có lợi cá nhân."},{"front_en":"Reflect — evaluate and learn","back_vi":"Sau hành động, đánh giá kết quả so với dự kiến, nguyên nhân khác biệt và liệu đã xác định đủ facts, stakeholders, conflicts, influences, guidance và alternatives. Có thể phải phản tư nhiều lần khi tác động dài hạn xuất hiện, từ đó cải thiện quyết định và quy trình sau này. | Exam trap: Reflection không chỉ xảy ra khi quyết định có kết quả xấu."},{"front_en":"Iterative rather than rigid process","back_vi":"Framework có bốn giai đoạn nhưng mang tính iterative: khi dữ liệu mới xuất hiện, người quyết định có thể quay lại Identify/Consider; đôi khi không có phương án hoàn toàn thỏa mãn mọi người, cần chọn cách tốt nhất theo nghĩa vụ và bối cảnh. | Exam trap: Không bắt buộc hoàn thành mỗi bước đúng một lần."},{"front_en":"Ethical decision-making framework — framework?","back_vi":"Identify → Consider → Decide and act → Reflect · Identify: facts, stakeholders/duties, ethical principles, conflicts. Consider: situational influences, guidance, alternatives. Decide/act: lựa chọn và thực hiện. Reflect: đánh giá kết quả. · Quy trình iterative, quay lại bước trước khi thông tin mới xuất hiện."},{"front_en":"Identify checklist — framework?","back_vi":"Known facts / missing facts / facts vs opinion / stakeholders / duties / applicable requirements / conflicts · Bảng kiểm trước khi ra quyết định; tách assumption, pressure và information. · Không bỏ qua stakeholder gián tiếp hay nghĩa vụ thị trường."},{"front_en":"Consider checklist — framework?","back_vi":"Situational influences / biases / independent guidance / feasible alternatives / consequences · Tìm nguồn tư vấn phù hợp, tránh người chịu cùng áp lực; đánh giá lựa chọn, consequences và tính phù hợp với các yêu cầu áp dụng. · Khi hỏi ngoài công ty phải bảo vệ confidential information."},{"front_en":"Reflect checklist — framework?","back_vi":"Expected outcome vs actual outcome → causes → omitted information or influences → lessons · Kiểm tra kết quả theo thời gian và rút kinh nghiệm để cải thiện quy trình. · Không dùng hindsight để giả định mọi thông tin sau này đã biết từ trước."},{"front_en":"An analyst is asked to send confidential draft research to an external friend for advice. The analyst has not established permission to share the material. How should the analyst apply the framework?","back_vi":"Do not send the draft before resolving confidentiality; seek authorized guidance and alternatives. — Identify: facts, confidentiality, external contact, duties, possible pressure muốn hoàn thành nhanh; còn thiếu permission. Consider: kiểm tra firm policy, consult authorized compliance/colleagues, tìm alternative không tiết lộ confidential information; decide sau khi đủ cơ sở, reflect sau đó."},{"front_en":"A client seeks a low-risk income investment. An adviser has incomplete product information and receives extra compensation for one option. Which step should occur before deciding?","back_vi":"Gather the missing product information and evaluate alternatives before making a recommendation. — Identify: risk/return needs, compensation conflict, unknown risk/cost facts; Consider: kiểm tra alternatives, guidance, bias do incentive. Chưa đủ dữ liệu để quyết định, nên thu thập research và so sánh options. Disclosure một mình không thay thế suitability hoặc basis."},{"front_en":"A manager implemented an ethical decision after consulting compliance. Months later, unexpected client harm emerges. What is the appropriate next step?","back_vi":"Reflect on the outcome, investigate the cause and improve the decision process. — Reflect: so sánh kết quả thực tế với dự kiến; xem lại facts, stakeholders, influences, guidance và alternative actions. Điều tra nguyên nhân, xác định corrective steps nếu cần và cập nhật quy trình để tránh lặp lại; không tự động suy rằng quyết định ban đầu phi đạo đức chỉ vì hậu quả ngoài dự kiến."},{"front_en":"Decision framework: iterate when material facts are missing","back_en":"Identify facts, affected parties, duties and conflicts; consider pressures, advice and alternatives; decide and act; then reflect on the outcome. If important facts are missing, return to identification or seek qualified guidance. Reflection improves future decisions; it cannot undo an existing violation merely by recognizing it.","back_vi":"Xác định dữ kiện, bên chịu ảnh hưởng, nghĩa vụ và xung đột; cân nhắc áp lực, hướng dẫn và phương án; quyết định/hành động; rồi phản tư. Thiếu dữ kiện quan trọng thì quay lại xác định hoặc tìm hướng dẫn phù hợp. Reflection cải thiện quyết định sau, không xóa vi phạm đã xảy ra.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 17 (LOS); pp. 32–42 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 89 Physical PDF pp. 157–160; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 13–14","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]}],"version":"7.3","qa_status":"TARGETED_SOURCE_COMPARISON_PENDING_FINAL"},{"module_id":"CFA26-10-02","module_title":"Code of Ethics and Standards of Professional Conduct","subject":"Ethical and Professional Standards","level":"CFA Level I 2026","status":"Source-mapped detailed academic draft; not independently certified","language":"Vietnamese explanations with English terminology and English exam questions","source_policy":"Original paraphrases, conceptual cases and questions; CFAI 2026 Volume 10 primary, Kaplan Book 4 and SAPP Ethics secondary. Legacy v59 ethics lessons reviewed and preserved. No publisher question reproductions.","disclaimer_vi":"Bản học chi tiết dạng draft, không thay thế nguyên văn Code and Standards. Phân biệt yêu cầu bắt buộc với hướng dẫn và best practices; nội dung LM2 là tổng quan 23 sub-standards, không thay cho LM3 Guidance. Chưa thẩm định học thuật độc lập từng câu.","los":[{"id":"CFA26-10-02-LOS01","letter":"a","title_en":"Professional Conduct Program and Enforcement","outcome_en":"describe the structure of the CFA Institute Professional Conduct Program and its enforcement process","overview_vi":"Bài 2.a: Professional Conduct Program and Enforcement. Học nguyên tắc, phân biệt nghĩa vụ và bẫy, rồi vận dụng vào tình huống tiếng Anh nguyên gốc. Các khung trong phần Công thức là khung định tính, không phải công thức toán. LM2 giới thiệu các sub-standard; hướng dẫn áp dụng chi tiết thuộc LM3. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 47 (LOS); pp. 47–52 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 90","pages":"Physical PDF pp. 161–162"},{"id":"SAPP CFA Level I 2026 — Ethics slides","pages":"Physical PDF pp. 17–18"}],"sections":[{"heading":"Scope of the Professional Conduct Program","body":"CFA Institute Professional Conduct Program (PCP) thực thi Code and Standards đối với members và candidates. Professional Conduct division còn thực thi testing policies của các chương trình CFA Institute và conduct của CIPM certificants theo phạm vi tương ứng. Đây là quy trình kỷ luật nghề nghiệp, không phải tòa án hay cơ quan bồi thường cho khách hàng.","trap":"Không coi PCP là cơ quan quản lý mọi người làm trong ngành tài chính."},{"heading":"Board of Governors and DRC","body":"Board of Governors chịu trách nhiệm giám sát PCP. Disciplinary Review Committee (DRC) gồm các CFA charterholders tình nguyện, phối hợp Professional Conduct staff về chính sách và phục vụ trên các panels xét vụ việc. Bylaws và Rules of Procedure for Professional Conduct là nền tảng quy trình.","trap":"Phân biệt oversight, điều tra của staff và adjudication khi charges không được chấp nhận."},{"heading":"Annual Professional Conduct Statement","body":"Members/candidates phải tự khai báo những vấn đề đặt nghi vấn về professional conduct theo annual Professional Conduct Statement, chẳng hạn civil litigation, criminal investigation hoặc written complaint. Việc khai báo không tự xác định có vi phạm; thông tin có thể dẫn đến inquiry.","trap":"Không đợi có kết luận vi phạm mới khai khi thuộc diện phải khai báo."},{"heading":"Complaints and public information","body":"Written complaints gửi Professional Conduct staff và thông tin từ media, regulatory notices hay nguồn công khai khác có thể khởi xướng inquiry. Không nhất thiết có đơn do khách hàng nộp; PCP có thể biết về hành vi đáng ngờ qua thông tin công khai.","trap":"Không suy ra thông tin trên báo chí tự động là chứng cứ kết luận vi phạm."},{"heading":"Exam monitoring","body":"Nguồn inquiry còn gồm proctor reports về hành vi nghi ngờ vi phạm testing rules, phân tích điểm và exam materials sau kỳ thi, theo dõi online/social media nhằm phát hiện việc tiết lộ thông tin thi bí mật. Inquiry có thể phát sinh ngay cả khi không có báo cáo tại phòng thi.","trap":"Không giới hạn giám sát candidate ở ngày thi."},{"heading":"Investigation by Professional Conduct staff","body":"Sau khi inquiry được khởi xướng, staff có thể yêu cầu written explanation, phỏng vấn member/candidate, complainants và third parties, thu thập documents và records liên quan. Mục đích là xác minh facts; không phải mọi inquiry đều dẫn tới charges hoặc panel.","trap":"Investigation không đồng nghĩa đã kết luận vi phạm."},{"heading":"Possible staff outcomes","body":"Sau đánh giá tài liệu, staff có thể kết thúc inquiry không áp dụng disciplinary sanction, gửi cautionary letter hoặc tiếp tục proceedings. Nếu staff cho rằng có vi phạm Code/Standards hoặc testing policies, member/candidate có cơ hội chấp nhận hoặc không chấp nhận charges và proposed sanctions.","trap":"Không mặc định mọi inquiry kết thúc bằng kỷ luật."},{"heading":"Contested charges and DRC panel","body":"Nếu member/candidate không chấp nhận charges và proposed sanction, vụ việc được chuyển DRC panel. Panel xem xét tài liệu và trình bày của cả staff lẫn người bị điều tra, quyết định có vi phạm hay không và sanction nếu có. Không đồng nhất panel với staff ban đầu.","trap":"Không coi việc từ chối proposed sanction tự nó là vi phạm mới."},{"heading":"Sanctions and consequences","body":"Sanctions có thể gồm public censure, suspension membership và quyền sử dụng CFA designation, revocation CFA charter; candidates có thể bị đình chỉ hoặc cấm tiếp tục CFA Program. Tùy sự việc và quy trình, không mặc định sanction cao nhất cho mọi vi phạm.","trap":"PCP không tự động quyết định bồi thường tiền hoặc hình phạt hình sự."},{"heading":"Voluntary adoption by firms","body":"Code and Standards áp dụng trực tiếp cho cá nhân là member/candidate; CFA Institute khuyến khích firm hoặc nonmember tự nguyện đưa các nguyên tắc vào code của mình. Claim compliance chỉ phù hợp sau khi đảm bảo đáp ứng nguyên tắc và cần nêu rằng claim chưa được CFA Institute xác minh. Asset Manager Code là bộ hướng dẫn hướng tới firm, khác đối tượng.","trap":"Không gọi voluntary firm claim là chứng nhận CFA Institute hoặc thay thế Asset Manager Code."},{"heading":"Enforcement: allegations, investigation and contested charges","body":"Khiếu nại hoặc tin công khai có thể khởi động điều tra nhưng chưa phải kết luận. Staff thu thập tài liệu, giải trình, có thể kết thúc, cảnh báo hoặc tiến hành kỷ luật. Nếu không chấp nhận cáo buộc và chế tài đề xuất, panel DRC xác định vi phạm và chế tài. Quy trình CFA khác tố tụng tòa án.","body_en":"A complaint or public report may trigger an inquiry but is not itself a finding. Staff may gather documents and explanations, end the matter, caution the individual, or pursue discipline. If proposed charges and sanctions are not accepted, a DRC panel determines the violation and any sanction. The CFA disciplinary process is distinct from court proceedings.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 47–52 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 161–162; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 17–18","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"PCP structure","expr":"Board oversight → Professional Conduct staff and DRC","meaning":"Board of Governors giám sát, staff tiến hành inquiry/investigation; DRC là committee volunteer charterholders phối hợp chính sách và xét disputed cases.","conditions":"Không đồng nhất DRC với cơ quan quản lý thị trường hoặc coi Board xử từng hồ sơ."},{"name":"Five inquiry sources","expr":"Self-disclosure; written complaints; public sources; proctor reports; post-exam analysis and online monitoring","meaning":"Nhớ đầy đủ nguồn inquiry theo CFAI, kể cả thông tin không đến từ khách hàng hay employer.","conditions":"Inquiry không có nghĩa là vi phạm đã được xác nhận."},{"name":"Investigation and disposition","expr":"Inquiry → investigate → no sanction / cautionary letter / disciplinary proceedings","meaning":"Staff thu thập giải trình, phỏng vấn, documents/records; sau đó quyết định disposition. Nếu đề xuất charges/sanction, subject có cơ hội accept hoặc reject.","conditions":"Không chuyển mọi inquiry tự động tới DRC panel."},{"name":"Disputed charges","expr":"Reject proposed charges/sanction → DRC panel reviews evidence and presentations → finding and sanction if appropriate","meaning":"DRC panel xem xét thông tin của staff và member/candidate, đưa ra kết luận và sanction khi có vi phạm.","conditions":"Không suy ra việc từ chối đề xuất là một hành vi vi phạm độc lập."}],"examples":[{"question_en":"A candidate is named in a public regulatory announcement. No formal written complaint has been received by CFA Institute. Which statement about the PCP is most accurate?","steps_vi":["Public sources như regulatory notice và media là nguồn inquiry độc lập với written complaint.","Professional Conduct staff có thể mở inquiry, xác minh facts và quyết định disposition. Chưa đủ cơ sở kết luận sanction."],"answer":"The public notice may trigger an inquiry without a written complaint.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"Following an investigation, staff proposes a sanction. The member disputes the charge and rejects the proposed sanction. Which procedural outcome is consistent with the curriculum?","steps_vi":["Staff đề xuất charges/sanction; subject có quyền accept hoặc reject.","Nếu không chấp nhận, DRC panel xem xét tài liệu và trình bày của cả hai bên để xác định violation và sanction nếu có."],"answer":"Referral to a DRC panel for review.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A firm voluntarily adopts the Code and Standards and wishes to market its adoption to clients. Which action is most appropriate?","steps_vi":["Code trực tiếp áp dụng cho members/candidates; firms có thể voluntarily adopt.","Kiểm tra code đáp ứng các nguyên tắc, dùng claim compliance với lưu ý claim chưa được CFA Institute verified. Không gọi firm là CFA charterholder."],"answer":"Accurately claim compliance, if supported, and disclose that CFA Institute has not verified the claim.","check":"Original conceptual vignette; conclusion limited to stated facts."}],"questions":[{"stem_en":"A nonmember who is not a CFA Program candidate works for a firm that uses its own ethics code. Which statement about the CFA Institute Code and Standards is most accurate?","options":["Every investment employee automatically becomes subject to CFA Institute discipline.","The Code and Standards directly govern CFA Institute members and candidates; voluntary firm adoption is distinct.","The employer's code cannot include the CFA Institute principles."],"correct":1,"why_vi":"CFA Institute Professional Conduct Program (PCP) thực thi Code and Standards đối với members và candidates. Professional Conduct division còn thực thi testing policies của các chương trình CFA Institute và conduct của CIPM certificants theo phạm vi tương ứng. Đây là quy trình kỷ luật nghề nghiệp, không phải tòa án hay cơ quan bồi thường cho khách hàng.","trap_vi":"Không coi PCP là cơ quan quản lý mọi người làm trong ngành tài chính."},{"stem_en":"Which entity maintains oversight of the Professional Conduct Program?","options":["The member's employer.","The complaining party.","CFA Institute Board of Governors."],"correct":2,"why_vi":"Board of Governors chịu trách nhiệm giám sát PCP. Disciplinary Review Committee (DRC) gồm các CFA charterholders tình nguyện, phối hợp Professional Conduct staff về chính sách và phục vụ trên các panels xét vụ việc. Bylaws và Rules of Procedure for Professional Conduct là nền tảng quy trình.","trap_vi":"Phân biệt oversight, điều tra của staff và adjudication khi charges không được chấp nhận."},{"stem_en":"A member is involved in a civil lawsuit questioning her professional conduct but no finding has been made. Which action is consistent with the inquiry framework?","options":["Disclose the matter as required on the Professional Conduct Statement.","Wait until a criminal conviction occurs.","Assume the employer's knowledge replaces self-disclosure."],"correct":0,"why_vi":"Members/candidates phải tự khai báo những vấn đề đặt nghi vấn về professional conduct theo annual Professional Conduct Statement, chẳng hạn civil litigation, criminal investigation hoặc written complaint. Việc khai báo không tự xác định có vi phạm; thông tin có thể dẫn đến inquiry.","trap_vi":"Không đợi có kết luận vi phạm mới khai khi thuộc diện phải khai báo."},{"stem_en":"A regulatory notice publicly describes possible misconduct by a CFA member. Which response is possible under the PCP?","options":["Staff must wait for a client to submit a complaint.","A DRC panel must immediately revoke the charter.","Staff may initiate an inquiry based on the public notice."],"correct":2,"why_vi":"Written complaints gửi Professional Conduct staff và thông tin từ media, regulatory notices hay nguồn công khai khác có thể khởi xướng inquiry. Không nhất thiết có đơn do khách hàng nộp; PCP có thể biết về hành vi đáng ngờ qua thông tin công khai.","trap_vi":"Không suy ra thông tin trên báo chí tự động là chứng cứ kết luận vi phạm."},{"stem_en":"An examination security review detects possible disclosure of confidential exam content after the testing date. The review may:","options":["be considered only if the exam proctor witnessed the disclosure.","provide a basis for a Professional Conduct inquiry.","be ignored because the examination has ended."],"correct":1,"why_vi":"Nguồn inquiry còn gồm proctor reports về hành vi nghi ngờ vi phạm testing rules, phân tích điểm và exam materials sau kỳ thi, theo dõi online/social media nhằm phát hiện việc tiết lộ thông tin thi bí mật. Inquiry có thể phát sinh ngay cả khi không có báo cáo tại phòng thi.","trap_vi":"Không giới hạn giám sát candidate ở ngày thi."},{"stem_en":"Which activity is most consistent with the investigation phase?","options":["Automatically imposing a sanction upon receiving a complaint.","Requesting relevant records and a written explanation.","Referring every inquiry to a disciplinary panel before reviewing evidence."],"correct":1,"why_vi":"Sau khi inquiry được khởi xướng, staff có thể yêu cầu written explanation, phỏng vấn member/candidate, complainants và third parties, thu thập documents và records liên quan. Mục đích là xác minh facts; không phải mọi inquiry đều dẫn tới charges hoặc panel.","trap_vi":"Investigation không đồng nghĩa đã kết luận vi phạm."},{"stem_en":"After an investigation, Professional Conduct staff concludes that a disciplinary sanction is not warranted. Which outcome is possible?","options":["Mandatory suspension of membership.","Closing the inquiry without a disciplinary sanction.","A compulsory DRC hearing in every case."],"correct":1,"why_vi":"Sau đánh giá tài liệu, staff có thể kết thúc inquiry không áp dụng disciplinary sanction, gửi cautionary letter hoặc tiếp tục proceedings. Nếu staff cho rằng có vi phạm Code/Standards hoặc testing policies, member/candidate có cơ hội chấp nhận hoặc không chấp nhận charges và proposed sanctions.","trap_vi":"Không mặc định mọi inquiry kết thúc bằng kỷ luật."},{"stem_en":"A candidate rejects the charges and proposed sanction after investigation. What is the next procedural step described in the curriculum?","options":["Automatic acceptance of the proposed sanction by default.","Referral to a panel composed of DRC members.","Closure of the inquiry because the candidate disagrees."],"correct":1,"why_vi":"Nếu member/candidate không chấp nhận charges và proposed sanction, vụ việc được chuyển DRC panel. Panel xem xét tài liệu và trình bày của cả staff lẫn người bị điều tra, quyết định có vi phạm hay không và sanction nếu có. Không đồng nhất panel với staff ban đầu.","trap_vi":"Không coi việc từ chối proposed sanction tự nó là vi phạm mới."},{"stem_en":"Which outcome is within the professional disciplinary scope described by the curriculum?","options":["Suspension of the right to use the CFA designation.","Automatic criminal imprisonment ordered by the DRC.","Guaranteed reimbursement of every client's investment loss."],"correct":0,"why_vi":"Sanctions có thể gồm public censure, suspension membership và quyền sử dụng CFA designation, revocation CFA charter; candidates có thể bị đình chỉ hoặc cấm tiếp tục CFA Program. Tùy sự việc và quy trình, không mặc định sanction cao nhất cho mọi vi phạm.","trap_vi":"PCP không tự động quyết định bồi thường tiền hoặc hình phạt hình sự."},{"stem_en":"A firm adopts the principles of the CFA Institute Code and Standards and wishes to announce this. Which representation is appropriate?","options":["Advertise that CFA Institute has certified all its employees.","State that adopting the principles is equivalent to earning a CFA charter.","Claim compliance only after meeting the principles and state that CFA Institute has not verified the claim."],"correct":2,"why_vi":"Code and Standards áp dụng trực tiếp cho cá nhân là member/candidate; CFA Institute khuyến khích firm hoặc nonmember tự nguyện đưa các nguyên tắc vào code của mình. Claim compliance chỉ phù hợp sau khi đảm bảo đáp ứng nguyên tắc và cần nêu rằng claim chưa được CFA Institute xác minh. Asset Manager Code là bộ hướng dẫn hướng tới firm, khác đối tượng.","trap_vi":"Không gọi voluntary firm claim là chứng nhận CFA Institute hoặc thay thế Asset Manager Code."},{"stem_en":"A candidate is named in a public regulatory announcement. No formal written complaint has been received by CFA Institute. Which statement about the PCP is most accurate?","options":["A written complaint is required before any inquiry.","The Board of Governors must impose a sanction immediately.","Staff may investigate information from the public regulatory announcement."],"correct":2,"why_vi":"Public sources như regulatory notice và media là nguồn inquiry độc lập với written complaint. Professional Conduct staff có thể mở inquiry, xác minh facts và quyết định disposition. Chưa đủ cơ sở kết luận sanction.","trap_vi":"Inquiry sources are not limited to complaints."},{"stem_en":"Following an investigation, staff proposes a sanction. The member disputes the charge and rejects the proposed sanction. Which procedural outcome is consistent with the curriculum?","options":["The matter is referred to a panel of DRC members.","Staff must close the case immediately.","The member is automatically expelled for contesting the charge."],"correct":0,"why_vi":"Staff đề xuất charges/sanction; subject có quyền accept hoặc reject. Nếu không chấp nhận, DRC panel xem xét tài liệu và trình bày của cả hai bên để xác định violation và sanction nếu có.","trap_vi":"A contested charge triggers panel review, not automatic guilt."},{"stem_en":"A firm voluntarily adopts the Code and Standards and wishes to market its adoption to clients. Which action is most appropriate?","options":["Claim that CFA Institute has independently certified its compliance.","Claim that all firm employees are CFA charterholders.","Verify its own alignment and clearly state that the compliance claim has not been verified by CFA Institute."],"correct":2,"why_vi":"Code trực tiếp áp dụng cho members/candidates; firms có thể voluntarily adopt. Kiểm tra code đáp ứng các nguyên tắc, dùng claim compliance với lưu ý claim chưa được CFA Institute verified. Không gọi firm là CFA charterholder.","trap_vi":"Voluntary adoption is distinct from independent verification and individual credentials."},{"stem_en":"Professional Conduct staff receive a credible regulatory notice about a member. Which statement is most accurate?","options":["An inquiry requires a complaint from another charterholder.","The notice may initiate an inquiry without establishing a violation.","The notice automatically revokes the charter."],"correct":1,"why_en":"Public regulatory information can trigger an inquiry; evidence is assessed before discipline.","why_vi":"Thông tin cơ quan quản lý có thể khởi động điều tra; cần đánh giá chứng cứ trước kỷ luật.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 47–52 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 161–162; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 17–18","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Enforcement: allegations, investigation and contested charges"},{"stem_en":"A candidate rejects proposed charges and a sanction after a staff investigation. Under the process described in the curriculum, the next decision on the contested matter is made by:","options":["the candidate’s employer.","a prospective client.","a panel of DRC members."],"correct":2,"why_en":"The contested case is referred to a DRC panel.","why_vi":"Vụ việc bị phản đối được chuyển tới panel DRC.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 47–52 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 161–162; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 17–18","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Enforcement: allegations, investigation and contested charges"}],"cards":[{"front_en":"Scope of the Professional Conduct Program","back_vi":"CFA Institute Professional Conduct Program (PCP) thực thi Code and Standards đối với members và candidates. Professional Conduct division còn thực thi testing policies của các chương trình CFA Institute và conduct của CIPM certificants theo phạm vi tương ứng. Đây là quy trình kỷ luật nghề nghiệp, không phải tòa án hay cơ quan bồi thường cho khách hàng. | Exam trap: Không coi PCP là cơ quan quản lý mọi người làm trong ngành tài chính."},{"front_en":"Board of Governors and DRC","back_vi":"Board of Governors chịu trách nhiệm giám sát PCP. Disciplinary Review Committee (DRC) gồm các CFA charterholders tình nguyện, phối hợp Professional Conduct staff về chính sách và phục vụ trên các panels xét vụ việc. Bylaws và Rules of Procedure for Professional Conduct là nền tảng quy trình. | Exam trap: Phân biệt oversight, điều tra của staff và adjudication khi charges không được chấp nhận."},{"front_en":"Annual Professional Conduct Statement","back_vi":"Members/candidates phải tự khai báo những vấn đề đặt nghi vấn về professional conduct theo annual Professional Conduct Statement, chẳng hạn civil litigation, criminal investigation hoặc written complaint. Việc khai báo không tự xác định có vi phạm; thông tin có thể dẫn đến inquiry. | Exam trap: Không đợi có kết luận vi phạm mới khai khi thuộc diện phải khai báo."},{"front_en":"Complaints and public information","back_vi":"Written complaints gửi Professional Conduct staff và thông tin từ media, regulatory notices hay nguồn công khai khác có thể khởi xướng inquiry. Không nhất thiết có đơn do khách hàng nộp; PCP có thể biết về hành vi đáng ngờ qua thông tin công khai. | Exam trap: Không suy ra thông tin trên báo chí tự động là chứng cứ kết luận vi phạm."},{"front_en":"Exam monitoring","back_vi":"Nguồn inquiry còn gồm proctor reports về hành vi nghi ngờ vi phạm testing rules, phân tích điểm và exam materials sau kỳ thi, theo dõi online/social media nhằm phát hiện việc tiết lộ thông tin thi bí mật. Inquiry có thể phát sinh ngay cả khi không có báo cáo tại phòng thi. | Exam trap: Không giới hạn giám sát candidate ở ngày thi."},{"front_en":"Investigation by Professional Conduct staff","back_vi":"Sau khi inquiry được khởi xướng, staff có thể yêu cầu written explanation, phỏng vấn member/candidate, complainants và third parties, thu thập documents và records liên quan. Mục đích là xác minh facts; không phải mọi inquiry đều dẫn tới charges hoặc panel. | Exam trap: Investigation không đồng nghĩa đã kết luận vi phạm."},{"front_en":"Possible staff outcomes","back_vi":"Sau đánh giá tài liệu, staff có thể kết thúc inquiry không áp dụng disciplinary sanction, gửi cautionary letter hoặc tiếp tục proceedings. Nếu staff cho rằng có vi phạm Code/Standards hoặc testing policies, member/candidate có cơ hội chấp nhận hoặc không chấp nhận charges và proposed sanctions. | Exam trap: Không mặc định mọi inquiry kết thúc bằng kỷ luật."},{"front_en":"Contested charges and DRC panel","back_vi":"Nếu member/candidate không chấp nhận charges và proposed sanction, vụ việc được chuyển DRC panel. Panel xem xét tài liệu và trình bày của cả staff lẫn người bị điều tra, quyết định có vi phạm hay không và sanction nếu có. Không đồng nhất panel với staff ban đầu. | Exam trap: Không coi việc từ chối proposed sanction tự nó là vi phạm mới."},{"front_en":"Sanctions and consequences","back_vi":"Sanctions có thể gồm public censure, suspension membership và quyền sử dụng CFA designation, revocation CFA charter; candidates có thể bị đình chỉ hoặc cấm tiếp tục CFA Program. Tùy sự việc và quy trình, không mặc định sanction cao nhất cho mọi vi phạm. | Exam trap: PCP không tự động quyết định bồi thường tiền hoặc hình phạt hình sự."},{"front_en":"Voluntary adoption by firms","back_vi":"Code and Standards áp dụng trực tiếp cho cá nhân là member/candidate; CFA Institute khuyến khích firm hoặc nonmember tự nguyện đưa các nguyên tắc vào code của mình. Claim compliance chỉ phù hợp sau khi đảm bảo đáp ứng nguyên tắc và cần nêu rằng claim chưa được CFA Institute xác minh. Asset Manager Code là bộ hướng dẫn hướng tới firm, khác đối tượng. | Exam trap: Không gọi voluntary firm claim là chứng nhận CFA Institute hoặc thay thế Asset Manager Code."},{"front_en":"PCP structure — framework?","back_vi":"Board oversight → Professional Conduct staff and DRC · Board of Governors giám sát, staff tiến hành inquiry/investigation; DRC là committee volunteer charterholders phối hợp chính sách và xét disputed cases. · Không đồng nhất DRC với cơ quan quản lý thị trường hoặc coi Board xử từng hồ sơ."},{"front_en":"Five inquiry sources — framework?","back_vi":"Self-disclosure; written complaints; public sources; proctor reports; post-exam analysis and online monitoring · Nhớ đầy đủ nguồn inquiry theo CFAI, kể cả thông tin không đến từ khách hàng hay employer. · Inquiry không có nghĩa là vi phạm đã được xác nhận."},{"front_en":"Investigation and disposition — framework?","back_vi":"Inquiry → investigate → no sanction / cautionary letter / disciplinary proceedings · Staff thu thập giải trình, phỏng vấn, documents/records; sau đó quyết định disposition. Nếu đề xuất charges/sanction, subject có cơ hội accept hoặc reject. · Không chuyển mọi inquiry tự động tới DRC panel."},{"front_en":"Disputed charges — framework?","back_vi":"Reject proposed charges/sanction → DRC panel reviews evidence and presentations → finding and sanction if appropriate · DRC panel xem xét thông tin của staff và member/candidate, đưa ra kết luận và sanction khi có vi phạm. · Không suy ra việc từ chối đề xuất là một hành vi vi phạm độc lập."},{"front_en":"A candidate is named in a public regulatory announcement. No formal written complaint has been received by CFA Institute. Which statement about the PCP is most accurate?","back_vi":"The public notice may trigger an inquiry without a written complaint. — Public sources như regulatory notice và media là nguồn inquiry độc lập với written complaint. Professional Conduct staff có thể mở inquiry, xác minh facts và quyết định disposition. Chưa đủ cơ sở kết luận sanction."},{"front_en":"Following an investigation, staff proposes a sanction. The member disputes the charge and rejects the proposed sanction. Which procedural outcome is consistent with the curriculum?","back_vi":"Referral to a DRC panel for review. — Staff đề xuất charges/sanction; subject có quyền accept hoặc reject. Nếu không chấp nhận, DRC panel xem xét tài liệu và trình bày của cả hai bên để xác định violation và sanction nếu có."},{"front_en":"A firm voluntarily adopts the Code and Standards and wishes to market its adoption to clients. Which action is most appropriate?","back_vi":"Accurately claim compliance, if supported, and disclose that CFA Institute has not verified the claim. — Code trực tiếp áp dụng cho members/candidates; firms có thể voluntarily adopt. Kiểm tra code đáp ứng các nguyên tắc, dùng claim compliance với lưu ý claim chưa được CFA Institute verified. Không gọi firm là CFA charterholder."},{"front_en":"Enforcement: allegations, investigation and contested charges","back_en":"A complaint or public report may trigger an inquiry but is not itself a finding. Staff may gather documents and explanations, end the matter, caution the individual, or pursue discipline. If proposed charges and sanctions are not accepted, a DRC panel determines the violation and any sanction. The CFA disciplinary process is distinct from court proceedings.","back_vi":"Khiếu nại hoặc tin công khai có thể khởi động điều tra nhưng chưa phải kết luận. Staff thu thập tài liệu, giải trình, có thể kết thúc, cảnh báo hoặc tiến hành kỷ luật. Nếu không chấp nhận cáo buộc và chế tài đề xuất, panel DRC xác định vi phạm và chế tài. Quy trình CFA khác tố tụng tòa án.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 47–52 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 161–162; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 17–18","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-02-LOS02","letter":"b","title_en":"Six Code Components and Seven Standards","outcome_en":"identify the six components of the Code of Ethics and seven Standards of Professional Conduct","overview_vi":"Bài 2.b: Six Code Components and Seven Standards. Học nguyên tắc, phân biệt nghĩa vụ và bẫy, rồi vận dụng vào tình huống tiếng Anh nguyên gốc. Các khung trong phần Công thức là khung định tính, không phải công thức toán. LM2 giới thiệu các sub-standard; hướng dẫn áp dụng chi tiết thuộc LM3. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 47 (LOS); pp. 49–51, 57–61 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 90","pages":"Physical PDF pp. 162–165"},{"id":"SAPP CFA Level I 2026 — Ethics slides","pages":"Physical PDF pp. 19–22"}],"sections":[{"heading":"Code principle 1 — integrity, competence and respect","body":"Nguyên tắc đầu tiên nhấn mạnh integrity, competence, diligence, respect và ứng xử có đạo đức với public, clients/prospective clients, employers, employees, colleagues và các market participants. Đây là phạm vi rộng hơn quan hệ với khách hàng trả phí.","trap":"Không chỉ áp dụng khi trực tiếp quản lý tài sản."},{"heading":"Code principle 2 — profession and clients before self","body":"Integrity của investment profession và lợi ích clients phải được đặt cao hơn lợi ích cá nhân. Nguyên tắc này kết nối client focus với niềm tin vào ngành; không được dùng khách hàng như công cụ đạt mục tiêu cá nhân.","trap":"Không hiểu client interest là lý do vượt qua market integrity hoặc applicable law."},{"heading":"Code principle 3 — reasonable care and independent judgment","body":"Trong analysis, recommendations, investment actions và hoạt động chuyên môn khác, cần reasonable care và independent professional judgment. Thông tin từ người khác có thể hữu ích nhưng không được thay thế đánh giá độc lập phù hợp vai trò.","trap":"Không đồng nhất independence với việc phải tự thu thập toàn bộ dữ liệu."},{"heading":"Code principle 4 — encourage ethical professional practice","body":"Không chỉ tự hành xử chuyên nghiệp và đạo đức, member/candidate còn khuyến khích người khác thực hành như vậy, góp phần tạo uy tín cho bản thân và profession. Mentoring, nêu gương và cải tiến văn hóa là các cách hỗ trợ.","trap":"Không hiểu khuyến khích ethics là quyền công khai mọi hồ sơ bí mật."},{"heading":"Code principle 5 — capital market integrity and viability","body":"Nguyên tắc nhấn mạnh tính toàn vẹn và khả năng tồn tại bền vững của global capital markets vì lợi ích cuối cùng của xã hội. Một quyết định cá nhân có thể đóng góp vào thị trường minh bạch hoặc làm suy yếu niềm tin khi nhiều hành vi xấu tích tụ.","trap":"Không bỏ phần ultimate benefit of society khi hiểu mục tiêu của Code."},{"heading":"Code principle 6 — maintain and improve competence","body":"Member/candidate phải duy trì và cải thiện năng lực nghề nghiệp, đồng thời cố gắng duy trì và nâng cao năng lực của người khác trong ngành. Chuẩn mới I(E) làm rõ yêu cầu competence theo vai trò cụ thể; không áp đặt một chương trình continuing education duy nhất.","trap":"Phân biệt nghĩa vụ duy trì competence với một số giờ CPD bắt buộc không được nêu trong Standard I(E)."},{"heading":"Standard I — Professionalism","body":"Nhóm I bao gồm I(A) Knowledge of the Law, I(B) Independence and Objectivity, I(C) Misrepresentation, I(D) Misconduct, I(E) Competence. Nhóm tập trung vào cách cá nhân hành nghề: luật, phán đoán, trung thực, integrity và năng lực.","trap":"I(E) là mục thứ năm của Standard I; nhớ đủ năm mục theo văn bản CFAI 2026."},{"heading":"Standard II — Integrity of Capital Markets","body":"Nhóm II gồm II(A) Material Nonpublic Information và II(B) Market Manipulation. Mục tiêu là bảo vệ tính toàn vẹn của thông tin và cơ chế hình thành giá, không cho phép dùng thông tin trọng yếu chưa công khai hay thao túng để gây hiểu lầm.","trap":"Không xếp market manipulation vào suitability chỉ vì có tác động khách hàng."},{"heading":"Standard III — Duties to Clients","body":"Nhóm III gồm III(A) Loyalty, Prudence, and Care; III(B) Fair Dealing; III(C) Suitability; III(D) Performance Presentation; III(E) Preservation of Confidentiality. Tập trung bảo vệ quyền lợi, công bằng, tính phù hợp, thông tin hiệu quả đầu tư và bảo mật.","trap":"Loyalty ở III(A) là với clients, khác IV(A) Loyalty với employers."},{"heading":"Standard IV — Duties to Employers","body":"Nhóm IV gồm IV(A) Loyalty, IV(B) Additional Compensation Arrangements và IV(C) Responsibilities of Supervisors. Mục tiêu là bảo vệ nghĩa vụ trong quan hệ lao động, xử lý compensation xung đột và giám sát người thuộc quyền.","trap":"Không nhầm additional compensation với referral fee chỉ vì cả hai có thể là tiền."},{"heading":"Standard V — Investment Analysis, Recommendations, and Actions","body":"Nhóm V gồm V(A) Diligence and Reasonable Basis, V(B) Communication with Clients and Prospective Clients và V(C) Record Retention. Đây là các yêu cầu về quy trình tạo cơ sở phân tích, truyền đạt và lưu bằng chứng.","trap":"V(B) trong nguồn 2026 có yêu cầu nêu loại dịch vụ và chi phí."},{"heading":"Standard VI — Conflicts of Interest","body":"Nhóm VI gồm VI(A) Avoid or Disclose Conflicts, VI(B) Priority of Transactions và VI(C) Referral Fees. Cần nhận diện và tránh xung đột khi hợp lý, công bố khi cần, ưu tiên giao dịch client/employer và minh bạch lợi ích giới thiệu.","trap":"Tên hiện hành VI(A) không chỉ là Disclosure of Conflicts."},{"heading":"Standard VII — Responsibilities as a CFA Institute Member or CFA Candidate","body":"Nhóm VII gồm VII(A) Conduct as Participants in CFA Institute Programs và VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program. Nhóm bảo vệ integrity, validity và security của programs cũng như tính chính xác khi nói về membership, candidacy, designation.","trap":"Không dùng CFA designation như lời bảo đảm performance."},{"heading":"Individual Code and Standards versus firm-level commitments","body":"Code and Standards áp dụng cá nhân thành viên và ứng viên. Firm hoặc người không phải thành viên có thể tự nguyện áp dụng, nhưng claim không có nghĩa CFA Institute xác minh. Asset Manager Code là khung riêng hướng tới tổ chức quản lý tài sản. Không nhầm với tuân thủ báo cáo hiệu suất GIPS.","body_en":"The Code and Standards govern members and candidates personally. A firm or nonmember can voluntarily adopt them, but a claim does not imply CFA Institute verified it. The Asset Manager Code is a distinct firm-oriented framework. Do not confuse either with GIPS performance-reporting compliance.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 57–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 162–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 19–22","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Six Code components","expr":"Integrity/competence/diligence/respect; profession and clients before self; care and independent judgment; practice and encourage ethics; market integrity and viability for society; maintain/improve competence","meaning":"Sáu nguyên tắc ở mức khái quát. Học ý nghĩa và chủ thể, không chỉ thứ tự. ","conditions":"Các sub-standards ở LOS 2.c cụ thể hóa yêu cầu; đây là bản diễn giải để học, không thay thế văn bản chính thức."},{"name":"Seven Standards and 23 sub-standards","expr":"I:5; II:2; III:5; IV:3; V:3; VI:3; VII:2 → 23","meaning":"I Professionalism; II Integrity of Capital Markets; III Duties to Clients; IV Duties to Employers; V Investment Analysis, Recommendations, and Actions; VI Conflicts of Interest; VII Responsibilities as a CFA Institute Member or CFA Candidate.","conditions":"Số mục dùng để kiểm đủ outline 2026; V(B) có 5 yêu cầu nhưng vẫn là 1 sub-standard."},{"name":"2023 revisions used in 2026","expr":"I(E) Competence; V(B) nature of services and costs; VI(A) Avoid or Disclose Conflicts","meaning":"Ba điểm thay đổi cần cập nhật khi học từ notes cũ: competence theo vai trò, disclosure dịch vụ/chi phí, tránh conflict khi hợp lý hoặc disclose đầy đủ.","conditions":"Slide SAPP trang 20 cũng có I(E); đọc theo sơ đồ bố cục, không bỏ dòng cuối khi trích xuất văn bản."}],"examples":[{"question_en":"A manager refuses to use an inaccurate sales claim even though it would increase revenue and a personal bonus. Which two Code objectives are most clearly reinforced?","steps_vi":["Integrity trong cách ứng xử và đặt client/profession trước personal interest.","Không phải vì Code bảo đảm lợi nhuận mà vì honesty, professional judgment và client trust."],"answer":"Integrity and placing professional integrity/client interests above personal interests.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A member uses a complex automated model for a new mandate and does not understand its major limitations. Which recent revision most directly clarifies the obligation to address the skill gap?","steps_vi":["Code principle 6 yêu cầu maintain/improve competence; 2023 revision thêm I(E).","I(E) đòi năng lực phù hợp vai trò; cần học hoặc hỗ trợ phù hợp, không đòi một chương trình CPD cố định."],"answer":"I(E) Competence.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A firm's training manual calls VI(A) 'Disclosure of Conflicts' and says every conflict can be handled by a footnote. What update is necessary?","steps_vi":["Tên 2026 là Avoid or Disclose Conflicts. Ưu tiên tránh khi hợp lý; nếu không, full fair prominent plain-language disclosure.","Footnote mơ hồ không đảm bảo truyền đạt hiệu quả; một số hành vi bị cấm theo standards khác không chữa bằng disclosure."],"answer":"Update VI(A) to Avoid or Disclose Conflicts and require effective disclosure when avoidance is not reasonable.","check":"Original conceptual vignette; conclusion limited to stated facts."}],"questions":[{"stem_en":"A researcher humiliates a colleague while knowingly misrepresenting the colleague's work. Which Code principle most directly encompasses the expected professional behavior?","options":["Promoting the analyst's personal commercial interests.","Guaranteeing the accuracy of all future market forecasts.","Integrity, competence, diligence, and respect toward professional stakeholders."],"correct":2,"why_vi":"Nguyên tắc đầu tiên nhấn mạnh integrity, competence, diligence, respect và ứng xử có đạo đức với public, clients/prospective clients, employers, employees, colleagues và các market participants. Đây là phạm vi rộng hơn quan hệ với khách hàng trả phí.","trap_vi":"Không chỉ áp dụng khi trực tiếp quản lý tài sản."},{"stem_en":"An adviser sacrifices a personal bonus to avoid recommending a product that disadvantages the client. Which Code principle is most directly illustrated?","options":["Maximizing the employer's revenue regardless of client effects.","Giving all clients identical portfolio holdings.","Placing professional integrity and client interests above personal interests."],"correct":2,"why_vi":"Integrity của investment profession và lợi ích clients phải được đặt cao hơn lợi ích cá nhân. Nguyên tắc này kết nối client focus với niềm tin vào ngành; không được dùng khách hàng như công cụ đạt mục tiêu cá nhân.","trap_vi":"Không hiểu client interest là lý do vượt qua market integrity hoặc applicable law."},{"stem_en":"A portfolio manager reviews an external research report rather than accepting its conclusion solely because of the provider's reputation. This best illustrates:","options":["a prohibition on the use of third-party research.","a requirement to agree with all external analysts.","reasonable care and independent professional judgment."],"correct":2,"why_vi":"Trong analysis, recommendations, investment actions và hoạt động chuyên môn khác, cần reasonable care và independent professional judgment. Thông tin từ người khác có thể hữu ích nhưng không được thay thế đánh giá độc lập phù hợp vai trò.","trap_vi":"Không đồng nhất independence với việc phải tự thu thập toàn bộ dữ liệu."},{"stem_en":"A supervisor encourages colleagues to raise ethical concerns and models sound professional conduct. This most directly reflects:","options":["an obligation to disclose all client files publicly.","a guarantee that misconduct cannot occur.","practicing and encouraging ethical professional behavior."],"correct":2,"why_vi":"Không chỉ tự hành xử chuyên nghiệp và đạo đức, member/candidate còn khuyến khích người khác thực hành như vậy, góp phần tạo uy tín cho bản thân và profession. Mentoring, nêu gương và cải tiến văn hóa là các cách hỗ trợ.","trap_vi":"Không hiểu khuyến khích ethics là quyền công khai mọi hồ sơ bí mật."},{"stem_en":"A trader refuses to take part in conduct intended to undermine reliable market pricing. Which Code objective is most directly supported?","options":["Integrity and viability of global capital markets for society's benefit.","A guarantee that security prices never decline.","Priority of the trader's annual compensation."],"correct":0,"why_vi":"Nguyên tắc nhấn mạnh tính toàn vẹn và khả năng tồn tại bền vững của global capital markets vì lợi ích cuối cùng của xã hội. Một quyết định cá nhân có thể đóng góp vào thị trường minh bạch hoặc làm suy yếu niềm tin khi nhiều hành vi xấu tích tụ.","trap_vi":"Không bỏ phần ultimate benefit of society khi hiểu mục tiêu của Code."},{"stem_en":"A specialist enters a new investment field and obtains training while sharing relevant knowledge with colleagues. This most directly reflects:","options":["a guarantee of successful performance in the new field.","maintaining and improving professional competence.","a requirement to obtain a separate CFA charter for each specialization."],"correct":1,"why_vi":"Member/candidate phải duy trì và cải thiện năng lực nghề nghiệp, đồng thời cố gắng duy trì và nâng cao năng lực của người khác trong ngành. Chuẩn mới I(E) làm rõ yêu cầu competence theo vai trò cụ thể; không áp đặt một chương trình continuing education duy nhất.","trap_vi":"Phân biệt nghĩa vụ duy trì competence với một số giờ CPD bắt buộc không được nêu trong Standard I(E)."},{"stem_en":"Which sub-standard belongs to Standard I, Professionalism?","options":["Fair Dealing.","Referral Fees.","Competence."],"correct":2,"why_vi":"Nhóm I bao gồm I(A) Knowledge of the Law, I(B) Independence and Objectivity, I(C) Misrepresentation, I(D) Misconduct, I(E) Competence. Nhóm tập trung vào cách cá nhân hành nghề: luật, phán đoán, trung thực, integrity và năng lực.","trap_vi":"I(E) là mục thứ năm của Standard I; nhớ đủ năm mục theo văn bản CFAI 2026."},{"stem_en":"Which pair belongs to Standard II?","options":["Material Nonpublic Information and Market Manipulation.","Priority of Transactions and Referral Fees.","Performance Presentation and Record Retention."],"correct":0,"why_vi":"Nhóm II gồm II(A) Material Nonpublic Information và II(B) Market Manipulation. Mục tiêu là bảo vệ tính toàn vẹn của thông tin và cơ chế hình thành giá, không cho phép dùng thông tin trọng yếu chưa công khai hay thao túng để gây hiểu lầm.","trap_vi":"Không xếp market manipulation vào suitability chỉ vì có tác động khách hàng."},{"stem_en":"Which sub-standard is part of Duties to Clients?","options":["Preservation of Confidentiality.","Additional Compensation Arrangements.","Responsibilities of Supervisors."],"correct":0,"why_vi":"Nhóm III gồm III(A) Loyalty, Prudence, and Care; III(B) Fair Dealing; III(C) Suitability; III(D) Performance Presentation; III(E) Preservation of Confidentiality. Tập trung bảo vệ quyền lợi, công bằng, tính phù hợp, thông tin hiệu quả đầu tư và bảo mật.","trap_vi":"Loyalty ở III(A) là với clients, khác IV(A) Loyalty với employers."},{"stem_en":"Which group includes Responsibilities of Supervisors?","options":["Standard III — Duties to Clients.","Standard IV — Duties to Employers.","Standard VI — Conflicts of Interest."],"correct":1,"why_vi":"Nhóm IV gồm IV(A) Loyalty, IV(B) Additional Compensation Arrangements và IV(C) Responsibilities of Supervisors. Mục tiêu là bảo vệ nghĩa vụ trong quan hệ lao động, xử lý compensation xung đột và giám sát người thuộc quyền.","trap_vi":"Không nhầm additional compensation với referral fee chỉ vì cả hai có thể là tiền."},{"stem_en":"Which sub-standard is concerned with records supporting investment analysis?","options":["III(D) Performance Presentation.","V(C) Record Retention.","I(D) Misconduct."],"correct":1,"why_vi":"Nhóm V gồm V(A) Diligence and Reasonable Basis, V(B) Communication with Clients and Prospective Clients và V(C) Record Retention. Đây là các yêu cầu về quy trình tạo cơ sở phân tích, truyền đạt và lưu bằng chứng.","trap_vi":"V(B) trong nguồn 2026 có yêu cầu nêu loại dịch vụ và chi phí."},{"stem_en":"Which title matches the 2026 wording of Standard VI(A)?","options":["Avoid or Disclose Conflicts.","Additional Compensation Arrangements.","Independence and Objectivity."],"correct":0,"why_vi":"Nhóm VI gồm VI(A) Avoid or Disclose Conflicts, VI(B) Priority of Transactions và VI(C) Referral Fees. Cần nhận diện và tránh xung đột khi hợp lý, công bố khi cần, ưu tiên giao dịch client/employer và minh bạch lợi ích giới thiệu.","trap_vi":"Tên hiện hành VI(A) không chỉ là Disclosure of Conflicts."},{"stem_en":"Which issue most directly belongs to Standard VII?","options":["Misrepresenting the implications of CFA Program candidacy.","Calculating portfolio standard deviation incorrectly by accident.","Disclosing a referral benefit to a prospective client."],"correct":0,"why_vi":"Nhóm VII gồm VII(A) Conduct as Participants in CFA Institute Programs và VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program. Nhóm bảo vệ integrity, validity và security của programs cũng như tính chính xác khi nói về membership, candidacy, designation.","trap_vi":"Không dùng CFA designation như lời bảo đảm performance."},{"stem_en":"A manager refuses to use an inaccurate sales claim even though it would increase revenue and a personal bonus. Which two Code objectives are most clearly reinforced?","options":["Guaranteed performance and identical client portfolios.","Personal profit maximization and employer revenue priority.","Integrity and prioritization of professional and client interests over self-interest."],"correct":2,"why_vi":"Integrity trong cách ứng xử và đặt client/profession trước personal interest. Không phải vì Code bảo đảm lợi nhuận mà vì honesty, professional judgment và client trust.","trap_vi":"Code principles express duties, not return guarantees."},{"stem_en":"A member uses a complex automated model for a new mandate and does not understand its major limitations. Which recent revision most directly clarifies the obligation to address the skill gap?","options":["VI(C) Referral Fees.","VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program.","I(E) Competence."],"correct":2,"why_vi":"Code principle 6 yêu cầu maintain/improve competence; 2023 revision thêm I(E). I(E) đòi năng lực phù hợp vai trò; cần học hoặc hỗ trợ phù hợp, không đòi một chương trình CPD cố định.","trap_vi":"The 2026 outline includes I(E), even if an older source omits it."},{"stem_en":"A firm's training manual calls VI(A) 'Disclosure of Conflicts' and says every conflict can be handled by a footnote. What update is necessary?","options":["Keep the old approach because all conflicts are cured by any disclosure.","Recognize avoidance where reasonably possible and full, fair, prominent, effective disclosure otherwise.","Prohibit every conceivable business conflict, regardless of facts."],"correct":1,"why_vi":"Tên 2026 là Avoid or Disclose Conflicts. Ưu tiên tránh khi hợp lý; nếu không, full fair prominent plain-language disclosure. Footnote mơ hồ không đảm bảo truyền đạt hiệu quả; một số hành vi bị cấm theo standards khác không chữa bằng disclosure.","trap_vi":"The revision emphasizes avoidance and effective disclosure, not a universal ban."},{"stem_en":"An advisory firm voluntarily adopts the CFA Code and Standards. Which claim is most appropriate?","options":["Its adoption means CFA Institute has independently verified the firm.","Its adoption automatically makes every employee a CFA Institute member.","It may communicate its adoption with the appropriate qualification that CFA Institute has not verified the claim."],"correct":2,"why_en":"Voluntary adoption does not constitute independent verification or confer membership.","why_vi":"Tự nguyện áp dụng không đồng nghĩa xác minh độc lập hay cấp tư cách thành viên.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 57–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 162–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 19–22","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Individual Code and Standards versus firm-level commitments"}],"cards":[{"front_en":"Code principle 1 — integrity, competence and respect","back_vi":"Nguyên tắc đầu tiên nhấn mạnh integrity, competence, diligence, respect và ứng xử có đạo đức với public, clients/prospective clients, employers, employees, colleagues và các market participants. Đây là phạm vi rộng hơn quan hệ với khách hàng trả phí. | Exam trap: Không chỉ áp dụng khi trực tiếp quản lý tài sản."},{"front_en":"Code principle 2 — profession and clients before self","back_vi":"Integrity của investment profession và lợi ích clients phải được đặt cao hơn lợi ích cá nhân. Nguyên tắc này kết nối client focus với niềm tin vào ngành; không được dùng khách hàng như công cụ đạt mục tiêu cá nhân. | Exam trap: Không hiểu client interest là lý do vượt qua market integrity hoặc applicable law."},{"front_en":"Code principle 3 — reasonable care and independent judgment","back_vi":"Trong analysis, recommendations, investment actions và hoạt động chuyên môn khác, cần reasonable care và independent professional judgment. Thông tin từ người khác có thể hữu ích nhưng không được thay thế đánh giá độc lập phù hợp vai trò. | Exam trap: Không đồng nhất independence với việc phải tự thu thập toàn bộ dữ liệu."},{"front_en":"Code principle 4 — encourage ethical professional practice","back_vi":"Không chỉ tự hành xử chuyên nghiệp và đạo đức, member/candidate còn khuyến khích người khác thực hành như vậy, góp phần tạo uy tín cho bản thân và profession. Mentoring, nêu gương và cải tiến văn hóa là các cách hỗ trợ. | Exam trap: Không hiểu khuyến khích ethics là quyền công khai mọi hồ sơ bí mật."},{"front_en":"Code principle 5 — capital market integrity and viability","back_vi":"Nguyên tắc nhấn mạnh tính toàn vẹn và khả năng tồn tại bền vững của global capital markets vì lợi ích cuối cùng của xã hội. Một quyết định cá nhân có thể đóng góp vào thị trường minh bạch hoặc làm suy yếu niềm tin khi nhiều hành vi xấu tích tụ. | Exam trap: Không bỏ phần ultimate benefit of society khi hiểu mục tiêu của Code."},{"front_en":"Code principle 6 — maintain and improve competence","back_vi":"Member/candidate phải duy trì và cải thiện năng lực nghề nghiệp, đồng thời cố gắng duy trì và nâng cao năng lực của người khác trong ngành. Chuẩn mới I(E) làm rõ yêu cầu competence theo vai trò cụ thể; không áp đặt một chương trình continuing education duy nhất. | Exam trap: Phân biệt nghĩa vụ duy trì competence với một số giờ CPD bắt buộc không được nêu trong Standard I(E)."},{"front_en":"Standard I — Professionalism","back_vi":"Nhóm I bao gồm I(A) Knowledge of the Law, I(B) Independence and Objectivity, I(C) Misrepresentation, I(D) Misconduct, I(E) Competence. Nhóm tập trung vào cách cá nhân hành nghề: luật, phán đoán, trung thực, integrity và năng lực. | Exam trap: I(E) là mục thứ năm của Standard I; nhớ đủ năm mục theo văn bản CFAI 2026."},{"front_en":"Standard II — Integrity of Capital Markets","back_vi":"Nhóm II gồm II(A) Material Nonpublic Information và II(B) Market Manipulation. Mục tiêu là bảo vệ tính toàn vẹn của thông tin và cơ chế hình thành giá, không cho phép dùng thông tin trọng yếu chưa công khai hay thao túng để gây hiểu lầm. | Exam trap: Không xếp market manipulation vào suitability chỉ vì có tác động khách hàng."},{"front_en":"Standard III — Duties to Clients","back_vi":"Nhóm III gồm III(A) Loyalty, Prudence, and Care; III(B) Fair Dealing; III(C) Suitability; III(D) Performance Presentation; III(E) Preservation of Confidentiality. Tập trung bảo vệ quyền lợi, công bằng, tính phù hợp, thông tin hiệu quả đầu tư và bảo mật. | Exam trap: Loyalty ở III(A) là với clients, khác IV(A) Loyalty với employers."},{"front_en":"Standard IV — Duties to Employers","back_vi":"Nhóm IV gồm IV(A) Loyalty, IV(B) Additional Compensation Arrangements và IV(C) Responsibilities of Supervisors. Mục tiêu là bảo vệ nghĩa vụ trong quan hệ lao động, xử lý compensation xung đột và giám sát người thuộc quyền. | Exam trap: Không nhầm additional compensation với referral fee chỉ vì cả hai có thể là tiền."},{"front_en":"Standard V — Investment Analysis, Recommendations, and Actions","back_vi":"Nhóm V gồm V(A) Diligence and Reasonable Basis, V(B) Communication with Clients and Prospective Clients và V(C) Record Retention. Đây là các yêu cầu về quy trình tạo cơ sở phân tích, truyền đạt và lưu bằng chứng. | Exam trap: V(B) trong nguồn 2026 có yêu cầu nêu loại dịch vụ và chi phí."},{"front_en":"Standard VI — Conflicts of Interest","back_vi":"Nhóm VI gồm VI(A) Avoid or Disclose Conflicts, VI(B) Priority of Transactions và VI(C) Referral Fees. Cần nhận diện và tránh xung đột khi hợp lý, công bố khi cần, ưu tiên giao dịch client/employer và minh bạch lợi ích giới thiệu. | Exam trap: Tên hiện hành VI(A) không chỉ là Disclosure of Conflicts."},{"front_en":"Standard VII — Responsibilities as a CFA Institute Member or CFA Candidate","back_vi":"Nhóm VII gồm VII(A) Conduct as Participants in CFA Institute Programs và VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program. Nhóm bảo vệ integrity, validity và security của programs cũng như tính chính xác khi nói về membership, candidacy, designation. | Exam trap: Không dùng CFA designation như lời bảo đảm performance."},{"front_en":"Six Code components — framework?","back_vi":"Integrity/competence/diligence/respect; profession and clients before self; care and independent judgment; practice and encourage ethics; market integrity and viability for society; maintain/improve competence · Sáu nguyên tắc ở mức khái quát. Học ý nghĩa và chủ thể, không chỉ thứ tự.  · Các sub-standards ở LOS 2.c cụ thể hóa yêu cầu; đây là bản diễn giải để học, không thay thế văn bản chính thức."},{"front_en":"Seven Standards and 23 sub-standards — framework?","back_vi":"I:5; II:2; III:5; IV:3; V:3; VI:3; VII:2 → 23 · I Professionalism; II Integrity of Capital Markets; III Duties to Clients; IV Duties to Employers; V Investment Analysis, Recommendations, and Actions; VI Conflicts of Interest; VII Responsibilities as a CFA Institute Member or CFA Candidate. · Số mục dùng để kiểm đủ outline 2026; V(B) có 5 yêu cầu nhưng vẫn là 1 sub-standard."},{"front_en":"2023 revisions used in 2026 — framework?","back_vi":"I(E) Competence; V(B) nature of services and costs; VI(A) Avoid or Disclose Conflicts · Ba điểm thay đổi cần cập nhật khi học từ notes cũ: competence theo vai trò, disclosure dịch vụ/chi phí, tránh conflict khi hợp lý hoặc disclose đầy đủ. · Slide SAPP trang 20 cũng có I(E); đọc theo sơ đồ bố cục, không bỏ dòng cuối khi trích xuất văn bản."},{"front_en":"A manager refuses to use an inaccurate sales claim even though it would increase revenue and a personal bonus. Which two Code objectives are most clearly reinforced?","back_vi":"Integrity and placing professional integrity/client interests above personal interests. — Integrity trong cách ứng xử và đặt client/profession trước personal interest. Không phải vì Code bảo đảm lợi nhuận mà vì honesty, professional judgment và client trust."},{"front_en":"A member uses a complex automated model for a new mandate and does not understand its major limitations. Which recent revision most directly clarifies the obligation to address the skill gap?","back_vi":"I(E) Competence. — Code principle 6 yêu cầu maintain/improve competence; 2023 revision thêm I(E). I(E) đòi năng lực phù hợp vai trò; cần học hoặc hỗ trợ phù hợp, không đòi một chương trình CPD cố định."},{"front_en":"A firm's training manual calls VI(A) 'Disclosure of Conflicts' and says every conflict can be handled by a footnote. What update is necessary?","back_vi":"Update VI(A) to Avoid or Disclose Conflicts and require effective disclosure when avoidance is not reasonable. — Tên 2026 là Avoid or Disclose Conflicts. Ưu tiên tránh khi hợp lý; nếu không, full fair prominent plain-language disclosure. Footnote mơ hồ không đảm bảo truyền đạt hiệu quả; một số hành vi bị cấm theo standards khác không chữa bằng disclosure."},{"front_en":"Individual Code and Standards versus firm-level commitments","back_en":"The Code and Standards govern members and candidates personally. A firm or nonmember can voluntarily adopt them, but a claim does not imply CFA Institute verified it. The Asset Manager Code is a distinct firm-oriented framework. Do not confuse either with GIPS performance-reporting compliance.","back_vi":"Code and Standards áp dụng cá nhân thành viên và ứng viên. Firm hoặc người không phải thành viên có thể tự nguyện áp dụng, nhưng claim không có nghĩa CFA Institute xác minh. Asset Manager Code là khung riêng hướng tới tổ chức quản lý tài sản. Không nhầm với tuân thủ báo cáo hiệu suất GIPS.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 57–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 162–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 19–22","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-02-LOS03","letter":"c","title_en":"Ethical Responsibilities under Each Sub-standard","outcome_en":"explain responsibilities under the Code and Standards, including each sub-section","overview_vi":"Bài 2.c: Ethical Responsibilities under Each Sub-standard. Học nguyên tắc, phân biệt nghĩa vụ và bẫy, rồi vận dụng vào tình huống tiếng Anh nguyên gốc. Các khung trong phần Công thức là khung định tính, không phải công thức toán. LM2 giới thiệu các sub-standard; hướng dẫn áp dụng chi tiết thuộc LM3. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 47 (LOS); pp. 49–51, 58–61 (content)"},{"id":"Kaplan SchweserNotes 2026 — Book 4, Reading 90","pages":"Physical PDF pp. 163–165"},{"id":"SAPP CFA Level I 2026 — Ethics slides","pages":"Physical PDF pp. 20–22"},{"id":"CFAI 2026 Volume 10 — selected supporting Guidance (LM3; not full coverage)","pages":"Physical PDF pp. 67–76, 90–107, 109–125, 126–161, 162–182, 183–209, 210–235 (selected passages for cross-standard distinctions)"}],"sections":[{"heading":"I(A) Knowledge of the Law","body":"Hiểu và tuân thủ laws, rules, regulations và Code and Standards áp dụng cho hoạt động chuyên môn; khi có khác biệt phải theo yêu cầu nghiêm hơn. Không knowingly participate hoặc assist vi phạm và phải dissociate. Việc nhắc cấp trên/compliance có thể là bước phù hợp nhưng nếu vẫn tiếp tục vi phạm thì chưa đủ.","trap":"Không phải lúc nào cũng phải tuân thủ CFA Standards thay cho luật; chọn yêu cầu áp dụng nghiêm hơn."},{"heading":"I(B) Independence and Objectivity","body":"Dùng reasonable care và judgment để duy trì independence/objectivity. Không offer, solicit hoặc accept gift, benefit, compensation hay consideration có thể được kỳ vọng hợp lý làm tổn hại tính độc lập của mình hoặc người khác. Đánh giá quan hệ, mục đích, mức độ và ảnh hưởng chứ không chỉ giá trị tiền.","trap":"Không phải mọi món quà đều bị cấm; tiêu chí chính là nguy cơ ảnh hưởng objectivity."},{"heading":"I(C) Misrepresentation","body":"Không knowingly misrepresent trong investment analysis, recommendations, actions hay hoạt động chuyên môn. Misrepresentation có thể xuất hiện trong thông tin sai lệch, trình bày gây hiểu lầm, bỏ sót facts quan trọng, mô tả năng lực hoặc nhận công lao của người khác. Cần phân biệt lỗi vô ý với hành vi knowingly misleading, dù lỗi vô ý có thể đặt vấn đề diligence.","trap":"Không coi việc ghi nguồn hình thức là đủ nếu vẫn diễn giải gây hiểu lầm."},{"heading":"I(D) Misconduct","body":"Không tham gia conduct chuyên môn có dishonesty, fraud hoặc deceit, hay hành vi phản ánh bất lợi tới professional reputation, integrity hoặc competence. Cần xem sự liên hệ giữa hành vi và phẩm chất nghề nghiệp; không suy diễn mọi tranh cãi đời tư đều là misconduct.","trap":"Không chỉ giới hạn misconduct ở giao dịch chứng khoán hoặc trường hợp có án hình sự."},{"heading":"I(E) Competence","body":"Phải hành động với và duy trì competence cần thiết để hoàn thành professional responsibilities. Mức năng lực phụ thuộc facts, nature và complexity của vai trò; có nhiều cách cập nhật, không có chương trình học cụ thể bắt buộc trong standard này. Khi nhận nhiệm vụ mới cần đánh giá khoảng trống kiến thức và bổ sung phù hợp.","trap":"I(E) là Standard mới trong sửa đổi 2023 được sử dụng trong 2026, không thể bỏ qua."},{"heading":"II(A) Material Nonpublic Information","body":"Người nắm thông tin vừa material vừa nonpublic có khả năng ảnh hưởng giá trị khoản đầu tư không được act hoặc cause others to act dựa trên thông tin đó. Cần đánh giá cả materiality lẫn mức độ công khai; thông tin chỉ được gửi tới một nhóm nhỏ không mặc nhiên là public.","trap":"Không chỉ cấm giao dịch cá nhân; gây người khác giao dịch cũng bị cấm."},{"heading":"II(B) Market Manipulation","body":"Không thực hiện hành vi bóp méo giá hoặc tạo khối lượng giao dịch giả tạo với intent to mislead market participants. Điểm mấu chốt là mục đích gây hiểu lầm; giao dịch hợp pháp vì nhu cầu thanh khoản hoặc triển khai chiến lược không tự động là manipulation.","trap":"Volume tăng không đủ để kết luận intent to mislead."},{"heading":"III(A) Loyalty, Prudence, and Care","body":"Có duty of loyalty với clients, hành động với reasonable care và prudent judgment, vì lợi ích của khách hàng và đặt client interests trước employer hoặc bản thân. Cần xác định đúng client và beneficiary trong bối cảnh quản lý tài sản; không bỏ qua ràng buộc luật và market integrity.","trap":"Prudent judgment không bảo đảm luôn sinh lời."},{"heading":"III(B) Fair Dealing","body":"Đối xử fair và objective với tất cả clients khi cung cấp research, recommendations, investment actions hay professional activities. Fair không nhất thiết identical: mức dịch vụ có thể khác nếu minh bạch và không làm khách hàng khác bị đối xử không công bằng; phân bổ cơ hội hữu hạn cần quy trình công bằng.","trap":"Không đồng nhất fair dealing với việc mọi tài khoản có cùng giao dịch, số lượng hoặc dịch vụ."},{"heading":"III(C) Suitability — advisory relationship","body":"Trước recommendation/action, reasonable inquiry về investment experience, risk/return objectives và financial constraints của current/prospective client; cập nhật thường xuyên. Xác định khoản đầu tư phù hợp tình hình tài chính, written objectives, mandates và constraints trong bối cảnh total portfolio.","trap":"Không chỉ xem risk của từng security riêng lẻ hoặc dựa vào tuổi khách hàng."},{"heading":"III(C) Suitability — specific mandate","body":"Khi quản lý portfolio theo mandate, strategy hoặc style xác định, chỉ đưa ra recommendations/actions phù hợp stated objectives và constraints của portfolio. Không cần bảo đảm pooled fund phù hợp mọi nhà đầu tư riêng lẻ khi không có advisory relationship, nhưng phải tôn trọng chính mandate.","trap":"Không nhầm nghĩa vụ quản lý fund mandate với thu thập IPS riêng của tất cả nhà đầu tư."},{"heading":"III(D) Performance Presentation","body":"Khi truyền đạt investment performance, phải reasonable efforts để fair, accurate và complete. Không cherry-pick thành tích tốt gây sai lệch, không trình bày simulated/hypothetical như actual, cần làm rõ dữ liệu và giới hạn liên quan. GIPS hỗ trợ trình bày nhưng III(D) không yêu cầu mọi cá nhân hoặc firm tự động claim GIPS compliance.","trap":"Không nhầm reasonable efforts với bảo đảm kết quả tương lai."},{"heading":"III(E) Preservation of Confidentiality","body":"Bảo mật thông tin current, former và prospective clients, trừ khi thông tin liên quan illegal activities của client/prospective client, luật yêu cầu disclosure hoặc client/prospective client cho phép disclosure. Xác định yêu cầu pháp lý thực tế trước khi tiết lộ, không coi một ngoại lệ là quyền công bố tùy ý cho bất cứ người nào.","trap":"Former clients vẫn thuộc phạm vi bảo mật."},{"heading":"IV(A) Loyalty to Employers","body":"Trong vấn đề liên quan employment, hành động vì lợi ích employer, không tước lợi ích từ kỹ năng của mình, không divulge confidential information hoặc gây hại employer. Nghĩa vụ này không vượt lên luật, market integrity hay client interests; cần cân nhắc facts khi chuẩn bị rời công ty.","trap":"Không đồng nhất loyalty với cấm đổi việc hoặc buộc làm theo mọi yêu cầu của sếp."},{"heading":"IV(B) Additional Compensation Arrangements","body":"Không accept gifts, benefits, compensation hay consideration cạnh tranh với hoặc có thể gây conflict với employer interest trừ khi có written consent từ tất cả parties involved. Xem xét cả lợi ích phi tiền tệ và conditional bonus; phân biệt với một món quà đe dọa objectivity theo I(B).","trap":"Consent phải bằng văn bản và từ all parties involved, không chỉ oral notice."},{"heading":"IV(C) Responsibilities of Supervisors","body":"Người có supervisory authority phải make reasonable efforts để bảo đảm người thuộc quyền tuân thủ applicable laws, rules, regulations và Code and Standards. Cần hệ thống phòng ngừa, phát hiện, xử lý và theo dõi phù hợp. Đây là reasonable efforts, không strict liability cho mọi hành vi của subordinate.","trap":"Không tự động kết luận supervisor vi phạm chỉ vì subordinate có vi phạm."},{"heading":"V(A) Diligence and Reasonable Basis","body":"Phân tích, recommendation và investment action cần diligence, independence, thoroughness cùng reasonable and adequate basis supported by appropriate research and investigation. Độ sâu nghiên cứu tùy sản phẩm và vai trò; sử dụng third-party research không loại bỏ trách nhiệm xem xét chất lượng.","trap":"Reasonable basis không có nghĩa prediction phải luôn đúng."},{"heading":"V(B) Communication — nature of services and costs","body":"CFAI 2026 yêu cầu disclose với clients và prospective clients bản chất services cung cấp cùng thông tin costs liên quan tới dịch vụ đó. Mục tiêu là informed decision về việc thuê professional/firm và ảnh hưởng tài chính; không chỉ công bố investment process hay rủi ro.","trap":"Đây là yêu cầu được bổ sung trong sửa đổi 2023; không bỏ sót khi học từ bản cũ."},{"heading":"V(B) Communication — process and material changes","body":"Disclose basic format và general principles của investment process dùng để phân tích, chọn securities và xây dựng portfolios; promptly disclose changes có thể materially affect process. Cần đủ để client hiểu cách quản lý, không bắt buộc tiết lộ mọi proprietary detail không cần thiết.","trap":"Không đợi kỳ báo cáo năm nếu thay đổi trọng yếu cần thông báo kịp thời."},{"heading":"V(B) Communication — risks, important factors and facts versus opinions","body":"Disclose significant limitations and risks của process, dùng reasonable judgment chọn important factors cần đưa vào communications, phân biệt facts và opinions trong analysis/recommendations. Forecast là opinion hoặc estimate, dù dựa trên dữ liệu; cần nêu assumptions quan trọng và tránh biến dự báo thành chắc chắn.","trap":"Không cần liệt kê mọi yếu tố không liên quan; trọng tâm là yếu tố quan trọng và significant risks."},{"heading":"V(C) Record Retention","body":"Develop và maintain appropriate records hỗ trợ investment analyses, recommendations, actions và communications. Tài liệu cần đủ để giải thích basis, không chỉ kết quả cuối; tuân thủ yêu cầu thời hạn từ luật hoặc firm nếu áp dụng. Guidance chi tiết về thời hạn sẽ học ở LM3.","trap":"Không biến một recommended period thành quy tắc bắt buộc trong mọi hoàn cảnh."},{"heading":"VI(A) Avoid or Disclose Conflicts","body":"Tránh xung đột nếu reasonably possible; nếu không, full and fair disclosure mọi vấn đề có thể reasonably impair independence/objectivity hoặc cản trở duties với clients, prospective clients, employer. Disclosure phải prominent, plain language và truyền đạt relevant information hiệu quả. Disclosure không hợp thức hóa một hành vi bị standard khác cấm.","trap":"Tên sửa đổi là Avoid or Disclose Conflicts; ưu tiên tránh khi hợp lý, không chỉ ghi chú nhỏ."},{"heading":"VI(B) Priority of Transactions","body":"Transactions cho clients và employers phải ưu tiên trước transactions mà member/candidate là beneficial owner. Không front-run orders hoặc sử dụng vị thế cá nhân để chiếm lợi thế từ giao dịch khách hàng; cần phân biệt beneficial ownership với việc thực hiện giao dịch cho người khác trong vai trò chuyên môn.","trap":"Personal trading không bị cấm tuyệt đối; điều quan trọng là priority và controls."},{"heading":"VI(C) Referral Fees","body":"Disclose cho employer, clients và prospective clients as appropriate về compensation, consideration hoặc benefit received from or paid to others do recommendation products/services. Có thể bao gồm tiền, lợi ích phi tiền tệ và thỏa thuận hai chiều; thông tin giúp bên nhận recommendation đánh giá bias và tổng chi phí.","trap":"Không chỉ disclose referral income nhận được; khoản trả cho người khác cũng thuộc phạm vi."},{"heading":"VII(A) Conduct as Participants in CFA Institute Programs","body":"Không thực hiện conduct làm tổn hại reputation/integrity của CFA Institute hoặc designation, hoặc integrity, validity, security của CFA Institute programs. Bao gồm tuân thủ testing policies và bảo mật nội dung thi không được phép công khai. Việc nêu quan điểm chung về chương trình khác với tiết lộ confidential exam content.","trap":"Không nhầm criticism hợp pháp về chương trình với tiết lộ câu hỏi bảo mật."},{"heading":"VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program","body":"Khi nói về CFA Institute, membership, designation hoặc candidacy, không misrepresent hay exaggerate ý nghĩa và hệ quả. Có thể trình bày chính xác tình trạng hoặc thành tích hợp lệ, không gọi một người đã qua một level là partial charterholder hoặc bảo đảm superior performance nhờ credential.","trap":"Không đánh đồng passing exams, active candidacy, membership và holding the charter."},{"heading":"Multiple applicable standards","body":"Một hành vi có thể đặt vấn đề nhiều Standards. Tách actor, duty, facts, knowledge/intent, timing, recipient, required disclosure hoặc consent và exceptions; sau đó chọn standard hoặc action được hỏi chính xác. Không coi việc đáp ứng một standard là miễn trừ những standard khác.","trap":"Câu hỏi most directly không yêu cầu liệt kê mọi vi phạm có thể tồn tại."},{"heading":"2023 revision: competence as a role-specific duty","body":"I(E) nêu rõ năng lực phù hợp vai trò. Chuyển sang chuyên môn mới có thể cần kiến thức mới trước khi thực hiện độc lập. Năng lực xét theo bối cảnh; không quy định một chương trình đào tạo bắt buộc cụ thể, và kết quả đầu tư xấu không tự chứng minh thiếu năng lực.","body_en":"Standard I(E) makes role-appropriate competence explicit. A move into a new specialty can require new knowledge before independently performing responsibilities. Competence is assessed in context; no single mandatory continuing-education program is specified, and a poor investment result alone does not demonstrate incompetence.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 58–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 163–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 20–22","origin":"studyhub","review_status":"targeted_source_comparison_v73"},{"heading":"2023 revision: communication of service scope and costs","body":"V(B) nêu rõ bản chất dịch vụ và thông tin chi phí liên quan, kể cả với khách hàng tiềm năng. Công bố này bổ sung chứ không thay thế giải thích quy trình đầu tư, thay đổi trọng yếu, rủi ro/giới hạn và phân biệt dữ kiện với ý kiến.","body_en":"V(B) explicitly includes the nature of services and information about associated client costs, including for prospective clients. That disclosure supplements, rather than replaces, explanation of the investment process, material changes, relevant risks and limitations, and distinctions between facts and opinions.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 58–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 163–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 20–22","origin":"studyhub","review_status":"targeted_source_comparison_v73"},{"heading":"2023 revision: avoidance and effective conflict disclosure","body":"VI(A) ưu tiên tránh xung đột khi hợp lý. Khi không thể tránh hợp lý, phải công bố đầy đủ, công bằng, nổi bật và dễ hiểu cho các khách hàng, khách tiềm năng và chủ lao động liên quan. Công bố không hợp thức hóa hành vi bị chuẩn mực khác cấm.","body_en":"VI(A) prefers avoiding conflicts when reasonably possible. Where a conflict cannot reasonably be avoided, disclosure must be complete, fair, prominent and understandable to affected clients, prospects and employer as relevant. Disclosure does not cure conduct separately prohibited by another standard.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 58–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 163–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 20–22","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Standards issue spotting","expr":"Actor → relevant duty → facts and knowledge/intent → applicable rule → exception → action → reasoning","meaning":"Đọc đúng vai trò, facts, đối tượng nhận thông tin, timing và điều kiện. Nếu nhiều standards, phân biệt vấn đề câu hỏi yêu cầu và các vi phạm khác.","conditions":"Không gắn nhãn chỉ vì một từ khóa xuất hiện trong stem."},{"name":"Consent vs disclosure vs prohibition","expr":"I(B): protect independence; IV(B): written consent all parties; VI(A): avoid or disclose; VI(C): referral disclosure; II(A): no action on MNPI","meaning":"Đừng sử dụng disclosure như một biện pháp chữa mọi hành vi. Written consent, disclosure và prohibition có điều kiện khác nhau.","conditions":"Nếu hành vi vi phạm một standard độc lập, đáp ứng standard khác không miễn trừ vi phạm."},{"name":"Client duties map","expr":"III(A) best interests; III(B) fair/objective treatment; III(C) suitability/mandate; III(D) fair/accurate/complete performance; III(E) confidentiality","meaning":"Phân biệt năm duty theo hành vi được hỏi.","conditions":"Có thể có nhiều vi phạm; không suy ra lỗ vốn là proof of unsuitability."},{"name":"Research and communication","expr":"V(A) basis; V(B) communication; V(C) records","meaning":"V(A) chất lượng quá trình và cơ sở; V(B) dịch vụ/chi phí, process, risk, important factors, fact/opinion; V(C) bằng chứng lưu trữ.","conditions":"Một report có reasonable basis vẫn có thể thiếu disclosure; ngược lại lưu records đầy đủ chưa chứng minh basis hợp lý."},{"name":"Conflicts of interest map","expr":"VI(A) avoid/disclose conflicts; VI(B) client/employer transactions first; VI(C) disclose referral benefits","meaning":"Ba vấn đề khác nhau: conflict ảnh hưởng judgment, priority đối với beneficial ownership, compensation cho recommendation.","conditions":"Không coi tất cả conflicts là cấm tuyệt đối; cần xét yêu cầu cụ thể và standards liên quan."},{"name":"Confidentiality exceptions under III(E)","expr":"Illegal activities of client/prospective client; legal requirement; client/prospective client permission","meaning":"Bảo mật áp dụng cho current, former và prospective clients. Chỉ áp dụng ngoại lệ phù hợp và cân nhắc luật.","conditions":"Không công bố tùy tiện khi có một nghi ngờ chưa xác định; tìm legal/compliance guidance khi cần."},{"name":"CFA program reference","expr":"Accurately state membership, designation or candidacy; do not exaggerate implications; protect exam integrity","meaning":"VII(A) bảo vệ integrity và security chương trình; VII(B) mô tả chính xác trạng thái và ý nghĩa credential.","conditions":"Không dùng partial designation, return guarantee, hoặc confidential exam details."}],"examples":[{"question_en":"A member receives a cash bonus offer from a client for outperforming a benchmark. The bonus could conflict with the employer's interests. The member emails the supervisor about it but has not obtained consent. What is required before acceptance?","steps_vi":["IV(B) applies because compensation may conflict with employer interest. Notification is not written consent.","Obtain written consent from all parties involved before accepting; evaluate other duties, including independence if relevant."],"answer":"Written consent from all parties involved before accepting the arrangement.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"An adviser identifies an unavoidable potential conflict and makes a prominent disclosure to the appropriate parties. The adviser then learns material nonpublic information and buys securities based on it. Which statement is most accurate?","steps_vi":["VI(A) disclosure may address conflict but II(A) independently prohibits acting or causing others to act on MNPI.","Client benefit or disclosure does not cure II(A); do not act on the information."],"answer":"The trade violates II(A) regardless of the conflict disclosure.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A manager publishes a positive recommendation with an adequate research basis but provides clients no information about a significant process risk. Which issue remains?","steps_vi":["V(A) reasonable basis appears satisfied under stated facts; V(B) requires disclosure of significant limitations and risks.","Analyze communication separately from quality of research; add appropriate disclosure."],"answer":"V(B) Communication with Clients and Prospective Clients.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A pooled fund has a stated small-cap equity mandate. Its manager buys a large-cap bond portfolio outside the mandate because the manager expects high returns. Some investors personally prefer bonds. Which standard is most directly relevant?","steps_vi":["III(C) requires consistency with fund's stated mandate, strategy, style and constraints.","Individual investor preferences do not excuse action outside the mandate. Expected return does not cure suitability issue."],"answer":"III(C) Suitability, specifically the duty to comply with the mandate.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"An adviser receives a noncash benefit from a third-party service provider for referring potential clients. The adviser believes the service is good value. What should the adviser do?","steps_vi":["VI(C) includes compensation, consideration or benefits paid or received for recommendations, not only cash.","Disclose the referral arrangement to employer and clients/prospective clients as appropriate so they understand potential influence."],"answer":"Disclose the referral benefit to the appropriate parties.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A departing analyst is offered a new job. She plans to use general experience and skills but does not take employer records or solicit clients before leaving. Which conclusion is most defensible from the stated facts?","steps_vi":["IV(A) prohibits harming employer and depriving it of skills while employed, or taking confidential information. General skills and lawful career change are distinct from employer proprietary records.","Given no solicitation, record taking, or other harm stated, job change itself is not automatically a violation; additional facts could change the outcome."],"answer":"Changing employers alone does not establish an IV(A) violation.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A supervisor implements reasonable compliance procedures and responds promptly after detecting an employee's violation. Which statement is most accurate?","steps_vi":["IV(C) requires reasonable efforts, not guaranteed absence of violations. Facts about effectiveness and response matter.","The existence of a subordinate violation alone does not prove supervisory failure."],"answer":"A subordinate's violation does not by itself establish a violation by the supervisor.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A firm offers two disclosed service tiers. Premium clients receive additional detailed research meetings, while all similarly situated clients receive significant recommendation changes fairly. Which standard distinction matters?","steps_vi":["III(B) fair and objective treatment does not require identical services; disclosed levels may differ provided fair treatment remains.","Facts specify equal fairness for important recommendations; additional meetings alone do not show a violation."],"answer":"Fair dealing does not require identical services under every arrangement.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A former client has not authorized disclosure. A colleague requests the client's transaction history for an unrelated personal purpose. No legal obligation or illegal activity exception applies. What should the adviser do?","steps_vi":["III(E) covers former clients in addition to current and prospective clients.","Không có ngoại lệ phù hợp; từ chối tiết lộ và bảo vệ hồ sơ."],"answer":"Preserve confidentiality.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A manager recommends an investment supported by reasonable research. The investment declines sharply due to unexpected economic news. Which conclusion is most accurate based solely on these facts?","steps_vi":["V(A) requires diligence/reasonable basis rather than accurate predictions. III(A) and III(C) also depend on conduct and suitability facts, not simply outcome.","A negative return is not sufficient evidence of a standard violation."],"answer":"No violation can be inferred solely from the negative outcome.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"An analyst's report contains a correctly labeled forecast but the analyst intentionally excludes known facts that would materially change readers' understanding. Which concern is most directly raised?","steps_vi":["Fact/opinion labeling is part of V(B), but knowingly misleading omission also raises I(C).","Correct labeling of one estimate cannot excuse deliberate misrepresentation in the broader report."],"answer":"I(C) Misrepresentation remains relevant despite the forecast label.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A candidate accurately states that she passed Level II but also claims this credential guarantees superior investment returns. Which aspect violates the Standards?","steps_vi":["VII(B) permits factual statements of achievements but prohibits exaggerating designation or program implications.","Guarantee of superior performance is unsupported by passing an exam and misrepresents implications."],"answer":"The assertion of guaranteed superior investment returns.","check":"Original conceptual vignette; conclusion limited to stated facts."},{"question_en":"A candidate discusses the exam's general difficulty without revealing questions or confidential topic specifics, while another candidate distributes recalled confidential questions. Which statement is most accurate?","steps_vi":["VII(A) protects program integrity/security and confidential exam information. General nonconfidential opinion differs from disclosure of exam questions.","The second action is prohibited; the first as stated is not automatically a violation."],"answer":"Sharing confidential questions violates VII(A); general nonconfidential opinions do not by themselves establish a violation.","check":"Original conceptual vignette; conclusion limited to stated facts."}],"questions":[{"stem_en":"Local rules permit a member to do something expressly prohibited by an applicable professional standard. What should the member do?","options":["Follow local rules because they always override professional standards.","Follow the more stringent applicable requirement.","Seek the client's permission to ignore the professional standard."],"correct":1,"why_vi":"Hiểu và tuân thủ laws, rules, regulations và Code and Standards áp dụng cho hoạt động chuyên môn; khi có khác biệt phải theo yêu cầu nghiêm hơn. Không knowingly participate hoặc assist vi phạm và phải dissociate. Việc nhắc cấp trên/compliance có thể là bước phù hợp nhưng nếu vẫn tiếp tục vi phạm thì chưa đủ.","trap_vi":"Không phải lúc nào cũng phải tuân thủ CFA Standards thay cho luật; chọn yêu cầu áp dụng nghiêm hơn."},{"stem_en":"An issuer offers a luxury vacation only if an analyst publishes a favorable rating. Which standard is most directly implicated?","options":["III(E) Preservation of Confidentiality.","V(C) Record Retention.","I(B) Independence and Objectivity."],"correct":2,"why_vi":"Dùng reasonable care và judgment để duy trì independence/objectivity. Không offer, solicit hoặc accept gift, benefit, compensation hay consideration có thể được kỳ vọng hợp lý làm tổn hại tính độc lập của mình hoặc người khác. Đánh giá quan hệ, mục đích, mức độ và ảnh hưởng chứ không chỉ giá trị tiền.","trap_vi":"Không phải mọi món quà đều bị cấm; tiêu chí chính là nguy cơ ảnh hưởng objectivity."},{"stem_en":"An analyst knowingly presents another researcher's forecast as her own without attribution. Which standard most directly addresses the conduct?","options":["II(B) Market Manipulation.","IV(C) Responsibilities of Supervisors.","I(C) Misrepresentation."],"correct":2,"why_vi":"Không knowingly misrepresent trong investment analysis, recommendations, actions hay hoạt động chuyên môn. Misrepresentation có thể xuất hiện trong thông tin sai lệch, trình bày gây hiểu lầm, bỏ sót facts quan trọng, mô tả năng lực hoặc nhận công lao của người khác. Cần phân biệt lỗi vô ý với hành vi knowingly misleading, dù lỗi vô ý có thể đặt vấn đề diligence.","trap_vi":"Không coi việc ghi nguồn hình thức là đủ nếu vẫn diễn giải gây hiểu lầm."},{"stem_en":"A manager falsifies business expense receipts for personal gain. Which standard is most directly concerned with dishonesty in this conduct?","options":["III(C) Suitability.","I(D) Misconduct.","V(B) Communication with Clients and Prospective Clients."],"correct":1,"why_vi":"Không tham gia conduct chuyên môn có dishonesty, fraud hoặc deceit, hay hành vi phản ánh bất lợi tới professional reputation, integrity hoặc competence. Cần xem sự liên hệ giữa hành vi và phẩm chất nghề nghiệp; không suy diễn mọi tranh cãi đời tư đều là misconduct.","trap_vi":"Không chỉ giới hạn misconduct ở giao dịch chứng khoán hoặc trường hợp có án hình sự."},{"stem_en":"A manager takes responsibility for a complex strategy despite lacking necessary expertise and makes no effort to acquire it. Which standard most directly addresses this issue?","options":["III(D) Performance Presentation.","I(E) Competence.","VI(C) Referral Fees."],"correct":1,"why_vi":"Phải hành động với và duy trì competence cần thiết để hoàn thành professional responsibilities. Mức năng lực phụ thuộc facts, nature và complexity của vai trò; có nhiều cách cập nhật, không có chương trình học cụ thể bắt buộc trong standard này. Khi nhận nhiệm vụ mới cần đánh giá khoảng trống kiến thức và bổ sung phù hợp.","trap_vi":"I(E) là Standard mới trong sửa đổi 2023 được sử dụng trong 2026, không thể bỏ qua."},{"stem_en":"A member receives confidential price-sensitive acquisition information and tells a friend to buy shares. Which standard most directly prohibits the action?","options":["II(A) Material Nonpublic Information.","VI(B) Priority of Transactions.","III(D) Performance Presentation."],"correct":0,"why_vi":"Người nắm thông tin vừa material vừa nonpublic có khả năng ảnh hưởng giá trị khoản đầu tư không được act hoặc cause others to act dựa trên thông tin đó. Cần đánh giá cả materiality lẫn mức độ công khai; thông tin chỉ được gửi tới một nhóm nhỏ không mặc nhiên là public.","trap_vi":"Không chỉ cấm giao dịch cá nhân; gây người khác giao dịch cũng bị cấm."},{"stem_en":"A trader executes offsetting trades solely to create the appearance of strong demand. Which standard most directly applies?","options":["II(B) Market Manipulation.","III(B) Fair Dealing.","I(E) Competence."],"correct":0,"why_vi":"Không thực hiện hành vi bóp méo giá hoặc tạo khối lượng giao dịch giả tạo với intent to mislead market participants. Điểm mấu chốt là mục đích gây hiểu lầm; giao dịch hợp pháp vì nhu cầu thanh khoản hoặc triển khai chiến lược không tự động là manipulation.","trap_vi":"Volume tăng không đủ để kết luận intent to mislead."},{"stem_en":"A portfolio manager selects a costly service provider solely to benefit the manager personally, although it disadvantages the client. Which standard most directly establishes the duty to put the client first?","options":["III(A) Loyalty, Prudence, and Care.","IV(A) Loyalty.","VII(A) Conduct as Participants in CFA Institute Programs."],"correct":0,"why_vi":"Có duty of loyalty với clients, hành động với reasonable care và prudent judgment, vì lợi ích của khách hàng và đặt client interests trước employer hoặc bản thân. Cần xác định đúng client và beneficiary trong bối cảnh quản lý tài sản; không bỏ qua ràng buộc luật và market integrity.","trap_vi":"Prudent judgment không bảo đảm luôn sinh lời."},{"stem_en":"A manager deliberately gives favored clients a material recommendation well before similarly situated clients without a disclosed basis. Which standard most directly applies?","options":["V(C) Record Retention.","I(E) Competence.","III(B) Fair Dealing."],"correct":2,"why_vi":"Đối xử fair và objective với tất cả clients khi cung cấp research, recommendations, investment actions hay professional activities. Fair không nhất thiết identical: mức dịch vụ có thể khác nếu minh bạch và không làm khách hàng khác bị đối xử không công bằng; phân bổ cơ hội hữu hạn cần quy trình công bằng.","trap_vi":"Không đồng nhất fair dealing với việc mọi tài khoản có cùng giao dịch, số lượng hoặc dịch vụ."},{"stem_en":"Before recommending a leveraged investment to a new advisory client, a member should first:","options":["obtain relevant client objectives, experience and constraints and assess total-portfolio suitability.","recommend the investment if it was profitable last year.","assume suitability if the client is willing to sign a purchase order."],"correct":0,"why_vi":"Trước recommendation/action, reasonable inquiry về investment experience, risk/return objectives và financial constraints của current/prospective client; cập nhật thường xuyên. Xác định khoản đầu tư phù hợp tình hình tài chính, written objectives, mandates và constraints trong bối cảnh total portfolio.","trap_vi":"Không chỉ xem risk của từng security riêng lẻ hoặc dựa vào tuổi khách hàng."},{"stem_en":"A manager of a stated short-duration bond fund buys long-duration bonds outside the fund's mandate to seek higher returns. Which duty is most directly violated?","options":["Keeping all fund investors' personal information under III(E).","Reporting the manager's annual professional conduct statement.","Managing the portfolio consistently with its stated objectives and constraints under III(C)."],"correct":2,"why_vi":"Khi quản lý portfolio theo mandate, strategy hoặc style xác định, chỉ đưa ra recommendations/actions phù hợp stated objectives và constraints của portfolio. Không cần bảo đảm pooled fund phù hợp mọi nhà đầu tư riêng lẻ khi không có advisory relationship, nhưng phải tôn trọng chính mandate.","trap_vi":"Không nhầm nghĩa vụ quản lý fund mandate với thu thập IPS riêng của tất cả nhà đầu tư."},{"stem_en":"A firm advertises only successful portfolios in a way that implies the results represent its complete performance history. Which standard most directly addresses the presentation?","options":["III(D) Performance Presentation.","II(A) Material Nonpublic Information.","IV(B) Additional Compensation Arrangements."],"correct":0,"why_vi":"Khi truyền đạt investment performance, phải reasonable efforts để fair, accurate và complete. Không cherry-pick thành tích tốt gây sai lệch, không trình bày simulated/hypothetical như actual, cần làm rõ dữ liệu và giới hạn liên quan. GIPS hỗ trợ trình bày nhưng III(D) không yêu cầu mọi cá nhân hoặc firm tự động claim GIPS compliance.","trap_vi":"Không nhầm reasonable efforts với bảo đảm kết quả tương lai."},{"stem_en":"An adviser wishes to reveal a former client's holdings to an acquaintance. No permission, legal requirement or illegal activity is involved. The adviser should:","options":["disclose because the advisory relationship has ended.","disclose if the acquaintance promises not to trade.","preserve the client's confidentiality."],"correct":2,"why_vi":"Bảo mật thông tin current, former và prospective clients, trừ khi thông tin liên quan illegal activities của client/prospective client, luật yêu cầu disclosure hoặc client/prospective client cho phép disclosure. Xác định yêu cầu pháp lý thực tế trước khi tiết lộ, không coi một ngoại lệ là quyền công bố tùy ý cho bất cứ người nào.","trap_vi":"Former clients vẫn thuộc phạm vi bảo mật."},{"stem_en":"A departing employee secretly takes the employer's confidential client database for future commercial use. Which standard most directly addresses the employment duty?","options":["IV(A) Loyalty.","II(B) Market Manipulation.","VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program."],"correct":0,"why_vi":"Trong vấn đề liên quan employment, hành động vì lợi ích employer, không tước lợi ích từ kỹ năng của mình, không divulge confidential information hoặc gây hại employer. Nghĩa vụ này không vượt lên luật, market integrity hay client interests; cần cân nhắc facts khi chuẩn bị rời công ty.","trap_vi":"Không đồng nhất loyalty với cấm đổi việc hoặc buộc làm theo mọi yêu cầu của sếp."},{"stem_en":"A client offers a private performance bonus that could conflict with the member's employer's interests. Before acceptance, the member must obtain:","options":["only verbal approval from the client.","written consent from all parties involved.","approval from the member's family."],"correct":1,"why_vi":"Không accept gifts, benefits, compensation hay consideration cạnh tranh với hoặc có thể gây conflict với employer interest trừ khi có written consent từ tất cả parties involved. Xem xét cả lợi ích phi tiền tệ và conditional bonus; phân biệt với một món quà đe dọa objectivity theo I(B).","trap_vi":"Consent phải bằng văn bản và từ all parties involved, không chỉ oral notice."},{"stem_en":"A supervisor learns that an employee may have bypassed trading controls and does nothing despite having authority to investigate. Which standard most directly concerns the supervisor?","options":["IV(C) Responsibilities of Supervisors.","VI(C) Referral Fees.","III(D) Performance Presentation."],"correct":0,"why_vi":"Người có supervisory authority phải make reasonable efforts để bảo đảm người thuộc quyền tuân thủ applicable laws, rules, regulations và Code and Standards. Cần hệ thống phòng ngừa, phát hiện, xử lý và theo dõi phù hợp. Đây là reasonable efforts, không strict liability cho mọi hành vi của subordinate.","trap_vi":"Không tự động kết luận supervisor vi phạm chỉ vì subordinate có vi phạm."},{"stem_en":"An analyst issues a recommendation based solely on an unverified rumor without research. Which standard most directly addresses the lack of analytical support?","options":["VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program.","III(E) Preservation of Confidentiality.","V(A) Diligence and Reasonable Basis."],"correct":2,"why_vi":"Phân tích, recommendation và investment action cần diligence, independence, thoroughness cùng reasonable and adequate basis supported by appropriate research and investigation. Độ sâu nghiên cứu tùy sản phẩm và vai trò; sử dụng third-party research không loại bỏ trách nhiệm xem xét chất lượng.","trap_vi":"Reasonable basis không có nghĩa prediction phải luôn đúng."},{"stem_en":"A prospective client asks what advisory services are included and what costs will be charged. Which standard expressly addresses these disclosures?","options":["V(B) Communication with Clients and Prospective Clients.","VI(B) Priority of Transactions.","II(B) Market Manipulation."],"correct":0,"why_vi":"CFAI 2026 yêu cầu disclose với clients và prospective clients bản chất services cung cấp cùng thông tin costs liên quan tới dịch vụ đó. Mục tiêu là informed decision về việc thuê professional/firm và ảnh hưởng tài chính; không chỉ công bố investment process hay rủi ro.","trap_vi":"Đây là yêu cầu được bổ sung trong sửa đổi 2023; không bỏ sót khi học từ bản cũ."},{"stem_en":"A firm replaces its discretionary selection process with a materially different automated method. Under V(B), the firm should:","options":["promptly communicate the material process change to clients and prospective clients.","wait for clients to discover the change from their holdings.","report the change only if future performance is negative."],"correct":0,"why_vi":"Disclose basic format và general principles của investment process dùng để phân tích, chọn securities và xây dựng portfolios; promptly disclose changes có thể materially affect process. Cần đủ để client hiểu cách quản lý, không bắt buộc tiết lộ mọi proprietary detail không cần thiết.","trap_vi":"Không đợi kỳ báo cáo năm nếu thay đổi trọng yếu cần thông báo kịp thời."},{"stem_en":"A report presents an uncertain earnings forecast as an established fact and omits a significant model limitation. Which standard most directly addresses both communication issues?","options":["VI(C) Referral Fees.","IV(A) Loyalty.","V(B) Communication with Clients and Prospective Clients."],"correct":2,"why_vi":"Disclose significant limitations and risks của process, dùng reasonable judgment chọn important factors cần đưa vào communications, phân biệt facts và opinions trong analysis/recommendations. Forecast là opinion hoặc estimate, dù dựa trên dữ liệu; cần nêu assumptions quan trọng và tránh biến dự báo thành chắc chắn.","trap_vi":"Không cần liệt kê mọi yếu tố không liên quan; trọng tâm là yếu tố quan trọng và significant risks."},{"stem_en":"An analyst deletes the only supporting records for an investment recommendation immediately after publication. Which standard most directly concerns the records?","options":["III(B) Fair Dealing.","II(B) Market Manipulation.","V(C) Record Retention."],"correct":2,"why_vi":"Develop và maintain appropriate records hỗ trợ investment analyses, recommendations, actions và communications. Tài liệu cần đủ để giải thích basis, không chỉ kết quả cuối; tuân thủ yêu cầu thời hạn từ luật hoặc firm nếu áp dụng. Guidance chi tiết về thời hạn sẽ học ở LM3.","trap_vi":"Không biến một recommended period thành quy tắc bắt buộc trong mọi hoàn cảnh."},{"stem_en":"An analyst cannot reasonably avoid a material ownership conflict and remains permitted to cover the issuer. What does VI(A) require?","options":["Full, fair, prominent disclosure in plain language to the relevant parties.","A vague reference buried in an unrelated appendix.","Disclosure only after a client complains."],"correct":0,"why_vi":"Tránh xung đột nếu reasonably possible; nếu không, full and fair disclosure mọi vấn đề có thể reasonably impair independence/objectivity hoặc cản trở duties với clients, prospective clients, employer. Disclosure phải prominent, plain language và truyền đạt relevant information hiệu quả. Disclosure không hợp thức hóa một hành vi bị standard khác cấm.","trap_vi":"Tên sửa đổi là Avoid or Disclose Conflicts; ưu tiên tránh khi hợp lý, không chỉ ghi chú nhỏ."},{"stem_en":"A member buys shares for her personal account before placing known pending client buy orders, seeking to benefit from the anticipated price effect. Which standard most directly addresses the priority issue?","options":["III(D) Performance Presentation.","V(C) Record Retention.","VI(B) Priority of Transactions."],"correct":2,"why_vi":"Transactions cho clients và employers phải ưu tiên trước transactions mà member/candidate là beneficial owner. Không front-run orders hoặc sử dụng vị thế cá nhân để chiếm lợi thế từ giao dịch khách hàng; cần phân biệt beneficial ownership với việc thực hiện giao dịch cho người khác trong vai trò chuyên môn.","trap_vi":"Personal trading không bị cấm tuyệt đối; điều quan trọng là priority và controls."},{"stem_en":"A member receives a noncash benefit for referring clients to a service provider. Which action is required under VI(C)?","options":["Disclose only cash payments, not noncash benefits.","Disclose the referral benefit to the appropriate employer and client or prospective client.","Avoid disclosure if the referred service is competitively priced."],"correct":1,"why_vi":"Disclose cho employer, clients và prospective clients as appropriate về compensation, consideration hoặc benefit received from or paid to others do recommendation products/services. Có thể bao gồm tiền, lợi ích phi tiền tệ và thỏa thuận hai chiều; thông tin giúp bên nhận recommendation đánh giá bias và tổng chi phí.","trap_vi":"Không chỉ disclose referral income nhận được; khoản trả cho người khác cũng thuộc phạm vi."},{"stem_en":"A candidate sends confidential examination questions to another candidate after the exam. Which standard most directly addresses this action?","options":["III(E) Preservation of Confidentiality.","VII(A) Conduct as Participants in CFA Institute Programs.","VI(C) Referral Fees."],"correct":1,"why_vi":"Không thực hiện conduct làm tổn hại reputation/integrity của CFA Institute hoặc designation, hoặc integrity, validity, security của CFA Institute programs. Bao gồm tuân thủ testing policies và bảo mật nội dung thi không được phép công khai. Việc nêu quan điểm chung về chương trình khác với tiết lộ confidential exam content.","trap_vi":"Không nhầm criticism hợp pháp về chương trình với tiết lộ câu hỏi bảo mật."},{"stem_en":"A candidate who passed Level I advertises that she holds a partial CFA charter. Which standard most directly addresses the claim?","options":["I(E) Competence.","III(B) Fair Dealing.","VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program."],"correct":2,"why_vi":"Khi nói về CFA Institute, membership, designation hoặc candidacy, không misrepresent hay exaggerate ý nghĩa và hệ quả. Có thể trình bày chính xác tình trạng hoặc thành tích hợp lệ, không gọi một người đã qua một level là partial charterholder hoặc bảo đảm superior performance nhờ credential.","trap_vi":"Không đánh đồng passing exams, active candidacy, membership và holding the charter."},{"stem_en":"A manager fully discloses a personal conflict but knowingly uses material nonpublic information to trade for clients. Which conclusion is most accurate?","options":["Full disclosure makes the trade permissible under every standard.","Disclosure of the conflict does not excuse the violation of II(A).","Client benefit overrides the material nonpublic information prohibition."],"correct":1,"why_vi":"Một hành vi có thể đặt vấn đề nhiều Standards. Tách actor, duty, facts, knowledge/intent, timing, recipient, required disclosure hoặc consent và exceptions; sau đó chọn standard hoặc action được hỏi chính xác. Không coi việc đáp ứng một standard là miễn trừ những standard khác.","trap_vi":"Câu hỏi most directly không yêu cầu liệt kê mọi vi phạm có thể tồn tại."},{"stem_en":"A member receives a cash bonus offer from a client for outperforming a benchmark. The bonus could conflict with the employer's interests. The member emails the supervisor about it but has not obtained consent. What is required before acceptance?","options":["Accept once the employer has received an email notification, even without consent.","Accept if the client gives verbal permission.","Obtain written consent from all parties involved before accepting."],"correct":2,"why_vi":"IV(B) applies because compensation may conflict with employer interest. Notification is not written consent. Obtain written consent from all parties involved before accepting; evaluate other duties, including independence if relevant.","trap_vi":"IV(B) requires written consent, not merely disclosure."},{"stem_en":"An adviser identifies an unavoidable potential conflict and makes a prominent disclosure to the appropriate parties. The adviser then learns material nonpublic information and buys securities based on it. Which statement is most accurate?","options":["The use of material nonpublic information is prohibited despite conflict disclosure.","The trade is permitted because disclosure satisfies VI(A).","The trade is permitted if the client benefits."],"correct":0,"why_vi":"VI(A) disclosure may address conflict but II(A) independently prohibits acting or causing others to act on MNPI. Client benefit or disclosure does not cure II(A); do not act on the information.","trap_vi":"Different standards may impose independent requirements."},{"stem_en":"A manager publishes a positive recommendation with an adequate research basis but provides clients no information about a significant process risk. Which issue remains?","options":["No violation can occur if V(A) is satisfied.","A potential violation of V(B) because significant process risks were not disclosed.","A violation of V(C) solely because research supported the recommendation."],"correct":1,"why_vi":"V(A) reasonable basis appears satisfied under stated facts; V(B) requires disclosure of significant limitations and risks. Analyze communication separately from quality of research; add appropriate disclosure.","trap_vi":"Diligence and communication are separate obligations."},{"stem_en":"A pooled fund has a stated small-cap equity mandate. Its manager buys a large-cap bond portfolio outside the mandate because the manager expects high returns. Some investors personally prefer bonds. Which standard is most directly relevant?","options":["III(E), because individual investor preferences are confidential.","III(C), because the action is inconsistent with the portfolio's stated mandate.","No violation if some investors personally prefer the new assets."],"correct":1,"why_vi":"III(C) requires consistency with fund's stated mandate, strategy, style and constraints. Individual investor preferences do not excuse action outside the mandate. Expected return does not cure suitability issue.","trap_vi":"Pooled portfolio mandate differs from personal advisory suitability."},{"stem_en":"An adviser receives a noncash benefit from a third-party service provider for referring potential clients. The adviser believes the service is good value. What should the adviser do?","options":["Do not disclose because no cash is paid.","Disclose the referral benefit to the employer and relevant clients or prospective clients, as appropriate.","Disclose only if the service later proves unsuitable."],"correct":1,"why_vi":"VI(C) includes compensation, consideration or benefits paid or received for recommendations, not only cash. Disclose the referral arrangement to employer and clients/prospective clients as appropriate so they understand potential influence.","trap_vi":"Good value does not eliminate referral disclosure duties."},{"stem_en":"A departing analyst is offered a new job. She plans to use general experience and skills but does not take employer records or solicit clients before leaving. Which conclusion is most defensible from the stated facts?","options":["The stated career change alone does not establish a violation of employer loyalty.","Accepting any new job automatically violates IV(A).","IV(A) authorizes the analyst to take confidential files after resignation."],"correct":0,"why_vi":"IV(A) prohibits harming employer and depriving it of skills while employed, or taking confidential information. General skills and lawful career change are distinct from employer proprietary records. Given no solicitation, record taking, or other harm stated, job change itself is not automatically a violation; additional facts could change the outcome.","trap_vi":"Do not infer undisclosed conduct or ban legitimate job mobility."},{"stem_en":"A supervisor implements reasonable compliance procedures and responds promptly after detecting an employee's violation. Which statement is most accurate?","options":["Any subordinate violation automatically proves supervisory misconduct.","Supervisors have no responsibility after adopting a written policy.","Assess the supervisor's reasonable efforts rather than presume automatic liability."],"correct":2,"why_vi":"IV(C) requires reasonable efforts, not guaranteed absence of violations. Facts about effectiveness and response matter. The existence of a subordinate violation alone does not prove supervisory failure.","trap_vi":"Supervisory liability is not automatic, but active oversight remains required."},{"stem_en":"A firm offers two disclosed service tiers. Premium clients receive additional detailed research meetings, while all similarly situated clients receive significant recommendation changes fairly. Which standard distinction matters?","options":["Any service tier automatically violates III(B).","Premium clients may always receive important recommendations before others.","Different disclosed services can be consistent with fair dealing when clients are treated fairly."],"correct":2,"why_vi":"III(B) fair and objective treatment does not require identical services; disclosed levels may differ provided fair treatment remains. Facts specify equal fairness for important recommendations; additional meetings alone do not show a violation.","trap_vi":"Fair is not identical, and different tiers do not justify unfair priority."},{"stem_en":"A former client has not authorized disclosure. A colleague requests the client's transaction history for an unrelated personal purpose. No legal obligation or illegal activity exception applies. What should the adviser do?","options":["Share the history because the client relationship has ended.","Refuse the request and maintain confidentiality.","Share the history if the colleague makes a verbal promise not to distribute it."],"correct":1,"why_vi":"III(E) covers former clients in addition to current and prospective clients. Không có ngoại lệ phù hợp; từ chối tiết lộ và bảo vệ hồ sơ.","trap_vi":"Termination of the relationship does not terminate confidentiality."},{"stem_en":"A manager recommends an investment supported by reasonable research. The investment declines sharply due to unexpected economic news. Which conclusion is most accurate based solely on these facts?","options":["The manager automatically violates V(A) whenever a security declines.","A loss alone does not establish a violation of V(A).","III(D) requires all performance to be positive."],"correct":1,"why_vi":"V(A) requires diligence/reasonable basis rather than accurate predictions. III(A) and III(C) also depend on conduct and suitability facts, not simply outcome. A negative return is not sufficient evidence of a standard violation.","trap_vi":"Evaluate conduct, not only outcome."},{"stem_en":"An analyst's report contains a correctly labeled forecast but the analyst intentionally excludes known facts that would materially change readers' understanding. Which concern is most directly raised?","options":["I(C) may be violated by a knowingly misleading omission.","The report is necessarily compliant because the forecast is labeled.","Only VII(A) can apply because an investment report is confidential."],"correct":0,"why_vi":"Fact/opinion labeling is part of V(B), but knowingly misleading omission also raises I(C). Correct labeling of one estimate cannot excuse deliberate misrepresentation in the broader report.","trap_vi":"Correct compliance with one element does not excuse misleading conduct."},{"stem_en":"A candidate accurately states that she passed Level II but also claims this credential guarantees superior investment returns. Which aspect violates the Standards?","options":["The claim that passing Level II guarantees superior returns.","The truthful statement that she passed Level II.","Both factual statements and any reference to CFA Institute are forbidden."],"correct":0,"why_vi":"VII(B) permits factual statements of achievements but prohibits exaggerating designation or program implications. Guarantee of superior performance is unsupported by passing an exam and misrepresents implications.","trap_vi":"Accurate achievement claims are distinct from exaggerated implications."},{"stem_en":"A candidate discusses the exam's general difficulty without revealing questions or confidential topic specifics, while another candidate distributes recalled confidential questions. Which statement is most accurate?","options":["Both candidates necessarily violate VII(A) merely by mentioning the exam.","Neither candidate can violate VII(A) once the exam has ended.","The candidate sharing confidential examination questions violates VII(A)."],"correct":2,"why_vi":"VII(A) protects program integrity/security and confidential exam information. General nonconfidential opinion differs from disclosure of exam questions. The second action is prohibited; the first as stated is not automatically a violation.","trap_vi":"Exam confidentiality continues after the exam; ordinary opinion is distinct."},{"stem_en":"A bond analyst is assigned an unfamiliar derivatives mandate. Which response best addresses I(E)?","options":["Develop the required competence and arrange appropriate qualified support before independently taking on unfamiliar responsibilities.","Assume a CFA charter establishes competence in every mandate.","Rely solely on whether the first trade is profitable."],"correct":0,"why_en":"The duty is role-specific and requires relevant capability, not a particular credential or a profitable outcome.","why_vi":"Nghĩa vụ theo vai trò, cần năng lực thực tế, không chỉ chứng chỉ hoặc giao dịch có lãi.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 58–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 163–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 20–22","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"2023 revision: competence as a role-specific duty"},{"stem_en":"An adviser gives prospective clients a detailed description of investment selection but omits information about the associated advisory costs. Which standard most directly addresses the missing disclosure?","options":["I(E) Competence.","V(B) Communication with Clients and Prospective Clients.","VII(B) Reference to CFA Institute."],"correct":1,"why_en":"The current V(B) explicitly covers service nature and associated costs.","why_vi":"V(B) hiện yêu cầu thông tin bản chất dịch vụ và chi phí liên quan.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 58–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 163–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 20–22","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"2023 revision: communication of service scope and costs"},{"stem_en":"An analyst can reasonably eliminate a material personal conflict before accepting an assignment. Which approach best reflects the revised VI(A)?","options":["Keep the conflict and hide it in a technical footnote.","Assume disclosure is never permitted.","Prefer avoiding the conflict; if it cannot reasonably be avoided, disclose it fully and clearly."],"correct":2,"why_en":"Avoidance is preferred where reasonable; effective disclosure is the alternative, not permission to violate other duties.","why_vi":"Ưu tiên tránh khi hợp lý; công bố hiệu quả là phương án thay thế, không miễn trừ nghĩa vụ khác.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 58–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 163–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 20–22","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"2023 revision: avoidance and effective conflict disclosure"},{"stem_en":"A manager discloses a conflict and then knowingly trades on material nonpublic information. Which statement is most accurate?","options":["The disclosure does not remove the separate prohibition under II(A).","Disclosure makes the transaction compliant with all standards.","Disclosure substitutes for assessing the information’s status."],"correct":0,"why_en":"Conflict disclosure cannot authorize a separate violation.","why_vi":"Công bố xung đột không cho phép vi phạm riêng biệt.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 58–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 163–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 20–22","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"2023 revision: avoidance and effective conflict disclosure"}],"cards":[{"front_en":"I(A) Knowledge of the Law","back_vi":"Hiểu và tuân thủ laws, rules, regulations và Code and Standards áp dụng cho hoạt động chuyên môn; khi có khác biệt phải theo yêu cầu nghiêm hơn. Không knowingly participate hoặc assist vi phạm và phải dissociate. Việc nhắc cấp trên/compliance có thể là bước phù hợp nhưng nếu vẫn tiếp tục vi phạm thì chưa đủ. | Exam trap: Không phải lúc nào cũng phải tuân thủ CFA Standards thay cho luật; chọn yêu cầu áp dụng nghiêm hơn."},{"front_en":"I(B) Independence and Objectivity","back_vi":"Dùng reasonable care và judgment để duy trì independence/objectivity. Không offer, solicit hoặc accept gift, benefit, compensation hay consideration có thể được kỳ vọng hợp lý làm tổn hại tính độc lập của mình hoặc người khác. Đánh giá quan hệ, mục đích, mức độ và ảnh hưởng chứ không chỉ giá trị tiền. | Exam trap: Không phải mọi món quà đều bị cấm; tiêu chí chính là nguy cơ ảnh hưởng objectivity."},{"front_en":"I(C) Misrepresentation","back_vi":"Không knowingly misrepresent trong investment analysis, recommendations, actions hay hoạt động chuyên môn. Misrepresentation có thể xuất hiện trong thông tin sai lệch, trình bày gây hiểu lầm, bỏ sót facts quan trọng, mô tả năng lực hoặc nhận công lao của người khác. Cần phân biệt lỗi vô ý với hành vi knowingly misleading, dù lỗi vô ý có thể đặt vấn đề diligence. | Exam trap: Không coi việc ghi nguồn hình thức là đủ nếu vẫn diễn giải gây hiểu lầm."},{"front_en":"I(D) Misconduct","back_vi":"Không tham gia conduct chuyên môn có dishonesty, fraud hoặc deceit, hay hành vi phản ánh bất lợi tới professional reputation, integrity hoặc competence. Cần xem sự liên hệ giữa hành vi và phẩm chất nghề nghiệp; không suy diễn mọi tranh cãi đời tư đều là misconduct. | Exam trap: Không chỉ giới hạn misconduct ở giao dịch chứng khoán hoặc trường hợp có án hình sự."},{"front_en":"I(E) Competence","back_vi":"Phải hành động với và duy trì competence cần thiết để hoàn thành professional responsibilities. Mức năng lực phụ thuộc facts, nature và complexity của vai trò; có nhiều cách cập nhật, không có chương trình học cụ thể bắt buộc trong standard này. Khi nhận nhiệm vụ mới cần đánh giá khoảng trống kiến thức và bổ sung phù hợp. | Exam trap: I(E) là Standard mới trong sửa đổi 2023 được sử dụng trong 2026, không thể bỏ qua."},{"front_en":"II(A) Material Nonpublic Information","back_vi":"Người nắm thông tin vừa material vừa nonpublic có khả năng ảnh hưởng giá trị khoản đầu tư không được act hoặc cause others to act dựa trên thông tin đó. Cần đánh giá cả materiality lẫn mức độ công khai; thông tin chỉ được gửi tới một nhóm nhỏ không mặc nhiên là public. | Exam trap: Không chỉ cấm giao dịch cá nhân; gây người khác giao dịch cũng bị cấm."},{"front_en":"II(B) Market Manipulation","back_vi":"Không thực hiện hành vi bóp méo giá hoặc tạo khối lượng giao dịch giả tạo với intent to mislead market participants. Điểm mấu chốt là mục đích gây hiểu lầm; giao dịch hợp pháp vì nhu cầu thanh khoản hoặc triển khai chiến lược không tự động là manipulation. | Exam trap: Volume tăng không đủ để kết luận intent to mislead."},{"front_en":"III(A) Loyalty, Prudence, and Care","back_vi":"Có duty of loyalty với clients, hành động với reasonable care và prudent judgment, vì lợi ích của khách hàng và đặt client interests trước employer hoặc bản thân. Cần xác định đúng client và beneficiary trong bối cảnh quản lý tài sản; không bỏ qua ràng buộc luật và market integrity. | Exam trap: Prudent judgment không bảo đảm luôn sinh lời."},{"front_en":"III(B) Fair Dealing","back_vi":"Đối xử fair và objective với tất cả clients khi cung cấp research, recommendations, investment actions hay professional activities. Fair không nhất thiết identical: mức dịch vụ có thể khác nếu minh bạch và không làm khách hàng khác bị đối xử không công bằng; phân bổ cơ hội hữu hạn cần quy trình công bằng. | Exam trap: Không đồng nhất fair dealing với việc mọi tài khoản có cùng giao dịch, số lượng hoặc dịch vụ."},{"front_en":"III(C) Suitability — advisory relationship","back_vi":"Trước recommendation/action, reasonable inquiry về investment experience, risk/return objectives và financial constraints của current/prospective client; cập nhật thường xuyên. Xác định khoản đầu tư phù hợp tình hình tài chính, written objectives, mandates và constraints trong bối cảnh total portfolio. | Exam trap: Không chỉ xem risk của từng security riêng lẻ hoặc dựa vào tuổi khách hàng."},{"front_en":"III(C) Suitability — specific mandate","back_vi":"Khi quản lý portfolio theo mandate, strategy hoặc style xác định, chỉ đưa ra recommendations/actions phù hợp stated objectives và constraints của portfolio. Không cần bảo đảm pooled fund phù hợp mọi nhà đầu tư riêng lẻ khi không có advisory relationship, nhưng phải tôn trọng chính mandate. | Exam trap: Không nhầm nghĩa vụ quản lý fund mandate với thu thập IPS riêng của tất cả nhà đầu tư."},{"front_en":"III(D) Performance Presentation","back_vi":"Khi truyền đạt investment performance, phải reasonable efforts để fair, accurate và complete. Không cherry-pick thành tích tốt gây sai lệch, không trình bày simulated/hypothetical như actual, cần làm rõ dữ liệu và giới hạn liên quan. GIPS hỗ trợ trình bày nhưng III(D) không yêu cầu mọi cá nhân hoặc firm tự động claim GIPS compliance. | Exam trap: Không nhầm reasonable efforts với bảo đảm kết quả tương lai."},{"front_en":"III(E) Preservation of Confidentiality","back_vi":"Bảo mật thông tin current, former và prospective clients, trừ khi thông tin liên quan illegal activities của client/prospective client, luật yêu cầu disclosure hoặc client/prospective client cho phép disclosure. Xác định yêu cầu pháp lý thực tế trước khi tiết lộ, không coi một ngoại lệ là quyền công bố tùy ý cho bất cứ người nào. | Exam trap: Former clients vẫn thuộc phạm vi bảo mật."},{"front_en":"IV(A) Loyalty to Employers","back_vi":"Trong vấn đề liên quan employment, hành động vì lợi ích employer, không tước lợi ích từ kỹ năng của mình, không divulge confidential information hoặc gây hại employer. Nghĩa vụ này không vượt lên luật, market integrity hay client interests; cần cân nhắc facts khi chuẩn bị rời công ty. | Exam trap: Không đồng nhất loyalty với cấm đổi việc hoặc buộc làm theo mọi yêu cầu của sếp."},{"front_en":"IV(B) Additional Compensation Arrangements","back_vi":"Không accept gifts, benefits, compensation hay consideration cạnh tranh với hoặc có thể gây conflict với employer interest trừ khi có written consent từ tất cả parties involved. Xem xét cả lợi ích phi tiền tệ và conditional bonus; phân biệt với một món quà đe dọa objectivity theo I(B). | Exam trap: Consent phải bằng văn bản và từ all parties involved, không chỉ oral notice."},{"front_en":"IV(C) Responsibilities of Supervisors","back_vi":"Người có supervisory authority phải make reasonable efforts để bảo đảm người thuộc quyền tuân thủ applicable laws, rules, regulations và Code and Standards. Cần hệ thống phòng ngừa, phát hiện, xử lý và theo dõi phù hợp. Đây là reasonable efforts, không strict liability cho mọi hành vi của subordinate. | Exam trap: Không tự động kết luận supervisor vi phạm chỉ vì subordinate có vi phạm."},{"front_en":"V(A) Diligence and Reasonable Basis","back_vi":"Phân tích, recommendation và investment action cần diligence, independence, thoroughness cùng reasonable and adequate basis supported by appropriate research and investigation. Độ sâu nghiên cứu tùy sản phẩm và vai trò; sử dụng third-party research không loại bỏ trách nhiệm xem xét chất lượng. | Exam trap: Reasonable basis không có nghĩa prediction phải luôn đúng."},{"front_en":"V(B) Communication — nature of services and costs","back_vi":"CFAI 2026 yêu cầu disclose với clients và prospective clients bản chất services cung cấp cùng thông tin costs liên quan tới dịch vụ đó. Mục tiêu là informed decision về việc thuê professional/firm và ảnh hưởng tài chính; không chỉ công bố investment process hay rủi ro. | Exam trap: Đây là yêu cầu được bổ sung trong sửa đổi 2023; không bỏ sót khi học từ bản cũ."},{"front_en":"V(B) Communication — process and material changes","back_vi":"Disclose basic format và general principles của investment process dùng để phân tích, chọn securities và xây dựng portfolios; promptly disclose changes có thể materially affect process. Cần đủ để client hiểu cách quản lý, không bắt buộc tiết lộ mọi proprietary detail không cần thiết. | Exam trap: Không đợi kỳ báo cáo năm nếu thay đổi trọng yếu cần thông báo kịp thời."},{"front_en":"V(B) Communication — risks, important factors and facts versus opinions","back_vi":"Disclose significant limitations and risks của process, dùng reasonable judgment chọn important factors cần đưa vào communications, phân biệt facts và opinions trong analysis/recommendations. Forecast là opinion hoặc estimate, dù dựa trên dữ liệu; cần nêu assumptions quan trọng và tránh biến dự báo thành chắc chắn. | Exam trap: Không cần liệt kê mọi yếu tố không liên quan; trọng tâm là yếu tố quan trọng và significant risks."},{"front_en":"V(C) Record Retention","back_vi":"Develop và maintain appropriate records hỗ trợ investment analyses, recommendations, actions và communications. Tài liệu cần đủ để giải thích basis, không chỉ kết quả cuối; tuân thủ yêu cầu thời hạn từ luật hoặc firm nếu áp dụng. Guidance chi tiết về thời hạn sẽ học ở LM3. | Exam trap: Không biến một recommended period thành quy tắc bắt buộc trong mọi hoàn cảnh."},{"front_en":"VI(A) Avoid or Disclose Conflicts","back_vi":"Tránh xung đột nếu reasonably possible; nếu không, full and fair disclosure mọi vấn đề có thể reasonably impair independence/objectivity hoặc cản trở duties với clients, prospective clients, employer. Disclosure phải prominent, plain language và truyền đạt relevant information hiệu quả. Disclosure không hợp thức hóa một hành vi bị standard khác cấm. | Exam trap: Tên sửa đổi là Avoid or Disclose Conflicts; ưu tiên tránh khi hợp lý, không chỉ ghi chú nhỏ."},{"front_en":"VI(B) Priority of Transactions","back_vi":"Transactions cho clients và employers phải ưu tiên trước transactions mà member/candidate là beneficial owner. Không front-run orders hoặc sử dụng vị thế cá nhân để chiếm lợi thế từ giao dịch khách hàng; cần phân biệt beneficial ownership với việc thực hiện giao dịch cho người khác trong vai trò chuyên môn. | Exam trap: Personal trading không bị cấm tuyệt đối; điều quan trọng là priority và controls."},{"front_en":"VI(C) Referral Fees","back_vi":"Disclose cho employer, clients và prospective clients as appropriate về compensation, consideration hoặc benefit received from or paid to others do recommendation products/services. Có thể bao gồm tiền, lợi ích phi tiền tệ và thỏa thuận hai chiều; thông tin giúp bên nhận recommendation đánh giá bias và tổng chi phí. | Exam trap: Không chỉ disclose referral income nhận được; khoản trả cho người khác cũng thuộc phạm vi."},{"front_en":"VII(A) Conduct as Participants in CFA Institute Programs","back_vi":"Không thực hiện conduct làm tổn hại reputation/integrity của CFA Institute hoặc designation, hoặc integrity, validity, security của CFA Institute programs. Bao gồm tuân thủ testing policies và bảo mật nội dung thi không được phép công khai. Việc nêu quan điểm chung về chương trình khác với tiết lộ confidential exam content. | Exam trap: Không nhầm criticism hợp pháp về chương trình với tiết lộ câu hỏi bảo mật."},{"front_en":"VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program","back_vi":"Khi nói về CFA Institute, membership, designation hoặc candidacy, không misrepresent hay exaggerate ý nghĩa và hệ quả. Có thể trình bày chính xác tình trạng hoặc thành tích hợp lệ, không gọi một người đã qua một level là partial charterholder hoặc bảo đảm superior performance nhờ credential. | Exam trap: Không đánh đồng passing exams, active candidacy, membership và holding the charter."},{"front_en":"Multiple applicable standards","back_vi":"Một hành vi có thể đặt vấn đề nhiều Standards. Tách actor, duty, facts, knowledge/intent, timing, recipient, required disclosure hoặc consent và exceptions; sau đó chọn standard hoặc action được hỏi chính xác. Không coi việc đáp ứng một standard là miễn trừ những standard khác. | Exam trap: Câu hỏi most directly không yêu cầu liệt kê mọi vi phạm có thể tồn tại."},{"front_en":"Standards issue spotting — framework?","back_vi":"Actor → relevant duty → facts and knowledge/intent → applicable rule → exception → action → reasoning · Đọc đúng vai trò, facts, đối tượng nhận thông tin, timing và điều kiện. Nếu nhiều standards, phân biệt vấn đề câu hỏi yêu cầu và các vi phạm khác. · Không gắn nhãn chỉ vì một từ khóa xuất hiện trong stem."},{"front_en":"Consent vs disclosure vs prohibition — framework?","back_vi":"I(B): protect independence; IV(B): written consent all parties; VI(A): avoid or disclose; VI(C): referral disclosure; II(A): no action on MNPI · Đừng sử dụng disclosure như một biện pháp chữa mọi hành vi. Written consent, disclosure và prohibition có điều kiện khác nhau. · Nếu hành vi vi phạm một standard độc lập, đáp ứng standard khác không miễn trừ vi phạm."},{"front_en":"Client duties map — framework?","back_vi":"III(A) best interests; III(B) fair/objective treatment; III(C) suitability/mandate; III(D) fair/accurate/complete performance; III(E) confidentiality · Phân biệt năm duty theo hành vi được hỏi. · Có thể có nhiều vi phạm; không suy ra lỗ vốn là proof of unsuitability."},{"front_en":"Research and communication — framework?","back_vi":"V(A) basis; V(B) communication; V(C) records · V(A) chất lượng quá trình và cơ sở; V(B) dịch vụ/chi phí, process, risk, important factors, fact/opinion; V(C) bằng chứng lưu trữ. · Một report có reasonable basis vẫn có thể thiếu disclosure; ngược lại lưu records đầy đủ chưa chứng minh basis hợp lý."},{"front_en":"Conflicts of interest map — framework?","back_vi":"VI(A) avoid/disclose conflicts; VI(B) client/employer transactions first; VI(C) disclose referral benefits · Ba vấn đề khác nhau: conflict ảnh hưởng judgment, priority đối với beneficial ownership, compensation cho recommendation. · Không coi tất cả conflicts là cấm tuyệt đối; cần xét yêu cầu cụ thể và standards liên quan."},{"front_en":"Confidentiality exceptions under III(E) — framework?","back_vi":"Illegal activities of client/prospective client; legal requirement; client/prospective client permission · Bảo mật áp dụng cho current, former và prospective clients. Chỉ áp dụng ngoại lệ phù hợp và cân nhắc luật. · Không công bố tùy tiện khi có một nghi ngờ chưa xác định; tìm legal/compliance guidance khi cần."},{"front_en":"CFA program reference — framework?","back_vi":"Accurately state membership, designation or candidacy; do not exaggerate implications; protect exam integrity · VII(A) bảo vệ integrity và security chương trình; VII(B) mô tả chính xác trạng thái và ý nghĩa credential. · Không dùng partial designation, return guarantee, hoặc confidential exam details."},{"front_en":"A member receives a cash bonus offer from a client for outperforming a benchmark. The bonus could conflict with the employer's interests. The member emails the supervisor about it but has not obtained consent. What is required before acceptance?","back_vi":"Written consent from all parties involved before accepting the arrangement. — IV(B) applies because compensation may conflict with employer interest. Notification is not written consent. Obtain written consent from all parties involved before accepting; evaluate other duties, including independence if relevant."},{"front_en":"An adviser identifies an unavoidable potential conflict and makes a prominent disclosure to the appropriate parties. The adviser then learns material nonpublic information and buys securities based on it. Which statement is most accurate?","back_vi":"The trade violates II(A) regardless of the conflict disclosure. — VI(A) disclosure may address conflict but II(A) independently prohibits acting or causing others to act on MNPI. Client benefit or disclosure does not cure II(A); do not act on the information."},{"front_en":"A manager publishes a positive recommendation with an adequate research basis but provides clients no information about a significant process risk. Which issue remains?","back_vi":"V(B) Communication with Clients and Prospective Clients. — V(A) reasonable basis appears satisfied under stated facts; V(B) requires disclosure of significant limitations and risks. Analyze communication separately from quality of research; add appropriate disclosure."},{"front_en":"A pooled fund has a stated small-cap equity mandate. Its manager buys a large-cap bond portfolio outside the mandate because the manager expects high returns. Some investors personally prefer bonds. Which standard is most directly relevant?","back_vi":"III(C) Suitability, specifically the duty to comply with the mandate. — III(C) requires consistency with fund's stated mandate, strategy, style and constraints. Individual investor preferences do not excuse action outside the mandate. Expected return does not cure suitability issue."},{"front_en":"An adviser receives a noncash benefit from a third-party service provider for referring potential clients. The adviser believes the service is good value. What should the adviser do?","back_vi":"Disclose the referral benefit to the appropriate parties. — VI(C) includes compensation, consideration or benefits paid or received for recommendations, not only cash. Disclose the referral arrangement to employer and clients/prospective clients as appropriate so they understand potential influence."},{"front_en":"A departing analyst is offered a new job. She plans to use general experience and skills but does not take employer records or solicit clients before leaving. Which conclusion is most defensible from the stated facts?","back_vi":"Changing employers alone does not establish an IV(A) violation. — IV(A) prohibits harming employer and depriving it of skills while employed, or taking confidential information. General skills and lawful career change are distinct from employer proprietary records. Given no solicitation, record taking, or other harm stated, job change itself is not automatically a violation; additional facts could change the outcome."},{"front_en":"A supervisor implements reasonable compliance procedures and responds promptly after detecting an employee's violation. Which statement is most accurate?","back_vi":"A subordinate's violation does not by itself establish a violation by the supervisor. — IV(C) requires reasonable efforts, not guaranteed absence of violations. Facts about effectiveness and response matter. The existence of a subordinate violation alone does not prove supervisory failure."},{"front_en":"A firm offers two disclosed service tiers. Premium clients receive additional detailed research meetings, while all similarly situated clients receive significant recommendation changes fairly. Which standard distinction matters?","back_vi":"Fair dealing does not require identical services under every arrangement. — III(B) fair and objective treatment does not require identical services; disclosed levels may differ provided fair treatment remains. Facts specify equal fairness for important recommendations; additional meetings alone do not show a violation."},{"front_en":"A former client has not authorized disclosure. A colleague requests the client's transaction history for an unrelated personal purpose. No legal obligation or illegal activity exception applies. What should the adviser do?","back_vi":"Preserve confidentiality. — III(E) covers former clients in addition to current and prospective clients. Không có ngoại lệ phù hợp; từ chối tiết lộ và bảo vệ hồ sơ."},{"front_en":"A manager recommends an investment supported by reasonable research. The investment declines sharply due to unexpected economic news. Which conclusion is most accurate based solely on these facts?","back_vi":"No violation can be inferred solely from the negative outcome. — V(A) requires diligence/reasonable basis rather than accurate predictions. III(A) and III(C) also depend on conduct and suitability facts, not simply outcome. A negative return is not sufficient evidence of a standard violation."},{"front_en":"An analyst's report contains a correctly labeled forecast but the analyst intentionally excludes known facts that would materially change readers' understanding. Which concern is most directly raised?","back_vi":"I(C) Misrepresentation remains relevant despite the forecast label. — Fact/opinion labeling is part of V(B), but knowingly misleading omission also raises I(C). Correct labeling of one estimate cannot excuse deliberate misrepresentation in the broader report."},{"front_en":"A candidate accurately states that she passed Level II but also claims this credential guarantees superior investment returns. Which aspect violates the Standards?","back_vi":"The assertion of guaranteed superior investment returns. — VII(B) permits factual statements of achievements but prohibits exaggerating designation or program implications. Guarantee of superior performance is unsupported by passing an exam and misrepresents implications."},{"front_en":"A candidate discusses the exam's general difficulty without revealing questions or confidential topic specifics, while another candidate distributes recalled confidential questions. Which statement is most accurate?","back_vi":"Sharing confidential questions violates VII(A); general nonconfidential opinions do not by themselves establish a violation. — VII(A) protects program integrity/security and confidential exam information. General nonconfidential opinion differs from disclosure of exam questions. The second action is prohibited; the first as stated is not automatically a violation."},{"front_en":"2023 revision: competence as a role-specific duty","back_en":"Standard I(E) makes role-appropriate competence explicit. A move into a new specialty can require new knowledge before independently performing responsibilities. Competence is assessed in context; no single mandatory continuing-education program is specified, and a poor investment result alone does not demonstrate incompetence.","back_vi":"I(E) nêu rõ năng lực phù hợp vai trò. Chuyển sang chuyên môn mới có thể cần kiến thức mới trước khi thực hiện độc lập. Năng lực xét theo bối cảnh; không quy định một chương trình đào tạo bắt buộc cụ thể, và kết quả đầu tư xấu không tự chứng minh thiếu năng lực.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 58–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 163–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 20–22","origin":"studyhub","review_status":"targeted_source_comparison_v73"},{"front_en":"2023 revision: communication of service scope and costs","back_en":"V(B) explicitly includes the nature of services and information about associated client costs, including for prospective clients. That disclosure supplements, rather than replaces, explanation of the investment process, material changes, relevant risks and limitations, and distinctions between facts and opinions.","back_vi":"V(B) nêu rõ bản chất dịch vụ và thông tin chi phí liên quan, kể cả với khách hàng tiềm năng. Công bố này bổ sung chứ không thay thế giải thích quy trình đầu tư, thay đổi trọng yếu, rủi ro/giới hạn và phân biệt dữ kiện với ý kiến.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 58–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 163–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 20–22","origin":"studyhub","review_status":"targeted_source_comparison_v73"},{"front_en":"2023 revision: avoidance and effective conflict disclosure","back_en":"VI(A) prefers avoiding conflicts when reasonably possible. Where a conflict cannot reasonably be avoided, disclosure must be complete, fair, prominent and understandable to affected clients, prospects and employer as relevant. Disclosure does not cure conduct separately prohibited by another standard.","back_vi":"VI(A) ưu tiên tránh xung đột khi hợp lý. Khi không thể tránh hợp lý, phải công bố đầy đủ, công bằng, nổi bật và dễ hiểu cho các khách hàng, khách tiềm năng và chủ lao động liên quan. Công bố không hợp thức hóa hành vi bị chuẩn mực khác cấm.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF p. 47 (LOS); pp. 49–51, 58–61 (content); Kaplan SchweserNotes 2026 — Book 4, Reading 90 Physical PDF pp. 163–165; SAPP CFA Level I 2026 — Ethics slides Physical PDF pp. 20–22","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]}],"version":"7.3","qa_status":"TARGETED_SOURCE_COMPARISON_PENDING_FINAL"},{"module_id":"CFA26-10-03","module_title":"Guidance for Standards I–VII","subject":"Ethical and Professional Standards","level":"CFA Level I 2026","status":"Source-mapped detailed academic draft; not independently certified","language":"Vietnamese explanations with English terminology and English exam questions","source_policy":"Original explanations and vignettes based on CFAI 2026 Volume 10 LM3; Kaplan Book 4 Reading 91 and SAPP Module 3 consulted. No publisher questions copied. Practical controls not explicitly listed by CFAI for II(B) and VII(A) are labeled as instructional extensions.","disclaimer_vi":"Ba LOS bao phủ toàn bộ 23 sub-standards; mỗi mục có số trang PDF nguồn. Phân biệt mandatory requirements, guidance và recommended procedures; các tình huống là tự biên soạn, kết luận giới hạn bởi facts được nêu. Không thay thế văn bản Code and Standards; chưa thẩm định độc lập từng tình huống.","los":[{"id":"CFA26-10-03-LOS01","letter":"a","title_en":"Apply the Code and Standards to Professional Integrity Issues","outcome_en":"demonstrate the application of the Code of Ethics and Standards of Professional Conduct to situations involving issues of professional integrity","overview_vi":"Học từng sub-standard theo thứ tự I(A)–VII(B), xác định phạm vi, duty, ngoại lệ, và tình huống áp dụng. Mỗi mục ghi trang PDF vật lý để đối chiếu. V7.4: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 67 (LOS); pp. 67–235 (Guidance, procedures and applications); pp. 236–254 practice/solutions range (not reproduced)"},{"id":"Kaplan SchweserNotes 2026 — Book 4 Reading 91","pages":"Physical PDF pp. 167–194"},{"id":"SAPP CFA Level I 2026 — Ethics slides Module 3","pages":"Physical PDF pp. 23–185; topic cases pp. 186–199 (not reproduced)"}],"sections":[{"heading":"I(A) Knowledge of the Law — Scope and hierarchy","body":"Xác định luật và quy định thực sự áp dụng cho hoạt động: nơi cư trú, nơi cung cấp dịch vụ, quy định nghề nghiệp và Code and Standards. Nếu có nhiều yêu cầu áp dụng, tuân thủ yêu cầu nghiêm ngặt hơn. Nếu nước sở tại không có quy định tương ứng, Standards vẫn áp dụng. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29]","trap":"Không tự chọn luật thuận lợi nhất hoặc mặc định luật quốc gia luôn nghiêm ngặt hơn Standards."},{"heading":"I(A) Knowledge of the Law — Knowing association","body":"Không cố ý tham gia hoặc hỗ trợ vi phạm. Khi có căn cứ nhận biết hành vi vi phạm, tìm cách chấm dứt hoặc báo cáo trong nội bộ; nếu không khắc phục được phải tách khỏi hoạt động, từ chối dùng tài liệu sai hoặc thực hiện giao dịch, thậm chí nghỉ việc khi không còn phương án. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29]","trap":"Chỉ phản đối bằng lời nhưng tiếp tục hỗ trợ không phải dissociation."},{"heading":"I(A) Knowledge of the Law — Reporting and cross-border products","body":"Tham vấn compliance hoặc luật sư khi chưa rõ luật. Báo cáo cơ quan ngoài công ty được khuyến khích nhưng Standards không tự đặt nghĩa vụ báo cáo mọi vi phạm ra bên ngoài; luật áp dụng có thể bắt buộc. Người cấu trúc/sản xuất sản phẩm cũng phải hiểu quy định nơi sản phẩm được phân phối. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29]","trap":"Không nhầm quy trình báo cáo được khuyến nghị với nghĩa vụ pháp lý; không đổ trách nhiệm tuân thủ cho compliance."},{"heading":"I(B) Independence and Objectivity — Influence and gifts","body":"Duy trì nhận định độc lập, không đề nghị/nhận/trao lợi ích có thể hợp lý được kỳ vọng làm lệch khách quan. Xét giá trị, bối cảnh, tần suất và người trả; entertainment thông thường không mặc nhiên bị cấm. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41]","trap":"Không cần chứng minh đã thay đổi khuyến nghị mới có vi phạm."},{"heading":"I(B) Independence and Objectivity — Client gifts versus third parties","body":"Quà từ khách hàng sau kết quả đã đạt có thể được chấp nhận nếu không làm suy giảm khách quan, phải thông báo employer trước nếu khả thi, nếu không thì sau. Phần thưởng thỏa thuận cho hiệu suất tương lai có thể là additional compensation theo IV(B). Quà từ broker/issuer có động cơ ảnh hưởng đòi hỏi thận trọng cao hơn. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41]","trap":"Disclosure không cứu được quà gây mất độc lập; không nhầm thông báo với written consent."},{"heading":"I(B) Independence and Objectivity — Research pressure and issuer-paid research","body":"Không để corporate access, underwriting, sales pressure hay management tác động rating; issuer-paid research có thể chấp nhận nếu khách quan, thù lao cố định không gắn kết luận/giá cổ phiếu và công bố rõ nguồn trả phí. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41]","trap":"Trả bằng option hay phụ thuộc rating tạo động cơ; không coi mọi issuer-paid research đều bị cấm."},{"heading":"I(B) Independence and Objectivity — Travel and manager selection","body":"Tự chi trả chuyến đi khi khả thi; nếu không có phương tiện thương mại, chuyến đi do issuer bố trí có thể phù hợp nếu hợp lý, cần thiết, không xa hoa. Due diligence khi chọn manager/broker; không đổi hợp đồng để nhận ưu đãi cá nhân. Không nhận phân bổ IPO khan hiếm nhờ vị thế khách hàng. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41]","trap":"Đi công tác cần thiết khác chuyến nghỉ dưỡng; xét tính hợp lý thực tế."},{"heading":"I(C) Misrepresentation — Accuracy and omissions","body":"Không cố ý trình bày sai về analysis, actions hoặc dịch vụ: lời nói, email, website, marketing và tài liệu bên thứ ba. Việc bỏ thông tin trọng yếu, chọn lọc thành tích để gây hiểu nhầm cũng là misrepresentation. Khi phát hiện thông tin sai, sửa và ngừng sử dụng. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49]","trap":"Không chỉ những câu sai trắng trợn; omission có thể gây hiểu nhầm."},{"heading":"I(C) Misrepresentation — Performance and guarantees","body":"Không hứa mức lợi nhuận chắc chắn cho sản phẩm rủi ro. Có thể mô tả bảo đảm thực tế của bên bảo lãnh cùng điều kiện/rủi ro. Không chọn benchmark hay vendor định giá chỉ để tạo hình ảnh đẹp, không che phí hoặc thiếu dữ liệu quan trọng. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49]","trap":"Số liệu đúng nhưng benchmark không phù hợp có thể gây hiểu nhầm."},{"heading":"I(C) Misrepresentation — Plagiarism and internal research","body":"Ghi nguồn cho nội dung, ý tưởng, mô hình, bảng/biểu đồ, dự báo của người khác; diễn đạt lại không bỏ nghĩa vụ attribution. Có thể sử dụng dữ liệu từ dịch vụ báo cáo tài chính/thống kê được công nhận không cần ghi từng nguồn theo guidance; tài liệu thuộc sở hữu firm có thể tiếp tục dùng sau khi tác giả rời firm, nhưng không nhận toàn bộ công lao cá nhân. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49]","trap":"Không áp dụng ngoại lệ dữ liệu cho báo cáo phân tích độc quyền."},{"heading":"I(D) Misconduct — Professional integrity","body":"Không thực hiện hành vi nghề nghiệp gian dối, lừa đảo, thiếu trung thực; hành vi khác có thể vi phạm nếu phản ánh bất lợi đến danh tiếng nghề nghiệp, liêm chính hay năng lực. Không dùng Standards để xử lý bất đồng cá nhân/chính trị không liên quan đạo đức nghề nghiệp. [CFAI PDF pp. 101–103; Kaplan PDF pp. 172; SAPP PDF pp. 50–52]","trap":"Không phải mọi vi phạm pháp luật ngoài nghề đều tự động là misconduct theo Standard này."},{"heading":"I(D) Misconduct — Personal behavior and evidence","body":"Gian lận chi phí, giả mạo chứng từ, lạm dụng tài sản hoặc hành vi ảnh hưởng khả năng làm việc có thể vi phạm; xét bản chất và liên hệ nghề nghiệp, không chỉ tình trạng bị buộc tội. [CFAI PDF pp. 101–103; Kaplan PDF pp. 172; SAPP PDF pp. 50–52]","trap":"Không cần thiệt hại đầu tư mới cấu thành gian dối nghề nghiệp."},{"heading":"I(E) Competence — Role-specific capability","body":"Phải hành nghề với năng lực cần thiết và duy trì năng lực phù hợp nhiệm vụ: knowledge, skills, abilities, kinh nghiệm và công nghệ cần thiết. Khi nhận nhiệm vụ mới, chủ động phát triển năng lực trước khi thực hiện phần vượt khả năng; có thể tìm hỗ trợ chuyên môn thích hợp. [CFAI PDF pp. 104–107; Kaplan PDF pp. 172; SAPP PDF pp. 53–54]","trap":"Không chỉ dựa vào bằng cấp, số năm kinh nghiệm hoặc chức danh."},{"heading":"I(E) Competence — Outcomes and learning","body":"Kết quả đầu tư xấu không tự chứng minh thiếu năng lực; xét quy trình, kiến thức và mức độ chuẩn bị. Continuing education, seminars, professional development, self-study là cách được khuyến nghị, không có số giờ cố định bắt buộc trong Standard I(E). [CFAI PDF pp. 104–107; Kaplan PDF pp. 172; SAPP PDF pp. 53–54]","trap":"Không nhầm competence với bảo đảm thành công hoặc mandatory CE hours."},{"heading":"II(A) Material Nonpublic Information — Materiality and public status","body":"Thông tin material nếu ảnh hưởng đáng kể đến giá trị hoặc nhà đầu tư hợp lý muốn biết trước quyết định. Xét độ cụ thể, độ tin cậy, sự kiện, quy mô, thời điểm và tác động. Nonpublic nếu chưa được phổ biến ra thị trường; thông báo cho nhóm analyst kín không tự thành public. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61]","trap":"Tin không chắc chắn không mặc nhiên immaterial; selective disclosure không phải public release."},{"heading":"II(A) Material Nonpublic Information — Prohibited action and mosaic","body":"Không hành động hoặc khiến người khác hành động dựa trên material nonpublic information, kể cả securities liên quan hoặc quỹ. Mosaic theory cho phép tổng hợp thông tin public với nonpublic không trọng yếu để suy ra kết luận material. Giữ hồ sơ phân tích. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61]","trap":"Không dùng mosaic để hợp thức hóa một mẩu MNPI; không truyền tín hiệu để người khác giao dịch."},{"heading":"II(A) Material Nonpublic Information — Research and communications","body":"Có thể khuyến khích issuer phổ biến thông tin cho thị trường; chờ phổ biến rộng rãi trước khi sử dụng. Expert networks có thể cung cấp insight hợp pháp nhưng phải tránh MNPI; không cấm research hợp lệ chỉ vì kết luận khác consensus. Nếu MNPI vô tình đến, hạn chế truy cập và liên hệ compliance. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61]","trap":"Không cần mọi nhà đầu tư thực sự đọc tin; cần thông tin được đưa ra thị trường."},{"heading":"II(B) Market Manipulation — Information-based manipulation","body":"Cấm lan truyền thông tin sai/lừa dối nhằm gây hiểu nhầm market participants hoặc làm méo giá/volume; ví dụ pump-and-dump bằng tin giả, báo cáo có chủ đích sai. [CFAI PDF pp. 120–125; Kaplan PDF pp. 174–175; SAPP PDF pp. 62–66]","trap":"Intent to mislead là dấu hiệu trọng tâm; khác dự báo thiện chí sau đó sai."},{"heading":"II(B) Market Manipulation — Transaction-based manipulation","body":"Giao dịch tạo khối lượng giả, giá đóng cửa giả, wash trades, kiểm soát nguồn cung để thao túng giá liên quan có thể vi phạm. Giao dịch lớn hợp lệ để đáp ứng nhu cầu, arbitrage, liquidity hoặc rebalancing không tự động là thao túng vì có ảnh hưởng giá. [CFAI PDF pp. 120–125; Kaplan PDF pp. 174–175; SAPP PDF pp. 62–66]","trap":"Xét mục đích, bối cảnh, cấu trúc giao dịch; không suy luận từ biến động đơn thuần."},{"heading":"III(A) Loyalty, Prudence, and Care — Client first and fiduciary duties","body":"Hành động vì lợi ích client, sử dụng reasonable care và prudent judgment, đặt client trước employer và cá nhân. Xác định client thực sự: người thụ hưởng pension hoặc đối tượng được phục vụ, không mặc định người ký hợp đồng là beneficiary. Tuân thủ tài liệu quản lý tài sản và luật áp dụng. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77]","trap":"Không hứa tối đa hóa return bất kể rủi ro; không đồng nhất mọi vai trò với fiduciary theo luật."},{"heading":"III(A) Loyalty, Prudence, and Care — Brokerage, soft commissions and execution","body":"Client brokerage là tài sản client: chọn execution theo lợi ích client, chất lượng/giá tổng thể; nghiên cứu/dịch vụ dùng commission phải hỗ trợ client phù hợp. Directed brokerage theo yêu cầu client cần thông tin về trade-offs, có thể hạn chế best execution. Không dùng commission mua lợi ích cá nhân hoặc chi phí không phục vụ client. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77]","trap":"Best execution không nhất thiết commission thấp nhất; disclose xung đột không đủ nếu lợi ích client bị xâm hại."},{"heading":"III(A) Loyalty, Prudence, and Care — Proxy and custody","body":"Xem xét proxy voting theo lợi ích client; cân nhắc chi phí và lợi ích, không mặc định phải vote mọi proxy. Tách tài sản client, quản lý quyền hạn, cung cấp báo cáo holdings và transactions theo yêu cầu phù hợp. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77]","trap":"Không vote theo lợi ích employer; có thể không vote nếu chi phí lớn hơn lợi ích."},{"heading":"III(B) Fair Dealing — Fair not identical","body":"Đối xử công bằng, khách quan khi disseminate khuyến nghị và thực hiện actions. Không yêu cầu identical service; gói tư vấn khác nhau có thể tồn tại nếu minh bạch, không làm bất lợi client khác. Cung cấp cơ hội công bằng cho client phù hợp. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85]","trap":"Không ưu tiên client lớn trước khi disseminate thông tin chung."},{"heading":"III(B) Fair Dealing — Recommendations and changes","body":"Thông báo khuyến nghị mới/thay đổi kịp thời cho các client liên quan, dùng phương thức giảm chênh lệch thời gian, không cho một số người giao dịch trước; client đặt lệnh trái khuyến nghị mới cần được biết thay đổi trước khi thực hiện nếu liên quan. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85]","trap":"Phân biệt follow-up chi tiết sau công bố chung và selective advance access."},{"heading":"III(B) Fair Dealing — Allocation","body":"Phân bổ công bằng theo policy công bố trước, phù hợp mandate; pro rata là một cách cho issue khan hiếm, xét lot size và tính khả thi. Không ưu tiên account cá nhân, account trả phí cao hay cherry-pick giao dịch lời. Family account là client bình thường nếu quản lý như client khác, tùy beneficial ownership và conflict. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85]","trap":"Không bắt buộc mọi account nhận số lượng giống nhau; không loại client chỉ vì quan hệ gia đình."},{"heading":"III(C) Suitability — Advisory relationship","body":"Thu thập thông tin khách hàng trước khuyến nghị: kinh nghiệm, risk/return objectives, financial circumstances và constraints, cập nhật định kỳ. Đánh giá investment phù hợp mục tiêu và giới hạn đã viết, xét tổng danh mục, leverage, liquidity, time horizon và khả năng chịu lỗ. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95]","trap":"Sản phẩm tốt không mặc nhiên phù hợp; willingness khác ability."},{"heading":"III(C) Suitability — Mandate versus advisory","body":"Manager quản lý pooled fund hoặc mandate cụ thể phải tuân thủ objective/style/constraints đã công bố; không có nghĩa phải đánh giá suitability từng investor cuối nếu không có advisory relationship với họ. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95]","trap":"Không tự đổi mandate chỉ vì cơ hội lợi nhuận."},{"heading":"III(C) Suitability — Unsolicited unsuitable orders","body":"Trao đổi lý do không phù hợp trước giao dịch; đánh giá tác động danh mục. Nếu tác động nhỏ, theo policy firm và client xác nhận hiểu; nếu tác động trọng yếu, cân nhắc cập nhật IPS hợp lý, separate client-directed account hoặc xem xét tiếp tục quan hệ nếu không giải quyết được. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95]","trap":"Không phải cứ client yêu cầu thì được bỏ IPS; không phải mọi unsolicited unsuitable order đều bắt buộc từ chối."},{"heading":"III(D) Performance Presentation — Fair accurate complete","body":"Nỗ lực hợp lý để trình bày hiệu quả đầu tư công bằng, chính xác, đầy đủ; past performance không bảo đảm future results; không lựa chọn account/period có chủ đích gây sai lệch. Brief presentation có thể được dùng nếu nêu giới hạn và cung cấp chi tiết khi yêu cầu. [CFAI PDF pp. 152–156; Kaplan PDF pp. 178–179; SAPP PDF pp. 96–99]","trap":"Không đồng nhất ngắn gọn với thiếu trung thực; không đưa forecast như thành tích thực."},{"heading":"III(D) Performance Presentation — Composite and disclosures","body":"Khuyến nghị dùng weighted composite của portfolios tương tự, giữ terminated accounts trong lịch sử đến ngày chấm dứt, công bố phí, gross/net, simulated/model returns, benchmark và phương pháp tính; lưu dữ liệu. GIPS được khuyến nghị nhưng không bắt buộc bởi III(D). [CFAI PDF pp. 152–156; Kaplan PDF pp. 178–179; SAPP PDF pp. 96–99]","trap":"Không chọn best account làm đại diện; GIPS compliance không tự động chứng minh mọi presentation công bằng."},{"heading":"III(E) Preservation of Confidentiality — Scope and exceptions","body":"Bảo mật thông tin current, former và prospective clients. Ngoại lệ: thông tin liên quan hành vi bất hợp pháp của client, luật yêu cầu disclosure, hoặc client cho phép. Nghĩa vụ pháp lý báo cáo có thể phát sinh; không tự quyết đoán nếu không rõ, hỏi legal/compliance. [CFAI PDF pp. 157–160; Kaplan PDF pp. 179; SAPP PDF pp. 100–104]","trap":"Former client vẫn được bảo mật; không chia sẻ vì tò mò hay lợi ích marketing."},{"heading":"III(E) Preservation of Confidentiality — PCP and electronic security","body":"Standard không ngăn hợp tác với CFA Institute Professional Conduct Program (PCP) trong điều tra, với điều kiện luật áp dụng cho phép; PCP bảo mật. Dữ liệu điện tử/email/cloud cần kiểm soát truy cập, hạn chế chia sẻ với nhân sự được phép và phục vụ client. [CFAI PDF pp. 157–160; Kaplan PDF pp. 179; SAPP PDF pp. 100–104]","trap":"Không coi PCP là ngoại lệ vô hạn vượt luật; không coi đồng nghiệp nào cũng có quyền truy cập."},{"heading":"IV(A) Loyalty — Employment duties and independent practice","body":"Trong công việc phải vì lợi ích employer, không chiếm dụng kỹ năng, tài liệu, thông tin bí mật hay cơ hội gây hại. Client first vẫn ưu tiên; không bắt buộc hy sinh mọi nghĩa vụ gia đình. Independent contractor tuân điều khoản hợp đồng. Hoạt động độc lập cạnh tranh có thù lao cần thông báo đầy đủ bản chất, thời hạn, thù lao và nhận consent trước khi bắt đầu. [CFAI PDF pp. 161–171; Kaplan PDF pp. 180–181; SAPP PDF pp. 105–115]","trap":"Không phải mọi hoạt động ngoài giờ đều bị cấm; xét cạnh tranh và ảnh hưởng employer."},{"heading":"IV(A) Loyalty — Leaving employer and social media","body":"Trước ngày nghỉ hiệu lực vẫn thực hiện nghĩa vụ; có thể chuẩn bị hợp pháp cho công việc mới nhưng không solicit client trước khi rời, không lấy client lists, records/trade secrets, kể cả từ thiết bị cá nhân. Sau nghỉ có thể dùng kiến thức/kỹ năng chung, liên hệ từ thông tin công khai/nhớ tên nếu không vi phạm hợp đồng/luật; thỏa thuận tuyển dụng giữa firms có thể cho phép phạm vi dữ liệu nhất định. [CFAI PDF pp. 161–171; Kaplan PDF pp. 180–181; SAPP PDF pp. 105–115]","trap":"Không đồng nhất kinh nghiệm tích lũy với dữ liệu sở hữu firm; tuân policy social media."},{"heading":"IV(A) Loyalty — Whistleblowing","body":"Trong trường hợp đặc biệt, hành động bảo vệ client hoặc integrity of markets có thể biện minh việc đi ngược lợi ích employer nếu không vì lợi ích cá nhân; xét luật, kênh nội bộ và tính cần thiết. Không dùng lý do whistleblowing để lấy bí mật phục vụ cạnh tranh. [CFAI PDF pp. 161–171; Kaplan PDF pp. 180–181; SAPP PDF pp. 105–115]","trap":"Loyalty không yêu cầu che giấu gian lận; không phải blanket exemption."},{"heading":"IV(B) Additional Compensation Arrangements — Written consent before acceptance","body":"Không nhận thù lao/lợi ích cạnh tranh hoặc có thể hợp lý tạo xung đột với employer nếu chưa có written consent của tất cả parties involved. Direct/indirect, cash/noncash đều có thể thuộc phạm vi; email có thể là văn bản. Xét bản chất arrangement, không chỉ tên gọi gift. [CFAI PDF pp. 172–173; Kaplan PDF pp. 181–182; SAPP PDF pp. 116–119]","trap":"Thông báo một chiều hoặc verbal consent không đủ khi IV(B) áp dụng."},{"heading":"IV(B) Additional Compensation Arrangements — Past gift versus prospective incentive","body":"Quà client tự nguyện cho thành tích đã xảy ra thường xét I(B), disclosure employer; offer bonus phụ thuộc hiệu suất tương lai là arrangement cần consent trước. Third-party benefit có thể còn liên quan I(B), VI(A) hoặc VI(C). [CFAI PDF pp. 172–173; Kaplan PDF pp. 181–182; SAPP PDF pp. 116–119]","trap":"Không thay written consent bằng disclosure conflict; có thể có nhiều Standards."},{"heading":"IV(C) Responsibilities of Supervisors — Reasonable supervision","body":"Người có authority phải reasonable efforts để ngăn và phát hiện vi phạm của người dưới quyền, kể cả người không thuộc CFA Program. Delegation không xóa trách nhiệm giám sát; compliance system phù hợp hoạt động, luật và Standards. Nếu inadequate, báo management và đề xuất sửa; nếu không có hệ thống đầy đủ, từ chối supervisory responsibility bằng văn bản cho đến khi khắc phục. [CFAI PDF pp. 174–182; Kaplan PDF pp. 182–183; SAPP PDF pp. 120–127]","trap":"Không phải strict liability cho mọi hành vi cấp dưới, nhưng không đủ nếu chỉ giao việc."},{"heading":"IV(C) Responsibilities of Supervisors — Investigate and restrict","body":"Khi biết hoặc có nghi ngờ vi phạm, điều tra kịp thời, tăng giám sát hoặc hạn chế hoạt động trong lúc điều tra; không chỉ chấp nhận lời đảm bảo của người bị nghi hoặc chuyển trách nhiệm cho compliance rồi bỏ qua. [CFAI PDF pp. 174–182; Kaplan PDF pp. 182–183; SAPP PDF pp. 120–127]","trap":"Không đợi vi phạm được chứng minh mới có biện pháp hợp lý."},{"heading":"V(A) Diligence and Reasonable Basis — Research depth and independence","body":"Phân tích, khuyến nghị và hành động đầu tư cần diligence, independence, thoroughness và reasonable adequate basis từ research/investigation thích hợp. Độ sâu phụ thuộc nhiệm vụ, loại sản phẩm, strategy, rủi ro, nguồn lực và vai trò. Xem macro, ngành, financials, peer comparisons, fee và limitations phù hợp. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136]","trap":"Không có công thức số trang bắt buộc; kết quả xấu không tự chứng minh thiếu diligence."},{"heading":"V(A) Diligence and Reasonable Basis — Third-party research and models","body":"Có thể dựa vào research bên ngoài nếu có reasonable basis tin chất lượng: kiểm tra assumptions, timeliness, rigor, objectivity, independence, nguồn dữ liệu và red flags. Quant models cần hiểu logic, assumptions, limitations, kiểm tra range of scenarios, sensitivity, chất lượng inputs; không nhất thiết tự viết mọi model. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136]","trap":"Không tin vendor mù quáng; không mặc định outsource bị cấm."},{"heading":"V(A) Diligence and Reasonable Basis — Group research and external managers","body":"Có thể đứng tên group recommendation nếu reasonable basis và quy trình đầy đủ dù cá nhân không đồng ý kết luận cuối; không được ủng hộ nếu biết nghiên cứu thiếu cơ sở. Due diligence chọn external adviser/manager, xem performance, style, controls, fee và review định kỳ. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136]","trap":"Không bắt mọi thành viên có cùng forecast; xét basis của group output."},{"heading":"V(B) Communication with Clients and Prospective Clients — Nature and cost of services","body":"Công bố nature of services và chi phí liên quan cho clients/prospects; tại khởi đầu và khi thay đổi, đủ chi tiết để hiểu cách chi phí phát sinh, gồm third-party service costs. Không nhất thiết biết trước dollar amount chính xác khi phụ thuộc AUM hoặc biến số khác. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143]","trap":"Không chỉ nói management fee nếu còn chi phí đáng kể khác; không đòi exact dollar khi chưa biết."},{"heading":"V(B) Communication with Clients and Prospective Clients — Process changes, limitations and risks","body":"Mô tả basic format và general principles dùng phân tích, lựa chọn chứng khoán, xây danh mục; promptly disclose thay đổi material. Công bố significant limitations và risks, kể cả model assumptions, leverage, liquidity, structured payoff và hạn chế dữ liệu nếu trọng yếu. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143]","trap":"Không bắt tiết lộ mọi bí mật thuật toán; không được che material risk."},{"heading":"V(B) Communication with Clients and Prospective Clients — Facts, opinions and all media","body":"Dùng reasonable judgment chọn factors quan trọng; phân biệt fact với opinion/forecast/model output; áp dụng với email, chat, oral, social media, report. Giao tiếp phù hợp sophistication và giải thích khả năng lãi/lỗ, tổng return khi liên quan. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143]","trap":"Dự báo từ model không thành fact chỉ vì có số chính xác."},{"heading":"V(C) Record Retention — Supporting records and media","body":"Xây dựng và duy trì records thích hợp hỗ trợ analysis, recommendations, actions và investment communications; bao gồm dữ liệu, models, assumptions, notes, emails, messages/social media khi liên quan. Lưu phù hợp quy định, chính sách và khả năng truy xuất. [CFAI PDF pp. 207–209; Kaplan PDF pp. 186; SAPP PDF pp. 144–148]","trap":"Không chỉ lưu final report; không bỏ qua giao tiếp điện tử."},{"heading":"V(C) Record Retention — Ownership and retention periods","body":"Records làm trong employment thường thuộc firm, không mang đi khi rời trừ có consent phù hợp. Nếu không có luật hoặc firm policy quy định, CFAI khuyến nghị giữ ít nhất 7 năm; phải tuân luật và policy áp dụng, không coi 7 năm là bắt buộc phổ quát. Tại firm mới, tái tạo basis từ nguồn hợp lệ nếu cần. [CFAI PDF pp. 207–209; Kaplan PDF pp. 186; SAPP PDF pp. 144–148]","trap":"Không lấy proprietary files để chứng minh diligence cá nhân; 7 năm là recommendation trong điều kiện nêu."},{"heading":"VI(A) Avoid or Disclose Conflicts — Avoid or disclose","body":"Tránh xung đột có thể làm lệch independence/objectivity hoặc ảnh hưởng duties khi hợp lý; nếu không tránh được, công bố đầy đủ và công bằng các matters hợp lý có thể impair duties, nổi bật, dễ hiểu, tới bên liên quan và cập nhật khi thay đổi. Disclosure giúp đánh giá chứ không chữa mọi hành vi bị cấm. [CFAI PDF pp. 210–214; Kaplan PDF pp. 187–188; SAPP PDF pp. 149–157]","trap":"Không chỉ disclosure chung chung ở cuối tài liệu; không thay client first hoặc I(B)."},{"heading":"VI(A) Avoid or Disclose Conflicts — Employer and client conflicts","body":"Xung đột gồm beneficial holdings, board/directorship, family/business ties, issuer investment banking, compensation/incentive, market making và các hoạt động cạnh tranh. Công bố cho employer để quản lý duties, cho clients/prospects khi ảnh hưởng dịch vụ/khuyến nghị; cân nhắc recusal, thay analyst hoặc loại xung đột. [CFAI PDF pp. 210–214; Kaplan PDF pp. 187–188; SAPP PDF pp. 149–157]","trap":"Không chỉ xét conflict đã làm thay đổi quyết định; reasonably expected conflicts cũng quan trọng."},{"heading":"VI(B) Priority of Transactions — Client and employer precedence","body":"Giao dịch cho client và employer ưu tiên hơn giao dịch nơi member/candidate là beneficial owner. Không front-run khuyến nghị hoặc client trades, không tận dụng ưu thế từ việc biết lệnh trước. Personal trade không bị cấm tuyệt đối nếu client không bị bất lợi và các quy định được đáp ứng. [CFAI PDF pp. 215–220; Kaplan PDF pp. 188–189; SAPP PDF pp. 158–164]","trap":"Không nhầm personal account với mọi family account; xét beneficial interest."},{"heading":"VI(B) Priority of Transactions — Family accounts and personal trades","body":"Family account quản lý như client bình thường nếu là client thật, đối xử công bằng; nếu member có beneficial ownership thì áp dụng priority. Personal trades sau khi client/employer có cơ hội hợp lý, theo policy, không dùng MNPI hoặc unfair allocations. [CFAI PDF pp. 215–220; Kaplan PDF pp. 188–189; SAPP PDF pp. 158–164]","trap":"Không bắt loại mọi tài khoản gia đình khỏi phân bổ; không tự đặt thời gian blackout chung cho mọi firm."},{"heading":"VI(C) Referral Fees — Scope, timing and nature","body":"Công bố cho employer, clients và prospects khi phù hợp mọi compensation/benefit nhận hoặc trả cho recommendation sản phẩm/dịch vụ, trước formal agreement. Nêu nature (flat, percentage, one-time, continuing, performance-based, cash/noncash, research/soft dollars) và estimated dollar value; giúp đánh giá bias và full costs. [CFAI PDF pp. 221–223; Kaplan PDF pp. 189; SAPP PDF pp. 165–168]","trap":"Không chỉ khoản nhận bằng tiền; không chỉ disclose referral fee sau hợp đồng."},{"heading":"VII(A) Conduct as Participants in CFA Institute Programs — Exam integrity and confidentiality","body":"Không làm suy yếu uy tín/integrity CFA Institute, designation hoặc integrity, validity, security CFA programs. Không chia sẻ/solicit actual exam questions, topics tested/not tested hoặc thông tin scoring/confidential development; tuân exam rules, không lấy materials hoặc gian lận, kể cả khi thi không thành công. [CFAI PDF pp. 224–229; Kaplan PDF pp. 189–190; SAPP PDF pp. 169–174]","trap":"Không chỉ việc chia sẻ nguyên văn câu hỏi mới vi phạm; topics covered/not covered cũng confidential."},{"heading":"VII(A) Conduct as Participants in CFA Institute Programs — Opinions and volunteer duties","body":"Có thể bày tỏ ý kiến về CFA Institute/program/policy hoặc độ khó chung nếu không tiết lộ nội dung cụ thể. Volunteers, graders và người tham gia các chương trình khác phải giữ confidential process/materials; không lợi dụng vai trò để trục lợi hay cung cấp thông tin. [CFAI PDF pp. 224–229; Kaplan PDF pp. 189–190; SAPP PDF pp. 169–174]","trap":"Không cấm phê bình thiện chí; không nhầm opinion chung với topic disclosure."},{"heading":"VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program — Designation and membership","body":"Không misrepresent/exaggerate ý nghĩa CFA membership, designation hoặc candidacy. Chỉ dùng CFA designation nếu có quyền sử dụng, duy trì membership và các yêu cầu liên quan; nếu không còn quyền, có thể nêu sự kiện lịch sử chính xác nhưng không dùng designation như hiện tại. Dùng CFA như dấu hiệu professional designation phù hợp, không biến thành danh từ số nhiều hay tên firm. [CFAI PDF pp. 230–235; Kaplan PDF pp. 190–191; SAPP PDF pp. 175–183]","trap":"Không dùng CFA như chứng nhận guaranteed returns hoặc superiority."},{"heading":"VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program — Candidate status and factual statements","body":"Nêu chính xác active candidacy khi đáp ứng định nghĩa, có thể nói đã pass một level nếu đúng. Không có partial designation, không dùng 'CFA Level II' sau tên, 'CFA expected' hay dự đoán thời điểm nhận charter. Có thể nói pass ba levels liên tiếp như sự kiện thật nhưng không hàm ý năng lực vượt trội. [CFAI PDF pp. 230–235; Kaplan PDF pp. 190–191; SAPP PDF pp. 175–183]","trap":"Passing exams không đồng nghĩa charter; candidate status không tồn tại vô hạn."},{"heading":"I(A) — Applicable law, uncertainty and dissociation","body":"Cần hiểu luật áp dụng một cách hợp lý và thiện chí, không phải thành chuyên gia mọi hệ thống luật. Khi chưa rõ, hỏi bộ phận có chuyên môn; tuân thủ yêu cầu áp dụng nghiêm hơn. Báo cấp trên không cho phép tiếp tục cố ý hỗ trợ. Nếu xử lý nội bộ thất bại, tách khỏi hoạt động; báo ngoài khi luật áp dụng yêu cầu, không mặc nhiên do Standard.","body_en":"A reasonable good-faith understanding of applicable law is required, not expertise in every possible jurisdiction. Seek qualified guidance when uncertain; apply the stricter applicable requirement. A report to a supervisor does not permit continued knowing assistance. If internal efforts fail, remove yourself from the activity; external reporting is required when applicable law demands it, not automatically by the Standard.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 67–76 (I(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"I(B) — Research incentives and legitimate access","body":"Phí cố định cho nghiên cứu do tổ chức phát hành tài trợ có thể phù hợp nếu nghiên cứu độc lập, đầy đủ và công bố thỏa thuận phí. Phí phụ thuộc kết luận thuận lợi làm suy yếu tính độc lập. Khi đi khảo sát, ưu tiên phương tiện thương mại tự chi trả; nếu không có phương tiện phù hợp, thu xếp khiêm tốn của issuer có thể chấp nhận nếu chuyến đi cần thiết và được cân nhắc hợp lý.","body_en":"A fixed fee for issuer-sponsored research can be compatible with objectivity if the research is independent, thorough and the compensation arrangement is disclosed. Compensation contingent on a favorable result is incompatible with independent judgment. For travel, commercial transport at one's own expense is preferred; modest issuer arrangements may be acceptable when commercial transport is unavailable and the visit is necessary, with reasonable judgment.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 76–90 (I(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"I(C) — Error correction, attribution and valuation integrity","body":"Sai sót vô ý không mặc nhiên là cố ý trình bày sai, nhưng khi phát hiện phải ngừng phát tán và đính chính với người nhận. Diễn giải lại và phân tích mượn cần ghi nguồn; dữ kiện phổ thông không cần truy nguyên mọi nguồn. Không đổi nguồn định giá chỉ để lấy mức giá có lợi.","body_en":"An inadvertent mistake is not automatically knowing misrepresentation, but after discovery the member should stop disseminating erroneous material and correct recipients' understanding. Paraphrases and borrowed analyses require attribution; commonplace facts do not require tracing every original source. Do not switch valuation sources merely to obtain a favorable mark.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 90–101 (I(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"I(D) — Misconduct and professional relevance","body":"Cấm hành vi nghề nghiệp gian dối, gian lận, lừa gạt. Hành vi khác được xét theo ảnh hưởng xấu đến uy tín, liêm chính hoặc năng lực nghề; khó khăn tài chính cá nhân và bất tuân dân sự không tự động thỏa điều kiện đó. Không cần có bản án mới xác định vi phạm liêm chính.","body_en":"Dishonesty, fraud and deceit in professional conduct are prohibited. Other conduct is assessed by whether it reflects adversely on professional reputation, integrity or competence; private financial hardship and civil disobedience do not automatically satisfy that test. A conviction is not a prerequisite to a professional-integrity finding.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 101–104 (I(D)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"I(E) — Role-specific competence and transitions","body":"Competence là kiến thức, kỹ năng và khả năng cần cho trách nhiệm thực tế. Khi đổi vai trò, xác định thiếu hụt trước khi làm độc lập và dùng đào tạo hoặc hỗ trợ có chuyên môn. Kết quả xấu riêng lẻ không chứng minh thiếu năng lực; I(E) không ấn định lịch đào tạo liên tục chung bắt buộc.","body_en":"Competence is the knowledge, skills and abilities needed for the actual responsibilities performed. When moving to a new role, identify gaps before acting independently and use training or qualified assistance. A poor outcome alone does not establish incompetence; there is no single mandatory continuing-education schedule under I(E).","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 104–109 (I(E)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"II(A) — Materiality, dissemination and mosaic analysis","body":"Xét ý nghĩa với nhà đầu tư hợp lý và độ tin cậy/cụ thể của thông tin. Chia sẻ riêng cho nhóm nhỏ chưa chắc là công khai. Chờ phổ biến công khai hiệu quả trước khi giao dịch hoặc khiến người khác giao dịch trên MNPI. Thông tin công khai cộng mảnh riêng lẻ không trọng yếu có thể tạo kết luận trọng yếu theo mosaic; thêm dữ liệu công khai không hợp thức hóa đầu vào MNPI.","body_en":"Assess significance to a reasonable investor and the reliability/specificity of the information. Information shared privately with a small audience is not necessarily public. Wait for effective public dissemination before acting or causing others to act on material nonpublic information. Public information plus nonmaterial nonpublic pieces may support a material inference under mosaic theory; a material nonpublic input is not cured by adding public data.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 109–120 (II(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"II(B) — Intent versus ordinary trading effects","body":"Market manipulation đòi hỏi ý định đánh lừa qua bóp méo giá hoặc tăng khối lượng giả tạo. Cung cấp thanh khoản, phòng hộ hoặc giao dịch lớn thật có thể ảnh hưởng giá nhưng không mặc nhiên vi phạm. Lan truyền tin biết là sai để kích mua là manipulation dựa thông tin; wash trade tạo hoạt động giả là dựa giao dịch.","body_en":"Market manipulation requires deceptive intent to distort prices or artificially inflate volume. Genuine liquidity provision, hedging or large transactions can move prices without necessarily violating II(B). Disseminating a knowingly false story to induce purchases is information-based manipulation; wash trades creating false activity are transaction-based.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 120–124 (II(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"III(A) — Beneficiaries, directed brokerage and soft commissions","body":"Xác định client thực, gồm người thụ hưởng quỹ thay vì chỉ bên thuê. Hoa hồng từ tài sản khách phải phục vụ khách, xét best execution và bản chất lợi ích nghiên cứu/dịch vụ. Khách có thể chỉ định broker sau khi được thông tin thích hợp về bất lợi; manager không âm thầm dùng commission cho lợi ích cá nhân hoặc riêng firm.","body_en":"Identify the actual client, including plan beneficiaries rather than merely the hiring party. Brokerage paid from client assets should benefit clients, with attention to best execution and the nature of research/service benefits. A client can direct brokerage after receiving appropriate information about possible disadvantages; the manager must not silently redirect commissions for personal or firm-only benefits.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 125–135 (III(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"III(B) — Fair access versus identical service","body":"Fair dealing là công bằng, không bắt buộc dịch vụ giống hệt. Tier được công bố có thể khác nếu không làm khách khác bất lợi không công bằng. Truyền đạt thay đổi khuyến nghị công bằng cho khách bị ảnh hưởng. Phân bổ chứng khoán khan hiếm theo tiêu chí khách quan định trước, xét suitability và khối lượng hợp lệ, không thưởng khách ưu ái.","body_en":"Fair dealing is equitable, not necessarily identical service. Disclosed service tiers can differ without disadvantaging other clients unfairly. Communicate changes to recommendations fairly to affected clients. Allocate scarce securities under objective, pre-established procedures, taking suitability and legitimate order sizes into account rather than rewarding favored clients.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 135–144 (III(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"III(C) — Portfolio context and unsolicited orders","body":"Trong quan hệ tư vấn, đánh giá tài chính, mục tiêu, hạn chế và sự phù hợp trong toàn danh mục. Manager theo mandate tuân thủ mandate thay vì xét từng người mua quỹ. Với lệnh khách tự yêu cầu nhưng không phù hợp, giải thích, ghi nhận, xét tác động trọng yếu, rà IPS nếu cần và theo quy trình firm, không mặc nhiên khớp hay từ chối mọi lệnh.","body_en":"In advisory relationships, assess client financial circumstances, objectives and constraints, and investment fit within the total portfolio. A mandate manager follows the stated mandate rather than assessing each fund investor individually. For an unsolicited unsuitable request, discuss the mismatch; document and assess material impact, revisit the IPS if necessary, and follow firm procedures rather than automatically executing or refusing every request.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 144–152 (III(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"III(D) — Performance comparability and completeness","body":"Báo cáo hiệu suất công bằng, chính xác, đầy đủ là bắt buộc dù không theo GIPS. Phân biệt return thực với mô phỏng, kết quả nơi làm trước, gross/net và kỳ liên quan. Loại tài khoản chấm dứt hoặc kết quả kém chỉ để làm đẹp lịch sử là gây hiểu nhầm.","body_en":"Fair, accurate and complete performance reporting is required even without GIPS compliance. Clearly distinguish actual and simulated returns, predecessor performance, gross versus net results and relevant periods. Excluding terminated or poorly performing accounts solely to improve a reported track record is misleading.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 152–157 (III(D)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"III(E) — Confidentiality exceptions and controlled disclosure","body":"Bảo mật áp dụng khách hiện tại, cũ, tiềm năng. Ngoại lệ: thông tin về hoạt động trái luật của khách, luật yêu cầu công bố hoặc khách cho phép. Nếu luật hạn chế, xin tư vấn và tuân luật áp dụng. Hợp tác PCP được khuyến khích trong giới hạn luật, không cho phép công khai dữ liệu khách tùy ý.","body_en":"Confidentiality covers current, former and prospective clients. Exceptions involve client illegal activity, legally required disclosure or client permission. If law restricts disclosure, seek legal guidance and comply with the applicable law. Cooperation with the Professional Conduct Program is encouraged within applicable legal limits; it is not permission to publicly release private client data.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 157–162 (III(E)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"IV(A) — Preparation to leave and employer property","body":"Chuẩn bị doanh nghiệp tương lai ngoài giờ có thể phù hợp nếu không ảnh hưởng nhiệm vụ; cạnh tranh hoặc lôi kéo khách trước khi nghỉ có thể vi phạm loyalty. Sau khi nghỉ, dùng kỹ năng và kinh nghiệm chung, nhưng không lấy hồ sơ employer hoặc dữ liệu khách mật nếu không phép. Whistleblowing để bảo vệ khách/thị trường có thể biện minh hành động vốn trái loyalty, không phải hành động vì lợi riêng.","body_en":"Preparing a future business on personal time may be permissible if duties are not impaired; active competition or solicitation for the new business before leaving may violate loyalty. After departure, use general skills and experience, but do not take employer records or confidential client data without authorization. Whistleblowing for protecting clients or market integrity may justify actions that would otherwise be disloyal, not actions motivated merely by personal advantage.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 162–172 (IV(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"IV(B) — Prospective additional compensation versus past gifts","body":"Có chấp thuận bằng văn bản của mọi bên liên quan trước khi nhận bù đắp/lợi ích bên ngoài cạnh tranh hoặc có thể hợp lý tạo xung đột với employer. Quà cảm ơn cho kết quả quá khứ không tự là thỏa thuận thù lao tương lai; áp dụng independence/objectivity và quy định quà. Đề nghị gắn với return tương lai tạo động cơ khác.","body_en":"Obtain written consent from all parties involved before accepting outside compensation or benefits that compete with or could reasonably create a conflict with the employer's interest. A retrospective gift from a satisfied client is not automatically a prospective compensation agreement; apply independence/objectivity and employer gift rules. An offer tied to future returns raises different incentives.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 172–175 (IV(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"IV(C) — Reasonable supervision, delegation and response","body":"Supervisor phải nỗ lực hợp lý bảo đảm tuân thủ của người dưới quyền, kể cả không phải member. Giao việc không xóa trách nhiệm. Nếu không thể có hệ thống đủ, từ chối trách nhiệm bằng văn bản đến khi có quy trình phù hợp. Khi biết dấu hiệu sai phạm, điều tra và hạn chế hoạt động thích hợp, không chỉ nhận cam kết.","body_en":"Supervisors must make reasonable efforts to ensure compliance by those under their authority, including nonmembers. Delegating tasks does not remove supervisory responsibility. If an adequate system cannot be established, decline supervisory responsibility in writing until adequate procedures exist. Upon learning of possible misconduct, investigate and restrict activity appropriately rather than merely accepting assurances.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 174–183 (IV(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"V(A) — Research quality, external models and group conclusions","body":"Diligence tương xứng vai trò, độ phức tạp và hoàn cảnh. Đánh giá giả định, độ chặt chẽ, thời điểm, độc lập của nghiên cứu ngoài; kiểm tra mô hình, hiểu giới hạn thay vì coi output phần mềm là chân lý. Có thể tham gia báo cáo nhóm có cơ sở hợp lý dù khác kết luận cá nhân nếu quy trình và căn cứ vững.","body_en":"Diligence is proportional to role, investment complexity and circumstances. Evaluate external research for assumptions, rigor, timeliness and independence; test models and understand limitations instead of treating software outputs as authority. A member may support a group report with a reasonable basis even if disagreeing with its conclusion, provided the process and basis are sound.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 183–195 (V(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"V(B) — Service costs, process changes, risks and opinions","body":"Giải thích bản chất dịch vụ và chi phí liên quan cho khách hiện tại/tiềm năng. Công bố quy trình đầu tư cơ bản và kịp thời thông báo thay đổi trọng yếu; nêu rủi ro/giới hạn đáng kể. Phân biệt facts với dự báo/phán đoán kể cả giao tiếp ngắn. Chi tiết tùy dịch vụ và đối tượng nhưng hình thức không biện minh bỏ sót trọng yếu.","body_en":"Explain the nature of investment services and relevant costs to current and prospective clients. Disclose the basic investment process and promptly communicate material changes; identify significant risks and limitations. Distinguish verifiable facts from forecasts and judgment, including in short-form communication. The amount of detail depends on the service and audience, but material omissions are not justified by format.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 195–207 (V(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"V(C) — Records, digital channels and ownership","body":"Lưu hồ sơ hỗ trợ phân tích, khuyến nghị, hành động và giao tiếp đầu tư. Định dạng điện tử/tạm thời không được miễn. Áp dụng yêu cầu lưu của luật/firm; nếu không có yêu cầu áp dụng, CFAI khuyến nghị ít nhất 7 năm. Hồ sơ employer thường thuộc firm; khi cần hãy tái lập từ nguồn công khai thay vì lấy không phép.","body_en":"Keep records supporting analyses, recommendations, actions and investment-related communications. Electronic or ephemeral formats are not exempt. Retention requirements from law or firm policies apply; absent applicable requirements, CFA Institute recommends at least seven years. Employer records generally belong to the firm; recreate research from public sources if needed rather than taking records without permission.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 207–210 (V(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"VI(A) — Avoidance first and effective disclosure","body":"Tránh xung đột khi có thể hợp lý; nếu không, công bố đầy đủ, công bằng, nổi bật, dễ hiểu cho employer, khách và khách tiềm năng phù hợp. Cập nhật khi hoàn cảnh đổi. Sở hữu cổ phiếu, vị trí board và thù lao có thể ảnh hưởng phán đoán dù chưa chứng minh khuyến nghị thiên lệch. Công bố không cho phép hành vi chuẩn khác cấm.","body_en":"Avoid conflicts when reasonably practicable; otherwise provide full, fair, prominent and understandable disclosure to the employer, clients and prospects as applicable. Update disclosures when circumstances change. Stock ownership, board positions and compensation can compromise judgment even before a biased recommendation is proven. Disclosure does not authorize conduct prohibited by another standard.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 210–215 (VI(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"VI(B) — Beneficial ownership and family-client accounts","body":"Giao dịch khách ưu tiên trước employer và cá nhân. Tài khoản gia đình thực sự là client phải được đối xử công bằng, không tự ưu ái hay phạt; nếu member có beneficial ownership, cần xét hạn chế giao dịch cá nhân áp dụng. Cùng đầu tư không tự bị cấm nếu bảo đảm ưu tiên khách và nghĩa vụ khác.","body_en":"Client transactions take precedence over employer and personal transactions. Family accounts that are genuine client accounts should be treated fairly, not automatically favored or penalized; where the member has beneficial ownership, applicable personal trading restrictions also matter. Co-investment itself is not prohibited if client priority and other duties are respected.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 215–221 (VI(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"VI(C) — Referral benefits in cash or kind","body":"Công bố thù lao, khoản đối ứng hoặc lợi ích nhận/trả cho giới thiệu khách cho employer, khách và khách tiềm năng phù hợp. Giải thích bản chất và giá trị ước tính khi liên quan trước khi khách tiềm năng ký thỏa thuận dịch vụ. Nghiên cứu, dịch vụ, giảm giá phi tiền mặt cũng tạo động cơ giới thiệu.","body_en":"Disclose compensation, consideration or benefits received from or paid to others for referrals to the employer, clients and prospective clients as appropriate. Explain nature and estimated value when relevant before a prospective client enters the relevant service agreement. Noncash research, services or discounts can also create referral incentives.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 221–224 (VI(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"VII(A) — Program integrity and permitted opinions","body":"Không công bố hoặc xin nội dung thi mật, thông tin chấm thi mật hoặc tài liệu chương trình được bảo vệ. Nêu ý kiến về CFA Institute hoặc trải nghiệm thi có thể phù hợp nếu không tiết lộ thông tin mật hay làm suy yếu tính toàn vẹn chương trình. Tuân thủ quy định ứng viên không chỉ giới hạn đáp án thi.","body_en":"Do not disclose or solicit confidential exam content, confidential grading information or other protected program material. Expressing an opinion about CFA Institute or one's exam experience can be permissible if it does not reveal protected information or undermine program integrity. Compliance with candidate rules extends beyond the exam answers themselves.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 224–230 (VII(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"VII(B) — Designation, candidacy and factual claims","body":"Chỉ dùng designation khi có quyền; nghĩa vụ membership có ý nghĩa. CFA không phải chứng chỉ từng phần hay bảo đảm return cao hơn. Có thể nêu facts về kỳ thi đã qua và ngày nếu đúng; candidate status tùy đăng ký/tình trạng thực, không chỉ dự định đăng ký.","body_en":"Use the designation only while entitled to it; membership obligations matter. The CFA designation is not a partial credential or guarantee of superior returns. Factual statements about exams passed and dates are permitted when accurate; candidate status depends on the actual registration/status requirements, not an intention to enroll.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 230–235 (VII(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"}],"formulas":[{"name":"I — Professionalism","expr":"Applicable requirements → objective judgment → accurate representation → integrity → competence","meaning":"Tách I(A) tuân luật/dissociate, I(B) khách quan, I(C) misrepresentation, I(D) misconduct, I(E) competence.","conditions":"Một hành vi có thể vi phạm nhiều chuẩn; xét từng duty."},{"name":"II — Market integrity","expr":"Material? → Nonpublic? → Act/cause others?; Intent to mislead?","meaning":"II(A) xét tính chất thông tin và sử dụng; II(B) xét mục đích làm méo thị trường.","conditions":"Không dùng lợi nhuận hoặc price movement làm tiêu chí duy nhất."},{"name":"III — Duties to clients","expr":"Identify client → client first → fair allocation → suitability → accurate presentation → confidentiality","meaning":"Tách beneficiary, fair vs equal, advisory vs mandate, disclosure và ngoại lệ bảo mật.","conditions":"Luôn xét vai trò và facts."},{"name":"IV — Duties to employers","expr":"Employment duty → competing pay → written consent → reasonable supervision","meaning":"IV(A) loyalty; IV(B) additional compensation; IV(C) supervisory authority.","conditions":"Client interests ưu tiên; consent/disclosure khác nhau."},{"name":"V — Analysis and communication","expr":"Adequate research basis → disclose services/cost/process/risks → retain support","meaning":"V(A) basis; V(B) communication; V(C) records.","conditions":"Không dùng disclosure thay due diligence."},{"name":"VI — Conflicts","expr":"Avoid or disclose → client/employer trading priority → referral benefit disclosure","meaning":"VI(A), VI(B), VI(C) bổ sung cho nhau.","conditions":"Disclosure không chữa front-running hay inducement."},{"name":"VII — CFA responsibilities","expr":"Protect confidential program information → accurate status/designation references","meaning":"VII(A) conduct; VII(B) references.","conditions":"General opinions allowed; confidential exam content not allowed."}],"examples":[{"question_en":"A market permits selective trading on confidential earnings data, but the analyst is subject to the CFA Standards. She trades personally.","steps_vi":["Xác định chuẩn liên quan: I(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Standards nghiêm ngặt hơn; có thông tin material nonpublic và giao dịch. Lợi nhuận thực tế không quyết định vi phạm."],"answer":"Violation of I(A) and II(A)","check":"Original case; conclusion limited to facts stated."},{"question_en":"An issuer pays an analyst a fixed research fee, disclosed prominently in the report. The analyst independently reaches a negative recommendation.","steps_vi":["Xác định chuẩn liên quan: I(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Thù lao không phụ thuộc kết luận, công bố và nghiên cứu độc lập; không có dữ kiện mất khách quan."],"answer":"Issuer-paid research can comply with I(B).","check":"Original case; conclusion limited to facts stated."},{"question_en":"An advisor advertises a leveraged equity fund as guaranteeing a 12% annual return, although no guarantee exists.","steps_vi":["Xác định chuẩn liên quan: I(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Không có bảo đảm thực tế; lời hứa chắc chắn gây hiểu nhầm."],"answer":"Violation of I(C)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A research associate submits invented hotel receipts for reimbursement after a business trip.","steps_vi":["Xác định chuẩn liên quan: I(D). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Gian dối trong quan hệ nghề nghiệp dù không gây thiệt hại trực tiếp client."],"answer":"Violation of I(D)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A manager takes responsibility for complex structured credit without understanding its risks and refuses available training or qualified assistance.","steps_vi":["Xác định chuẩn liên quan: I(E). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Nhận nhiệm vụ vượt năng lực mà không xử lý thiếu hụt; kết quả và bằng cấp không miễn nghĩa vụ."],"answer":"Violation of I(E)","check":"Original case; conclusion limited to facts stated."},{"question_en":"An engineer privately provides an analyst with a credible, material, unreleased production failure. The analyst tells a trader to sell but does not trade himself.","steps_vi":["Xác định chuẩn liên quan: II(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Causing another to act bị cấm; không cần giao dịch cá nhân."],"answer":"Violation of II(A)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A trader arranges purchases and sales with an affiliated account solely to create an appearance of active demand.","steps_vi":["Xác định chuẩn liên quan: II(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Khối lượng giả nhằm đánh lừa thị trường, dù giá lệnh là market price."],"answer":"Violation of II(B)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A trustee votes pension shares to preserve the sponsoring employer's control despite a clear economic disadvantage to plan beneficiaries.","steps_vi":["Xác định chuẩn liên quan: III(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Lợi ích beneficiaries là trọng tâm; quyền sponsor không lấn át duty."],"answer":"Violation of III(A)","check":"Original case; conclusion limited to facts stated."},{"question_en":"After releasing a rating change to all affected clients through the agreed channel, an analyst provides extra detail to subscribers of a disclosed premium service.","steps_vi":["Xác định chuẩn liên quan: III(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Thông tin chung được phổ biến công bằng, service tier minh bạch không gây bất lợi theo dữ kiện."],"answer":"The arrangement can comply with III(B).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A conservative retiree with near-term spending needs is advised to place most assets in an illiquid leveraged fund without considering existing holdings.","steps_vi":["Xác định chuẩn liên quan: III(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Không đánh giá constraints, risk và tổng danh mục."],"answer":"Violation of III(C)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A marketer presents only the best account as the performance of the entire strategy, although other similar accounts performed poorly.","steps_vi":["Xác định chuẩn liên quan: III(D). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Lựa chọn gây sai lệch; số liệu account thật không làm presentation công bằng."],"answer":"Violation of III(D)","check":"Original case; conclusion limited to facts stated."},{"question_en":"An advisor shares a former client's medical and financial information with a friend to illustrate a sales opportunity without permission.","steps_vi":["Xác định chuẩn liên quan: III(E). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Former client vẫn thuộc phạm vi; không có ngoại lệ."],"answer":"Violation of III(E)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A departing employee copies the firm's confidential client database to a personal drive and solicits clients before the resignation takes effect.","steps_vi":["Xác định chuẩn liên quan: IV(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Lấy tài sản/information và solicit trước khi nghỉ gây hại employer."],"answer":"Violation of IV(A)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A client promises a manager a future bonus if the account outperforms. The manager accepts after obtaining only verbal permission from the employer.","steps_vi":["Xác định chuẩn liên quan: IV(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Thỏa thuận tương lai có thể tạo conflict; written consent trước acceptance."],"answer":"Violation of IV(B)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A supervisor learns of suspicious allocation records but merely asks the trader to promise not to repeat the conduct and makes no investigation.","steps_vi":["Xác định chuẩn liên quan: IV(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Reasonable effort gồm điều tra và biện pháp giám sát, không chỉ lời hứa."],"answer":"Violation of IV(C)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A portfolio manager recommends a complex product based solely on a salesperson's assurance, despite obvious gaps in the information and no research.","steps_vi":["Xác định chuẩn liên quan: V(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Không đủ reasonable basis; kết quả sau không sửa thiếu diligence."],"answer":"Violation of V(A)","check":"Original case; conclusion limited to facts stated."},{"question_en":"An advisor describes advisory fees but knowingly omits significant third-party platform costs from communications to prospective clients.","steps_vi":["Xác định chuẩn liên quan: V(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Chi phí dịch vụ cần công bố cho prospects, bao gồm liên quan bên thứ ba."],"answer":"Violation of V(B)","check":"Original case; conclusion limited to facts stated."},{"question_en":"An analyst deletes all model inputs and research notes while retaining only the final investment recommendation, making the basis impossible to substantiate.","steps_vi":["Xác định chuẩn liên quan: V(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Records phải hỗ trợ analysis/actions; final report có thể không đủ."],"answer":"Violation of V(C)","check":"Original case; conclusion limited to facts stated."},{"question_en":"An analyst owns a significant position in a covered issuer and does not disclose it to clients or the employer, although the report is carefully researched.","steps_vi":["Xác định chuẩn liên quan: VI(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Reasonably expected conflict từ holding; adequate research không thay disclosure."],"answer":"Violation of VI(A)","check":"Original case; conclusion limited to facts stated."},{"question_en":"An advisor purchases shares in a personal account immediately before executing a known large client buy order in the same security to benefit from expected price impact.","steps_vi":["Xác định chuẩn liên quan: VI(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Front-running, beneficial owner ưu tiên trước client."],"answer":"Violation of VI(B)","check":"Original case; conclusion limited to facts stated."},{"question_en":"An advisor receives free research for referring clients to an outside provider and discloses nothing because no cash changes hands.","steps_vi":["Xác định chuẩn liên quan: VI(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Noncash consideration cũng là benefit phải disclose."],"answer":"Violation of VI(C)","check":"Original case; conclusion limited to facts stated."},{"question_en":"After an exam, a candidate posts which curriculum topic was not tested, without reproducing any question.","steps_vi":["Xác định chuẩn liên quan: VII(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Content-specific topic coverage là confidential; không cần nguyên văn."],"answer":"Violation of VII(A)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A Level II candidate lists 'CFA, expected next year' after her name on a business card.","steps_vi":["Xác định chuẩn liên quan: VII(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Không có partial/expected designation; ghi candidacy chính xác thay vì suffix sai."],"answer":"Violation of VII(B)","check":"Original case; conclusion limited to facts stated."}],"questions":[{"stem_en":"A market permits selective trading on confidential earnings data, but the analyst is subject to the CFA Standards. She trades personally.","options":["No violation because local law permits the trade.","Violation only if the trade produces a profit.","Violation of I(A) and II(A)"],"correct":2,"why_vi":"Standards nghiêm ngặt hơn; có thông tin material nonpublic và giao dịch. Lợi nhuận thực tế không quyết định vi phạm.","trap_vi":"Không áp dụng local law như một ngoại lệ miễn trừ Standards.","standard":"I(A)"},{"stem_en":"An issuer pays an analyst a fixed research fee, disclosed prominently in the report. The analyst independently reaches a negative recommendation.","options":["Issuer-paid research can comply with I(B).","All issuer-paid research is prohibited.","A negative rating automatically demonstrates a conflict violation."],"correct":0,"why_vi":"Thù lao không phụ thuộc kết luận, công bố và nghiên cứu độc lập; không có dữ kiện mất khách quan.","trap_vi":"Không nhầm nguồn trả phí với kết luận tất yếu thiên lệch.","standard":"I(B)"},{"stem_en":"An advisor advertises a leveraged equity fund as guaranteeing a 12% annual return, although no guarantee exists.","options":["Compliant if past returns exceeded 12%.","Compliant if the fund has a long operating history.","Violation of I(C)"],"correct":2,"why_vi":"Không có bảo đảm thực tế; lời hứa chắc chắn gây hiểu nhầm.","trap_vi":"Past performance không biến expected return thành guarantee.","standard":"I(C)"},{"stem_en":"A research associate submits invented hotel receipts for reimbursement after a business trip.","options":["Violation of I(D)","Compliant because no client account was harmed.","Compliant if the employer has not detected the receipts."],"correct":0,"why_vi":"Gian dối trong quan hệ nghề nghiệp dù không gây thiệt hại trực tiếp client.","trap_vi":"Không đánh đồng misconduct với investment loss.","standard":"I(D)"},{"stem_en":"A manager takes responsibility for complex structured credit without understanding its risks and refuses available training or qualified assistance.","options":["Violation of I(E)","No violation until a portfolio loss occurs.","No violation because she holds a finance degree."],"correct":0,"why_vi":"Nhận nhiệm vụ vượt năng lực mà không xử lý thiếu hụt; kết quả và bằng cấp không miễn nghĩa vụ.","trap_vi":"Xét khả năng thực hiện nhiệm vụ cụ thể.","standard":"I(E)"},{"stem_en":"An engineer privately provides an analyst with a credible, material, unreleased production failure. The analyst tells a trader to sell but does not trade himself.","options":["Violation of II(A)","Compliant because he made no personal trade.","Compliant if he does not identify the engineer."],"correct":0,"why_vi":"Causing another to act bị cấm; không cần giao dịch cá nhân.","trap_vi":"Không lách bằng lời khuyên gián tiếp.","standard":"II(A)"},{"stem_en":"A trader arranges purchases and sales with an affiliated account solely to create an appearance of active demand.","options":["Violation of II(B)","Compliant if trades are executed at market prices.","Compliant if no external investor trades."],"correct":0,"why_vi":"Khối lượng giả nhằm đánh lừa thị trường, dù giá lệnh là market price.","trap_vi":"Mục đích quan trọng hơn hình thức thực hiện.","standard":"II(B)"},{"stem_en":"A trustee votes pension shares to preserve the sponsoring employer's control despite a clear economic disadvantage to plan beneficiaries.","options":["Compliant because the employer sponsors the plan.","Compliant if the trustee discloses the sponsor's request.","Violation of III(A)"],"correct":2,"why_vi":"Lợi ích beneficiaries là trọng tâm; quyền sponsor không lấn át duty.","trap_vi":"Xác định client thật sự.","standard":"III(A)"},{"stem_en":"After releasing a rating change to all affected clients through the agreed channel, an analyst provides extra detail to subscribers of a disclosed premium service.","options":["The arrangement can comply with III(B).","Fair dealing requires identical discussion time for all clients.","Premium services always violate III(B)."],"correct":0,"why_vi":"Thông tin chung được phổ biến công bằng, service tier minh bạch không gây bất lợi theo dữ kiện.","trap_vi":"Fair không phải equal.","standard":"III(B)"},{"stem_en":"A conservative retiree with near-term spending needs is advised to place most assets in an illiquid leveraged fund without considering existing holdings.","options":["Compliant if the fund has a high expected return.","Compliant if other clients own the same fund.","Violation of III(C)"],"correct":2,"why_vi":"Không đánh giá constraints, risk và tổng danh mục.","trap_vi":"Expected return không thay thế suitability.","standard":"III(C)"},{"stem_en":"A marketer presents only the best account as the performance of the entire strategy, although other similar accounts performed poorly.","options":["Compliant if the selected return is numerically correct.","Violation of III(D)","Compliant if the client is sophisticated."],"correct":1,"why_vi":"Lựa chọn gây sai lệch; số liệu account thật không làm presentation công bằng.","trap_vi":"Phân biệt arithmetic accuracy với representativeness.","standard":"III(D)"},{"stem_en":"An advisor shares a former client's medical and financial information with a friend to illustrate a sales opportunity without permission.","options":["Violation of III(E)","Compliant because the client relationship ended.","Compliant if the friend promises secrecy."],"correct":0,"why_vi":"Former client vẫn thuộc phạm vi; không có ngoại lệ.","trap_vi":"Không nhầm chấm dứt quan hệ với chấm dứt confidentiality.","standard":"III(E)"},{"stem_en":"A departing employee copies the firm's confidential client database to a personal drive and solicits clients before the resignation takes effect.","options":["Violation of IV(A)","Compliant because the employee created some database entries.","Compliant if the clients may benefit from lower fees."],"correct":0,"why_vi":"Lấy tài sản/information và solicit trước khi nghỉ gây hại employer.","trap_vi":"Không coi dữ liệu lưu trên thiết bị cá nhân là tài sản cá nhân.","standard":"IV(A)"},{"stem_en":"A client promises a manager a future bonus if the account outperforms. The manager accepts after obtaining only verbal permission from the employer.","options":["Compliant because the client is the beneficiary.","Compliant because the bonus has not yet been paid.","Violation of IV(B)"],"correct":2,"why_vi":"Thỏa thuận tương lai có thể tạo conflict; written consent trước acceptance.","trap_vi":"Không đợi payment mới phát sinh vấn đề.","standard":"IV(B)"},{"stem_en":"A supervisor learns of suspicious allocation records but merely asks the trader to promise not to repeat the conduct and makes no investigation.","options":["Violation of IV(C)","Compliant because the trader promised improvement.","Compliant if the supervisor delegates the issue informally."],"correct":0,"why_vi":"Reasonable effort gồm điều tra và biện pháp giám sát, không chỉ lời hứa.","trap_vi":"Không nhầm delegation với discharge of duty.","standard":"IV(C)"},{"stem_en":"A portfolio manager recommends a complex product based solely on a salesperson's assurance, despite obvious gaps in the information and no research.","options":["Compliant if the salesperson is experienced.","Compliant if the product later earns a profit.","Violation of V(A)"],"correct":2,"why_vi":"Không đủ reasonable basis; kết quả sau không sửa thiếu diligence.","trap_vi":"Không nhầm suitability với research basis.","standard":"V(A)"},{"stem_en":"An advisor describes advisory fees but knowingly omits significant third-party platform costs from communications to prospective clients.","options":["Violation of V(B)","Compliant because the costs are paid to another entity.","Compliant until a prospect signs an agreement."],"correct":0,"why_vi":"Chi phí dịch vụ cần công bố cho prospects, bao gồm liên quan bên thứ ba.","trap_vi":"Không giới hạn disclosure vào client đã ký hợp đồng.","standard":"V(B)"},{"stem_en":"An analyst deletes all model inputs and research notes while retaining only the final investment recommendation, making the basis impossible to substantiate.","options":["Compliant because the final recommendation is retained.","Compliant if the analyst remembers the assumptions.","Violation of V(C)"],"correct":2,"why_vi":"Records phải hỗ trợ analysis/actions; final report có thể không đủ.","trap_vi":"Không nhầm publication với recordkeeping.","standard":"V(C)"},{"stem_en":"An analyst owns a significant position in a covered issuer and does not disclose it to clients or the employer, although the report is carefully researched.","options":["Compliant because V(A) research is adequate.","Violation of VI(A)","Compliant if the analyst has not traded recently."],"correct":1,"why_vi":"Reasonably expected conflict từ holding; adequate research không thay disclosure.","trap_vi":"Một Standard đạt không miễn Standard khác.","standard":"VI(A)"},{"stem_en":"An advisor purchases shares in a personal account immediately before executing a known large client buy order in the same security to benefit from expected price impact.","options":["Violation of VI(B)","Compliant if the client eventually obtains the shares.","Compliant if the personal purchase uses a different broker."],"correct":0,"why_vi":"Front-running, beneficial owner ưu tiên trước client.","trap_vi":"Không cần chứng minh client lỗ thực tế.","standard":"VI(B)"},{"stem_en":"An advisor receives free research for referring clients to an outside provider and discloses nothing because no cash changes hands.","options":["Compliant because research is not money.","Compliant if the outside provider charges market fees.","Violation of VI(C)"],"correct":2,"why_vi":"Noncash consideration cũng là benefit phải disclose.","trap_vi":"Không giới hạn referral fees vào tiền mặt.","standard":"VI(C)"},{"stem_en":"After an exam, a candidate posts which curriculum topic was not tested, without reproducing any question.","options":["Compliant because no question wording was shared.","Violation of VII(A)","Compliant because the exam has ended."],"correct":1,"why_vi":"Content-specific topic coverage là confidential; không cần nguyên văn.","trap_vi":"Không coi sau exam là hết nghĩa vụ.","standard":"VII(A)"},{"stem_en":"A Level II candidate lists 'CFA, expected next year' after her name on a business card.","options":["Compliant if she expects to pass all exams.","Violation of VII(B)","Compliant if her employer approves."],"correct":1,"why_vi":"Không có partial/expected designation; ghi candidacy chính xác thay vì suffix sai.","trap_vi":"Không nhầm enrollment với charter.","standard":"VII(B)"}],"cards":[{"front_en":"I(A) Knowledge of the Law — Scope and hierarchy","back_vi":"Xác định luật và quy định thực sự áp dụng cho hoạt động: nơi cư trú, nơi cung cấp dịch vụ, quy định nghề nghiệp và Code and Standards. Nếu có nhiều yêu cầu áp dụng, tuân thủ yêu cầu nghiêm ngặt hơn. Nếu nước sở tại không có quy định tương ứng, Standards vẫn áp dụng. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29] | Exam trap: Không tự chọn luật thuận lợi nhất hoặc mặc định luật quốc gia luôn nghiêm ngặt hơn Standards."},{"front_en":"I(A) Knowledge of the Law — Knowing association","back_vi":"Không cố ý tham gia hoặc hỗ trợ vi phạm. Khi có căn cứ nhận biết hành vi vi phạm, tìm cách chấm dứt hoặc báo cáo trong nội bộ; nếu không khắc phục được phải tách khỏi hoạt động, từ chối dùng tài liệu sai hoặc thực hiện giao dịch, thậm chí nghỉ việc khi không còn phương án. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29] | Exam trap: Chỉ phản đối bằng lời nhưng tiếp tục hỗ trợ không phải dissociation."},{"front_en":"I(A) Knowledge of the Law — Reporting and cross-border products","back_vi":"Tham vấn compliance hoặc luật sư khi chưa rõ luật. Báo cáo cơ quan ngoài công ty được khuyến khích nhưng Standards không tự đặt nghĩa vụ báo cáo mọi vi phạm ra bên ngoài; luật áp dụng có thể bắt buộc. Người cấu trúc/sản xuất sản phẩm cũng phải hiểu quy định nơi sản phẩm được phân phối. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29] | Exam trap: Không nhầm quy trình báo cáo được khuyến nghị với nghĩa vụ pháp lý; không đổ trách nhiệm tuân thủ cho compliance."},{"front_en":"A market permits selective trading on confidential earnings data, but the analyst is subject to the CFA Standards. She trades personally.","back_vi":"Violation of I(A) and II(A) — Standards nghiêm ngặt hơn; có thông tin material nonpublic và giao dịch. Lợi nhuận thực tế không quyết định vi phạm. | Trap: Không áp dụng local law như một ngoại lệ miễn trừ Standards."},{"front_en":"I(B) Independence and Objectivity — Influence and gifts","back_vi":"Duy trì nhận định độc lập, không đề nghị/nhận/trao lợi ích có thể hợp lý được kỳ vọng làm lệch khách quan. Xét giá trị, bối cảnh, tần suất và người trả; entertainment thông thường không mặc nhiên bị cấm. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41] | Exam trap: Không cần chứng minh đã thay đổi khuyến nghị mới có vi phạm."},{"front_en":"I(B) Independence and Objectivity — Client gifts versus third parties","back_vi":"Quà từ khách hàng sau kết quả đã đạt có thể được chấp nhận nếu không làm suy giảm khách quan, phải thông báo employer trước nếu khả thi, nếu không thì sau. Phần thưởng thỏa thuận cho hiệu suất tương lai có thể là additional compensation theo IV(B). Quà từ broker/issuer có động cơ ảnh hưởng đòi hỏi thận trọng cao hơn. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41] | Exam trap: Disclosure không cứu được quà gây mất độc lập; không nhầm thông báo với written consent."},{"front_en":"I(B) Independence and Objectivity — Research pressure and issuer-paid research","back_vi":"Không để corporate access, underwriting, sales pressure hay management tác động rating; issuer-paid research có thể chấp nhận nếu khách quan, thù lao cố định không gắn kết luận/giá cổ phiếu và công bố rõ nguồn trả phí. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41] | Exam trap: Trả bằng option hay phụ thuộc rating tạo động cơ; không coi mọi issuer-paid research đều bị cấm."},{"front_en":"I(B) Independence and Objectivity — Travel and manager selection","back_vi":"Tự chi trả chuyến đi khi khả thi; nếu không có phương tiện thương mại, chuyến đi do issuer bố trí có thể phù hợp nếu hợp lý, cần thiết, không xa hoa. Due diligence khi chọn manager/broker; không đổi hợp đồng để nhận ưu đãi cá nhân. Không nhận phân bổ IPO khan hiếm nhờ vị thế khách hàng. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41] | Exam trap: Đi công tác cần thiết khác chuyến nghỉ dưỡng; xét tính hợp lý thực tế."},{"front_en":"An issuer pays an analyst a fixed research fee, disclosed prominently in the report. The analyst independently reaches a negative recommendation.","back_vi":"Issuer-paid research can comply with I(B). — Thù lao không phụ thuộc kết luận, công bố và nghiên cứu độc lập; không có dữ kiện mất khách quan. | Trap: Không nhầm nguồn trả phí với kết luận tất yếu thiên lệch."},{"front_en":"I(C) Misrepresentation — Accuracy and omissions","back_vi":"Không cố ý trình bày sai về analysis, actions hoặc dịch vụ: lời nói, email, website, marketing và tài liệu bên thứ ba. Việc bỏ thông tin trọng yếu, chọn lọc thành tích để gây hiểu nhầm cũng là misrepresentation. Khi phát hiện thông tin sai, sửa và ngừng sử dụng. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49] | Exam trap: Không chỉ những câu sai trắng trợn; omission có thể gây hiểu nhầm."},{"front_en":"I(C) Misrepresentation — Performance and guarantees","back_vi":"Không hứa mức lợi nhuận chắc chắn cho sản phẩm rủi ro. Có thể mô tả bảo đảm thực tế của bên bảo lãnh cùng điều kiện/rủi ro. Không chọn benchmark hay vendor định giá chỉ để tạo hình ảnh đẹp, không che phí hoặc thiếu dữ liệu quan trọng. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49] | Exam trap: Số liệu đúng nhưng benchmark không phù hợp có thể gây hiểu nhầm."},{"front_en":"I(C) Misrepresentation — Plagiarism and internal research","back_vi":"Ghi nguồn cho nội dung, ý tưởng, mô hình, bảng/biểu đồ, dự báo của người khác; diễn đạt lại không bỏ nghĩa vụ attribution. Có thể sử dụng dữ liệu từ dịch vụ báo cáo tài chính/thống kê được công nhận không cần ghi từng nguồn theo guidance; tài liệu thuộc sở hữu firm có thể tiếp tục dùng sau khi tác giả rời firm, nhưng không nhận toàn bộ công lao cá nhân. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49] | Exam trap: Không áp dụng ngoại lệ dữ liệu cho báo cáo phân tích độc quyền."},{"front_en":"An advisor advertises a leveraged equity fund as guaranteeing a 12% annual return, although no guarantee exists.","back_vi":"Violation of I(C) — Không có bảo đảm thực tế; lời hứa chắc chắn gây hiểu nhầm. | Trap: Past performance không biến expected return thành guarantee."},{"front_en":"I(D) Misconduct — Professional integrity","back_vi":"Không thực hiện hành vi nghề nghiệp gian dối, lừa đảo, thiếu trung thực; hành vi khác có thể vi phạm nếu phản ánh bất lợi đến danh tiếng nghề nghiệp, liêm chính hay năng lực. Không dùng Standards để xử lý bất đồng cá nhân/chính trị không liên quan đạo đức nghề nghiệp. [CFAI PDF pp. 101–103; Kaplan PDF pp. 172; SAPP PDF pp. 50–52] | Exam trap: Không phải mọi vi phạm pháp luật ngoài nghề đều tự động là misconduct theo Standard này."},{"front_en":"I(D) Misconduct — Personal behavior and evidence","back_vi":"Gian lận chi phí, giả mạo chứng từ, lạm dụng tài sản hoặc hành vi ảnh hưởng khả năng làm việc có thể vi phạm; xét bản chất và liên hệ nghề nghiệp, không chỉ tình trạng bị buộc tội. [CFAI PDF pp. 101–103; Kaplan PDF pp. 172; SAPP PDF pp. 50–52] | Exam trap: Không cần thiệt hại đầu tư mới cấu thành gian dối nghề nghiệp."},{"front_en":"A research associate submits invented hotel receipts for reimbursement after a business trip.","back_vi":"Violation of I(D) — Gian dối trong quan hệ nghề nghiệp dù không gây thiệt hại trực tiếp client. | Trap: Không đánh đồng misconduct với investment loss."},{"front_en":"I(E) Competence — Role-specific capability","back_vi":"Phải hành nghề với năng lực cần thiết và duy trì năng lực phù hợp nhiệm vụ: knowledge, skills, abilities, kinh nghiệm và công nghệ cần thiết. Khi nhận nhiệm vụ mới, chủ động phát triển năng lực trước khi thực hiện phần vượt khả năng; có thể tìm hỗ trợ chuyên môn thích hợp. [CFAI PDF pp. 104–107; Kaplan PDF pp. 172; SAPP PDF pp. 53–54] | Exam trap: Không chỉ dựa vào bằng cấp, số năm kinh nghiệm hoặc chức danh."},{"front_en":"I(E) Competence — Outcomes and learning","back_vi":"Kết quả đầu tư xấu không tự chứng minh thiếu năng lực; xét quy trình, kiến thức và mức độ chuẩn bị. Continuing education, seminars, professional development, self-study là cách được khuyến nghị, không có số giờ cố định bắt buộc trong Standard I(E). [CFAI PDF pp. 104–107; Kaplan PDF pp. 172; SAPP PDF pp. 53–54] | Exam trap: Không nhầm competence với bảo đảm thành công hoặc mandatory CE hours."},{"front_en":"A manager takes responsibility for complex structured credit without understanding its risks and refuses available training or qualified assistance.","back_vi":"Violation of I(E) — Nhận nhiệm vụ vượt năng lực mà không xử lý thiếu hụt; kết quả và bằng cấp không miễn nghĩa vụ. | Trap: Xét khả năng thực hiện nhiệm vụ cụ thể."},{"front_en":"II(A) Material Nonpublic Information — Materiality and public status","back_vi":"Thông tin material nếu ảnh hưởng đáng kể đến giá trị hoặc nhà đầu tư hợp lý muốn biết trước quyết định. Xét độ cụ thể, độ tin cậy, sự kiện, quy mô, thời điểm và tác động. Nonpublic nếu chưa được phổ biến ra thị trường; thông báo cho nhóm analyst kín không tự thành public. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61] | Exam trap: Tin không chắc chắn không mặc nhiên immaterial; selective disclosure không phải public release."},{"front_en":"II(A) Material Nonpublic Information — Prohibited action and mosaic","back_vi":"Không hành động hoặc khiến người khác hành động dựa trên material nonpublic information, kể cả securities liên quan hoặc quỹ. Mosaic theory cho phép tổng hợp thông tin public với nonpublic không trọng yếu để suy ra kết luận material. Giữ hồ sơ phân tích. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61] | Exam trap: Không dùng mosaic để hợp thức hóa một mẩu MNPI; không truyền tín hiệu để người khác giao dịch."},{"front_en":"II(A) Material Nonpublic Information — Research and communications","back_vi":"Có thể khuyến khích issuer phổ biến thông tin cho thị trường; chờ phổ biến rộng rãi trước khi sử dụng. Expert networks có thể cung cấp insight hợp pháp nhưng phải tránh MNPI; không cấm research hợp lệ chỉ vì kết luận khác consensus. Nếu MNPI vô tình đến, hạn chế truy cập và liên hệ compliance. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61] | Exam trap: Không cần mọi nhà đầu tư thực sự đọc tin; cần thông tin được đưa ra thị trường."},{"front_en":"An engineer privately provides an analyst with a credible, material, unreleased production failure. The analyst tells a trader to sell but does not trade himself.","back_vi":"Violation of II(A) — Causing another to act bị cấm; không cần giao dịch cá nhân. | Trap: Không lách bằng lời khuyên gián tiếp."},{"front_en":"II(B) Market Manipulation — Information-based manipulation","back_vi":"Cấm lan truyền thông tin sai/lừa dối nhằm gây hiểu nhầm market participants hoặc làm méo giá/volume; ví dụ pump-and-dump bằng tin giả, báo cáo có chủ đích sai. [CFAI PDF pp. 120–125; Kaplan PDF pp. 174–175; SAPP PDF pp. 62–66] | Exam trap: Intent to mislead là dấu hiệu trọng tâm; khác dự báo thiện chí sau đó sai."},{"front_en":"II(B) Market Manipulation — Transaction-based manipulation","back_vi":"Giao dịch tạo khối lượng giả, giá đóng cửa giả, wash trades, kiểm soát nguồn cung để thao túng giá liên quan có thể vi phạm. Giao dịch lớn hợp lệ để đáp ứng nhu cầu, arbitrage, liquidity hoặc rebalancing không tự động là thao túng vì có ảnh hưởng giá. [CFAI PDF pp. 120–125; Kaplan PDF pp. 174–175; SAPP PDF pp. 62–66] | Exam trap: Xét mục đích, bối cảnh, cấu trúc giao dịch; không suy luận từ biến động đơn thuần."},{"front_en":"A trader arranges purchases and sales with an affiliated account solely to create an appearance of active demand.","back_vi":"Violation of II(B) — Khối lượng giả nhằm đánh lừa thị trường, dù giá lệnh là market price. | Trap: Mục đích quan trọng hơn hình thức thực hiện."},{"front_en":"III(A) Loyalty, Prudence, and Care — Client first and fiduciary duties","back_vi":"Hành động vì lợi ích client, sử dụng reasonable care và prudent judgment, đặt client trước employer và cá nhân. Xác định client thực sự: người thụ hưởng pension hoặc đối tượng được phục vụ, không mặc định người ký hợp đồng là beneficiary. Tuân thủ tài liệu quản lý tài sản và luật áp dụng. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77] | Exam trap: Không hứa tối đa hóa return bất kể rủi ro; không đồng nhất mọi vai trò với fiduciary theo luật."},{"front_en":"III(A) Loyalty, Prudence, and Care — Brokerage, soft commissions and execution","back_vi":"Client brokerage là tài sản client: chọn execution theo lợi ích client, chất lượng/giá tổng thể; nghiên cứu/dịch vụ dùng commission phải hỗ trợ client phù hợp. Directed brokerage theo yêu cầu client cần thông tin về trade-offs, có thể hạn chế best execution. Không dùng commission mua lợi ích cá nhân hoặc chi phí không phục vụ client. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77] | Exam trap: Best execution không nhất thiết commission thấp nhất; disclose xung đột không đủ nếu lợi ích client bị xâm hại."},{"front_en":"III(A) Loyalty, Prudence, and Care — Proxy and custody","back_vi":"Xem xét proxy voting theo lợi ích client; cân nhắc chi phí và lợi ích, không mặc định phải vote mọi proxy. Tách tài sản client, quản lý quyền hạn, cung cấp báo cáo holdings và transactions theo yêu cầu phù hợp. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77] | Exam trap: Không vote theo lợi ích employer; có thể không vote nếu chi phí lớn hơn lợi ích."},{"front_en":"A trustee votes pension shares to preserve the sponsoring employer's control despite a clear economic disadvantage to plan beneficiaries.","back_vi":"Violation of III(A) — Lợi ích beneficiaries là trọng tâm; quyền sponsor không lấn át duty. | Trap: Xác định client thật sự."},{"front_en":"III(B) Fair Dealing — Fair not identical","back_vi":"Đối xử công bằng, khách quan khi disseminate khuyến nghị và thực hiện actions. Không yêu cầu identical service; gói tư vấn khác nhau có thể tồn tại nếu minh bạch, không làm bất lợi client khác. Cung cấp cơ hội công bằng cho client phù hợp. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85] | Exam trap: Không ưu tiên client lớn trước khi disseminate thông tin chung."},{"front_en":"III(B) Fair Dealing — Recommendations and changes","back_vi":"Thông báo khuyến nghị mới/thay đổi kịp thời cho các client liên quan, dùng phương thức giảm chênh lệch thời gian, không cho một số người giao dịch trước; client đặt lệnh trái khuyến nghị mới cần được biết thay đổi trước khi thực hiện nếu liên quan. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85] | Exam trap: Phân biệt follow-up chi tiết sau công bố chung và selective advance access."},{"front_en":"III(B) Fair Dealing — Allocation","back_vi":"Phân bổ công bằng theo policy công bố trước, phù hợp mandate; pro rata là một cách cho issue khan hiếm, xét lot size và tính khả thi. Không ưu tiên account cá nhân, account trả phí cao hay cherry-pick giao dịch lời. Family account là client bình thường nếu quản lý như client khác, tùy beneficial ownership và conflict. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85] | Exam trap: Không bắt buộc mọi account nhận số lượng giống nhau; không loại client chỉ vì quan hệ gia đình."},{"front_en":"After releasing a rating change to all affected clients through the agreed channel, an analyst provides extra detail to subscribers of a disclosed premium service.","back_vi":"The arrangement can comply with III(B). — Thông tin chung được phổ biến công bằng, service tier minh bạch không gây bất lợi theo dữ kiện. | Trap: Fair không phải equal."},{"front_en":"III(C) Suitability — Advisory relationship","back_vi":"Thu thập thông tin khách hàng trước khuyến nghị: kinh nghiệm, risk/return objectives, financial circumstances và constraints, cập nhật định kỳ. Đánh giá investment phù hợp mục tiêu và giới hạn đã viết, xét tổng danh mục, leverage, liquidity, time horizon và khả năng chịu lỗ. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95] | Exam trap: Sản phẩm tốt không mặc nhiên phù hợp; willingness khác ability."},{"front_en":"III(C) Suitability — Mandate versus advisory","back_vi":"Manager quản lý pooled fund hoặc mandate cụ thể phải tuân thủ objective/style/constraints đã công bố; không có nghĩa phải đánh giá suitability từng investor cuối nếu không có advisory relationship với họ. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95] | Exam trap: Không tự đổi mandate chỉ vì cơ hội lợi nhuận."},{"front_en":"III(C) Suitability — Unsolicited unsuitable orders","back_vi":"Trao đổi lý do không phù hợp trước giao dịch; đánh giá tác động danh mục. Nếu tác động nhỏ, theo policy firm và client xác nhận hiểu; nếu tác động trọng yếu, cân nhắc cập nhật IPS hợp lý, separate client-directed account hoặc xem xét tiếp tục quan hệ nếu không giải quyết được. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95] | Exam trap: Không phải cứ client yêu cầu thì được bỏ IPS; không phải mọi unsolicited unsuitable order đều bắt buộc từ chối."},{"front_en":"A conservative retiree with near-term spending needs is advised to place most assets in an illiquid leveraged fund without considering existing holdings.","back_vi":"Violation of III(C) — Không đánh giá constraints, risk và tổng danh mục. | Trap: Expected return không thay thế suitability."},{"front_en":"III(D) Performance Presentation — Fair accurate complete","back_vi":"Nỗ lực hợp lý để trình bày hiệu quả đầu tư công bằng, chính xác, đầy đủ; past performance không bảo đảm future results; không lựa chọn account/period có chủ đích gây sai lệch. Brief presentation có thể được dùng nếu nêu giới hạn và cung cấp chi tiết khi yêu cầu. [CFAI PDF pp. 152–156; Kaplan PDF pp. 178–179; SAPP PDF pp. 96–99] | Exam trap: Không đồng nhất ngắn gọn với thiếu trung thực; không đưa forecast như thành tích thực."},{"front_en":"III(D) Performance Presentation — Composite and disclosures","back_vi":"Khuyến nghị dùng weighted composite của portfolios tương tự, giữ terminated accounts trong lịch sử đến ngày chấm dứt, công bố phí, gross/net, simulated/model returns, benchmark và phương pháp tính; lưu dữ liệu. GIPS được khuyến nghị nhưng không bắt buộc bởi III(D). [CFAI PDF pp. 152–156; Kaplan PDF pp. 178–179; SAPP PDF pp. 96–99] | Exam trap: Không chọn best account làm đại diện; GIPS compliance không tự động chứng minh mọi presentation công bằng."},{"front_en":"A marketer presents only the best account as the performance of the entire strategy, although other similar accounts performed poorly.","back_vi":"Violation of III(D) — Lựa chọn gây sai lệch; số liệu account thật không làm presentation công bằng. | Trap: Phân biệt arithmetic accuracy với representativeness."},{"front_en":"III(E) Preservation of Confidentiality — Scope and exceptions","back_vi":"Bảo mật thông tin current, former và prospective clients. Ngoại lệ: thông tin liên quan hành vi bất hợp pháp của client, luật yêu cầu disclosure, hoặc client cho phép. Nghĩa vụ pháp lý báo cáo có thể phát sinh; không tự quyết đoán nếu không rõ, hỏi legal/compliance. [CFAI PDF pp. 157–160; Kaplan PDF pp. 179; SAPP PDF pp. 100–104] | Exam trap: Former client vẫn được bảo mật; không chia sẻ vì tò mò hay lợi ích marketing."},{"front_en":"III(E) Preservation of Confidentiality — PCP and electronic security","back_vi":"Standard không ngăn hợp tác với CFA Institute Professional Conduct Program (PCP) trong điều tra, với điều kiện luật áp dụng cho phép; PCP bảo mật. Dữ liệu điện tử/email/cloud cần kiểm soát truy cập, hạn chế chia sẻ với nhân sự được phép và phục vụ client. [CFAI PDF pp. 157–160; Kaplan PDF pp. 179; SAPP PDF pp. 100–104] | Exam trap: Không coi PCP là ngoại lệ vô hạn vượt luật; không coi đồng nghiệp nào cũng có quyền truy cập."},{"front_en":"An advisor shares a former client's medical and financial information with a friend to illustrate a sales opportunity without permission.","back_vi":"Violation of III(E) — Former client vẫn thuộc phạm vi; không có ngoại lệ. | Trap: Không nhầm chấm dứt quan hệ với chấm dứt confidentiality."},{"front_en":"IV(A) Loyalty — Employment duties and independent practice","back_vi":"Trong công việc phải vì lợi ích employer, không chiếm dụng kỹ năng, tài liệu, thông tin bí mật hay cơ hội gây hại. Client first vẫn ưu tiên; không bắt buộc hy sinh mọi nghĩa vụ gia đình. Independent contractor tuân điều khoản hợp đồng. Hoạt động độc lập cạnh tranh có thù lao cần thông báo đầy đủ bản chất, thời hạn, thù lao và nhận consent trước khi bắt đầu. [CFAI PDF pp. 161–171; Kaplan PDF pp. 180–181; SAPP PDF pp. 105–115] | Exam trap: Không phải mọi hoạt động ngoài giờ đều bị cấm; xét cạnh tranh và ảnh hưởng employer."},{"front_en":"IV(A) Loyalty — Leaving employer and social media","back_vi":"Trước ngày nghỉ hiệu lực vẫn thực hiện nghĩa vụ; có thể chuẩn bị hợp pháp cho công việc mới nhưng không solicit client trước khi rời, không lấy client lists, records/trade secrets, kể cả từ thiết bị cá nhân. Sau nghỉ có thể dùng kiến thức/kỹ năng chung, liên hệ từ thông tin công khai/nhớ tên nếu không vi phạm hợp đồng/luật; thỏa thuận tuyển dụng giữa firms có thể cho phép phạm vi dữ liệu nhất định. [CFAI PDF pp. 161–171; Kaplan PDF pp. 180–181; SAPP PDF pp. 105–115] | Exam trap: Không đồng nhất kinh nghiệm tích lũy với dữ liệu sở hữu firm; tuân policy social media."},{"front_en":"IV(A) Loyalty — Whistleblowing","back_vi":"Trong trường hợp đặc biệt, hành động bảo vệ client hoặc integrity of markets có thể biện minh việc đi ngược lợi ích employer nếu không vì lợi ích cá nhân; xét luật, kênh nội bộ và tính cần thiết. Không dùng lý do whistleblowing để lấy bí mật phục vụ cạnh tranh. [CFAI PDF pp. 161–171; Kaplan PDF pp. 180–181; SAPP PDF pp. 105–115] | Exam trap: Loyalty không yêu cầu che giấu gian lận; không phải blanket exemption."},{"front_en":"A departing employee copies the firm's confidential client database to a personal drive and solicits clients before the resignation takes effect.","back_vi":"Violation of IV(A) — Lấy tài sản/information và solicit trước khi nghỉ gây hại employer. | Trap: Không coi dữ liệu lưu trên thiết bị cá nhân là tài sản cá nhân."},{"front_en":"IV(B) Additional Compensation Arrangements — Written consent before acceptance","back_vi":"Không nhận thù lao/lợi ích cạnh tranh hoặc có thể hợp lý tạo xung đột với employer nếu chưa có written consent của tất cả parties involved. Direct/indirect, cash/noncash đều có thể thuộc phạm vi; email có thể là văn bản. Xét bản chất arrangement, không chỉ tên gọi gift. [CFAI PDF pp. 172–173; Kaplan PDF pp. 181–182; SAPP PDF pp. 116–119] | Exam trap: Thông báo một chiều hoặc verbal consent không đủ khi IV(B) áp dụng."},{"front_en":"IV(B) Additional Compensation Arrangements — Past gift versus prospective incentive","back_vi":"Quà client tự nguyện cho thành tích đã xảy ra thường xét I(B), disclosure employer; offer bonus phụ thuộc hiệu suất tương lai là arrangement cần consent trước. Third-party benefit có thể còn liên quan I(B), VI(A) hoặc VI(C). [CFAI PDF pp. 172–173; Kaplan PDF pp. 181–182; SAPP PDF pp. 116–119] | Exam trap: Không thay written consent bằng disclosure conflict; có thể có nhiều Standards."},{"front_en":"A client promises a manager a future bonus if the account outperforms. The manager accepts after obtaining only verbal permission from the employer.","back_vi":"Violation of IV(B) — Thỏa thuận tương lai có thể tạo conflict; written consent trước acceptance. | Trap: Không đợi payment mới phát sinh vấn đề."},{"front_en":"IV(C) Responsibilities of Supervisors — Reasonable supervision","back_vi":"Người có authority phải reasonable efforts để ngăn và phát hiện vi phạm của người dưới quyền, kể cả người không thuộc CFA Program. Delegation không xóa trách nhiệm giám sát; compliance system phù hợp hoạt động, luật và Standards. Nếu inadequate, báo management và đề xuất sửa; nếu không có hệ thống đầy đủ, từ chối supervisory responsibility bằng văn bản cho đến khi khắc phục. [CFAI PDF pp. 174–182; Kaplan PDF pp. 182–183; SAPP PDF pp. 120–127] | Exam trap: Không phải strict liability cho mọi hành vi cấp dưới, nhưng không đủ nếu chỉ giao việc."},{"front_en":"IV(C) Responsibilities of Supervisors — Investigate and restrict","back_vi":"Khi biết hoặc có nghi ngờ vi phạm, điều tra kịp thời, tăng giám sát hoặc hạn chế hoạt động trong lúc điều tra; không chỉ chấp nhận lời đảm bảo của người bị nghi hoặc chuyển trách nhiệm cho compliance rồi bỏ qua. [CFAI PDF pp. 174–182; Kaplan PDF pp. 182–183; SAPP PDF pp. 120–127] | Exam trap: Không đợi vi phạm được chứng minh mới có biện pháp hợp lý."},{"front_en":"A supervisor learns of suspicious allocation records but merely asks the trader to promise not to repeat the conduct and makes no investigation.","back_vi":"Violation of IV(C) — Reasonable effort gồm điều tra và biện pháp giám sát, không chỉ lời hứa. | Trap: Không nhầm delegation với discharge of duty."},{"front_en":"V(A) Diligence and Reasonable Basis — Research depth and independence","back_vi":"Phân tích, khuyến nghị và hành động đầu tư cần diligence, independence, thoroughness và reasonable adequate basis từ research/investigation thích hợp. Độ sâu phụ thuộc nhiệm vụ, loại sản phẩm, strategy, rủi ro, nguồn lực và vai trò. Xem macro, ngành, financials, peer comparisons, fee và limitations phù hợp. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136] | Exam trap: Không có công thức số trang bắt buộc; kết quả xấu không tự chứng minh thiếu diligence."},{"front_en":"V(A) Diligence and Reasonable Basis — Third-party research and models","back_vi":"Có thể dựa vào research bên ngoài nếu có reasonable basis tin chất lượng: kiểm tra assumptions, timeliness, rigor, objectivity, independence, nguồn dữ liệu và red flags. Quant models cần hiểu logic, assumptions, limitations, kiểm tra range of scenarios, sensitivity, chất lượng inputs; không nhất thiết tự viết mọi model. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136] | Exam trap: Không tin vendor mù quáng; không mặc định outsource bị cấm."},{"front_en":"V(A) Diligence and Reasonable Basis — Group research and external managers","back_vi":"Có thể đứng tên group recommendation nếu reasonable basis và quy trình đầy đủ dù cá nhân không đồng ý kết luận cuối; không được ủng hộ nếu biết nghiên cứu thiếu cơ sở. Due diligence chọn external adviser/manager, xem performance, style, controls, fee và review định kỳ. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136] | Exam trap: Không bắt mọi thành viên có cùng forecast; xét basis của group output."},{"front_en":"A portfolio manager recommends a complex product based solely on a salesperson's assurance, despite obvious gaps in the information and no research.","back_vi":"Violation of V(A) — Không đủ reasonable basis; kết quả sau không sửa thiếu diligence. | Trap: Không nhầm suitability với research basis."},{"front_en":"V(B) Communication with Clients and Prospective Clients — Nature and cost of services","back_vi":"Công bố nature of services và chi phí liên quan cho clients/prospects; tại khởi đầu và khi thay đổi, đủ chi tiết để hiểu cách chi phí phát sinh, gồm third-party service costs. Không nhất thiết biết trước dollar amount chính xác khi phụ thuộc AUM hoặc biến số khác. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143] | Exam trap: Không chỉ nói management fee nếu còn chi phí đáng kể khác; không đòi exact dollar khi chưa biết."},{"front_en":"V(B) Communication with Clients and Prospective Clients — Process changes, limitations and risks","back_vi":"Mô tả basic format và general principles dùng phân tích, lựa chọn chứng khoán, xây danh mục; promptly disclose thay đổi material. Công bố significant limitations và risks, kể cả model assumptions, leverage, liquidity, structured payoff và hạn chế dữ liệu nếu trọng yếu. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143] | Exam trap: Không bắt tiết lộ mọi bí mật thuật toán; không được che material risk."},{"front_en":"V(B) Communication with Clients and Prospective Clients — Facts, opinions and all media","back_vi":"Dùng reasonable judgment chọn factors quan trọng; phân biệt fact với opinion/forecast/model output; áp dụng với email, chat, oral, social media, report. Giao tiếp phù hợp sophistication và giải thích khả năng lãi/lỗ, tổng return khi liên quan. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143] | Exam trap: Dự báo từ model không thành fact chỉ vì có số chính xác."},{"front_en":"An advisor describes advisory fees but knowingly omits significant third-party platform costs from communications to prospective clients.","back_vi":"Violation of V(B) — Chi phí dịch vụ cần công bố cho prospects, bao gồm liên quan bên thứ ba. | Trap: Không giới hạn disclosure vào client đã ký hợp đồng."},{"front_en":"V(C) Record Retention — Supporting records and media","back_vi":"Xây dựng và duy trì records thích hợp hỗ trợ analysis, recommendations, actions và investment communications; bao gồm dữ liệu, models, assumptions, notes, emails, messages/social media khi liên quan. Lưu phù hợp quy định, chính sách và khả năng truy xuất. [CFAI PDF pp. 207–209; Kaplan PDF pp. 186; SAPP PDF pp. 144–148] | Exam trap: Không chỉ lưu final report; không bỏ qua giao tiếp điện tử."},{"front_en":"V(C) Record Retention — Ownership and retention periods","back_vi":"Records làm trong employment thường thuộc firm, không mang đi khi rời trừ có consent phù hợp. Nếu không có luật hoặc firm policy quy định, CFAI khuyến nghị giữ ít nhất 7 năm; phải tuân luật và policy áp dụng, không coi 7 năm là bắt buộc phổ quát. Tại firm mới, tái tạo basis từ nguồn hợp lệ nếu cần. [CFAI PDF pp. 207–209; Kaplan PDF pp. 186; SAPP PDF pp. 144–148] | Exam trap: Không lấy proprietary files để chứng minh diligence cá nhân; 7 năm là recommendation trong điều kiện nêu."},{"front_en":"An analyst deletes all model inputs and research notes while retaining only the final investment recommendation, making the basis impossible to substantiate.","back_vi":"Violation of V(C) — Records phải hỗ trợ analysis/actions; final report có thể không đủ. | Trap: Không nhầm publication với recordkeeping."},{"front_en":"VI(A) Avoid or Disclose Conflicts — Avoid or disclose","back_vi":"Tránh xung đột có thể làm lệch independence/objectivity hoặc ảnh hưởng duties khi hợp lý; nếu không tránh được, công bố đầy đủ và công bằng các matters hợp lý có thể impair duties, nổi bật, dễ hiểu, tới bên liên quan và cập nhật khi thay đổi. Disclosure giúp đánh giá chứ không chữa mọi hành vi bị cấm. [CFAI PDF pp. 210–214; Kaplan PDF pp. 187–188; SAPP PDF pp. 149–157] | Exam trap: Không chỉ disclosure chung chung ở cuối tài liệu; không thay client first hoặc I(B)."},{"front_en":"VI(A) Avoid or Disclose Conflicts — Employer and client conflicts","back_vi":"Xung đột gồm beneficial holdings, board/directorship, family/business ties, issuer investment banking, compensation/incentive, market making và các hoạt động cạnh tranh. Công bố cho employer để quản lý duties, cho clients/prospects khi ảnh hưởng dịch vụ/khuyến nghị; cân nhắc recusal, thay analyst hoặc loại xung đột. [CFAI PDF pp. 210–214; Kaplan PDF pp. 187–188; SAPP PDF pp. 149–157] | Exam trap: Không chỉ xét conflict đã làm thay đổi quyết định; reasonably expected conflicts cũng quan trọng."},{"front_en":"An analyst owns a significant position in a covered issuer and does not disclose it to clients or the employer, although the report is carefully researched.","back_vi":"Violation of VI(A) — Reasonably expected conflict từ holding; adequate research không thay disclosure. | Trap: Một Standard đạt không miễn Standard khác."},{"front_en":"VI(B) Priority of Transactions — Client and employer precedence","back_vi":"Giao dịch cho client và employer ưu tiên hơn giao dịch nơi member/candidate là beneficial owner. Không front-run khuyến nghị hoặc client trades, không tận dụng ưu thế từ việc biết lệnh trước. Personal trade không bị cấm tuyệt đối nếu client không bị bất lợi và các quy định được đáp ứng. [CFAI PDF pp. 215–220; Kaplan PDF pp. 188–189; SAPP PDF pp. 158–164] | Exam trap: Không nhầm personal account với mọi family account; xét beneficial interest."},{"front_en":"VI(B) Priority of Transactions — Family accounts and personal trades","back_vi":"Family account quản lý như client bình thường nếu là client thật, đối xử công bằng; nếu member có beneficial ownership thì áp dụng priority. Personal trades sau khi client/employer có cơ hội hợp lý, theo policy, không dùng MNPI hoặc unfair allocations. [CFAI PDF pp. 215–220; Kaplan PDF pp. 188–189; SAPP PDF pp. 158–164] | Exam trap: Không bắt loại mọi tài khoản gia đình khỏi phân bổ; không tự đặt thời gian blackout chung cho mọi firm."},{"front_en":"An advisor purchases shares in a personal account immediately before executing a known large client buy order in the same security to benefit from expected price impact.","back_vi":"Violation of VI(B) — Front-running, beneficial owner ưu tiên trước client. | Trap: Không cần chứng minh client lỗ thực tế."},{"front_en":"VI(C) Referral Fees — Scope, timing and nature","back_vi":"Công bố cho employer, clients và prospects khi phù hợp mọi compensation/benefit nhận hoặc trả cho recommendation sản phẩm/dịch vụ, trước formal agreement. Nêu nature (flat, percentage, one-time, continuing, performance-based, cash/noncash, research/soft dollars) và estimated dollar value; giúp đánh giá bias và full costs. [CFAI PDF pp. 221–223; Kaplan PDF pp. 189; SAPP PDF pp. 165–168] | Exam trap: Không chỉ khoản nhận bằng tiền; không chỉ disclose referral fee sau hợp đồng."},{"front_en":"An advisor receives free research for referring clients to an outside provider and discloses nothing because no cash changes hands.","back_vi":"Violation of VI(C) — Noncash consideration cũng là benefit phải disclose. | Trap: Không giới hạn referral fees vào tiền mặt."},{"front_en":"VII(A) Conduct as Participants in CFA Institute Programs — Exam integrity and confidentiality","back_vi":"Không làm suy yếu uy tín/integrity CFA Institute, designation hoặc integrity, validity, security CFA programs. Không chia sẻ/solicit actual exam questions, topics tested/not tested hoặc thông tin scoring/confidential development; tuân exam rules, không lấy materials hoặc gian lận, kể cả khi thi không thành công. [CFAI PDF pp. 224–229; Kaplan PDF pp. 189–190; SAPP PDF pp. 169–174] | Exam trap: Không chỉ việc chia sẻ nguyên văn câu hỏi mới vi phạm; topics covered/not covered cũng confidential."},{"front_en":"VII(A) Conduct as Participants in CFA Institute Programs — Opinions and volunteer duties","back_vi":"Có thể bày tỏ ý kiến về CFA Institute/program/policy hoặc độ khó chung nếu không tiết lộ nội dung cụ thể. Volunteers, graders và người tham gia các chương trình khác phải giữ confidential process/materials; không lợi dụng vai trò để trục lợi hay cung cấp thông tin. [CFAI PDF pp. 224–229; Kaplan PDF pp. 189–190; SAPP PDF pp. 169–174] | Exam trap: Không cấm phê bình thiện chí; không nhầm opinion chung với topic disclosure."},{"front_en":"After an exam, a candidate posts which curriculum topic was not tested, without reproducing any question.","back_vi":"Violation of VII(A) — Content-specific topic coverage là confidential; không cần nguyên văn. | Trap: Không coi sau exam là hết nghĩa vụ."},{"front_en":"VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program — Designation and membership","back_vi":"Không misrepresent/exaggerate ý nghĩa CFA membership, designation hoặc candidacy. Chỉ dùng CFA designation nếu có quyền sử dụng, duy trì membership và các yêu cầu liên quan; nếu không còn quyền, có thể nêu sự kiện lịch sử chính xác nhưng không dùng designation như hiện tại. Dùng CFA như dấu hiệu professional designation phù hợp, không biến thành danh từ số nhiều hay tên firm. [CFAI PDF pp. 230–235; Kaplan PDF pp. 190–191; SAPP PDF pp. 175–183] | Exam trap: Không dùng CFA như chứng nhận guaranteed returns hoặc superiority."},{"front_en":"VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program — Candidate status and factual statements","back_vi":"Nêu chính xác active candidacy khi đáp ứng định nghĩa, có thể nói đã pass một level nếu đúng. Không có partial designation, không dùng 'CFA Level II' sau tên, 'CFA expected' hay dự đoán thời điểm nhận charter. Có thể nói pass ba levels liên tiếp như sự kiện thật nhưng không hàm ý năng lực vượt trội. [CFAI PDF pp. 230–235; Kaplan PDF pp. 190–191; SAPP PDF pp. 175–183] | Exam trap: Passing exams không đồng nghĩa charter; candidate status không tồn tại vô hạn."},{"front_en":"A Level II candidate lists 'CFA, expected next year' after her name on a business card.","back_vi":"Violation of VII(B) — Không có partial/expected designation; ghi candidacy chính xác thay vì suffix sai. | Trap: Không nhầm enrollment với charter."},{"front_en":"I — Professionalism — decision framework?","back_vi":"Applicable requirements → objective judgment → accurate representation → integrity → competence · Tách I(A) tuân luật/dissociate, I(B) khách quan, I(C) misrepresentation, I(D) misconduct, I(E) competence. · Một hành vi có thể vi phạm nhiều chuẩn; xét từng duty."},{"front_en":"II — Market integrity — decision framework?","back_vi":"Material? → Nonpublic? → Act/cause others?; Intent to mislead? · II(A) xét tính chất thông tin và sử dụng; II(B) xét mục đích làm méo thị trường. · Không dùng lợi nhuận hoặc price movement làm tiêu chí duy nhất."},{"front_en":"III — Duties to clients — decision framework?","back_vi":"Identify client → client first → fair allocation → suitability → accurate presentation → confidentiality · Tách beneficiary, fair vs equal, advisory vs mandate, disclosure và ngoại lệ bảo mật. · Luôn xét vai trò và facts."},{"front_en":"IV — Duties to employers — decision framework?","back_vi":"Employment duty → competing pay → written consent → reasonable supervision · IV(A) loyalty; IV(B) additional compensation; IV(C) supervisory authority. · Client interests ưu tiên; consent/disclosure khác nhau."},{"front_en":"V — Analysis and communication — decision framework?","back_vi":"Adequate research basis → disclose services/cost/process/risks → retain support · V(A) basis; V(B) communication; V(C) records. · Không dùng disclosure thay due diligence."},{"front_en":"VI — Conflicts — decision framework?","back_vi":"Avoid or disclose → client/employer trading priority → referral benefit disclosure · VI(A), VI(B), VI(C) bổ sung cho nhau. · Disclosure không chữa front-running hay inducement."},{"front_en":"VII — CFA responsibilities — decision framework?","back_vi":"Protect confidential program information → accurate status/designation references · VII(A) conduct; VII(B) references. · General opinions allowed; confidential exam content not allowed."},{"front_en":"I(A) — Applicable law, uncertainty and dissociation","back_en":"A reasonable good-faith understanding of applicable law is required, not expertise in every possible jurisdiction. Seek qualified guidance when uncertain; apply the stricter applicable requirement. A report to a supervisor does not permit continued knowing assistance. If internal efforts fail, remove yourself from the activity; external reporting is required when applicable law demands it, not automatically by the Standard.","back_vi":"Cần hiểu luật áp dụng một cách hợp lý và thiện chí, không phải thành chuyên gia mọi hệ thống luật. Khi chưa rõ, hỏi bộ phận có chuyên môn; tuân thủ yêu cầu áp dụng nghiêm hơn. Báo cấp trên không cho phép tiếp tục cố ý hỗ trợ. Nếu xử lý nội bộ thất bại, tách khỏi hoạt động; báo ngoài khi luật áp dụng yêu cầu, không mặc nhiên do Standard.","source_anchor":"CFAI Ethics 2026 physical PDF pp 67–76 (I(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"I(B) — Research incentives and legitimate access","back_en":"A fixed fee for issuer-sponsored research can be compatible with objectivity if the research is independent, thorough and the compensation arrangement is disclosed. Compensation contingent on a favorable result is incompatible with independent judgment. For travel, commercial transport at one's own expense is preferred; modest issuer arrangements may be acceptable when commercial transport is unavailable and the visit is necessary, with reasonable judgment.","back_vi":"Phí cố định cho nghiên cứu do tổ chức phát hành tài trợ có thể phù hợp nếu nghiên cứu độc lập, đầy đủ và công bố thỏa thuận phí. Phí phụ thuộc kết luận thuận lợi làm suy yếu tính độc lập. Khi đi khảo sát, ưu tiên phương tiện thương mại tự chi trả; nếu không có phương tiện phù hợp, thu xếp khiêm tốn của issuer có thể chấp nhận nếu chuyến đi cần thiết và được cân nhắc hợp lý.","source_anchor":"CFAI Ethics 2026 physical PDF pp 76–90 (I(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"I(C) — Error correction, attribution and valuation integrity","back_en":"An inadvertent mistake is not automatically knowing misrepresentation, but after discovery the member should stop disseminating erroneous material and correct recipients' understanding. Paraphrases and borrowed analyses require attribution; commonplace facts do not require tracing every original source. Do not switch valuation sources merely to obtain a favorable mark.","back_vi":"Sai sót vô ý không mặc nhiên là cố ý trình bày sai, nhưng khi phát hiện phải ngừng phát tán và đính chính với người nhận. Diễn giải lại và phân tích mượn cần ghi nguồn; dữ kiện phổ thông không cần truy nguyên mọi nguồn. Không đổi nguồn định giá chỉ để lấy mức giá có lợi.","source_anchor":"CFAI Ethics 2026 physical PDF pp 90–101 (I(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"I(D) — Misconduct and professional relevance","back_en":"Dishonesty, fraud and deceit in professional conduct are prohibited. Other conduct is assessed by whether it reflects adversely on professional reputation, integrity or competence; private financial hardship and civil disobedience do not automatically satisfy that test. A conviction is not a prerequisite to a professional-integrity finding.","back_vi":"Cấm hành vi nghề nghiệp gian dối, gian lận, lừa gạt. Hành vi khác được xét theo ảnh hưởng xấu đến uy tín, liêm chính hoặc năng lực nghề; khó khăn tài chính cá nhân và bất tuân dân sự không tự động thỏa điều kiện đó. Không cần có bản án mới xác định vi phạm liêm chính.","source_anchor":"CFAI Ethics 2026 physical PDF pp 101–104 (I(D)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"I(E) — Role-specific competence and transitions","back_en":"Competence is the knowledge, skills and abilities needed for the actual responsibilities performed. When moving to a new role, identify gaps before acting independently and use training or qualified assistance. A poor outcome alone does not establish incompetence; there is no single mandatory continuing-education schedule under I(E).","back_vi":"Competence là kiến thức, kỹ năng và khả năng cần cho trách nhiệm thực tế. Khi đổi vai trò, xác định thiếu hụt trước khi làm độc lập và dùng đào tạo hoặc hỗ trợ có chuyên môn. Kết quả xấu riêng lẻ không chứng minh thiếu năng lực; I(E) không ấn định lịch đào tạo liên tục chung bắt buộc.","source_anchor":"CFAI Ethics 2026 physical PDF pp 104–109 (I(E)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"II(A) — Materiality, dissemination and mosaic analysis","back_en":"Assess significance to a reasonable investor and the reliability/specificity of the information. Information shared privately with a small audience is not necessarily public. Wait for effective public dissemination before acting or causing others to act on material nonpublic information. Public information plus nonmaterial nonpublic pieces may support a material inference under mosaic theory; a material nonpublic input is not cured by adding public data.","back_vi":"Xét ý nghĩa với nhà đầu tư hợp lý và độ tin cậy/cụ thể của thông tin. Chia sẻ riêng cho nhóm nhỏ chưa chắc là công khai. Chờ phổ biến công khai hiệu quả trước khi giao dịch hoặc khiến người khác giao dịch trên MNPI. Thông tin công khai cộng mảnh riêng lẻ không trọng yếu có thể tạo kết luận trọng yếu theo mosaic; thêm dữ liệu công khai không hợp thức hóa đầu vào MNPI.","source_anchor":"CFAI Ethics 2026 physical PDF pp 109–120 (II(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"II(B) — Intent versus ordinary trading effects","back_en":"Market manipulation requires deceptive intent to distort prices or artificially inflate volume. Genuine liquidity provision, hedging or large transactions can move prices without necessarily violating II(B). Disseminating a knowingly false story to induce purchases is information-based manipulation; wash trades creating false activity are transaction-based.","back_vi":"Market manipulation đòi hỏi ý định đánh lừa qua bóp méo giá hoặc tăng khối lượng giả tạo. Cung cấp thanh khoản, phòng hộ hoặc giao dịch lớn thật có thể ảnh hưởng giá nhưng không mặc nhiên vi phạm. Lan truyền tin biết là sai để kích mua là manipulation dựa thông tin; wash trade tạo hoạt động giả là dựa giao dịch.","source_anchor":"CFAI Ethics 2026 physical PDF pp 120–124 (II(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"III(A) — Beneficiaries, directed brokerage and soft commissions","back_en":"Identify the actual client, including plan beneficiaries rather than merely the hiring party. Brokerage paid from client assets should benefit clients, with attention to best execution and the nature of research/service benefits. A client can direct brokerage after receiving appropriate information about possible disadvantages; the manager must not silently redirect commissions for personal or firm-only benefits.","back_vi":"Xác định client thực, gồm người thụ hưởng quỹ thay vì chỉ bên thuê. Hoa hồng từ tài sản khách phải phục vụ khách, xét best execution và bản chất lợi ích nghiên cứu/dịch vụ. Khách có thể chỉ định broker sau khi được thông tin thích hợp về bất lợi; manager không âm thầm dùng commission cho lợi ích cá nhân hoặc riêng firm.","source_anchor":"CFAI Ethics 2026 physical PDF pp 125–135 (III(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"III(B) — Fair access versus identical service","back_en":"Fair dealing is equitable, not necessarily identical service. Disclosed service tiers can differ without disadvantaging other clients unfairly. Communicate changes to recommendations fairly to affected clients. Allocate scarce securities under objective, pre-established procedures, taking suitability and legitimate order sizes into account rather than rewarding favored clients.","back_vi":"Fair dealing là công bằng, không bắt buộc dịch vụ giống hệt. Tier được công bố có thể khác nếu không làm khách khác bất lợi không công bằng. Truyền đạt thay đổi khuyến nghị công bằng cho khách bị ảnh hưởng. Phân bổ chứng khoán khan hiếm theo tiêu chí khách quan định trước, xét suitability và khối lượng hợp lệ, không thưởng khách ưu ái.","source_anchor":"CFAI Ethics 2026 physical PDF pp 135–144 (III(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"III(C) — Portfolio context and unsolicited orders","back_en":"In advisory relationships, assess client financial circumstances, objectives and constraints, and investment fit within the total portfolio. A mandate manager follows the stated mandate rather than assessing each fund investor individually. For an unsolicited unsuitable request, discuss the mismatch; document and assess material impact, revisit the IPS if necessary, and follow firm procedures rather than automatically executing or refusing every request.","back_vi":"Trong quan hệ tư vấn, đánh giá tài chính, mục tiêu, hạn chế và sự phù hợp trong toàn danh mục. Manager theo mandate tuân thủ mandate thay vì xét từng người mua quỹ. Với lệnh khách tự yêu cầu nhưng không phù hợp, giải thích, ghi nhận, xét tác động trọng yếu, rà IPS nếu cần và theo quy trình firm, không mặc nhiên khớp hay từ chối mọi lệnh.","source_anchor":"CFAI Ethics 2026 physical PDF pp 144–152 (III(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"III(D) — Performance comparability and completeness","back_en":"Fair, accurate and complete performance reporting is required even without GIPS compliance. Clearly distinguish actual and simulated returns, predecessor performance, gross versus net results and relevant periods. Excluding terminated or poorly performing accounts solely to improve a reported track record is misleading.","back_vi":"Báo cáo hiệu suất công bằng, chính xác, đầy đủ là bắt buộc dù không theo GIPS. Phân biệt return thực với mô phỏng, kết quả nơi làm trước, gross/net và kỳ liên quan. Loại tài khoản chấm dứt hoặc kết quả kém chỉ để làm đẹp lịch sử là gây hiểu nhầm.","source_anchor":"CFAI Ethics 2026 physical PDF pp 152–157 (III(D)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"III(E) — Confidentiality exceptions and controlled disclosure","back_en":"Confidentiality covers current, former and prospective clients. Exceptions involve client illegal activity, legally required disclosure or client permission. If law restricts disclosure, seek legal guidance and comply with the applicable law. Cooperation with the Professional Conduct Program is encouraged within applicable legal limits; it is not permission to publicly release private client data.","back_vi":"Bảo mật áp dụng khách hiện tại, cũ, tiềm năng. Ngoại lệ: thông tin về hoạt động trái luật của khách, luật yêu cầu công bố hoặc khách cho phép. Nếu luật hạn chế, xin tư vấn và tuân luật áp dụng. Hợp tác PCP được khuyến khích trong giới hạn luật, không cho phép công khai dữ liệu khách tùy ý.","source_anchor":"CFAI Ethics 2026 physical PDF pp 157–162 (III(E)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"IV(A) — Preparation to leave and employer property","back_en":"Preparing a future business on personal time may be permissible if duties are not impaired; active competition or solicitation for the new business before leaving may violate loyalty. After departure, use general skills and experience, but do not take employer records or confidential client data without authorization. Whistleblowing for protecting clients or market integrity may justify actions that would otherwise be disloyal, not actions motivated merely by personal advantage.","back_vi":"Chuẩn bị doanh nghiệp tương lai ngoài giờ có thể phù hợp nếu không ảnh hưởng nhiệm vụ; cạnh tranh hoặc lôi kéo khách trước khi nghỉ có thể vi phạm loyalty. Sau khi nghỉ, dùng kỹ năng và kinh nghiệm chung, nhưng không lấy hồ sơ employer hoặc dữ liệu khách mật nếu không phép. Whistleblowing để bảo vệ khách/thị trường có thể biện minh hành động vốn trái loyalty, không phải hành động vì lợi riêng.","source_anchor":"CFAI Ethics 2026 physical PDF pp 162–172 (IV(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"IV(B) — Prospective additional compensation versus past gifts","back_en":"Obtain written consent from all parties involved before accepting outside compensation or benefits that compete with or could reasonably create a conflict with the employer's interest. A retrospective gift from a satisfied client is not automatically a prospective compensation agreement; apply independence/objectivity and employer gift rules. An offer tied to future returns raises different incentives.","back_vi":"Có chấp thuận bằng văn bản của mọi bên liên quan trước khi nhận bù đắp/lợi ích bên ngoài cạnh tranh hoặc có thể hợp lý tạo xung đột với employer. Quà cảm ơn cho kết quả quá khứ không tự là thỏa thuận thù lao tương lai; áp dụng independence/objectivity và quy định quà. Đề nghị gắn với return tương lai tạo động cơ khác.","source_anchor":"CFAI Ethics 2026 physical PDF pp 172–175 (IV(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"IV(C) — Reasonable supervision, delegation and response","back_en":"Supervisors must make reasonable efforts to ensure compliance by those under their authority, including nonmembers. Delegating tasks does not remove supervisory responsibility. If an adequate system cannot be established, decline supervisory responsibility in writing until adequate procedures exist. Upon learning of possible misconduct, investigate and restrict activity appropriately rather than merely accepting assurances.","back_vi":"Supervisor phải nỗ lực hợp lý bảo đảm tuân thủ của người dưới quyền, kể cả không phải member. Giao việc không xóa trách nhiệm. Nếu không thể có hệ thống đủ, từ chối trách nhiệm bằng văn bản đến khi có quy trình phù hợp. Khi biết dấu hiệu sai phạm, điều tra và hạn chế hoạt động thích hợp, không chỉ nhận cam kết.","source_anchor":"CFAI Ethics 2026 physical PDF pp 174–183 (IV(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"V(A) — Research quality, external models and group conclusions","back_en":"Diligence is proportional to role, investment complexity and circumstances. Evaluate external research for assumptions, rigor, timeliness and independence; test models and understand limitations instead of treating software outputs as authority. A member may support a group report with a reasonable basis even if disagreeing with its conclusion, provided the process and basis are sound.","back_vi":"Diligence tương xứng vai trò, độ phức tạp và hoàn cảnh. Đánh giá giả định, độ chặt chẽ, thời điểm, độc lập của nghiên cứu ngoài; kiểm tra mô hình, hiểu giới hạn thay vì coi output phần mềm là chân lý. Có thể tham gia báo cáo nhóm có cơ sở hợp lý dù khác kết luận cá nhân nếu quy trình và căn cứ vững.","source_anchor":"CFAI Ethics 2026 physical PDF pp 183–195 (V(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"V(B) — Service costs, process changes, risks and opinions","back_en":"Explain the nature of investment services and relevant costs to current and prospective clients. Disclose the basic investment process and promptly communicate material changes; identify significant risks and limitations. Distinguish verifiable facts from forecasts and judgment, including in short-form communication. The amount of detail depends on the service and audience, but material omissions are not justified by format.","back_vi":"Giải thích bản chất dịch vụ và chi phí liên quan cho khách hiện tại/tiềm năng. Công bố quy trình đầu tư cơ bản và kịp thời thông báo thay đổi trọng yếu; nêu rủi ro/giới hạn đáng kể. Phân biệt facts với dự báo/phán đoán kể cả giao tiếp ngắn. Chi tiết tùy dịch vụ và đối tượng nhưng hình thức không biện minh bỏ sót trọng yếu.","source_anchor":"CFAI Ethics 2026 physical PDF pp 195–207 (V(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"V(C) — Records, digital channels and ownership","back_en":"Keep records supporting analyses, recommendations, actions and investment-related communications. Electronic or ephemeral formats are not exempt. Retention requirements from law or firm policies apply; absent applicable requirements, CFA Institute recommends at least seven years. Employer records generally belong to the firm; recreate research from public sources if needed rather than taking records without permission.","back_vi":"Lưu hồ sơ hỗ trợ phân tích, khuyến nghị, hành động và giao tiếp đầu tư. Định dạng điện tử/tạm thời không được miễn. Áp dụng yêu cầu lưu của luật/firm; nếu không có yêu cầu áp dụng, CFAI khuyến nghị ít nhất 7 năm. Hồ sơ employer thường thuộc firm; khi cần hãy tái lập từ nguồn công khai thay vì lấy không phép.","source_anchor":"CFAI Ethics 2026 physical PDF pp 207–210 (V(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"VI(A) — Avoidance first and effective disclosure","back_en":"Avoid conflicts when reasonably practicable; otherwise provide full, fair, prominent and understandable disclosure to the employer, clients and prospects as applicable. Update disclosures when circumstances change. Stock ownership, board positions and compensation can compromise judgment even before a biased recommendation is proven. Disclosure does not authorize conduct prohibited by another standard.","back_vi":"Tránh xung đột khi có thể hợp lý; nếu không, công bố đầy đủ, công bằng, nổi bật, dễ hiểu cho employer, khách và khách tiềm năng phù hợp. Cập nhật khi hoàn cảnh đổi. Sở hữu cổ phiếu, vị trí board và thù lao có thể ảnh hưởng phán đoán dù chưa chứng minh khuyến nghị thiên lệch. Công bố không cho phép hành vi chuẩn khác cấm.","source_anchor":"CFAI Ethics 2026 physical PDF pp 210–215 (VI(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"VI(B) — Beneficial ownership and family-client accounts","back_en":"Client transactions take precedence over employer and personal transactions. Family accounts that are genuine client accounts should be treated fairly, not automatically favored or penalized; where the member has beneficial ownership, applicable personal trading restrictions also matter. Co-investment itself is not prohibited if client priority and other duties are respected.","back_vi":"Giao dịch khách ưu tiên trước employer và cá nhân. Tài khoản gia đình thực sự là client phải được đối xử công bằng, không tự ưu ái hay phạt; nếu member có beneficial ownership, cần xét hạn chế giao dịch cá nhân áp dụng. Cùng đầu tư không tự bị cấm nếu bảo đảm ưu tiên khách và nghĩa vụ khác.","source_anchor":"CFAI Ethics 2026 physical PDF pp 215–221 (VI(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"VI(C) — Referral benefits in cash or kind","back_en":"Disclose compensation, consideration or benefits received from or paid to others for referrals to the employer, clients and prospective clients as appropriate. Explain nature and estimated value when relevant before a prospective client enters the relevant service agreement. Noncash research, services or discounts can also create referral incentives.","back_vi":"Công bố thù lao, khoản đối ứng hoặc lợi ích nhận/trả cho giới thiệu khách cho employer, khách và khách tiềm năng phù hợp. Giải thích bản chất và giá trị ước tính khi liên quan trước khi khách tiềm năng ký thỏa thuận dịch vụ. Nghiên cứu, dịch vụ, giảm giá phi tiền mặt cũng tạo động cơ giới thiệu.","source_anchor":"CFAI Ethics 2026 physical PDF pp 221–224 (VI(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"VII(A) — Program integrity and permitted opinions","back_en":"Do not disclose or solicit confidential exam content, confidential grading information or other protected program material. Expressing an opinion about CFA Institute or one's exam experience can be permissible if it does not reveal protected information or undermine program integrity. Compliance with candidate rules extends beyond the exam answers themselves.","back_vi":"Không công bố hoặc xin nội dung thi mật, thông tin chấm thi mật hoặc tài liệu chương trình được bảo vệ. Nêu ý kiến về CFA Institute hoặc trải nghiệm thi có thể phù hợp nếu không tiết lộ thông tin mật hay làm suy yếu tính toàn vẹn chương trình. Tuân thủ quy định ứng viên không chỉ giới hạn đáp án thi.","source_anchor":"CFAI Ethics 2026 physical PDF pp 224–230 (VII(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"VII(B) — Designation, candidacy and factual claims","back_en":"Use the designation only while entitled to it; membership obligations matter. The CFA designation is not a partial credential or guarantee of superior returns. Factual statements about exams passed and dates are permitted when accurate; candidate status depends on the actual registration/status requirements, not an intention to enroll.","back_vi":"Chỉ dùng designation khi có quyền; nghĩa vụ membership có ý nghĩa. CFA không phải chứng chỉ từng phần hay bảo đảm return cao hơn. Có thể nêu facts về kỳ thi đã qua và ngày nếu đúng; candidate status tùy đăng ký/tình trạng thực, không chỉ dự định đăng ký.","source_anchor":"CFAI Ethics 2026 physical PDF pp 230–235 (VII(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"}]},{"id":"CFA26-10-03-LOS02","letter":"b","title_en":"Prevent Violations: Recommended Practices and Procedures","outcome_en":"recommend practices and procedures designed to prevent violations of the Code of Ethics and Standards of Professional Conduct","overview_vi":"Học recommended procedures theo từng sub-standard; không biến best practices thành mandatory rules. Với II(B), VII(A), khung kiểm soát thực hành được ghi rõ là biện pháp bổ trợ dựa trên guidance. V7.4: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 67 (LOS); pp. 67–235 (Guidance, procedures and applications); pp. 236–254 practice/solutions range (not reproduced)"},{"id":"Kaplan SchweserNotes 2026 — Book 4 Reading 91","pages":"Physical PDF pp. 167–194"},{"id":"SAPP CFA Level I 2026 — Ethics slides Module 3","pages":"Physical PDF pp. 23–185; topic cases pp. 186–199 (not reproduced)"}],"sections":[{"heading":"I(A) Knowledge of the Law — Keep the legal inventory current","body":"Theo dõi thay đổi luật, lưu bản cập nhật, định kỳ rà soát chính sách; có kênh báo cáo vi phạm và hướng dẫn sản phẩm xuyên biên giới. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29]","trap":"Recommended procedures; nghĩa vụ tuân thủ và dissociate là bắt buộc."},{"heading":"I(A) Knowledge of the Law — Escalate and document","body":"Ghi nhận sự việc, trao đổi với supervisor/compliance, xin tư vấn pháp lý khi cần; nếu không sửa được, ngừng liên quan đến hành vi sai phạm. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29]","trap":"Documentation là recommended; không trì hoãn dissociation."},{"heading":"I(B) Independence and Objectivity — Protect research and gift policy","body":"Tách research khỏi áp lực investment banking, restricted list nếu không thể công bố nhận định độc lập, giới hạn quà bên ngoài mức tượng trưng, có quy trình review và báo cáo. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41]","trap":"Recommended; độc lập và không nhận inducement là mandatory."},{"heading":"I(B) Independence and Objectivity — Travel, IPO and placement controls","body":"Tự trả chi phí đi lại khi thực tế cho phép; yêu cầu preclearance, hạn chế IPO/private placements, bổ nhiệm compliance officer có thẩm quyền. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41]","trap":"Recommended, không phải lệnh cấm tuyệt đối mọi chuyến đi."},{"heading":"I(C) Misrepresentation — Verify marketing and credentials","body":"Lập mô tả bằng văn bản về dịch vụ, năng lực và kinh nghiệm; kiểm tra định kỳ tài liệu, website, dữ liệu vendor và claims của bên thứ ba; sửa sai sớm. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49]","trap":"Recommended; cấm knowingly misrepresent là mandatory."},{"heading":"I(C) Misrepresentation — Attribution trail","body":"Lưu báo cáo, ghi nguồn của bản tóm tắt, trích dẫn mô hình/biểu đồ và kiểm tra quyền sử dụng; lưu các bản sửa. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49]","trap":"Recommended; không đạo văn là mandatory."},{"heading":"I(D) Misconduct — Conduct and hiring controls","body":"Khuyến nghị code of ethics, thông báo hành vi bị cấm và chế tài, kiểm tra references của ứng viên. [CFAI PDF pp. 101–103; Kaplan PDF pp. 172; SAPP PDF pp. 50–52]","trap":"Recommended; mục tiêu ngăn hành vi thiếu trung thực."},{"heading":"I(E) Competence — Role gap assessment","body":"Đánh giá khoảng trống kỹ năng khi chuyển vị trí; lập kế hoạch tự học, đào tạo, mentoring, tham vấn chuyên gia; cập nhật kiến thức khi sản phẩm/quy định thay đổi. [CFAI PDF pp. 104–107; Kaplan PDF pp. 172; SAPP PDF pp. 53–54]","trap":"Recommended methods; duy trì năng lực là mandatory."},{"heading":"II(A) Material Nonpublic Information — Information barriers","body":"Thiết lập firewall giữa bộ phận, restricted/watch lists, kiểm soát luồng thông tin, review giao dịch cá nhân và proprietary; phân quyền, kiểm tra tài liệu và đào tạo. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61]","trap":"Recommended; không act/cause others to act là mandatory."},{"heading":"II(A) Material Nonpublic Information — Public dissemination and mosaic records","body":"Khuyến khích public disclosure; theo dõi thời điểm phổ biến, lưu nguồn và lý do của phân tích mosaic; compliance xem xét khi vô tình nhận MNPI. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61]","trap":"Recommended; không giao dịch trước khi thông tin public."},{"heading":"II(B) Market Manipulation — Trade and communication surveillance","body":"Kiểm soát giao dịch đối ứng, bất thường cuối phiên, tin đồn và xung đột; lưu lý do kinh tế, review truyền thông và escalation. Đây là biện pháp thiết kế bổ trợ, không phải danh mục quy trình bắt buộc riêng của Standard. [CFAI PDF pp. 120–125; Kaplan PDF pp. 174–175; SAPP PDF pp. 62–66]","trap":"CFAI guidance: prohibitions và intent; control thực hành được suy ra từ mục tiêu phòng ngừa."},{"heading":"III(A) Loyalty, Prudence, and Care — Client asset safeguards","body":"Xác định client, mục tiêu, giới hạn, tài sản custody; phân tách tài sản và cung cấp statement định kỳ (quarterly được khuyến nghị khi kiểm soát tài sản), có chính sách vote proxy và rà soát brokerage. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77]","trap":"Recommended; nghĩa vụ client first là mandatory."},{"heading":"III(A) Loyalty, Prudence, and Care — Best execution review","body":"Đánh giá giá/chi phí/khả năng thực hiện, chất lượng dịch vụ, cách sử dụng brokerage; minh bạch directed brokerage và giới hạn execution. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77]","trap":"Recommended process."},{"heading":"III(B) Fair Dealing — Dissemination protocol","body":"Giới hạn người biết trước, rút ngắn thời gian từ quyết định đến phổ biến, hướng dẫn giao tiếp, phát hành đồng thời khi khả thi, lưu thời điểm, thông báo service tiers. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85]","trap":"Recommended; fair treatment là mandatory."},{"heading":"III(B) Fair Dealing — Trade allocation policy","body":"Ghi thời điểm và lệnh, preallocate hoặc theo quy trình công bằng, average price khi phù hợp, review accounts, công bố policy và mức dịch vụ. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85]","trap":"Recommended; pro rata không phải quy tắc duy nhất."},{"heading":"III(C) Suitability — Written IPS and periodic review","body":"Lập IPS nêu risk/return, constraints, benchmark, trách nhiệm, xem xét beneficiaries; review khi có thay đổi và định kỳ, lưu xác nhận. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95]","trap":"Recommended written procedures; suitability và reassessment là mandatory."},{"heading":"III(C) Suitability — Unsuitable order escalation","body":"Có policy documented discussion, portfolio impact assessment, client acknowledgment và separate account/IPS review nếu thích hợp. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95]","trap":"Recommended; không thực hiện mù quáng."},{"heading":"III(D) Performance Presentation — Performance data governance","body":"Review composite inclusion, terminated account history, calculation and disclosures; lưu dữ liệu, xem xét sophistication của audience, cung cấp chi tiết theo yêu cầu; khuyến khích GIPS. [CFAI PDF pp. 152–156; Kaplan PDF pp. 178–179; SAPP PDF pp. 96–99]","trap":"Recommended; reasonable efforts là mandatory."},{"heading":"III(E) Preservation of Confidentiality — Access and secure communication","body":"Chỉ chia sẻ với người có thẩm quyền phục vụ client, kiểm tra người nhận, thiết lập lưu trữ an toàn, đào tạo, xử lý disclosure theo luật và policy. [CFAI PDF pp. 157–160; Kaplan PDF pp. 179; SAPP PDF pp. 100–104]","trap":"Recommended; confidentiality là mandatory."},{"heading":"IV(A) Loyalty — Outside activity and separation policy","body":"Có quy trình consent hoạt động cạnh tranh, bảo mật, bàn giao/thu hồi records, social media policy; tách tài khoản cá nhân và nghề nghiệp, cân bằng incentive. [CFAI PDF pp. 161–171; Kaplan PDF pp. 180–181; SAPP PDF pp. 105–115]","trap":"Recommended; consent trước hoạt động cạnh tranh là yêu cầu guidance."},{"heading":"IV(B) Additional Compensation Arrangements — Document proposed terms","body":"Báo cáo bằng văn bản nature, estimated value, conditions/duration và parties; xác minh terms từ bên đề nghị, lưu consent trước khi nhận. [CFAI PDF pp. 172–173; Kaplan PDF pp. 181–182; SAPP PDF pp. 116–119]","trap":"Recommended documentation; written consent từ all parties là mandatory."},{"heading":"IV(C) Responsibilities of Supervisors — Compliance system design","body":"Viết quy trình rõ ràng, phạm vi và authority compliance, checks and balances, permitted conduct, reporting, sanctions, training và review; tách code nguyên tắc khỏi thủ tục chi tiết, incentive không khuyến khích sai phạm. [CFAI PDF pp. 174–182; Kaplan PDF pp. 182–183; SAPP PDF pp. 120–127]","trap":"Recommended; reasonable efforts là mandatory."},{"heading":"IV(C) Responsibilities of Supervisors — Respond to suspected breaches","body":"Điều tra, tăng supervision hoặc giới hạn hoạt động, ghi nhận escalation, cập nhật quy trình và đào tạo. Nếu hệ thống không đầy đủ, từ chối nhận responsibility bằng văn bản. [CFAI PDF pp. 174–182; Kaplan PDF pp. 182–183; SAPP PDF pp. 120–127]","trap":"Recommended procedure grounded in guidance; reasonable preventive/detective efforts required."},{"heading":"V(A) Diligence and Reasonable Basis — Research quality assurance","body":"Có chuẩn minimum research, documented basis, criteria chất lượng và review third-party sources định kỳ; incentive dựa trên chất lượng, không chỉ rating hay doanh thu. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136]","trap":"Recommended; adequate basis là mandatory."},{"heading":"V(A) Diligence and Reasonable Basis — Model and manager diligence","body":"Quy định scenario/sensitivity tests, validation của model, inputs và accuracy over time; đánh giá external manager theo criteria và lịch review. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136]","trap":"Recommended; tùy vai trò và sản phẩm."},{"heading":"V(B) Communication with Clients and Prospective Clients — Service and cost disclosure review","body":"Kiểm tra tài liệu onboarding và prospect, phí trực tiếp/gián tiếp/third-party, thay đổi dịch vụ/cost; mẫu communication phải cập nhật, lưu bằng chứng. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143]","trap":"Recommended mechanism; disclosure obligations mandatory."},{"heading":"V(B) Communication with Clients and Prospective Clients — Material process change communication","body":"Quy trình xác định significant risk/limitation, review report và phân biệt forecast/fact; thông báo kịp thời thay đổi material; lưu communication ở mọi kênh. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143]","trap":"Recommended; prompt disclosure of material process change required."},{"heading":"V(C) Record Retention — Retention and access protocol","body":"Có lịch retention theo luật/policy, backup, access controls, lưu input/model và communications, bàn giao khi nghỉ; nếu không có quy định, dùng hướng dẫn 7 năm. [CFAI PDF pp. 207–209; Kaplan PDF pp. 186; SAPP PDF pp. 144–148]","trap":"Recommended; appropriate records là mandatory."},{"heading":"VI(A) Avoid or Disclose Conflicts — Conflict inventory and disclosure","body":"Khai báo ownership, outside interests, compensation và issuer ties; review, avoid/recuse khi khả thi, disclosure prominent plain language và cập nhật thay đổi. [CFAI PDF pp. 210–214; Kaplan PDF pp. 187–188; SAPP PDF pp. 149–157]","trap":"Recommended mechanism; tránh hoặc full/fair disclosure là mandatory."},{"heading":"VI(B) Priority of Transactions — Personal trade controls","body":"Disclose holdings/beneficial ownership, preclearance, blackout/restricted periods phù hợp, duplicate confirmations hoặc periodic statements; hạn chế IPO/private placements, review giao dịch và sanctions. [CFAI PDF pp. 215–220; Kaplan PDF pp. 188–189; SAPP PDF pp. 158–164]","trap":"Recommended controls; priority mandatory."},{"heading":"VI(C) Referral Fees — Referral program controls","body":"Khuyến khích firm cấm hoặc yêu cầu approval; thông báo client về approved programs, cập nhật employer thường xuyên (ít nhất quarterly được khuyến nghị) về amount và nature. [CFAI PDF pp. 221–223; Kaplan PDF pp. 189; SAPP PDF pp. 165–168]","trap":"Recommended; appropriate disclosure mandatory."},{"heading":"VII(A) Conduct as Participants in CFA Institute Programs — Program confidentiality controls","body":"Đọc và tuân Candidate Pledge/testing policies, giới hạn quyền truy cập thông tin chương trình, không lưu/chia sẻ exam content; training và review cho volunteers. Đây là cách thực hành phòng ngừa dựa trên guidance, không phải danh mục riêng bắt buộc. [CFAI PDF pp. 224–229; Kaplan PDF pp. 189–190; SAPP PDF pp. 169–174]","trap":"Mandatory: integrity and confidentiality; control cụ thể là cách hỗ trợ."},{"heading":"VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program — Review references and marketing","body":"Giải thích proper references cho HR/marketing, review CV, bios, business cards, websites, status changes; sửa claims về performance hoặc superiority. [CFAI PDF pp. 230–235; Kaplan PDF pp. 190–191; SAPP PDF pp. 175–183]","trap":"Recommended; không misrepresent là mandatory."},{"heading":"I(A) — Prevention controls and compliance workflow","body":"Lập danh mục luật theo khu vực và sản phẩm; cập nhật kênh giao tiếp mới; lưu tư vấn, quá trình báo cáo và tách khỏi vi phạm. Quy trình không thay thế hành động khi đã biết vi phạm.","body_en":"Keep a jurisdiction-by-product register, update it for new communication channels, and record compliance advice, escalation and dissociation. A procedure assists compliance; it cannot replace action on a known violation.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 67–76 (I(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"I(B) — Prevention controls and compliance workflow","body":"Tách thu nhập nghiên cứu khỏi kết quả bán hàng/ngân hàng đầu tư; ghi lợi ích bên thứ ba, dùng restricted list khi cần và ghi lý do chuyến đi ngoại lệ cần thiết, hợp lý.","body_en":"Separate research pay from banking or sales outcomes; record third-party benefits, use a restricted list where necessary, and document why exceptional travel is necessary and proportionate.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 76–90 (I(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"I(C) — Prevention controls and compliance workflow","body":"Lưu tài liệu và danh mục nguồn, kiểm tra bằng cấp/thành tích công bố, dùng chính sách định giá nhất quán và sổ đính chính ghi người nhận.","body_en":"Maintain source files and an attribution register, verify public credentials and performance claims, use consistent pricing policies, and keep a correction log with the recipients notified.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 90–101 (I(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"I(D) — Prevention controls and compliance workflow","body":"Có chính sách ứng xử, ghi nhận vấn đề bằng chứng cứ thay vì tin đồn, dùng kênh báo cáo phù hợp. Đào tạo phân biệt vấn đề liêm chính nghề với hành vi cá nhân không liên quan.","body_en":"Adopt a conduct policy, document concerns with evidence rather than rumors, and use appropriate escalation channels. Training should distinguish professional-integrity issues from unrelated personal conduct.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 101–104 (I(D)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"I(E) — Prevention controls and compliance workflow","body":"Ánh xạ nhiệm vụ với kỹ năng, đánh giá thiếu hụt khi đổi vai trò, đào tạo/giám sát có trọng tâm và đánh giá lại khi sản phẩm hoặc phương pháp đổi.","body_en":"Map duties to skills, assess gaps at role transitions, arrange targeted training and oversight, and reassess capability as products or methods change.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 104–109 (I(E)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"II(A) — Prevention controls and compliance workflow","body":"Dùng tường thông tin, danh sách hạn chế/theo dõi, kiểm soát truy cập, kiểm tra công bố và ghi nghiên cứu mosaic đồng thời. Hỏi compliance trước khi giao dịch nếu chưa rõ tình trạng thông tin.","body_en":"Use information barriers, restricted/watch lists, controlled access, public-release checks and contemporaneous mosaic research notes. Escalate uncertain information status before trading.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 109–120 (II(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"II(B) — Prevention controls and compliance workflow","body":"Rà soát mẫu lệnh bất thường và thông tin công bố, lưu lý do giao dịch và điều tra dấu hiệu ý định đánh lừa thay vì coi mọi tác động giá là sai.","body_en":"Review unusual order patterns and public claims, retain execution rationale and investigate evidence of misleading intent rather than treating all price impact as misconduct.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 120–124 (II(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"III(A) — Prevention controls and compliance workflow","body":"Rà chất lượng/chi phí broker, ghi chỉ dẫn và xung đột, kiểm soát lưu ký, rà quyết định proxy theo lợi ích người thụ hưởng.","body_en":"Review brokerage quality and costs, document client-directed instructions and conflicts, maintain custody controls, and review proxy decisions in beneficiaries' interests.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 125–135 (III(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"III(B) — Prevention controls and compliance workflow","body":"Dùng công bố theo thời điểm, chính sách phân bổ, ghi lệnh trước giao dịch và rà ngoại lệ; công bố khác biệt dịch vụ.","body_en":"Use timed dissemination, a documented allocation policy, pre-trade order records and periodic exception reviews; disclose service differences.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 135–144 (III(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"III(C) — Prevention controls and compliance workflow","body":"Duy trì IPS cập nhật, ghi thay đổi trọng yếu và đánh giá phù hợp toàn danh mục, quy định kênh xử lý lệnh không phù hợp do khách chủ động.","body_en":"Maintain current IPS records, document material changes and the suitability assessment for the whole portfolio, and define an escalation path for unsolicited unsuitable requests.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 144–152 (III(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"III(D) — Prevention controls and compliance workflow","body":"Lưu dữ liệu hiệu suất và quy tắc composite, ghi nhãn mô phỏng/phí trọng yếu, đối chiếu số marketing với hồ sơ nguồn.","body_en":"Retain supporting performance data and composite rules, label simulations and material fees, and independently reconcile marketing figures to the source records.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 152–157 (III(D)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"III(E) — Prevention controls and compliance workflow","body":"Giới hạn truy cập theo vai trò, dùng giao tiếp an toàn, lưu chấp thuận, hỏi compliance/legal trước công bố bất thường.","body_en":"Limit access by role, use secure communications, obtain and retain permissions, and consult compliance/legal before unusual disclosure.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 157–162 (III(E)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"IV(A) — Prevention controls and compliance workflow","body":"Làm rõ chính sách việc ngoài/ nghỉ việc, lưu chấp thuận, kiểm soát lấy hồ sơ, dùng kênh báo cáo an toàn cho sai phạm nghiêm trọng.","body_en":"Clarify outside activity and departure policies, document permissions, control record removal and use secure reporting channels for serious misconduct.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 162–172 (IV(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"IV(B) — Prevention controls and compliance workflow","body":"Ghi điều khoản, bản chất, số tiền và thời hạn thù lao ngoài, lấy chấp thuận văn bản trước khi nhận, đánh giá lại khi đổi điều khoản.","body_en":"Record terms, nature, amount and duration of proposed outside compensation, obtain written consent before acceptance, and reassess if terms change.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 172–175 (IV(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"IV(C) — Prevention controls and compliance workflow","body":"Duy trì kiểm soát phòng ngừa/phát hiện bằng văn bản, phân quyền, đào tạo, kiểm tra tuân thủ, ghi điều tra và hạn chế hoạt động nghi vấn trong khi điều tra.","body_en":"Maintain written preventive/detective controls, assign authority, train staff, test compliance, record investigations and restrict suspect activities while investigating.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 174–183 (IV(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"V(A) — Prevention controls and compliance workflow","body":"Yêu cầu kiểm định mô hình, rà nhà cung cấp nghiên cứu, đánh giá định kỳ và ghi giả định lớn, stress test, ý kiến khác khi phù hợp.","body_en":"Require model validation, research-provider review, periodic reassessment and documentation of major assumptions, stress tests and dissent when appropriate.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 183–195 (V(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"V(B) — Prevention controls and compliance workflow","body":"Duy trì công bố phí/dịch vụ, sổ thông báo đổi quy trình, rà rủi ro trọng yếu trong thông tin và ghi rõ ước tính là ý kiến.","body_en":"Maintain client-facing fee and service disclosures, a process-change notification log, review communications for material risks, and mark estimates clearly as opinions.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 195–207 (V(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"V(C) — Prevention controls and compliance workflow","body":"Lưu tin nhắn trọng yếu, dữ liệu nguồn, mô hình, ghi chú quyết định theo quy tắc lưu; kiểm tra khả năng phục hồi và lưu chấp thuận chuyển hồ sơ.","body_en":"Archive material messages, source data, models and decision notes under documented retention rules; test recoverability and record permission for any transfer.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 207–210 (V(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"VI(A) — Prevention controls and compliance workflow","body":"Duy trì sổ xung đột, xét tránh hoặc chuyển nhiệm vụ, công bố quan hệ trọng yếu rõ ràng, theo dõi thay đổi sở hữu hưởng lợi và thù lao.","body_en":"Maintain a conflict register, evaluate avoidance or reassignment, disclose material relationships in plain language and monitor changes to beneficial ownership and compensation.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 210–215 (VI(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"VI(B) — Prevention controls and compliance workflow","body":"Dùng preclearance, blackout phù hợp, khai lợi ích sở hữu, theo dõi tài khoản và kiểm tra phân bổ công bằng.","body_en":"Use preclearance, blackout periods where appropriate, beneficial-interest declarations, account monitoring and fair allocation checks.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 215–221 (VI(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"VI(C) — Prevention controls and compliance workflow","body":"Theo dõi giới thiệu nhận/trả kể cả lợi ích phi tiền, lấy phê duyệt firm cần thiết và công bố trước thỏa thuận khách liên quan.","body_en":"Track paid and received referrals, including noncash benefits, obtain required firm approvals and disclose terms before the relevant client agreement.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 221–224 (VI(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"VII(A) — Prevention controls and compliance workflow","body":"Đọc quy định ứng viên và bảo mật tình nguyện viên, tách thông tin công khai khỏi tài liệu mật, tránh chia sẻ nội dung thi tái dựng.","body_en":"Review candidate rules and volunteer confidentiality obligations, separate public information from protected material, and avoid sharing reconstructed exam content.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 224–230 (VII(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"VII(B) — Prevention controls and compliance workflow","body":"Rà bio/marketing về trạng thái active, dùng nhãn đúng, thành tích factual và không bảo đảm hiệu suất; sửa tuyên bố lỗi thời kịp thời.","body_en":"Review biographies and marketing for active status, correct use of marks, accurate factual achievements and absence of performance guarantees; correct obsolete claims promptly.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 230–235 (VII(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"}],"formulas":[{"name":"I(A) — Keep the legal inventory current","expr":"Theo dõi thay đổi luật, lưu bản cập nhật, định kỳ rà soát chính sách; có kênh báo cáo vi phạm và hướng dẫn sản phẩm xuyên biên giới.","meaning":"Recommended procedures; nghĩa vụ tuân thủ và dissociate là bắt buộc.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"I(A) — Escalate and document","expr":"Ghi nhận sự việc, trao đổi với supervisor/compliance, xin tư vấn pháp lý khi cần; nếu không sửa được, ngừng liên quan đến hành vi sai phạm.","meaning":"Documentation là recommended; không trì hoãn dissociation.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"I(B) — Protect research and gift policy","expr":"Tách research khỏi áp lực investment banking, restricted list nếu không thể công bố nhận định độc lập, giới hạn quà bên ngoài mức tượng trưng, có quy trình review và báo cáo.","meaning":"Recommended; độc lập và không nhận inducement là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"I(B) — Travel, IPO and placement controls","expr":"Tự trả chi phí đi lại khi thực tế cho phép; yêu cầu preclearance, hạn chế IPO/private placements, bổ nhiệm compliance officer có thẩm quyền.","meaning":"Recommended, không phải lệnh cấm tuyệt đối mọi chuyến đi.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"I(C) — Verify marketing and credentials","expr":"Lập mô tả bằng văn bản về dịch vụ, năng lực và kinh nghiệm; kiểm tra định kỳ tài liệu, website, dữ liệu vendor và claims của bên thứ ba; sửa sai sớm.","meaning":"Recommended; cấm knowingly misrepresent là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"I(C) — Attribution trail","expr":"Lưu báo cáo, ghi nguồn của bản tóm tắt, trích dẫn mô hình/biểu đồ và kiểm tra quyền sử dụng; lưu các bản sửa.","meaning":"Recommended; không đạo văn là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"I(D) — Conduct and hiring controls","expr":"Khuyến nghị code of ethics, thông báo hành vi bị cấm và chế tài, kiểm tra references của ứng viên.","meaning":"Recommended; mục tiêu ngăn hành vi thiếu trung thực.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"I(E) — Role gap assessment","expr":"Đánh giá khoảng trống kỹ năng khi chuyển vị trí; lập kế hoạch tự học, đào tạo, mentoring, tham vấn chuyên gia; cập nhật kiến thức khi sản phẩm/quy định thay đổi.","meaning":"Recommended methods; duy trì năng lực là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"II(A) — Information barriers","expr":"Thiết lập firewall giữa bộ phận, restricted/watch lists, kiểm soát luồng thông tin, review giao dịch cá nhân và proprietary; phân quyền, kiểm tra tài liệu và đào tạo.","meaning":"Recommended; không act/cause others to act là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"II(A) — Public dissemination and mosaic records","expr":"Khuyến khích public disclosure; theo dõi thời điểm phổ biến, lưu nguồn và lý do của phân tích mosaic; compliance xem xét khi vô tình nhận MNPI.","meaning":"Recommended; không giao dịch trước khi thông tin public.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"II(B) — Trade and communication surveillance","expr":"Kiểm soát giao dịch đối ứng, bất thường cuối phiên, tin đồn và xung đột; lưu lý do kinh tế, review truyền thông và escalation. Đây là biện pháp thiết kế bổ trợ, không phải danh mục quy trình bắt buộc riêng của Standard.","meaning":"CFAI guidance: prohibitions và intent; control thực hành được suy ra từ mục tiêu phòng ngừa.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"III(A) — Client asset safeguards","expr":"Xác định client, mục tiêu, giới hạn, tài sản custody; phân tách tài sản và cung cấp statement định kỳ (quarterly được khuyến nghị khi kiểm soát tài sản), có chính sách vote proxy và rà soát brokerage.","meaning":"Recommended; nghĩa vụ client first là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"III(A) — Best execution review","expr":"Đánh giá giá/chi phí/khả năng thực hiện, chất lượng dịch vụ, cách sử dụng brokerage; minh bạch directed brokerage và giới hạn execution.","meaning":"Recommended process.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"III(B) — Dissemination protocol","expr":"Giới hạn người biết trước, rút ngắn thời gian từ quyết định đến phổ biến, hướng dẫn giao tiếp, phát hành đồng thời khi khả thi, lưu thời điểm, thông báo service tiers.","meaning":"Recommended; fair treatment là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"III(B) — Trade allocation policy","expr":"Ghi thời điểm và lệnh, preallocate hoặc theo quy trình công bằng, average price khi phù hợp, review accounts, công bố policy và mức dịch vụ.","meaning":"Recommended; pro rata không phải quy tắc duy nhất.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"III(C) — Written IPS and periodic review","expr":"Lập IPS nêu risk/return, constraints, benchmark, trách nhiệm, xem xét beneficiaries; review khi có thay đổi và định kỳ, lưu xác nhận.","meaning":"Recommended written procedures; suitability và reassessment là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"III(C) — Unsuitable order escalation","expr":"Có policy documented discussion, portfolio impact assessment, client acknowledgment và separate account/IPS review nếu thích hợp.","meaning":"Recommended; không thực hiện mù quáng.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"III(D) — Performance data governance","expr":"Review composite inclusion, terminated account history, calculation and disclosures; lưu dữ liệu, xem xét sophistication của audience, cung cấp chi tiết theo yêu cầu; khuyến khích GIPS.","meaning":"Recommended; reasonable efforts là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"III(E) — Access and secure communication","expr":"Chỉ chia sẻ với người có thẩm quyền phục vụ client, kiểm tra người nhận, thiết lập lưu trữ an toàn, đào tạo, xử lý disclosure theo luật và policy.","meaning":"Recommended; confidentiality là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"IV(A) — Outside activity and separation policy","expr":"Có quy trình consent hoạt động cạnh tranh, bảo mật, bàn giao/thu hồi records, social media policy; tách tài khoản cá nhân và nghề nghiệp, cân bằng incentive.","meaning":"Recommended; consent trước hoạt động cạnh tranh là yêu cầu guidance.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"IV(B) — Document proposed terms","expr":"Báo cáo bằng văn bản nature, estimated value, conditions/duration và parties; xác minh terms từ bên đề nghị, lưu consent trước khi nhận.","meaning":"Recommended documentation; written consent từ all parties là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"IV(C) — Compliance system design","expr":"Viết quy trình rõ ràng, phạm vi và authority compliance, checks and balances, permitted conduct, reporting, sanctions, training và review; tách code nguyên tắc khỏi thủ tục chi tiết, incentive không khuyến khích sai phạm.","meaning":"Recommended; reasonable efforts là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"IV(C) — Respond to suspected breaches","expr":"Điều tra, tăng supervision hoặc giới hạn hoạt động, ghi nhận escalation, cập nhật quy trình và đào tạo. Nếu hệ thống không đầy đủ, từ chối nhận responsibility bằng văn bản.","meaning":"Recommended procedure grounded in guidance; reasonable preventive/detective efforts required.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"V(A) — Research quality assurance","expr":"Có chuẩn minimum research, documented basis, criteria chất lượng và review third-party sources định kỳ; incentive dựa trên chất lượng, không chỉ rating hay doanh thu.","meaning":"Recommended; adequate basis là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"V(A) — Model and manager diligence","expr":"Quy định scenario/sensitivity tests, validation của model, inputs và accuracy over time; đánh giá external manager theo criteria và lịch review.","meaning":"Recommended; tùy vai trò và sản phẩm.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"V(B) — Service and cost disclosure review","expr":"Kiểm tra tài liệu onboarding và prospect, phí trực tiếp/gián tiếp/third-party, thay đổi dịch vụ/cost; mẫu communication phải cập nhật, lưu bằng chứng.","meaning":"Recommended mechanism; disclosure obligations mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"V(B) — Material process change communication","expr":"Quy trình xác định significant risk/limitation, review report và phân biệt forecast/fact; thông báo kịp thời thay đổi material; lưu communication ở mọi kênh.","meaning":"Recommended; prompt disclosure of material process change required.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"V(C) — Retention and access protocol","expr":"Có lịch retention theo luật/policy, backup, access controls, lưu input/model và communications, bàn giao khi nghỉ; nếu không có quy định, dùng hướng dẫn 7 năm.","meaning":"Recommended; appropriate records là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"VI(A) — Conflict inventory and disclosure","expr":"Khai báo ownership, outside interests, compensation và issuer ties; review, avoid/recuse khi khả thi, disclosure prominent plain language và cập nhật thay đổi.","meaning":"Recommended mechanism; tránh hoặc full/fair disclosure là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"VI(B) — Personal trade controls","expr":"Disclose holdings/beneficial ownership, preclearance, blackout/restricted periods phù hợp, duplicate confirmations hoặc periodic statements; hạn chế IPO/private placements, review giao dịch và sanctions.","meaning":"Recommended controls; priority mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"VI(C) — Referral program controls","expr":"Khuyến khích firm cấm hoặc yêu cầu approval; thông báo client về approved programs, cập nhật employer thường xuyên (ít nhất quarterly được khuyến nghị) về amount và nature.","meaning":"Recommended; appropriate disclosure mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"VII(A) — Program confidentiality controls","expr":"Đọc và tuân Candidate Pledge/testing policies, giới hạn quyền truy cập thông tin chương trình, không lưu/chia sẻ exam content; training và review cho volunteers. Đây là cách thực hành phòng ngừa dựa trên guidance, không phải danh mục riêng bắt buộc.","meaning":"Mandatory: integrity and confidentiality; control cụ thể là cách hỗ trợ.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"name":"VII(B) — Review references and marketing","expr":"Giải thích proper references cho HR/marketing, review CV, bios, business cards, websites, status changes; sửa claims về performance hoặc superiority.","meaning":"Recommended; không misrepresent là mandatory.","conditions":"Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."}],"examples":[{"question_en":"A firm distributes funds in three jurisdictions. Which control best supports compliance?","steps_vi":["Xác định chuẩn liên quan: I(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Theo dõi thay đổi luật, lưu bản cập nhật, định kỳ rà soát chính sách; có kênh báo cáo vi phạm và hướng dẫn sản phẩm xuyên biên giới. Recommended procedures; nghĩa vụ tuân thủ và dissociate là bắt buộc."],"answer":"Maintain a current jurisdiction-specific rule inventory and review procedures.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A compliance review confirms a continuing unlawful practice. Which procedure best supports the analyst's duties?","steps_vi":["Xác định chuẩn liên quan: I(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Ghi nhận sự việc, trao đổi với supervisor/compliance, xin tư vấn pháp lý khi cần; nếu không sửa được, ngừng liên quan đến hành vi sai phạm. Documentation là recommended; không trì hoãn dissociation."],"answer":"Document escalation and provide a mechanism to withdraw from the activity.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which policy best reduces pressure from an investment banking division?","steps_vi":["Xác định chuẩn liên quan: I(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Tách research khỏi áp lực investment banking, restricted list nếu không thể công bố nhận định độc lập, giới hạn quà bên ngoài mức tượng trưng, có quy trình review và báo cáo. Recommended; độc lập và không nhận inducement là mandatory."],"answer":"Independent research review and a restricted list when objective coverage cannot be maintained.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which procedure best addresses preferential allocations to employees?","steps_vi":["Xác định chuẩn liên quan: I(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Tự trả chi phí đi lại khi thực tế cho phép; yêu cầu preclearance, hạn chế IPO/private placements, bổ nhiệm compliance officer có thẩm quyền. Recommended, không phải lệnh cấm tuyệt đối mọi chuyến đi."],"answer":"Preclear and restrict employee IPO participation.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which review most directly reduces misleading marketing claims?","steps_vi":["Xác định chuẩn liên quan: I(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Lập mô tả bằng văn bản về dịch vụ, năng lực và kinh nghiệm; kiểm tra định kỳ tài liệu, website, dữ liệu vendor và claims của bên thứ ba; sửa sai sớm. Recommended; cấm knowingly misrepresent là mandatory."],"answer":"Verify credentials and third-party claims before publication.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which procedure best prevents unattributed use of external models?","steps_vi":["Xác định chuẩn liên quan: I(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Lưu báo cáo, ghi nguồn của bản tóm tắt, trích dẫn mô hình/biểu đồ và kiểm tra quyền sử dụng; lưu các bản sửa. Recommended; không đạo văn là mandatory."],"answer":"Maintain source records and require attribution in research.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which control most directly supports I(D)?","steps_vi":["Xác định chuẩn liên quan: I(D). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Khuyến nghị code of ethics, thông báo hành vi bị cấm và chế tài, kiểm tra references của ứng viên. Recommended; mục tiêu ngăn hành vi thiếu trung thực."],"answer":"Communicate sanctions for fraudulent conduct and check employment references.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which action best prepares an equity analyst for a new credit-risk mandate?","steps_vi":["Xác định chuẩn liên quan: I(E). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Đánh giá khoảng trống kỹ năng khi chuyển vị trí; lập kế hoạch tự học, đào tạo, mentoring, tham vấn chuyên gia; cập nhật kiến thức khi sản phẩm/quy định thay đổi. Recommended methods; duy trì năng lực là mandatory."],"answer":"Identify skill gaps and acquire relevant training and support before assuming unsupported duties.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which control best reduces the risk of confidential deal information reaching traders?","steps_vi":["Xác định chuẩn liên quan: II(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Thiết lập firewall giữa bộ phận, restricted/watch lists, kiểm soát luồng thông tin, review giao dịch cá nhân và proprietary; phân quyền, kiểm tra tài liệu và đào tạo. Recommended; không act/cause others to act là mandatory."],"answer":"Information barriers and monitored restricted lists.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A company gives selected analysts a material update. Which procedure is most appropriate?","steps_vi":["Xác định chuẩn liên quan: II(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Khuyến khích public disclosure; theo dõi thời điểm phổ biến, lưu nguồn và lý do của phân tích mosaic; compliance xem xét khi vô tình nhận MNPI. Recommended; không giao dịch trước khi thông tin public."],"answer":"Seek broad public dissemination and restrict use until the information is public.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which surveillance best targets transaction-based manipulation?","steps_vi":["Xác định chuẩn liên quan: II(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Kiểm soát giao dịch đối ứng, bất thường cuối phiên, tin đồn và xung đột; lưu lý do kinh tế, review truyền thông và escalation. Đây là biện pháp thiết kế bổ trợ, không phải danh mục quy trình bắt buộc riêng của Standard. CFAI guidance: prohibitions và intent; control thực hành được suy ra từ mục tiêu phòng ngừa."],"answer":"Review matched trades and unexplained end-of-session price changes.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which procedure best protects client assets held by a manager?","steps_vi":["Xác định chuẩn liên quan: III(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Xác định client, mục tiêu, giới hạn, tài sản custody; phân tách tài sản và cung cấp statement định kỳ (quarterly được khuyến nghị khi kiểm soát tài sản), có chính sách vote proxy và rà soát brokerage. Recommended; nghĩa vụ client first là mandatory."],"answer":"Segregate client assets and provide regular account statements.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which review best supports best execution?","steps_vi":["Xác định chuẩn liên quan: III(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Đánh giá giá/chi phí/khả năng thực hiện, chất lượng dịch vụ, cách sử dụng brokerage; minh bạch directed brokerage và giới hạn execution. Recommended process."],"answer":"Assess total execution quality, costs and client benefits.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which dissemination procedure best supports III(B)?","steps_vi":["Xác định chuẩn liên quan: III(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Giới hạn người biết trước, rút ngắn thời gian từ quyết định đến phổ biến, hướng dẫn giao tiếp, phát hành đồng thời khi khả thi, lưu thời điểm, thông báo service tiers. Recommended; fair treatment là mandatory."],"answer":"Release recommendation changes to eligible clients through a common process before individualized follow-up.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which allocation practice best prevents cherry-picking?","steps_vi":["Xác định chuẩn liên quan: III(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Ghi thời điểm và lệnh, preallocate hoặc theo quy trình công bằng, average price khi phù hợp, review accounts, công bố policy và mức dịch vụ. Recommended; pro rata không phải quy tắc duy nhất."],"answer":"Set objective allocation rules before trade outcomes are known.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which procedure best supports suitability for an advisory client?","steps_vi":["Xác định chuẩn liên quan: III(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Lập IPS nêu risk/return, constraints, benchmark, trách nhiệm, xem xét beneficiaries; review khi có thay đổi và định kỳ, lưu xác nhận. Recommended written procedures; suitability và reassessment là mandatory."],"answer":"Collect and periodically update objectives, financial circumstances and constraints.","check":"Original case; conclusion limited to facts stated."},{"question_en":"What should a manager do first upon receiving an unsuitable unsolicited order?","steps_vi":["Xác định chuẩn liên quan: III(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Có policy documented discussion, portfolio impact assessment, client acknowledgment và separate account/IPS review nếu thích hợp. Recommended; không thực hiện mù quáng."],"answer":"Discuss why it conflicts with the client's stated objectives or constraints.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which procedure best reduces survivorship bias in a performance presentation?","steps_vi":["Xác định chuẩn liên quan: III(D). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Review composite inclusion, terminated account history, calculation and disclosures; lưu dữ liệu, xem xét sophistication của audience, cung cấp chi tiết theo yêu cầu; khuyến khích GIPS. Recommended; reasonable efforts là mandatory."],"answer":"Retain terminated portfolios in historical results through their termination dates.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which procedure best protects client confidentiality?","steps_vi":["Xác định chuẩn liên quan: III(E). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Chỉ chia sẻ với người có thẩm quyền phục vụ client, kiểm tra người nhận, thiết lập lưu trữ an toàn, đào tạo, xử lý disclosure theo luật và policy. Recommended; confidentiality là mandatory."],"answer":"Limit access to authorized personnel with a client-related need.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which policy best reduces conflicts when employees leave?","steps_vi":["Xác định chuẩn liên quan: IV(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Có quy trình consent hoạt động cạnh tranh, bảo mật, bàn giao/thu hồi records, social media policy; tách tài khoản cá nhân và nghề nghiệp, cân bằng incentive. Recommended; consent trước hoạt động cạnh tranh là yêu cầu guidance."],"answer":"Define acceptable preparations, client solicitation restrictions and return of firm records.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which action best supports compliance for a proposed outside performance bonus?","steps_vi":["Xác định chuẩn liên quan: IV(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Báo cáo bằng văn bản nature, estimated value, conditions/duration và parties; xác minh terms từ bên đề nghị, lưu consent trước khi nhận. Recommended documentation; written consent từ all parties là mandatory."],"answer":"Obtain written consent from all involved parties before accepting.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which control best supports supervisory responsibilities?","steps_vi":["Xác định chuẩn liên quan: IV(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Viết quy trình rõ ràng, phạm vi và authority compliance, checks and balances, permitted conduct, reporting, sanctions, training và review; tách code nguyên tắc khỏi thủ tục chi tiết, incentive không khuyến khích sai phạm. Recommended; reasonable efforts là mandatory."],"answer":"Written procedures, assigned authority, monitoring and corrective action.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A supervisor receives credible evidence of misconduct. What is the most appropriate response?","steps_vi":["Xác định chuẩn liên quan: IV(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Điều tra, tăng supervision hoặc giới hạn hoạt động, ghi nhận escalation, cập nhật quy trình và đào tạo. Nếu hệ thống không đầy đủ, từ chối nhận responsibility bằng văn bản. Recommended procedure grounded in guidance; reasonable preventive/detective efforts required."],"answer":"Promptly investigate and restrict activity as warranted during the review.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which policy best supports reliance on external research?","steps_vi":["Xác định chuẩn liên quan: V(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Có chuẩn minimum research, documented basis, criteria chất lượng và review third-party sources định kỳ; incentive dựa trên chất lượng, không chỉ rating hay doanh thu. Recommended; adequate basis là mandatory."],"answer":"Periodically evaluate the provider's assumptions, rigor, timeliness and independence.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which procedure best addresses a complex quantitative model?","steps_vi":["Xác định chuẩn liên quan: V(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Quy định scenario/sensitivity tests, validation của model, inputs và accuracy over time; đánh giá external manager theo criteria và lịch review. Recommended; tùy vai trò và sản phẩm."],"answer":"Test the model across relevant scenarios and examine input sensitivity.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which onboarding practice best supports V(B)?","steps_vi":["Xác định chuẩn liên quan: V(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Kiểm tra tài liệu onboarding và prospect, phí trực tiếp/gián tiếp/third-party, thay đổi dịch vụ/cost; mẫu communication phải cập nhật, lưu bằng chứng. Recommended mechanism; disclosure obligations mandatory."],"answer":"Explain services and reasonably detailed costs, including applicable third-party charges.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which procedure best addresses a major change to portfolio construction?","steps_vi":["Xác định chuẩn liên quan: V(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Quy trình xác định significant risk/limitation, review report và phân biệt forecast/fact; thông báo kịp thời thay đổi material; lưu communication ở mọi kênh. Recommended; prompt disclosure of material process change required."],"answer":"Notify affected clients promptly and explain material implications.","check":"Original case; conclusion limited to facts stated."},{"question_en":"In the absence of an applicable legal or firm retention period, what does CFA Institute recommend?","steps_vi":["Xác định chuẩn liên quan: V(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Có lịch retention theo luật/policy, backup, access controls, lưu input/model và communications, bàn giao khi nghỉ; nếu không có quy định, dùng hướng dẫn 7 năm. Recommended; appropriate records là mandatory."],"answer":"Retain records for at least seven years.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which policy best implements VI(A)?","steps_vi":["Xác định chuẩn liên quan: VI(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Khai báo ownership, outside interests, compensation và issuer ties; review, avoid/recuse khi khả thi, disclosure prominent plain language và cập nhật thay đổi. Recommended mechanism; tránh hoặc full/fair disclosure là mandatory."],"answer":"Maintain a conflict register, seek avoidance and provide prominent understandable disclosures for remaining conflicts.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which procedure best helps prevent front-running?","steps_vi":["Xác định chuẩn liên quan: VI(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Disclose holdings/beneficial ownership, preclearance, blackout/restricted periods phù hợp, duplicate confirmations hoặc periodic statements; hạn chế IPO/private placements, review giao dịch và sanctions. Recommended controls; priority mandatory."],"answer":"Require preclearance and review employee trades against pending client orders.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which procedure best supports VI(C)?","steps_vi":["Xác định chuẩn liên quan: VI(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Khuyến khích firm cấm hoặc yêu cầu approval; thông báo client về approved programs, cập nhật employer thường xuyên (ít nhất quarterly được khuyến nghị) về amount và nature. Recommended; appropriate disclosure mandatory."],"answer":"Require prior approval and timely disclosure of referral benefits with periodic employer updates.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which study-group rule best protects CFA Program integrity?","steps_vi":["Xác định chuẩn liên quan: VII(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Đọc và tuân Candidate Pledge/testing policies, giới hạn quyền truy cập thông tin chương trình, không lưu/chia sẻ exam content; training và review cho volunteers. Đây là cách thực hành phòng ngừa dựa trên guidance, không phải danh mục riêng bắt buộc. Mandatory: integrity and confidentiality; control cụ thể là cách hỗ trợ."],"answer":"Discuss curriculum concepts without sharing actual exam content or topics tested.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Which procedure best reduces misuse of the designation?","steps_vi":["Xác định chuẩn liên quan: VII(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Giải thích proper references cho HR/marketing, review CV, bios, business cards, websites, status changes; sửa claims về performance hoặc superiority. Recommended; không misrepresent là mandatory."],"answer":"Verify current status and review marketing references for accuracy.","check":"Original case; conclusion limited to facts stated."}],"questions":[{"stem_en":"A firm distributes funds in three jurisdictions. Which control best supports compliance?","options":["Apply only the domicile's rules.","Require analysts to rely on client interpretations of law.","Maintain a current jurisdiction-specific rule inventory and review procedures."],"correct":2,"why_vi":"Theo dõi thay đổi luật, lưu bản cập nhật, định kỳ rà soát chính sách; có kênh báo cáo vi phạm và hướng dẫn sản phẩm xuyên biên giới. Recommended procedures; nghĩa vụ tuân thủ và dissociate là bắt buộc.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"I(A)"},{"stem_en":"A compliance review confirms a continuing unlawful practice. Which procedure best supports the analyst's duties?","options":["Document escalation and provide a mechanism to withdraw from the activity.","Wait until an outside regulator requests documents.","Allow continued participation if a supervisor approves."],"correct":0,"why_vi":"Ghi nhận sự việc, trao đổi với supervisor/compliance, xin tư vấn pháp lý khi cần; nếu không sửa được, ngừng liên quan đến hành vi sai phạm. Documentation là recommended; không trì hoãn dissociation.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"I(A)"},{"stem_en":"Which policy best reduces pressure from an investment banking division?","options":["Independent research review and a restricted list when objective coverage cannot be maintained.","Require issuer approval of each rating.","Tie analyst pay to underwriting revenue from covered issuers."],"correct":0,"why_vi":"Tách research khỏi áp lực investment banking, restricted list nếu không thể công bố nhận định độc lập, giới hạn quà bên ngoài mức tượng trưng, có quy trình review và báo cáo. Recommended; độc lập và không nhận inducement là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"I(B)"},{"stem_en":"Which procedure best addresses preferential allocations to employees?","options":["Reserve oversubscribed IPO shares for analysts.","Allow preferential allocation if disclosed after execution.","Preclear and restrict employee IPO participation."],"correct":2,"why_vi":"Tự trả chi phí đi lại khi thực tế cho phép; yêu cầu preclearance, hạn chế IPO/private placements, bổ nhiệm compliance officer có thẩm quyền. Recommended, không phải lệnh cấm tuyệt đối mọi chuyến đi.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"I(B)"},{"stem_en":"Which review most directly reduces misleading marketing claims?","options":["Publish claims once a vendor signs a contract.","Verify credentials and third-party claims before publication.","Use the highest reported return regardless of context."],"correct":1,"why_vi":"Lập mô tả bằng văn bản về dịch vụ, năng lực và kinh nghiệm; kiểm tra định kỳ tài liệu, website, dữ liệu vendor và claims của bên thứ ba; sửa sai sớm. Recommended; cấm knowingly misrepresent là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"I(C)"},{"stem_en":"Which procedure best prevents unattributed use of external models?","options":["Remove citations when wording is changed.","Maintain source records and require attribution in research.","Credit only sources that agree with conclusions."],"correct":1,"why_vi":"Lưu báo cáo, ghi nguồn của bản tóm tắt, trích dẫn mô hình/biểu đồ và kiểm tra quyền sử dụng; lưu các bản sửa. Recommended; không đạo văn là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"I(C)"},{"stem_en":"Which control most directly supports I(D)?","options":["Ignore falsified expense reports below a monetary threshold.","Punish staff solely for lawful political disagreement.","Communicate sanctions for fraudulent conduct and check employment references."],"correct":2,"why_vi":"Khuyến nghị code of ethics, thông báo hành vi bị cấm và chế tài, kiểm tra references của ứng viên. Recommended; mục tiêu ngăn hành vi thiếu trung thực.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"I(D)"},{"stem_en":"Which action best prepares an equity analyst for a new credit-risk mandate?","options":["Rely on the analyst's existing title alone.","Wait for a credit loss before learning the models.","Identify skill gaps and acquire relevant training and support before assuming unsupported duties."],"correct":2,"why_vi":"Đánh giá khoảng trống kỹ năng khi chuyển vị trí; lập kế hoạch tự học, đào tạo, mentoring, tham vấn chuyên gia; cập nhật kiến thức khi sản phẩm/quy định thay đổi. Recommended methods; duy trì năng lực là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"I(E)"},{"stem_en":"Which control best reduces the risk of confidential deal information reaching traders?","options":["Information barriers and monitored restricted lists.","Share deal details with traders who promise discretion.","Permit trading if the firm, rather than a person, benefits."],"correct":0,"why_vi":"Thiết lập firewall giữa bộ phận, restricted/watch lists, kiểm soát luồng thông tin, review giao dịch cá nhân và proprietary; phân quyền, kiểm tra tài liệu và đào tạo. Recommended; không act/cause others to act là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"II(A)"},{"stem_en":"A company gives selected analysts a material update. Which procedure is most appropriate?","options":["Seek broad public dissemination and restrict use until the information is public.","Treat attendance by multiple analysts as public disclosure.","Publish a trade recommendation immediately with no source detail."],"correct":0,"why_vi":"Khuyến khích public disclosure; theo dõi thời điểm phổ biến, lưu nguồn và lý do của phân tích mosaic; compliance xem xét khi vô tình nhận MNPI. Recommended; không giao dịch trước khi thông tin public.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"II(A)"},{"stem_en":"Which surveillance best targets transaction-based manipulation?","options":["Flag all large orders as proven violations.","Review matched trades and unexplained end-of-session price changes.","Exempt proprietary transactions from review."],"correct":1,"why_vi":"Kiểm soát giao dịch đối ứng, bất thường cuối phiên, tin đồn và xung đột; lưu lý do kinh tế, review truyền thông và escalation. Đây là biện pháp thiết kế bổ trợ, không phải danh mục quy trình bắt buộc riêng của Standard. CFAI guidance: prohibitions và intent; control thực hành được suy ra từ mục tiêu phòng ngừa.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"II(B)"},{"stem_en":"Which procedure best protects client assets held by a manager?","options":["Pool personal and client securities without records.","Segregate client assets and provide regular account statements.","Vote proxies solely as the sponsoring employer requests."],"correct":1,"why_vi":"Xác định client, mục tiêu, giới hạn, tài sản custody; phân tách tài sản và cung cấp statement định kỳ (quarterly được khuyến nghị khi kiểm soát tài sản), có chính sách vote proxy và rà soát brokerage. Recommended; nghĩa vụ client first là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"III(A)"},{"stem_en":"Which review best supports best execution?","options":["Select the broker offering the manager the most entertainment.","Use the lowest stated commission without considering execution.","Assess total execution quality, costs and client benefits."],"correct":2,"why_vi":"Đánh giá giá/chi phí/khả năng thực hiện, chất lượng dịch vụ, cách sử dụng brokerage; minh bạch directed brokerage và giới hạn execution. Recommended process.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"III(A)"},{"stem_en":"Which dissemination procedure best supports III(B)?","options":["Notify high-fee accounts before all other eligible clients.","Release recommendation changes to eligible clients through a common process before individualized follow-up.","Delay notification until favored accounts finish trading."],"correct":1,"why_vi":"Giới hạn người biết trước, rút ngắn thời gian từ quyết định đến phổ biến, hướng dẫn giao tiếp, phát hành đồng thời khi khả thi, lưu thời điểm, thông báo service tiers. Recommended; fair treatment là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"III(B)"},{"stem_en":"Which allocation practice best prevents cherry-picking?","options":["Allocate profitable fills after prices move.","Give favored clients the best executions regardless of order.","Set objective allocation rules before trade outcomes are known."],"correct":2,"why_vi":"Ghi thời điểm và lệnh, preallocate hoặc theo quy trình công bằng, average price khi phù hợp, review accounts, công bố policy và mức dịch vụ. Recommended; pro rata không phải quy tắc duy nhất.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"III(B)"},{"stem_en":"Which procedure best supports suitability for an advisory client?","options":["Collect and periodically update objectives, financial circumstances and constraints.","Use only the client's age to select investments.","Recommend products solely from their past returns."],"correct":0,"why_vi":"Lập IPS nêu risk/return, constraints, benchmark, trách nhiệm, xem xét beneficiaries; review khi có thay đổi và định kỳ, lưu xác nhận. Recommended written procedures; suitability và reassessment là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"III(C)"},{"stem_en":"What should a manager do first upon receiving an unsuitable unsolicited order?","options":["Execute immediately and update the IPS afterward.","Discuss why it conflicts with the client's stated objectives or constraints.","Automatically terminate every advisory relationship."],"correct":1,"why_vi":"Có policy documented discussion, portfolio impact assessment, client acknowledgment và separate account/IPS review nếu thích hợp. Recommended; không thực hiện mù quáng.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"III(C)"},{"stem_en":"Which procedure best reduces survivorship bias in a performance presentation?","options":["Remove any account that has closed.","Show only the highest-performing surviving account.","Retain terminated portfolios in historical results through their termination dates."],"correct":2,"why_vi":"Review composite inclusion, terminated account history, calculation and disclosures; lưu dữ liệu, xem xét sophistication của audience, cung cấp chi tiết theo yêu cầu; khuyến khích GIPS. Recommended; reasonable efforts là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"III(D)"},{"stem_en":"Which procedure best protects client confidentiality?","options":["Limit access to authorized personnel with a client-related need.","Give all employees access to client files.","Publish former clients' account details for marketing."],"correct":0,"why_vi":"Chỉ chia sẻ với người có thẩm quyền phục vụ client, kiểm tra người nhận, thiết lập lưu trữ an toàn, đào tạo, xử lý disclosure theo luật và policy. Recommended; confidentiality là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"III(E)"},{"stem_en":"Which policy best reduces conflicts when employees leave?","options":["Define acceptable preparations, client solicitation restrictions and return of firm records.","Allow employees to copy all records to private storage.","Ban all use of professional experience after departure."],"correct":0,"why_vi":"Có quy trình consent hoạt động cạnh tranh, bảo mật, bàn giao/thu hồi records, social media policy; tách tài khoản cá nhân và nghề nghiệp, cân bằng incentive. Recommended; consent trước hoạt động cạnh tranh là yêu cầu guidance.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"IV(A)"},{"stem_en":"Which action best supports compliance for a proposed outside performance bonus?","options":["Accept after oral approval and document it next year.","Obtain written consent from all involved parties before accepting.","Notify the employer only after payment."],"correct":1,"why_vi":"Báo cáo bằng văn bản nature, estimated value, conditions/duration và parties; xác minh terms từ bên đề nghị, lưu consent trước khi nhận. Recommended documentation; written consent từ all parties là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"IV(B)"},{"stem_en":"Which control best supports supervisory responsibilities?","options":["Rely solely on employee promises of compliance.","Written procedures, assigned authority, monitoring and corrective action.","Reward only sales volume regardless of conduct."],"correct":1,"why_vi":"Viết quy trình rõ ràng, phạm vi và authority compliance, checks and balances, permitted conduct, reporting, sanctions, training và review; tách code nguyên tắc khỏi thủ tục chi tiết, incentive không khuyến khích sai phạm. Recommended; reasonable efforts là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"IV(C)"},{"stem_en":"A supervisor receives credible evidence of misconduct. What is the most appropriate response?","options":["Accept the employee's denial and close the case.","Promptly investigate and restrict activity as warranted during the review.","Wait for a client complaint before monitoring."],"correct":1,"why_vi":"Điều tra, tăng supervision hoặc giới hạn hoạt động, ghi nhận escalation, cập nhật quy trình và đào tạo. Nếu hệ thống không đầy đủ, từ chối nhận responsibility bằng văn bản. Recommended procedure grounded in guidance; reasonable preventive/detective efforts required.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"IV(C)"},{"stem_en":"Which policy best supports reliance on external research?","options":["Periodically evaluate the provider's assumptions, rigor, timeliness and independence.","Accept any report from a recognized brand without review.","Use only reports agreeing with the firm's positions."],"correct":0,"why_vi":"Có chuẩn minimum research, documented basis, criteria chất lượng và review third-party sources định kỳ; incentive dựa trên chất lượng, không chỉ rating hay doanh thu. Recommended; adequate basis là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"V(A)"},{"stem_en":"Which procedure best addresses a complex quantitative model?","options":["Assume a successful backtest proves future reliability.","Test the model across relevant scenarios and examine input sensitivity.","Use the model without understanding its material limitations."],"correct":1,"why_vi":"Quy định scenario/sensitivity tests, validation của model, inputs và accuracy over time; đánh giá external manager theo criteria và lịch review. Recommended; tùy vai trò và sản phẩm.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"V(A)"},{"stem_en":"Which onboarding practice best supports V(B)?","options":["Mention only fees charged directly by the adviser.","Explain services and reasonably detailed costs, including applicable third-party charges.","Disclose costs only after the client terminates service."],"correct":1,"why_vi":"Kiểm tra tài liệu onboarding và prospect, phí trực tiếp/gián tiếp/third-party, thay đổi dịch vụ/cost; mẫu communication phải cập nhật, lưu bằng chứng. Recommended mechanism; disclosure obligations mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"V(B)"},{"stem_en":"Which procedure best addresses a major change to portfolio construction?","options":["Wait until the next annual report regardless of significance.","Communicate the change only to the model developers.","Notify affected clients promptly and explain material implications."],"correct":2,"why_vi":"Quy trình xác định significant risk/limitation, review report và phân biệt forecast/fact; thông báo kịp thời thay đổi material; lưu communication ở mọi kênh. Recommended; prompt disclosure of material process change required.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"V(B)"},{"stem_en":"In the absence of an applicable legal or firm retention period, what does CFA Institute recommend?","options":["Destroy records once a recommendation is published.","Retain only the latest recommendation for one year.","Retain records for at least seven years."],"correct":2,"why_vi":"Có lịch retention theo luật/policy, backup, access controls, lưu input/model và communications, bàn giao khi nghỉ; nếu không có quy định, dùng hướng dẫn 7 năm. Recommended; appropriate records là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"V(C)"},{"stem_en":"Which policy best implements VI(A)?","options":["Use a generic statement that conflicts may exist without describing material relationships.","Disclose only after a client proves actual bias.","Maintain a conflict register, seek avoidance and provide prominent understandable disclosures for remaining conflicts."],"correct":2,"why_vi":"Khai báo ownership, outside interests, compensation và issuer ties; review, avoid/recuse khi khả thi, disclosure prominent plain language và cập nhật thay đổi. Recommended mechanism; tránh hoặc full/fair disclosure là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"VI(A)"},{"stem_en":"Which procedure best helps prevent front-running?","options":["Permit personal orders first if employees pay higher commissions.","Require preclearance and review employee trades against pending client orders.","Review personal trades only when clients report losses."],"correct":1,"why_vi":"Disclose holdings/beneficial ownership, preclearance, blackout/restricted periods phù hợp, duplicate confirmations hoặc periodic statements; hạn chế IPO/private placements, review giao dịch và sanctions. Recommended controls; priority mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"VI(B)"},{"stem_en":"Which procedure best supports VI(C)?","options":["Require prior approval and timely disclosure of referral benefits with periodic employer updates.","Disclose only referral compensation paid in cash.","Wait until the client has signed before describing the arrangement."],"correct":0,"why_vi":"Khuyến khích firm cấm hoặc yêu cầu approval; thông báo client về approved programs, cập nhật employer thường xuyên (ít nhất quarterly được khuyến nghị) về amount và nature. Recommended; appropriate disclosure mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"VI(C)"},{"stem_en":"Which study-group rule best protects CFA Program integrity?","options":["Discuss curriculum concepts without sharing actual exam content or topics tested.","Collect recalled exam questions from recent candidates.","Ask volunteers for confidential scoring information."],"correct":0,"why_vi":"Đọc và tuân Candidate Pledge/testing policies, giới hạn quyền truy cập thông tin chương trình, không lưu/chia sẻ exam content; training và review cho volunteers. Đây là cách thực hành phòng ngừa dựa trên guidance, không phải danh mục riêng bắt buộc. Mandatory: integrity and confidentiality; control cụ thể là cách hỗ trợ.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"VII(A)"},{"stem_en":"Which procedure best reduces misuse of the designation?","options":["Permit an expected CFA completion date after employees' names.","Verify current status and review marketing references for accuracy.","Describe all exam passers as charterholders."],"correct":1,"why_vi":"Giải thích proper references cho HR/marketing, review CV, bios, business cards, websites, status changes; sửa claims về performance hoặc superiority. Recommended; không misrepresent là mandatory.","trap_vi":"Phân biệt mandatory standard với recommended control.","standard":"VII(B)"}],"cards":[{"front_en":"I(A) Knowledge of the Law — Keep the legal inventory current","back_vi":"Theo dõi thay đổi luật, lưu bản cập nhật, định kỳ rà soát chính sách; có kênh báo cáo vi phạm và hướng dẫn sản phẩm xuyên biên giới. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29] | Exam trap: Recommended procedures; nghĩa vụ tuân thủ và dissociate là bắt buộc."},{"front_en":"I(A) — Keep the legal inventory current — decision framework?","back_vi":"Theo dõi thay đổi luật, lưu bản cập nhật, định kỳ rà soát chính sách; có kênh báo cáo vi phạm và hướng dẫn sản phẩm xuyên biên giới. · Recommended procedures; nghĩa vụ tuân thủ và dissociate là bắt buộc. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"A firm distributes funds in three jurisdictions. Which control best supports compliance?","back_vi":"Maintain a current jurisdiction-specific rule inventory and review procedures. — Theo dõi thay đổi luật, lưu bản cập nhật, định kỳ rà soát chính sách; có kênh báo cáo vi phạm và hướng dẫn sản phẩm xuyên biên giới. Recommended procedures; nghĩa vụ tuân thủ và dissociate là bắt buộc. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"I(A) Knowledge of the Law — Escalate and document","back_vi":"Ghi nhận sự việc, trao đổi với supervisor/compliance, xin tư vấn pháp lý khi cần; nếu không sửa được, ngừng liên quan đến hành vi sai phạm. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29] | Exam trap: Documentation là recommended; không trì hoãn dissociation."},{"front_en":"I(A) — Escalate and document — decision framework?","back_vi":"Ghi nhận sự việc, trao đổi với supervisor/compliance, xin tư vấn pháp lý khi cần; nếu không sửa được, ngừng liên quan đến hành vi sai phạm. · Documentation là recommended; không trì hoãn dissociation. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"A compliance review confirms a continuing unlawful practice. Which procedure best supports the analyst's duties?","back_vi":"Document escalation and provide a mechanism to withdraw from the activity. — Ghi nhận sự việc, trao đổi với supervisor/compliance, xin tư vấn pháp lý khi cần; nếu không sửa được, ngừng liên quan đến hành vi sai phạm. Documentation là recommended; không trì hoãn dissociation. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"I(B) Independence and Objectivity — Protect research and gift policy","back_vi":"Tách research khỏi áp lực investment banking, restricted list nếu không thể công bố nhận định độc lập, giới hạn quà bên ngoài mức tượng trưng, có quy trình review và báo cáo. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41] | Exam trap: Recommended; độc lập và không nhận inducement là mandatory."},{"front_en":"I(B) — Protect research and gift policy — decision framework?","back_vi":"Tách research khỏi áp lực investment banking, restricted list nếu không thể công bố nhận định độc lập, giới hạn quà bên ngoài mức tượng trưng, có quy trình review và báo cáo. · Recommended; độc lập và không nhận inducement là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which policy best reduces pressure from an investment banking division?","back_vi":"Independent research review and a restricted list when objective coverage cannot be maintained. — Tách research khỏi áp lực investment banking, restricted list nếu không thể công bố nhận định độc lập, giới hạn quà bên ngoài mức tượng trưng, có quy trình review và báo cáo. Recommended; độc lập và không nhận inducement là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"I(B) Independence and Objectivity — Travel, IPO and placement controls","back_vi":"Tự trả chi phí đi lại khi thực tế cho phép; yêu cầu preclearance, hạn chế IPO/private placements, bổ nhiệm compliance officer có thẩm quyền. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41] | Exam trap: Recommended, không phải lệnh cấm tuyệt đối mọi chuyến đi."},{"front_en":"I(B) — Travel, IPO and placement controls — decision framework?","back_vi":"Tự trả chi phí đi lại khi thực tế cho phép; yêu cầu preclearance, hạn chế IPO/private placements, bổ nhiệm compliance officer có thẩm quyền. · Recommended, không phải lệnh cấm tuyệt đối mọi chuyến đi. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which procedure best addresses preferential allocations to employees?","back_vi":"Preclear and restrict employee IPO participation. — Tự trả chi phí đi lại khi thực tế cho phép; yêu cầu preclearance, hạn chế IPO/private placements, bổ nhiệm compliance officer có thẩm quyền. Recommended, không phải lệnh cấm tuyệt đối mọi chuyến đi. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"I(C) Misrepresentation — Verify marketing and credentials","back_vi":"Lập mô tả bằng văn bản về dịch vụ, năng lực và kinh nghiệm; kiểm tra định kỳ tài liệu, website, dữ liệu vendor và claims của bên thứ ba; sửa sai sớm. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49] | Exam trap: Recommended; cấm knowingly misrepresent là mandatory."},{"front_en":"I(C) — Verify marketing and credentials — decision framework?","back_vi":"Lập mô tả bằng văn bản về dịch vụ, năng lực và kinh nghiệm; kiểm tra định kỳ tài liệu, website, dữ liệu vendor và claims của bên thứ ba; sửa sai sớm. · Recommended; cấm knowingly misrepresent là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which review most directly reduces misleading marketing claims?","back_vi":"Verify credentials and third-party claims before publication. — Lập mô tả bằng văn bản về dịch vụ, năng lực và kinh nghiệm; kiểm tra định kỳ tài liệu, website, dữ liệu vendor và claims của bên thứ ba; sửa sai sớm. Recommended; cấm knowingly misrepresent là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"I(C) Misrepresentation — Attribution trail","back_vi":"Lưu báo cáo, ghi nguồn của bản tóm tắt, trích dẫn mô hình/biểu đồ và kiểm tra quyền sử dụng; lưu các bản sửa. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49] | Exam trap: Recommended; không đạo văn là mandatory."},{"front_en":"I(C) — Attribution trail — decision framework?","back_vi":"Lưu báo cáo, ghi nguồn của bản tóm tắt, trích dẫn mô hình/biểu đồ và kiểm tra quyền sử dụng; lưu các bản sửa. · Recommended; không đạo văn là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which procedure best prevents unattributed use of external models?","back_vi":"Maintain source records and require attribution in research. — Lưu báo cáo, ghi nguồn của bản tóm tắt, trích dẫn mô hình/biểu đồ và kiểm tra quyền sử dụng; lưu các bản sửa. Recommended; không đạo văn là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"I(D) Misconduct — Conduct and hiring controls","back_vi":"Khuyến nghị code of ethics, thông báo hành vi bị cấm và chế tài, kiểm tra references của ứng viên. [CFAI PDF pp. 101–103; Kaplan PDF pp. 172; SAPP PDF pp. 50–52] | Exam trap: Recommended; mục tiêu ngăn hành vi thiếu trung thực."},{"front_en":"I(D) — Conduct and hiring controls — decision framework?","back_vi":"Khuyến nghị code of ethics, thông báo hành vi bị cấm và chế tài, kiểm tra references của ứng viên. · Recommended; mục tiêu ngăn hành vi thiếu trung thực. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which control most directly supports I(D)?","back_vi":"Communicate sanctions for fraudulent conduct and check employment references. — Khuyến nghị code of ethics, thông báo hành vi bị cấm và chế tài, kiểm tra references của ứng viên. Recommended; mục tiêu ngăn hành vi thiếu trung thực. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"I(E) Competence — Role gap assessment","back_vi":"Đánh giá khoảng trống kỹ năng khi chuyển vị trí; lập kế hoạch tự học, đào tạo, mentoring, tham vấn chuyên gia; cập nhật kiến thức khi sản phẩm/quy định thay đổi. [CFAI PDF pp. 104–107; Kaplan PDF pp. 172; SAPP PDF pp. 53–54] | Exam trap: Recommended methods; duy trì năng lực là mandatory."},{"front_en":"I(E) — Role gap assessment — decision framework?","back_vi":"Đánh giá khoảng trống kỹ năng khi chuyển vị trí; lập kế hoạch tự học, đào tạo, mentoring, tham vấn chuyên gia; cập nhật kiến thức khi sản phẩm/quy định thay đổi. · Recommended methods; duy trì năng lực là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which action best prepares an equity analyst for a new credit-risk mandate?","back_vi":"Identify skill gaps and acquire relevant training and support before assuming unsupported duties. — Đánh giá khoảng trống kỹ năng khi chuyển vị trí; lập kế hoạch tự học, đào tạo, mentoring, tham vấn chuyên gia; cập nhật kiến thức khi sản phẩm/quy định thay đổi. Recommended methods; duy trì năng lực là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"II(A) Material Nonpublic Information — Information barriers","back_vi":"Thiết lập firewall giữa bộ phận, restricted/watch lists, kiểm soát luồng thông tin, review giao dịch cá nhân và proprietary; phân quyền, kiểm tra tài liệu và đào tạo. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61] | Exam trap: Recommended; không act/cause others to act là mandatory."},{"front_en":"II(A) — Information barriers — decision framework?","back_vi":"Thiết lập firewall giữa bộ phận, restricted/watch lists, kiểm soát luồng thông tin, review giao dịch cá nhân và proprietary; phân quyền, kiểm tra tài liệu và đào tạo. · Recommended; không act/cause others to act là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which control best reduces the risk of confidential deal information reaching traders?","back_vi":"Information barriers and monitored restricted lists. — Thiết lập firewall giữa bộ phận, restricted/watch lists, kiểm soát luồng thông tin, review giao dịch cá nhân và proprietary; phân quyền, kiểm tra tài liệu và đào tạo. Recommended; không act/cause others to act là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"II(A) Material Nonpublic Information — Public dissemination and mosaic records","back_vi":"Khuyến khích public disclosure; theo dõi thời điểm phổ biến, lưu nguồn và lý do của phân tích mosaic; compliance xem xét khi vô tình nhận MNPI. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61] | Exam trap: Recommended; không giao dịch trước khi thông tin public."},{"front_en":"II(A) — Public dissemination and mosaic records — decision framework?","back_vi":"Khuyến khích public disclosure; theo dõi thời điểm phổ biến, lưu nguồn và lý do của phân tích mosaic; compliance xem xét khi vô tình nhận MNPI. · Recommended; không giao dịch trước khi thông tin public. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"A company gives selected analysts a material update. Which procedure is most appropriate?","back_vi":"Seek broad public dissemination and restrict use until the information is public. — Khuyến khích public disclosure; theo dõi thời điểm phổ biến, lưu nguồn và lý do của phân tích mosaic; compliance xem xét khi vô tình nhận MNPI. Recommended; không giao dịch trước khi thông tin public. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"II(B) Market Manipulation — Trade and communication surveillance","back_vi":"Kiểm soát giao dịch đối ứng, bất thường cuối phiên, tin đồn và xung đột; lưu lý do kinh tế, review truyền thông và escalation. Đây là biện pháp thiết kế bổ trợ, không phải danh mục quy trình bắt buộc riêng của Standard. [CFAI PDF pp. 120–125; Kaplan PDF pp. 174–175; SAPP PDF pp. 62–66] | Exam trap: CFAI guidance: prohibitions và intent; control thực hành được suy ra từ mục tiêu phòng ngừa."},{"front_en":"II(B) — Trade and communication surveillance — decision framework?","back_vi":"Kiểm soát giao dịch đối ứng, bất thường cuối phiên, tin đồn và xung đột; lưu lý do kinh tế, review truyền thông và escalation. Đây là biện pháp thiết kế bổ trợ, không phải danh mục quy trình bắt buộc riêng của Standard. · CFAI guidance: prohibitions và intent; control thực hành được suy ra từ mục tiêu phòng ngừa. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which surveillance best targets transaction-based manipulation?","back_vi":"Review matched trades and unexplained end-of-session price changes. — Kiểm soát giao dịch đối ứng, bất thường cuối phiên, tin đồn và xung đột; lưu lý do kinh tế, review truyền thông và escalation. Đây là biện pháp thiết kế bổ trợ, không phải danh mục quy trình bắt buộc riêng của Standard. CFAI guidance: prohibitions và intent; control thực hành được suy ra từ mục tiêu phòng ngừa. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"III(A) Loyalty, Prudence, and Care — Client asset safeguards","back_vi":"Xác định client, mục tiêu, giới hạn, tài sản custody; phân tách tài sản và cung cấp statement định kỳ (quarterly được khuyến nghị khi kiểm soát tài sản), có chính sách vote proxy và rà soát brokerage. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77] | Exam trap: Recommended; nghĩa vụ client first là mandatory."},{"front_en":"III(A) — Client asset safeguards — decision framework?","back_vi":"Xác định client, mục tiêu, giới hạn, tài sản custody; phân tách tài sản và cung cấp statement định kỳ (quarterly được khuyến nghị khi kiểm soát tài sản), có chính sách vote proxy và rà soát brokerage. · Recommended; nghĩa vụ client first là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which procedure best protects client assets held by a manager?","back_vi":"Segregate client assets and provide regular account statements. — Xác định client, mục tiêu, giới hạn, tài sản custody; phân tách tài sản và cung cấp statement định kỳ (quarterly được khuyến nghị khi kiểm soát tài sản), có chính sách vote proxy và rà soát brokerage. Recommended; nghĩa vụ client first là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"III(A) Loyalty, Prudence, and Care — Best execution review","back_vi":"Đánh giá giá/chi phí/khả năng thực hiện, chất lượng dịch vụ, cách sử dụng brokerage; minh bạch directed brokerage và giới hạn execution. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77] | Exam trap: Recommended process."},{"front_en":"III(A) — Best execution review — decision framework?","back_vi":"Đánh giá giá/chi phí/khả năng thực hiện, chất lượng dịch vụ, cách sử dụng brokerage; minh bạch directed brokerage và giới hạn execution. · Recommended process. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which review best supports best execution?","back_vi":"Assess total execution quality, costs and client benefits. — Đánh giá giá/chi phí/khả năng thực hiện, chất lượng dịch vụ, cách sử dụng brokerage; minh bạch directed brokerage và giới hạn execution. Recommended process. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"III(B) Fair Dealing — Dissemination protocol","back_vi":"Giới hạn người biết trước, rút ngắn thời gian từ quyết định đến phổ biến, hướng dẫn giao tiếp, phát hành đồng thời khi khả thi, lưu thời điểm, thông báo service tiers. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85] | Exam trap: Recommended; fair treatment là mandatory."},{"front_en":"III(B) — Dissemination protocol — decision framework?","back_vi":"Giới hạn người biết trước, rút ngắn thời gian từ quyết định đến phổ biến, hướng dẫn giao tiếp, phát hành đồng thời khi khả thi, lưu thời điểm, thông báo service tiers. · Recommended; fair treatment là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which dissemination procedure best supports III(B)?","back_vi":"Release recommendation changes to eligible clients through a common process before individualized follow-up. — Giới hạn người biết trước, rút ngắn thời gian từ quyết định đến phổ biến, hướng dẫn giao tiếp, phát hành đồng thời khi khả thi, lưu thời điểm, thông báo service tiers. Recommended; fair treatment là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"III(B) Fair Dealing — Trade allocation policy","back_vi":"Ghi thời điểm và lệnh, preallocate hoặc theo quy trình công bằng, average price khi phù hợp, review accounts, công bố policy và mức dịch vụ. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85] | Exam trap: Recommended; pro rata không phải quy tắc duy nhất."},{"front_en":"III(B) — Trade allocation policy — decision framework?","back_vi":"Ghi thời điểm và lệnh, preallocate hoặc theo quy trình công bằng, average price khi phù hợp, review accounts, công bố policy và mức dịch vụ. · Recommended; pro rata không phải quy tắc duy nhất. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which allocation practice best prevents cherry-picking?","back_vi":"Set objective allocation rules before trade outcomes are known. — Ghi thời điểm và lệnh, preallocate hoặc theo quy trình công bằng, average price khi phù hợp, review accounts, công bố policy và mức dịch vụ. Recommended; pro rata không phải quy tắc duy nhất. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"III(C) Suitability — Written IPS and periodic review","back_vi":"Lập IPS nêu risk/return, constraints, benchmark, trách nhiệm, xem xét beneficiaries; review khi có thay đổi và định kỳ, lưu xác nhận. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95] | Exam trap: Recommended written procedures; suitability và reassessment là mandatory."},{"front_en":"III(C) — Written IPS and periodic review — decision framework?","back_vi":"Lập IPS nêu risk/return, constraints, benchmark, trách nhiệm, xem xét beneficiaries; review khi có thay đổi và định kỳ, lưu xác nhận. · Recommended written procedures; suitability và reassessment là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which procedure best supports suitability for an advisory client?","back_vi":"Collect and periodically update objectives, financial circumstances and constraints. — Lập IPS nêu risk/return, constraints, benchmark, trách nhiệm, xem xét beneficiaries; review khi có thay đổi và định kỳ, lưu xác nhận. Recommended written procedures; suitability và reassessment là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"III(C) Suitability — Unsuitable order escalation","back_vi":"Có policy documented discussion, portfolio impact assessment, client acknowledgment và separate account/IPS review nếu thích hợp. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95] | Exam trap: Recommended; không thực hiện mù quáng."},{"front_en":"III(C) — Unsuitable order escalation — decision framework?","back_vi":"Có policy documented discussion, portfolio impact assessment, client acknowledgment và separate account/IPS review nếu thích hợp. · Recommended; không thực hiện mù quáng. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"What should a manager do first upon receiving an unsuitable unsolicited order?","back_vi":"Discuss why it conflicts with the client's stated objectives or constraints. — Có policy documented discussion, portfolio impact assessment, client acknowledgment và separate account/IPS review nếu thích hợp. Recommended; không thực hiện mù quáng. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"III(D) Performance Presentation — Performance data governance","back_vi":"Review composite inclusion, terminated account history, calculation and disclosures; lưu dữ liệu, xem xét sophistication của audience, cung cấp chi tiết theo yêu cầu; khuyến khích GIPS. [CFAI PDF pp. 152–156; Kaplan PDF pp. 178–179; SAPP PDF pp. 96–99] | Exam trap: Recommended; reasonable efforts là mandatory."},{"front_en":"III(D) — Performance data governance — decision framework?","back_vi":"Review composite inclusion, terminated account history, calculation and disclosures; lưu dữ liệu, xem xét sophistication của audience, cung cấp chi tiết theo yêu cầu; khuyến khích GIPS. · Recommended; reasonable efforts là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which procedure best reduces survivorship bias in a performance presentation?","back_vi":"Retain terminated portfolios in historical results through their termination dates. — Review composite inclusion, terminated account history, calculation and disclosures; lưu dữ liệu, xem xét sophistication của audience, cung cấp chi tiết theo yêu cầu; khuyến khích GIPS. Recommended; reasonable efforts là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"III(E) Preservation of Confidentiality — Access and secure communication","back_vi":"Chỉ chia sẻ với người có thẩm quyền phục vụ client, kiểm tra người nhận, thiết lập lưu trữ an toàn, đào tạo, xử lý disclosure theo luật và policy. [CFAI PDF pp. 157–160; Kaplan PDF pp. 179; SAPP PDF pp. 100–104] | Exam trap: Recommended; confidentiality là mandatory."},{"front_en":"III(E) — Access and secure communication — decision framework?","back_vi":"Chỉ chia sẻ với người có thẩm quyền phục vụ client, kiểm tra người nhận, thiết lập lưu trữ an toàn, đào tạo, xử lý disclosure theo luật và policy. · Recommended; confidentiality là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which procedure best protects client confidentiality?","back_vi":"Limit access to authorized personnel with a client-related need. — Chỉ chia sẻ với người có thẩm quyền phục vụ client, kiểm tra người nhận, thiết lập lưu trữ an toàn, đào tạo, xử lý disclosure theo luật và policy. Recommended; confidentiality là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"IV(A) Loyalty — Outside activity and separation policy","back_vi":"Có quy trình consent hoạt động cạnh tranh, bảo mật, bàn giao/thu hồi records, social media policy; tách tài khoản cá nhân và nghề nghiệp, cân bằng incentive. [CFAI PDF pp. 161–171; Kaplan PDF pp. 180–181; SAPP PDF pp. 105–115] | Exam trap: Recommended; consent trước hoạt động cạnh tranh là yêu cầu guidance."},{"front_en":"IV(A) — Outside activity and separation policy — decision framework?","back_vi":"Có quy trình consent hoạt động cạnh tranh, bảo mật, bàn giao/thu hồi records, social media policy; tách tài khoản cá nhân và nghề nghiệp, cân bằng incentive. · Recommended; consent trước hoạt động cạnh tranh là yêu cầu guidance. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which policy best reduces conflicts when employees leave?","back_vi":"Define acceptable preparations, client solicitation restrictions and return of firm records. — Có quy trình consent hoạt động cạnh tranh, bảo mật, bàn giao/thu hồi records, social media policy; tách tài khoản cá nhân và nghề nghiệp, cân bằng incentive. Recommended; consent trước hoạt động cạnh tranh là yêu cầu guidance. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"IV(B) Additional Compensation Arrangements — Document proposed terms","back_vi":"Báo cáo bằng văn bản nature, estimated value, conditions/duration và parties; xác minh terms từ bên đề nghị, lưu consent trước khi nhận. [CFAI PDF pp. 172–173; Kaplan PDF pp. 181–182; SAPP PDF pp. 116–119] | Exam trap: Recommended documentation; written consent từ all parties là mandatory."},{"front_en":"IV(B) — Document proposed terms — decision framework?","back_vi":"Báo cáo bằng văn bản nature, estimated value, conditions/duration và parties; xác minh terms từ bên đề nghị, lưu consent trước khi nhận. · Recommended documentation; written consent từ all parties là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which action best supports compliance for a proposed outside performance bonus?","back_vi":"Obtain written consent from all involved parties before accepting. — Báo cáo bằng văn bản nature, estimated value, conditions/duration và parties; xác minh terms từ bên đề nghị, lưu consent trước khi nhận. Recommended documentation; written consent từ all parties là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"IV(C) Responsibilities of Supervisors — Compliance system design","back_vi":"Viết quy trình rõ ràng, phạm vi và authority compliance, checks and balances, permitted conduct, reporting, sanctions, training và review; tách code nguyên tắc khỏi thủ tục chi tiết, incentive không khuyến khích sai phạm. [CFAI PDF pp. 174–182; Kaplan PDF pp. 182–183; SAPP PDF pp. 120–127] | Exam trap: Recommended; reasonable efforts là mandatory."},{"front_en":"IV(C) — Compliance system design — decision framework?","back_vi":"Viết quy trình rõ ràng, phạm vi và authority compliance, checks and balances, permitted conduct, reporting, sanctions, training và review; tách code nguyên tắc khỏi thủ tục chi tiết, incentive không khuyến khích sai phạm. · Recommended; reasonable efforts là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which control best supports supervisory responsibilities?","back_vi":"Written procedures, assigned authority, monitoring and corrective action. — Viết quy trình rõ ràng, phạm vi và authority compliance, checks and balances, permitted conduct, reporting, sanctions, training và review; tách code nguyên tắc khỏi thủ tục chi tiết, incentive không khuyến khích sai phạm. Recommended; reasonable efforts là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"IV(C) Responsibilities of Supervisors — Respond to suspected breaches","back_vi":"Điều tra, tăng supervision hoặc giới hạn hoạt động, ghi nhận escalation, cập nhật quy trình và đào tạo. Nếu hệ thống không đầy đủ, từ chối nhận responsibility bằng văn bản. [CFAI PDF pp. 174–182; Kaplan PDF pp. 182–183; SAPP PDF pp. 120–127] | Exam trap: Recommended procedure grounded in guidance; reasonable preventive/detective efforts required."},{"front_en":"IV(C) — Respond to suspected breaches — decision framework?","back_vi":"Điều tra, tăng supervision hoặc giới hạn hoạt động, ghi nhận escalation, cập nhật quy trình và đào tạo. Nếu hệ thống không đầy đủ, từ chối nhận responsibility bằng văn bản. · Recommended procedure grounded in guidance; reasonable preventive/detective efforts required. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"A supervisor receives credible evidence of misconduct. What is the most appropriate response?","back_vi":"Promptly investigate and restrict activity as warranted during the review. — Điều tra, tăng supervision hoặc giới hạn hoạt động, ghi nhận escalation, cập nhật quy trình và đào tạo. Nếu hệ thống không đầy đủ, từ chối nhận responsibility bằng văn bản. Recommended procedure grounded in guidance; reasonable preventive/detective efforts required. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"V(A) Diligence and Reasonable Basis — Research quality assurance","back_vi":"Có chuẩn minimum research, documented basis, criteria chất lượng và review third-party sources định kỳ; incentive dựa trên chất lượng, không chỉ rating hay doanh thu. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136] | Exam trap: Recommended; adequate basis là mandatory."},{"front_en":"V(A) — Research quality assurance — decision framework?","back_vi":"Có chuẩn minimum research, documented basis, criteria chất lượng và review third-party sources định kỳ; incentive dựa trên chất lượng, không chỉ rating hay doanh thu. · Recommended; adequate basis là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which policy best supports reliance on external research?","back_vi":"Periodically evaluate the provider's assumptions, rigor, timeliness and independence. — Có chuẩn minimum research, documented basis, criteria chất lượng và review third-party sources định kỳ; incentive dựa trên chất lượng, không chỉ rating hay doanh thu. Recommended; adequate basis là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"V(A) Diligence and Reasonable Basis — Model and manager diligence","back_vi":"Quy định scenario/sensitivity tests, validation của model, inputs và accuracy over time; đánh giá external manager theo criteria và lịch review. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136] | Exam trap: Recommended; tùy vai trò và sản phẩm."},{"front_en":"V(A) — Model and manager diligence — decision framework?","back_vi":"Quy định scenario/sensitivity tests, validation của model, inputs và accuracy over time; đánh giá external manager theo criteria và lịch review. · Recommended; tùy vai trò và sản phẩm. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which procedure best addresses a complex quantitative model?","back_vi":"Test the model across relevant scenarios and examine input sensitivity. — Quy định scenario/sensitivity tests, validation của model, inputs và accuracy over time; đánh giá external manager theo criteria và lịch review. Recommended; tùy vai trò và sản phẩm. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"V(B) Communication with Clients and Prospective Clients — Service and cost disclosure review","back_vi":"Kiểm tra tài liệu onboarding và prospect, phí trực tiếp/gián tiếp/third-party, thay đổi dịch vụ/cost; mẫu communication phải cập nhật, lưu bằng chứng. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143] | Exam trap: Recommended mechanism; disclosure obligations mandatory."},{"front_en":"V(B) — Service and cost disclosure review — decision framework?","back_vi":"Kiểm tra tài liệu onboarding và prospect, phí trực tiếp/gián tiếp/third-party, thay đổi dịch vụ/cost; mẫu communication phải cập nhật, lưu bằng chứng. · Recommended mechanism; disclosure obligations mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which onboarding practice best supports V(B)?","back_vi":"Explain services and reasonably detailed costs, including applicable third-party charges. — Kiểm tra tài liệu onboarding và prospect, phí trực tiếp/gián tiếp/third-party, thay đổi dịch vụ/cost; mẫu communication phải cập nhật, lưu bằng chứng. Recommended mechanism; disclosure obligations mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"V(B) Communication with Clients and Prospective Clients — Material process change communication","back_vi":"Quy trình xác định significant risk/limitation, review report và phân biệt forecast/fact; thông báo kịp thời thay đổi material; lưu communication ở mọi kênh. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143] | Exam trap: Recommended; prompt disclosure of material process change required."},{"front_en":"V(B) — Material process change communication — decision framework?","back_vi":"Quy trình xác định significant risk/limitation, review report và phân biệt forecast/fact; thông báo kịp thời thay đổi material; lưu communication ở mọi kênh. · Recommended; prompt disclosure of material process change required. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which procedure best addresses a major change to portfolio construction?","back_vi":"Notify affected clients promptly and explain material implications. — Quy trình xác định significant risk/limitation, review report và phân biệt forecast/fact; thông báo kịp thời thay đổi material; lưu communication ở mọi kênh. Recommended; prompt disclosure of material process change required. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"V(C) Record Retention — Retention and access protocol","back_vi":"Có lịch retention theo luật/policy, backup, access controls, lưu input/model và communications, bàn giao khi nghỉ; nếu không có quy định, dùng hướng dẫn 7 năm. [CFAI PDF pp. 207–209; Kaplan PDF pp. 186; SAPP PDF pp. 144–148] | Exam trap: Recommended; appropriate records là mandatory."},{"front_en":"V(C) — Retention and access protocol — decision framework?","back_vi":"Có lịch retention theo luật/policy, backup, access controls, lưu input/model và communications, bàn giao khi nghỉ; nếu không có quy định, dùng hướng dẫn 7 năm. · Recommended; appropriate records là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"In the absence of an applicable legal or firm retention period, what does CFA Institute recommend?","back_vi":"Retain records for at least seven years. — Có lịch retention theo luật/policy, backup, access controls, lưu input/model và communications, bàn giao khi nghỉ; nếu không có quy định, dùng hướng dẫn 7 năm. Recommended; appropriate records là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"VI(A) Avoid or Disclose Conflicts — Conflict inventory and disclosure","back_vi":"Khai báo ownership, outside interests, compensation và issuer ties; review, avoid/recuse khi khả thi, disclosure prominent plain language và cập nhật thay đổi. [CFAI PDF pp. 210–214; Kaplan PDF pp. 187–188; SAPP PDF pp. 149–157] | Exam trap: Recommended mechanism; tránh hoặc full/fair disclosure là mandatory."},{"front_en":"VI(A) — Conflict inventory and disclosure — decision framework?","back_vi":"Khai báo ownership, outside interests, compensation và issuer ties; review, avoid/recuse khi khả thi, disclosure prominent plain language và cập nhật thay đổi. · Recommended mechanism; tránh hoặc full/fair disclosure là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which policy best implements VI(A)?","back_vi":"Maintain a conflict register, seek avoidance and provide prominent understandable disclosures for remaining conflicts. — Khai báo ownership, outside interests, compensation và issuer ties; review, avoid/recuse khi khả thi, disclosure prominent plain language và cập nhật thay đổi. Recommended mechanism; tránh hoặc full/fair disclosure là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"VI(B) Priority of Transactions — Personal trade controls","back_vi":"Disclose holdings/beneficial ownership, preclearance, blackout/restricted periods phù hợp, duplicate confirmations hoặc periodic statements; hạn chế IPO/private placements, review giao dịch và sanctions. [CFAI PDF pp. 215–220; Kaplan PDF pp. 188–189; SAPP PDF pp. 158–164] | Exam trap: Recommended controls; priority mandatory."},{"front_en":"VI(B) — Personal trade controls — decision framework?","back_vi":"Disclose holdings/beneficial ownership, preclearance, blackout/restricted periods phù hợp, duplicate confirmations hoặc periodic statements; hạn chế IPO/private placements, review giao dịch và sanctions. · Recommended controls; priority mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which procedure best helps prevent front-running?","back_vi":"Require preclearance and review employee trades against pending client orders. — Disclose holdings/beneficial ownership, preclearance, blackout/restricted periods phù hợp, duplicate confirmations hoặc periodic statements; hạn chế IPO/private placements, review giao dịch và sanctions. Recommended controls; priority mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"VI(C) Referral Fees — Referral program controls","back_vi":"Khuyến khích firm cấm hoặc yêu cầu approval; thông báo client về approved programs, cập nhật employer thường xuyên (ít nhất quarterly được khuyến nghị) về amount và nature. [CFAI PDF pp. 221–223; Kaplan PDF pp. 189; SAPP PDF pp. 165–168] | Exam trap: Recommended; appropriate disclosure mandatory."},{"front_en":"VI(C) — Referral program controls — decision framework?","back_vi":"Khuyến khích firm cấm hoặc yêu cầu approval; thông báo client về approved programs, cập nhật employer thường xuyên (ít nhất quarterly được khuyến nghị) về amount và nature. · Recommended; appropriate disclosure mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which procedure best supports VI(C)?","back_vi":"Require prior approval and timely disclosure of referral benefits with periodic employer updates. — Khuyến khích firm cấm hoặc yêu cầu approval; thông báo client về approved programs, cập nhật employer thường xuyên (ít nhất quarterly được khuyến nghị) về amount và nature. Recommended; appropriate disclosure mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"VII(A) Conduct as Participants in CFA Institute Programs — Program confidentiality controls","back_vi":"Đọc và tuân Candidate Pledge/testing policies, giới hạn quyền truy cập thông tin chương trình, không lưu/chia sẻ exam content; training và review cho volunteers. Đây là cách thực hành phòng ngừa dựa trên guidance, không phải danh mục riêng bắt buộc. [CFAI PDF pp. 224–229; Kaplan PDF pp. 189–190; SAPP PDF pp. 169–174] | Exam trap: Mandatory: integrity and confidentiality; control cụ thể là cách hỗ trợ."},{"front_en":"VII(A) — Program confidentiality controls — decision framework?","back_vi":"Đọc và tuân Candidate Pledge/testing policies, giới hạn quyền truy cập thông tin chương trình, không lưu/chia sẻ exam content; training và review cho volunteers. Đây là cách thực hành phòng ngừa dựa trên guidance, không phải danh mục riêng bắt buộc. · Mandatory: integrity and confidentiality; control cụ thể là cách hỗ trợ. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which study-group rule best protects CFA Program integrity?","back_vi":"Discuss curriculum concepts without sharing actual exam content or topics tested. — Đọc và tuân Candidate Pledge/testing policies, giới hạn quyền truy cập thông tin chương trình, không lưu/chia sẻ exam content; training và review cho volunteers. Đây là cách thực hành phòng ngừa dựa trên guidance, không phải danh mục riêng bắt buộc. Mandatory: integrity and confidentiality; control cụ thể là cách hỗ trợ. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program — Review references and marketing","back_vi":"Giải thích proper references cho HR/marketing, review CV, bios, business cards, websites, status changes; sửa claims về performance hoặc superiority. [CFAI PDF pp. 230–235; Kaplan PDF pp. 190–191; SAPP PDF pp. 175–183] | Exam trap: Recommended; không misrepresent là mandatory."},{"front_en":"VII(B) — Review references and marketing — decision framework?","back_vi":"Giải thích proper references cho HR/marketing, review CV, bios, business cards, websites, status changes; sửa claims về performance hoặc superiority. · Recommended; không misrepresent là mandatory. · Áp dụng theo facts và luật/policy thực tế; không suy diễn rằng mọi biện pháp recommended là nghĩa vụ bắt buộc."},{"front_en":"Which procedure best reduces misuse of the designation?","back_vi":"Verify current status and review marketing references for accuracy. — Giải thích proper references cho HR/marketing, review CV, bios, business cards, websites, status changes; sửa claims về performance hoặc superiority. Recommended; không misrepresent là mandatory. | Trap: Phân biệt mandatory standard với recommended control."},{"front_en":"I(A) — Prevention controls and compliance workflow","back_en":"Keep a jurisdiction-by-product register, update it for new communication channels, and record compliance advice, escalation and dissociation. A procedure assists compliance; it cannot replace action on a known violation.","back_vi":"Lập danh mục luật theo khu vực và sản phẩm; cập nhật kênh giao tiếp mới; lưu tư vấn, quá trình báo cáo và tách khỏi vi phạm. Quy trình không thay thế hành động khi đã biết vi phạm.","source_anchor":"CFAI Ethics 2026 physical PDF pp 67–76 (I(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"I(B) — Prevention controls and compliance workflow","back_en":"Separate research pay from banking or sales outcomes; record third-party benefits, use a restricted list where necessary, and document why exceptional travel is necessary and proportionate.","back_vi":"Tách thu nhập nghiên cứu khỏi kết quả bán hàng/ngân hàng đầu tư; ghi lợi ích bên thứ ba, dùng restricted list khi cần và ghi lý do chuyến đi ngoại lệ cần thiết, hợp lý.","source_anchor":"CFAI Ethics 2026 physical PDF pp 76–90 (I(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"I(C) — Prevention controls and compliance workflow","back_en":"Maintain source files and an attribution register, verify public credentials and performance claims, use consistent pricing policies, and keep a correction log with the recipients notified.","back_vi":"Lưu tài liệu và danh mục nguồn, kiểm tra bằng cấp/thành tích công bố, dùng chính sách định giá nhất quán và sổ đính chính ghi người nhận.","source_anchor":"CFAI Ethics 2026 physical PDF pp 90–101 (I(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"I(D) — Prevention controls and compliance workflow","back_en":"Adopt a conduct policy, document concerns with evidence rather than rumors, and use appropriate escalation channels. Training should distinguish professional-integrity issues from unrelated personal conduct.","back_vi":"Có chính sách ứng xử, ghi nhận vấn đề bằng chứng cứ thay vì tin đồn, dùng kênh báo cáo phù hợp. Đào tạo phân biệt vấn đề liêm chính nghề với hành vi cá nhân không liên quan.","source_anchor":"CFAI Ethics 2026 physical PDF pp 101–104 (I(D)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"I(E) — Prevention controls and compliance workflow","back_en":"Map duties to skills, assess gaps at role transitions, arrange targeted training and oversight, and reassess capability as products or methods change.","back_vi":"Ánh xạ nhiệm vụ với kỹ năng, đánh giá thiếu hụt khi đổi vai trò, đào tạo/giám sát có trọng tâm và đánh giá lại khi sản phẩm hoặc phương pháp đổi.","source_anchor":"CFAI Ethics 2026 physical PDF pp 104–109 (I(E)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"II(A) — Prevention controls and compliance workflow","back_en":"Use information barriers, restricted/watch lists, controlled access, public-release checks and contemporaneous mosaic research notes. Escalate uncertain information status before trading.","back_vi":"Dùng tường thông tin, danh sách hạn chế/theo dõi, kiểm soát truy cập, kiểm tra công bố và ghi nghiên cứu mosaic đồng thời. Hỏi compliance trước khi giao dịch nếu chưa rõ tình trạng thông tin.","source_anchor":"CFAI Ethics 2026 physical PDF pp 109–120 (II(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"II(B) — Prevention controls and compliance workflow","back_en":"Review unusual order patterns and public claims, retain execution rationale and investigate evidence of misleading intent rather than treating all price impact as misconduct.","back_vi":"Rà soát mẫu lệnh bất thường và thông tin công bố, lưu lý do giao dịch và điều tra dấu hiệu ý định đánh lừa thay vì coi mọi tác động giá là sai.","source_anchor":"CFAI Ethics 2026 physical PDF pp 120–124 (II(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"III(A) — Prevention controls and compliance workflow","back_en":"Review brokerage quality and costs, document client-directed instructions and conflicts, maintain custody controls, and review proxy decisions in beneficiaries' interests.","back_vi":"Rà chất lượng/chi phí broker, ghi chỉ dẫn và xung đột, kiểm soát lưu ký, rà quyết định proxy theo lợi ích người thụ hưởng.","source_anchor":"CFAI Ethics 2026 physical PDF pp 125–135 (III(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"III(B) — Prevention controls and compliance workflow","back_en":"Use timed dissemination, a documented allocation policy, pre-trade order records and periodic exception reviews; disclose service differences.","back_vi":"Dùng công bố theo thời điểm, chính sách phân bổ, ghi lệnh trước giao dịch và rà ngoại lệ; công bố khác biệt dịch vụ.","source_anchor":"CFAI Ethics 2026 physical PDF pp 135–144 (III(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"III(C) — Prevention controls and compliance workflow","back_en":"Maintain current IPS records, document material changes and the suitability assessment for the whole portfolio, and define an escalation path for unsolicited unsuitable requests.","back_vi":"Duy trì IPS cập nhật, ghi thay đổi trọng yếu và đánh giá phù hợp toàn danh mục, quy định kênh xử lý lệnh không phù hợp do khách chủ động.","source_anchor":"CFAI Ethics 2026 physical PDF pp 144–152 (III(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"III(D) — Prevention controls and compliance workflow","back_en":"Retain supporting performance data and composite rules, label simulations and material fees, and independently reconcile marketing figures to the source records.","back_vi":"Lưu dữ liệu hiệu suất và quy tắc composite, ghi nhãn mô phỏng/phí trọng yếu, đối chiếu số marketing với hồ sơ nguồn.","source_anchor":"CFAI Ethics 2026 physical PDF pp 152–157 (III(D)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"III(E) — Prevention controls and compliance workflow","back_en":"Limit access by role, use secure communications, obtain and retain permissions, and consult compliance/legal before unusual disclosure.","back_vi":"Giới hạn truy cập theo vai trò, dùng giao tiếp an toàn, lưu chấp thuận, hỏi compliance/legal trước công bố bất thường.","source_anchor":"CFAI Ethics 2026 physical PDF pp 157–162 (III(E)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"IV(A) — Prevention controls and compliance workflow","back_en":"Clarify outside activity and departure policies, document permissions, control record removal and use secure reporting channels for serious misconduct.","back_vi":"Làm rõ chính sách việc ngoài/ nghỉ việc, lưu chấp thuận, kiểm soát lấy hồ sơ, dùng kênh báo cáo an toàn cho sai phạm nghiêm trọng.","source_anchor":"CFAI Ethics 2026 physical PDF pp 162–172 (IV(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"IV(B) — Prevention controls and compliance workflow","back_en":"Record terms, nature, amount and duration of proposed outside compensation, obtain written consent before acceptance, and reassess if terms change.","back_vi":"Ghi điều khoản, bản chất, số tiền và thời hạn thù lao ngoài, lấy chấp thuận văn bản trước khi nhận, đánh giá lại khi đổi điều khoản.","source_anchor":"CFAI Ethics 2026 physical PDF pp 172–175 (IV(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"IV(C) — Prevention controls and compliance workflow","back_en":"Maintain written preventive/detective controls, assign authority, train staff, test compliance, record investigations and restrict suspect activities while investigating.","back_vi":"Duy trì kiểm soát phòng ngừa/phát hiện bằng văn bản, phân quyền, đào tạo, kiểm tra tuân thủ, ghi điều tra và hạn chế hoạt động nghi vấn trong khi điều tra.","source_anchor":"CFAI Ethics 2026 physical PDF pp 174–183 (IV(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"V(A) — Prevention controls and compliance workflow","back_en":"Require model validation, research-provider review, periodic reassessment and documentation of major assumptions, stress tests and dissent when appropriate.","back_vi":"Yêu cầu kiểm định mô hình, rà nhà cung cấp nghiên cứu, đánh giá định kỳ và ghi giả định lớn, stress test, ý kiến khác khi phù hợp.","source_anchor":"CFAI Ethics 2026 physical PDF pp 183–195 (V(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"V(B) — Prevention controls and compliance workflow","back_en":"Maintain client-facing fee and service disclosures, a process-change notification log, review communications for material risks, and mark estimates clearly as opinions.","back_vi":"Duy trì công bố phí/dịch vụ, sổ thông báo đổi quy trình, rà rủi ro trọng yếu trong thông tin và ghi rõ ước tính là ý kiến.","source_anchor":"CFAI Ethics 2026 physical PDF pp 195–207 (V(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"V(C) — Prevention controls and compliance workflow","back_en":"Archive material messages, source data, models and decision notes under documented retention rules; test recoverability and record permission for any transfer.","back_vi":"Lưu tin nhắn trọng yếu, dữ liệu nguồn, mô hình, ghi chú quyết định theo quy tắc lưu; kiểm tra khả năng phục hồi và lưu chấp thuận chuyển hồ sơ.","source_anchor":"CFAI Ethics 2026 physical PDF pp 207–210 (V(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"VI(A) — Prevention controls and compliance workflow","back_en":"Maintain a conflict register, evaluate avoidance or reassignment, disclose material relationships in plain language and monitor changes to beneficial ownership and compensation.","back_vi":"Duy trì sổ xung đột, xét tránh hoặc chuyển nhiệm vụ, công bố quan hệ trọng yếu rõ ràng, theo dõi thay đổi sở hữu hưởng lợi và thù lao.","source_anchor":"CFAI Ethics 2026 physical PDF pp 210–215 (VI(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"VI(B) — Prevention controls and compliance workflow","back_en":"Use preclearance, blackout periods where appropriate, beneficial-interest declarations, account monitoring and fair allocation checks.","back_vi":"Dùng preclearance, blackout phù hợp, khai lợi ích sở hữu, theo dõi tài khoản và kiểm tra phân bổ công bằng.","source_anchor":"CFAI Ethics 2026 physical PDF pp 215–221 (VI(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"VI(C) — Prevention controls and compliance workflow","back_en":"Track paid and received referrals, including noncash benefits, obtain required firm approvals and disclose terms before the relevant client agreement.","back_vi":"Theo dõi giới thiệu nhận/trả kể cả lợi ích phi tiền, lấy phê duyệt firm cần thiết và công bố trước thỏa thuận khách liên quan.","source_anchor":"CFAI Ethics 2026 physical PDF pp 221–224 (VI(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"VII(A) — Prevention controls and compliance workflow","back_en":"Review candidate rules and volunteer confidentiality obligations, separate public information from protected material, and avoid sharing reconstructed exam content.","back_vi":"Đọc quy định ứng viên và bảo mật tình nguyện viên, tách thông tin công khai khỏi tài liệu mật, tránh chia sẻ nội dung thi tái dựng.","source_anchor":"CFAI Ethics 2026 physical PDF pp 224–230 (VII(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"VII(B) — Prevention controls and compliance workflow","back_en":"Review biographies and marketing for active status, correct use of marks, accurate factual achievements and absence of performance guarantees; correct obsolete claims promptly.","back_vi":"Rà bio/marketing về trạng thái active, dùng nhãn đúng, thành tích factual và không bảo đảm hiệu suất; sửa tuyên bố lỗi thời kịp thời.","source_anchor":"CFAI Ethics 2026 physical PDF pp 230–235 (VII(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"}]},{"id":"CFA26-10-03-LOS03","letter":"c","title_en":"Identify Compliant and Violating Conduct","outcome_en":"identify conduct that conforms to the Code and Standards and conduct that violates the Code and Standards","overview_vi":"Luyện nhận diện conforming/violating conduct theo facts, gồm các tình huống giao thoa nhiều Standards; không suy luận vi phạm từ kết quả đầu tư hoặc suy đoán thiếu dữ kiện. V7.4: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF p. 67 (LOS); pp. 67–235 (Guidance, procedures and applications); pp. 236–254 practice/solutions range (not reproduced)"},{"id":"Kaplan SchweserNotes 2026 — Book 4 Reading 91","pages":"Physical PDF pp. 167–194"},{"id":"SAPP CFA Level I 2026 — Ethics slides Module 3","pages":"Physical PDF pp. 23–185; topic cases pp. 186–199 (not reproduced)"}],"sections":[{"heading":"I(A) Knowledge of the Law — recognition test","body":"Điểm quyết định trong tình huống: Luật áp dụng yêu cầu báo cáo; dissociation không thay thế nghĩa vụ pháp lý. Standards không tự đặt nghĩa vụ báo cáo phổ quát nhưng không thể dùng điều đó để vi phạm luật. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29]","trap":"I(A): nghĩa vụ tuân thủ và dissociation có thể đồng thời."},{"heading":"I(B) Independence and Objectivity — recognition test","body":"Điểm quyết định trong tình huống: Cơ chế trả thưởng tạo incentive làm lệch independence/objectivity. Tách compensation là phương án phòng ngừa trực tiếp; disclosure không tự loại nguy cơ. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41]","trap":"I(B) và VI(A) có thể cùng liên quan; không chỉ conflict disclosure."},{"heading":"I(C) Misrepresentation — recognition test","body":"Điểm quyết định trong tình huống: Benchmark được chọn có chủ đích làm hiểu sai relative performance; accuracy của phép tính không đủ. I(C) và III(D) đều có thể áp dụng. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49]","trap":"Một facts pattern có thể vi phạm nhiều Standards."},{"heading":"I(D) Misconduct — recognition test","body":"Điểm quyết định trong tình huống: Thông tin nghề nghiệp sai có chủ đích vừa là misrepresentation vừa là dishonest professional conduct. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 101–103; Kaplan PDF pp. 172; SAPP PDF pp. 50–52]","trap":"Không chỉ Standard về misrepresentation khi có deception."},{"heading":"I(E) Competence — recognition test","body":"Điểm quyết định trong tình huống: Competence cần phù hợp nhiệm vụ; nhận vai trò mới không tự vi phạm khi chủ động bổ sung năng lực trước khi thực hiện. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 104–107; Kaplan PDF pp. 172; SAPP PDF pp. 53–54]","trap":"Continuing education và professional designation là phương thức, không phải yêu cầu cụ thể duy nhất."},{"heading":"II(A) Material Nonpublic Information — recognition test","body":"Điểm quyết định trong tình huống: Cấm hành động dựa MNPI bất kể lợi ích cho ai. Hạn chế chứng khoán và trao đổi compliance hỗ trợ phòng ngừa. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61]","trap":"Disclosure nguồn tin không biến MNPI thành public."},{"heading":"II(B) Market Manipulation — recognition test","body":"Điểm quyết định trong tình huống: Intent to mislead là dấu hiệu trọng tâm của market manipulation; forecast sai hoặc tác động giá không đủ. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 120–125; Kaplan PDF pp. 174–175; SAPP PDF pp. 62–66]","trap":"Xét V(A) nếu basis thiếu, nhưng không tự suy ra II(B)."},{"heading":"III(A) Loyalty, Prudence, and Care — recognition test","body":"Điểm quyết định trong tình huống: Guidance cho phép client-directed brokerage có disclosure về hạn chế. Client commission vẫn phải phục vụ quyền lợi client. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77]","trap":"Client instruction không cho phép misuse of assets."},{"heading":"III(B) Fair Dealing — recognition test","body":"Điểm quyết định trong tình huống: Differentiated service được phép nếu không gây bất lợi cho khách khác; preferential advance dissemination làm vi phạm fairness. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85]","trap":"Phân biệt extra detail sau release với thông tin trọng yếu trước release."},{"heading":"III(C) Suitability — recognition test","body":"Điểm quyết định trong tình huống: Tác động material cần xử lý phù hợp; separate account có thể là lựa chọn sau discussion. Không tự ý sửa IPS hoặc thực hiện trong portfolio trái mandate. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95]","trap":"Xét mức độ material và firm policy."},{"heading":"III(D) Performance Presentation — recognition test","body":"Điểm quyết định trong tình huống: Brief presentation có thể hợp lệ nếu minh bạch giới hạn và có chi tiết khi yêu cầu; không cherry-pick. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 152–156; Kaplan PDF pp. 178–179; SAPP PDF pp. 96–99]","trap":"Brevity không phải ngoại lệ cho fairness."},{"heading":"III(E) Preservation of Confidentiality — recognition test","body":"Điểm quyết định trong tình huống: Client permission là ngoại lệ; phải giới hạn phạm vi. Prospective client thuộc confidentiality ngay cả chưa ký hợp đồng. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 157–160; Kaplan PDF pp. 179; SAPP PDF pp. 100–104]","trap":"Xem nội dung và phạm vi authorization."},{"heading":"IV(A) Loyalty — recognition test","body":"Điểm quyết định trong tình huống: Sau khi nghỉ có thể dùng general skills và public information nếu không có ràng buộc khác. Không lấy confidential client list. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 161–171; Kaplan PDF pp. 180–181; SAPP PDF pp. 105–115]","trap":"Phân biệt employer records và general knowledge."},{"heading":"IV(B) Additional Compensation Arrangements — recognition test","body":"Điểm quyết định trong tình huống: Prospective incentive là additional compensation có conflict; written consent trước acceptance. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 172–173; Kaplan PDF pp. 181–182; SAPP PDF pp. 116–119]","trap":"I(B) past-service gifts không đồng nghĩa IV(B) arrangements."},{"heading":"IV(C) Responsibilities of Supervisors — recognition test","body":"Điểm quyết định trong tình huống: Không có hệ thống đầy đủ và đã từ chối sửa, guidance yêu cầu decline in writing; tiền phạt không thay duties. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 174–182; Kaplan PDF pp. 182–183; SAPP PDF pp. 120–127]","trap":"Reasonable efforts bao gồm điều kiện để giám sát hiệu quả."},{"heading":"V(A) Diligence and Reasonable Basis — recognition test","body":"Điểm quyết định trong tình huống: V(A) cần adequate basis trước recommendation; disclosure risk V(B) không thay due diligence. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136]","trap":"Research basis và communication là hai nghĩa vụ độc lập."},{"heading":"V(B) Communication with Clients and Prospective Clients — recognition test","body":"Điểm quyết định trong tình huống: Nature và cost phải đủ chi tiết, không nhất thiết số tiền chính xác chưa thể biết; phí third party cần đưa vào khi liên quan. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143]","trap":"Không dùng uncertainty để bỏ disclosure."},{"heading":"V(C) Record Retention — recognition test","body":"Điểm quyết định trong tình huống: 7 năm là khuyến nghị khi không có luật/firm policy; áp dụng policy 10 năm đã nêu. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 207–209; Kaplan PDF pp. 186; SAPP PDF pp. 144–148]","trap":"Không coi recommendation là maximum hoặc universal rule."},{"heading":"VI(A) Avoid or Disclose Conflicts — recognition test","body":"Điểm quyết định trong tình huống: Xung đột gia đình có thể ảnh hưởng objective selection; avoid/disclose trước quyết định, quản lý bằng safeguards. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 210–214; Kaplan PDF pp. 187–188; SAPP PDF pp. 149–157]","trap":"Disclosure phải đến đúng bên liên quan và không miễn I(B)."},{"heading":"VI(B) Priority of Transactions — recognition test","body":"Điểm quyết định trong tình huống: Beneficial ownership quan trọng hơn tên đăng ký account; ưu tiên client/employer. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 215–220; Kaplan PDF pp. 188–189; SAPP PDF pp. 158–164]","trap":"Khác với family account client thật không có beneficial interest của member."},{"heading":"VI(C) Referral Fees — recognition test","body":"Điểm quyết định trong tình huống: VI(C) gồm both received and paid benefits; timing trước formal agreement. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 221–223; Kaplan PDF pp. 189; SAPP PDF pp. 165–168]","trap":"Không bỏ qua khoản đã trả cho người giới thiệu."},{"heading":"VII(A) Conduct as Participants in CFA Institute Programs — recognition test","body":"Điểm quyết định trong tình huống: Soliciting/sharing confidential exam content gồm topics not covered, không chỉ actual questions. Dùng curriculum công khai để luyện. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 224–229; Kaplan PDF pp. 189–190; SAPP PDF pp. 169–174]","trap":"Không dùng study purpose làm ngoại lệ."},{"heading":"VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program — recognition test","body":"Điểm quyết định trong tình huống: Có thể nêu sự kiện pass exams chính xác; không dùng designation/expected charter khi chưa được cấp quyền. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 230–235; Kaplan PDF pp. 190–191; SAPP PDF pp. 175–183]","trap":"Passing exams không phải charter."},{"heading":"Recognition: duty, decisive facts, exceptions and evidence","body":"Trước hết xác định quan hệ thực và nghĩa vụ áp dụng. Tách facts đủ chứng minh vi phạm khỏi facts chỉ gợi ý rủi ro. Kiểm từng chuẩn liên quan riêng và xét ngoại lệ có căn cứ. Một hành động có thể đúng chuẩn này nhưng sai chuẩn khác; kết quả xấu riêng lẻ không quyết định.","body_en":"First identify the actual relationship and applicable duty. Separate facts that establish a violation from facts that merely suggest risk. Test each relevant standard independently, and check whether an exception is supported by the facts. An action can comply with one standard and violate another; a bad outcome alone is not decisive.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 pp 67–235, practice pp 236–254","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"}],"formulas":[{"name":"Gift vs additional compensation","expr":"Past voluntary gift → I(B) disclosure; prospective conflicting bonus → IV(B) written consent","meaning":"Kiểm tra thời điểm và điều kiện thưởng, không chỉ tên gọi.","conditions":"I(B) vẫn cấm benefit có thể impair objectivity; consent không cứu hành vi cấm."},{"name":"Fair dealing vs suitability vs priority","expr":"Eligible and suitable? → fair dissemination/allocation? → beneficial ownership priority?","meaning":"III(B), III(C), VI(B) có thể đồng thời áp dụng.","conditions":"Không đánh đồng fair với equal hoặc family account với personal account."},{"name":"Research vs communication vs records","expr":"Reasonable basis? → material facts/risks/costs disclosed? → supporting records retained?","meaning":"Ba nghĩa vụ V(A), V(B), V(C) độc lập.","conditions":"Good performance không thay thế một trong ba."},{"name":"Law, disclosure and dissociation","expr":"Check applicable law → stricter requirements → stop knowing assistance → report if required","meaning":"Phân biệt I(A), báo cáo nội bộ và external reporting.","conditions":"Không suy ra reporting mandatory nếu luật không yêu cầu; vẫn phải dissociate."},{"name":"Compliance vs violation","expr":"Read stated facts → identify duty/exception → test required action → choose most supported conclusion","meaning":"Không thêm facts ngoài đề; phân biệt best next step với finding of violation.","conditions":"Không tự kết luận misconduct, manipulation hoặc incompetence từ kết quả xấu."}],"examples":[{"question_en":"A compliance officer refuses to correct a misleading sales brochure. A salesperson stops distributing it, documents the issue, and performs only unrelated lawful work. No law requires external reporting.","steps_vi":["Xác định chuẩn liên quan: I(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Đã tách khỏi hoạt động sai; nghỉ việc không phải bước mặc định nếu có thể tách hiệu quả. Báo cáo ngoài công ty không mặc nhiên bắt buộc."],"answer":"Her response is consistent with I(A).","check":"Original case; conclusion limited to facts stated."},{"question_en":"An analyst learns that colleagues are knowingly misallocating trades. He emails a protest but continues preparing the allocation sheets.","steps_vi":["Xác định chuẩn liên quan: I(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Biết vi phạm mà vẫn cung cấp hỗ trợ có ý nghĩa; cần chấm dứt sự liên quan."],"answer":"He violates I(A) by continuing to assist.","check":"Original case; conclusion limited to facts stated."},{"question_en":"An analyst works in a jurisdiction requiring public reporting of a specified securities violation. The firm asks her to withdraw from the activity but not file the legally required report. What is her most appropriate response?","steps_vi":["Xác định chuẩn liên quan: I(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Luật áp dụng yêu cầu báo cáo; dissociation không thay thế nghĩa vụ pháp lý. Standards không tự đặt nghĩa vụ báo cáo phổ quát nhưng không thể dùng điều đó để vi phạm luật."],"answer":"Withdraw and comply with the applicable reporting law.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A broker offers a portfolio manager an expensive family vacation if the manager directs client trades to the broker. The manager accepts but intends to maintain prior routing.","steps_vi":["Xác định chuẩn liên quan: I(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Lợi ích có khả năng hợp lý gây ảnh hưởng; ý định chủ quan và disclosure sau không loại bỏ vấn đề."],"answer":"Violation of I(B)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A satisfied client offers a modest gift for past service. The manager informs the employer before accepting and continues objective treatment of all accounts.","steps_vi":["Xác định chuẩn liên quan: I(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Quà ghi nhận quá khứ khác thỏa thuận trả thưởng tương lai; xét khách quan và thông báo employer."],"answer":"The conduct can comply with I(B).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A research analyst's bonus depends directly on securing investment banking mandates from the companies she rates. What is the most appropriate preventive change?","steps_vi":["Xác định chuẩn liên quan: I(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Cơ chế trả thưởng tạo incentive làm lệch independence/objectivity. Tách compensation là phương án phòng ngừa trực tiếp; disclosure không tự loại nguy cơ."],"answer":"Separate research compensation from the banking mandates of covered companies.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A researcher rewrites a consultant's proprietary valuation framework in her own words and publishes it as her own invention.","steps_vi":["Xác định chuẩn liên quan: I(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Ý tưởng/mô hình của người khác cần attribution; paraphrase không miễn nghĩa vụ."],"answer":"Violation of I(C)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A firm continues using a model created by a former employee. A new analyst describes it as the firm's model and accurately explains its limitations.","steps_vi":["Xác định chuẩn liên quan: I(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Firm có thể tiếp tục dùng sản phẩm thuộc sở hữu mình; analyst không nhận sai công lao."],"answer":"The conduct can comply with I(C).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A fund's marketing team replaces a relevant benchmark with a low-return unrelated index specifically to make the fund appear superior. All reported returns are arithmetically correct. Which conclusion is most appropriate?","steps_vi":["Xác định chuẩn liên quan: I(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Benchmark được chọn có chủ đích làm hiểu sai relative performance; accuracy của phép tính không đủ. I(C) và III(D) đều có thể áp dụng."],"answer":"The presentation is misleading and may violate both I(C) and III(D).","check":"Original case; conclusion limited to facts stated."},{"question_en":"Two analysts publicly disagree about a lawful political policy. Neither makes a false statement nor engages in conduct reflecting adversely on professional integrity.","steps_vi":["Xác định chuẩn liên quan: I(D). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Không biến Standards thành công cụ giải quyết tranh chấp chính trị/cá nhân; dữ kiện không chứng minh liên hệ bất lợi."],"answer":"The facts do not establish a violation of I(D).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A candidate intentionally falsifies professional qualifications in a job application. Which pair of Standards is most directly implicated?","steps_vi":["Xác định chuẩn liên quan: I(D). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Thông tin nghề nghiệp sai có chủ đích vừa là misrepresentation vừa là dishonest professional conduct."],"answer":"I(C) Misrepresentation and I(D) Misconduct","check":"Original case; conclusion limited to facts stated."},{"question_en":"A competent analyst performs appropriate research and risk analysis, but an unexpected event produces a loss.","steps_vi":["Xác định chuẩn liên quan: I(E). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Năng lực là khả năng/quy trình, không bảo đảm mọi kết quả."],"answer":"The loss alone does not establish an I(E) violation.","check":"Original case; conclusion limited to facts stated."},{"question_en":"An employer changes its mandate from domestic equities to global derivatives. The manager recognizes gaps, arranges specialized support, and completes appropriate training before taking new responsibilities. Which conclusion is best?","steps_vi":["Xác định chuẩn liên quan: I(E). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Competence cần phù hợp nhiệm vụ; nhận vai trò mới không tự vi phạm khi chủ động bổ sung năng lực trước khi thực hiện."],"answer":"The steps support compliance with I(E).","check":"Original case; conclusion limited to facts stated."},{"question_en":"An analyst combines public shipment statistics with nonmaterial observations from store visits and independently concludes demand is falling. She trades on the conclusion.","steps_vi":["Xác định chuẩn liên quan: II(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Public + nonmaterial nonpublic có thể tạo kết luận material; không có MNPI trong dữ kiện."],"answer":"Consistent with mosaic theory.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A private call gives selected fund managers an unreleased material earnings revision. One manager trades immediately because several competitors heard it.","steps_vi":["Xác định chuẩn liên quan: II(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Thông tin chưa phổ biến ra marketplace; số người tham dự không đủ."],"answer":"Violation of II(A)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A consultant offers an analyst confidential, material merger terms. The analyst declines to use them and asks compliance to restrict the securities concerned. What is the best assessment?","steps_vi":["Xác định chuẩn liên quan: II(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Cấm hành động dựa MNPI bất kể lợi ích cho ai. Hạn chế chứng khoán và trao đổi compliance hỗ trợ phòng ngừa."],"answer":"The response is consistent with II(A).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A pension manager sells a large position to meet documented benefit payments. The sale depresses the market price.","steps_vi":["Xác định chuẩn liên quan: II(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Nhu cầu thanh khoản thật, không có intent gây hiểu nhầm trong dữ kiện."],"answer":"The price impact alone does not establish manipulation.","check":"Original case; conclusion limited to facts stated."},{"question_en":"An analyst publishes a good-faith earnings estimate based on documented research. The estimate proves incorrect and causes a temporary price decline. Which fact is most important when assessing II(B)?","steps_vi":["Xác định chuẩn liên quan: II(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Intent to mislead là dấu hiệu trọng tâm của market manipulation; forecast sai hoặc tác động giá không đủ."],"answer":"Whether the analyst intended to mislead market participants.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A manager directs client commissions to pay for a personal vacation, without client benefit.","steps_vi":["Xác định chuẩn liên quan: III(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Client brokerage không phải nguồn lợi ích cá nhân."],"answer":"Violation of III(A)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A manager documents that voting a minor foreign holding would impose costs disproportionate to any likely client benefit and declines to vote.","steps_vi":["Xác định chuẩn liên quan: III(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Guidance cho phép cân nhắc cost-benefit vì client."],"answer":"The decision can comply with III(A).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A fund manager accepts a client's direction to use a specified broker. The manager explains that the restriction may prevent best execution and documents the instruction. Which statement is best?","steps_vi":["Xác định chuẩn liên quan: III(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Guidance cho phép client-directed brokerage có disclosure về hạn chế. Client commission vẫn phải phục vụ quyền lợi client."],"answer":"Directed brokerage can be appropriate when the client understands the execution trade-off.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A manager allocates profitable trades to a high-fee account and losing trades to other suitable accounts after observing the outcome.","steps_vi":["Xác định chuẩn liên quan: III(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Cherry-picking sau kết quả là đối xử bất công."],"answer":"Violation of III(B)","check":"Original case; conclusion limited to facts stated."},{"question_en":"An oversubscribed offering is allocated using a disclosed pro rata method among eligible accounts. A fee-paying relative's client account is treated like comparable clients, with no manager beneficial interest.","steps_vi":["Xác định chuẩn liên quan: III(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Client thực sự được đối xử công bằng; không mặc định loại họ hàng."],"answer":"The allocation can comply with III(B).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A firm provides differentiated research subscription levels. Before a rating change is released to other eligible clients, its premium clients receive the change and place trades. Which Standard is most directly implicated?","steps_vi":["Xác định chuẩn liên quan: III(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Differentiated service được phép nếu không gây bất lợi cho khách khác; preferential advance dissemination làm vi phạm fairness."],"answer":"III(B) Fair Dealing","check":"Original case; conclusion limited to facts stated."},{"question_en":"A manager of a disclosed small-cap equity fund purchases large-cap bonds merely because their expected return is attractive, contrary to the mandate.","steps_vi":["Xác định chuẩn liên quan: III(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Quản lý mandate phải theo stated objectives/constraints."],"answer":"Violation of III(C)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A client insists on a small unsuitable transaction. After explaining the conflict and confirming minimal portfolio impact, the advisor obtains acknowledgment and follows the firm's permitted procedure.","steps_vi":["Xác định chuẩn liên quan: III(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Quy trình khác nhau theo mức ảnh hưởng; dữ kiện nêu đủ thảo luận và acknowledgment."],"answer":"The transaction can comply with III(C).","check":"Original case; conclusion limited to facts stated."},{"question_en":"An advisory client insists on a transaction that would materially alter portfolio risk beyond the IPS. The client refuses an IPS revision. The firm permits a separate client-directed account. What is the best next step?","steps_vi":["Xác định chuẩn liên quan: III(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Tác động material cần xử lý phù hợp; separate account có thể là lựa chọn sau discussion. Không tự ý sửa IPS hoặc thực hiện trong portfolio trái mandate."],"answer":"Explain the mismatch and consider the separate account under firm policy rather than executing in the advisory portfolio.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A firm clearly labels a backtest as hypothetical, states major assumptions and limitations, and provides detailed calculations on request.","steps_vi":["Xác định chuẩn liên quan: III(D). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Disclosure đầy đủ giúp tránh gây hiểu nhầm; không đánh đồng simulated với actual."],"answer":"The presentation can comply with III(D).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A firm wants to communicate a brief summary of its investment record to prospects. What is most appropriate?","steps_vi":["Xác định chuẩn liên quan: III(D). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Brief presentation có thể hợp lệ nếu minh bạch giới hạn và có chi tiết khi yêu cầu; không cherry-pick."],"answer":"Clearly identify the summary as limited and make supporting details available upon request.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A court order legally requires disclosure of specified client records. The advisor provides only the required records after legal review.","steps_vi":["Xác định chuẩn liên quan: III(E). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Luật yêu cầu là ngoại lệ; giới hạn phạm vi."],"answer":"The disclosure can comply with III(E).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A prospective client authorizes an advisor in writing to share specified financial information with a tax specialist assisting the client. The advisor shares only the authorized information. Which assessment is best?","steps_vi":["Xác định chuẩn liên quan: III(E). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Client permission là ngoại lệ; phải giới hạn phạm vi. Prospective client thuộc confidentiality ngay cả chưa ký hợp đồng."],"answer":"The disclosure can comply with III(E).","check":"Original case; conclusion limited to facts stated."},{"question_en":"An analyst prepares a business plan for a future firm outside working hours, without soliciting clients or using employer resources or confidential information.","steps_vi":["Xác định chuẩn liên quan: IV(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Chuẩn bị hợp pháp khác cạnh tranh thực tế hay lấy tài sản firm."],"answer":"Preparation alone can comply with IV(A).","check":"Original case; conclusion limited to facts stated."},{"question_en":"An employee proposes a paid competing advisory service, describes its nature, duration and compensation, and obtains employer consent before starting.","steps_vi":["Xác định chuẩn liên quan: IV(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Consent trước khi bắt đầu với thông tin đầy đủ."],"answer":"The arrangement can comply with IV(A).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A former employee uses public directories and general professional skills to contact potential customers after the resignation is effective. No confidential records, restrictive agreement, or applicable law is violated. Which conclusion is most appropriate?","steps_vi":["Xác định chuẩn liên quan: IV(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Sau khi nghỉ có thể dùng general skills và public information nếu không có ràng buộc khác. Không lấy confidential client list."],"answer":"The conduct can comply with IV(A).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A manager receives a proposed competing compensation arrangement and obtains documented consent from all parties before acceptance, while maintaining objective client service.","steps_vi":["Xác định chuẩn liên quan: IV(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Đã đáp ứng điều kiện written consent, không có dữ kiện vi phạm khác."],"answer":"The arrangement can comply with IV(B).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A client offers a manager a payment for exceeding next year's return target. The manager has not agreed. Which step is most appropriate before acceptance?","steps_vi":["Xác định chuẩn liên quan: IV(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Prospective incentive là additional compensation có conflict; written consent trước acceptance."],"answer":"Obtain written consent from all involved parties.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A supervisor establishes effective procedures, training and monitoring. A subordinate secretly bypasses controls despite reasonable detection efforts.","steps_vi":["Xác định chuẩn liên quan: IV(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Xét reasonable efforts, không bảo đảm tuyệt đối."],"answer":"The subordinate's violation alone does not prove IV(C) was violated.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A firm offers an employee responsibility for a trading desk without any adequate compliance system. Management refuses to adopt controls. Which response is most appropriate?","steps_vi":["Xác định chuẩn liên quan: IV(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Không có hệ thống đầy đủ và đã từ chối sửa, guidance yêu cầu decline in writing; tiền phạt không thay duties."],"answer":"Decline supervisory responsibility in writing until adequate procedures are in place.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A team reaches a recommendation using thorough documented research. An analyst disagrees with the conclusion but reasonably believes the group's basis is adequate and signs the report.","steps_vi":["Xác định chuẩn liên quan: V(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Group research có thể phù hợp nếu basis adequate."],"answer":"The conduct can comply with V(A).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A manager uses third-party research after evaluating its assumptions, currency, independence and analytical quality. No warning signs remain.","steps_vi":["Xác định chuẩn liên quan: V(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Có thể dựa vào third-party khi đánh giá hợp lý."],"answer":"Reliance can comply with V(A).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A firm launches an unfamiliar quantitative strategy based on a vendor's backtest. The analyst identifies untested stress scenarios. What is the best response before recommending it?","steps_vi":["Xác định chuẩn liên quan: V(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","V(A) cần adequate basis trước recommendation; disclosure risk V(B) không thay due diligence."],"answer":"Investigate the assumptions and test relevant scenarios before establishing a recommendation.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A manager replaces an unleveraged investment process with a materially leveraged strategy and waits a year to tell clients.","steps_vi":["Xác định chuẩn liên quan: V(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Material process change và significant risk phải được thông báo kịp thời."],"answer":"Violation of V(B)","check":"Original case; conclusion limited to facts stated."},{"question_en":"A report clearly labels a model-based price target as an estimate, describes material assumptions and risks, and distinguishes observed prices from projections.","steps_vi":["Xác định chuẩn liên quan: V(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Fact/opinion tách bạch và nêu assumptions."],"answer":"The communication can comply with V(B).","check":"Original case; conclusion limited to facts stated."},{"question_en":"An adviser charges an asset-based fee and uses an outside platform with a variable transaction fee. Exact future costs cannot be known. What disclosure is most appropriate?","steps_vi":["Xác định chuẩn liên quan: V(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Nature và cost phải đủ chi tiết, không nhất thiết số tiền chính xác chưa thể biết; phí third party cần đưa vào khi liên quan."],"answer":"Describe the services, fee structure and relevant third-party costs in reasonably detailed terms.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A departing analyst obtains written permission to use specified nonconfidential firm records and follows all relevant law and policy.","steps_vi":["Xác định chuẩn liên quan: V(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Có permission phù hợp trong phạm vi; không mở rộng sang dữ liệu khác."],"answer":"The permitted use can comply with V(C).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A firm's policy requires retaining relevant records for ten years. An analyst proposes deletion after seven years because that is CFA Institute's recommended period when no requirements exist. What should she do?","steps_vi":["Xác định chuẩn liên quan: V(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","7 năm là khuyến nghị khi không có luật/firm policy; áp dụng policy 10 năm đã nêu."],"answer":"Follow the applicable ten-year firm policy.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A manager identifies a conflicting outside role and relinquishes it before making affected investment decisions; no remaining relevant conflict exists.","steps_vi":["Xác định chuẩn liên quan: VI(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Tránh conflict là hướng phù hợp; xem các facts và duties còn lại."],"answer":"Avoidance can comply with VI(A).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A portfolio manager's spouse is a director of a prospective service provider. Which approach best addresses the conflict before selection?","steps_vi":["Xác định chuẩn liên quan: VI(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Xung đột gia đình có thể ảnh hưởng objective selection; avoid/disclose trước quyết định, quản lý bằng safeguards."],"answer":"Avoid the conflict where feasible or disclose it fully and fairly to relevant parties, with appropriate safeguards.","check":"Original case; conclusion limited to facts stated."},{"question_en":"After clients and the employer have had an appropriate opportunity to trade, an analyst follows preclearance rules and buys shares personally without MNPI or client disadvantage.","steps_vi":["Xác định chuẩn liên quan: VI(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Personal trading có thể hợp lệ với priority và controls."],"answer":"The trade can comply with VI(B).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A manager has a beneficial interest in an account held in a relative's name. A scarce investment is available to suitable client accounts. How should the manager treat the account?","steps_vi":["Xác định chuẩn liên quan: VI(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Beneficial ownership quan trọng hơn tên đăng ký account; ưu tiên client/employer."],"answer":"Apply client and employer priority to the beneficially owned account.","check":"Original case; conclusion limited to facts stated."},{"question_en":"Before a prospect signs, an advisor discloses the referral benefit's nature and estimated value and informs the employer as appropriate.","steps_vi":["Xác định chuẩn liên quan: VI(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Đáp ứng timing, recipients và nature/value theo facts."],"answer":"The disclosure can comply with VI(C).","check":"Original case; conclusion limited to facts stated."},{"question_en":"An advisor pays a real-estate broker for referring investment clients. Which disclosure is appropriate?","steps_vi":["Xác định chuẩn liên quan: VI(C). Đọc các facts có ý nghĩa trước khi chọn đáp án.","VI(C) gồm both received and paid benefits; timing trước formal agreement."],"answer":"Disclose the referral arrangement, including its nature and estimated value, to relevant parties before a formal service agreement.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A candidate publicly criticizes the exam scheduling policy and says the exam felt difficult, without mentioning questions or topics covered.","steps_vi":["Xác định chuẩn liên quan: VII(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Opinion chung cho phép, không tiết lộ nội dung."],"answer":"The comments can comply with VII(A).","check":"Original case; conclusion limited to facts stated."},{"question_en":"A study instructor asks recent candidates to describe topics absent from their actual examinations to improve a practice test. Which response is appropriate for a candidate?","steps_vi":["Xác định chuẩn liên quan: VII(A). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Soliciting/sharing confidential exam content gồm topics not covered, không chỉ actual questions. Dùng curriculum công khai để luyện."],"answer":"Decline to disclose exam-specific coverage and discuss published curriculum instead.","check":"Original case; conclusion limited to facts stated."},{"question_en":"A charterholder truthfully states that he passed all three CFA Program exams in consecutive years without claiming superior returns or ability.","steps_vi":["Xác định chuẩn liên quan: VII(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Factual statement cho phép; không suy ra superiority."],"answer":"The statement can comply with VII(B).","check":"Original case; conclusion limited to facts stated."},{"question_en":"An individual has passed all three CFA Program exams but has not yet received the charter. Which statement is most appropriate?","steps_vi":["Xác định chuẩn liên quan: VII(B). Đọc các facts có ý nghĩa trước khi chọn đáp án.","Có thể nêu sự kiện pass exams chính xác; không dùng designation/expected charter khi chưa được cấp quyền."],"answer":"I have passed all three levels of the CFA Program exams.","check":"Original case; conclusion limited to facts stated."}],"questions":[{"stem_en":"A compliance officer refuses to correct a misleading sales brochure. A salesperson stops distributing it, documents the issue, and performs only unrelated lawful work. No law requires external reporting.","options":["Her response is consistent with I(A).","She must resign immediately regardless of alternatives.","She must report externally under I(A) in every case."],"correct":0,"why_vi":"Đã tách khỏi hoạt động sai; nghỉ việc không phải bước mặc định nếu có thể tách hiệu quả. Báo cáo ngoài công ty không mặc nhiên bắt buộc.","trap_vi":"Phân biệt dissociation với báo cáo bên ngoài.","standard":"I(A)"},{"stem_en":"An analyst learns that colleagues are knowingly misallocating trades. He emails a protest but continues preparing the allocation sheets.","options":["His email satisfies his duty.","He is exempt because his supervisor decides allocations.","He violates I(A) by continuing to assist."],"correct":2,"why_vi":"Biết vi phạm mà vẫn cung cấp hỗ trợ có ý nghĩa; cần chấm dứt sự liên quan.","trap_vi":"Không chỉ xét người quyết định cuối.","standard":"I(A)"},{"stem_en":"An analyst works in a jurisdiction requiring public reporting of a specified securities violation. The firm asks her to withdraw from the activity but not file the legally required report. What is her most appropriate response?","options":["Withdraw but do not report because CFA Standards never require reporting.","Withdraw and comply with the applicable reporting law.","Remain involved until the firm files the report."],"correct":1,"why_vi":"Luật áp dụng yêu cầu báo cáo; dissociation không thay thế nghĩa vụ pháp lý. Standards không tự đặt nghĩa vụ báo cáo phổ quát nhưng không thể dùng điều đó để vi phạm luật.","trap_vi":"I(A): nghĩa vụ tuân thủ và dissociation có thể đồng thời.","standard":"I(A)"},{"stem_en":"A broker offers a portfolio manager an expensive family vacation if the manager directs client trades to the broker. The manager accepts but intends to maintain prior routing.","options":["No violation until routing changes.","No violation if the manager later discloses the gift.","Violation of I(B)"],"correct":2,"why_vi":"Lợi ích có khả năng hợp lý gây ảnh hưởng; ý định chủ quan và disclosure sau không loại bỏ vấn đề.","trap_vi":"Không yêu cầu hậu quả thực tế.","standard":"I(B)"},{"stem_en":"A satisfied client offers a modest gift for past service. The manager informs the employer before accepting and continues objective treatment of all accounts.","options":["The manager must always obtain written consent from every client.","Any gift from a client is prohibited.","The conduct can comply with I(B)."],"correct":2,"why_vi":"Quà ghi nhận quá khứ khác thỏa thuận trả thưởng tương lai; xét khách quan và thông báo employer.","trap_vi":"IV(B) có thể áp dụng nếu thỏa thuận cạnh tranh lợi ích employer.","standard":"I(B)"},{"stem_en":"A research analyst's bonus depends directly on securing investment banking mandates from the companies she rates. What is the most appropriate preventive change?","options":["Disclose the formula and retain the inducement unchanged.","Require a favorable rating only when the analyst's model supports it.","Separate research compensation from the banking mandates of covered companies."],"correct":2,"why_vi":"Cơ chế trả thưởng tạo incentive làm lệch independence/objectivity. Tách compensation là phương án phòng ngừa trực tiếp; disclosure không tự loại nguy cơ.","trap_vi":"I(B) và VI(A) có thể cùng liên quan; không chỉ conflict disclosure.","standard":"I(B)"},{"stem_en":"A researcher rewrites a consultant's proprietary valuation framework in her own words and publishes it as her own invention.","options":["Compliant because no sentences were copied.","Violation of I(C)","Compliant because the model was used for education."],"correct":1,"why_vi":"Ý tưởng/mô hình của người khác cần attribution; paraphrase không miễn nghĩa vụ.","trap_vi":"Không đồng nhất plagiarism với sao chép nguyên văn.","standard":"I(C)"},{"stem_en":"A firm continues using a model created by a former employee. A new analyst describes it as the firm's model and accurately explains its limitations.","options":["The firm must discontinue all models created by former staff.","The conduct can comply with I(C).","The analyst must claim personal authorship to use the model."],"correct":1,"why_vi":"Firm có thể tiếp tục dùng sản phẩm thuộc sở hữu mình; analyst không nhận sai công lao.","trap_vi":"Phân biệt firm ownership và personal attribution.","standard":"I(C)"},{"stem_en":"A fund's marketing team replaces a relevant benchmark with a low-return unrelated index specifically to make the fund appear superior. All reported returns are arithmetically correct. Which conclusion is most appropriate?","options":["No violation occurs because the return calculations are correct.","Only V(C) applies, regardless of the presentation.","The presentation is misleading and may violate both I(C) and III(D)."],"correct":2,"why_vi":"Benchmark được chọn có chủ đích làm hiểu sai relative performance; accuracy của phép tính không đủ. I(C) và III(D) đều có thể áp dụng.","trap_vi":"Một facts pattern có thể vi phạm nhiều Standards.","standard":"I(C)"},{"stem_en":"Two analysts publicly disagree about a lawful political policy. Neither makes a false statement nor engages in conduct reflecting adversely on professional integrity.","options":["Every political disagreement violates I(D).","The facts do not establish a violation of I(D).","Only the junior analyst violates I(D)."],"correct":1,"why_vi":"Không biến Standards thành công cụ giải quyết tranh chấp chính trị/cá nhân; dữ kiện không chứng minh liên hệ bất lợi.","trap_vi":"Không suy luận vi phạm từ bất đồng đơn thuần.","standard":"I(D)"},{"stem_en":"A candidate intentionally falsifies professional qualifications in a job application. Which pair of Standards is most directly implicated?","options":["II(B) Market Manipulation and III(B) Fair Dealing","I(C) Misrepresentation and I(D) Misconduct","V(C) Record Retention and VI(B) Priority of Transactions"],"correct":1,"why_vi":"Thông tin nghề nghiệp sai có chủ đích vừa là misrepresentation vừa là dishonest professional conduct.","trap_vi":"Không chỉ Standard về misrepresentation khi có deception.","standard":"I(D)"},{"stem_en":"A competent analyst performs appropriate research and risk analysis, but an unexpected event produces a loss.","options":["Any loss proves incompetence.","A loss proves the analyst violated the Code's integrity principle.","The loss alone does not establish an I(E) violation."],"correct":2,"why_vi":"Năng lực là khả năng/quy trình, không bảo đảm mọi kết quả.","trap_vi":"Không dùng hindsight để đánh giá competence.","standard":"I(E)"},{"stem_en":"An employer changes its mandate from domestic equities to global derivatives. The manager recognizes gaps, arranges specialized support, and completes appropriate training before taking new responsibilities. Which conclusion is best?","options":["The steps support compliance with I(E).","The manager must obtain a new professional designation to comply.","The manager violates I(E) merely by changing roles."],"correct":0,"why_vi":"Competence cần phù hợp nhiệm vụ; nhận vai trò mới không tự vi phạm khi chủ động bổ sung năng lực trước khi thực hiện.","trap_vi":"Continuing education và professional designation là phương thức, không phải yêu cầu cụ thể duy nhất.","standard":"I(E)"},{"stem_en":"An analyst combines public shipment statistics with nonmaterial observations from store visits and independently concludes demand is falling. She trades on the conclusion.","options":["Consistent with mosaic theory.","Violation because her conclusion is material.","Violation because some observations were nonpublic."],"correct":0,"why_vi":"Public + nonmaterial nonpublic có thể tạo kết luận material; không có MNPI trong dữ kiện.","trap_vi":"Phân biệt material conclusion và material input.","standard":"II(A)"},{"stem_en":"A private call gives selected fund managers an unreleased material earnings revision. One manager trades immediately because several competitors heard it.","options":["Compliant because multiple firms received the information.","Violation of II(A)","Compliant if she trades for clients rather than herself."],"correct":1,"why_vi":"Thông tin chưa phổ biến ra marketplace; số người tham dự không đủ.","trap_vi":"Client benefit không miễn nghĩa vụ thị trường.","standard":"II(A)"},{"stem_en":"A consultant offers an analyst confidential, material merger terms. The analyst declines to use them and asks compliance to restrict the securities concerned. What is the best assessment?","options":["The response is consistent with II(A).","The analyst may use the information if only client accounts benefit.","The analyst may trade if she discloses the consultant's name afterward."],"correct":0,"why_vi":"Cấm hành động dựa MNPI bất kể lợi ích cho ai. Hạn chế chứng khoán và trao đổi compliance hỗ trợ phòng ngừa.","trap_vi":"Disclosure nguồn tin không biến MNPI thành public.","standard":"II(A)"},{"stem_en":"A pension manager sells a large position to meet documented benefit payments. The sale depresses the market price.","options":["Any large trade that lowers price violates II(B).","The price impact alone does not establish manipulation.","The manager must delay until price impact is zero."],"correct":1,"why_vi":"Nhu cầu thanh khoản thật, không có intent gây hiểu nhầm trong dữ kiện.","trap_vi":"Price impact không đồng nghĩa manipulation.","standard":"II(B)"},{"stem_en":"An analyst publishes a good-faith earnings estimate based on documented research. The estimate proves incorrect and causes a temporary price decline. Which fact is most important when assessing II(B)?","options":["Whether the analyst intended to mislead market participants.","Whether the share price moved at all.","Whether the analyst's estimate differed from consensus."],"correct":0,"why_vi":"Intent to mislead là dấu hiệu trọng tâm của market manipulation; forecast sai hoặc tác động giá không đủ.","trap_vi":"Xét V(A) nếu basis thiếu, nhưng không tự suy ra II(B).","standard":"II(B)"},{"stem_en":"A manager directs client commissions to pay for a personal vacation, without client benefit.","options":["Compliant if commission rates remain unchanged.","Violation of III(A)","Compliant if the manager selects good securities."],"correct":1,"why_vi":"Client brokerage không phải nguồn lợi ích cá nhân.","trap_vi":"Không bù trừ vi phạm bằng hiệu quả đầu tư.","standard":"III(A)"},{"stem_en":"A manager documents that voting a minor foreign holding would impose costs disproportionate to any likely client benefit and declines to vote.","options":["The decision can comply with III(A).","Every unvoted proxy violates III(A).","Only the employer's preference determines whether to vote."],"correct":0,"why_vi":"Guidance cho phép cân nhắc cost-benefit vì client.","trap_vi":"Không tuyệt đối hóa proxy voting.","standard":"III(A)"},{"stem_en":"A fund manager accepts a client's direction to use a specified broker. The manager explains that the restriction may prevent best execution and documents the instruction. Which statement is best?","options":["Client-directed brokerage is prohibited under all circumstances.","The manager may use the direction to purchase personal benefits with client commissions.","Directed brokerage can be appropriate when the client understands the execution trade-off."],"correct":2,"why_vi":"Guidance cho phép client-directed brokerage có disclosure về hạn chế. Client commission vẫn phải phục vụ quyền lợi client.","trap_vi":"Client instruction không cho phép misuse of assets.","standard":"III(A)"},{"stem_en":"A manager allocates profitable trades to a high-fee account and losing trades to other suitable accounts after observing the outcome.","options":["Compliant if overall average client return is positive.","Compliant if allocation is disclosed after the fact.","Violation of III(B)"],"correct":2,"why_vi":"Cherry-picking sau kết quả là đối xử bất công.","trap_vi":"Không nhầm disclosure với fairness.","standard":"III(B)"},{"stem_en":"An oversubscribed offering is allocated using a disclosed pro rata method among eligible accounts. A fee-paying relative's client account is treated like comparable clients, with no manager beneficial interest.","options":["The relative must always be excluded.","The relative must receive an extra allocation.","The allocation can comply with III(B)."],"correct":2,"why_vi":"Client thực sự được đối xử công bằng; không mặc định loại họ hàng.","trap_vi":"VI(B) cần xét riêng nếu có beneficial ownership.","standard":"III(B)"},{"stem_en":"A firm provides differentiated research subscription levels. Before a rating change is released to other eligible clients, its premium clients receive the change and place trades. Which Standard is most directly implicated?","options":["III(D) Performance Presentation","III(B) Fair Dealing","VII(B) Reference to the CFA Program"],"correct":1,"why_vi":"Differentiated service được phép nếu không gây bất lợi cho khách khác; preferential advance dissemination làm vi phạm fairness.","trap_vi":"Phân biệt extra detail sau release với thông tin trọng yếu trước release.","standard":"III(B)"},{"stem_en":"A manager of a disclosed small-cap equity fund purchases large-cap bonds merely because their expected return is attractive, contrary to the mandate.","options":["Violation of III(C)","Compliant because diversification is generally beneficial.","Compliant if no shareholder complains."],"correct":0,"why_vi":"Quản lý mandate phải theo stated objectives/constraints.","trap_vi":"Không dùng portfolio theory làm lý do vượt mandate.","standard":"III(C)"},{"stem_en":"A client insists on a small unsuitable transaction. After explaining the conflict and confirming minimal portfolio impact, the advisor obtains acknowledgment and follows the firm's permitted procedure.","options":["Any unsuitable unsolicited transaction must always be refused.","The advisor may skip discussion because the client initiated it.","The transaction can comply with III(C)."],"correct":2,"why_vi":"Quy trình khác nhau theo mức ảnh hưởng; dữ kiện nêu đủ thảo luận và acknowledgment.","trap_vi":"Không tuyệt đối hóa refusal.","standard":"III(C)"},{"stem_en":"An advisory client insists on a transaction that would materially alter portfolio risk beyond the IPS. The client refuses an IPS revision. The firm permits a separate client-directed account. What is the best next step?","options":["Explain the mismatch and consider the separate account under firm policy rather than executing in the advisory portfolio.","Execute in the advisory portfolio because the client has requested it.","Rewrite the IPS without the client's agreement."],"correct":0,"why_vi":"Tác động material cần xử lý phù hợp; separate account có thể là lựa chọn sau discussion. Không tự ý sửa IPS hoặc thực hiện trong portfolio trái mandate.","trap_vi":"Xét mức độ material và firm policy.","standard":"III(C)"},{"stem_en":"A firm clearly labels a backtest as hypothetical, states major assumptions and limitations, and provides detailed calculations on request.","options":["Hypothetical performance is always prohibited.","The firm may label the backtest as actual if it uses historical prices.","The presentation can comply with III(D)."],"correct":2,"why_vi":"Disclosure đầy đủ giúp tránh gây hiểu nhầm; không đánh đồng simulated với actual.","trap_vi":"Không mặc định cấm mọi model results.","standard":"III(D)"},{"stem_en":"A firm wants to communicate a brief summary of its investment record to prospects. What is most appropriate?","options":["Omit the existence of terminated accounts because the summary is short.","Clearly identify the summary as limited and make supporting details available upon request.","Include only years with positive returns and label them as the full history."],"correct":1,"why_vi":"Brief presentation có thể hợp lệ nếu minh bạch giới hạn và có chi tiết khi yêu cầu; không cherry-pick.","trap_vi":"Brevity không phải ngoại lệ cho fairness.","standard":"III(D)"},{"stem_en":"A court order legally requires disclosure of specified client records. The advisor provides only the required records after legal review.","options":["Confidentiality prohibits disclosure even if law requires it.","The disclosure can comply with III(E).","The order permits publication of every unrelated client record."],"correct":1,"why_vi":"Luật yêu cầu là ngoại lệ; giới hạn phạm vi.","trap_vi":"Không mở rộng disclosure vượt yêu cầu.","standard":"III(E)"},{"stem_en":"A prospective client authorizes an advisor in writing to share specified financial information with a tax specialist assisting the client. The advisor shares only the authorized information. Which assessment is best?","options":["Prospective-client data may never be disclosed even with permission.","The authorization permits all other client data to be shared too.","The disclosure can comply with III(E)."],"correct":2,"why_vi":"Client permission là ngoại lệ; phải giới hạn phạm vi. Prospective client thuộc confidentiality ngay cả chưa ký hợp đồng.","trap_vi":"Xem nội dung và phạm vi authorization.","standard":"III(E)"},{"stem_en":"An analyst prepares a business plan for a future firm outside working hours, without soliciting clients or using employer resources or confidential information.","options":["Any preparation for future employment is prohibited.","The analyst must begin competing immediately to demonstrate independence.","Preparation alone can comply with IV(A)."],"correct":2,"why_vi":"Chuẩn bị hợp pháp khác cạnh tranh thực tế hay lấy tài sản firm.","trap_vi":"Phân biệt preparing và commencing competing practice.","standard":"IV(A)"},{"stem_en":"An employee proposes a paid competing advisory service, describes its nature, duration and compensation, and obtains employer consent before starting.","options":["Competing services can never be authorized.","Consent after completing the work is equally sufficient.","The arrangement can comply with IV(A)."],"correct":2,"why_vi":"Consent trước khi bắt đầu với thông tin đầy đủ.","trap_vi":"IV(B) cũng có thể áp dụng nếu thù lao tạo conflict.","standard":"IV(A)"},{"stem_en":"A former employee uses public directories and general professional skills to contact potential customers after the resignation is effective. No confidential records, restrictive agreement, or applicable law is violated. Which conclusion is most appropriate?","options":["Contacting any former firm's customers is permanently prohibited.","The conduct can comply with IV(A).","The former employee must destroy all professional knowledge gained at the firm."],"correct":1,"why_vi":"Sau khi nghỉ có thể dùng general skills và public information nếu không có ràng buộc khác. Không lấy confidential client list.","trap_vi":"Phân biệt employer records và general knowledge.","standard":"IV(A)"},{"stem_en":"A manager receives a proposed competing compensation arrangement and obtains documented consent from all parties before acceptance, while maintaining objective client service.","options":["The arrangement can comply with IV(B).","Written consent is never sufficient for any additional compensation.","Consent from the client alone is always sufficient."],"correct":0,"why_vi":"Đã đáp ứng điều kiện written consent, không có dữ kiện vi phạm khác.","trap_vi":"Xét I(B), VI(A) riêng nếu có xung đột khác.","standard":"IV(B)"},{"stem_en":"A client offers a manager a payment for exceeding next year's return target. The manager has not agreed. Which step is most appropriate before acceptance?","options":["Accept and notify the employer only if the target is met.","Obtain written consent from all involved parties.","Treat it as a past-service gift and disclose after payment."],"correct":1,"why_vi":"Prospective incentive là additional compensation có conflict; written consent trước acceptance.","trap_vi":"I(B) past-service gifts không đồng nghĩa IV(B) arrangements.","standard":"IV(B)"},{"stem_en":"A supervisor establishes effective procedures, training and monitoring. A subordinate secretly bypasses controls despite reasonable detection efforts.","options":["The subordinate's violation alone does not prove IV(C) was violated.","Any subordinate violation automatically establishes supervisor liability.","The supervisor has no duty to monitor after training."],"correct":0,"why_vi":"Xét reasonable efforts, không bảo đảm tuyệt đối.","trap_vi":"Không strict liability; kiểm tra phản ứng khi biết.","standard":"IV(C)"},{"stem_en":"A firm offers an employee responsibility for a trading desk without any adequate compliance system. Management refuses to adopt controls. Which response is most appropriate?","options":["Decline supervisory responsibility in writing until adequate procedures are in place.","Accept the role and delegate all oversight to the traders.","Accept if management promises to assume any financial penalties."],"correct":0,"why_vi":"Không có hệ thống đầy đủ và đã từ chối sửa, guidance yêu cầu decline in writing; tiền phạt không thay duties.","trap_vi":"Reasonable efforts bao gồm điều kiện để giám sát hiệu quả.","standard":"IV(C)"},{"stem_en":"A team reaches a recommendation using thorough documented research. An analyst disagrees with the conclusion but reasonably believes the group's basis is adequate and signs the report.","options":["A dissenting analyst must always withdraw from group research.","The conduct can comply with V(A).","The analyst may sign only if the forecast is identical to her own."],"correct":1,"why_vi":"Group research có thể phù hợp nếu basis adequate.","trap_vi":"Khác biệt opinion không đồng nghĩa vi phạm.","standard":"V(A)"},{"stem_en":"A manager uses third-party research after evaluating its assumptions, currency, independence and analytical quality. No warning signs remain.","options":["External research is always prohibited.","Only an original model developed personally can meet V(A).","Reliance can comply with V(A)."],"correct":2,"why_vi":"Có thể dựa vào third-party khi đánh giá hợp lý.","trap_vi":"Không nhầm reasonable reliance với automatic reliance.","standard":"V(A)"},{"stem_en":"A firm launches an unfamiliar quantitative strategy based on a vendor's backtest. The analyst identifies untested stress scenarios. What is the best response before recommending it?","options":["Investigate the assumptions and test relevant scenarios before establishing a recommendation.","Recommend the strategy if the vendor is reputable.","Ignore the scenarios if the marketing team discloses them."],"correct":0,"why_vi":"V(A) cần adequate basis trước recommendation; disclosure risk V(B) không thay due diligence.","trap_vi":"Research basis và communication là hai nghĩa vụ độc lập.","standard":"V(A)"},{"stem_en":"A manager replaces an unleveraged investment process with a materially leveraged strategy and waits a year to tell clients.","options":["Compliant if the new strategy improves return.","Compliant because process descriptions are never required.","Violation of V(B)"],"correct":2,"why_vi":"Material process change và significant risk phải được thông báo kịp thời.","trap_vi":"Không dùng lợi nhuận để miễn disclosure.","standard":"V(B)"},{"stem_en":"A report clearly labels a model-based price target as an estimate, describes material assumptions and risks, and distinguishes observed prices from projections.","options":["All model estimates must be omitted.","The communication can comply with V(B).","A numerical estimate must be described as fact."],"correct":1,"why_vi":"Fact/opinion tách bạch và nêu assumptions.","trap_vi":"Không biến precision thành certainty.","standard":"V(B)"},{"stem_en":"An adviser charges an asset-based fee and uses an outside platform with a variable transaction fee. Exact future costs cannot be known. What disclosure is most appropriate?","options":["Disclose no cost information because the exact future amount is unknown.","Describe the services, fee structure and relevant third-party costs in reasonably detailed terms.","Disclose only the fixed asset-based fee."],"correct":1,"why_vi":"Nature và cost phải đủ chi tiết, không nhất thiết số tiền chính xác chưa thể biết; phí third party cần đưa vào khi liên quan.","trap_vi":"Không dùng uncertainty để bỏ disclosure.","standard":"V(B)"},{"stem_en":"A departing analyst obtains written permission to use specified nonconfidential firm records and follows all relevant law and policy.","options":["The permitted use can comply with V(C).","All use of records after departure is automatically prohibited.","The analyst may also take unrelated confidential records without permission."],"correct":0,"why_vi":"Có permission phù hợp trong phạm vi; không mở rộng sang dữ liệu khác.","trap_vi":"Ownership và confidentiality xét riêng.","standard":"V(C)"},{"stem_en":"A firm's policy requires retaining relevant records for ten years. An analyst proposes deletion after seven years because that is CFA Institute's recommended period when no requirements exist. What should she do?","options":["Follow the applicable ten-year firm policy.","Delete after seven years because CFA guidance overrides firm policy.","Delete immediately after clients receive the final report."],"correct":0,"why_vi":"7 năm là khuyến nghị khi không có luật/firm policy; áp dụng policy 10 năm đã nêu.","trap_vi":"Không coi recommendation là maximum hoặc universal rule.","standard":"V(C)"},{"stem_en":"A manager identifies a conflicting outside role and relinquishes it before making affected investment decisions; no remaining relevant conflict exists.","options":["Disclosure is required for every eliminated conflict regardless of facts.","The manager must retain the role and disclose it instead.","Avoidance can comply with VI(A)."],"correct":2,"why_vi":"Tránh conflict là hướng phù hợp; xem các facts và duties còn lại.","trap_vi":"Không hiểu VI(A) là disclose-only.","standard":"VI(A)"},{"stem_en":"A portfolio manager's spouse is a director of a prospective service provider. Which approach best addresses the conflict before selection?","options":["Select the provider first and disclose only if service quality is poor.","Disclose to the spouse alone.","Avoid the conflict where feasible or disclose it fully and fairly to relevant parties, with appropriate safeguards."],"correct":2,"why_vi":"Xung đột gia đình có thể ảnh hưởng objective selection; avoid/disclose trước quyết định, quản lý bằng safeguards.","trap_vi":"Disclosure phải đến đúng bên liên quan và không miễn I(B).","standard":"VI(A)"},{"stem_en":"After clients and the employer have had an appropriate opportunity to trade, an analyst follows preclearance rules and buys shares personally without MNPI or client disadvantage.","options":["The trade can comply with VI(B).","Every personal investment is prohibited.","The analyst must always wait until all clients sell their shares."],"correct":0,"why_vi":"Personal trading có thể hợp lệ với priority và controls.","trap_vi":"Không tuyệt đối hóa ban.","standard":"VI(B)"},{"stem_en":"A manager has a beneficial interest in an account held in a relative's name. A scarce investment is available to suitable client accounts. How should the manager treat the account?","options":["Give the account the same priority as unrelated clients merely because it is in a relative's name.","Apply client and employer priority to the beneficially owned account.","Always allocate the entire scarce investment to the relative's account."],"correct":1,"why_vi":"Beneficial ownership quan trọng hơn tên đăng ký account; ưu tiên client/employer.","trap_vi":"Khác với family account client thật không có beneficial interest của member.","standard":"VI(B)"},{"stem_en":"Before a prospect signs, an advisor discloses the referral benefit's nature and estimated value and informs the employer as appropriate.","options":["The disclosure can comply with VI(C).","Referral arrangements are always prohibited.","Disclosure may be delayed until the first referral payment."],"correct":0,"why_vi":"Đáp ứng timing, recipients và nature/value theo facts.","trap_vi":"Kiểm tra conflict/independence riêng nếu cần.","standard":"VI(C)"},{"stem_en":"An advisor pays a real-estate broker for referring investment clients. Which disclosure is appropriate?","options":["Disclose only fees the advisor receives, not fees paid.","Disclose the arrangement only after the first account has been closed.","Disclose the referral arrangement, including its nature and estimated value, to relevant parties before a formal service agreement."],"correct":2,"why_vi":"VI(C) gồm both received and paid benefits; timing trước formal agreement.","trap_vi":"Không bỏ qua khoản đã trả cho người giới thiệu.","standard":"VI(C)"},{"stem_en":"A candidate publicly criticizes the exam scheduling policy and says the exam felt difficult, without mentioning questions or topics covered.","options":["Any criticism of CFA Institute violates VII(A).","The comments can comply with VII(A).","The candidate may therefore disclose actual questions as evidence."],"correct":1,"why_vi":"Opinion chung cho phép, không tiết lộ nội dung.","trap_vi":"Phân biệt criticism và confidentiality.","standard":"VII(A)"},{"stem_en":"A study instructor asks recent candidates to describe topics absent from their actual examinations to improve a practice test. Which response is appropriate for a candidate?","options":["Provide the absent topics but omit question wording.","Decline to disclose exam-specific coverage and discuss published curriculum instead.","Provide the information if the instructor promises anonymity."],"correct":1,"why_vi":"Soliciting/sharing confidential exam content gồm topics not covered, không chỉ actual questions. Dùng curriculum công khai để luyện.","trap_vi":"Không dùng study purpose làm ngoại lệ.","standard":"VII(A)"},{"stem_en":"A charterholder truthfully states that he passed all three CFA Program exams in consecutive years without claiming superior returns or ability.","options":["Mentioning consecutive exam passes is always prohibited.","The statement can comply with VII(B).","He may therefore guarantee better performance than noncharterholders."],"correct":1,"why_vi":"Factual statement cho phép; không suy ra superiority.","trap_vi":"Facts khác exaggerated implications.","standard":"VII(B)"},{"stem_en":"An individual has passed all three CFA Program exams but has not yet received the charter. Which statement is most appropriate?","options":["I have passed all three levels of the CFA Program exams.","I am a CFA charterholder with the charter pending.","CFA, expected this year."],"correct":0,"why_vi":"Có thể nêu sự kiện pass exams chính xác; không dùng designation/expected charter khi chưa được cấp quyền.","trap_vi":"Passing exams không phải charter.","standard":"VII(B)"},{"stem_en":"An operations specialist learns that a required regulatory filing is false. Compliance refuses correction, and local law requires her to report the false filing to the regulator. She should most appropriately:","options":["stop participating and make the required regulatory report.","continue preparing the filing after documenting her objection.","resign without making the required regulatory report."],"correct":0,"why_en":"Both dissociation and the legal reporting duty apply; objection alone or resignation alone cannot satisfy both.","why_vi":"Cả nghĩa vụ tách khỏi vi phạm và báo theo luật đều áp dụng; phản đối hoặc nghỉ việc riêng lẻ không đủ.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 67–76 (I(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"I(A)"},{"stem_en":"An issuer offers an analyst a fee that doubles if the published target price exceeds the current market price. Full disclosure is proposed. The analyst should:","options":["accept because the payment will be disclosed.","decline the contingent arrangement and seek independent compensation terms.","accept if the issuer cannot edit the report."],"correct":1,"why_en":"Disclosure or editorial control does not remove the incentive to distort the conclusion. A fixed disclosed fee is a different arrangement.","why_vi":"Công bố hoặc quyền biên tập không xóa động cơ bóp méo kết luận. Phí cố định được công bố là trường hợp khác.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 76–90 (I(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"I(B)"},{"stem_en":"A manager discovers that a brochure accidentally lists a degree she never earned. She continues distributing it until the next print run. Her conduct after discovering the error most likely:","options":["complies because the original error was unintentional.","complies if she did not design the brochure.","violates the misrepresentation standard."],"correct":2,"why_en":"Continuing distribution after discovery makes the inaccurate claim knowing; authorship is not the decisive fact.","why_vi":"Tiếp tục phát tán sau khi biết khiến thông tin sai trở thành có chủ ý; ai thiết kế không phải yếu tố quyết định.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 90–101 (I(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"I(C)"},{"stem_en":"A portfolio administrator deliberately falsifies an internal reconciliation to conceal a cash shortage. No client has yet lost money and no criminal charge has been filed. The administrator most likely:","options":["violates I(D) because deliberate professional deceit is sufficient.","complies until a client suffers a loss.","complies until convicted of an offense."],"correct":0,"why_en":"The deceit itself breaches professional integrity; loss or conviction is not a prerequisite.","why_vi":"Gian dối tự nó vi phạm liêm chính nghề; không cần thiệt hại hoặc bản án.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 101–104 (I(D)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"I(D)"},{"stem_en":"An experienced equity analyst is assigned to value complex credit derivatives. She identifies her knowledge gap and arranges qualified supervision and training before issuing valuations. Which statement is most accurate?","options":["She violates I(E) simply by accepting a new role.","Her actions support compliance with the role-specific competence obligation.","Her charter alone establishes competence for any valuation."],"correct":1,"why_en":"The standard focuses on acquiring and maintaining the capabilities necessary for the actual duties, not title alone.","why_vi":"Chuẩn mực xét khả năng cần thiết cho nhiệm vụ thực tế, không chỉ chức danh.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 104–109 (I(E)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"I(E)"},{"stem_en":"An analyst combines a confidential, material earnings revision from the CFO with public industry data. She recommends buying before the revision is released. Her best defense is:","options":["mosaic theory because public information was also used.","mosaic theory because the analyst did not trade personally.","neither: a material nonpublic input prevents reliance on mosaic theory."],"correct":2,"why_en":"The prohibition includes causing others to act; adding public data does not cleanse MNPI.","why_vi":"Cấm cả khiến người khác giao dịch; thêm dữ liệu công khai không làm sạch MNPI.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 109–120 (II(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"II(A)"},{"stem_en":"A fund sells a large position to meet genuine redemptions, temporarily depressing its price. There is no intent to mislead. Under II(B), the sale most likely:","options":["is not manipulation merely because it affects price.","is manipulation because the price falls.","is manipulation unless all other investors consent."],"correct":0,"why_en":"Ordinary trading can have market impact without deceptive intent; the stated facts do not establish manipulation.","why_vi":"Giao dịch thông thường có thể tác động giá mà không có ý định đánh lừa; facts không đủ kết luận manipulation.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 120–124 (II(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"II(B)"},{"stem_en":"A manager directs trades to a broker offering office furniture for the manager's firm, financed from client commissions. No client benefits from the arrangement. The manager most likely:","options":["complies if trade confirmations are accurate.","violates the duty of loyalty, prudence and care.","complies if the broker is licensed."],"correct":1,"why_en":"Using client brokerage for firm-only benefits misuses client assets; accurate confirmations or licensing do not remedy this.","why_vi":"Dùng hoa hồng khách cho lợi ích riêng firm là sử dụng sai tài sản; xác nhận hoặc giấy phép không khắc phục.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 125–135 (III(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"III(A)"},{"stem_en":"A firm receives only half of the shares needed to fill equally suitable client orders. Its manager allocates all shares to accounts that may provide future referrals, contrary to the firm's neutral allocation policy. This most likely:","options":["complies because the orders are suitable.","complies if all clients were informed of the issue.","violates fair dealing."],"correct":2,"why_en":"Suitability and notice do not justify preferential allocation based on referral potential.","why_vi":"Suitability và thông báo không biện minh phân bổ ưu ái dựa vào khả năng giới thiệu khách.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 135–144 (III(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"III(B)"},{"stem_en":"An adviser is asked to add an investment that would materially breach a client's documented risk constraints. The client insists. The adviser should first:","options":["explain the inconsistency, assess portfolio impact and review the client's circumstances and IPS.","execute because the client requested the trade.","quietly change the IPS after execution."],"correct":0,"why_en":"An unsolicited request does not remove the suitability process; material inconsistency requires review before action.","why_vi":"Lệnh khách chủ động không loại bỏ quy trình suitability; mâu thuẫn trọng yếu cần rà trước khi hành động.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 144–152 (III(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"III(C)"},{"stem_en":"A firm shows a back-tested strategy next to actual portfolio performance, without identifying which results are hypothetical. It does not claim GIPS compliance. The presentation most likely:","options":["complies because GIPS is voluntary.","violates III(D) because the nature of the returns is obscured.","complies if both calculations are mathematically correct."],"correct":1,"why_en":"The standard is independent of GIPS claims and requires fair, accurate and complete presentation, not arithmetic alone.","why_vi":"Standard độc lập với GIPS; cần trình bày công bằng, chính xác, đầy đủ, không chỉ đúng phép tính.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 152–157 (III(D)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"III(D)"},{"stem_en":"A former client has never authorized disclosure of her holdings. A journalist asks for the holdings, with no evidence of illegality or legal requirement. The adviser should:","options":["disclose because the relationship ended.","disclose if the journalist promises anonymity.","preserve confidentiality."],"correct":2,"why_en":"Former clients are covered; neither termination nor a journalist's promise establishes an exception.","why_vi":"Khách cũ vẫn được bảo mật; chấm dứt hoặc lời hứa ẩn danh không tạo ngoại lệ.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 157–162 (III(E)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"III(E)"},{"stem_en":"An analyst signs a lease for a future office on a weekend, performs all current duties, does not solicit clients and takes no employer data. Under IV(A) the preparation most likely:","options":["is permissible on the stated facts.","violates loyalty because any planning to leave is prohibited.","violates loyalty unless clients approve the lease."],"correct":0,"why_en":"Preparation alone is distinct from actual competition, solicitation or misuse of employer resources.","why_vi":"Chuẩn bị riêng khác với cạnh tranh, lôi kéo khách hoặc sử dụng sai tài sản employer.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 162–172 (IV(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"IV(A)"},{"stem_en":"A client offers a manager a bonus next year if the client's account beats a benchmark. The manager wishes to accept. The most appropriate action is to:","options":["accept and inform the employer after the bonus is paid.","obtain written consent from all involved parties before accepting the arrangement.","accept after telling other clients but not the employer."],"correct":1,"why_en":"A prospective performance bonus can conflict with employer interests; prior written consent is required under IV(B).","why_vi":"Thưởng hiệu suất tương lai có thể xung đột với employer; IV(B) yêu cầu chấp thuận văn bản trước.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 172–175 (IV(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"IV(B)"},{"stem_en":"A supervisor receives credible evidence that a trader repeatedly breached client-order priority. He tells the trader not to do it again but conducts no investigation and leaves all trading authority unchanged. He most likely:","options":["complies because he communicated a warning.","complies if the trader is not a CFA member.","fails to meet the supervisory standard."],"correct":2,"why_en":"A warning alone is inadequate in response to credible evidence; reasonable investigation and controls are needed.","why_vi":"Cảnh báo riêng lẻ không đủ khi có bằng chứng đáng tin; cần điều tra và kiểm soát hợp lý.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 174–183 (IV(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"IV(C)"},{"stem_en":"A research team uses a sound, well-documented process. One analyst prefers a different reasonable forecast but has no objection to the quality of the team's work. Under V(A), the analyst most likely:","options":["may remain associated with the group report despite the difference of opinion.","must remove her name from every report with a different forecast.","must require the group to adopt her forecast."],"correct":0,"why_en":"Reasonable disagreement does not negate a sound research basis; the standard does not require unanimity.","why_vi":"Bất đồng hợp lý không làm mất cơ sở nghiên cứu vững; không yêu cầu đồng thuận tuyệt đối.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 183–195 (V(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"V(A)"},{"stem_en":"A manager changes a client strategy from unleveraged bonds to leveraged bond derivatives, increasing material risks, without notifying clients because the benchmark is unchanged. The manager most likely:","options":["complies because the benchmark did not change.","violates V(B) by failing to communicate a material process change.","complies if performance subsequently improves."],"correct":1,"why_en":"A material change in process and risks requires communication; benchmark and realized results do not remove the duty.","why_vi":"Thay đổi trọng yếu quy trình/rủi ro cần thông báo; benchmark và kết quả sau đó không xóa nghĩa vụ.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 195–207 (V(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"V(B)"},{"stem_en":"A jurisdiction requires advisers to keep supporting records for ten years. Firm policy specifies seven years. An adviser should retain the records for at least:","options":["five years because electronic records are exempt.","seven years because CFA Institute recommends seven years.","ten years because the applicable law requires it."],"correct":2,"why_en":"The seven-year recommendation does not override a stricter applicable retention requirement.","why_vi":"Khuyến nghị 7 năm không thay yêu cầu lưu nghiêm hơn theo luật áp dụng.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 207–210 (V(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"V(C)"},{"stem_en":"A director-analyst can readily transfer coverage of the company on whose board she serves to an independent colleague. The most appropriate initial response under VI(A) is to:","options":["avoid the conflict through reassignment where reasonably practicable.","bury a disclosure in a long unrelated appendix and retain coverage.","wait until a client proves bias."],"correct":0,"why_en":"Avoidance is preferred when reasonably practicable; hidden disclosure and waiting for proof do not manage the conflict.","why_vi":"Ưu tiên tránh khi hợp lý; giấu công bố và chờ bằng chứng thiên lệch không quản trị xung đột.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 210–215 (VI(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"VI(A)"},{"stem_en":"A manager's sister pays normal fees and has an ordinary client account in which the manager has no beneficial interest. The manager excludes it from all oversubscribed issues solely because of the family relationship. This most likely:","options":["is required by client priority.","is inconsistent with fair treatment of a genuine client account.","is required even if the sister's account is suitable."],"correct":1,"why_en":"A genuine family-client account should not be disadvantaged simply due to relationship; no beneficial interest is stated.","why_vi":"Tài khoản gia đình thật sự là client không bị bất lợi chỉ do quan hệ; facts không có beneficial interest.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 215–221 (VI(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"VI(B)"},{"stem_en":"An adviser receives free analytics access in return for referring prospects to a separate manager. No cash is paid. Under VI(C) the adviser should:","options":["omit disclosure because there is no cash payment.","disclose only if the analytics provider is publicly listed.","disclose the referral benefit to the appropriate parties."],"correct":2,"why_en":"A noncash benefit is still consideration that may influence the recommendation.","why_vi":"Lợi ích phi tiền vẫn là đối ứng có thể tác động khuyến nghị.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 221–224 (VI(C)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"VI(C)"},{"stem_en":"After an exam, a candidate posts that the overall experience was stressful but reveals no exam questions, tested topics or confidential details. On these facts the post most likely:","options":["does not violate VII(A) merely for expressing an opinion.","violates VII(A) because every opinion about an exam is prohibited.","violates VII(A) unless a charterholder approves the post."],"correct":0,"why_en":"Nonconfidential opinions are not categorically forbidden; the facts exclude disclosure of protected exam information.","why_vi":"Ý kiến không mật không bị cấm tuyệt đối; facts loại trừ tiết lộ thông tin thi được bảo vệ.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 224–230 (VII(A)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"VII(A)"},{"stem_en":"An employee has passed Level I but is not registered for a future exam and is not otherwise a current candidate. Which statement is most appropriate?","options":["I hold a partial CFA designation.","I passed the Level I CFA exam.","I am a CFA Level II candidate because I intend to register."],"correct":1,"why_en":"The factual exam achievement is permissible; neither a partial designation nor an unsupported current candidate claim is appropriate.","why_vi":"Thành tích kỳ thi là facts được phép; designation từng phần hoặc tự nhận candidate chưa đủ điều kiện không phù hợp.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 230–235 (VII(B)); Kaplan Book 4 pp 167–194; SAPP Ethics Module 3 pp 23–185 (targeted comparison)","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"VII(B)"}],"cards":[{"front_en":"I(A) Knowledge of the Law — recognition test","back_vi":"Điểm quyết định trong tình huống: Luật áp dụng yêu cầu báo cáo; dissociation không thay thế nghĩa vụ pháp lý. Standards không tự đặt nghĩa vụ báo cáo phổ quát nhưng không thể dùng điều đó để vi phạm luật. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 67–75; Kaplan PDF pp. 169–170; SAPP PDF pp. 24–29] | Exam trap: I(A): nghĩa vụ tuân thủ và dissociation có thể đồng thời."},{"front_en":"A compliance officer refuses to correct a misleading sales brochure. A salesperson stops distributing it, documents the issue, and performs only unrelated lawful work. No law requires external reporting.","back_vi":"Her response is consistent with I(A). — Đã tách khỏi hoạt động sai; nghỉ việc không phải bước mặc định nếu có thể tách hiệu quả. Báo cáo ngoài công ty không mặc nhiên bắt buộc. | Trap: Phân biệt dissociation với báo cáo bên ngoài."},{"front_en":"An analyst learns that colleagues are knowingly misallocating trades. He emails a protest but continues preparing the allocation sheets.","back_vi":"He violates I(A) by continuing to assist. — Biết vi phạm mà vẫn cung cấp hỗ trợ có ý nghĩa; cần chấm dứt sự liên quan. | Trap: Không chỉ xét người quyết định cuối."},{"front_en":"An analyst works in a jurisdiction requiring public reporting of a specified securities violation. The firm asks her to withdraw from the activity but not file the legally required report. What is her most appropriate response?","back_vi":"Withdraw and comply with the applicable reporting law. — Luật áp dụng yêu cầu báo cáo; dissociation không thay thế nghĩa vụ pháp lý. Standards không tự đặt nghĩa vụ báo cáo phổ quát nhưng không thể dùng điều đó để vi phạm luật. | Trap: I(A): nghĩa vụ tuân thủ và dissociation có thể đồng thời."},{"front_en":"I(B) Independence and Objectivity — recognition test","back_vi":"Điểm quyết định trong tình huống: Cơ chế trả thưởng tạo incentive làm lệch independence/objectivity. Tách compensation là phương án phòng ngừa trực tiếp; disclosure không tự loại nguy cơ. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 76–89; Kaplan PDF pp. 170–171; SAPP PDF pp. 30–41] | Exam trap: I(B) và VI(A) có thể cùng liên quan; không chỉ conflict disclosure."},{"front_en":"A broker offers a portfolio manager an expensive family vacation if the manager directs client trades to the broker. The manager accepts but intends to maintain prior routing.","back_vi":"Violation of I(B) — Lợi ích có khả năng hợp lý gây ảnh hưởng; ý định chủ quan và disclosure sau không loại bỏ vấn đề. | Trap: Không yêu cầu hậu quả thực tế."},{"front_en":"A satisfied client offers a modest gift for past service. The manager informs the employer before accepting and continues objective treatment of all accounts.","back_vi":"The conduct can comply with I(B). — Quà ghi nhận quá khứ khác thỏa thuận trả thưởng tương lai; xét khách quan và thông báo employer. | Trap: IV(B) có thể áp dụng nếu thỏa thuận cạnh tranh lợi ích employer."},{"front_en":"A research analyst's bonus depends directly on securing investment banking mandates from the companies she rates. What is the most appropriate preventive change?","back_vi":"Separate research compensation from the banking mandates of covered companies. — Cơ chế trả thưởng tạo incentive làm lệch independence/objectivity. Tách compensation là phương án phòng ngừa trực tiếp; disclosure không tự loại nguy cơ. | Trap: I(B) và VI(A) có thể cùng liên quan; không chỉ conflict disclosure."},{"front_en":"I(C) Misrepresentation — recognition test","back_vi":"Điểm quyết định trong tình huống: Benchmark được chọn có chủ đích làm hiểu sai relative performance; accuracy của phép tính không đủ. I(C) và III(D) đều có thể áp dụng. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 90–100; Kaplan PDF pp. 171–172; SAPP PDF pp. 42–49] | Exam trap: Một facts pattern có thể vi phạm nhiều Standards."},{"front_en":"A researcher rewrites a consultant's proprietary valuation framework in her own words and publishes it as her own invention.","back_vi":"Violation of I(C) — Ý tưởng/mô hình của người khác cần attribution; paraphrase không miễn nghĩa vụ. | Trap: Không đồng nhất plagiarism với sao chép nguyên văn."},{"front_en":"A firm continues using a model created by a former employee. A new analyst describes it as the firm's model and accurately explains its limitations.","back_vi":"The conduct can comply with I(C). — Firm có thể tiếp tục dùng sản phẩm thuộc sở hữu mình; analyst không nhận sai công lao. | Trap: Phân biệt firm ownership và personal attribution."},{"front_en":"A fund's marketing team replaces a relevant benchmark with a low-return unrelated index specifically to make the fund appear superior. All reported returns are arithmetically correct. Which conclusion is most appropriate?","back_vi":"The presentation is misleading and may violate both I(C) and III(D). — Benchmark được chọn có chủ đích làm hiểu sai relative performance; accuracy của phép tính không đủ. I(C) và III(D) đều có thể áp dụng. | Trap: Một facts pattern có thể vi phạm nhiều Standards."},{"front_en":"I(D) Misconduct — recognition test","back_vi":"Điểm quyết định trong tình huống: Thông tin nghề nghiệp sai có chủ đích vừa là misrepresentation vừa là dishonest professional conduct. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 101–103; Kaplan PDF pp. 172; SAPP PDF pp. 50–52] | Exam trap: Không chỉ Standard về misrepresentation khi có deception."},{"front_en":"Two analysts publicly disagree about a lawful political policy. Neither makes a false statement nor engages in conduct reflecting adversely on professional integrity.","back_vi":"The facts do not establish a violation of I(D). — Không biến Standards thành công cụ giải quyết tranh chấp chính trị/cá nhân; dữ kiện không chứng minh liên hệ bất lợi. | Trap: Không suy luận vi phạm từ bất đồng đơn thuần."},{"front_en":"A candidate intentionally falsifies professional qualifications in a job application. Which pair of Standards is most directly implicated?","back_vi":"I(C) Misrepresentation and I(D) Misconduct — Thông tin nghề nghiệp sai có chủ đích vừa là misrepresentation vừa là dishonest professional conduct. | Trap: Không chỉ Standard về misrepresentation khi có deception."},{"front_en":"I(E) Competence — recognition test","back_vi":"Điểm quyết định trong tình huống: Competence cần phù hợp nhiệm vụ; nhận vai trò mới không tự vi phạm khi chủ động bổ sung năng lực trước khi thực hiện. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 104–107; Kaplan PDF pp. 172; SAPP PDF pp. 53–54] | Exam trap: Continuing education và professional designation là phương thức, không phải yêu cầu cụ thể duy nhất."},{"front_en":"A competent analyst performs appropriate research and risk analysis, but an unexpected event produces a loss.","back_vi":"The loss alone does not establish an I(E) violation. — Năng lực là khả năng/quy trình, không bảo đảm mọi kết quả. | Trap: Không dùng hindsight để đánh giá competence."},{"front_en":"An employer changes its mandate from domestic equities to global derivatives. The manager recognizes gaps, arranges specialized support, and completes appropriate training before taking new responsibilities. Which conclusion is best?","back_vi":"The steps support compliance with I(E). — Competence cần phù hợp nhiệm vụ; nhận vai trò mới không tự vi phạm khi chủ động bổ sung năng lực trước khi thực hiện. | Trap: Continuing education và professional designation là phương thức, không phải yêu cầu cụ thể duy nhất."},{"front_en":"II(A) Material Nonpublic Information — recognition test","back_vi":"Điểm quyết định trong tình huống: Cấm hành động dựa MNPI bất kể lợi ích cho ai. Hạn chế chứng khoán và trao đổi compliance hỗ trợ phòng ngừa. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 108–119; Kaplan PDF pp. 173–174; SAPP PDF pp. 55–61] | Exam trap: Disclosure nguồn tin không biến MNPI thành public."},{"front_en":"An analyst combines public shipment statistics with nonmaterial observations from store visits and independently concludes demand is falling. She trades on the conclusion.","back_vi":"Consistent with mosaic theory. — Public + nonmaterial nonpublic có thể tạo kết luận material; không có MNPI trong dữ kiện. | Trap: Phân biệt material conclusion và material input."},{"front_en":"A private call gives selected fund managers an unreleased material earnings revision. One manager trades immediately because several competitors heard it.","back_vi":"Violation of II(A) — Thông tin chưa phổ biến ra marketplace; số người tham dự không đủ. | Trap: Client benefit không miễn nghĩa vụ thị trường."},{"front_en":"A consultant offers an analyst confidential, material merger terms. The analyst declines to use them and asks compliance to restrict the securities concerned. What is the best assessment?","back_vi":"The response is consistent with II(A). — Cấm hành động dựa MNPI bất kể lợi ích cho ai. Hạn chế chứng khoán và trao đổi compliance hỗ trợ phòng ngừa. | Trap: Disclosure nguồn tin không biến MNPI thành public."},{"front_en":"II(B) Market Manipulation — recognition test","back_vi":"Điểm quyết định trong tình huống: Intent to mislead là dấu hiệu trọng tâm của market manipulation; forecast sai hoặc tác động giá không đủ. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 120–125; Kaplan PDF pp. 174–175; SAPP PDF pp. 62–66] | Exam trap: Xét V(A) nếu basis thiếu, nhưng không tự suy ra II(B)."},{"front_en":"A pension manager sells a large position to meet documented benefit payments. The sale depresses the market price.","back_vi":"The price impact alone does not establish manipulation. — Nhu cầu thanh khoản thật, không có intent gây hiểu nhầm trong dữ kiện. | Trap: Price impact không đồng nghĩa manipulation."},{"front_en":"An analyst publishes a good-faith earnings estimate based on documented research. The estimate proves incorrect and causes a temporary price decline. Which fact is most important when assessing II(B)?","back_vi":"Whether the analyst intended to mislead market participants. — Intent to mislead là dấu hiệu trọng tâm của market manipulation; forecast sai hoặc tác động giá không đủ. | Trap: Xét V(A) nếu basis thiếu, nhưng không tự suy ra II(B)."},{"front_en":"III(A) Loyalty, Prudence, and Care — recognition test","back_vi":"Điểm quyết định trong tình huống: Guidance cho phép client-directed brokerage có disclosure về hạn chế. Client commission vẫn phải phục vụ quyền lợi client. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 126–134; Kaplan PDF pp. 175–176; SAPP PDF pp. 67–77] | Exam trap: Client instruction không cho phép misuse of assets."},{"front_en":"A manager directs client commissions to pay for a personal vacation, without client benefit.","back_vi":"Violation of III(A) — Client brokerage không phải nguồn lợi ích cá nhân. | Trap: Không bù trừ vi phạm bằng hiệu quả đầu tư."},{"front_en":"A manager documents that voting a minor foreign holding would impose costs disproportionate to any likely client benefit and declines to vote.","back_vi":"The decision can comply with III(A). — Guidance cho phép cân nhắc cost-benefit vì client. | Trap: Không tuyệt đối hóa proxy voting."},{"front_en":"A fund manager accepts a client's direction to use a specified broker. The manager explains that the restriction may prevent best execution and documents the instruction. Which statement is best?","back_vi":"Directed brokerage can be appropriate when the client understands the execution trade-off. — Guidance cho phép client-directed brokerage có disclosure về hạn chế. Client commission vẫn phải phục vụ quyền lợi client. | Trap: Client instruction không cho phép misuse of assets."},{"front_en":"III(B) Fair Dealing — recognition test","back_vi":"Điểm quyết định trong tình huống: Differentiated service được phép nếu không gây bất lợi cho khách khác; preferential advance dissemination làm vi phạm fairness. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 135–143; Kaplan PDF pp. 176–177; SAPP PDF pp. 78–85] | Exam trap: Phân biệt extra detail sau release với thông tin trọng yếu trước release."},{"front_en":"A manager allocates profitable trades to a high-fee account and losing trades to other suitable accounts after observing the outcome.","back_vi":"Violation of III(B) — Cherry-picking sau kết quả là đối xử bất công. | Trap: Không nhầm disclosure với fairness."},{"front_en":"An oversubscribed offering is allocated using a disclosed pro rata method among eligible accounts. A fee-paying relative's client account is treated like comparable clients, with no manager beneficial interest.","back_vi":"The allocation can comply with III(B). — Client thực sự được đối xử công bằng; không mặc định loại họ hàng. | Trap: VI(B) cần xét riêng nếu có beneficial ownership."},{"front_en":"A firm provides differentiated research subscription levels. Before a rating change is released to other eligible clients, its premium clients receive the change and place trades. Which Standard is most directly implicated?","back_vi":"III(B) Fair Dealing — Differentiated service được phép nếu không gây bất lợi cho khách khác; preferential advance dissemination làm vi phạm fairness. | Trap: Phân biệt extra detail sau release với thông tin trọng yếu trước release."},{"front_en":"III(C) Suitability — recognition test","back_vi":"Điểm quyết định trong tình huống: Tác động material cần xử lý phù hợp; separate account có thể là lựa chọn sau discussion. Không tự ý sửa IPS hoặc thực hiện trong portfolio trái mandate. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 144–151; Kaplan PDF pp. 177–178; SAPP PDF pp. 86–95] | Exam trap: Xét mức độ material và firm policy."},{"front_en":"A manager of a disclosed small-cap equity fund purchases large-cap bonds merely because their expected return is attractive, contrary to the mandate.","back_vi":"Violation of III(C) — Quản lý mandate phải theo stated objectives/constraints. | Trap: Không dùng portfolio theory làm lý do vượt mandate."},{"front_en":"A client insists on a small unsuitable transaction. After explaining the conflict and confirming minimal portfolio impact, the advisor obtains acknowledgment and follows the firm's permitted procedure.","back_vi":"The transaction can comply with III(C). — Quy trình khác nhau theo mức ảnh hưởng; dữ kiện nêu đủ thảo luận và acknowledgment. | Trap: Không tuyệt đối hóa refusal."},{"front_en":"An advisory client insists on a transaction that would materially alter portfolio risk beyond the IPS. The client refuses an IPS revision. The firm permits a separate client-directed account. What is the best next step?","back_vi":"Explain the mismatch and consider the separate account under firm policy rather than executing in the advisory portfolio. — Tác động material cần xử lý phù hợp; separate account có thể là lựa chọn sau discussion. Không tự ý sửa IPS hoặc thực hiện trong portfolio trái mandate. | Trap: Xét mức độ material và firm policy."},{"front_en":"III(D) Performance Presentation — recognition test","back_vi":"Điểm quyết định trong tình huống: Brief presentation có thể hợp lệ nếu minh bạch giới hạn và có chi tiết khi yêu cầu; không cherry-pick. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 152–156; Kaplan PDF pp. 178–179; SAPP PDF pp. 96–99] | Exam trap: Brevity không phải ngoại lệ cho fairness."},{"front_en":"A firm clearly labels a backtest as hypothetical, states major assumptions and limitations, and provides detailed calculations on request.","back_vi":"The presentation can comply with III(D). — Disclosure đầy đủ giúp tránh gây hiểu nhầm; không đánh đồng simulated với actual. | Trap: Không mặc định cấm mọi model results."},{"front_en":"A firm wants to communicate a brief summary of its investment record to prospects. What is most appropriate?","back_vi":"Clearly identify the summary as limited and make supporting details available upon request. — Brief presentation có thể hợp lệ nếu minh bạch giới hạn và có chi tiết khi yêu cầu; không cherry-pick. | Trap: Brevity không phải ngoại lệ cho fairness."},{"front_en":"III(E) Preservation of Confidentiality — recognition test","back_vi":"Điểm quyết định trong tình huống: Client permission là ngoại lệ; phải giới hạn phạm vi. Prospective client thuộc confidentiality ngay cả chưa ký hợp đồng. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 157–160; Kaplan PDF pp. 179; SAPP PDF pp. 100–104] | Exam trap: Xem nội dung và phạm vi authorization."},{"front_en":"A court order legally requires disclosure of specified client records. The advisor provides only the required records after legal review.","back_vi":"The disclosure can comply with III(E). — Luật yêu cầu là ngoại lệ; giới hạn phạm vi. | Trap: Không mở rộng disclosure vượt yêu cầu."},{"front_en":"A prospective client authorizes an advisor in writing to share specified financial information with a tax specialist assisting the client. The advisor shares only the authorized information. Which assessment is best?","back_vi":"The disclosure can comply with III(E). — Client permission là ngoại lệ; phải giới hạn phạm vi. Prospective client thuộc confidentiality ngay cả chưa ký hợp đồng. | Trap: Xem nội dung và phạm vi authorization."},{"front_en":"IV(A) Loyalty — recognition test","back_vi":"Điểm quyết định trong tình huống: Sau khi nghỉ có thể dùng general skills và public information nếu không có ràng buộc khác. Không lấy confidential client list. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 161–171; Kaplan PDF pp. 180–181; SAPP PDF pp. 105–115] | Exam trap: Phân biệt employer records và general knowledge."},{"front_en":"An analyst prepares a business plan for a future firm outside working hours, without soliciting clients or using employer resources or confidential information.","back_vi":"Preparation alone can comply with IV(A). — Chuẩn bị hợp pháp khác cạnh tranh thực tế hay lấy tài sản firm. | Trap: Phân biệt preparing và commencing competing practice."},{"front_en":"An employee proposes a paid competing advisory service, describes its nature, duration and compensation, and obtains employer consent before starting.","back_vi":"The arrangement can comply with IV(A). — Consent trước khi bắt đầu với thông tin đầy đủ. | Trap: IV(B) cũng có thể áp dụng nếu thù lao tạo conflict."},{"front_en":"A former employee uses public directories and general professional skills to contact potential customers after the resignation is effective. No confidential records, restrictive agreement, or applicable law is violated. Which conclusion is most appropriate?","back_vi":"The conduct can comply with IV(A). — Sau khi nghỉ có thể dùng general skills và public information nếu không có ràng buộc khác. Không lấy confidential client list. | Trap: Phân biệt employer records và general knowledge."},{"front_en":"IV(B) Additional Compensation Arrangements — recognition test","back_vi":"Điểm quyết định trong tình huống: Prospective incentive là additional compensation có conflict; written consent trước acceptance. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 172–173; Kaplan PDF pp. 181–182; SAPP PDF pp. 116–119] | Exam trap: I(B) past-service gifts không đồng nghĩa IV(B) arrangements."},{"front_en":"A manager receives a proposed competing compensation arrangement and obtains documented consent from all parties before acceptance, while maintaining objective client service.","back_vi":"The arrangement can comply with IV(B). — Đã đáp ứng điều kiện written consent, không có dữ kiện vi phạm khác. | Trap: Xét I(B), VI(A) riêng nếu có xung đột khác."},{"front_en":"A client offers a manager a payment for exceeding next year's return target. The manager has not agreed. Which step is most appropriate before acceptance?","back_vi":"Obtain written consent from all involved parties. — Prospective incentive là additional compensation có conflict; written consent trước acceptance. | Trap: I(B) past-service gifts không đồng nghĩa IV(B) arrangements."},{"front_en":"IV(C) Responsibilities of Supervisors — recognition test","back_vi":"Điểm quyết định trong tình huống: Không có hệ thống đầy đủ và đã từ chối sửa, guidance yêu cầu decline in writing; tiền phạt không thay duties. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 174–182; Kaplan PDF pp. 182–183; SAPP PDF pp. 120–127] | Exam trap: Reasonable efforts bao gồm điều kiện để giám sát hiệu quả."},{"front_en":"A supervisor establishes effective procedures, training and monitoring. A subordinate secretly bypasses controls despite reasonable detection efforts.","back_vi":"The subordinate's violation alone does not prove IV(C) was violated. — Xét reasonable efforts, không bảo đảm tuyệt đối. | Trap: Không strict liability; kiểm tra phản ứng khi biết."},{"front_en":"A firm offers an employee responsibility for a trading desk without any adequate compliance system. Management refuses to adopt controls. Which response is most appropriate?","back_vi":"Decline supervisory responsibility in writing until adequate procedures are in place. — Không có hệ thống đầy đủ và đã từ chối sửa, guidance yêu cầu decline in writing; tiền phạt không thay duties. | Trap: Reasonable efforts bao gồm điều kiện để giám sát hiệu quả."},{"front_en":"V(A) Diligence and Reasonable Basis — recognition test","back_vi":"Điểm quyết định trong tình huống: V(A) cần adequate basis trước recommendation; disclosure risk V(B) không thay due diligence. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 183–194; Kaplan PDF pp. 183–184; SAPP PDF pp. 128–136] | Exam trap: Research basis và communication là hai nghĩa vụ độc lập."},{"front_en":"A team reaches a recommendation using thorough documented research. An analyst disagrees with the conclusion but reasonably believes the group's basis is adequate and signs the report.","back_vi":"The conduct can comply with V(A). — Group research có thể phù hợp nếu basis adequate. | Trap: Khác biệt opinion không đồng nghĩa vi phạm."},{"front_en":"A manager uses third-party research after evaluating its assumptions, currency, independence and analytical quality. No warning signs remain.","back_vi":"Reliance can comply with V(A). — Có thể dựa vào third-party khi đánh giá hợp lý. | Trap: Không nhầm reasonable reliance với automatic reliance."},{"front_en":"A firm launches an unfamiliar quantitative strategy based on a vendor's backtest. The analyst identifies untested stress scenarios. What is the best response before recommending it?","back_vi":"Investigate the assumptions and test relevant scenarios before establishing a recommendation. — V(A) cần adequate basis trước recommendation; disclosure risk V(B) không thay due diligence. | Trap: Research basis và communication là hai nghĩa vụ độc lập."},{"front_en":"V(B) Communication with Clients and Prospective Clients — recognition test","back_vi":"Điểm quyết định trong tình huống: Nature và cost phải đủ chi tiết, không nhất thiết số tiền chính xác chưa thể biết; phí third party cần đưa vào khi liên quan. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 195–206; Kaplan PDF pp. 184–186; SAPP PDF pp. 137–143] | Exam trap: Không dùng uncertainty để bỏ disclosure."},{"front_en":"A manager replaces an unleveraged investment process with a materially leveraged strategy and waits a year to tell clients.","back_vi":"Violation of V(B) — Material process change và significant risk phải được thông báo kịp thời. | Trap: Không dùng lợi nhuận để miễn disclosure."},{"front_en":"A report clearly labels a model-based price target as an estimate, describes material assumptions and risks, and distinguishes observed prices from projections.","back_vi":"The communication can comply with V(B). — Fact/opinion tách bạch và nêu assumptions. | Trap: Không biến precision thành certainty."},{"front_en":"An adviser charges an asset-based fee and uses an outside platform with a variable transaction fee. Exact future costs cannot be known. What disclosure is most appropriate?","back_vi":"Describe the services, fee structure and relevant third-party costs in reasonably detailed terms. — Nature và cost phải đủ chi tiết, không nhất thiết số tiền chính xác chưa thể biết; phí third party cần đưa vào khi liên quan. | Trap: Không dùng uncertainty để bỏ disclosure."},{"front_en":"V(C) Record Retention — recognition test","back_vi":"Điểm quyết định trong tình huống: 7 năm là khuyến nghị khi không có luật/firm policy; áp dụng policy 10 năm đã nêu. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 207–209; Kaplan PDF pp. 186; SAPP PDF pp. 144–148] | Exam trap: Không coi recommendation là maximum hoặc universal rule."},{"front_en":"A departing analyst obtains written permission to use specified nonconfidential firm records and follows all relevant law and policy.","back_vi":"The permitted use can comply with V(C). — Có permission phù hợp trong phạm vi; không mở rộng sang dữ liệu khác. | Trap: Ownership và confidentiality xét riêng."},{"front_en":"A firm's policy requires retaining relevant records for ten years. An analyst proposes deletion after seven years because that is CFA Institute's recommended period when no requirements exist. What should she do?","back_vi":"Follow the applicable ten-year firm policy. — 7 năm là khuyến nghị khi không có luật/firm policy; áp dụng policy 10 năm đã nêu. | Trap: Không coi recommendation là maximum hoặc universal rule."},{"front_en":"VI(A) Avoid or Disclose Conflicts — recognition test","back_vi":"Điểm quyết định trong tình huống: Xung đột gia đình có thể ảnh hưởng objective selection; avoid/disclose trước quyết định, quản lý bằng safeguards. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 210–214; Kaplan PDF pp. 187–188; SAPP PDF pp. 149–157] | Exam trap: Disclosure phải đến đúng bên liên quan và không miễn I(B)."},{"front_en":"A manager identifies a conflicting outside role and relinquishes it before making affected investment decisions; no remaining relevant conflict exists.","back_vi":"Avoidance can comply with VI(A). — Tránh conflict là hướng phù hợp; xem các facts và duties còn lại. | Trap: Không hiểu VI(A) là disclose-only."},{"front_en":"A portfolio manager's spouse is a director of a prospective service provider. Which approach best addresses the conflict before selection?","back_vi":"Avoid the conflict where feasible or disclose it fully and fairly to relevant parties, with appropriate safeguards. — Xung đột gia đình có thể ảnh hưởng objective selection; avoid/disclose trước quyết định, quản lý bằng safeguards. | Trap: Disclosure phải đến đúng bên liên quan và không miễn I(B)."},{"front_en":"VI(B) Priority of Transactions — recognition test","back_vi":"Điểm quyết định trong tình huống: Beneficial ownership quan trọng hơn tên đăng ký account; ưu tiên client/employer. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 215–220; Kaplan PDF pp. 188–189; SAPP PDF pp. 158–164] | Exam trap: Khác với family account client thật không có beneficial interest của member."},{"front_en":"After clients and the employer have had an appropriate opportunity to trade, an analyst follows preclearance rules and buys shares personally without MNPI or client disadvantage.","back_vi":"The trade can comply with VI(B). — Personal trading có thể hợp lệ với priority và controls. | Trap: Không tuyệt đối hóa ban."},{"front_en":"A manager has a beneficial interest in an account held in a relative's name. A scarce investment is available to suitable client accounts. How should the manager treat the account?","back_vi":"Apply client and employer priority to the beneficially owned account. — Beneficial ownership quan trọng hơn tên đăng ký account; ưu tiên client/employer. | Trap: Khác với family account client thật không có beneficial interest của member."},{"front_en":"VI(C) Referral Fees — recognition test","back_vi":"Điểm quyết định trong tình huống: VI(C) gồm both received and paid benefits; timing trước formal agreement. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 221–223; Kaplan PDF pp. 189; SAPP PDF pp. 165–168] | Exam trap: Không bỏ qua khoản đã trả cho người giới thiệu."},{"front_en":"Before a prospect signs, an advisor discloses the referral benefit's nature and estimated value and informs the employer as appropriate.","back_vi":"The disclosure can comply with VI(C). — Đáp ứng timing, recipients và nature/value theo facts. | Trap: Kiểm tra conflict/independence riêng nếu cần."},{"front_en":"An advisor pays a real-estate broker for referring investment clients. Which disclosure is appropriate?","back_vi":"Disclose the referral arrangement, including its nature and estimated value, to relevant parties before a formal service agreement. — VI(C) gồm both received and paid benefits; timing trước formal agreement. | Trap: Không bỏ qua khoản đã trả cho người giới thiệu."},{"front_en":"VII(A) Conduct as Participants in CFA Institute Programs — recognition test","back_vi":"Điểm quyết định trong tình huống: Soliciting/sharing confidential exam content gồm topics not covered, không chỉ actual questions. Dùng curriculum công khai để luyện. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 224–229; Kaplan PDF pp. 189–190; SAPP PDF pp. 169–174] | Exam trap: Không dùng study purpose làm ngoại lệ."},{"front_en":"A candidate publicly criticizes the exam scheduling policy and says the exam felt difficult, without mentioning questions or topics covered.","back_vi":"The comments can comply with VII(A). — Opinion chung cho phép, không tiết lộ nội dung. | Trap: Phân biệt criticism và confidentiality."},{"front_en":"A study instructor asks recent candidates to describe topics absent from their actual examinations to improve a practice test. Which response is appropriate for a candidate?","back_vi":"Decline to disclose exam-specific coverage and discuss published curriculum instead. — Soliciting/sharing confidential exam content gồm topics not covered, không chỉ actual questions. Dùng curriculum công khai để luyện. | Trap: Không dùng study purpose làm ngoại lệ."},{"front_en":"VII(B) Reference to CFA Institute, the CFA Designation, and the CFA Program — recognition test","back_vi":"Điểm quyết định trong tình huống: Có thể nêu sự kiện pass exams chính xác; không dùng designation/expected charter khi chưa được cấp quyền. Đối chiếu facts với phạm vi và ngoại lệ trong LOS 3.a trước khi kết luận. [CFAI PDF pp. 230–235; Kaplan PDF pp. 190–191; SAPP PDF pp. 175–183] | Exam trap: Passing exams không phải charter."},{"front_en":"A charterholder truthfully states that he passed all three CFA Program exams in consecutive years without claiming superior returns or ability.","back_vi":"The statement can comply with VII(B). — Factual statement cho phép; không suy ra superiority. | Trap: Facts khác exaggerated implications."},{"front_en":"An individual has passed all three CFA Program exams but has not yet received the charter. Which statement is most appropriate?","back_vi":"I have passed all three levels of the CFA Program exams. — Có thể nêu sự kiện pass exams chính xác; không dùng designation/expected charter khi chưa được cấp quyền. | Trap: Passing exams không phải charter."},{"front_en":"Gift vs additional compensation — decision framework?","back_vi":"Past voluntary gift → I(B) disclosure; prospective conflicting bonus → IV(B) written consent · Kiểm tra thời điểm và điều kiện thưởng, không chỉ tên gọi. · I(B) vẫn cấm benefit có thể impair objectivity; consent không cứu hành vi cấm."},{"front_en":"Fair dealing vs suitability vs priority — decision framework?","back_vi":"Eligible and suitable? → fair dissemination/allocation? → beneficial ownership priority? · III(B), III(C), VI(B) có thể đồng thời áp dụng. · Không đánh đồng fair với equal hoặc family account với personal account."},{"front_en":"Research vs communication vs records — decision framework?","back_vi":"Reasonable basis? → material facts/risks/costs disclosed? → supporting records retained? · Ba nghĩa vụ V(A), V(B), V(C) độc lập. · Good performance không thay thế một trong ba."},{"front_en":"Law, disclosure and dissociation — decision framework?","back_vi":"Check applicable law → stricter requirements → stop knowing assistance → report if required · Phân biệt I(A), báo cáo nội bộ và external reporting. · Không suy ra reporting mandatory nếu luật không yêu cầu; vẫn phải dissociate."},{"front_en":"Compliance vs violation — decision framework?","back_vi":"Read stated facts → identify duty/exception → test required action → choose most supported conclusion · Không thêm facts ngoài đề; phân biệt best next step với finding of violation. · Không tự kết luận misconduct, manipulation hoặc incompetence từ kết quả xấu."},{"front_en":"Recognition: duty, decisive facts, exceptions and evidence","back_en":"First identify the actual relationship and applicable duty. Separate facts that establish a violation from facts that merely suggest risk. Test each relevant standard independently, and check whether an exception is supported by the facts. An action can comply with one standard and violate another; a bad outcome alone is not decisive.","back_vi":"Trước hết xác định quan hệ thực và nghĩa vụ áp dụng. Tách facts đủ chứng minh vi phạm khỏi facts chỉ gợi ý rủi ro. Kiểm từng chuẩn liên quan riêng và xét ngoại lệ có căn cứ. Một hành động có thể đúng chuẩn này nhưng sai chuẩn khác; kết quả xấu riêng lẻ không quyết định.","source_anchor":"CFAI Ethics 2026 pp 67–235, practice pp 236–254","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"}]}],"version":"7.4","qa_status":"TARGETED_SOURCE_COMPARISON_PENDING_FINAL"},{"module_id":"CFA26-10-04","module_title":"Introduction to the Global Investment Performance Standards (GIPS)","subject":"Ethical and Professional Standards","level":"CFA Level I 2026","status":"Source-mapped detailed academic draft; not independently certified","language":"Vietnamese explanations with English terminology and English exam questions","source_policy":"Original bilingual explanations and original English cases informed by CFAI Curriculum 2026 Volume 10, Kaplan Book 4, SAPP Ethics. Publisher questions not reproduced.","disclaimer_vi":"Bản học theo LOS; tài liệu CFAI dẫn chiếu văn bản GIPS Standards for Firms 2020 riêng, chưa được đối chiếu toàn văn trong lượt này. Các chi tiết bổ trợ từ Kaplan/SAPP được ghi nguồn; không dùng làm tư vấn compliance thực tế.","los":[{"id":"CFA26-10-04-LOS01","letter":"a","title_en":"Purpose, Eligible Claimants and Benefits","outcome_en":"explain why the GIPS standards were created, who can claim compliance, and who benefits from compliance","overview_vi":"Học Purpose, Eligible Claimants and Benefits. Phân biệt requirements và recommendations; kiểm tra phạm vi áp dụng trước khi kết luận. Ghi chú Kaplan/SAPP là nội dung bổ trợ nếu được nêu rõ. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF pp. 255–257"},{"id":"Kaplan SchweserNotes 2026 — Book 4 Reading 92","pages":"Physical PDF pp. 195"},{"id":"SAPP CFA Level I 2026 — Ethics slides Module 4","pages":"Physical PDF pp. 201–210"}],"sections":[{"heading":"Purpose and origins","body":"GIPS (Global Investment Performance Standards) ra đời vì báo cáo thành tích không có phương pháp thống nhất, khó so sánh xuyên quốc gia và dễ thiên lệch. Đây là bộ chuẩn mực đạo đức do giới hành nghề xây dựng, nhằm fair representation (trình bày công bằng) và full disclosure (công bố đầy đủ) thành tích quá khứ. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.]","trap":"GIPS không phải mô hình dự báo lợi nhuận hay bảo đảm hiệu suất tương lai."},{"heading":"Representative accounts","body":"Chọn một tài khoản đạt lợi nhuận cao nhất để đại diện cho cả chiến lược tạo selection bias. Tài khoản được chọn có thể có kết quả đúng về số học nhưng thông điệp đại diện sai. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.]","trap":"Số đúng không bảo đảm presentation công bằng."},{"heading":"Survivorship bias","body":"Loại những danh mục đã đóng khỏi lịch sử khiến mẫu chỉ gồm khách hàng còn tồn tại; nếu tài khoản kém thường rời đi thì kết quả bị thổi phồng. Lịch sử phải phản ánh tài khoản hợp lệ trong thời gian chúng thuộc composite. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.]","trap":"Không nhầm đóng tài khoản với quyền xóa lịch sử."},{"heading":"Varying time periods","body":"Chỉ chọn khoảng thời gian có lợi hoặc đổi giai đoạn so sánh khiến track record không đại diện và giảm comparability. Cần phương pháp báo cáo nhất quán, phù hợp với yêu cầu áp dụng. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.]","trap":"Không kết luận firm A tốt hơn firm B nếu kỳ, rủi ro và phương pháp không tương đồng."},{"heading":"Five objectives","body":"Năm mục tiêu: bảo vệ lợi ích và niềm tin nhà đầu tư; dữ liệu chính xác và nhất quán; một chuẩn thống nhất được chấp nhận toàn cầu; cạnh tranh công bằng quốc tế; thúc đẩy tự quản của ngành. Mission bao gồm ethics, integrity và trust. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.]","trap":"Mục tiêu không phải xếp hạng nhà quản lý hay loại trừ thua lỗ."},{"heading":"Eligible organizations and three chapters","body":"Ấn bản 2020 gồm Firms, Asset Owners, Verifiers. Tổ chức thực sự quản lý tài sản có thể lựa chọn tuân thủ. Asset owner cạnh tranh kinh doanh dùng Firms; asset owner không cạnh tranh, báo cáo oversight body, có thể chọn Asset Owners. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.]","trap":"Không tự đồng nhất asset owner và investment firm."},{"heading":"Consultants and vendors","body":"Consultant chỉ có thể claim compliance khi thực sự quản lý tài sản thuộc phạm vi claim và đáp ứng mọi yêu cầu. Consultant thuần tư vấn có thể endorse GIPS hay yêu cầu managers tuân thủ. Phần mềm và vendor không thể tự claim compliant dù hỗ trợ tính toán. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.]","trap":"Không nhầm công cụ hỗ trợ với đối tượng chịu trách nhiệm claim."},{"heading":"Voluntary but all-or-nothing","body":"Tuân thủ thường là tự nguyện, không phải yêu cầu pháp lý phổ biến. Khi claim, firm phải đáp ứng mọi applicable requirements trong phạm vi toàn firm và dùng compliance statement thích hợp. Không được claim theo sản phẩm, composite hay một phần chuẩn. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.]","trap":"Voluntary không có nghĩa được tự chọn requirements nào sẽ tuân thủ."},{"heading":"Benefits to managers","body":"Track record có tính đáng tin hơn, tiếp cận các cuộc đấu thầu yêu cầu GIPS, cải thiện controls và quy trình đo lường. Không đồng nghĩa CFA Institute phê chuẩn firm. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.]","trap":"Không coi GIPS là giấy phép hoặc bảo đảm superior returns."},{"heading":"Benefits to clients and asset owners","body":"Khách hàng hiện tại/tiềm năng có thông tin dễ so sánh và đáng tin hơn; asset owners và oversight bodies hiểu nguồn rủi ro và excess return tốt hơn khi báo cáo thống nhất. Vẫn phải làm due diligence về chiến lược, rủi ro, phí, nhân sự và vận hành. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.]","trap":"Compliance không thay thế due diligence."},{"heading":"GIPS eligibility: asset management, advice and software","body":"Firm quản lý tài sản thực có thể claim khi đáp ứng yêu cầu áp dụng. Consultant không quản lý tài sản liên quan có thể ủng hộ chuẩn hoặc yêu cầu managers tuân thủ, nhưng không claim cho tài sản đó. Phần mềm hỗ trợ tính toán nhưng không tự trở thành tổ chức compliant. Asset owner chọn khung phù hợp theo việc có cạnh tranh kinh doanh hay không.","body_en":"A firm managing actual assets may claim compliance only after satisfying the applicable requirements. A consultant that does not manage the relevant assets can endorse the standards or require managers to comply, but cannot claim compliance for those assets. Software may support calculation without itself becoming a compliant organization. Asset owners use the relevant framework depending on whether they compete for business.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 255–257; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 195; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 201–210","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Claim decision","expr":"Actual asset management → define firm/asset owner → all applicable requirements → proper claim","meaning":"Xét đối tượng, phạm vi và điều kiện trước khi claim.","conditions":"Không dùng claim một phần hoặc claim cho software."},{"name":"Reporting bias diagnosis","expr":"Selected portfolio / omitted terminated accounts / selected time window","meaning":"Ba dạng representative account, survivorship bias, varying time periods.","conditions":"Đánh giá tính đại diện, không chỉ độ chính xác số học."}],"examples":[{"question_en":"A firm presents its highest-return account as typical of an entire strategy. Which problem is most directly illustrated?","steps_vi":["Xác định vấn đề: GIPS 4a. Xét đúng dữ kiện và điều kiện được nêu.","Chọn tài khoản thắng đại diện cho tổng thể là representative-account selection, dù số lợi nhuận thực tế của tài khoản là đúng."],"answer":"Representative-account selection","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A manager removes all accounts closed by clients from a five-year historical record. Which bias is the greatest concern?","steps_vi":["Xác định vấn đề: GIPS 4a. Xét đúng dữ kiện và điều kiện được nêu.","Tài khoản đóng có thể là tài khoản yếu; xóa lịch sử làm mẫu còn lại thiên lệch."],"answer":"Survivorship bias","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"Two firms report returns for different periods, each selected after observing its own performance. GIPS primarily seeks to improve:","steps_vi":["Xác định vấn đề: GIPS 4a. Xét đúng dữ kiện và điều kiện được nêu.","Lựa chọn kỳ có lợi làm thành tích không so sánh được; chuẩn hóa báo cáo hỗ trợ tính công bằng."],"answer":"Comparability and fair representation","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A consultant evaluates managers but does not manage any assets. Which statement is most appropriate?","steps_vi":["Xác định vấn đề: GIPS 4a. Xét đúng dữ kiện và điều kiện được nêu.","Consultant không quản lý tài sản không phải đối tượng claim; có thể endorse hoặc yêu cầu manager comply."],"answer":"It may endorse GIPS but cannot claim compliance.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A portfolio software company has correctly implemented performance algorithms. The company may most appropriately:","steps_vi":["Xác định vấn đề: GIPS 4a. Xét đúng dữ kiện và điều kiện được nêu.","Software không phải firm quản lý actual assets. Tính đúng hỗ trợ nhưng không tạo tư cách claim."],"answer":"Describe how its software supports firms' compliance efforts without claiming compliance itself.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A pension asset owner does not compete for business and reports to its trustees. Which framework is most directly relevant if it elects to comply?","steps_vi":["Xác định vấn đề: GIPS 4a. Xét đúng dữ kiện và điều kiện được nêu.","Asset owner không cạnh tranh và báo cáo oversight body có thể chọn chuẩn Asset Owners."],"answer":"GIPS Standards for Asset Owners","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A firm complies with most applicable GIPS provisions but has not completed several required procedures. Which claim is appropriate?","steps_vi":["Xác định vấn đề: GIPS 4a. Xét đúng dữ kiện và điều kiện được nêu.","GIPS all-or-nothing ở phạm vi firm; không cho partial claim."],"answer":"No compliance claim until all applicable requirements are satisfied.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A prospective client receives a GIPS report. Which action remains appropriate?","steps_vi":["Xác định vấn đề: GIPS 4a. Xét đúng dữ kiện và điều kiện được nêu.","GIPS tăng độ tin cậy của lịch sử nhưng không loại rủi ro hoặc thay đánh giá manager."],"answer":"Perform due diligence on the manager's risks and capabilities.","check":"Original instructional case; conclusion limited to stated facts."}],"questions":[{"stem_en":"A firm presents its highest-return account as typical of an entire strategy. Which problem is most directly illustrated?","options":["Survivorship bias","Inconsistent currency conversion","Representative-account selection"],"correct":2,"why_vi":"Chọn tài khoản thắng đại diện cho tổng thể là representative-account selection, dù số lợi nhuận thực tế của tài khoản là đúng.","trap_vi":"Survivorship bias cần loại bỏ tài khoản đã rời mẫu.","standard":"GIPS 4a"},{"stem_en":"A manager removes all accounts closed by clients from a five-year historical record. Which bias is the greatest concern?","options":["Look-ahead bias from forecasting prices","Benchmark duration mismatch","Survivorship bias"],"correct":2,"why_vi":"Tài khoản đóng có thể là tài khoản yếu; xóa lịch sử làm mẫu còn lại thiên lệch.","trap_vi":"Termination không cho phép xóa return khi còn thuộc composite.","standard":"GIPS 4a"},{"stem_en":"Two firms report returns for different periods, each selected after observing its own performance. GIPS primarily seeks to improve:","options":["Comparability and fair representation","Predictability of next year's returns","Uniformity of investment mandates"],"correct":0,"why_vi":"Lựa chọn kỳ có lợi làm thành tích không so sánh được; chuẩn hóa báo cáo hỗ trợ tính công bằng.","trap_vi":"Không bắt mọi firm dùng cùng strategy.","standard":"GIPS 4a"},{"stem_en":"A consultant evaluates managers but does not manage any assets. Which statement is most appropriate?","options":["It can claim compliance for its manager-selection service.","It may endorse GIPS but cannot claim compliance.","It may claim compliance if every recommended manager is compliant."],"correct":1,"why_vi":"Consultant không quản lý tài sản không phải đối tượng claim; có thể endorse hoặc yêu cầu manager comply.","trap_vi":"Compliance của người được giới thiệu không chuyển sang consultant.","standard":"GIPS 4a"},{"stem_en":"A portfolio software company has correctly implemented performance algorithms. The company may most appropriately:","options":["Claim compliance for the calculation engine only.","Claim compliance after its software is independently verified.","Describe how its software supports firms' compliance efforts without claiming compliance itself."],"correct":2,"why_vi":"Software không phải firm quản lý actual assets. Tính đúng hỗ trợ nhưng không tạo tư cách claim.","trap_vi":"Verification không biến vendor thành eligible firm.","standard":"GIPS 4a"},{"stem_en":"A pension asset owner does not compete for business and reports to its trustees. Which framework is most directly relevant if it elects to comply?","options":["GIPS Standards for Verifiers","GIPS Standards for Asset Owners","GIPS Standards for Firms solely because it owns securities"],"correct":1,"why_vi":"Asset owner không cạnh tranh và báo cáo oversight body có thể chọn chuẩn Asset Owners.","trap_vi":"Sở hữu tài sản không tự động phải dùng Firms.","standard":"GIPS 4a"},{"stem_en":"A firm complies with most applicable GIPS provisions but has not completed several required procedures. Which claim is appropriate?","options":["Compliance except for the unfinished procedures.","No compliance claim until all applicable requirements are satisfied.","Compliance for its best documented product."],"correct":1,"why_vi":"GIPS all-or-nothing ở phạm vi firm; không cho partial claim.","trap_vi":"Voluntary adoption khác voluntary requirements.","standard":"GIPS 4a"},{"stem_en":"A prospective client receives a GIPS report. Which action remains appropriate?","options":["Assume the manager's returns will exceed its benchmark.","Treat the report as a guarantee of capital preservation.","Perform due diligence on the manager's risks and capabilities."],"correct":2,"why_vi":"GIPS tăng độ tin cậy của lịch sử nhưng không loại rủi ro hoặc thay đánh giá manager.","trap_vi":"Compliance không là performance guarantee.","standard":"GIPS 4a"},{"stem_en":"A software supplier calculates returns for several asset managers using a methodology consistent with GIPS requirements. It does not manage assets. The supplier may most appropriately:","options":["claim firm-wide GIPS compliance.","describe its calculation support without claiming that the supplier is GIPS compliant.","claim compliance for each calculation module."],"correct":1,"why_en":"Calculation support is not the same as an eligible asset-managing firm’s compliance claim.","why_vi":"Hỗ trợ tính toán khác với claim của firm thực quản lý tài sản.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 255–257; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 195; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 201–210","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"GIPS eligibility: asset management, advice and software"}],"cards":[{"front_en":"Purpose and origins","back_vi":"GIPS (Global Investment Performance Standards) ra đời vì báo cáo thành tích không có phương pháp thống nhất, khó so sánh xuyên quốc gia và dễ thiên lệch. Đây là bộ chuẩn mực đạo đức do giới hành nghề xây dựng, nhằm fair representation (trình bày công bằng) và full disclosure (công bố đầy đủ) thành tích quá khứ. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.] | Exam trap: GIPS không phải mô hình dự báo lợi nhuận hay bảo đảm hiệu suất tương lai."},{"front_en":"Representative accounts","back_vi":"Chọn một tài khoản đạt lợi nhuận cao nhất để đại diện cho cả chiến lược tạo selection bias. Tài khoản được chọn có thể có kết quả đúng về số học nhưng thông điệp đại diện sai. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.] | Exam trap: Số đúng không bảo đảm presentation công bằng."},{"front_en":"Survivorship bias","back_vi":"Loại những danh mục đã đóng khỏi lịch sử khiến mẫu chỉ gồm khách hàng còn tồn tại; nếu tài khoản kém thường rời đi thì kết quả bị thổi phồng. Lịch sử phải phản ánh tài khoản hợp lệ trong thời gian chúng thuộc composite. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.] | Exam trap: Không nhầm đóng tài khoản với quyền xóa lịch sử."},{"front_en":"Varying time periods","back_vi":"Chỉ chọn khoảng thời gian có lợi hoặc đổi giai đoạn so sánh khiến track record không đại diện và giảm comparability. Cần phương pháp báo cáo nhất quán, phù hợp với yêu cầu áp dụng. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.] | Exam trap: Không kết luận firm A tốt hơn firm B nếu kỳ, rủi ro và phương pháp không tương đồng."},{"front_en":"Five objectives","back_vi":"Năm mục tiêu: bảo vệ lợi ích và niềm tin nhà đầu tư; dữ liệu chính xác và nhất quán; một chuẩn thống nhất được chấp nhận toàn cầu; cạnh tranh công bằng quốc tế; thúc đẩy tự quản của ngành. Mission bao gồm ethics, integrity và trust. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.] | Exam trap: Mục tiêu không phải xếp hạng nhà quản lý hay loại trừ thua lỗ."},{"front_en":"Eligible organizations and three chapters","back_vi":"Ấn bản 2020 gồm Firms, Asset Owners, Verifiers. Tổ chức thực sự quản lý tài sản có thể lựa chọn tuân thủ. Asset owner cạnh tranh kinh doanh dùng Firms; asset owner không cạnh tranh, báo cáo oversight body, có thể chọn Asset Owners. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.] | Exam trap: Không tự đồng nhất asset owner và investment firm."},{"front_en":"Consultants and vendors","back_vi":"Consultant chỉ có thể claim compliance khi thực sự quản lý tài sản thuộc phạm vi claim và đáp ứng mọi yêu cầu. Consultant thuần tư vấn có thể endorse GIPS hay yêu cầu managers tuân thủ. Phần mềm và vendor không thể tự claim compliant dù hỗ trợ tính toán. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.] | Exam trap: Không nhầm công cụ hỗ trợ với đối tượng chịu trách nhiệm claim."},{"front_en":"Voluntary but all-or-nothing","back_vi":"Tuân thủ thường là tự nguyện, không phải yêu cầu pháp lý phổ biến. Khi claim, firm phải đáp ứng mọi applicable requirements trong phạm vi toàn firm và dùng compliance statement thích hợp. Không được claim theo sản phẩm, composite hay một phần chuẩn. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.] | Exam trap: Voluntary không có nghĩa được tự chọn requirements nào sẽ tuân thủ."},{"front_en":"Benefits to managers","back_vi":"Track record có tính đáng tin hơn, tiếp cận các cuộc đấu thầu yêu cầu GIPS, cải thiện controls và quy trình đo lường. Không đồng nghĩa CFA Institute phê chuẩn firm. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.] | Exam trap: Không coi GIPS là giấy phép hoặc bảo đảm superior returns."},{"front_en":"Benefits to clients and asset owners","back_vi":"Khách hàng hiện tại/tiềm năng có thông tin dễ so sánh và đáng tin hơn; asset owners và oversight bodies hiểu nguồn rủi ro và excess return tốt hơn khi báo cáo thống nhất. Vẫn phải làm due diligence về chiến lược, rủi ro, phí, nhân sự và vận hành. [CFAI PDF pp. 255–257; Kaplan pp. 195; SAPP pp. 201–210.] | Exam trap: Compliance không thay thế due diligence."},{"front_en":"Claim decision — decision framework?","back_vi":"Actual asset management → define firm/asset owner → all applicable requirements → proper claim · Xét đối tượng, phạm vi và điều kiện trước khi claim. · Không dùng claim một phần hoặc claim cho software."},{"front_en":"Reporting bias diagnosis — decision framework?","back_vi":"Selected portfolio / omitted terminated accounts / selected time window · Ba dạng representative account, survivorship bias, varying time periods. · Đánh giá tính đại diện, không chỉ độ chính xác số học."},{"front_en":"A firm presents its highest-return account as typical of an entire strategy. Which problem is most directly illustrated?","back_vi":"Representative-account selection — Chọn tài khoản thắng đại diện cho tổng thể là representative-account selection, dù số lợi nhuận thực tế của tài khoản là đúng. | Exam trap: Survivorship bias cần loại bỏ tài khoản đã rời mẫu."},{"front_en":"A manager removes all accounts closed by clients from a five-year historical record. Which bias is the greatest concern?","back_vi":"Survivorship bias — Tài khoản đóng có thể là tài khoản yếu; xóa lịch sử làm mẫu còn lại thiên lệch. | Exam trap: Termination không cho phép xóa return khi còn thuộc composite."},{"front_en":"Two firms report returns for different periods, each selected after observing its own performance. GIPS primarily seeks to improve:","back_vi":"Comparability and fair representation — Lựa chọn kỳ có lợi làm thành tích không so sánh được; chuẩn hóa báo cáo hỗ trợ tính công bằng. | Exam trap: Không bắt mọi firm dùng cùng strategy."},{"front_en":"A consultant evaluates managers but does not manage any assets. Which statement is most appropriate?","back_vi":"It may endorse GIPS but cannot claim compliance. — Consultant không quản lý tài sản không phải đối tượng claim; có thể endorse hoặc yêu cầu manager comply. | Exam trap: Compliance của người được giới thiệu không chuyển sang consultant."},{"front_en":"A portfolio software company has correctly implemented performance algorithms. The company may most appropriately:","back_vi":"Describe how its software supports firms' compliance efforts without claiming compliance itself. — Software không phải firm quản lý actual assets. Tính đúng hỗ trợ nhưng không tạo tư cách claim. | Exam trap: Verification không biến vendor thành eligible firm."},{"front_en":"A pension asset owner does not compete for business and reports to its trustees. Which framework is most directly relevant if it elects to comply?","back_vi":"GIPS Standards for Asset Owners — Asset owner không cạnh tranh và báo cáo oversight body có thể chọn chuẩn Asset Owners. | Exam trap: Sở hữu tài sản không tự động phải dùng Firms."},{"front_en":"A firm complies with most applicable GIPS provisions but has not completed several required procedures. Which claim is appropriate?","back_vi":"No compliance claim until all applicable requirements are satisfied. — GIPS all-or-nothing ở phạm vi firm; không cho partial claim. | Exam trap: Voluntary adoption khác voluntary requirements."},{"front_en":"A prospective client receives a GIPS report. Which action remains appropriate?","back_vi":"Perform due diligence on the manager's risks and capabilities. — GIPS tăng độ tin cậy của lịch sử nhưng không loại rủi ro hoặc thay đánh giá manager. | Exam trap: Compliance không là performance guarantee."},{"front_en":"GIPS eligibility: asset management, advice and software","back_en":"A firm managing actual assets may claim compliance only after satisfying the applicable requirements. A consultant that does not manage the relevant assets can endorse the standards or require managers to comply, but cannot claim compliance for those assets. Software may support calculation without itself becoming a compliant organization. Asset owners use the relevant framework depending on whether they compete for business.","back_vi":"Firm quản lý tài sản thực có thể claim khi đáp ứng yêu cầu áp dụng. Consultant không quản lý tài sản liên quan có thể ủng hộ chuẩn hoặc yêu cầu managers tuân thủ, nhưng không claim cho tài sản đó. Phần mềm hỗ trợ tính toán nhưng không tự trở thành tổ chức compliant. Asset owner chọn khung phù hợp theo việc có cạnh tranh kinh doanh hay không.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 255–257; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 195; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 201–210","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-04-LOS02","letter":"b","title_en":"Key Concepts of GIPS Standards for Firms","outcome_en":"describe the key concepts of the GIPS Standards for Firms","overview_vi":"Học Key Concepts of GIPS Standards for Firms. Phân biệt requirements và recommendations; kiểm tra phạm vi áp dụng trước khi kết luận. Ghi chú Kaplan/SAPP là nội dung bổ trợ nếu được nêu rõ. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF pp. 257–258"},{"id":"Kaplan SchweserNotes 2026 — Book 4 Reading 92","pages":"Physical PDF pp. 195–196"},{"id":"SAPP CFA Level I 2026 — Ethics slides Module 4","pages":"Physical PDF pp. 211–214"}],"sections":[{"heading":"Fair representation and full disclosure","body":"Hai nguyên tắc nền tảng liên kết: trình bày không chọn lọc và cung cấp thông tin thích hợp để người đọc hiểu kết quả. Requirements là mức bắt buộc khi claim; recommendations giúp đạt best practice. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.]","trap":"Chỉ đạt minimum requirements chưa hẳn đạt mọi best practice."},{"heading":"Applicable requirements and evolution","body":"Firm phải theo tất cả requirements áp dụng, kể cả guidance, interpretations và Q&A do cơ quan GIPS công bố. Chuẩn tiếp tục phát triển; không bao trùm mọi lĩnh vực performance measurement. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.]","trap":"Không xem tài liệu tóm tắt là toàn văn GIPS."},{"heading":"Eight sections of Firms","body":"Kaplan Reading 92 và slide liệt kê 8 phần: Fundamentals; Input Data and Calculation Methodology; Composite and Pooled Fund Maintenance; Composite TWR Report; Composite MWR Report; Pooled Fund TWR Report; Pooled Fund MWR Report; GIPS Advertising Guidelines. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.]","trap":"Không nhầm ba chapters của ấn bản 2020 với tám sections trong Firms."},{"heading":"Input data and valuations","body":"Giá trị holdings, cash flows và dữ liệu định giá là inputs của performance. Dữ liệu nhất quán và phương pháp quy định giúp so sánh giữa firms; sai dữ liệu vẫn có thể tạo return sai dù thuật toán chuẩn. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.]","trap":"Không thể sửa lỗi input bằng disclosure đơn thuần."},{"heading":"Composite and pooled fund maintenance","body":"Phải tạo/duy trì composites cho strategies có segregated accounts hoặc được marketing cho segregated accounts; đưa tất cả actual fee-paying discretionary segregated accounts vào ít nhất một composite. Pooled funds được đưa vào composite phù hợp định nghĩa; duy trì thông tin về toàn bộ strategies qua composites hoặc pooled funds. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.]","trap":"Không áp dụng quy tắc ít nhất một composite cho mọi pooled fund bất kể strategy."},{"heading":"Time-weighted and money-weighted reporting","body":"TWR liên kết lợi nhuận các giai đoạn, hạn chế tác động thời điểm external cash flows; MWR phản ánh cả quy mô/thời điểm dòng tiền. SAPP trình bày TWR là mặc định trừ khi đủ điều kiện trình bày MWR theo quy định; đây là kiến thức hỗ trợ, không thay toàn văn điều kiện GIPS. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.]","trap":"Không chọn phương pháp chỉ vì kết quả cao hơn."},{"heading":"Composite return weighting","body":"Kaplan nhấn mạnh composite return là asset-weighted, không phải simple average. Ví dụ đơn giản với giá trị đầu kỳ và không có external flow: weighted return = tổng tỷ trọng tài sản nhân return. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.]","trap":"Khi có cash flow, dùng phương pháp phù hợp; không coi công thức đơn giản là mọi trường hợp."},{"heading":"Reports and disclosures","body":"Sections 4–7 quy định và khuyến nghị cho performance reports của composites và pooled funds. Một số disclosures chung, số khác phụ thuộc tình huống; không cần phát biểu về disclosure không áp dụng. Advertising guidelines áp dụng quảng cáo có nhắc claim GIPS. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.]","trap":"Không áp dụng advertising guidelines cho mọi quảng cáo chỉ vì firm compliant."},{"heading":"Compliance requires reliable inputs and all applicable requirements","body":"Báo cáo so sánh được phụ thuộc dữ liệu định giá/dòng tiền đáng tin cùng quy tắc tính và trình bày nhất quán. Claim đòi hỏi mọi requirement áp dụng; recommendation hỗ trợ best practice nhưng không mặc nhiên bắt buộc. Công thức tốt không bù được dữ liệu đầu vào cố ý gây hiểu nhầm.","body_en":"Comparable reporting depends on reliable valuations and cash-flow data as well as consistent calculation and presentation rules. Meeting applicable requirements is necessary for a claim; recommendations support best practice but are not automatically mandatory. A well-designed calculation cannot compensate for knowingly misleading input data.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 257–258; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 195–196; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 211–214","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Report families","expr":"Composite / pooled fund × TWR / MWR","meaning":"Bốn nhóm báo cáo ở Sections 4–7.","conditions":"Không tự chọn methodology để tô đẹp return."},{"name":"Simple composite illustration","expr":"R = Σ(A_i × R_i)/ΣA_i","meaning":"A_i là giá trị đầu kỳ trong ví dụ không có dòng tiền ngoài.","conditions":"Không thay thế toàn bộ calculation methodology GIPS."}],"examples":[{"question_en":"A firm correctly computes returns using the required method but uses stale, materially inaccurate asset valuations. What is the most direct problem?","steps_vi":["Xác định vấn đề: GIPS 4b. Xét đúng dữ kiện và điều kiện được nêu.","Giá trị holdings không chính xác làm performance sai ngay cả nếu thuật toán chuẩn."],"answer":"Input-data integrity","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"Which item belongs to the eight sections of GIPS Standards for Firms?","steps_vi":["Xác định vấn đề: GIPS 4b. Xét đúng dữ kiện và điều kiện được nêu.","Pooled fund MWR report thuộc tám sections của Firms; hai phương án khác là chapters riêng."],"answer":"Pooled Fund Money-Weighted Return Report","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A compliant firm ignores a newly applicable authoritative GIPS requirement because its original implementation predates that requirement. The firm should:","steps_vi":["Xác định vấn đề: GIPS 4b. Xét đúng dữ kiện và điều kiện được nêu.","Claim đòi hỏi mọi applicable requirements, bao gồm cập nhật authoritative."],"answer":"Update its procedures to meet the applicable requirement.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A firm elects to follow required GIPS provisions but not an applicable recommendation. Which statement is most accurate?","steps_vi":["Xác định vấn đề: GIPS 4b. Xét đúng dữ kiện và điều kiện được nêu.","Requirements bắt buộc; recommendations hướng best practice. Tuy nhiên fair representation và full disclosure vẫn là nền tảng."],"answer":"A recommendation is not automatically a mandatory condition of compliance.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A manager maintains segregated accounts in an active bond strategy. Which action is required in principle?","steps_vi":["Xác định vấn đề: GIPS 4b. Xét đúng dữ kiện và điều kiện được nêu.","Có segregated accounts theo strategy phải duy trì composite tương ứng; không chọn theo kết quả."],"answer":"Maintain a composite for that strategy and include eligible accounts.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An advertisement by a GIPS-compliant firm makes no reference to its GIPS compliance. Which statement is most accurate under the reading?","steps_vi":["Xác định vấn đề: GIPS 4b. Xét đúng dữ kiện và điều kiện được nêu.","Kaplan phân biệt quảng cáo nhắc claim GIPS với quảng cáo không nhắc; nghĩa vụ báo cáo vẫn riêng."],"answer":"GIPS Advertising Guidelines do not apply solely because the firm is compliant.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"For an illustrative one-period composite with no external cash flows, portfolio A starts at $30 million and earns 12%, while B starts at $70 million and earns 2%. What is the asset-weighted return?","steps_vi":["Xác định vấn đề: GIPS 4b. Xét đúng dữ kiện và điều kiện được nêu.","Tỷ trọng 30% và 70%; 0.30×12% + 0.70×2% = 3.6% + 1.4% = 5.00%."],"answer":"5.00%","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"For two subperiods separated by an external contribution, the returns are +10% and −5%. What is the linked time-weighted return?","steps_vi":["Xác định vấn đề: GIPS 4b. Xét đúng dữ kiện và điều kiện được nêu.","(1.10)(0.95)−1=0.045. TWR liên kết geometric returns, không lấy tổng hoặc trung bình đơn giản."],"answer":"4.50%","check":"Original instructional case; conclusion limited to stated facts."}],"questions":[{"stem_en":"A firm correctly computes returns using the required method but uses stale, materially inaccurate asset valuations. What is the most direct problem?","options":["Input-data integrity","The requirement to obtain verification","An automatic violation of advertising guidelines only"],"correct":0,"why_vi":"Giá trị holdings không chính xác làm performance sai ngay cả nếu thuật toán chuẩn.","trap_vi":"Verification không sửa input sai.","standard":"GIPS 4b"},{"stem_en":"Which item belongs to the eight sections of GIPS Standards for Firms?","options":["Pooled Fund Money-Weighted Return Report","GIPS Standards for Asset Owners","GIPS Standards for Verifiers"],"correct":0,"why_vi":"Pooled fund MWR report thuộc tám sections của Firms; hai phương án khác là chapters riêng.","trap_vi":"Phân biệt chapters và sections.","standard":"GIPS 4b"},{"stem_en":"A compliant firm ignores a newly applicable authoritative GIPS requirement because its original implementation predates that requirement. The firm should:","options":["Continue under its original procedures indefinitely.","Update its procedures to meet the applicable requirement.","Apply the update only if its verifier requests it."],"correct":1,"why_vi":"Claim đòi hỏi mọi applicable requirements, bao gồm cập nhật authoritative.","trap_vi":"Không phụ thuộc yêu cầu riêng của verifier.","standard":"GIPS 4b"},{"stem_en":"A firm elects to follow required GIPS provisions but not an applicable recommendation. Which statement is most accurate?","options":["A recommendation is not automatically a mandatory condition of compliance.","Any omitted recommendation always prevents a compliance claim.","Recommendations replace applicable requirements when more convenient."],"correct":0,"why_vi":"Requirements bắt buộc; recommendations hướng best practice. Tuy nhiên fair representation và full disclosure vẫn là nền tảng.","trap_vi":"Không đánh đồng should và must.","standard":"GIPS 4b"},{"stem_en":"A manager maintains segregated accounts in an active bond strategy. Which action is required in principle?","options":["Maintain a composite for that strategy and include eligible accounts.","Maintain a composite only if the strategy beats its benchmark.","Use a single representative account instead of a composite."],"correct":0,"why_vi":"Có segregated accounts theo strategy phải duy trì composite tương ứng; không chọn theo kết quả.","trap_vi":"Không dùng representative account thay composite.","standard":"GIPS 4b"},{"stem_en":"An advertisement by a GIPS-compliant firm makes no reference to its GIPS compliance. Which statement is most accurate under the reading?","options":["GIPS Advertising Guidelines do not apply solely because the firm is compliant.","All advertisements must contain a GIPS claim.","The firm can omit applicable GIPS disclosures from its performance reports."],"correct":0,"why_vi":"Kaplan phân biệt quảng cáo nhắc claim GIPS với quảng cáo không nhắc; nghĩa vụ báo cáo vẫn riêng.","trap_vi":"Không suy ra miễn mọi nghĩa vụ marketing hoặc luật.","standard":"GIPS 4b"},{"stem_en":"For an illustrative one-period composite with no external cash flows, portfolio A starts at $30 million and earns 12%, while B starts at $70 million and earns 2%. What is the asset-weighted return?","options":["7.00%","9.00%","5.00%"],"correct":2,"why_vi":"Tỷ trọng 30% và 70%; 0.30×12% + 0.70×2% = 3.6% + 1.4% = 5.00%.","trap_vi":"7% là simple average; 9% đảo tỷ trọng.","standard":"GIPS 4b"},{"stem_en":"For two subperiods separated by an external contribution, the returns are +10% and −5%. What is the linked time-weighted return?","options":["4.50%","5.00%","2.50%"],"correct":0,"why_vi":"(1.10)(0.95)−1=0.045. TWR liên kết geometric returns, không lấy tổng hoặc trung bình đơn giản.","trap_vi":"Đây là minh họa phương pháp, không phải yêu cầu tính riêng LOS GIPS.","standard":"GIPS 4b"},{"stem_en":"A firm uses an appropriate calculation methodology but knowingly feeds it biased valuation inputs. Which conclusion is most accurate?","options":["The calculation methodology alone establishes GIPS compliance.","Disclosure of the software vendor is sufficient.","Reliable inputs and fair presentation remain necessary despite the methodology."],"correct":2,"why_en":"Integrity of inputs is essential to accurate and fair performance reporting.","why_vi":"Tính toàn vẹn input thiết yếu cho báo cáo chính xác, công bằng.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 257–258; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 195–196; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 211–214","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Compliance requires reliable inputs and all applicable requirements"}],"cards":[{"front_en":"Fair representation and full disclosure","back_vi":"Hai nguyên tắc nền tảng liên kết: trình bày không chọn lọc và cung cấp thông tin thích hợp để người đọc hiểu kết quả. Requirements là mức bắt buộc khi claim; recommendations giúp đạt best practice. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.] | Exam trap: Chỉ đạt minimum requirements chưa hẳn đạt mọi best practice."},{"front_en":"Applicable requirements and evolution","back_vi":"Firm phải theo tất cả requirements áp dụng, kể cả guidance, interpretations và Q&A do cơ quan GIPS công bố. Chuẩn tiếp tục phát triển; không bao trùm mọi lĩnh vực performance measurement. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.] | Exam trap: Không xem tài liệu tóm tắt là toàn văn GIPS."},{"front_en":"Eight sections of Firms","back_vi":"Kaplan Reading 92 và slide liệt kê 8 phần: Fundamentals; Input Data and Calculation Methodology; Composite and Pooled Fund Maintenance; Composite TWR Report; Composite MWR Report; Pooled Fund TWR Report; Pooled Fund MWR Report; GIPS Advertising Guidelines. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.] | Exam trap: Không nhầm ba chapters của ấn bản 2020 với tám sections trong Firms."},{"front_en":"Input data and valuations","back_vi":"Giá trị holdings, cash flows và dữ liệu định giá là inputs của performance. Dữ liệu nhất quán và phương pháp quy định giúp so sánh giữa firms; sai dữ liệu vẫn có thể tạo return sai dù thuật toán chuẩn. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.] | Exam trap: Không thể sửa lỗi input bằng disclosure đơn thuần."},{"front_en":"Composite and pooled fund maintenance","back_vi":"Phải tạo/duy trì composites cho strategies có segregated accounts hoặc được marketing cho segregated accounts; đưa tất cả actual fee-paying discretionary segregated accounts vào ít nhất một composite. Pooled funds được đưa vào composite phù hợp định nghĩa; duy trì thông tin về toàn bộ strategies qua composites hoặc pooled funds. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.] | Exam trap: Không áp dụng quy tắc ít nhất một composite cho mọi pooled fund bất kể strategy."},{"front_en":"Time-weighted and money-weighted reporting","back_vi":"TWR liên kết lợi nhuận các giai đoạn, hạn chế tác động thời điểm external cash flows; MWR phản ánh cả quy mô/thời điểm dòng tiền. SAPP trình bày TWR là mặc định trừ khi đủ điều kiện trình bày MWR theo quy định; đây là kiến thức hỗ trợ, không thay toàn văn điều kiện GIPS. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.] | Exam trap: Không chọn phương pháp chỉ vì kết quả cao hơn."},{"front_en":"Composite return weighting","back_vi":"Kaplan nhấn mạnh composite return là asset-weighted, không phải simple average. Ví dụ đơn giản với giá trị đầu kỳ và không có external flow: weighted return = tổng tỷ trọng tài sản nhân return. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.] | Exam trap: Khi có cash flow, dùng phương pháp phù hợp; không coi công thức đơn giản là mọi trường hợp."},{"front_en":"Reports and disclosures","back_vi":"Sections 4–7 quy định và khuyến nghị cho performance reports của composites và pooled funds. Một số disclosures chung, số khác phụ thuộc tình huống; không cần phát biểu về disclosure không áp dụng. Advertising guidelines áp dụng quảng cáo có nhắc claim GIPS. [CFAI PDF pp. 257–258; Kaplan pp. 195–196; SAPP pp. 211–214.] | Exam trap: Không áp dụng advertising guidelines cho mọi quảng cáo chỉ vì firm compliant."},{"front_en":"Report families — decision framework?","back_vi":"Composite / pooled fund × TWR / MWR · Bốn nhóm báo cáo ở Sections 4–7. · Không tự chọn methodology để tô đẹp return."},{"front_en":"Simple composite illustration — decision framework?","back_vi":"R = Σ(A_i × R_i)/ΣA_i · A_i là giá trị đầu kỳ trong ví dụ không có dòng tiền ngoài. · Không thay thế toàn bộ calculation methodology GIPS."},{"front_en":"A firm correctly computes returns using the required method but uses stale, materially inaccurate asset valuations. What is the most direct problem?","back_vi":"Input-data integrity — Giá trị holdings không chính xác làm performance sai ngay cả nếu thuật toán chuẩn. | Exam trap: Verification không sửa input sai."},{"front_en":"Which item belongs to the eight sections of GIPS Standards for Firms?","back_vi":"Pooled Fund Money-Weighted Return Report — Pooled fund MWR report thuộc tám sections của Firms; hai phương án khác là chapters riêng. | Exam trap: Phân biệt chapters và sections."},{"front_en":"A compliant firm ignores a newly applicable authoritative GIPS requirement because its original implementation predates that requirement. The firm should:","back_vi":"Update its procedures to meet the applicable requirement. — Claim đòi hỏi mọi applicable requirements, bao gồm cập nhật authoritative. | Exam trap: Không phụ thuộc yêu cầu riêng của verifier."},{"front_en":"A firm elects to follow required GIPS provisions but not an applicable recommendation. Which statement is most accurate?","back_vi":"A recommendation is not automatically a mandatory condition of compliance. — Requirements bắt buộc; recommendations hướng best practice. Tuy nhiên fair representation và full disclosure vẫn là nền tảng. | Exam trap: Không đánh đồng should và must."},{"front_en":"A manager maintains segregated accounts in an active bond strategy. Which action is required in principle?","back_vi":"Maintain a composite for that strategy and include eligible accounts. — Có segregated accounts theo strategy phải duy trì composite tương ứng; không chọn theo kết quả. | Exam trap: Không dùng representative account thay composite."},{"front_en":"An advertisement by a GIPS-compliant firm makes no reference to its GIPS compliance. Which statement is most accurate under the reading?","back_vi":"GIPS Advertising Guidelines do not apply solely because the firm is compliant. — Kaplan phân biệt quảng cáo nhắc claim GIPS với quảng cáo không nhắc; nghĩa vụ báo cáo vẫn riêng. | Exam trap: Không suy ra miễn mọi nghĩa vụ marketing hoặc luật."},{"front_en":"For an illustrative one-period composite with no external cash flows, portfolio A starts at $30 million and earns 12%, while B starts at $70 million and earns 2%. What is the asset-weighted return?","back_vi":"5.00% — Tỷ trọng 30% và 70%; 0.30×12% + 0.70×2% = 3.6% + 1.4% = 5.00%. | Exam trap: 7% là simple average; 9% đảo tỷ trọng."},{"front_en":"For two subperiods separated by an external contribution, the returns are +10% and −5%. What is the linked time-weighted return?","back_vi":"4.50% — (1.10)(0.95)−1=0.045. TWR liên kết geometric returns, không lấy tổng hoặc trung bình đơn giản. | Exam trap: Đây là minh họa phương pháp, không phải yêu cầu tính riêng LOS GIPS."},{"front_en":"Compliance requires reliable inputs and all applicable requirements","back_en":"Comparable reporting depends on reliable valuations and cash-flow data as well as consistent calculation and presentation rules. Meeting applicable requirements is necessary for a claim; recommendations support best practice but are not automatically mandatory. A well-designed calculation cannot compensate for knowingly misleading input data.","back_vi":"Báo cáo so sánh được phụ thuộc dữ liệu định giá/dòng tiền đáng tin cùng quy tắc tính và trình bày nhất quán. Claim đòi hỏi mọi requirement áp dụng; recommendation hỗ trợ best practice nhưng không mặc nhiên bắt buộc. Công thức tốt không bù được dữ liệu đầu vào cố ý gây hiểu nhầm.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 257–258; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 195–196; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 211–214","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-04-LOS03","letter":"c","title_en":"Composites in Performance Reporting","outcome_en":"explain the purpose of composites in performance reporting","overview_vi":"Học Composites in Performance Reporting. Phân biệt requirements và recommendations; kiểm tra phạm vi áp dụng trước khi kết luận. Ghi chú Kaplan/SAPP là nội dung bổ trợ nếu được nêu rõ. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF pp. 258–259"},{"id":"Kaplan SchweserNotes 2026 — Book 4 Reading 92","pages":"Physical PDF pp. 196"},{"id":"SAPP CFA Level I 2026 — Ethics slides Module 4","pages":"Physical PDF pp. 212–214"}],"sections":[{"heading":"Composite definition","body":"Composite là nhóm một hoặc nhiều portfolios cùng mandate, objective hoặc strategy; cho thấy kết quả quản lý của một loại chiến lược thay vì một account thuận lợi. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.]","trap":"Một composite có thể chỉ có một portfolio đủ điều kiện."},{"heading":"Ex ante definition","body":"Tiêu chí đưa vào composite phải lập trước khi biết thành tích. Áp dụng nhất quán cho portfolios phù hợp, tránh chọn sau khi biết return. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.]","trap":"Ex post reclassification vì kết quả xấu là cherry-picking."},{"heading":"Segregated account inclusion","body":"Mọi actual fee-paying discretionary segregated accounts phải vào ít nhất một composite. Không dùng toàn bộ portfolios fee-paying nếu client restrictions khiến non-discretionary. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.]","trap":"Cả fee-paying và discretionary đều quan trọng cho quy tắc này."},{"heading":"Pooled funds","body":"Pooled funds phù hợp composite definition phải được đưa vào composite; đặc biệt tất cả fee-paying discretionary pooled funds phù hợp. Strategy chỉ có pooled funds không tự động đòi tạo composite nếu không quản lý/marketing segregated accounts. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.]","trap":"Không nhầm pooled fund với composite hoặc bắt mọi fund có composite riêng."},{"heading":"Historical accounts","body":"Khi account từng đủ điều kiện trong một strategy, track record phản ánh giai đoạn được quản lý ở strategy đó. Termination không cho phép xóa lịch sử hợp lệ. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.]","trap":"Không nhầm với việc đưa tài khoản đã đóng vào return kỳ sau khi đóng."},{"heading":"Strategy rather than legal wrapper","body":"Phân nhóm theo mục tiêu và cách triển khai đầu tư, ví dụ domestic investment-grade bond, global equity hay index replication; không nhóm tùy tiện chỉ vì loại khách hàng hoặc returns tương tự. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.]","trap":"Không lấy performance làm tiêu chí membership."},{"heading":"Composite versus total firm assets","body":"Composite đại diện strategy đủ điều kiện; total firm assets có phạm vi rộng hơn, bao gồm assets discretionary và non-discretionary thực sự quản lý. Không suy luận total assets bằng cộng composite đơn giản nếu có chồng lấn hoặc assets ngoài composite. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.]","trap":"Không đồng nhất danh sách composite với balance sheet firm."},{"heading":"Composite membership: strategy, ex-ante criteria and pooled funds","body":"Định nghĩa tiêu chí theo chiến lược trước khi biết return. Đưa mọi tài khoản riêng actual fee-paying discretionary vào ít nhất một composite, và pooled fund đủ tiêu chí vào composite phù hợp. Composite một portfolio có thể hợp lệ. Chấm dứt account không cho phép sửa lịch sử hợp lệ. Portfolio non-discretionary không đưa vào composite.","body_en":"Define strategy-based eligibility before observing returns. Include all actual fee-paying discretionary segregated accounts in at least one composite, and include qualifying pooled funds in composites they meet. A one-portfolio composite can be valid. Termination does not justify rewriting eligible historical performance. Non-discretionary portfolios are excluded from composites.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 258–259; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 196; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 212–214","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Inclusion test","expr":"Actual → fee-paying → discretionary → strategy definition → include","meaning":"Áp dụng quy tắc segregated accounts; xét pooled funds theo định nghĩa phù hợp.","conditions":"Không loại account vì kết quả thấp."}],"examples":[{"question_en":"A new strategy has only one actual fee-paying discretionary segregated account. Which statement is most appropriate?","steps_vi":["Xác định vấn đề: GIPS 4c. Xét đúng dữ kiện và điều kiện được nêu.","Composite một hoặc nhiều portfolios; membership theo strategy."],"answer":"A composite can contain that single account.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A firm's global equity accounts differ in performance but follow the same mandate. Which is the most appropriate basis for inclusion?","steps_vi":["Xác định vấn đề: GIPS 4c. Xét đúng dữ kiện và điều kiện được nêu.","Ex ante criteria, không phải return hoặc renewals."],"answer":"Pre-established strategy eligibility criteria","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A fee-paying segregated account is managed within the firm's discretionary bond mandate. It should be included in:","steps_vi":["Xác định vấn đề: GIPS 4c. Xét đúng dữ kiện và điều kiện được nêu.","Actual fee-paying discretionary segregated account phải thuộc ít nhất một composite phù hợp."],"answer":"At least one composite that fits its strategy.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A discretionary pooled fund meets an existing composite's strategy definition and pays fees. The firm should:","steps_vi":["Xác định vấn đề: GIPS 4c. Xét đúng dữ kiện và điều kiện được nêu.","Pooled fund đáp ứng definition phải vào composite phù hợp."],"answer":"Include it in that composite.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An account was eligible for a composite for three years and then terminated. What treatment best prevents survivorship bias?","steps_vi":["Xác định vấn đề: GIPS 4c. Xét đúng dữ kiện và điều kiện được nêu.","Giữ lịch sử kỳ account thuộc composite, không giả lập sau termination."],"answer":"Retain its historical performance for the eligible period.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A manager groups portfolios by their realized return quartiles after each year closes. Why is this inappropriate?","steps_vi":["Xác định vấn đề: GIPS 4c. Xét đúng dữ kiện và điều kiện được nêu.","Phân nhóm theo returns sau kỳ tạo cherry-picking, không theo mandate."],"answer":"Membership is based on outcomes rather than a pre-established mandate.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A firm manages a restricted nondiscretionary account that is not eligible for any composite. Which statement is most accurate?","steps_vi":["Xác định vấn đề: GIPS 4c. Xét đúng dữ kiện và điều kiện được nêu.","Total firm assets rộng hơn composite; account non-discretionary không thuộc composite."],"answer":"It may still be part of total firm assets.","check":"Original instructional case; conclusion limited to stated facts."}],"questions":[{"stem_en":"A new strategy has only one actual fee-paying discretionary segregated account. Which statement is most appropriate?","options":["A composite cannot exist until at least two accounts join.","The firm must wait until the account has a positive return.","A composite can contain that single account."],"correct":2,"why_vi":"Composite một hoặc nhiều portfolios; membership theo strategy.","trap_vi":"Không có minimum hai portfolios trong định nghĩa.","standard":"GIPS 4c"},{"stem_en":"A firm's global equity accounts differ in performance but follow the same mandate. Which is the most appropriate basis for inclusion?","options":["Ranking the accounts by realized return","Pre-established strategy eligibility criteria","Clients' decision to renew their contracts after year-end"],"correct":1,"why_vi":"Ex ante criteria, không phải return hoặc renewals.","trap_vi":"Selection sau kết quả là bias.","standard":"GIPS 4c"},{"stem_en":"A fee-paying segregated account is managed within the firm's discretionary bond mandate. It should be included in:","options":["A composite only if its return is close to the median.","A composite only if the client agrees to a higher fee.","At least one composite that fits its strategy."],"correct":2,"why_vi":"Actual fee-paying discretionary segregated account phải thuộc ít nhất một composite phù hợp.","trap_vi":"Không dùng mức phí hay return để loại account hợp lệ.","standard":"GIPS 4c"},{"stem_en":"A discretionary pooled fund meets an existing composite's strategy definition and pays fees. The firm should:","options":["Exclude it because pooled funds can never enter composites.","Create a second composite only for the legal wrapper.","Include it in that composite."],"correct":2,"why_vi":"Pooled fund đáp ứng definition phải vào composite phù hợp.","trap_vi":"Legal wrapper không tự quyết định inclusion.","standard":"GIPS 4c"},{"stem_en":"An account was eligible for a composite for three years and then terminated. What treatment best prevents survivorship bias?","options":["Delete all its historical returns upon termination.","Retain its historical performance for the eligible period.","Continue reporting hypothetical returns for the account indefinitely."],"correct":1,"why_vi":"Giữ lịch sử kỳ account thuộc composite, không giả lập sau termination.","trap_vi":"Historical inclusion khác current membership.","standard":"GIPS 4c"},{"stem_en":"A manager groups portfolios by their realized return quartiles after each year closes. Why is this inappropriate?","options":["Composites are required to contain exactly one portfolio.","Only portfolios with identical fee schedules can be combined.","Membership is based on outcomes rather than a pre-established mandate."],"correct":2,"why_vi":"Phân nhóm theo returns sau kỳ tạo cherry-picking, không theo mandate.","trap_vi":"Không cần fee schedule giống hệt nhau.","standard":"GIPS 4c"},{"stem_en":"A firm manages a restricted nondiscretionary account that is not eligible for any composite. Which statement is most accurate?","options":["It may still be part of total firm assets.","It must be included in the best-performing composite.","It must be excluded from all firm asset totals."],"correct":0,"why_vi":"Total firm assets rộng hơn composite; account non-discretionary không thuộc composite.","trap_vi":"Không dùng composite inclusion để định nghĩa toàn bộ AUM.","standard":"GIPS 4c"},{"stem_en":"A firm launches a segregated-account strategy with only one eligible fee-paying discretionary account. Which treatment is most appropriate?","options":["Create the relevant composite even though it currently contains one account.","Wait until at least three accounts exist.","Choose whether to form the composite after observing the account’s return."],"correct":0,"why_en":"One portfolio is sufficient and criteria must be established ex ante.","why_vi":"Một portfolio đủ; tiêu chí lập ex ante.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 258–259; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 196; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 212–214","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Composite membership: strategy, ex-ante criteria and pooled funds"},{"stem_en":"A fee-paying discretionary pooled fund meets the established definition of a composite. The firm should most appropriately:","options":["exclude it solely because of its legal wrapper.","include it in the composite it qualifies for.","include it only if it exceeds the composite’s historical return."],"correct":1,"why_en":"Qualifying pooled funds are included; legal form or realized performance alone is not an exclusion criterion.","why_vi":"Pooled fund đủ tiêu chí được đưa vào; hình thức pháp lý hay return thực hiện không phải lý do loại riêng.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 258–259; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 196; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 212–214","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Composite membership: strategy, ex-ante criteria and pooled funds"}],"cards":[{"front_en":"Composite definition","back_vi":"Composite là nhóm một hoặc nhiều portfolios cùng mandate, objective hoặc strategy; cho thấy kết quả quản lý của một loại chiến lược thay vì một account thuận lợi. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.] | Exam trap: Một composite có thể chỉ có một portfolio đủ điều kiện."},{"front_en":"Ex ante definition","back_vi":"Tiêu chí đưa vào composite phải lập trước khi biết thành tích. Áp dụng nhất quán cho portfolios phù hợp, tránh chọn sau khi biết return. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.] | Exam trap: Ex post reclassification vì kết quả xấu là cherry-picking."},{"front_en":"Segregated account inclusion","back_vi":"Mọi actual fee-paying discretionary segregated accounts phải vào ít nhất một composite. Không dùng toàn bộ portfolios fee-paying nếu client restrictions khiến non-discretionary. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.] | Exam trap: Cả fee-paying và discretionary đều quan trọng cho quy tắc này."},{"front_en":"Pooled funds","back_vi":"Pooled funds phù hợp composite definition phải được đưa vào composite; đặc biệt tất cả fee-paying discretionary pooled funds phù hợp. Strategy chỉ có pooled funds không tự động đòi tạo composite nếu không quản lý/marketing segregated accounts. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.] | Exam trap: Không nhầm pooled fund với composite hoặc bắt mọi fund có composite riêng."},{"front_en":"Historical accounts","back_vi":"Khi account từng đủ điều kiện trong một strategy, track record phản ánh giai đoạn được quản lý ở strategy đó. Termination không cho phép xóa lịch sử hợp lệ. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.] | Exam trap: Không nhầm với việc đưa tài khoản đã đóng vào return kỳ sau khi đóng."},{"front_en":"Strategy rather than legal wrapper","back_vi":"Phân nhóm theo mục tiêu và cách triển khai đầu tư, ví dụ domestic investment-grade bond, global equity hay index replication; không nhóm tùy tiện chỉ vì loại khách hàng hoặc returns tương tự. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.] | Exam trap: Không lấy performance làm tiêu chí membership."},{"front_en":"Composite versus total firm assets","back_vi":"Composite đại diện strategy đủ điều kiện; total firm assets có phạm vi rộng hơn, bao gồm assets discretionary và non-discretionary thực sự quản lý. Không suy luận total assets bằng cộng composite đơn giản nếu có chồng lấn hoặc assets ngoài composite. [CFAI PDF pp. 258–259; Kaplan pp. 196; SAPP pp. 212–214.] | Exam trap: Không đồng nhất danh sách composite với balance sheet firm."},{"front_en":"Inclusion test — decision framework?","back_vi":"Actual → fee-paying → discretionary → strategy definition → include · Áp dụng quy tắc segregated accounts; xét pooled funds theo định nghĩa phù hợp. · Không loại account vì kết quả thấp."},{"front_en":"A new strategy has only one actual fee-paying discretionary segregated account. Which statement is most appropriate?","back_vi":"A composite can contain that single account. — Composite một hoặc nhiều portfolios; membership theo strategy. | Exam trap: Không có minimum hai portfolios trong định nghĩa."},{"front_en":"A firm's global equity accounts differ in performance but follow the same mandate. Which is the most appropriate basis for inclusion?","back_vi":"Pre-established strategy eligibility criteria — Ex ante criteria, không phải return hoặc renewals. | Exam trap: Selection sau kết quả là bias."},{"front_en":"A fee-paying segregated account is managed within the firm's discretionary bond mandate. It should be included in:","back_vi":"At least one composite that fits its strategy. — Actual fee-paying discretionary segregated account phải thuộc ít nhất một composite phù hợp. | Exam trap: Không dùng mức phí hay return để loại account hợp lệ."},{"front_en":"A discretionary pooled fund meets an existing composite's strategy definition and pays fees. The firm should:","back_vi":"Include it in that composite. — Pooled fund đáp ứng definition phải vào composite phù hợp. | Exam trap: Legal wrapper không tự quyết định inclusion."},{"front_en":"An account was eligible for a composite for three years and then terminated. What treatment best prevents survivorship bias?","back_vi":"Retain its historical performance for the eligible period. — Giữ lịch sử kỳ account thuộc composite, không giả lập sau termination. | Exam trap: Historical inclusion khác current membership."},{"front_en":"A manager groups portfolios by their realized return quartiles after each year closes. Why is this inappropriate?","back_vi":"Membership is based on outcomes rather than a pre-established mandate. — Phân nhóm theo returns sau kỳ tạo cherry-picking, không theo mandate. | Exam trap: Không cần fee schedule giống hệt nhau."},{"front_en":"A firm manages a restricted nondiscretionary account that is not eligible for any composite. Which statement is most accurate?","back_vi":"It may still be part of total firm assets. — Total firm assets rộng hơn composite; account non-discretionary không thuộc composite. | Exam trap: Không dùng composite inclusion để định nghĩa toàn bộ AUM."},{"front_en":"Composite membership: strategy, ex-ante criteria and pooled funds","back_en":"Define strategy-based eligibility before observing returns. Include all actual fee-paying discretionary segregated accounts in at least one composite, and include qualifying pooled funds in composites they meet. A one-portfolio composite can be valid. Termination does not justify rewriting eligible historical performance. Non-discretionary portfolios are excluded from composites.","back_vi":"Định nghĩa tiêu chí theo chiến lược trước khi biết return. Đưa mọi tài khoản riêng actual fee-paying discretionary vào ít nhất một composite, và pooled fund đủ tiêu chí vào composite phù hợp. Composite một portfolio có thể hợp lệ. Chấm dứt account không cho phép sửa lịch sử hợp lệ. Portfolio non-discretionary không đưa vào composite.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 258–259; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 196; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 212–214","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-04-LOS04","letter":"d","title_en":"Fundamentals of Compliance, Firm and Discretion","outcome_en":"describe the fundamentals of compliance, including the recommendations of the GIPS standards with respect to the definition of the firm and the firm’s definition of discretion","overview_vi":"Học Fundamentals of Compliance, Firm and Discretion. Phân biệt requirements và recommendations; kiểm tra phạm vi áp dụng trước khi kết luận. Ghi chú Kaplan/SAPP là nội dung bổ trợ nếu được nêu rõ. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF pp. 259"},{"id":"Kaplan SchweserNotes 2026 — Book 4 Reading 92","pages":"Physical PDF pp. 196–197"},{"id":"SAPP CFA Level I 2026 — Ethics slides Module 4","pages":"Physical PDF pp. 215–221"}],"sections":[{"heading":"Definition of the firm","body":"Phạm vi claim là corporation, subsidiary hoặc division được giới thiệu ra bên ngoài như một business entity riêng biệt. Firm-wide áp dụng trong phạm vi định nghĩa hợp lệ, không nhất thiết toàn bộ corporate parent đa ngành. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.]","trap":"Không chọn desk tùy ý chỉ vì kết quả tốt."},{"heading":"Broadest meaningful definition","body":"Khuyến nghị dùng định nghĩa rộng nhất có ý nghĩa, bao gồm geographic offices cùng brand dù legal names khác nhau. Điều này hạn chế chọn chi nhánh tốt để claim. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.]","trap":"Broadest meaningful là recommendation; firm definition hợp lệ là requirement."},{"heading":"Discretion and restrictions","body":"Discretion trong GIPS xét khả năng thực hiện strategy dự kiến. Client restriction được ghi nhận nếu cản trở đến mức portfolio không đại diện strategy thì có thể phân loại nondiscretionary. Nondiscretionary portfolios không được vào composites. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.]","trap":"Restriction nhỏ không tự động làm mất discretion."},{"heading":"Policies, consistent implementation","body":"Firm cần xác lập và duy trì controls, policies và procedures để thiết lập và duy trì compliance; áp dụng nhất quán và đảm bảo dữ liệu có cơ sở. Các quy trình phải phù hợp với applicable laws/regulations và không trình bày sai lệch. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.]","trap":"Slide trang 218 thiếu từ phủ định trong câu false/misleading; CFAI p259 khẳng định không false hoặc misleading."},{"heading":"Reports to prospective clients","body":"CFAI yêu cầu nền tảng gồm cung cấp GIPS Reports cho prospective clients và một số prospective pooled fund investors. SAPP đề cập reasonable efforts, cung cấp danh sách composite descriptions theo yêu cầu, terminated composites giữ trong danh sách tối thiểu 5 năm và mốc 12 tháng; đây là chi tiết nguồn slide, cần kiểm tra văn bản GIPS 2020 đầy đủ trước khi áp dụng thực tế. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.]","trap":"Không tự biến ghi chú slide thành toàn văn điều kiện áp dụng cho mọi pooled fund."},{"heading":"Total firm assets and sub-advisers","body":"Theo slide p220, tổng assets là fair value của discretionary và nondiscretionary, fee-paying và non-fee-paying assets thực quản lý; gồm tài sản giao sub-adviser nếu firm có discretion chọn sub-adviser. Không chỉ tính composite assets. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.]","trap":"Không cộng trùng tài sản giao sub-adviser trong tổng."},{"heading":"Organizational change and joint marketing","body":"Slide p220 nêu thay đổi tổ chức không được dẫn đến sửa historical composite performance; joint marketing phải chỉ rõ firm nào claim và tách phạm vi các tổ chức khác. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.]","trap":"Không chuyển claim tự động sang affiliate."},{"heading":"Prohibited partial or misleading claim","body":"Không dùng wording compliance except for hoặc claim cho riêng methodology thay cho full compliance. Slide p219 ghi ngoại lệ cho firm compliant khi báo performance của individual portfolio cho chính client đó; không quảng bá một portfolio là GIPS compliant cho prospects. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.]","trap":"Phân biệt báo cáo riêng cho khách hàng với claim cấp sản phẩm."},{"heading":"Recommendations and requirements","body":"Recommendations gồm verification, broadest meaningful firm, best-practice guidance; slide còn nêu annual presentation cho existing client. Requirements gồm applicable rules/laws, firm-wide, truthful presentation và documented consistently applied procedures. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.]","trap":"Không biến recommendation thành requirement chỉ vì có lợi."},{"heading":"Firm boundaries and discretion: distinguish constraints from underperformance","body":"Firm được xác định theo thực thể kinh doanh giới thiệu với khách; khuyến nghị phạm vi rộng nhất có ý nghĩa, gồm văn phòng cùng thương hiệu. Ghi nhận hạn chế và xét liệu chúng thật sự ngăn triển khai chiến lược. Underperformance hoặc hạn chế vẫn cho phép triển khai đại diện không tự biến account thành non-discretionary.","body_en":"A firm is defined by the business entity presented to clients; the broadest meaningful definition, including offices under a common brand, is recommended. Document restrictions and evaluate whether they actually prevent implementation of the intended strategy. Ordinary underperformance or a client restriction that still permits representative implementation does not automatically make an account non-discretionary.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 259; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 196–197; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 215–221","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Define boundaries","expr":"Distinct business entity → common brand/geographic scope → firm-wide controls","meaning":"Xác lập phạm vi có ý nghĩa trước khi tính AUM và claim.","conditions":"Không giới hạn theo performance."},{"name":"Discretion decision","expr":"Document restriction → test strategy implementation → classify → apply consistently","meaning":"Không chỉ xét tên hợp đồng hoặc quyền giao dịch trên giấy.","conditions":"Non-discretionary không vào composites."}],"examples":[{"question_en":"Two branches use the same brand and offer the same services. Management proposes excluding the weaker branch from the GIPS firm definition solely due to its track record. What is most appropriate?","steps_vi":["Xác định vấn đề: GIPS 4d. Xét đúng dữ kiện và điều kiện được nêu.","Khuyến nghị phạm vi rộng có ý nghĩa gồm offices cùng brand; không dùng performance để chọn phạm vi."],"answer":"Use a meaningful firm definition rather than a performance-based boundary.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A subsidiary is genuinely held out as a distinct asset management business. Its parent also operates unrelated businesses. Which statement is most accurate?","steps_vi":["Xác định vấn đề: GIPS 4d. Xét đúng dữ kiện và điều kiện được nêu.","Distinct business entity có thể là defined firm; full compliance trong phạm vi đó."],"answer":"The subsidiary may be the defined firm if it meets all applicable requirements.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A client prohibits all holdings needed to implement a narrow strategy, and the documented restriction makes its portfolio unrepresentative. What is most appropriate?","steps_vi":["Xác định vấn đề: GIPS 4d. Xét đúng dữ kiện và điều kiện được nêu.","Hạn chế nghiêm trọng khiến strategy không thể thực hiện; nondiscretionary không vào composite."],"answer":"Classify the account as nondiscretionary for that strategy and exclude it from the composite.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A client excludes one small issuer, but the manager can still implement the intended diversified strategy. What is the best next step?","steps_vi":["Xác định vấn đề: GIPS 4d. Xét đúng dữ kiện và điều kiện được nêu.","Restriction phải xét ảnh hưởng khả năng triển khai; không phải cứ restriction là non-discretionary."],"answer":"Evaluate discretion using documented strategy-based criteria.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A joint marketing brochure contains two firms, only one of which claims GIPS compliance. What should the brochure make clear?","steps_vi":["Xác định vấn đề: GIPS 4d. Xét đúng dữ kiện và điều kiện được nêu.","Phạm vi claim phải rõ; affiliate không được hưởng claim qua liên kết."],"answer":"Which distinct firm is claiming compliance.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A firm moves a strategy between internal business units. It proposes rewriting the strategy's historical returns solely to reflect the restructuring. What is most appropriate?","steps_vi":["Xác định vấn đề: GIPS 4d. Xét đúng dữ kiện và điều kiện được nêu.","Thay tổ chức không làm thay actual history; slide nhấn mạnh không alteration."],"answer":"Do not alter historical composite performance because of the organizational change.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"Which practice is least consistent with the fundamentals of GIPS compliance?","steps_vi":["Xác định vấn đề: GIPS 4d. Xét đúng dữ kiện và điều kiện được nêu.","Dữ liệu đúng vẫn có thể trình bày misleading; CFAI yêu cầu không false/misleading."],"answer":"Using accurate numbers in a deliberately misleading performance presentation","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A firm actually manages $80m discretionary fee-paying, $15m nondiscretionary fee-paying and $5m discretionary non-fee-paying assets, with no overlap. What is total firm assets in this simplified example?","steps_vi":["Xác định vấn đề: GIPS 4d. Xét đúng dữ kiện và điều kiện được nêu.","Theo slide p220, cộng cả ba nhóm actual managed assets = 80+15+5=100 triệu."],"answer":"$100m","check":"Original instructional case; conclusion limited to stated facts."}],"questions":[{"stem_en":"Two branches use the same brand and offer the same services. Management proposes excluding the weaker branch from the GIPS firm definition solely due to its track record. What is most appropriate?","options":["Exclude the branch if its returns are below the benchmark.","Define each composite as a separate firm regardless of public identity.","Use a meaningful firm definition rather than a performance-based boundary."],"correct":2,"why_vi":"Khuyến nghị phạm vi rộng có ý nghĩa gồm offices cùng brand; không dùng performance để chọn phạm vi.","trap_vi":"Firm không phải composite.","standard":"GIPS 4d"},{"stem_en":"A subsidiary is genuinely held out as a distinct asset management business. Its parent also operates unrelated businesses. Which statement is most accurate?","options":["Only the entire parent conglomerate can ever claim compliance.","The subsidiary can claim partial compliance for one successful desk.","The subsidiary may be the defined firm if it meets all applicable requirements."],"correct":2,"why_vi":"Distinct business entity có thể là defined firm; full compliance trong phạm vi đó.","trap_vi":"Firm-wide không luôn đồng nhất legal parent.","standard":"GIPS 4d"},{"stem_en":"A client prohibits all holdings needed to implement a narrow strategy, and the documented restriction makes its portfolio unrepresentative. What is most appropriate?","options":["Classify the account as nondiscretionary for that strategy and exclude it from the composite.","Include it solely because it pays fees.","Classify every restricted portfolio as nondiscretionary without review."],"correct":0,"why_vi":"Hạn chế nghiêm trọng khiến strategy không thể thực hiện; nondiscretionary không vào composite.","trap_vi":"Không tự động loại mọi restricted account.","standard":"GIPS 4d"},{"stem_en":"A client excludes one small issuer, but the manager can still implement the intended diversified strategy. What is the best next step?","options":["Automatically remove the portfolio from all composites.","Ignore every client restriction in all cases.","Evaluate discretion using documented strategy-based criteria."],"correct":2,"why_vi":"Restriction phải xét ảnh hưởng khả năng triển khai; không phải cứ restriction là non-discretionary.","trap_vi":"Facts quan trọng hơn nhãn restriction.","standard":"GIPS 4d"},{"stem_en":"A joint marketing brochure contains two firms, only one of which claims GIPS compliance. What should the brochure make clear?","options":["That both firms are compliant because they share the brochure.","That the claim applies to the jointly marketed product only.","Which distinct firm is claiming compliance."],"correct":2,"why_vi":"Phạm vi claim phải rõ; affiliate không được hưởng claim qua liên kết.","trap_vi":"Không suy rộng compliance.","standard":"GIPS 4d"},{"stem_en":"A firm moves a strategy between internal business units. It proposes rewriting the strategy's historical returns solely to reflect the restructuring. What is most appropriate?","options":["Replace historical actual returns with the new unit's returns.","Remove all prior history whenever the reporting line changes.","Do not alter historical composite performance because of the organizational change."],"correct":2,"why_vi":"Thay tổ chức không làm thay actual history; slide nhấn mạnh không alteration.","trap_vi":"Không lấy structure hiện tại viết lại performance quá khứ.","standard":"GIPS 4d"},{"stem_en":"Which practice is least consistent with the fundamentals of GIPS compliance?","options":["Using accurate numbers in a deliberately misleading performance presentation","Documenting and consistently applying calculation procedures","Complying with applicable performance-reporting laws"],"correct":0,"why_vi":"Dữ liệu đúng vẫn có thể trình bày misleading; CFAI yêu cầu không false/misleading.","trap_vi":"Không chỉ kiểm tra arithmetic.","standard":"GIPS 4d"},{"stem_en":"A firm actually manages $80m discretionary fee-paying, $15m nondiscretionary fee-paying and $5m discretionary non-fee-paying assets, with no overlap. What is total firm assets in this simplified example?","options":["$80m","$100m","$95m"],"correct":1,"why_vi":"Theo slide p220, cộng cả ba nhóm actual managed assets = 80+15+5=100 triệu.","trap_vi":"80 chỉ tính fee-paying discretionary; 95 bỏ non-fee-paying.","standard":"GIPS 4d"},{"stem_en":"Two offices use the same public brand and jointly market the same strategies. Management wants to exclude the lower-return office solely to improve its GIPS claim. Which response best reflects the fundamentals?","options":["Exclude the office because any geographic boundary is permissible.","Use the broadest meaningful firm definition rather than select offices by performance.","Claim compliance for the best composite only."],"correct":1,"why_en":"Firm boundaries should not be selected to cherry-pick returns.","why_vi":"Không chọn phạm vi firm để chọn lọc hiệu suất.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 259; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 196–197; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 215–221","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Firm boundaries and discretion: distinguish constraints from underperformance"},{"stem_en":"A client imposes a documented restriction that prevents a manager from implementing the intended strategy sufficiently for the account to remain representative. The account may most appropriately be classified as:","options":["non-discretionary for composite purposes.","a separate composite solely because its return is lower.","discretionary in all cases because the manager receives a fee."],"correct":0,"why_en":"Discretion depends on ability to implement the strategy; documented material restrictions may make the account non-discretionary.","why_vi":"Discretion tùy khả năng triển khai; hạn chế trọng yếu có thể khiến account non-discretionary.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 259; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 196–197; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 215–221","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Firm boundaries and discretion: distinguish constraints from underperformance"}],"cards":[{"front_en":"Definition of the firm","back_vi":"Phạm vi claim là corporation, subsidiary hoặc division được giới thiệu ra bên ngoài như một business entity riêng biệt. Firm-wide áp dụng trong phạm vi định nghĩa hợp lệ, không nhất thiết toàn bộ corporate parent đa ngành. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.] | Exam trap: Không chọn desk tùy ý chỉ vì kết quả tốt."},{"front_en":"Broadest meaningful definition","back_vi":"Khuyến nghị dùng định nghĩa rộng nhất có ý nghĩa, bao gồm geographic offices cùng brand dù legal names khác nhau. Điều này hạn chế chọn chi nhánh tốt để claim. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.] | Exam trap: Broadest meaningful là recommendation; firm definition hợp lệ là requirement."},{"front_en":"Discretion and restrictions","back_vi":"Discretion trong GIPS xét khả năng thực hiện strategy dự kiến. Client restriction được ghi nhận nếu cản trở đến mức portfolio không đại diện strategy thì có thể phân loại nondiscretionary. Nondiscretionary portfolios không được vào composites. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.] | Exam trap: Restriction nhỏ không tự động làm mất discretion."},{"front_en":"Policies, consistent implementation","back_vi":"Firm cần xác lập và duy trì controls, policies và procedures để thiết lập và duy trì compliance; áp dụng nhất quán và đảm bảo dữ liệu có cơ sở. Các quy trình phải phù hợp với applicable laws/regulations và không trình bày sai lệch. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.] | Exam trap: Slide trang 218 thiếu từ phủ định trong câu false/misleading; CFAI p259 khẳng định không false hoặc misleading."},{"front_en":"Reports to prospective clients","back_vi":"CFAI yêu cầu nền tảng gồm cung cấp GIPS Reports cho prospective clients và một số prospective pooled fund investors. SAPP đề cập reasonable efforts, cung cấp danh sách composite descriptions theo yêu cầu, terminated composites giữ trong danh sách tối thiểu 5 năm và mốc 12 tháng; đây là chi tiết nguồn slide, cần kiểm tra văn bản GIPS 2020 đầy đủ trước khi áp dụng thực tế. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.] | Exam trap: Không tự biến ghi chú slide thành toàn văn điều kiện áp dụng cho mọi pooled fund."},{"front_en":"Total firm assets and sub-advisers","back_vi":"Theo slide p220, tổng assets là fair value của discretionary và nondiscretionary, fee-paying và non-fee-paying assets thực quản lý; gồm tài sản giao sub-adviser nếu firm có discretion chọn sub-adviser. Không chỉ tính composite assets. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.] | Exam trap: Không cộng trùng tài sản giao sub-adviser trong tổng."},{"front_en":"Organizational change and joint marketing","back_vi":"Slide p220 nêu thay đổi tổ chức không được dẫn đến sửa historical composite performance; joint marketing phải chỉ rõ firm nào claim và tách phạm vi các tổ chức khác. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.] | Exam trap: Không chuyển claim tự động sang affiliate."},{"front_en":"Prohibited partial or misleading claim","back_vi":"Không dùng wording compliance except for hoặc claim cho riêng methodology thay cho full compliance. Slide p219 ghi ngoại lệ cho firm compliant khi báo performance của individual portfolio cho chính client đó; không quảng bá một portfolio là GIPS compliant cho prospects. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.] | Exam trap: Phân biệt báo cáo riêng cho khách hàng với claim cấp sản phẩm."},{"front_en":"Recommendations and requirements","back_vi":"Recommendations gồm verification, broadest meaningful firm, best-practice guidance; slide còn nêu annual presentation cho existing client. Requirements gồm applicable rules/laws, firm-wide, truthful presentation và documented consistently applied procedures. [CFAI PDF pp. 259; Kaplan pp. 196–197; SAPP pp. 215–221.] | Exam trap: Không biến recommendation thành requirement chỉ vì có lợi."},{"front_en":"Define boundaries — decision framework?","back_vi":"Distinct business entity → common brand/geographic scope → firm-wide controls · Xác lập phạm vi có ý nghĩa trước khi tính AUM và claim. · Không giới hạn theo performance."},{"front_en":"Discretion decision — decision framework?","back_vi":"Document restriction → test strategy implementation → classify → apply consistently · Không chỉ xét tên hợp đồng hoặc quyền giao dịch trên giấy. · Non-discretionary không vào composites."},{"front_en":"Two branches use the same brand and offer the same services. Management proposes excluding the weaker branch from the GIPS firm definition solely due to its track record. What is most appropriate?","back_vi":"Use a meaningful firm definition rather than a performance-based boundary. — Khuyến nghị phạm vi rộng có ý nghĩa gồm offices cùng brand; không dùng performance để chọn phạm vi. | Exam trap: Firm không phải composite."},{"front_en":"A subsidiary is genuinely held out as a distinct asset management business. Its parent also operates unrelated businesses. Which statement is most accurate?","back_vi":"The subsidiary may be the defined firm if it meets all applicable requirements. — Distinct business entity có thể là defined firm; full compliance trong phạm vi đó. | Exam trap: Firm-wide không luôn đồng nhất legal parent."},{"front_en":"A client prohibits all holdings needed to implement a narrow strategy, and the documented restriction makes its portfolio unrepresentative. What is most appropriate?","back_vi":"Classify the account as nondiscretionary for that strategy and exclude it from the composite. — Hạn chế nghiêm trọng khiến strategy không thể thực hiện; nondiscretionary không vào composite. | Exam trap: Không tự động loại mọi restricted account."},{"front_en":"A client excludes one small issuer, but the manager can still implement the intended diversified strategy. What is the best next step?","back_vi":"Evaluate discretion using documented strategy-based criteria. — Restriction phải xét ảnh hưởng khả năng triển khai; không phải cứ restriction là non-discretionary. | Exam trap: Facts quan trọng hơn nhãn restriction."},{"front_en":"A joint marketing brochure contains two firms, only one of which claims GIPS compliance. What should the brochure make clear?","back_vi":"Which distinct firm is claiming compliance. — Phạm vi claim phải rõ; affiliate không được hưởng claim qua liên kết. | Exam trap: Không suy rộng compliance."},{"front_en":"A firm moves a strategy between internal business units. It proposes rewriting the strategy's historical returns solely to reflect the restructuring. What is most appropriate?","back_vi":"Do not alter historical composite performance because of the organizational change. — Thay tổ chức không làm thay actual history; slide nhấn mạnh không alteration. | Exam trap: Không lấy structure hiện tại viết lại performance quá khứ."},{"front_en":"Which practice is least consistent with the fundamentals of GIPS compliance?","back_vi":"Using accurate numbers in a deliberately misleading performance presentation — Dữ liệu đúng vẫn có thể trình bày misleading; CFAI yêu cầu không false/misleading. | Exam trap: Không chỉ kiểm tra arithmetic."},{"front_en":"A firm actually manages $80m discretionary fee-paying, $15m nondiscretionary fee-paying and $5m discretionary non-fee-paying assets, with no overlap. What is total firm assets in this simplified example?","back_vi":"$100m — Theo slide p220, cộng cả ba nhóm actual managed assets = 80+15+5=100 triệu. | Exam trap: 80 chỉ tính fee-paying discretionary; 95 bỏ non-fee-paying."},{"front_en":"Firm boundaries and discretion: distinguish constraints from underperformance","back_en":"A firm is defined by the business entity presented to clients; the broadest meaningful definition, including offices under a common brand, is recommended. Document restrictions and evaluate whether they actually prevent implementation of the intended strategy. Ordinary underperformance or a client restriction that still permits representative implementation does not automatically make an account non-discretionary.","back_vi":"Firm được xác định theo thực thể kinh doanh giới thiệu với khách; khuyến nghị phạm vi rộng nhất có ý nghĩa, gồm văn phòng cùng thương hiệu. Ghi nhận hạn chế và xét liệu chúng thật sự ngăn triển khai chiến lược. Underperformance hoặc hạn chế vẫn cho phép triển khai đại diện không tự biến account thành non-discretionary.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 259; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 196–197; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 215–221","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]},{"id":"CFA26-10-04-LOS05","letter":"e","title_en":"Independent Verification","outcome_en":"describe the concept of independent verification","overview_vi":"Học Independent Verification. Phân biệt requirements và recommendations; kiểm tra phạm vi áp dụng trước khi kết luận. Ghi chú Kaplan/SAPP là nội dung bổ trợ nếu được nêu rõ. V7.3: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF pp. 259–260"},{"id":"Kaplan SchweserNotes 2026 — Book 4 Reading 92","pages":"Physical PDF pp. 197–198"},{"id":"SAPP CFA Level I 2026 — Ethics slides Module 4","pages":"Physical PDF pp. 221–223"}],"sections":[{"heading":"Responsibility remains with firm","body":"Firm tự chịu trách nhiệm claim và duy trì compliance; thuê verifier không chuyển nghĩa vụ cho bên thứ ba. Verification được khuyến nghị và tự nguyện. [CFAI PDF pp. 259–260; Kaplan pp. 197–198; SAPP pp. 221–223.]","trap":"Không phải điều kiện bắt buộc để claim."},{"heading":"Independence and scope","body":"Nếu chọn verification, phải do independent third party thực hiện theo procedures yêu cầu, trên firm-wide basis. Compliance department của firm không thể tự làm independent verification. [CFAI PDF pp. 259–260; Kaplan pp. 197–198; SAPP pp. 221–223.]","trap":"Không verification một composite đơn lẻ thay cho toàn firm."},{"heading":"Assurance on design and implementation","body":"Verification kiểm tra policies/procedures về composite và pooled fund maintenance, calculation, presentation và distribution of performance, xem thiết kế phù hợp và triển khai toàn firm. [CFAI PDF pp. 259–260; Kaplan pp. 197–198; SAPP pp. 221–223.]","trap":"Không chỉ kiểm một vài return hoặc dữ liệu một sản phẩm."},{"heading":"Limits of verification","body":"Verification không đảm bảo độ chính xác của một performance report cụ thể, không chứng nhận future return và không loại trừ mọi lỗi. Report accuracy là câu hỏi khác với assurance về processes. [CFAI PDF pp. 259–260; Kaplan pp. 197–198; SAPP pp. 221–223.]","trap":"Không nhầm verification với guarantee hay endorsement."},{"heading":"Benefits and disclosure","body":"Verification tăng confidence, credibility và có thể cải thiện kiến thức performance team, consistency và controls. Kaplan có ví dụ disclosure về thời kỳ verified, verifier và availability của verification report; chỉ nêu nếu đúng thực tế. [CFAI PDF pp. 259–260; Kaplan pp. 197–198; SAPP pp. 221–223.]","trap":"Không dùng từ verified nếu chưa được independent verification."},{"heading":"Verification versus accuracy of a particular report","body":"Firm compliant vẫn chịu trách nhiệm claim. Independent verification tự nguyện; nếu thực hiện, đánh giá thiết kế và triển khai quy trình liên quan trên toàn firm. Không bảo đảm độ chính xác số học của một report riêng hoặc kết quả tương lai. Kiểm tra nội bộ cải thiện controls nhưng không phải independent verification.","body_en":"A compliant firm retains responsibility for its claim. Independent verification is optional; if undertaken it assesses firm-wide design and implementation of relevant policies and procedures. It does not guarantee the numerical accuracy of an individual report or future performance. Internal testing can improve controls but is not independent verification.","trap":"Tự biên soạn, đối chiếu có trọng tâm; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 259–260; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 197–198; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 221–223","origin":"studyhub","review_status":"targeted_source_comparison_v73"}],"formulas":[{"name":"Verification decision","expr":"Firm claims and maintains compliance → optional independent verifier → firm-wide assurance","meaning":"Assurance về policies/procedures design và implementation.","conditions":"Không bảo đảm report riêng hoặc future returns."}],"examples":[{"question_en":"A firm meets all applicable GIPS requirements but has not hired an independent verifier. Can it claim compliance?","steps_vi":["Xác định vấn đề: GIPS 4e. Xét đúng dữ kiện và điều kiện được nêu.","Firm chịu trách nhiệm full compliance; verification optional, không phải prerequisite."],"answer":"Yes, verification is voluntary.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A firm's internal compliance department tests all performance processes. Can it describe those tests as independent GIPS verification?","steps_vi":["Xác định vấn đề: GIPS 4e. Xét đúng dữ kiện và điều kiện được nêu.","Internal review hữu ích nhưng không đáp ứng independent third party requirement."],"answer":"No, verification requires an independent third party.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A third party is engaged to verify only the firm's flagship composite. Which conclusion is most appropriate?","steps_vi":["Xác định vấn đề: GIPS 4e. Xét đúng dữ kiện và điều kiện được nêu.","Verification toàn defined firm, không riêng composite."],"answer":"That engagement does not constitute firm-wide GIPS verification.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"What does GIPS verification primarily provide assurance about?","steps_vi":["Xác định vấn đề: GIPS 4e. Xét đúng dữ kiện và điều kiện được nêu.","Verification xem processes liên quan composites, pooled funds, calculation, presentation và distribution."],"answer":"Firm-wide design and implementation of relevant performance policies and procedures","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A verified firm later discovers a material reporting problem. Who remains responsible for correcting and maintaining compliance?","steps_vi":["Xác định vấn đề: GIPS 4e. Xét đúng dữ kiện và điều kiện được nêu.","Firm luôn tự chịu trách nhiệm claim; verifier không thay nghĩa vụ."],"answer":"The firm","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A prospect argues that verification removes the need to evaluate investment risk. The most appropriate response is:","steps_vi":["Xác định vấn đề: GIPS 4e. Xét đúng dữ kiện và điều kiện được nêu.","Verification không đánh giá strategy suitability hoặc future returns."],"answer":"Verification improves confidence in relevant processes, not the investment merits of the strategy.","check":"Original instructional case; conclusion limited to stated facts."}],"questions":[{"stem_en":"A firm meets all applicable GIPS requirements but has not hired an independent verifier. Can it claim compliance?","options":["Yes, verification is voluntary.","No, verification is mandatory before any claim.","Yes, but only for a single composite."],"correct":0,"why_vi":"Firm chịu trách nhiệm full compliance; verification optional, không phải prerequisite.","trap_vi":"Không đánh đồng recommendation và requirement.","standard":"GIPS 4e"},{"stem_en":"A firm's internal compliance department tests all performance processes. Can it describe those tests as independent GIPS verification?","options":["Yes, if the department reports to the board.","Yes, if it tests at least one composite per year.","No, verification requires an independent third party."],"correct":2,"why_vi":"Internal review hữu ích nhưng không đáp ứng independent third party requirement.","trap_vi":"Internal governance không thay independence.","standard":"GIPS 4e"},{"stem_en":"A third party is engaged to verify only the firm's flagship composite. Which conclusion is most appropriate?","options":["The firm is verified because the composite is representative.","That engagement does not constitute firm-wide GIPS verification.","Every other composite becomes verified automatically."],"correct":1,"why_vi":"Verification toàn defined firm, không riêng composite.","trap_vi":"Representative sample không đổi scope claim.","standard":"GIPS 4e"},{"stem_en":"What does GIPS verification primarily provide assurance about?","options":["Accuracy of every individual performance report","Firm-wide design and implementation of relevant performance policies and procedures","The firm's ability to outperform in future markets"],"correct":1,"why_vi":"Verification xem processes liên quan composites, pooled funds, calculation, presentation và distribution.","trap_vi":"Không guarantee report accuracy.","standard":"GIPS 4e"},{"stem_en":"A verified firm later discovers a material reporting problem. Who remains responsible for correcting and maintaining compliance?","options":["The firm","The verifier alone","Prospective clients who received the report"],"correct":0,"why_vi":"Firm luôn tự chịu trách nhiệm claim; verifier không thay nghĩa vụ.","trap_vi":"Assurance không chuyển responsibility.","standard":"GIPS 4e"},{"stem_en":"A prospect argues that verification removes the need to evaluate investment risk. The most appropriate response is:","options":["Verification guarantees risk-adjusted outperformance.","Verification improves confidence in relevant processes, not the investment merits of the strategy.","Verification eliminates the need for further due diligence on the manager."],"correct":1,"why_vi":"Verification không đánh giá strategy suitability hoặc future returns.","trap_vi":"Không nhầm assurance với recommendation đầu tư.","standard":"GIPS 4e"},{"stem_en":"A firm’s compliance department tests one composite report and finds no numerical errors. Which statement is most accurate?","options":["This establishes independent firm-wide GIPS verification.","This establishes that every future report will be correct.","This may support internal controls but does not constitute independent firm-wide verification."],"correct":2,"why_en":"Verification requires an independent third party and firm-wide scope.","why_vi":"Verification cần bên thứ ba độc lập và phạm vi toàn firm.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 259–260; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 197–198; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 221–223","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Verification versus accuracy of a particular report"},{"stem_en":"An independently verified firm discovers an error in a specific report. Which conclusion is most accurate?","options":["Verification guarantees every report is accurate, so the error is impossible.","The firm remains responsible for correcting the report and maintaining compliance.","The verifier alone becomes responsible for the firm’s claim."],"correct":1,"why_en":"Verification does not guarantee each report; the firm retains responsibility.","why_vi":"Verification không bảo đảm mọi report; firm vẫn chịu trách nhiệm.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 259–260; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 197–198; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 221–223","origin":"studyhub","review_status":"targeted_source_comparison_v73","archetype":"Verification versus accuracy of a particular report"}],"cards":[{"front_en":"Responsibility remains with firm","back_vi":"Firm tự chịu trách nhiệm claim và duy trì compliance; thuê verifier không chuyển nghĩa vụ cho bên thứ ba. Verification được khuyến nghị và tự nguyện. [CFAI PDF pp. 259–260; Kaplan pp. 197–198; SAPP pp. 221–223.] | Exam trap: Không phải điều kiện bắt buộc để claim."},{"front_en":"Independence and scope","back_vi":"Nếu chọn verification, phải do independent third party thực hiện theo procedures yêu cầu, trên firm-wide basis. Compliance department của firm không thể tự làm independent verification. [CFAI PDF pp. 259–260; Kaplan pp. 197–198; SAPP pp. 221–223.] | Exam trap: Không verification một composite đơn lẻ thay cho toàn firm."},{"front_en":"Assurance on design and implementation","back_vi":"Verification kiểm tra policies/procedures về composite và pooled fund maintenance, calculation, presentation và distribution of performance, xem thiết kế phù hợp và triển khai toàn firm. [CFAI PDF pp. 259–260; Kaplan pp. 197–198; SAPP pp. 221–223.] | Exam trap: Không chỉ kiểm một vài return hoặc dữ liệu một sản phẩm."},{"front_en":"Limits of verification","back_vi":"Verification không đảm bảo độ chính xác của một performance report cụ thể, không chứng nhận future return và không loại trừ mọi lỗi. Report accuracy là câu hỏi khác với assurance về processes. [CFAI PDF pp. 259–260; Kaplan pp. 197–198; SAPP pp. 221–223.] | Exam trap: Không nhầm verification với guarantee hay endorsement."},{"front_en":"Benefits and disclosure","back_vi":"Verification tăng confidence, credibility và có thể cải thiện kiến thức performance team, consistency và controls. Kaplan có ví dụ disclosure về thời kỳ verified, verifier và availability của verification report; chỉ nêu nếu đúng thực tế. [CFAI PDF pp. 259–260; Kaplan pp. 197–198; SAPP pp. 221–223.] | Exam trap: Không dùng từ verified nếu chưa được independent verification."},{"front_en":"Verification decision — decision framework?","back_vi":"Firm claims and maintains compliance → optional independent verifier → firm-wide assurance · Assurance về policies/procedures design và implementation. · Không bảo đảm report riêng hoặc future returns."},{"front_en":"A firm meets all applicable GIPS requirements but has not hired an independent verifier. Can it claim compliance?","back_vi":"Yes, verification is voluntary. — Firm chịu trách nhiệm full compliance; verification optional, không phải prerequisite. | Exam trap: Không đánh đồng recommendation và requirement."},{"front_en":"A firm's internal compliance department tests all performance processes. Can it describe those tests as independent GIPS verification?","back_vi":"No, verification requires an independent third party. — Internal review hữu ích nhưng không đáp ứng independent third party requirement. | Exam trap: Internal governance không thay independence."},{"front_en":"A third party is engaged to verify only the firm's flagship composite. Which conclusion is most appropriate?","back_vi":"That engagement does not constitute firm-wide GIPS verification. — Verification toàn defined firm, không riêng composite. | Exam trap: Representative sample không đổi scope claim."},{"front_en":"What does GIPS verification primarily provide assurance about?","back_vi":"Firm-wide design and implementation of relevant performance policies and procedures — Verification xem processes liên quan composites, pooled funds, calculation, presentation và distribution. | Exam trap: Không guarantee report accuracy."},{"front_en":"A verified firm later discovers a material reporting problem. Who remains responsible for correcting and maintaining compliance?","back_vi":"The firm — Firm luôn tự chịu trách nhiệm claim; verifier không thay nghĩa vụ. | Exam trap: Assurance không chuyển responsibility."},{"front_en":"A prospect argues that verification removes the need to evaluate investment risk. The most appropriate response is:","back_vi":"Verification improves confidence in relevant processes, not the investment merits of the strategy. — Verification không đánh giá strategy suitability hoặc future returns. | Exam trap: Không nhầm assurance với recommendation đầu tư."},{"front_en":"Verification versus accuracy of a particular report","back_en":"A compliant firm retains responsibility for its claim. Independent verification is optional; if undertaken it assesses firm-wide design and implementation of relevant policies and procedures. It does not guarantee the numerical accuracy of an individual report or future performance. Internal testing can improve controls but is not independent verification.","back_vi":"Firm compliant vẫn chịu trách nhiệm claim. Independent verification tự nguyện; nếu thực hiện, đánh giá thiết kế và triển khai quy trình liên quan trên toàn firm. Không bảo đảm độ chính xác số học của một report riêng hoặc kết quả tương lai. Kiểm tra nội bộ cải thiện controls nhưng không phải independent verification.","source_anchor":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10 Physical PDF pp. 259–260; Kaplan SchweserNotes 2026 — Book 4 Reading 92 Physical PDF pp. 197–198; SAPP CFA Level I 2026 — Ethics slides Module 4 Physical PDF pp. 221–223","origin":"studyhub","review_status":"targeted_source_comparison_v73"}]}],"version":"7.3","qa_status":"TARGETED_SOURCE_COMPARISON_PENDING_FINAL"},{"module_id":"CFA26-10-05","module_title":"Ethics Application","subject":"Ethical and Professional Standards","level":"CFA Level I 2026","status":"Source-mapped detailed academic draft; not independently certified","language":"Vietnamese explanations with English terminology and English exam questions","source_policy":"Original bilingual explanations and original English cases informed by CFAI Curriculum 2026 Volume 10, Kaplan Book 4, SAPP Ethics. Publisher questions not reproduced.","disclaimer_vi":"Các tình huống tự biên soạn, dựa trên nguyên tắc Code and Standards. Kết luận chỉ trong phạm vi facts được nêu; chưa có thẩm định học thuật độc lập.","los":[{"id":"CFA26-10-05-LOS01","letter":"a","title_en":"Evaluate Practices, Policies, and Conduct","outcome_en":"evaluate practices, policies, and conduct relative to the CFA Institute Code of Ethics and Standards of Professional Conduct","overview_vi":"Đánh giá conduct và policies theo 23 sub-standards. Xác định facts, duty, phạm vi và best response; không suy thêm facts ngoài đề. V7.4: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF pp. 265–301"},{"id":"Kaplan SchweserNotes 2026 — Book 4 Reading 93","pages":"Physical PDF pp. 200–209"},{"id":"SAPP CFA Level I 2026 — Ethics slides Module 5","pages":"Physical PDF pp. 224–250"}],"sections":[{"heading":"I(A) Knowledge of the Law — evaluate","body":"Khi facts cho thấy vi phạm, kiểm tra quy định áp dụng và yêu cầu nghiêm ngặt hơn; không biết luật không tự miễn trách nhiệm. Dừng hỗ trợ vi phạm, trao đổi supervisor/compliance, tách khỏi hoạt động vi phạm nếu chưa khắc phục. Báo cơ quan ngoài khi luật yêu cầu; CFA Standards không luôn bắt báo ngoài. [CFAI LM5 PDF pp. 266–268; Kaplan R93 pp. 200; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không chỉ báo cáo nội bộ rồi tiếp tục tham gia."},{"heading":"I(B) Independence and Objectivity — evaluate","body":"Đánh giá gift, entertainment, travel, political/other benefits theo khả năng ảnh hưởng judgment. Không nhận lợi ích có thể làm mất độc lập; disclosure không chữa inducement. Employer-approved modest arrangements phải vẫn bảo vệ objectivity. [CFAI LM5 PDF pp. 268–269; Kaplan R93 pp. 200; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không dùng ngưỡng tiền tùy ý như safe harbor."},{"heading":"I(C) Misrepresentation — evaluate","body":"Cấm knowingly misleading statements trong nghề, cả lời nói, written material và omission dữ kiện trọng yếu. Không hứa lợi nhuận không có cơ sở, không nhận công trình người khác là của mình. Cần sửa thông tin khi biết thay đổi khiến presentation trở nên misleading. [CFAI LM5 PDF pp. 269–272; Kaplan R93 pp. 200–201; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không giới hạn misrepresentation vào số liệu giả."},{"heading":"I(D) Misconduct — evaluate","body":"Phân tích fraud, dishonesty, deceit và hành vi làm tổn hại professional reputation, integrity hoặc competence. Không tự động coi mọi vi phạm hành chính hay civil disobedience là misconduct; facts về tính chất hành vi mới quyết định. [CFAI LM5 PDF pp. 272–273; Kaplan R93 pp. 201; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không đánh đồng bị bắt, bị kiện, conviction với kết luận đạo đức tự động."},{"heading":"I(E) Competence — evaluate","body":"Năng lực cần thiết phụ thuộc nhiệm vụ thực tế và thay đổi theo vai trò. Có thể phát triển qua training, mentoring, qualified assistance và preparation phù hợp; phải act with and maintain competence. Poor outcome không tự chứng minh vi phạm. [CFAI LM5 PDF pp. 274–275; Kaplan R93 pp. 201–202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không nhầm credential với năng lực cho mọi lĩnh vực."},{"heading":"II(A) Material Nonpublic Information — evaluate","body":"Hỏi thông tin có ảnh hưởng đáng kể đến quyết định/giá không, đã phổ biến rộng chưa và cá nhân có act/cause others to act hay không. Mosaic theory kết hợp public và nonmaterial nonpublic inputs; không hợp thức hóa MNPI bằng một ít public facts. [CFAI LM5 PDF pp. 275–277; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Suy luận từ confidential hints vẫn có thể là MNPI nếu nội dung material."},{"heading":"II(B) Market Manipulation — evaluate","body":"Information-based manipulation phát tán thông tin sai để đánh lừa. Transaction-based manipulation tạo tín hiệu giá/volume giả; đánh giá intent. Legitimate trades, arbitrage và hedging có thể tác động giá/volume mà không có intent to mislead. [CFAI LM5 PDF pp. 277–278; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Market impact không tự động chứng minh manipulation."},{"heading":"III(A) Loyalty, Prudence, and Care — evaluate","body":"Xác định client hoặc beneficiaries, ưu tiên lợi ích của họ trước employer/personal interests, hành động prudently và care. Contract/disclosure không miễn basic ethical duties. Dùng tài sản và brokerage cho lợi ích client, không chuyển giá trị để phục vụ lợi ích riêng. [CFAI LM5 PDF pp. 278–281; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không coi mọi thiệt hại là breach nếu hành động prudent theo mandate và facts."},{"heading":"III(B) Fair Dealing — evaluate","body":"Khi dissemination và allocation, cho khách hàng cơ hội công bằng theo eligibility, suitability và quy trình pre-established. Service tiers có thể khác nếu disclosed và không bất lợi bất công cho khách hàng khác. Fair không đồng nghĩa identical allocation. [CFAI LM5 PDF pp. 281–282; Kaplan R93 pp. 202–203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không lấy size/commission làm lý do ưu tiên bất công."},{"heading":"III(C) Suitability — evaluate","body":"Advisor thu thập objectives, constraints, experience, risk profile, cập nhật và xét toàn danh mục. Fund manager quản lý theo stated mandate không chịu trách nhiệm suitability riêng từng holder trong vai trò đó. Unsolicited order cần xử lý theo policy và facts, không bỏ qua mismatch. [CFAI LM5 PDF pp. 282–284; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không đánh giá suitability từ return kỳ vọng đơn lẻ."},{"heading":"III(D) Performance Presentation — evaluate","body":"Trình bày thành tích công bằng, chính xác, đầy đủ; phân biệt actual/simulated, predecessor results, periods, gross/net và sources. Không imply track record của entity mới nếu lịch sử thuộc entity khác mà không giải thích. [CFAI LM5 PDF pp. 284–285; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"GIPS compliance hữu ích nhưng III(D) không bắt mọi firm claim GIPS."},{"heading":"III(E) Preservation of Confidentiality — evaluate","body":"Bảo mật thông tin current, former và prospective clients; ngoại lệ khi thông tin liên quan illegal activities của client, disclosure required by law, hoặc client permits. Tuân thủ quy định dữ liệu và quy trình an toàn, không tiết lộ cho mục đích riêng. [CFAI LM5 PDF pp. 285–286; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Former client vẫn được bảo mật."},{"heading":"IV(A) Loyalty to Employers — evaluate","body":"Khi đang làm việc, không dùng thời gian/tài sản/confidential data của employer để cạnh tranh gây hại. Có thể chuẩn bị chuyển việc nếu không xung đột duty; không solicit trước khi rời theo điều kiện áp dụng. Sau khi rời vẫn không được mang proprietary records trái phép. Whistleblowing vì bảo vệ clients/market khác lợi ích cá nhân. [CFAI LM5 PDF pp. 286–289; Kaplan R93 pp. 203–204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không nhầm general knowledge/skills với confidential employer files."},{"heading":"IV(B) Additional Compensation Arrangements — evaluate","body":"Gifts, benefits, compensation hoặc consideration có thể tạo conflict với employer interests cần prior written consent của tất cả parties involved. Dạng tiền, noncash, bonus tương lai đều xét. Disclosure hoặc verbal approval không tự đáp ứng written consent. [CFAI LM5 PDF pp. 289–290; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không nhầm VI(A) disclosure với IV(B) consent."},{"heading":"IV(C) Responsibilities of Supervisors — evaluate","body":"Supervisor có nghĩa vụ reasonable efforts để detect/prevent violations bằng policies, training, monitoring và response. Nếu hệ thống không đủ và không thể cải thiện, từ chối responsibility bằng văn bản; khi có nghi vấn, investigate và hạn chế nguy cơ tiếp diễn. Không strict liability cho mọi hành vi cấp dưới. [CFAI LM5 PDF pp. 290–292; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không chỉ delegate hoặc chờ kết luận cuối cùng khi có red flags."},{"heading":"V(A) Diligence and Reasonable Basis — evaluate","body":"Diligence, independence và thoroughness; đủ basis từ investigation phù hợp. Third-party research/models có thể dùng nếu đánh giá reliability, assumptions và limitations; không bắt mọi analyst tự làm toàn bộ data. Khi material facts chưa xác minh, không assert certainty. [CFAI LM5 PDF pp. 292–293; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không lấy employer approval hoặc danh tiếng vendor thay due diligence."},{"heading":"V(B) Communication with Clients and Prospective Clients — evaluate","body":"Disclose nature of services và costs; basic format/general principles của process, promptly communicate material changes; disclose significant limitations/risks, identify important factors, separate fact and opinion. Không imply model/ratings có ý nghĩa giống nhau nếu methodology khác đáng kể. [CFAI LM5 PDF pp. 293–294; Kaplan R93 pp. 204–205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không thay client communication bằng tài liệu technical không giải thích."},{"heading":"V(C) Record Retention — evaluate","body":"Giữ records thích hợp hỗ trợ analysis, recommendations, actions và investment communications; tuân luật/regulation/firm policy. Trong absence of applicable requirements, CFAI khuyến nghị tối thiểu 7 năm (LM3 guidance). Employer records không tự trở thành property cá nhân. [CFAI LM5 PDF pp. 294–295; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"7 năm không phải universal mandatory rule."},{"heading":"VI(A) Avoid or Disclose Conflicts — evaluate","body":"Avoid conflicts khi hợp lý hoặc disclose đầy đủ công bằng, prominently, plain language, những matters reasonably expected to impair independence/objectivity hoặc interfere duties. Evaluate firm/personal holdings, board seats, compensation, relationships. Không dùng disclosure thay prohibition, consent hay fair dealing. [CFAI LM5 PDF pp. 296; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Boilerplate mơ hồ không đủ nếu conflict cụ thể là material."},{"heading":"VI(B) Priority of Transactions — evaluate","body":"Client và employer transactions có priority trước trades mà member/candidate beneficial owner. Family account không có beneficial interest và là client thực sự cần đối xử công bằng; personal trade không bị cấm tuyệt đối nếu không disadvantage client và tuân rules. Front-running và allocation abuse là bẫy. [CFAI LM5 PDF pp. 296–298; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không dùng tên account thay phân tích beneficial ownership."},{"heading":"VI(C) Referral Fees — evaluate","body":"Disclose với employer, clients và prospects khi thích hợp compensation, consideration hoặc benefit paid/received for referrals, gồm nature/value và cách thức nếu cần. Thực hiện đủ sớm để đánh giá recommendation và cost/conflict. [CFAI LM5 PDF pp. 298–299; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không giới hạn referral fee ở tiền mặt hoặc khoản phí tăng trực tiếp cho client."},{"heading":"VII(A) Conduct as Participants in CFA Institute Programs — evaluate","body":"Không compromise security, validity, integrity, reputation của CFA Institute programs. Không chia sẻ confidential exam content hoặc topics tested/not tested; general opinions, discussion of public curriculum và study strategy không bị cấm nếu không tiết lộ confidential information. [CFAI LM5 PDF pp. 300; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không nhầm phê bình chương trình với disclosure nội dung thi."},{"heading":"VII(B) Reference to CFA Institute, Designation, and Program — evaluate","body":"Dùng CFA designation đúng status, không dùng như danh từ hoặc tên firm, không imply partial designation hay superior investment returns được bảo đảm. Candidate status chỉ khi đáp ứng điều kiện; có thể nêu fact đã passed level nếu đúng, không tự gọi CFA charterholder trước khi awarded. [CFAI LM5 PDF pp. 300–301; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Passing levels khác earning/maintaining charter."},{"heading":"Mandatory disclosure versus confidentiality","body":"Bảo mật không phải lý do chống công bố bắt buộc theo luật. Xác định phạm vi luật yêu cầu và chỉ công bố trong phạm vi đó; tránh phát tán không cần thiết cho bên khác.","body_en":"Confidentiality is not a defense against a legally required disclosure. Determine what the law requires and disclose only within that requirement; avoid unnecessary dissemination to unrelated recipients.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (I(A), III(E)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"Objectivity and independent evidence","body":"Khuyến nghị hấp dẫn thương mại vẫn cần cơ sở nghiên cứu và phán đoán độc lập. Xét nguyên nhân đổi kết luận: chứng cứ mới đáng tin khác áp lực tạo phí.","body_en":"A commercially desirable recommendation still requires a reasonable research basis and independent judgment. Examine the cause of a revised conclusion: credible new evidence is different from pressure to generate fees.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (I(B), V(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"Fair allocation and front-running","body":"Phân biệt đối xử bất công giữa khách và ưu tiên cá nhân. Một chuỗi hành động có thể vi phạm cả hai nếu manager dành phần hấp dẫn cho cá nhân trước khi phân bổ công bằng cho khách.","body_en":"Distinguish discrimination among client accounts from personal priority. A single sequence can violate both where a manager reserves an attractive allocation for a personal account before allocating fairly to clients.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (III(B), VI(B)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"Outside business and consent","body":"Loyalty với employer và thù lao ngoài là nghĩa vụ khác nhau. Cho phép làm ngoài văn phòng không chắc là chấp thuận thù lao cạnh tranh. Xét riêng điều khoản, lôi kéo khách, tài sản firm và chấp thuận.","body_en":"Employer loyalty and additional compensation are distinct duties. Permission to work outside the office is not necessarily consent to a competing compensated arrangement. Analyze terms, client solicitation, use of firm resources and consent separately.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (IV(A), IV(B)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"Competence versus diligence","body":"Competence xét khả năng người làm; diligence xét công việc và cơ sở. Chuyên gia vẫn có thể nghiên cứu cẩu thả; người mới có thể phát triển năng lực với hỗ trợ trước khi hành động. Xét bằng chứng riêng, không suy cả hai từ khoản lỗ.","body_en":"Competence concerns the person's capability; diligence concerns the work and its basis. A specialist can produce careless research, and an inexperienced person can develop competence with support before acting. Assess evidence for each rather than infer both from a loss.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (I(E), V(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"}],"formulas":[{"name":"Identify relevant facts","expr":"Actor/role → action → affected party → duty → timing","meaning":"Tách client, employer, market và personal interests.","conditions":"Không giả định facts không được nêu."},{"name":"Violation or compliant conduct","expr":"Applicable rule → elements → exception → conclusion","meaning":"Phải giải thích logic, không chỉ nhớ standard label.","conditions":"Một hành vi có thể liên quan nhiều standards."},{"name":"Best next action","expr":"Stop prohibited conduct → escalate/document → disclose or obtain consent as required","meaning":"Biện pháp đúng phụ thuộc standard và facts.","conditions":"Disclosure không thay consent, diligence, competence hoặc prohibitions."},{"name":"Law and professional duty","expr":"Applicable law → stricter requirement → avoid/stop violation","meaning":"Đối chiếu I(A) và nghĩa vụ chuyên môn độc lập.","conditions":"Không mặc định báo cáo ngoài luôn bắt buộc."},{"name":"Outcome versus process","expr":"Facts about process and intent → reasonableness → outcome","meaning":"Phân biệt loss với lack of competence/diligence; phân biệt price impact và intent to mislead.","conditions":"Không dùng hindsight như proof of violation."}],"examples":[{"question_en":"A fund administrator discovers that her team deliberately backdates transaction confirmations in breach of applicable law. Her supervisor refuses to stop. What is her best immediate course of action?","steps_vi":["Xác định vấn đề: I(A). Xét đúng dữ kiện và điều kiện được nêu.","I(A) yêu cầu không knowingly assist và dissociate. Dừng xử lý trái luật, escalate và tách khỏi hoạt động; nghỉ việc có thể cần nếu không còn cách hiệu quả."],"answer":"Stop participating in the unlawful process and seek compliance assistance to dissociate.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An issuer offers an analyst a luxury weekend for her family if she publishes a favorable recommendation. Which response is most appropriate?","steps_vi":["Xác định vấn đề: I(B). Xét đúng dữ kiện và điều kiện được nêu.","Lợi ích phụ thuộc favorable recommendation trực tiếp làm ảnh hưởng objective judgment. Phải từ chối, không chỉ disclose."],"answer":"Decline the offer and preserve an independent research conclusion.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A consultant's proposal says a specialist will oversee a new mandate. Before the contract is signed, the consultant learns the specialist has permanently left and knows the client relies on that staffing claim. What should the consultant do?","steps_vi":["Xác định vấn đề: I(C). Xét đúng dữ kiện và điều kiện được nêu.","Omission về nhân sự trọng yếu khiến proposal hiện tại misleading. Cần cập nhật prospective client."],"answer":"Promptly correct the proposal and explain the staffing change.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An analyst intentionally submits fictitious personal expense claims to her employer. The amounts are small and no investment decision is affected. Which assessment is best?","steps_vi":["Xác định vấn đề: I(D). Xét đúng dữ kiện và điều kiện được nêu.","Fictitious expenses là dishonesty trong nghề, không cần thiệt hại investment portfolio."],"answer":"Her dishonesty supports a violation of I(D).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An experienced equity analyst accepts sole responsibility for a complex derivatives book despite knowing she cannot value its positions and has no qualified support. What is the most appropriate action?","steps_vi":["Xác định vấn đề: I(E). Xét đúng dữ kiện và điều kiện được nêu.","I(E) yêu cầu competence phù hợp responsibility; phải xử lý gap trước khi tự đảm nhận nhiệm vụ không đủ năng lực."],"answer":"Obtain the necessary competence or qualified support before undertaking unsupported responsibilities.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A supplier tells an analyst confidentially that a major customer's only factory has been destroyed. The analyst reasonably concludes the information is material and not public. What should she do?","steps_vi":["Xác định vấn đề: II(A). Xét đúng dữ kiện và điều kiện được nêu.","Nguồn ngoài issuer vẫn có thể MNPI. Không trade/cause others to act cho đến khi thông tin public phù hợp."],"answer":"Refrain from trading or causing others to trade on that information.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A trader arranges offsetting transactions between accounts under his control solely to create the appearance of demand before selling his holding. Which assessment is best?","steps_vi":["Xác định vấn đề: II(B). Xét đúng dữ kiện và điều kiện được nêu.","Mục đích tạo apparent demand giả đánh lừa người tham gia; settlement không chữa intent."],"answer":"The conduct is transaction-based market manipulation.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A manager directs client brokerage to a firm that provides her with personal vacation benefits, despite an equally capable lower-cost broker. Which assessment is best?","steps_vi":["Xác định vấn đề: III(A). Xét đúng dữ kiện và điều kiện được nêu.","Client brokerage phải phục vụ client; personal vacation là private benefit."],"answer":"The manager breaches loyalty by using client brokerage for personal benefit.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A research department privately gives a major client its changed sell recommendation one day before other eligible subscribers receive it, solely to reward that client's commissions. Which assessment is best?","steps_vi":["Xác định vấn đề: III(B). Xét đúng dữ kiện và điều kiện được nêu.","Ưu tiên thời điểm material recommendation vì commissions gây bất công; later distribution không xóa lợi thế."],"answer":"The selective early release violates fair dealing.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An adviser recommends placing a client's entire near-term emergency reserve in an illiquid speculative fund without examining liquidity needs. What is the most direct concern?","steps_vi":["Xác định vấn đề: III(C). Xét đúng dữ kiện và điều kiện được nêu.","Suitability đòi hỏi objectives/constraints và portfolio context; disclosure alone không thay assessment."],"answer":"The adviser has not established suitability in the context of the client's circumstances.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A new fund advertises seven years of results, four of which actually belong to a different predecessor vehicle. The presentation does not identify the predecessor. Which action is most appropriate?","steps_vi":["Xác định vấn đề: III(D). Xét đúng dữ kiện và điều kiện được nêu.","Omission khiến reader tưởng fund mới có lịch sử dài hơn thực tế. Phải phân biệt nguồn/kỳ performance."],"answer":"Clearly identify which returns belong to each vehicle and provide relevant context.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A departing employee sends former clients' account balances to an unrelated sales firm without permission or applicable exception. Which assessment is best?","steps_vi":["Xác định vấn đề: III(E). Xét đúng dữ kiện và điều kiện được nêu.","III(E) bao gồm former clients; account balance là confidential information."],"answer":"The disclosure violates preservation of confidentiality.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"Before resigning, an employee exports the firm's proprietary prospect database to use at a competing business she plans to launch. Which assessment is best?","steps_vi":["Xác định vấn đề: IV(A). Xét đúng dữ kiện và điều kiện được nêu.","Chuẩn bị cạnh tranh không cho quyền lấy proprietary data. Hành vi xảy ra trong employment và gây hại employer."],"answer":"The unauthorized taking violates employer loyalty.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A client offers a manager a personal cash bonus next year if her portfolio exceeds its benchmark. The arrangement could conflict with the manager's duties to her employer. What should the manager do before accepting?","steps_vi":["Xác định vấn đề: IV(B). Xét đúng dữ kiện và điều kiện được nêu.","IV(B) yêu cầu prior written consent từ tất cả parties khi potential conflict."],"answer":"Obtain written consent from all parties involved.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A compliance head finds credible evidence of repeated unauthorized trades by a supervised employee. Which action is most appropriate?","steps_vi":["Xác định vấn đề: IV(C). Xét đúng dữ kiện và điều kiện được nêu.","Red flags đòi reasonable investigation và containment. Promise không thay controls."],"answer":"Investigate promptly and implement reasonable measures to prevent further violations.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A junior analyst copies a target price from a promotional newsletter without evaluating its assumptions or reliability and publishes it as her recommendation. Which assessment is best?","steps_vi":["Xác định vấn đề: V(A). Xét đúng dữ kiện và điều kiện được nêu.","Public availability không bảo đảm reliable basis; phải evaluate research trước khi recommend."],"answer":"She lacks an adequately researched reasonable basis.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A discretionary adviser tells a prospect that a service is free but omits a mandatory platform charge that the client must pay to obtain it. Which assessment is best?","steps_vi":["Xác định vấn đề: V(B). Xét đúng dữ kiện và điều kiện được nêu.","Nature/costs của service phải disclose cho clients và prospects; mandatory platform charge là chi phí liên quan."],"answer":"The omission conflicts with V(B)'s obligation to disclose services and associated costs.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An analyst deletes all research support immediately after a recommendation is issued because she believes the conclusion itself is sufficient documentation. Which assessment is best?","steps_vi":["Xác định vấn đề: V(C). Xét đúng dữ kiện và điều kiện được nêu.","Records hỗ trợ basis và communication; final report không thay mọi support."],"answer":"She fails to maintain appropriate supporting records under V(C).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An analyst is asked to cover a company on whose board she serves. An equally qualified unconflicted analyst is available. Which course best addresses the conflict?","steps_vi":["Xác định vấn đề: VI(A). Xét đúng dữ kiện và điều kiện được nêu.","Avoid conflict khi hợp lý; nếu cannot avoid cần meaningful disclosure, không mơ hồ. Board access còn có MNPI concern."],"answer":"Assign the research to the unconflicted analyst and avoid the conflict.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A trader buys a thinly traded security in an account beneficially owned by him immediately before executing a large client buy order that he expects to raise the price. Which assessment is best?","steps_vi":["Xác định vấn đề: VI(B). Xét đúng dữ kiện và điều kiện được nêu.","Front-running đặt personal interest trước client, bất kể size hoặc after-the-fact disclosure."],"answer":"The trader violates priority of transactions.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An adviser receives free professional conference admission for each new client referred to another service provider. What should she do?","steps_vi":["Xác định vấn đề: VI(C). Xét đúng dữ kiện và điều kiện được nêu.","Noncash benefit có giá trị và có thể ảnh hưởng recommendation; VI(C) áp dụng."],"answer":"Disclose the referral arrangement and the nature of the noncash benefit as appropriate.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"After an exam, a candidate posts a reconstruction of several actual exam questions in a private study group. Which assessment is best?","steps_vi":["Xác định vấn đề: VII(A). Xét đúng dữ kiện và điều kiện được nêu.","Confidential exam content không được chia sẻ, kể cả nhóm private và sau thi."],"answer":"The disclosure compromises program integrity under VII(A).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A person who has passed all three CFA exams but has not been awarded the charter writes 'CFA charterholder' in a client brochure. Which assessment is best?","steps_vi":["Xác định vấn đề: VII(B). Xét đúng dữ kiện và điều kiện được nêu.","Chưa được awarded charter thì không dùng status charterholder; nêu fact passed exams nếu đúng."],"answer":"The reference misrepresents the person's status under VII(B).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A market's local securities rules permit trading on confidential takeover information. A CFA candidate receives a material, nonpublic takeover announcement from a director and places a personal order before publication. Which conclusion is most accurate?","steps_vi":["Xác định vấn đề: I(A), II(A). Xét đúng dữ kiện và điều kiện được nêu.","I(A) yêu cầu áp dụng stricter rule, ở đây II(A) cấm act on MNPI. Cùng một hành vi có thể vi phạm hai standards."],"answer":"Both the stricter-standard obligation and the MNPI prohibition are implicated.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A portfolio manager allocates favorable fills to her personal account and less favorable fills to eligible client accounts after observing execution prices. Which conclusion is best?","steps_vi":["Xác định vấn đề: III(B), VI(B). Xét đúng dữ kiện và điều kiện được nêu.","Ex post allocation ưu tiên beneficial personal account, bất công với clients; cả III(B) và VI(B)."],"answer":"The practice violates both fair dealing and priority of transactions.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An adviser recommends a leveraged strategy to a retiree, clearly explaining its leverage and fees, but never obtains the client's objectives, risk tolerance or liquidity needs. Which assessment is best?","steps_vi":["Xác định vấn đề: III(C), V(B). Xét đúng dữ kiện và điều kiện được nêu.","V(B) disclosure và III(C) suitability độc lập. Chưa thu thập facts cần thiết để xác định recommendation phù hợp."],"answer":"Suitability remains unsupported despite the communication about costs and leverage.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An employee planning to leave exports confidential client financial profiles from her employer's system to solicit clients at a new firm. There is no permission or legal exception. Which combination is most directly implicated?","steps_vi":["Xác định vấn đề: IV(A), III(E). Xét đúng dữ kiện và điều kiện được nêu.","Taking proprietary records gây hại employer; financial profiles confidential của clients không được sử dụng ngoài scope. IV(A), III(E)."],"answer":"Employer loyalty and preservation of confidentiality","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A planner recommends a third-party service with a mandatory client fee and receives a referral payment. She discloses neither. Which pair is most directly relevant?","steps_vi":["Xác định vấn đề: VI(C), V(B). Xét đúng dữ kiện và điều kiện được nêu.","VI(C) requires referral benefit disclosure; V(B) requires services and associated costs disclosure. Both missing."],"answer":"Referral fees and communication of services and costs","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A non-GIPS-compliant firm tells prospects that it presents performance fairly and accurately without claiming GIPS compliance. Which conclusion is best on these limited facts?","steps_vi":["Xác định vấn đề: III(D), GIPS. Xét đúng dữ kiện và điều kiện được nêu.","III(D) yêu cầu fair accurate complete performance, không mandate GIPS adoption. Không đủ facts để kết luận violation; partial claim không được phép."],"answer":"Lack of GIPS compliance alone does not establish a violation of III(D).","check":"Original instructional case; conclusion limited to stated facts."}],"questions":[{"stem_en":"A fund administrator discovers that her team deliberately backdates transaction confirmations in breach of applicable law. Her supervisor refuses to stop. What is her best immediate course of action?","options":["Stop participating in the unlawful process and seek compliance assistance to dissociate.","Continue processing confirmations while documenting objections.","Resign immediately without first considering any available effective dissociation measures."],"correct":0,"why_vi":"I(A) yêu cầu không knowingly assist và dissociate. Dừng xử lý trái luật, escalate và tách khỏi hoạt động; nghỉ việc có thể cần nếu không còn cách hiệu quả.","trap_vi":"Phản đối bằng lời không đủ nếu vẫn tiếp tay; resignation không tự động là bước đầu duy nhất.","standard":"I(A)"},{"stem_en":"An issuer offers an analyst a luxury weekend for her family if she publishes a favorable recommendation. Which response is most appropriate?","options":["Decline the offer and preserve an independent research conclusion.","Accept the trip and disclose it in a footnote.","Accept the trip provided the issuer does not edit the final report."],"correct":0,"why_vi":"Lợi ích phụ thuộc favorable recommendation trực tiếp làm ảnh hưởng objective judgment. Phải từ chối, không chỉ disclose.","trap_vi":"Disclosure không chữa quid pro quo.","standard":"I(B)"},{"stem_en":"A consultant's proposal says a specialist will oversee a new mandate. Before the contract is signed, the consultant learns the specialist has permanently left and knows the client relies on that staffing claim. What should the consultant do?","options":["Wait until the client asks about the specialist after funding.","Keep the proposal unchanged because it was accurate on its original date.","Promptly correct the proposal and explain the staffing change."],"correct":2,"why_vi":"Omission về nhân sự trọng yếu khiến proposal hiện tại misleading. Cần cập nhật prospective client.","trap_vi":"Từng đúng không có nghĩa tiếp tục đúng khi facts thay đổi.","standard":"I(C)"},{"stem_en":"An analyst intentionally submits fictitious personal expense claims to her employer. The amounts are small and no investment decision is affected. Which assessment is best?","options":["No violation occurs unless client investments are harmed.","The conduct is outside the Standards because the amounts are small.","Her dishonesty supports a violation of I(D)."],"correct":2,"why_vi":"Fictitious expenses là dishonesty trong nghề, không cần thiệt hại investment portfolio.","trap_vi":"Materiality của số tiền không là safe harbor cho fraud.","standard":"I(D)"},{"stem_en":"An experienced equity analyst accepts sole responsibility for a complex derivatives book despite knowing she cannot value its positions and has no qualified support. What is the most appropriate action?","options":["Rely on her equity experience and learn after placing trades.","Obtain the necessary competence or qualified support before undertaking unsupported responsibilities.","Disclose the gap to clients and proceed without safeguards."],"correct":1,"why_vi":"I(E) yêu cầu competence phù hợp responsibility; phải xử lý gap trước khi tự đảm nhận nhiệm vụ không đủ năng lực.","trap_vi":"Disclosure không thay competence.","standard":"I(E)"},{"stem_en":"A supplier tells an analyst confidentially that a major customer's only factory has been destroyed. The analyst reasonably concludes the information is material and not public. What should she do?","options":["Refrain from trading or causing others to trade on that information.","Trade because the information did not come directly from the issuer.","Share the information with selected clients so they can decide independently."],"correct":0,"why_vi":"Nguồn ngoài issuer vẫn có thể MNPI. Không trade/cause others to act cho đến khi thông tin public phù hợp.","trap_vi":"Source identity không quyết định materiality.","standard":"II(A)"},{"stem_en":"A trader arranges offsetting transactions between accounts under his control solely to create the appearance of demand before selling his holding. Which assessment is best?","options":["The conduct is acceptable because beneficial ownership is unchanged.","The conduct is transaction-based market manipulation.","The conduct is acceptable if all trades settle normally."],"correct":1,"why_vi":"Mục đích tạo apparent demand giả đánh lừa người tham gia; settlement không chữa intent.","trap_vi":"Không cần chứng minh eventual profit.","standard":"II(B)"},{"stem_en":"A manager directs client brokerage to a firm that provides her with personal vacation benefits, despite an equally capable lower-cost broker. Which assessment is best?","options":["The manager complies if total portfolio returns remain positive.","The manager complies if the benefit is recorded as a marketing expense.","The manager breaches loyalty by using client brokerage for personal benefit."],"correct":2,"why_vi":"Client brokerage phải phục vụ client; personal vacation là private benefit.","trap_vi":"Disclosure/accounting label không chuyển client asset thành personal resource.","standard":"III(A)"},{"stem_en":"A research department privately gives a major client its changed sell recommendation one day before other eligible subscribers receive it, solely to reward that client's commissions. Which assessment is best?","options":["The early release is fair because the client pays more commissions.","The selective early release violates fair dealing.","The release is fair if other clients eventually receive the report."],"correct":1,"why_vi":"Ưu tiên thời điểm material recommendation vì commissions gây bất công; later distribution không xóa lợi thế.","trap_vi":"Fair dealing không chỉ xét có gửi report hay không.","standard":"III(B)"},{"stem_en":"An adviser recommends placing a client's entire near-term emergency reserve in an illiquid speculative fund without examining liquidity needs. What is the most direct concern?","options":["The recommendation is acceptable if expected return is high.","The recommendation is acceptable because illiquidity is disclosed.","The adviser has not established suitability in the context of the client's circumstances."],"correct":2,"why_vi":"Suitability đòi hỏi objectives/constraints và portfolio context; disclosure alone không thay assessment.","trap_vi":"High expected return không giải quyết liquidity constraint.","standard":"III(C)"},{"stem_en":"A new fund advertises seven years of results, four of which actually belong to a different predecessor vehicle. The presentation does not identify the predecessor. Which action is most appropriate?","options":["Clearly identify which returns belong to each vehicle and provide relevant context.","Use all returns as the new fund's own because the strategy is similar.","Remove the fund's recent returns and retain only the predecessor record."],"correct":0,"why_vi":"Omission khiến reader tưởng fund mới có lịch sử dài hơn thực tế. Phải phân biệt nguồn/kỳ performance.","trap_vi":"Strategy giống không tự đồng nhất legal vehicle và history.","standard":"III(D)"},{"stem_en":"A departing employee sends former clients' account balances to an unrelated sales firm without permission or applicable exception. Which assessment is best?","options":["The disclosure is acceptable because the clients are former clients.","The disclosure is acceptable if only account balances, not trades, are shared.","The disclosure violates preservation of confidentiality."],"correct":2,"why_vi":"III(E) bao gồm former clients; account balance là confidential information.","trap_vi":"Kết thúc relationship không kết thúc duty.","standard":"III(E)"},{"stem_en":"Before resigning, an employee exports the firm's proprietary prospect database to use at a competing business she plans to launch. Which assessment is best?","options":["The unauthorized taking violates employer loyalty.","Preparations for a new business permit taking employer records.","The taking is acceptable if no prospect has yet been contacted."],"correct":0,"why_vi":"Chuẩn bị cạnh tranh không cho quyền lấy proprietary data. Hành vi xảy ra trong employment và gây hại employer.","trap_vi":"Không cần solicitation đã xảy ra mới có violation.","standard":"IV(A)"},{"stem_en":"A client offers a manager a personal cash bonus next year if her portfolio exceeds its benchmark. The arrangement could conflict with the manager's duties to her employer. What should the manager do before accepting?","options":["Obtain written consent from all parties involved.","Accept now and notify the employer after the bonus is paid.","Obtain the client's verbal approval and omit the employer."],"correct":0,"why_vi":"IV(B) yêu cầu prior written consent từ tất cả parties khi potential conflict.","trap_vi":"Timing, writing và parties đều quan trọng.","standard":"IV(B)"},{"stem_en":"A compliance head finds credible evidence of repeated unauthorized trades by a supervised employee. Which action is most appropriate?","options":["Investigate promptly and implement reasonable measures to prevent further violations.","Wait for the next annual audit without taking interim action.","Ask the employee to promise not to repeat the trades and take no further steps."],"correct":0,"why_vi":"Red flags đòi reasonable investigation và containment. Promise không thay controls.","trap_vi":"Supervision bao gồm detection và prevention.","standard":"IV(C)"},{"stem_en":"A junior analyst copies a target price from a promotional newsletter without evaluating its assumptions or reliability and publishes it as her recommendation. Which assessment is best?","options":["She complies because the newsletter is publicly available.","She lacks an adequately researched reasonable basis.","She complies if the recommendation later proves profitable."],"correct":1,"why_vi":"Public availability không bảo đảm reliable basis; phải evaluate research trước khi recommend.","trap_vi":"Không dùng hindsight để chứng minh diligence.","standard":"V(A)"},{"stem_en":"A discretionary adviser tells a prospect that a service is free but omits a mandatory platform charge that the client must pay to obtain it. Which assessment is best?","options":["The charge is irrelevant because it is collected by another entity.","The omission conflicts with V(B)'s obligation to disclose services and associated costs.","No cost disclosure is required until after the first investment is made."],"correct":1,"why_vi":"Nature/costs của service phải disclose cho clients và prospects; mandatory platform charge là chi phí liên quan.","trap_vi":"Không chỉ disclose advisory fee trực tiếp.","standard":"V(B)"},{"stem_en":"An analyst deletes all research support immediately after a recommendation is issued because she believes the conclusion itself is sufficient documentation. Which assessment is best?","options":["The published recommendation always replaces its supporting records.","She fails to maintain appropriate supporting records under V(C).","Record retention is required only for recommendations that lose money."],"correct":1,"why_vi":"Records hỗ trợ basis và communication; final report không thay mọi support.","trap_vi":"V(C) độc lập với outcome.","standard":"V(C)"},{"stem_en":"An analyst is asked to cover a company on whose board she serves. An equally qualified unconflicted analyst is available. Which course best addresses the conflict?","options":["Keep the assignment and disclose only that conflicts may exist in general.","Assign the research to the unconflicted analyst and avoid the conflict.","Keep the assignment because board service provides superior access."],"correct":1,"why_vi":"Avoid conflict khi hợp lý; nếu cannot avoid cần meaningful disclosure, không mơ hồ. Board access còn có MNPI concern.","trap_vi":"Không lấy access làm lý do ưu tiên conflict.","standard":"VI(A)"},{"stem_en":"A trader buys a thinly traded security in an account beneficially owned by him immediately before executing a large client buy order that he expects to raise the price. Which assessment is best?","options":["The trader violates priority of transactions.","The trader complies if the personal order is smaller than the client order.","The trader complies if he tells the client after execution."],"correct":0,"why_vi":"Front-running đặt personal interest trước client, bất kể size hoặc after-the-fact disclosure.","trap_vi":"Không dùng trade size như ngoại lệ.","standard":"VI(B)"},{"stem_en":"An adviser receives free professional conference admission for each new client referred to another service provider. What should she do?","options":["Disclose the referral arrangement and the nature of the noncash benefit as appropriate.","Omit disclosure because no cash is received.","Disclose only if the referred client loses money."],"correct":0,"why_vi":"Noncash benefit có giá trị và có thể ảnh hưởng recommendation; VI(C) áp dụng.","trap_vi":"Không cần cash hoặc realized loss.","standard":"VI(C)"},{"stem_en":"After an exam, a candidate posts a reconstruction of several actual exam questions in a private study group. Which assessment is best?","options":["The disclosure is acceptable because the group is private.","The disclosure compromises program integrity under VII(A).","The disclosure is acceptable once the candidate has submitted the exam."],"correct":1,"why_vi":"Confidential exam content không được chia sẻ, kể cả nhóm private và sau thi.","trap_vi":"Privacy của recipient không tạo exception.","standard":"VII(A)"},{"stem_en":"A person who has passed all three CFA exams but has not been awarded the charter writes 'CFA charterholder' in a client brochure. Which assessment is best?","options":["Passing the exams alone permits the charterholder claim.","The reference misrepresents the person's status under VII(B).","The claim is acceptable if the person intends to apply for membership."],"correct":1,"why_vi":"Chưa được awarded charter thì không dùng status charterholder; nêu fact passed exams nếu đúng.","trap_vi":"Intent to apply không tạo designation.","standard":"VII(B)"},{"stem_en":"A market's local securities rules permit trading on confidential takeover information. A CFA candidate receives a material, nonpublic takeover announcement from a director and places a personal order before publication. Which conclusion is most accurate?","options":["Only the MNPI prohibition is implicated because I(A) applies solely to local law.","Both the stricter-standard obligation and the MNPI prohibition are implicated.","Neither standard applies because the trade was lawful locally."],"correct":1,"why_vi":"I(A) yêu cầu áp dụng stricter rule, ở đây II(A) cấm act on MNPI. Cùng một hành vi có thể vi phạm hai standards.","trap_vi":"Không chọn local law chỉ vì dễ hơn.","standard":"I(A), II(A)"},{"stem_en":"A portfolio manager allocates favorable fills to her personal account and less favorable fills to eligible client accounts after observing execution prices. Which conclusion is best?","options":["The practice violates only suitability because prices differed.","The practice is acceptable if every account receives some shares.","The practice violates both fair dealing and priority of transactions."],"correct":2,"why_vi":"Ex post allocation ưu tiên beneficial personal account, bất công với clients; cả III(B) và VI(B).","trap_vi":"Receiving some allocation không chứng minh fairness.","standard":"III(B), VI(B)"},{"stem_en":"An adviser recommends a leveraged strategy to a retiree, clearly explaining its leverage and fees, but never obtains the client's objectives, risk tolerance or liquidity needs. Which assessment is best?","options":["There is no violation because disclosure establishes suitability.","Suitability remains unsupported despite the communication about costs and leverage.","The adviser must recommend the highest-return strategy regardless of the client's circumstances."],"correct":1,"why_vi":"V(B) disclosure và III(C) suitability độc lập. Chưa thu thập facts cần thiết để xác định recommendation phù hợp.","trap_vi":"Informed communication không thay suitability assessment.","standard":"III(C), V(B)"},{"stem_en":"An employee planning to leave exports confidential client financial profiles from her employer's system to solicit clients at a new firm. There is no permission or legal exception. Which combination is most directly implicated?","options":["Suitability and performance presentation only","Employer loyalty and preservation of confidentiality","Market manipulation and referral fees only"],"correct":1,"why_vi":"Taking proprietary records gây hại employer; financial profiles confidential của clients không được sử dụng ngoài scope. IV(A), III(E).","trap_vi":"Không coi client data là personal contacts được tự mang đi.","standard":"IV(A), III(E)"},{"stem_en":"A planner recommends a third-party service with a mandatory client fee and receives a referral payment. She discloses neither. Which pair is most directly relevant?","options":["Record retention and market manipulation","Referral fees and communication of services and costs","Competence and performance presentation only"],"correct":1,"why_vi":"VI(C) requires referral benefit disclosure; V(B) requires services and associated costs disclosure. Both missing.","trap_vi":"Không nhầm referral benefit với phí service; hai disclosures có mục tiêu riêng.","standard":"VI(C), V(B)"},{"stem_en":"A non-GIPS-compliant firm tells prospects that it presents performance fairly and accurately without claiming GIPS compliance. Which conclusion is best on these limited facts?","options":["Every CFA member's firm must claim GIPS compliance.","The firm may describe its best product as partially GIPS compliant.","Lack of GIPS compliance alone does not establish a violation of III(D)."],"correct":2,"why_vi":"III(D) yêu cầu fair accurate complete performance, không mandate GIPS adoption. Không đủ facts để kết luận violation; partial claim không được phép.","trap_vi":"Ethical duty applies independently of voluntary GIPS adoption.","standard":"III(D), GIPS"},{"stem_en":"A regulator lawfully requires specified records of a current client. The client objects to release. The adviser should most appropriately:","options":["refuse because confidentiality always takes precedence.","provide the required records within the legal scope.","release the client's entire file publicly."],"correct":1,"why_en":"III(E) allows legally required disclosure; I(A) requires obeying applicable law. Neither refusal nor unrestricted publication is justified.","why_vi":"III(E) cho phép công bố luật yêu cầu; I(A) yêu cầu tuân luật. Không nên từ chối hay công bố vô giới hạn.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (I(A), III(E)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"I(A), III(E)"},{"stem_en":"A banking director threatens to reduce an analyst's bonus unless she recommends a client issuer. The analyst issues the favorable report without supporting analysis. Which standards are most directly implicated?","options":["I(B) only.","V(A) only.","Both I(B) and V(A)."],"correct":2,"why_en":"Commercial pressure compromises objectivity and the unsupported report lacks a reasonable basis. Both duties apply independently.","why_vi":"Áp lực thương mại làm suy yếu độc lập và báo cáo thiếu cơ sở; cả hai nghĩa vụ áp dụng độc lập.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (I(B), V(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"I(B), V(A)"},{"stem_en":"A manager gives her own account the entire allocation of an oversubscribed issue ahead of suitable client orders, contrary to the neutral allocation rule. Which assessment is most accurate?","options":["Both client fair dealing and priority of transactions are compromised.","Only the firm's reporting format is relevant.","No violation if the manager's personal account is also suitable."],"correct":0,"why_en":"Suitability is not a defense for personal priority or unfair allocation; III(B) and VI(B) both matter.","why_vi":"Suitability không biện minh ưu tiên cá nhân hay phân bổ bất công; III(B) và VI(B) đều liên quan.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (III(B), VI(B)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"III(B), VI(B)"},{"stem_en":"A full-time adviser accepts fees for a competing advisory business and solicits her employer's clients while still employed, without consent. Which assessment is most accurate?","options":["Only IV(B) is relevant.","Both IV(A) and IV(B) are implicated.","Neither applies because the business is outside office hours."],"correct":1,"why_en":"Active competition and solicitation violate loyalty; the conflicting fee arrangement also requires prior written consent.","why_vi":"Cạnh tranh/lôi kéo khách vi phạm loyalty; thỏa thuận phí xung đột cũng cần chấp thuận văn bản trước.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (IV(A), IV(B)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"IV(A), IV(B)"},{"stem_en":"A qualified bond analyst intentionally skips the required credit review and issues a buy recommendation without evidence. The most directly established violation is:","options":["VII(B), because the analyst is qualified.","III(E), because the recommendation is published.","V(A), because the recommendation lacks diligence and a reasonable basis."],"correct":2,"why_en":"The facts directly establish deficient research, not necessarily lack of competence or misuse of a designation.","why_vi":"Facts trực tiếp chứng minh nghiên cứu thiếu, không nhất thiết thiếu năng lực hay sai designation.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (I(E), V(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"I(E), V(A)"}],"cards":[{"front_en":"I(A) Knowledge of the Law — evaluate","back_vi":"Khi facts cho thấy vi phạm, kiểm tra quy định áp dụng và yêu cầu nghiêm ngặt hơn; không biết luật không tự miễn trách nhiệm. Dừng hỗ trợ vi phạm, trao đổi supervisor/compliance, tách khỏi hoạt động vi phạm nếu chưa khắc phục. Báo cơ quan ngoài khi luật yêu cầu; CFA Standards không luôn bắt báo ngoài. [CFAI LM5 PDF pp. 266–268; Kaplan R93 pp. 200; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không chỉ báo cáo nội bộ rồi tiếp tục tham gia."},{"front_en":"A fund administrator discovers that her team deliberately backdates transaction confirmations in breach of applicable law. Her supervisor refuses to stop. What is her best immediate course of action?","back_vi":"Stop participating in the unlawful process and seek compliance assistance to dissociate. — I(A) yêu cầu không knowingly assist và dissociate. Dừng xử lý trái luật, escalate và tách khỏi hoạt động; nghỉ việc có thể cần nếu không còn cách hiệu quả. | Exam trap: Phản đối bằng lời không đủ nếu vẫn tiếp tay; resignation không tự động là bước đầu duy nhất."},{"front_en":"I(B) Independence and Objectivity — evaluate","back_vi":"Đánh giá gift, entertainment, travel, political/other benefits theo khả năng ảnh hưởng judgment. Không nhận lợi ích có thể làm mất độc lập; disclosure không chữa inducement. Employer-approved modest arrangements phải vẫn bảo vệ objectivity. [CFAI LM5 PDF pp. 268–269; Kaplan R93 pp. 200; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không dùng ngưỡng tiền tùy ý như safe harbor."},{"front_en":"An issuer offers an analyst a luxury weekend for her family if she publishes a favorable recommendation. Which response is most appropriate?","back_vi":"Decline the offer and preserve an independent research conclusion. — Lợi ích phụ thuộc favorable recommendation trực tiếp làm ảnh hưởng objective judgment. Phải từ chối, không chỉ disclose. | Exam trap: Disclosure không chữa quid pro quo."},{"front_en":"I(C) Misrepresentation — evaluate","back_vi":"Cấm knowingly misleading statements trong nghề, cả lời nói, written material và omission dữ kiện trọng yếu. Không hứa lợi nhuận không có cơ sở, không nhận công trình người khác là của mình. Cần sửa thông tin khi biết thay đổi khiến presentation trở nên misleading. [CFAI LM5 PDF pp. 269–272; Kaplan R93 pp. 200–201; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không giới hạn misrepresentation vào số liệu giả."},{"front_en":"A consultant's proposal says a specialist will oversee a new mandate. Before the contract is signed, the consultant learns the specialist has permanently left and knows the client relies on that staffing claim. What should the consultant do?","back_vi":"Promptly correct the proposal and explain the staffing change. — Omission về nhân sự trọng yếu khiến proposal hiện tại misleading. Cần cập nhật prospective client. | Exam trap: Từng đúng không có nghĩa tiếp tục đúng khi facts thay đổi."},{"front_en":"I(D) Misconduct — evaluate","back_vi":"Phân tích fraud, dishonesty, deceit và hành vi làm tổn hại professional reputation, integrity hoặc competence. Không tự động coi mọi vi phạm hành chính hay civil disobedience là misconduct; facts về tính chất hành vi mới quyết định. [CFAI LM5 PDF pp. 272–273; Kaplan R93 pp. 201; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không đánh đồng bị bắt, bị kiện, conviction với kết luận đạo đức tự động."},{"front_en":"An analyst intentionally submits fictitious personal expense claims to her employer. The amounts are small and no investment decision is affected. Which assessment is best?","back_vi":"Her dishonesty supports a violation of I(D). — Fictitious expenses là dishonesty trong nghề, không cần thiệt hại investment portfolio. | Exam trap: Materiality của số tiền không là safe harbor cho fraud."},{"front_en":"I(E) Competence — evaluate","back_vi":"Năng lực cần thiết phụ thuộc nhiệm vụ thực tế và thay đổi theo vai trò. Có thể phát triển qua training, mentoring, qualified assistance và preparation phù hợp; phải act with and maintain competence. Poor outcome không tự chứng minh vi phạm. [CFAI LM5 PDF pp. 274–275; Kaplan R93 pp. 201–202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không nhầm credential với năng lực cho mọi lĩnh vực."},{"front_en":"An experienced equity analyst accepts sole responsibility for a complex derivatives book despite knowing she cannot value its positions and has no qualified support. What is the most appropriate action?","back_vi":"Obtain the necessary competence or qualified support before undertaking unsupported responsibilities. — I(E) yêu cầu competence phù hợp responsibility; phải xử lý gap trước khi tự đảm nhận nhiệm vụ không đủ năng lực. | Exam trap: Disclosure không thay competence."},{"front_en":"II(A) Material Nonpublic Information — evaluate","back_vi":"Hỏi thông tin có ảnh hưởng đáng kể đến quyết định/giá không, đã phổ biến rộng chưa và cá nhân có act/cause others to act hay không. Mosaic theory kết hợp public và nonmaterial nonpublic inputs; không hợp thức hóa MNPI bằng một ít public facts. [CFAI LM5 PDF pp. 275–277; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Suy luận từ confidential hints vẫn có thể là MNPI nếu nội dung material."},{"front_en":"A supplier tells an analyst confidentially that a major customer's only factory has been destroyed. The analyst reasonably concludes the information is material and not public. What should she do?","back_vi":"Refrain from trading or causing others to trade on that information. — Nguồn ngoài issuer vẫn có thể MNPI. Không trade/cause others to act cho đến khi thông tin public phù hợp. | Exam trap: Source identity không quyết định materiality."},{"front_en":"II(B) Market Manipulation — evaluate","back_vi":"Information-based manipulation phát tán thông tin sai để đánh lừa. Transaction-based manipulation tạo tín hiệu giá/volume giả; đánh giá intent. Legitimate trades, arbitrage và hedging có thể tác động giá/volume mà không có intent to mislead. [CFAI LM5 PDF pp. 277–278; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Market impact không tự động chứng minh manipulation."},{"front_en":"A trader arranges offsetting transactions between accounts under his control solely to create the appearance of demand before selling his holding. Which assessment is best?","back_vi":"The conduct is transaction-based market manipulation. — Mục đích tạo apparent demand giả đánh lừa người tham gia; settlement không chữa intent. | Exam trap: Không cần chứng minh eventual profit."},{"front_en":"III(A) Loyalty, Prudence, and Care — evaluate","back_vi":"Xác định client hoặc beneficiaries, ưu tiên lợi ích của họ trước employer/personal interests, hành động prudently và care. Contract/disclosure không miễn basic ethical duties. Dùng tài sản và brokerage cho lợi ích client, không chuyển giá trị để phục vụ lợi ích riêng. [CFAI LM5 PDF pp. 278–281; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không coi mọi thiệt hại là breach nếu hành động prudent theo mandate và facts."},{"front_en":"A manager directs client brokerage to a firm that provides her with personal vacation benefits, despite an equally capable lower-cost broker. Which assessment is best?","back_vi":"The manager breaches loyalty by using client brokerage for personal benefit. — Client brokerage phải phục vụ client; personal vacation là private benefit. | Exam trap: Disclosure/accounting label không chuyển client asset thành personal resource."},{"front_en":"III(B) Fair Dealing — evaluate","back_vi":"Khi dissemination và allocation, cho khách hàng cơ hội công bằng theo eligibility, suitability và quy trình pre-established. Service tiers có thể khác nếu disclosed và không bất lợi bất công cho khách hàng khác. Fair không đồng nghĩa identical allocation. [CFAI LM5 PDF pp. 281–282; Kaplan R93 pp. 202–203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không lấy size/commission làm lý do ưu tiên bất công."},{"front_en":"A research department privately gives a major client its changed sell recommendation one day before other eligible subscribers receive it, solely to reward that client's commissions. Which assessment is best?","back_vi":"The selective early release violates fair dealing. — Ưu tiên thời điểm material recommendation vì commissions gây bất công; later distribution không xóa lợi thế. | Exam trap: Fair dealing không chỉ xét có gửi report hay không."},{"front_en":"III(C) Suitability — evaluate","back_vi":"Advisor thu thập objectives, constraints, experience, risk profile, cập nhật và xét toàn danh mục. Fund manager quản lý theo stated mandate không chịu trách nhiệm suitability riêng từng holder trong vai trò đó. Unsolicited order cần xử lý theo policy và facts, không bỏ qua mismatch. [CFAI LM5 PDF pp. 282–284; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không đánh giá suitability từ return kỳ vọng đơn lẻ."},{"front_en":"An adviser recommends placing a client's entire near-term emergency reserve in an illiquid speculative fund without examining liquidity needs. What is the most direct concern?","back_vi":"The adviser has not established suitability in the context of the client's circumstances. — Suitability đòi hỏi objectives/constraints và portfolio context; disclosure alone không thay assessment. | Exam trap: High expected return không giải quyết liquidity constraint."},{"front_en":"III(D) Performance Presentation — evaluate","back_vi":"Trình bày thành tích công bằng, chính xác, đầy đủ; phân biệt actual/simulated, predecessor results, periods, gross/net và sources. Không imply track record của entity mới nếu lịch sử thuộc entity khác mà không giải thích. [CFAI LM5 PDF pp. 284–285; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: GIPS compliance hữu ích nhưng III(D) không bắt mọi firm claim GIPS."},{"front_en":"A new fund advertises seven years of results, four of which actually belong to a different predecessor vehicle. The presentation does not identify the predecessor. Which action is most appropriate?","back_vi":"Clearly identify which returns belong to each vehicle and provide relevant context. — Omission khiến reader tưởng fund mới có lịch sử dài hơn thực tế. Phải phân biệt nguồn/kỳ performance. | Exam trap: Strategy giống không tự đồng nhất legal vehicle và history."},{"front_en":"III(E) Preservation of Confidentiality — evaluate","back_vi":"Bảo mật thông tin current, former và prospective clients; ngoại lệ khi thông tin liên quan illegal activities của client, disclosure required by law, hoặc client permits. Tuân thủ quy định dữ liệu và quy trình an toàn, không tiết lộ cho mục đích riêng. [CFAI LM5 PDF pp. 285–286; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Former client vẫn được bảo mật."},{"front_en":"A departing employee sends former clients' account balances to an unrelated sales firm without permission or applicable exception. Which assessment is best?","back_vi":"The disclosure violates preservation of confidentiality. — III(E) bao gồm former clients; account balance là confidential information. | Exam trap: Kết thúc relationship không kết thúc duty."},{"front_en":"IV(A) Loyalty to Employers — evaluate","back_vi":"Khi đang làm việc, không dùng thời gian/tài sản/confidential data của employer để cạnh tranh gây hại. Có thể chuẩn bị chuyển việc nếu không xung đột duty; không solicit trước khi rời theo điều kiện áp dụng. Sau khi rời vẫn không được mang proprietary records trái phép. Whistleblowing vì bảo vệ clients/market khác lợi ích cá nhân. [CFAI LM5 PDF pp. 286–289; Kaplan R93 pp. 203–204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không nhầm general knowledge/skills với confidential employer files."},{"front_en":"Before resigning, an employee exports the firm's proprietary prospect database to use at a competing business she plans to launch. Which assessment is best?","back_vi":"The unauthorized taking violates employer loyalty. — Chuẩn bị cạnh tranh không cho quyền lấy proprietary data. Hành vi xảy ra trong employment và gây hại employer. | Exam trap: Không cần solicitation đã xảy ra mới có violation."},{"front_en":"IV(B) Additional Compensation Arrangements — evaluate","back_vi":"Gifts, benefits, compensation hoặc consideration có thể tạo conflict với employer interests cần prior written consent của tất cả parties involved. Dạng tiền, noncash, bonus tương lai đều xét. Disclosure hoặc verbal approval không tự đáp ứng written consent. [CFAI LM5 PDF pp. 289–290; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không nhầm VI(A) disclosure với IV(B) consent."},{"front_en":"A client offers a manager a personal cash bonus next year if her portfolio exceeds its benchmark. The arrangement could conflict with the manager's duties to her employer. What should the manager do before accepting?","back_vi":"Obtain written consent from all parties involved. — IV(B) yêu cầu prior written consent từ tất cả parties khi potential conflict. | Exam trap: Timing, writing và parties đều quan trọng."},{"front_en":"IV(C) Responsibilities of Supervisors — evaluate","back_vi":"Supervisor có nghĩa vụ reasonable efforts để detect/prevent violations bằng policies, training, monitoring và response. Nếu hệ thống không đủ và không thể cải thiện, từ chối responsibility bằng văn bản; khi có nghi vấn, investigate và hạn chế nguy cơ tiếp diễn. Không strict liability cho mọi hành vi cấp dưới. [CFAI LM5 PDF pp. 290–292; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không chỉ delegate hoặc chờ kết luận cuối cùng khi có red flags."},{"front_en":"A compliance head finds credible evidence of repeated unauthorized trades by a supervised employee. Which action is most appropriate?","back_vi":"Investigate promptly and implement reasonable measures to prevent further violations. — Red flags đòi reasonable investigation và containment. Promise không thay controls. | Exam trap: Supervision bao gồm detection và prevention."},{"front_en":"V(A) Diligence and Reasonable Basis — evaluate","back_vi":"Diligence, independence và thoroughness; đủ basis từ investigation phù hợp. Third-party research/models có thể dùng nếu đánh giá reliability, assumptions và limitations; không bắt mọi analyst tự làm toàn bộ data. Khi material facts chưa xác minh, không assert certainty. [CFAI LM5 PDF pp. 292–293; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không lấy employer approval hoặc danh tiếng vendor thay due diligence."},{"front_en":"A junior analyst copies a target price from a promotional newsletter without evaluating its assumptions or reliability and publishes it as her recommendation. Which assessment is best?","back_vi":"She lacks an adequately researched reasonable basis. — Public availability không bảo đảm reliable basis; phải evaluate research trước khi recommend. | Exam trap: Không dùng hindsight để chứng minh diligence."},{"front_en":"V(B) Communication with Clients and Prospective Clients — evaluate","back_vi":"Disclose nature of services và costs; basic format/general principles của process, promptly communicate material changes; disclose significant limitations/risks, identify important factors, separate fact and opinion. Không imply model/ratings có ý nghĩa giống nhau nếu methodology khác đáng kể. [CFAI LM5 PDF pp. 293–294; Kaplan R93 pp. 204–205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không thay client communication bằng tài liệu technical không giải thích."},{"front_en":"A discretionary adviser tells a prospect that a service is free but omits a mandatory platform charge that the client must pay to obtain it. Which assessment is best?","back_vi":"The omission conflicts with V(B)'s obligation to disclose services and associated costs. — Nature/costs của service phải disclose cho clients và prospects; mandatory platform charge là chi phí liên quan. | Exam trap: Không chỉ disclose advisory fee trực tiếp."},{"front_en":"V(C) Record Retention — evaluate","back_vi":"Giữ records thích hợp hỗ trợ analysis, recommendations, actions và investment communications; tuân luật/regulation/firm policy. Trong absence of applicable requirements, CFAI khuyến nghị tối thiểu 7 năm (LM3 guidance). Employer records không tự trở thành property cá nhân. [CFAI LM5 PDF pp. 294–295; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: 7 năm không phải universal mandatory rule."},{"front_en":"An analyst deletes all research support immediately after a recommendation is issued because she believes the conclusion itself is sufficient documentation. Which assessment is best?","back_vi":"She fails to maintain appropriate supporting records under V(C). — Records hỗ trợ basis và communication; final report không thay mọi support. | Exam trap: V(C) độc lập với outcome."},{"front_en":"VI(A) Avoid or Disclose Conflicts — evaluate","back_vi":"Avoid conflicts khi hợp lý hoặc disclose đầy đủ công bằng, prominently, plain language, những matters reasonably expected to impair independence/objectivity hoặc interfere duties. Evaluate firm/personal holdings, board seats, compensation, relationships. Không dùng disclosure thay prohibition, consent hay fair dealing. [CFAI LM5 PDF pp. 296; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Boilerplate mơ hồ không đủ nếu conflict cụ thể là material."},{"front_en":"An analyst is asked to cover a company on whose board she serves. An equally qualified unconflicted analyst is available. Which course best addresses the conflict?","back_vi":"Assign the research to the unconflicted analyst and avoid the conflict. — Avoid conflict khi hợp lý; nếu cannot avoid cần meaningful disclosure, không mơ hồ. Board access còn có MNPI concern. | Exam trap: Không lấy access làm lý do ưu tiên conflict."},{"front_en":"VI(B) Priority of Transactions — evaluate","back_vi":"Client và employer transactions có priority trước trades mà member/candidate beneficial owner. Family account không có beneficial interest và là client thực sự cần đối xử công bằng; personal trade không bị cấm tuyệt đối nếu không disadvantage client và tuân rules. Front-running và allocation abuse là bẫy. [CFAI LM5 PDF pp. 296–298; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không dùng tên account thay phân tích beneficial ownership."},{"front_en":"A trader buys a thinly traded security in an account beneficially owned by him immediately before executing a large client buy order that he expects to raise the price. Which assessment is best?","back_vi":"The trader violates priority of transactions. — Front-running đặt personal interest trước client, bất kể size hoặc after-the-fact disclosure. | Exam trap: Không dùng trade size như ngoại lệ."},{"front_en":"VI(C) Referral Fees — evaluate","back_vi":"Disclose với employer, clients và prospects khi thích hợp compensation, consideration hoặc benefit paid/received for referrals, gồm nature/value và cách thức nếu cần. Thực hiện đủ sớm để đánh giá recommendation và cost/conflict. [CFAI LM5 PDF pp. 298–299; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không giới hạn referral fee ở tiền mặt hoặc khoản phí tăng trực tiếp cho client."},{"front_en":"An adviser receives free professional conference admission for each new client referred to another service provider. What should she do?","back_vi":"Disclose the referral arrangement and the nature of the noncash benefit as appropriate. — Noncash benefit có giá trị và có thể ảnh hưởng recommendation; VI(C) áp dụng. | Exam trap: Không cần cash hoặc realized loss."},{"front_en":"VII(A) Conduct as Participants in CFA Institute Programs — evaluate","back_vi":"Không compromise security, validity, integrity, reputation của CFA Institute programs. Không chia sẻ confidential exam content hoặc topics tested/not tested; general opinions, discussion of public curriculum và study strategy không bị cấm nếu không tiết lộ confidential information. [CFAI LM5 PDF pp. 300; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không nhầm phê bình chương trình với disclosure nội dung thi."},{"front_en":"After an exam, a candidate posts a reconstruction of several actual exam questions in a private study group. Which assessment is best?","back_vi":"The disclosure compromises program integrity under VII(A). — Confidential exam content không được chia sẻ, kể cả nhóm private và sau thi. | Exam trap: Privacy của recipient không tạo exception."},{"front_en":"VII(B) Reference to CFA Institute, Designation, and Program — evaluate","back_vi":"Dùng CFA designation đúng status, không dùng như danh từ hoặc tên firm, không imply partial designation hay superior investment returns được bảo đảm. Candidate status chỉ khi đáp ứng điều kiện; có thể nêu fact đã passed level nếu đúng, không tự gọi CFA charterholder trước khi awarded. [CFAI LM5 PDF pp. 300–301; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Passing levels khác earning/maintaining charter."},{"front_en":"A person who has passed all three CFA exams but has not been awarded the charter writes 'CFA charterholder' in a client brochure. Which assessment is best?","back_vi":"The reference misrepresents the person's status under VII(B). — Chưa được awarded charter thì không dùng status charterholder; nêu fact passed exams nếu đúng. | Exam trap: Intent to apply không tạo designation."},{"front_en":"Identify relevant facts — decision framework?","back_vi":"Actor/role → action → affected party → duty → timing · Tách client, employer, market và personal interests. · Không giả định facts không được nêu."},{"front_en":"Violation or compliant conduct — decision framework?","back_vi":"Applicable rule → elements → exception → conclusion · Phải giải thích logic, không chỉ nhớ standard label. · Một hành vi có thể liên quan nhiều standards."},{"front_en":"Best next action — decision framework?","back_vi":"Stop prohibited conduct → escalate/document → disclose or obtain consent as required · Biện pháp đúng phụ thuộc standard và facts. · Disclosure không thay consent, diligence, competence hoặc prohibitions."},{"front_en":"Law and professional duty — decision framework?","back_vi":"Applicable law → stricter requirement → avoid/stop violation · Đối chiếu I(A) và nghĩa vụ chuyên môn độc lập. · Không mặc định báo cáo ngoài luôn bắt buộc."},{"front_en":"Outcome versus process — decision framework?","back_vi":"Facts about process and intent → reasonableness → outcome · Phân biệt loss với lack of competence/diligence; phân biệt price impact và intent to mislead. · Không dùng hindsight như proof of violation."},{"front_en":"A market's local securities rules permit trading on confidential takeover information. A CFA candidate receives a material, nonpublic takeover announcement from a director and places a personal order before publication. Which conclusion is most accurate?","back_vi":"Both the stricter-standard obligation and the MNPI prohibition are implicated. — I(A) yêu cầu áp dụng stricter rule, ở đây II(A) cấm act on MNPI. Cùng một hành vi có thể vi phạm hai standards. | Exam trap: Không chọn local law chỉ vì dễ hơn."},{"front_en":"A portfolio manager allocates favorable fills to her personal account and less favorable fills to eligible client accounts after observing execution prices. Which conclusion is best?","back_vi":"The practice violates both fair dealing and priority of transactions. — Ex post allocation ưu tiên beneficial personal account, bất công với clients; cả III(B) và VI(B). | Exam trap: Receiving some allocation không chứng minh fairness."},{"front_en":"An adviser recommends a leveraged strategy to a retiree, clearly explaining its leverage and fees, but never obtains the client's objectives, risk tolerance or liquidity needs. Which assessment is best?","back_vi":"Suitability remains unsupported despite the communication about costs and leverage. — V(B) disclosure và III(C) suitability độc lập. Chưa thu thập facts cần thiết để xác định recommendation phù hợp. | Exam trap: Informed communication không thay suitability assessment."},{"front_en":"An employee planning to leave exports confidential client financial profiles from her employer's system to solicit clients at a new firm. There is no permission or legal exception. Which combination is most directly implicated?","back_vi":"Employer loyalty and preservation of confidentiality — Taking proprietary records gây hại employer; financial profiles confidential của clients không được sử dụng ngoài scope. IV(A), III(E). | Exam trap: Không coi client data là personal contacts được tự mang đi."},{"front_en":"A planner recommends a third-party service with a mandatory client fee and receives a referral payment. She discloses neither. Which pair is most directly relevant?","back_vi":"Referral fees and communication of services and costs — VI(C) requires referral benefit disclosure; V(B) requires services and associated costs disclosure. Both missing. | Exam trap: Không nhầm referral benefit với phí service; hai disclosures có mục tiêu riêng."},{"front_en":"A non-GIPS-compliant firm tells prospects that it presents performance fairly and accurately without claiming GIPS compliance. Which conclusion is best on these limited facts?","back_vi":"Lack of GIPS compliance alone does not establish a violation of III(D). — III(D) yêu cầu fair accurate complete performance, không mandate GIPS adoption. Không đủ facts để kết luận violation; partial claim không được phép. | Exam trap: Ethical duty applies independently of voluntary GIPS adoption."},{"front_en":"Mandatory disclosure versus confidentiality","back_en":"Confidentiality is not a defense against a legally required disclosure. Determine what the law requires and disclose only within that requirement; avoid unnecessary dissemination to unrelated recipients.","back_vi":"Bảo mật không phải lý do chống công bố bắt buộc theo luật. Xác định phạm vi luật yêu cầu và chỉ công bố trong phạm vi đó; tránh phát tán không cần thiết cho bên khác.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (I(A), III(E)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"Objectivity and independent evidence","back_en":"A commercially desirable recommendation still requires a reasonable research basis and independent judgment. Examine the cause of a revised conclusion: credible new evidence is different from pressure to generate fees.","back_vi":"Khuyến nghị hấp dẫn thương mại vẫn cần cơ sở nghiên cứu và phán đoán độc lập. Xét nguyên nhân đổi kết luận: chứng cứ mới đáng tin khác áp lực tạo phí.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (I(B), V(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"Fair allocation and front-running","back_en":"Distinguish discrimination among client accounts from personal priority. A single sequence can violate both where a manager reserves an attractive allocation for a personal account before allocating fairly to clients.","back_vi":"Phân biệt đối xử bất công giữa khách và ưu tiên cá nhân. Một chuỗi hành động có thể vi phạm cả hai nếu manager dành phần hấp dẫn cho cá nhân trước khi phân bổ công bằng cho khách.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (III(B), VI(B)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"Outside business and consent","back_en":"Employer loyalty and additional compensation are distinct duties. Permission to work outside the office is not necessarily consent to a competing compensated arrangement. Analyze terms, client solicitation, use of firm resources and consent separately.","back_vi":"Loyalty với employer và thù lao ngoài là nghĩa vụ khác nhau. Cho phép làm ngoài văn phòng không chắc là chấp thuận thù lao cạnh tranh. Xét riêng điều khoản, lôi kéo khách, tài sản firm và chấp thuận.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (IV(A), IV(B)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"Competence versus diligence","back_en":"Competence concerns the person's capability; diligence concerns the work and its basis. A specialist can produce careless research, and an inexperienced person can develop competence with support before acting. Assess evidence for each rather than infer both from a loss.","back_vi":"Competence xét khả năng người làm; diligence xét công việc và cơ sở. Chuyên gia vẫn có thể nghiên cứu cẩu thả; người mới có thể phát triển năng lực với hỗ trợ trước khi hành động. Xét bằng chứng riêng, không suy cả hai từ khoản lỗ.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (I(E), V(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"}]},{"id":"CFA26-10-05-LOS02","letter":"b","title_en":"Explain Compliant and Violating Conduct","outcome_en":"explain how the practices, policies, and conduct do or do not violate the CFA Institute Code of Ethics and Standards of Professional Conduct","overview_vi":"Giải thích vì sao hành vi phù hợp hoặc vi phạm; tách các nghĩa vụ độc lập và điều kiện ngoại lệ. Các tình huống khác LOS 5.a, gồm cases giao thoa nhiều chuẩn. V7.4: bổ sung đối chiếu có trọng tâm; chưa nghiệm thu toàn diện.","source":[{"id":"CFA Institute Curriculum 2026 — Ethical and Professional Standards Volume 10","pages":"Physical PDF pp. 265–301"},{"id":"Kaplan SchweserNotes 2026 — Book 4 Reading 93","pages":"Physical PDF pp. 200–209"},{"id":"SAPP CFA Level I 2026 — Ethics slides Module 5","pages":"Physical PDF pp. 224–250"}],"sections":[{"heading":"I(A) Knowledge of the Law — justify","body":"Đối chiếu duty với facts và exception: Khi local law cho phép nhưng Standards nghiêm hơn, áp dụng Standards; confidentiality vẫn có nghĩa vụ nếu không có exception. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 266–268; Kaplan R93 pp. 200; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Permitted by law khác required by law."},{"heading":"I(B) Independence and Objectivity — justify","body":"Đối chiếu duty với facts và exception: Gift từ client ghi nhận past service không mặc nhiên bị cấm; disclosure và firm policy được thực hiện, không có future contingent compensation. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 268–269; Kaplan R93 pp. 200; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Đừng nhầm unsolicited thank-you với additional compensation arrangement."},{"heading":"I(C) Misrepresentation — justify","body":"Đối chiếu duty với facts và exception: Misrepresentation ở guarantee không có cơ sở; đúng số lịch sử không làm prediction chắc chắn. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 269–272; Kaplan R93 pp. 200–201; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Historical performance không đảm bảo future return."},{"heading":"I(D) Misconduct — justify","body":"Đối chiếu duty với facts và exception: Facts không cho thấy dishonesty hay adverse professional integrity; không tự suy misconduct từ citation. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 272–273; Kaplan R93 pp. 201; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không thêm facts tiêu cực ngoài đề."},{"heading":"I(E) Competence — justify","body":"Đối chiếu duty với facts và exception: Competence xét knowledge, skill và thực hiện nhiệm vụ, không chỉ realized outcome. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 274–275; Kaplan R93 pp. 201–202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Outcome bias là bẫy."},{"heading":"II(A) Material Nonpublic Information — justify","body":"Đối chiếu duty với facts và exception: Mosaic theory cho phép kết hợp public và nonmaterial nonpublic data thành conclusion material. Facts xác định không dùng MNPI. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 275–277; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Material conclusion khác material input."},{"heading":"II(B) Market Manipulation — justify","body":"Đối chiếu duty với facts và exception: Arbitrage có mục đích kinh tế thật; price/volume effect không đủ nếu không intent to mislead. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 277–278; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Phân biệt market impact với artificial signal."},{"heading":"III(A) Loyalty, Prudence, and Care — justify","body":"Đối chiếu duty với facts và exception: Cần xem agreed obligations và prudence; liquidation đúng điều kiện không tự vi phạm chỉ vì loss. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 278–281; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không dùng realized loss làm test duy nhất."},{"heading":"III(B) Fair Dealing — justify","body":"Đối chiếu duty với facts và exception: Fair khác equal; differentiated service có thể hợp lệ nếu disclosed và không unfairly disadvantage others. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 281–282; Kaplan R93 pp. 202–203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không đồng nhất mức dịch vụ với quyền ưu tiên giao dịch."},{"heading":"III(C) Suitability — justify","body":"Đối chiếu duty với facts và exception: Mandate-based manager khác personal advisor; thực hiện stated strategy. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 282–284; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không áp nghĩa vụ advisory cá nhân cho mọi pooled fund manager."},{"heading":"III(D) Performance Presentation — justify","body":"Đối chiếu duty với facts và exception: III(D) tập trung fair/accurate/complete; giả lập phải minh bạch, không giả làm actual. Facts không chứng minh violation khác. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 284–285; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Hypothetical không mặc nhiên cấm; đánh giá đầy đủ context."},{"heading":"III(E) Preservation of Confidentiality — justify","body":"Đối chiếu duty với facts và exception: Disclosure required by law là exception; giới hạn scope và secure channel. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 285–286; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Legal permission khác legal requirement."},{"heading":"IV(A) Loyalty to Employers — justify","body":"Đối chiếu duty với facts và exception: Knowledge và skill chung khác proprietary documents; facts nêu không breach agreement. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 286–289; Kaplan R93 pp. 203–204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không tự thêm noncompete hoặc trade-secret facts."},{"heading":"IV(B) Additional Compensation Arrangements — justify","body":"Đối chiếu duty với facts và exception: Written disclosure không là approval; explicit refusal cho thấy consent chưa có. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 289–290; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không đánh đồng documented notification và permission."},{"heading":"IV(C) Responsibilities of Supervisors — justify","body":"Đối chiếu duty với facts và exception: IV(C) xét reasonable efforts, không strict liability. Facts không chỉ ra supervisor thiếu efforts. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 290–292; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Kết quả xấu không tự chứng minh process failure."},{"heading":"V(A) Diligence and Reasonable Basis — justify","body":"Đối chiếu duty với facts và exception: V(A) đòi reasonable diligence, không bắt tái tạo mọi dữ liệu; facts có đánh giá nguồn và basis. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 292–293; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Outsourcing không miễn review nhưng không bị cấm tuyệt đối."},{"heading":"V(B) Communication with Clients and Prospective Clients — justify","body":"Đối chiếu duty với facts và exception: V(B) yêu cầu prompt communication of material changes và significant risks/limitations. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 293–294; Kaplan R93 pp. 204–205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không cần đợi loss mới disclose."},{"heading":"V(C) Record Retention — justify","body":"Đối chiếu duty với facts và exception: I(A) và V(C): luật 10 năm áp dụng; recommendation 7 năm khi không có rule khác không override luật. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 294–295; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Mandatory legal period khác recommended fallback."},{"heading":"VI(A) Avoid or Disclose Conflicts — justify","body":"Đối chiếu duty với facts và exception: VI(A) cho avoid or disclose; facts nêu safeguards và prominent disclosure. II(A), I(B) và other duties vẫn áp dụng. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 296; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Disclosure không universal cure."},{"heading":"VI(B) Priority of Transactions — justify","body":"Đối chiếu duty với facts và exception: Facts không beneficial ownership; account là client thực sự, fair dealing áp dụng. Disclose conflict nếu có theo VI(A). Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 296–298; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Family relationship không tự xác lập beneficial ownership."},{"heading":"VI(C) Referral Fees — justify","body":"Đối chiếu duty với facts và exception: VI(C) yêu cầu transparency về paid/received referral benefit; không cấm mọi fee. Other duties remain. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 298–299; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Ai trả phí không xóa incentive."},{"heading":"VII(A) Conduct as Participants in CFA Institute Programs — justify","body":"Đối chiếu duty với facts và exception: General opinions được phép; không tiết lộ confidential exam specifics. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 300; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không nhầm opinion với confidential content."},{"heading":"VII(B) Reference to CFA Institute, Designation, and Program — justify","body":"Đối chiếu duty với facts và exception: Factual accurate reference được phép, không guarantee superior returns. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 300–301; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.]","trap":"Không cấm mọi reference đến CFA designation."},{"heading":"Suitability is not guaranteed by past returns","body":"Lịch sử tốt không chứng minh khuyến nghị phù hợp cá nhân. Phải khớp mục tiêu, hạn chế, toàn danh mục; tuyên bố hiệu suất riêng phải công bằng, chính xác, đầy đủ.","body_en":"A strong historical record does not prove a recommendation suitable for an individual. Match objectives, constraints and portfolio context; performance claims must separately be fair, accurate and complete.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (III(C), III(D)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"Fee transparency and referral incentives","body":"Công bố phí quản lý không tự công bố đối ứng giới thiệu. Khách cần biết chi phí dịch vụ và động cơ giới thiệu liên quan để đánh giá dịch vụ/xung đột.","body_en":"Disclosure of management fees does not automatically disclose referral consideration. Clients need information about service costs and relevant referral incentives to assess the service and conflicts.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (V(B), VI(C)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"Disclosure does not cleanse MNPI","body":"Dù công bố đầy đủ xung đột sở hữu cũng không được giao dịch trên MNPI. Xét tình trạng thông tin và lệnh cấm trước khi xét công bố xung đột.","body_en":"Even full disclosure of an ownership conflict does not permit acting on material nonpublic information. Analyze information status and trading prohibition before considering conflict disclosure.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (II(A), VI(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"Individual and supervisory accountability","body":"Vi phạm cấp dưới không tự chứng minh supervisor vi phạm. Xét nỗ lực hợp lý ngăn ngừa, phát hiện, điều tra, xử lý. Cá nhân vẫn chịu trách nhiệm hành vi của mình.","body_en":"A subordinate's violation does not automatically establish a supervisor's violation. Examine the supervisor's reasonable efforts to prevent, detect, investigate and address misconduct. The individual remains responsible for personal conduct.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (IV(C), I(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"heading":"Program status and confidential information","body":"Nêu đúng thành tích kỳ thi khác tự nhận designation từng phần hoặc tiết lộ nội dung thi mật. Một câu có thể factual trong khi câu khác cùng thông tin vi phạm nghĩa vụ khác.","body_en":"A truthful account of exam achievement differs from a claim of partial designation or an improper disclosure of confidential tested material. One statement can be factual while another in the same communication violates a different obligation.","trap":"Study Hub tự biên soạn; không phải nguyên văn CFAI, chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (VII(A), VII(B)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"}],"formulas":[{"name":"Identify relevant facts","expr":"Actor/role → action → affected party → duty → timing","meaning":"Tách client, employer, market và personal interests.","conditions":"Không giả định facts không được nêu."},{"name":"Violation or compliant conduct","expr":"Applicable rule → elements → exception → conclusion","meaning":"Phải giải thích logic, không chỉ nhớ standard label.","conditions":"Một hành vi có thể liên quan nhiều standards."},{"name":"Best next action","expr":"Stop prohibited conduct → escalate/document → disclose or obtain consent as required","meaning":"Biện pháp đúng phụ thuộc standard và facts.","conditions":"Disclosure không thay consent, diligence, competence hoặc prohibitions."},{"name":"Law and professional duty","expr":"Applicable law → stricter requirement → avoid/stop violation","meaning":"Đối chiếu I(A) và nghĩa vụ chuyên môn độc lập.","conditions":"Không mặc định báo cáo ngoài luôn bắt buộc."},{"name":"Outcome versus process","expr":"Facts about process and intent → reasonableness → outcome","meaning":"Phân biệt loss với lack of competence/diligence; phân biệt price impact và intent to mislead.","conditions":"Không dùng hindsight như proof of violation."}],"examples":[{"question_en":"A local rule permits an adviser to disclose a client's confidential investment information to a marketer, but no disclosure exception under III(E) applies. The adviser does so. Which conclusion is best?","steps_vi":["Xác định vấn đề: I(A). Xét đúng dữ kiện và điều kiện được nêu.","Khi local law cho phép nhưng Standards nghiêm hơn, áp dụng Standards; confidentiality vẫn có nghĩa vụ nếu không có exception."],"answer":"The adviser violates the stricter applicable CFA requirements.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A client unexpectedly sends an adviser a modest gift thanking her for last year's service. No future reward is promised and firm policy requires disclosure. She discloses it promptly and her judgment is unaffected. Which assessment is most appropriate?","steps_vi":["Xác định vấn đề: I(B). Xét đúng dữ kiện và điều kiện được nêu.","Gift từ client ghi nhận past service không mặc nhiên bị cấm; disclosure và firm policy được thực hiện, không có future contingent compensation."],"answer":"The facts support compliance with I(B).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An adviser advertises an unguaranteed equity fund as offering a certain 9% annual return. She includes the fund's actual past return of 9% in the same advertisement. Which statement is most accurate?","steps_vi":["Xác định vấn đề: I(C). Xét đúng dữ kiện và điều kiện được nêu.","Misrepresentation ở guarantee không có cơ sở; đúng số lịch sử không làm prediction chắc chắn."],"answer":"The unsupported guarantee violates I(C), notwithstanding the accurate historical figure.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A portfolio manager receives a minor parking citation unrelated to work, with no dishonesty or other facts suggesting impaired professional integrity. Which conclusion is best supported?","steps_vi":["Xác định vấn đề: I(D). Xét đúng dữ kiện và điều kiện được nêu.","Facts không cho thấy dishonesty hay adverse professional integrity; không tự suy misconduct từ citation."],"answer":"The citation alone does not establish a violation of I(D).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A properly trained bond manager uses an appropriate documented process, but unexpected rate changes lead to a loss. Which conclusion is best?","steps_vi":["Xác định vấn đề: I(E). Xét đúng dữ kiện và điều kiện được nêu.","Competence xét knowledge, skill và thực hiện nhiệm vụ, không chỉ realized outcome."],"answer":"The loss alone does not establish a violation of I(E).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An analyst combines published shipping statistics with confidential but individually nonmaterial observations about product packaging and reaches a material investment conclusion. No material nonpublic input is used. Which assessment is best?","steps_vi":["Xác định vấn đề: II(A). Xét đúng dữ kiện và điều kiện được nêu.","Mosaic theory cho phép kết hợp public và nonmaterial nonpublic data thành conclusion material. Facts xác định không dùng MNPI."],"answer":"The analysis is consistent with mosaic theory.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A manager buys an undervalued cash security and sells a related overpriced derivative to exploit a genuine pricing discrepancy. The trades increase volume, with no intent to mislead. Which assessment is best?","steps_vi":["Xác định vấn đề: II(B). Xét đúng dữ kiện và điều kiện được nêu.","Arbitrage có mục đích kinh tế thật; price/volume effect không đủ nếu không intent to mislead."],"answer":"The facts are consistent with legitimate arbitrage rather than manipulation.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A futures broker liquidates a client's position after a valid margin shortfall in accordance with a clearly disclosed agreement and applicable requirements. No improper motive is present. Which assessment is best?","steps_vi":["Xác định vấn đề: III(A). Xét đúng dữ kiện và điều kiện được nêu.","Cần xem agreed obligations và prudence; liquidation đúng điều kiện không tự vi phạm chỉ vì loss."],"answer":"The resulting client loss alone does not demonstrate a breach of III(A).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A firm openly offers an optional premium analytics service to all eligible clients. All clients receive recommendation changes fairly, and the premium service does not disadvantage standard subscribers. Which statement is most accurate?","steps_vi":["Xác định vấn đề: III(B). Xét đúng dữ kiện và điều kiện được nêu.","Fair khác equal; differentiated service có thể hợp lệ nếu disclosed và không unfairly disadvantage others."],"answer":"The disclosed service differentiation can comply with III(B).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A manager operates a public small-cap equity fund strictly according to its disclosed mandate. She has no advisory relationship with individual unitholders. Which statement is best?","steps_vi":["Xác định vấn đề: III(C). Xét đúng dữ kiện và điều kiện được nêu.","Mandate-based manager khác personal advisor; thực hiện stated strategy."],"answer":"Her duty in this role is to manage the fund consistently with its stated mandate.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An adviser reports a simulated model's historical returns but clearly labels the results hypothetical, discloses relevant limitations, and does not present them as actual client returns. Which assessment is best on the stated facts?","steps_vi":["Xác định vấn đề: III(D). Xét đúng dữ kiện và điều kiện được nêu.","III(D) tập trung fair/accurate/complete; giả lập phải minh bạch, không giả làm actual. Facts không chứng minh violation khác."],"answer":"The labeling addresses the distinction between hypothetical and actual returns.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A valid court order legally requires an adviser to produce specified confidential client documents. She provides only the required records through authorized channels. Which assessment is best?","steps_vi":["Xác định vấn đề: III(E). Xét đúng dữ kiện và điều kiện được nêu.","Disclosure required by law là exception; giới hạn scope và secure channel."],"answer":"The legally required disclosure falls within an exception to III(E).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"After leaving a firm, a former employee reconstructs a general valuation technique from her own knowledge without taking proprietary records or breaching any applicable agreement. Which assessment is best?","steps_vi":["Xác định vấn đề: IV(A). Xét đúng dữ kiện và điều kiện được nêu.","Knowledge và skill chung khác proprietary documents; facts nêu không breach agreement."],"answer":"Using general professional knowledge is not by itself a violation of IV(A).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A manager discloses a conflicting outside compensation agreement to her employer by email, but the employer explicitly declines consent. She accepts the agreement anyway. Which assessment is best?","steps_vi":["Xác định vấn đề: IV(B). Xét đúng dữ kiện và điều kiện được nêu.","Written disclosure không là approval; explicit refusal cho thấy consent chưa có."],"answer":"She violates IV(B) because disclosure is not consent.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A supervisor had reasonable controls, training, monitoring and promptly investigated a concealed isolated violation. Which conclusion is best supported?","steps_vi":["Xác định vấn đề: IV(C). Xét đúng dữ kiện và điều kiện được nêu.","IV(C) xét reasonable efforts, không strict liability. Facts không chỉ ra supervisor thiếu efforts."],"answer":"A subordinate's violation alone does not establish a violation by the supervisor.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An analyst reviews a reputable external data provider's methodology, checks critical assumptions against independent information, documents limitations and uses the results in her own analysis. Which assessment is best?","steps_vi":["Xác định vấn đề: V(A). Xét đúng dữ kiện và điều kiện được nêu.","V(A) đòi reasonable diligence, không bắt tái tạo mọi dữ liệu; facts có đánh giá nguồn và basis."],"answer":"Reliance on external research can be consistent with V(A) when appropriately evaluated.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A manager materially changes the portfolio selection model, adding leverage exposure and a new significant limitation. What is the best response?","steps_vi":["Xác định vấn đề: V(B). Xét đúng dữ kiện và điều kiện được nêu.","V(B) yêu cầu prompt communication of material changes và significant risks/limitations."],"answer":"Promptly communicate the material process change and significant risks to clients.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A jurisdiction requires investment research records to be retained for ten years. A firm proposes deleting them after seven years because of CFA guidance. What is most appropriate?","steps_vi":["Xác định vấn đề: V(C). Xét đúng dữ kiện và điều kiện được nêu.","I(A) và V(C): luật 10 năm áp dụng; recommendation 7 năm khi không có rule khác không override luật."],"answer":"Retain records for the applicable ten-year requirement.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An analyst has a material ownership interest in a covered issuer. The firm determines the conflict cannot reasonably be avoided and permits coverage with safeguards. She discloses the interest prominently in plain language. Which assessment is best on these facts?","steps_vi":["Xác định vấn đề: VI(A). Xét đúng dữ kiện và điều kiện được nêu.","VI(A) cho avoid or disclose; facts nêu safeguards và prominent disclosure. II(A), I(B) và other duties vẫn áp dụng."],"answer":"The disclosure addresses VI(A), subject to the other applicable duties.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A manager's sibling is a fee-paying client with an independently owned account in which the manager has no beneficial interest. The account is eligible for an oversubscribed allocation. How should it be treated?","steps_vi":["Xác định vấn đề: VI(B). Xét đúng dữ kiện và điều kiện được nêu.","Facts không beneficial ownership; account là client thực sự, fair dealing áp dụng. Disclose conflict nếu có theo VI(A)."],"answer":"Under the same fair allocation criteria as other eligible client accounts.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A firm pays a fixed referral fee to an accountant who introduces prospects. A prospect receives the arrangement's relevant disclosure before deciding whether to hire the firm. Which statement is best on these facts?","steps_vi":["Xác định vấn đề: VI(C). Xét đúng dữ kiện và điều kiện được nêu.","VI(C) yêu cầu transparency về paid/received referral benefit; không cấm mọi fee. Other duties remain."],"answer":"The disclosure helps the prospect evaluate the referral incentive and cost or conflict.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A candidate writes publicly that the exam felt difficult and that she prefers another preparation method, without revealing confidential content or tested topics. Which assessment is best?","steps_vi":["Xác định vấn đề: VII(A). Xét đúng dữ kiện và điều kiện được nêu.","General opinions được phép; không tiết lộ confidential exam specifics."],"answer":"Expressing that general opinion is not by itself a violation of VII(A).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A charterholder in good standing tells a prospect that earning the CFA designation required meeting program requirements, and makes no promise of superior returns. Which assessment is best?","steps_vi":["Xác định vấn đề: VII(B). Xét đúng dữ kiện và điều kiện được nêu.","Factual accurate reference được phép, không guarantee superior returns."],"answer":"The factual description can comply with VII(B).","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A sales brochure intentionally presents simulated returns as actual client returns. The calculations are mathematically accurate. Which explanation best supports a violation?","steps_vi":["Xác định vấn đề: I(C), III(D). Xét đúng dữ kiện và điều kiện được nêu.","Misrepresentation và performance presentation xét cách mô tả nguồn return; simulated không được giả làm actual."],"answer":"The false description misrepresents the source of performance and prevents a fair presentation.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A fund distributor offers an analyst a substantial future payment contingent on favorable coverage. The employer gives written consent, and the analyst publicly discloses the arrangement. What is the best explanation?","steps_vi":["Xác định vấn đề: I(B), IV(B), VI(A). Xét đúng dữ kiện và điều kiện được nêu.","IV(B) và VI(A) không chữa I(B) inducement. Cần independently assess objectivity; substantial conditional payment không thể chấp nhận chỉ vì consent/disclosure."],"answer":"Consent and disclosure do not make a payment that compromises objectivity acceptable.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"An analyst performs a documented, robust valuation but destroys supporting workpapers immediately after publication. Which explanation is best?","steps_vi":["Xác định vấn đề: V(A), V(C). Xét đúng dữ kiện và điều kiện được nêu.","V(A) có thể được đáp ứng, V(C) vẫn đòi records appropriate. Không suy violation of research basis chỉ từ việc hủy records, nhưng retention failure độc lập."],"answer":"A reasonable research basis does not remove the duty to retain supporting records.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A supervisor knowingly assigns an untrained staff member sole responsibility for a complex valuation process, despite repeated errors and available training resources. Which rationale is best?","steps_vi":["Xác định vấn đề: I(E), IV(C). Xét đúng dữ kiện và điều kiện được nêu.","I(E) xét năng lực người thực hiện; IV(C) xét reasonable prevention/detection, training/monitoring. Documentation alone không đủ."],"answer":"The staff member's role-specific competence and the supervisor's reasonable preventive efforts are separate issues.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A candidate accurately states that he passed Level I and then reveals specific confidential exam questions to advertise his tutoring service. Which conclusion is best?","steps_vi":["Xác định vấn đề: VII(A), VII(B). Xét đúng dữ kiện và điều kiện được nêu.","Fact passed level có thể nêu đúng; sharing confidential questions violates VII(A). Tách accurate reference và program integrity."],"answer":"The accurate status statement does not excuse a program-integrity violation.","check":"Original instructional case; conclusion limited to stated facts."},{"question_en":"A manager follows a documented allocation policy based on suitability and available capacity; personal orders are placed only after eligible client and employer orders have priority. A small client receives fewer shares than a larger client because of the policy. Which reasoning is best?","steps_vi":["Xác định vấn đề: III(A), III(B), VI(B). Xét đúng dữ kiện và điều kiện được nêu.","Fair treatment có thể khác absolute allocations khi criteria hợp lý; client/employer priority preserved. Facts không cho thấy breach of loyalty."],"answer":"Different share allocations do not by themselves establish unfair dealing when criteria are fair and priorities respected.","check":"Original instructional case; conclusion limited to stated facts."}],"questions":[{"stem_en":"A local rule permits an adviser to disclose a client's confidential investment information to a marketer, but no disclosure exception under III(E) applies. The adviser does so. Which conclusion is best?","options":["The adviser violates the stricter applicable CFA requirements.","The adviser complies because local permission overrides professional standards.","The adviser violates the Standards only if the client suffers a financial loss."],"correct":0,"why_vi":"Khi local law cho phép nhưng Standards nghiêm hơn, áp dụng Standards; confidentiality vẫn có nghĩa vụ nếu không có exception.","trap_vi":"Permitted by law khác required by law.","standard":"I(A)"},{"stem_en":"A client unexpectedly sends an adviser a modest gift thanking her for last year's service. No future reward is promised and firm policy requires disclosure. She discloses it promptly and her judgment is unaffected. Which assessment is most appropriate?","options":["The facts support compliance with I(B).","Any client gift necessarily violates I(B).","IV(B) always requires prior written consent for this unsolicited past-service gift."],"correct":0,"why_vi":"Gift từ client ghi nhận past service không mặc nhiên bị cấm; disclosure và firm policy được thực hiện, không có future contingent compensation.","trap_vi":"Đừng nhầm unsolicited thank-you với additional compensation arrangement.","standard":"I(B)"},{"stem_en":"An adviser advertises an unguaranteed equity fund as offering a certain 9% annual return. She includes the fund's actual past return of 9% in the same advertisement. Which statement is most accurate?","options":["The unsupported guarantee violates I(C), notwithstanding the accurate historical figure.","There is no violation because the historical figure is accurate.","There is no violation if the fund subsequently earns 9%."],"correct":0,"why_vi":"Misrepresentation ở guarantee không có cơ sở; đúng số lịch sử không làm prediction chắc chắn.","trap_vi":"Historical performance không đảm bảo future return.","standard":"I(C)"},{"stem_en":"A portfolio manager receives a minor parking citation unrelated to work, with no dishonesty or other facts suggesting impaired professional integrity. Which conclusion is best supported?","options":["The citation alone does not establish a violation of I(D).","Every legal infraction establishes professional misconduct.","The manager must be barred from all professional activity under I(D)."],"correct":0,"why_vi":"Facts không cho thấy dishonesty hay adverse professional integrity; không tự suy misconduct từ citation.","trap_vi":"Không thêm facts tiêu cực ngoài đề.","standard":"I(D)"},{"stem_en":"A properly trained bond manager uses an appropriate documented process, but unexpected rate changes lead to a loss. Which conclusion is best?","options":["The loss alone does not establish a violation of I(E).","Any negative return establishes incompetence.","Competence exists only if the portfolio outperforms its benchmark."],"correct":0,"why_vi":"Competence xét knowledge, skill và thực hiện nhiệm vụ, không chỉ realized outcome.","trap_vi":"Outcome bias là bẫy.","standard":"I(E)"},{"stem_en":"An analyst combines published shipping statistics with confidential but individually nonmaterial observations about product packaging and reaches a material investment conclusion. No material nonpublic input is used. Which assessment is best?","options":["The conclusion violates II(A) merely because it is material.","Any nonpublic observation makes the recommendation prohibited.","The analysis is consistent with mosaic theory."],"correct":2,"why_vi":"Mosaic theory cho phép kết hợp public và nonmaterial nonpublic data thành conclusion material. Facts xác định không dùng MNPI.","trap_vi":"Material conclusion khác material input.","standard":"II(A)"},{"stem_en":"A manager buys an undervalued cash security and sells a related overpriced derivative to exploit a genuine pricing discrepancy. The trades increase volume, with no intent to mislead. Which assessment is best?","options":["Any paired trades that increase volume violate II(B).","The trade is manipulation whenever prices move in response.","The facts are consistent with legitimate arbitrage rather than manipulation."],"correct":2,"why_vi":"Arbitrage có mục đích kinh tế thật; price/volume effect không đủ nếu không intent to mislead.","trap_vi":"Phân biệt market impact với artificial signal.","standard":"II(B)"},{"stem_en":"A futures broker liquidates a client's position after a valid margin shortfall in accordance with a clearly disclosed agreement and applicable requirements. No improper motive is present. Which assessment is best?","options":["Any liquidation producing a loss breaches III(A).","The broker must ignore the margin agreement to avoid harming the client.","The resulting client loss alone does not demonstrate a breach of III(A)."],"correct":2,"why_vi":"Cần xem agreed obligations và prudence; liquidation đúng điều kiện không tự vi phạm chỉ vì loss.","trap_vi":"Không dùng realized loss làm test duy nhất.","standard":"III(A)"},{"stem_en":"A firm openly offers an optional premium analytics service to all eligible clients. All clients receive recommendation changes fairly, and the premium service does not disadvantage standard subscribers. Which statement is most accurate?","options":["Every client must receive identical services at the same price.","Premium services always violate fair dealing.","The disclosed service differentiation can comply with III(B)."],"correct":2,"why_vi":"Fair khác equal; differentiated service có thể hợp lệ nếu disclosed và không unfairly disadvantage others.","trap_vi":"Không đồng nhất mức dịch vụ với quyền ưu tiên giao dịch.","standard":"III(B)"},{"stem_en":"A manager operates a public small-cap equity fund strictly according to its disclosed mandate. She has no advisory relationship with individual unitholders. Which statement is best?","options":["Her duty in this role is to manage the fund consistently with its stated mandate.","She must individually assess every unitholder's household finances before any fund trade.","She may ignore the stated mandate if several unitholders prefer large-cap stocks."],"correct":0,"why_vi":"Mandate-based manager khác personal advisor; thực hiện stated strategy.","trap_vi":"Không áp nghĩa vụ advisory cá nhân cho mọi pooled fund manager.","standard":"III(C)"},{"stem_en":"An adviser reports a simulated model's historical returns but clearly labels the results hypothetical, discloses relevant limitations, and does not present them as actual client returns. Which assessment is best on the stated facts?","options":["Hypothetical results are necessarily prohibited in every presentation.","The adviser may describe the model's return as actual because the simulation uses market data.","The labeling addresses the distinction between hypothetical and actual returns."],"correct":2,"why_vi":"III(D) tập trung fair/accurate/complete; giả lập phải minh bạch, không giả làm actual. Facts không chứng minh violation khác.","trap_vi":"Hypothetical không mặc nhiên cấm; đánh giá đầy đủ context.","standard":"III(D)"},{"stem_en":"A valid court order legally requires an adviser to produce specified confidential client documents. She provides only the required records through authorized channels. Which assessment is best?","options":["Confidentiality prohibits disclosure even when legally required.","The legally required disclosure falls within an exception to III(E).","She must obtain the client's permission before complying with every valid order."],"correct":1,"why_vi":"Disclosure required by law là exception; giới hạn scope và secure channel.","trap_vi":"Legal permission khác legal requirement.","standard":"III(E)"},{"stem_en":"After leaving a firm, a former employee reconstructs a general valuation technique from her own knowledge without taking proprietary records or breaching any applicable agreement. Which assessment is best?","options":["Every technique learned at work permanently belongs to the former employer.","Using general professional knowledge is not by itself a violation of IV(A).","A former employee may use only methods learned before joining the firm."],"correct":1,"why_vi":"Knowledge và skill chung khác proprietary documents; facts nêu không breach agreement.","trap_vi":"Không tự thêm noncompete hoặc trade-secret facts.","standard":"IV(A)"},{"stem_en":"A manager discloses a conflicting outside compensation agreement to her employer by email, but the employer explicitly declines consent. She accepts the agreement anyway. Which assessment is best?","options":["She complies because the email creates a written record.","She complies if no other client's account is immediately harmed.","She violates IV(B) because disclosure is not consent."],"correct":2,"why_vi":"Written disclosure không là approval; explicit refusal cho thấy consent chưa có.","trap_vi":"Không đánh đồng documented notification và permission.","standard":"IV(B)"},{"stem_en":"A supervisor had reasonable controls, training, monitoring and promptly investigated a concealed isolated violation. Which conclusion is best supported?","options":["Supervisors are automatically liable under IV(C) for every subordinate violation.","A subordinate's violation alone does not establish a violation by the supervisor.","Only a profitable unauthorized trade can establish a supervisory violation."],"correct":1,"why_vi":"IV(C) xét reasonable efforts, không strict liability. Facts không chỉ ra supervisor thiếu efforts.","trap_vi":"Kết quả xấu không tự chứng minh process failure.","standard":"IV(C)"},{"stem_en":"An analyst reviews a reputable external data provider's methodology, checks critical assumptions against independent information, documents limitations and uses the results in her own analysis. Which assessment is best?","options":["V(A) prohibits all external data in investment analysis.","Reliance on external research can be consistent with V(A) when appropriately evaluated.","The analyst must duplicate every original data-collection step regardless of context."],"correct":1,"why_vi":"V(A) đòi reasonable diligence, không bắt tái tạo mọi dữ liệu; facts có đánh giá nguồn và basis.","trap_vi":"Outsourcing không miễn review nhưng không bị cấm tuyệt đối.","standard":"V(A)"},{"stem_en":"A manager materially changes the portfolio selection model, adding leverage exposure and a new significant limitation. What is the best response?","options":["Promptly communicate the material process change and significant risks to clients.","Wait until the next annual review even if clients are making current decisions.","Disclose only if the changed strategy subsequently underperforms."],"correct":0,"why_vi":"V(B) yêu cầu prompt communication of material changes và significant risks/limitations.","trap_vi":"Không cần đợi loss mới disclose.","standard":"V(B)"},{"stem_en":"A jurisdiction requires investment research records to be retained for ten years. A firm proposes deleting them after seven years because of CFA guidance. What is most appropriate?","options":["Delete after seven years because CFA guidance overrides longer legal requirements.","Retain records only until the recommendation is withdrawn.","Retain records for the applicable ten-year requirement."],"correct":2,"why_vi":"I(A) và V(C): luật 10 năm áp dụng; recommendation 7 năm khi không có rule khác không override luật.","trap_vi":"Mandatory legal period khác recommended fallback.","standard":"V(C)"},{"stem_en":"An analyst has a material ownership interest in a covered issuer. The firm determines the conflict cannot reasonably be avoided and permits coverage with safeguards. She discloses the interest prominently in plain language. Which assessment is best on these facts?","options":["Any ownership interest makes research permanently prohibited regardless of facts.","The disclosure addresses VI(A), subject to the other applicable duties.","Disclosure automatically authorizes trading on material nonpublic information."],"correct":1,"why_vi":"VI(A) cho avoid or disclose; facts nêu safeguards và prominent disclosure. II(A), I(B) và other duties vẫn áp dụng.","trap_vi":"Disclosure không universal cure.","standard":"VI(A)"},{"stem_en":"A manager's sibling is a fee-paying client with an independently owned account in which the manager has no beneficial interest. The account is eligible for an oversubscribed allocation. How should it be treated?","options":["Always last because it belongs to a family member.","Under the same fair allocation criteria as other eligible client accounts.","Always first to avoid a personal conflict."],"correct":1,"why_vi":"Facts không beneficial ownership; account là client thực sự, fair dealing áp dụng. Disclose conflict nếu có theo VI(A).","trap_vi":"Family relationship không tự xác lập beneficial ownership.","standard":"VI(B)"},{"stem_en":"A firm pays a fixed referral fee to an accountant who introduces prospects. A prospect receives the arrangement's relevant disclosure before deciding whether to hire the firm. Which statement is best on these facts?","options":["All referral fees are categorically prohibited under VI(C).","The disclosure helps the prospect evaluate the referral incentive and cost or conflict.","Disclosure to prospects is unnecessary whenever the firm pays the fee itself."],"correct":1,"why_vi":"VI(C) yêu cầu transparency về paid/received referral benefit; không cấm mọi fee. Other duties remain.","trap_vi":"Ai trả phí không xóa incentive.","standard":"VI(C)"},{"stem_en":"A candidate writes publicly that the exam felt difficult and that she prefers another preparation method, without revealing confidential content or tested topics. Which assessment is best?","options":["All negative opinions about the exam violate VII(A).","Candidates may discuss actual questions as long as they also criticize the exam.","Expressing that general opinion is not by itself a violation of VII(A)."],"correct":2,"why_vi":"General opinions được phép; không tiết lộ confidential exam specifics.","trap_vi":"Không nhầm opinion với confidential content.","standard":"VII(A)"},{"stem_en":"A charterholder in good standing tells a prospect that earning the CFA designation required meeting program requirements, and makes no promise of superior returns. Which assessment is best?","options":["The factual description can comply with VII(B).","Mentioning the designation in client communications is always prohibited.","The charterholder must claim that the designation guarantees outperformance."],"correct":0,"why_vi":"Factual accurate reference được phép, không guarantee superior returns.","trap_vi":"Không cấm mọi reference đến CFA designation.","standard":"VII(B)"},{"stem_en":"A sales brochure intentionally presents simulated returns as actual client returns. The calculations are mathematically accurate. Which explanation best supports a violation?","options":["Only mathematical calculation errors can violate the Standards.","Disclosure is unnecessary when all underlying market data were real.","The false description misrepresents the source of performance and prevents a fair presentation."],"correct":2,"why_vi":"Misrepresentation và performance presentation xét cách mô tả nguồn return; simulated không được giả làm actual.","trap_vi":"Accurate arithmetic không chữa misleading label.","standard":"I(C), III(D)"},{"stem_en":"A fund distributor offers an analyst a substantial future payment contingent on favorable coverage. The employer gives written consent, and the analyst publicly discloses the arrangement. What is the best explanation?","options":["Consent and disclosure do not make a payment that compromises objectivity acceptable.","Written employer consent overrides all restrictions on analyst compensation.","Public disclosure alone satisfies every relevant Standard."],"correct":0,"why_vi":"IV(B) và VI(A) không chữa I(B) inducement. Cần independently assess objectivity; substantial conditional payment không thể chấp nhận chỉ vì consent/disclosure.","trap_vi":"Không dùng một standard để miễn nghĩa vụ standard khác.","standard":"I(B), IV(B), VI(A)"},{"stem_en":"An analyst performs a documented, robust valuation but destroys supporting workpapers immediately after publication. Which explanation is best?","options":["V(C) applies only when V(A) has been violated.","A reasonable research basis does not remove the duty to retain supporting records.","The published price target is necessarily an adequate replacement for all research records."],"correct":1,"why_vi":"V(A) có thể được đáp ứng, V(C) vẫn đòi records appropriate. Không suy violation of research basis chỉ từ việc hủy records, nhưng retention failure độc lập.","trap_vi":"Một duty được đáp ứng không miễn duty khác.","standard":"V(A), V(C)"},{"stem_en":"A supervisor knowingly assigns an untrained staff member sole responsibility for a complex valuation process, despite repeated errors and available training resources. Which rationale is best?","options":["The staff member's role-specific competence and the supervisor's reasonable preventive efforts are separate issues.","Only the staff member can ever violate a professional standard in this situation.","A supervisor satisfies IV(C) whenever assignments are documented in writing."],"correct":0,"why_vi":"I(E) xét năng lực người thực hiện; IV(C) xét reasonable prevention/detection, training/monitoring. Documentation alone không đủ.","trap_vi":"Không strict liability nhưng facts có red flags và lack of effort.","standard":"I(E), IV(C)"},{"stem_en":"A candidate accurately states that he passed Level I and then reveals specific confidential exam questions to advertise his tutoring service. Which conclusion is best?","options":["Passing Level I permits public discussion of actual exam questions.","The accurate status statement does not excuse a program-integrity violation.","Both statements necessarily violate VII(B) because candidates cannot mention passed levels."],"correct":1,"why_vi":"Fact passed level có thể nêu đúng; sharing confidential questions violates VII(A). Tách accurate reference và program integrity.","trap_vi":"Correct status không authorize exam disclosure.","standard":"VII(A), VII(B)"},{"stem_en":"A manager follows a documented allocation policy based on suitability and available capacity; personal orders are placed only after eligible client and employer orders have priority. A small client receives fewer shares than a larger client because of the policy. Which reasoning is best?","options":["Different share allocations do not by themselves establish unfair dealing when criteria are fair and priorities respected.","Fair dealing requires equal absolute share counts for every account.","Personal trading is always prohibited for investment professionals."],"correct":0,"why_vi":"Fair treatment có thể khác absolute allocations khi criteria hợp lý; client/employer priority preserved. Facts không cho thấy breach of loyalty.","trap_vi":"Fair không equal; personal trading không absolute ban.","standard":"III(A), III(B), VI(B)"},{"stem_en":"An adviser accurately discloses a volatile fund's complete history but recommends it to a client whose documented constraints prohibit its material leverage. Which conclusion follows?","options":["Accurate performance presentation does not cure the suitability breach.","Accurate performance presentation makes all recommendations suitable.","The leverage constraint is irrelevant if returns were positive."],"correct":0,"why_en":"III(D) may be satisfied while III(C) is violated; they test different obligations.","why_vi":"III(D) có thể được đáp ứng trong khi III(C) vi phạm; hai nghĩa vụ khác nhau.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (III(C), III(D)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"III(C), III(D)"},{"stem_en":"An adviser explains her advisory fee but omits a material payment received from another firm for referring this prospect. The most directly omitted disclosure is required by:","options":["V(C) Record Retention.","VI(C) Referral Fees.","VII(A) Program Conduct."],"correct":1,"why_en":"Referral compensation is a separate disclosure under VI(C); an advisory-fee statement does not communicate that payment.","why_vi":"Thù lao giới thiệu là công bố riêng theo VI(C); nêu phí tư vấn không truyền đạt khoản đó.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (V(B), VI(C)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"V(B), VI(C)"},{"stem_en":"An analyst has disclosed her ownership of a company to clients and employer. She then receives material confidential acquisition information and buys additional shares before public release. Which conclusion is most accurate?","options":["The purchase is permitted because the holding was disclosed.","The purchase is permitted if no client trades.","The purchase violates II(A) despite the conflict disclosure."],"correct":2,"why_en":"VI(A) disclosure does not override II(A), which prohibits acting on MNPI.","why_vi":"Công bố VI(A) không thay II(A) cấm giao dịch trên MNPI.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (II(A), VI(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"II(A), VI(A)"},{"stem_en":"A trader evades a reasonably designed and monitored control. The supervisor promptly discovers the breach, investigates and restricts trading. The most defensible conclusion is:","options":["the trader's violation does not alone establish a supervisor violation.","the supervisor automatically violates IV(C) whenever any employee violates a rule.","the trader is excused because controls were effective."],"correct":0,"why_en":"IV(C) is a reasonable-efforts obligation; the individual breach remains separate.","why_vi":"IV(C) là nghĩa vụ nỗ lực hợp lý; vi phạm cá nhân vẫn riêng biệt.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (IV(C), I(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"IV(C), I(A)"},{"stem_en":"A candidate truthfully states that she passed Level I and then publishes reconstructed confidential exam questions. Which assessment is most accurate?","options":["Both statements violate VII(B).","The achievement statement is permissible, but sharing the questions violates VII(A).","Neither statement violates because the exam is over."],"correct":1,"why_en":"Accurate factual achievement is allowed; confidentiality of exam content continues after the exam.","why_vi":"Thành tích factual đúng được phép; bảo mật nội dung thi vẫn tiếp tục sau kỳ thi.","trap_vi":"Tự biên soạn; chưa nghiệm thu độc lập.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (VII(A), VII(B)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final","archetype":"VII(A), VII(B)"}],"cards":[{"front_en":"I(A) Knowledge of the Law — justify","back_vi":"Đối chiếu duty với facts và exception: Khi local law cho phép nhưng Standards nghiêm hơn, áp dụng Standards; confidentiality vẫn có nghĩa vụ nếu không có exception. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 266–268; Kaplan R93 pp. 200; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Permitted by law khác required by law."},{"front_en":"A local rule permits an adviser to disclose a client's confidential investment information to a marketer, but no disclosure exception under III(E) applies. The adviser does so. Which conclusion is best?","back_vi":"The adviser violates the stricter applicable CFA requirements. — Khi local law cho phép nhưng Standards nghiêm hơn, áp dụng Standards; confidentiality vẫn có nghĩa vụ nếu không có exception. | Exam trap: Permitted by law khác required by law."},{"front_en":"I(B) Independence and Objectivity — justify","back_vi":"Đối chiếu duty với facts và exception: Gift từ client ghi nhận past service không mặc nhiên bị cấm; disclosure và firm policy được thực hiện, không có future contingent compensation. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 268–269; Kaplan R93 pp. 200; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Đừng nhầm unsolicited thank-you với additional compensation arrangement."},{"front_en":"A client unexpectedly sends an adviser a modest gift thanking her for last year's service. No future reward is promised and firm policy requires disclosure. She discloses it promptly and her judgment is unaffected. Which assessment is most appropriate?","back_vi":"The facts support compliance with I(B). — Gift từ client ghi nhận past service không mặc nhiên bị cấm; disclosure và firm policy được thực hiện, không có future contingent compensation. | Exam trap: Đừng nhầm unsolicited thank-you với additional compensation arrangement."},{"front_en":"I(C) Misrepresentation — justify","back_vi":"Đối chiếu duty với facts và exception: Misrepresentation ở guarantee không có cơ sở; đúng số lịch sử không làm prediction chắc chắn. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 269–272; Kaplan R93 pp. 200–201; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Historical performance không đảm bảo future return."},{"front_en":"An adviser advertises an unguaranteed equity fund as offering a certain 9% annual return. She includes the fund's actual past return of 9% in the same advertisement. Which statement is most accurate?","back_vi":"The unsupported guarantee violates I(C), notwithstanding the accurate historical figure. — Misrepresentation ở guarantee không có cơ sở; đúng số lịch sử không làm prediction chắc chắn. | Exam trap: Historical performance không đảm bảo future return."},{"front_en":"I(D) Misconduct — justify","back_vi":"Đối chiếu duty với facts và exception: Facts không cho thấy dishonesty hay adverse professional integrity; không tự suy misconduct từ citation. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 272–273; Kaplan R93 pp. 201; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không thêm facts tiêu cực ngoài đề."},{"front_en":"A portfolio manager receives a minor parking citation unrelated to work, with no dishonesty or other facts suggesting impaired professional integrity. Which conclusion is best supported?","back_vi":"The citation alone does not establish a violation of I(D). — Facts không cho thấy dishonesty hay adverse professional integrity; không tự suy misconduct từ citation. | Exam trap: Không thêm facts tiêu cực ngoài đề."},{"front_en":"I(E) Competence — justify","back_vi":"Đối chiếu duty với facts và exception: Competence xét knowledge, skill và thực hiện nhiệm vụ, không chỉ realized outcome. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 274–275; Kaplan R93 pp. 201–202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Outcome bias là bẫy."},{"front_en":"A properly trained bond manager uses an appropriate documented process, but unexpected rate changes lead to a loss. Which conclusion is best?","back_vi":"The loss alone does not establish a violation of I(E). — Competence xét knowledge, skill và thực hiện nhiệm vụ, không chỉ realized outcome. | Exam trap: Outcome bias là bẫy."},{"front_en":"II(A) Material Nonpublic Information — justify","back_vi":"Đối chiếu duty với facts và exception: Mosaic theory cho phép kết hợp public và nonmaterial nonpublic data thành conclusion material. Facts xác định không dùng MNPI. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 275–277; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Material conclusion khác material input."},{"front_en":"An analyst combines published shipping statistics with confidential but individually nonmaterial observations about product packaging and reaches a material investment conclusion. No material nonpublic input is used. Which assessment is best?","back_vi":"The analysis is consistent with mosaic theory. — Mosaic theory cho phép kết hợp public và nonmaterial nonpublic data thành conclusion material. Facts xác định không dùng MNPI. | Exam trap: Material conclusion khác material input."},{"front_en":"II(B) Market Manipulation — justify","back_vi":"Đối chiếu duty với facts và exception: Arbitrage có mục đích kinh tế thật; price/volume effect không đủ nếu không intent to mislead. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 277–278; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Phân biệt market impact với artificial signal."},{"front_en":"A manager buys an undervalued cash security and sells a related overpriced derivative to exploit a genuine pricing discrepancy. The trades increase volume, with no intent to mislead. Which assessment is best?","back_vi":"The facts are consistent with legitimate arbitrage rather than manipulation. — Arbitrage có mục đích kinh tế thật; price/volume effect không đủ nếu không intent to mislead. | Exam trap: Phân biệt market impact với artificial signal."},{"front_en":"III(A) Loyalty, Prudence, and Care — justify","back_vi":"Đối chiếu duty với facts và exception: Cần xem agreed obligations và prudence; liquidation đúng điều kiện không tự vi phạm chỉ vì loss. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 278–281; Kaplan R93 pp. 202; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không dùng realized loss làm test duy nhất."},{"front_en":"A futures broker liquidates a client's position after a valid margin shortfall in accordance with a clearly disclosed agreement and applicable requirements. No improper motive is present. Which assessment is best?","back_vi":"The resulting client loss alone does not demonstrate a breach of III(A). — Cần xem agreed obligations và prudence; liquidation đúng điều kiện không tự vi phạm chỉ vì loss. | Exam trap: Không dùng realized loss làm test duy nhất."},{"front_en":"III(B) Fair Dealing — justify","back_vi":"Đối chiếu duty với facts và exception: Fair khác equal; differentiated service có thể hợp lệ nếu disclosed và không unfairly disadvantage others. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 281–282; Kaplan R93 pp. 202–203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không đồng nhất mức dịch vụ với quyền ưu tiên giao dịch."},{"front_en":"A firm openly offers an optional premium analytics service to all eligible clients. All clients receive recommendation changes fairly, and the premium service does not disadvantage standard subscribers. Which statement is most accurate?","back_vi":"The disclosed service differentiation can comply with III(B). — Fair khác equal; differentiated service có thể hợp lệ nếu disclosed và không unfairly disadvantage others. | Exam trap: Không đồng nhất mức dịch vụ với quyền ưu tiên giao dịch."},{"front_en":"III(C) Suitability — justify","back_vi":"Đối chiếu duty với facts và exception: Mandate-based manager khác personal advisor; thực hiện stated strategy. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 282–284; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không áp nghĩa vụ advisory cá nhân cho mọi pooled fund manager."},{"front_en":"A manager operates a public small-cap equity fund strictly according to its disclosed mandate. She has no advisory relationship with individual unitholders. Which statement is best?","back_vi":"Her duty in this role is to manage the fund consistently with its stated mandate. — Mandate-based manager khác personal advisor; thực hiện stated strategy. | Exam trap: Không áp nghĩa vụ advisory cá nhân cho mọi pooled fund manager."},{"front_en":"III(D) Performance Presentation — justify","back_vi":"Đối chiếu duty với facts và exception: III(D) tập trung fair/accurate/complete; giả lập phải minh bạch, không giả làm actual. Facts không chứng minh violation khác. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 284–285; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Hypothetical không mặc nhiên cấm; đánh giá đầy đủ context."},{"front_en":"An adviser reports a simulated model's historical returns but clearly labels the results hypothetical, discloses relevant limitations, and does not present them as actual client returns. Which assessment is best on the stated facts?","back_vi":"The labeling addresses the distinction between hypothetical and actual returns. — III(D) tập trung fair/accurate/complete; giả lập phải minh bạch, không giả làm actual. Facts không chứng minh violation khác. | Exam trap: Hypothetical không mặc nhiên cấm; đánh giá đầy đủ context."},{"front_en":"III(E) Preservation of Confidentiality — justify","back_vi":"Đối chiếu duty với facts và exception: Disclosure required by law là exception; giới hạn scope và secure channel. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 285–286; Kaplan R93 pp. 203; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Legal permission khác legal requirement."},{"front_en":"A valid court order legally requires an adviser to produce specified confidential client documents. She provides only the required records through authorized channels. Which assessment is best?","back_vi":"The legally required disclosure falls within an exception to III(E). — Disclosure required by law là exception; giới hạn scope và secure channel. | Exam trap: Legal permission khác legal requirement."},{"front_en":"IV(A) Loyalty to Employers — justify","back_vi":"Đối chiếu duty với facts và exception: Knowledge và skill chung khác proprietary documents; facts nêu không breach agreement. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 286–289; Kaplan R93 pp. 203–204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không tự thêm noncompete hoặc trade-secret facts."},{"front_en":"After leaving a firm, a former employee reconstructs a general valuation technique from her own knowledge without taking proprietary records or breaching any applicable agreement. Which assessment is best?","back_vi":"Using general professional knowledge is not by itself a violation of IV(A). — Knowledge và skill chung khác proprietary documents; facts nêu không breach agreement. | Exam trap: Không tự thêm noncompete hoặc trade-secret facts."},{"front_en":"IV(B) Additional Compensation Arrangements — justify","back_vi":"Đối chiếu duty với facts và exception: Written disclosure không là approval; explicit refusal cho thấy consent chưa có. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 289–290; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không đánh đồng documented notification và permission."},{"front_en":"A manager discloses a conflicting outside compensation agreement to her employer by email, but the employer explicitly declines consent. She accepts the agreement anyway. Which assessment is best?","back_vi":"She violates IV(B) because disclosure is not consent. — Written disclosure không là approval; explicit refusal cho thấy consent chưa có. | Exam trap: Không đánh đồng documented notification và permission."},{"front_en":"IV(C) Responsibilities of Supervisors — justify","back_vi":"Đối chiếu duty với facts và exception: IV(C) xét reasonable efforts, không strict liability. Facts không chỉ ra supervisor thiếu efforts. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 290–292; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Kết quả xấu không tự chứng minh process failure."},{"front_en":"A supervisor had reasonable controls, training, monitoring and promptly investigated a concealed isolated violation. Which conclusion is best supported?","back_vi":"A subordinate's violation alone does not establish a violation by the supervisor. — IV(C) xét reasonable efforts, không strict liability. Facts không chỉ ra supervisor thiếu efforts. | Exam trap: Kết quả xấu không tự chứng minh process failure."},{"front_en":"V(A) Diligence and Reasonable Basis — justify","back_vi":"Đối chiếu duty với facts và exception: V(A) đòi reasonable diligence, không bắt tái tạo mọi dữ liệu; facts có đánh giá nguồn và basis. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 292–293; Kaplan R93 pp. 204; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Outsourcing không miễn review nhưng không bị cấm tuyệt đối."},{"front_en":"An analyst reviews a reputable external data provider's methodology, checks critical assumptions against independent information, documents limitations and uses the results in her own analysis. Which assessment is best?","back_vi":"Reliance on external research can be consistent with V(A) when appropriately evaluated. — V(A) đòi reasonable diligence, không bắt tái tạo mọi dữ liệu; facts có đánh giá nguồn và basis. | Exam trap: Outsourcing không miễn review nhưng không bị cấm tuyệt đối."},{"front_en":"V(B) Communication with Clients and Prospective Clients — justify","back_vi":"Đối chiếu duty với facts và exception: V(B) yêu cầu prompt communication of material changes và significant risks/limitations. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 293–294; Kaplan R93 pp. 204–205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không cần đợi loss mới disclose."},{"front_en":"A manager materially changes the portfolio selection model, adding leverage exposure and a new significant limitation. What is the best response?","back_vi":"Promptly communicate the material process change and significant risks to clients. — V(B) yêu cầu prompt communication of material changes và significant risks/limitations. | Exam trap: Không cần đợi loss mới disclose."},{"front_en":"V(C) Record Retention — justify","back_vi":"Đối chiếu duty với facts và exception: I(A) và V(C): luật 10 năm áp dụng; recommendation 7 năm khi không có rule khác không override luật. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 294–295; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Mandatory legal period khác recommended fallback."},{"front_en":"A jurisdiction requires investment research records to be retained for ten years. A firm proposes deleting them after seven years because of CFA guidance. What is most appropriate?","back_vi":"Retain records for the applicable ten-year requirement. — I(A) và V(C): luật 10 năm áp dụng; recommendation 7 năm khi không có rule khác không override luật. | Exam trap: Mandatory legal period khác recommended fallback."},{"front_en":"VI(A) Avoid or Disclose Conflicts — justify","back_vi":"Đối chiếu duty với facts và exception: VI(A) cho avoid or disclose; facts nêu safeguards và prominent disclosure. II(A), I(B) và other duties vẫn áp dụng. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 296; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Disclosure không universal cure."},{"front_en":"An analyst has a material ownership interest in a covered issuer. The firm determines the conflict cannot reasonably be avoided and permits coverage with safeguards. She discloses the interest prominently in plain language. Which assessment is best on these facts?","back_vi":"The disclosure addresses VI(A), subject to the other applicable duties. — VI(A) cho avoid or disclose; facts nêu safeguards và prominent disclosure. II(A), I(B) và other duties vẫn áp dụng. | Exam trap: Disclosure không universal cure."},{"front_en":"VI(B) Priority of Transactions — justify","back_vi":"Đối chiếu duty với facts và exception: Facts không beneficial ownership; account là client thực sự, fair dealing áp dụng. Disclose conflict nếu có theo VI(A). Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 296–298; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Family relationship không tự xác lập beneficial ownership."},{"front_en":"A manager's sibling is a fee-paying client with an independently owned account in which the manager has no beneficial interest. The account is eligible for an oversubscribed allocation. How should it be treated?","back_vi":"Under the same fair allocation criteria as other eligible client accounts. — Facts không beneficial ownership; account là client thực sự, fair dealing áp dụng. Disclose conflict nếu có theo VI(A). | Exam trap: Family relationship không tự xác lập beneficial ownership."},{"front_en":"VI(C) Referral Fees — justify","back_vi":"Đối chiếu duty với facts và exception: VI(C) yêu cầu transparency về paid/received referral benefit; không cấm mọi fee. Other duties remain. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 298–299; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Ai trả phí không xóa incentive."},{"front_en":"A firm pays a fixed referral fee to an accountant who introduces prospects. A prospect receives the arrangement's relevant disclosure before deciding whether to hire the firm. Which statement is best on these facts?","back_vi":"The disclosure helps the prospect evaluate the referral incentive and cost or conflict. — VI(C) yêu cầu transparency về paid/received referral benefit; không cấm mọi fee. Other duties remain. | Exam trap: Ai trả phí không xóa incentive."},{"front_en":"VII(A) Conduct as Participants in CFA Institute Programs — justify","back_vi":"Đối chiếu duty với facts và exception: General opinions được phép; không tiết lộ confidential exam specifics. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 300; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không nhầm opinion với confidential content."},{"front_en":"A candidate writes publicly that the exam felt difficult and that she prefers another preparation method, without revealing confidential content or tested topics. Which assessment is best?","back_vi":"Expressing that general opinion is not by itself a violation of VII(A). — General opinions được phép; không tiết lộ confidential exam specifics. | Exam trap: Không nhầm opinion với confidential content."},{"front_en":"VII(B) Reference to CFA Institute, Designation, and Program — justify","back_vi":"Đối chiếu duty với facts và exception: Factual accurate reference được phép, không guarantee superior returns. Khi giải thích, nêu rõ yếu tố nào đủ để kết luận và vì sao phương án còn lại không phù hợp. [CFAI LM5 PDF pp. 300–301; Kaplan R93 pp. 205; SAPP LM5 pp. 224–250; liên hệ guidance LM3.] | Exam trap: Không cấm mọi reference đến CFA designation."},{"front_en":"A charterholder in good standing tells a prospect that earning the CFA designation required meeting program requirements, and makes no promise of superior returns. Which assessment is best?","back_vi":"The factual description can comply with VII(B). — Factual accurate reference được phép, không guarantee superior returns. | Exam trap: Không cấm mọi reference đến CFA designation."},{"front_en":"Identify relevant facts — decision framework?","back_vi":"Actor/role → action → affected party → duty → timing · Tách client, employer, market và personal interests. · Không giả định facts không được nêu."},{"front_en":"Violation or compliant conduct — decision framework?","back_vi":"Applicable rule → elements → exception → conclusion · Phải giải thích logic, không chỉ nhớ standard label. · Một hành vi có thể liên quan nhiều standards."},{"front_en":"Best next action — decision framework?","back_vi":"Stop prohibited conduct → escalate/document → disclose or obtain consent as required · Biện pháp đúng phụ thuộc standard và facts. · Disclosure không thay consent, diligence, competence hoặc prohibitions."},{"front_en":"Law and professional duty — decision framework?","back_vi":"Applicable law → stricter requirement → avoid/stop violation · Đối chiếu I(A) và nghĩa vụ chuyên môn độc lập. · Không mặc định báo cáo ngoài luôn bắt buộc."},{"front_en":"Outcome versus process — decision framework?","back_vi":"Facts about process and intent → reasonableness → outcome · Phân biệt loss với lack of competence/diligence; phân biệt price impact và intent to mislead. · Không dùng hindsight như proof of violation."},{"front_en":"A sales brochure intentionally presents simulated returns as actual client returns. The calculations are mathematically accurate. Which explanation best supports a violation?","back_vi":"The false description misrepresents the source of performance and prevents a fair presentation. — Misrepresentation và performance presentation xét cách mô tả nguồn return; simulated không được giả làm actual. | Exam trap: Accurate arithmetic không chữa misleading label."},{"front_en":"A fund distributor offers an analyst a substantial future payment contingent on favorable coverage. The employer gives written consent, and the analyst publicly discloses the arrangement. What is the best explanation?","back_vi":"Consent and disclosure do not make a payment that compromises objectivity acceptable. — IV(B) và VI(A) không chữa I(B) inducement. Cần independently assess objectivity; substantial conditional payment không thể chấp nhận chỉ vì consent/disclosure. | Exam trap: Không dùng một standard để miễn nghĩa vụ standard khác."},{"front_en":"An analyst performs a documented, robust valuation but destroys supporting workpapers immediately after publication. Which explanation is best?","back_vi":"A reasonable research basis does not remove the duty to retain supporting records. — V(A) có thể được đáp ứng, V(C) vẫn đòi records appropriate. Không suy violation of research basis chỉ từ việc hủy records, nhưng retention failure độc lập. | Exam trap: Một duty được đáp ứng không miễn duty khác."},{"front_en":"A supervisor knowingly assigns an untrained staff member sole responsibility for a complex valuation process, despite repeated errors and available training resources. Which rationale is best?","back_vi":"The staff member's role-specific competence and the supervisor's reasonable preventive efforts are separate issues. — I(E) xét năng lực người thực hiện; IV(C) xét reasonable prevention/detection, training/monitoring. Documentation alone không đủ. | Exam trap: Không strict liability nhưng facts có red flags và lack of effort."},{"front_en":"A candidate accurately states that he passed Level I and then reveals specific confidential exam questions to advertise his tutoring service. Which conclusion is best?","back_vi":"The accurate status statement does not excuse a program-integrity violation. — Fact passed level có thể nêu đúng; sharing confidential questions violates VII(A). Tách accurate reference và program integrity. | Exam trap: Correct status không authorize exam disclosure."},{"front_en":"A manager follows a documented allocation policy based on suitability and available capacity; personal orders are placed only after eligible client and employer orders have priority. A small client receives fewer shares than a larger client because of the policy. Which reasoning is best?","back_vi":"Different share allocations do not by themselves establish unfair dealing when criteria are fair and priorities respected. — Fair treatment có thể khác absolute allocations khi criteria hợp lý; client/employer priority preserved. Facts không cho thấy breach of loyalty. | Exam trap: Fair không equal; personal trading không absolute ban."},{"front_en":"Suitability is not guaranteed by past returns","back_en":"A strong historical record does not prove a recommendation suitable for an individual. Match objectives, constraints and portfolio context; performance claims must separately be fair, accurate and complete.","back_vi":"Lịch sử tốt không chứng minh khuyến nghị phù hợp cá nhân. Phải khớp mục tiêu, hạn chế, toàn danh mục; tuyên bố hiệu suất riêng phải công bằng, chính xác, đầy đủ.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (III(C), III(D)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"Fee transparency and referral incentives","back_en":"Disclosure of management fees does not automatically disclose referral consideration. Clients need information about service costs and relevant referral incentives to assess the service and conflicts.","back_vi":"Công bố phí quản lý không tự công bố đối ứng giới thiệu. Khách cần biết chi phí dịch vụ và động cơ giới thiệu liên quan để đánh giá dịch vụ/xung đột.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (V(B), VI(C)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"Disclosure does not cleanse MNPI","back_en":"Even full disclosure of an ownership conflict does not permit acting on material nonpublic information. Analyze information status and trading prohibition before considering conflict disclosure.","back_vi":"Dù công bố đầy đủ xung đột sở hữu cũng không được giao dịch trên MNPI. Xét tình trạng thông tin và lệnh cấm trước khi xét công bố xung đột.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (II(A), VI(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"Individual and supervisory accountability","back_en":"A subordinate's violation does not automatically establish a supervisor's violation. Examine the supervisor's reasonable efforts to prevent, detect, investigate and address misconduct. The individual remains responsible for personal conduct.","back_vi":"Vi phạm cấp dưới không tự chứng minh supervisor vi phạm. Xét nỗ lực hợp lý ngăn ngừa, phát hiện, điều tra, xử lý. Cá nhân vẫn chịu trách nhiệm hành vi của mình.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (IV(C), I(A)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"},{"front_en":"Program status and confidential information","back_en":"A truthful account of exam achievement differs from a claim of partial designation or an improper disclosure of confidential tested material. One statement can be factual while another in the same communication violates a different obligation.","back_vi":"Nêu đúng thành tích kỳ thi khác tự nhận designation từng phần hoặc tiết lộ nội dung thi mật. Một câu có thể factual trong khi câu khác cùng thông tin vi phạm nghĩa vụ khác.","source_anchor":"CFAI Ethics 2026 physical PDF pp 265–301 (application), guidance pp 67–235 (VII(A), VII(B)); Kaplan R93 and SAPP LM5 targeted comparison","origin":"studyhub","review_status":"targeted_source_comparison_v74_pending_final"}]}],"version":"7.4","qa_status":"TARGETED_SOURCE_COMPARISON_PENDING_FINAL"}];
